-- Daily push notifications (pregnancy_day_notifications, mommy_day_notifications) translated into
-- es, fr, hi, id, ja, ko, nl, pl, pt, sv, vi, zh (owner request 2026-11-12; human-quality translation, not machine/Gemini). Batch 20261112210000_push_notifications_i18n_wave1.
-- Only empty cells are filled; existing text is never overwritten. Tables already CDC enrolled and writer guarded.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '300s';
DO $$ BEGIN
  IF (SELECT count(*) FROM _anacan_gcp_migration.guarded_relations WHERE schema_name = 'public'
      AND table_name IN ('pregnancy_day_notifications', 'mommy_day_notifications')) <> 2 THEN
    RAISE EXCEPTION 'PUSH_I18N_GUARD_MISSING'; END IF;
END $$;
UPDATE public.pregnancy_day_notifications SET title_es = '¡Del tamaño de una semilla de amapola! 🌱', body_es = 'Ya se llama oficialmente embrión. Crece muy rápido, y tú también estás cambiando.', title_fr = 'De la taille d''une graine de pavot ! 🌱', body_fr = 'On l''appelle désormais officiellement un embryon. Il grandit très vite, et vous aussi, vous changez.', title_hi = 'खसखस के दाने जितना! 🌱', body_hi = 'अब इसे आधिकारिक तौर पर भ्रूण कहा जाता है। यह तेज़ी से बढ़ रहा है, और आप भी बदल रही हैं।', title_id = 'Seukuran biji poppy! 🌱', body_id = 'Kini ia resmi disebut embrio. Ia tumbuh begitu cepat, dan Anda pun ikut berubah.', title_ja = 'ケシの実くらいの大きさ！🌱', body_ja = 'これからは正式に「胎芽」と呼ばれます。赤ちゃんはぐんぐん成長し、ママの体も変わっていきます。', title_ko = '양귀비 씨앗만 해요! 🌱', body_ko = '이제 공식적으로 배아라고 불려요. 아기는 빠르게 자라고, 엄마도 함께 변하고 있어요.', title_nl = 'Zo groot als een maanzaadje! 🌱', body_nl = 'Het heet nu officieel een embryo. Het groeit razendsnel, en jij verandert mee.', title_pl = 'Wielkości ziarenka maku! 🌱', body_pl = 'Teraz oficjalnie nazywa się zarodkiem. Rośnie bardzo szybko, a ty się zmieniasz.', title_pt = 'Do tamanho de uma semente de papoila! 🌱', body_pt = 'Agora chama-se oficialmente embrião. Cresce depressa, e a mãe também está a mudar.', title_sv = 'Stor som ett vallmofrö! 🌱', body_sv = 'Nu kallas den lilla officiellt för embryo. Den växer så snabbt, och du förändras också.', title_vi = 'To bằng hạt anh túc! 🌱', body_vi = 'Giờ đây con đã chính thức được gọi là phôi thai. Con lớn rất nhanh, và mẹ cũng đang thay đổi.', title_zh = '只有罂粟籽那么大！🌱', body_zh = '现在它正式被称为胚胎了。它在飞快成长，你也在悄悄改变。' WHERE id = 'df6c4f91-28b1-4f7a-8ab6-64fb294a5ab9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Del tamaño de un melocotón 🍑', body_es = 'Desabróchate el pantalón sin problema, ¡ponte cómoda! 😄', title_fr = 'De la taille d''une pêche 🍑', body_fr = 'Déboutonnez votre pantalon sans gêne, mettez-vous à l''aise ! 😄', title_hi = 'एक आड़ू जितना 🍑', body_hi = 'पैंट का बटन खोल दीजिए, आराम से रहिए! 😄', title_id = 'Seukuran buah persik 🍑', body_id = 'Silakan buka kancing celana Anda dan bersantailah! 😄', title_ja = '桃くらいの大きさ 🍑', body_ja = 'ズボンのボタンをはずしても大丈夫、楽にしてくださいね！😄', title_ko = '복숭아만 해요 🍑', body_ko = '바지 단추를 풀고 편하게 쉬어도 괜찮아요! 😄', title_nl = 'Zo groot als een perzik 🍑', body_nl = 'Maak gerust de knoop van je broek los en ontspan! 😄', title_pl = 'Wielkości brzoskwini 🍑', body_pl = 'Śmiało rozepnij guzik spodni i się odpręż! 😄', title_pt = 'Do tamanho de um pêssego 🍑', body_pt = 'Pode desapertar o botão das calças à vontade, relaxe! 😄', title_sv = 'Ungefär lika stor som en persika 🍑', body_sv = 'Knäpp gärna upp byxorna och gör det bekvämt för dig! 😄', title_vi = 'To bằng quả đào 🍑', body_vi = 'Cứ thoải mái cởi cúc quần ra, thư giãn đi mẹ! 😄', title_zh = '像一颗桃子那么大 🍑', body_zh = '裤子扣子想解就解开吧，舒服最重要！😄' WHERE id = 'e7c711cf-139e-409a-9191-4e2baba06f95' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Soy del tamaño de una berenjena! 🍆', body_es = 'Mido unos 38-39 cm. ¡Ya peso 1,35 kg! ¿Te peso mucho? Perdona, mamá, pero tengo que engordar.', title_fr = 'Je suis de la taille d''une aubergine ! 🍆', body_fr = 'Environ 38-39 cm. Je pèse déjà 1,35 kg ! Je deviens lourd pour vous ? Pardon, Maman, mais je dois encore prendre du poids.', title_hi = 'मैं बैंगन जितना हो गया हूँ! 🍆', body_hi = 'लगभग 38-39 cm। मेरा वज़न 1.35 kg हो गया! क्या मैं आपको भारी लग रहा हूँ? माफ़ करना माँ, पर मुझे वज़न बढ़ाना है।', title_id = 'Aku sudah seukuran terong! 🍆', body_id = 'Panjangku sekitar 38-39 cm. Beratku sudah 1,35 kg! Apakah aku mulai terasa berat? Maaf ya, Bunda, tapi aku memang harus menambah berat badan.', title_ja = 'ナスくらいの大きさになったよ！🍆', body_ja = '身長は約38-39 cm。体重は1.35 kgになったよ！重くなってきた？ごめんね、ママ、でももっと太らなきゃいけないの。', title_ko = '저는 가지만 해요! 🍆', body_ko = '키는 약 38-39cm, 몸무게는 1.35kg이 됐어요! 무겁게 느껴지세요? 미안해요, 엄마. 그래도 저는 살을 더 찌워야 해요.', title_nl = 'Ik ben zo groot als een aubergine! 🍆', body_nl = 'Ongeveer 38-39 cm. Ik weeg nu 1,35 kg! Word ik zwaar voor je? Sorry, mama, maar ik moet nog aankomen.', title_pl = 'Jestem wielkości bakłażana! 🍆', body_pl = 'Mam około 38-39 cm. Ważę już 1,35 kg! Czy już ci ciężko? Przepraszam, Mamo, ale muszę przybrać na wadze.', title_pt = 'Já tenho o tamanho de uma beringela! 🍆', body_pt = 'Tenho cerca de 38-39 cm. Já peso 1,35 kg! Estou a ficar pesado para si? Desculpe, Mamã, mas tenho de engordar.', title_sv = 'Jag är lika stor som en aubergine! 🍆', body_sv = 'Ungefär 38-39 cm. Jag väger 1,35 kg! Börjar jag bli tung för dig? Förlåt, mamma, men jag måste gå upp i vikt.', title_vi = 'Con to bằng quả cà tím rồi! 🍆', body_vi = 'Con dài khoảng 38-39 cm. Con nặng 1.35 kg rồi! Mẹ thấy con nặng không? Xin lỗi mẹ nhé, nhưng con phải tăng cân thêm.', title_zh = '我有一个茄子那么大啦！🍆', body_zh = '我大约38-39 cm长，体重已经1.35 kg啦！是不是觉得我变重了？对不起，妈妈，我还得再长胖一点。' WHERE id = '88619dd2-a8e1-47a0-8257-5ec0eff6998d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Ya soy como un mango! 🥭', body_es = 'Mido unos 15 cm. Mi piel aún es fina, pero se está formando mi capa de grasa. ¡Ahora me veo más rellenito, mamá!', title_fr = 'Je suis de la taille d''une mangue ! 🥭', body_fr = 'Environ 15 cm. Ma peau est encore fine, mais ma couche de graisse se forme. Je suis un peu plus potelé maintenant, Maman !', title_hi = 'मैं आम जितना हो गया! 🥭', body_hi = 'लगभग 15 cm। मेरी त्वचा अभी पतली है, पर चर्बी की परत बनने लगी है। अब मैं थोड़ा गोल-मटोल दिखता हूँ, माँ!', title_id = 'Aku sudah seukuran mangga! 🥭', body_id = 'Sekitar 15 cm. Kulitku masih tipis, tapi lapisan lemakku mulai terbentuk. Sekarang aku tampak lebih montok, Bunda!', title_ja = 'マンゴーくらいになったよ！🥭', body_ja = '身長は約15 cm。皮膚はまだ薄いけど、脂肪の層ができはじめているよ。ちょっとふっくらしてきたでしょ、ママ！', title_ko = '망고만큼 컸어요! 🥭', body_ko = '키는 약 15cm예요. 피부는 아직 얇지만 지방층이 생기고 있어요. 이제 조금 더 통통해 보여요, 엄마!', title_nl = 'Ik ben zo groot als een mango! 🥭', body_nl = 'Ongeveer 15 cm. Mijn huid is nog dun, maar er vormt zich een vetlaagje. Ik zie er nu wat molliger uit, mama!', title_pl = 'Jestem wielkości mango! 🥭', body_pl = 'Około 15 cm. Moja skóra jest jeszcze cienka, ale tworzy się warstwa tłuszczu. Wyglądam teraz pulchniej, Mamo!', title_pt = 'Já sou do tamanho de uma manga! 🥭', body_pt = 'Cerca de 15 cm. A minha pele ainda é fina, mas a camada de gordura está a formar-se. Agora estou mais rechonchudo, Mamã!', title_sv = 'Nu är jag lika stor som en mango! 🥭', body_sv = 'Ungefär 15 cm. Min hud är fortfarande tunn, men ett fettlager börjar bildas. Nu ser jag lite rundare ut, mamma!', title_vi = 'Con to bằng quả xoài rồi! 🥭', body_vi = 'Con dài khoảng 15 cm. Da con vẫn còn mỏng, nhưng lớp mỡ đang hình thành. Giờ con trông bụ bẫm hơn rồi, mẹ ơi!', title_zh = '我有一个芒果那么大啦！🥭', body_zh = '大约15 cm。我的皮肤还很薄，但脂肪层开始形成了。妈妈，我现在看起来更圆润啦！' WHERE id = '08979df0-c3a9-4a97-8501-c4fbc032480c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Del tamaño de un tomate! 🍅', body_es = 'Mido unos 18-20 cm. Ya me miden de la cabeza a los pies. Estoy creciendo y mi cuerpo se estira.', title_fr = 'De la taille d''une tomate ! 🍅', body_fr = 'Environ 18-20 cm. On me mesure maintenant de la tête aux pieds. Je grandis et mon corps s''affine.', title_hi = 'एक टमाटर जितना! 🍅', body_hi = 'लगभग 18-20 cm। अब मुझे सिर से पैर तक नापा जाता है। मेरी लंबाई बढ़ रही है, शरीर सुडौल हो रहा है।', title_id = 'Seukuran tomat! 🍅', body_id = 'Sekitar 18-20 cm. Kini aku diukur dari kepala sampai kaki. Tubuhku memanjang dan bentuknya makin jelas.', title_ja = 'トマトくらいの大きさ！🍅', body_ja = '身長は約18-20 cm。今は頭からかかとまで測れるようになったよ。背が伸びて、体つきもしっかりしてきたよ。', title_ko = '토마토만 해요! 🍅', body_ko = '키는 약 18-20cm예요. 이제 머리부터 발끝까지 재요. 키가 자라고 몸이 곧게 펴지고 있어요.', title_nl = 'Zo groot als een tomaat! 🍅', body_nl = 'Ongeveer 18-20 cm. Ik word nu van kop tot hiel gemeten. Ik word langer en mijn lichaam strekt zich.', title_pl = 'Wielkości pomidora! 🍅', body_pl = 'Około 18-20 cm. Teraz mierzy się mnie od głowy do stóp. Rosnę, a moje ciało się prostuje.', title_pt = 'Do tamanho de um tomate! 🍅', body_pt = 'Cerca de 18-20 cm. Agora já sou medido da cabeça aos pés. Estou a crescer e o meu corpo está a ganhar forma.', title_sv = 'Lika stor som en tomat! 🍅', body_sv = 'Ungefär 18-20 cm. Nu mäts jag från huvud till häl. Jag blir längre och kroppen tar form.', title_vi = 'To bằng quả cà chua! 🍅', body_vi = 'Con dài khoảng 18-20 cm. Giờ con được đo từ đầu đến chân rồi. Con đang dài ra, cơ thể ngày càng cân đối.', title_zh = '像一个番茄那么大！🍅', body_zh = '大约18-20 cm。现在开始从头量到脚啦。我在长高，身体也越来越舒展。' WHERE id = '6fb4f290-31ce-473d-a17d-ea607c5d055d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Ya soy como una mazorca de maíz! 🌽', body_es = 'Peso unos 600 gramos. Ahora tengo menos espacio. Mis pataditas pueden ser más fuertes, ¡perdona! 🦶', title_fr = 'Je suis de la taille d''un épi de maïs ! 🌽', body_fr = 'Environ 600 grammes. Je commence à manquer un peu de place. Mes coups de pied peuvent être plus forts, pardon ! 🦶', title_hi = 'मैं भुट्टे जितना हो गया! 🌽', body_hi = 'लगभग 600 g। अब मेरी जगह थोड़ी तंग हो रही है। मेरी किक और ज़ोरदार हो सकती हैं, माफ़ करना! 🦶', title_id = 'Aku sudah seukuran jagung! 🌽', body_id = 'Sekitar 600 gram. Ruanganku mulai terasa sempit. Tendanganku mungkin makin kuat, maaf ya! 🦶', title_ja = 'トウモロコシくらいになったよ！🌽', body_ja = '体重は約600グラム。だんだんお部屋が狭くなってきたよ。キックが強くなるかも、ごめんね！🦶', title_ko = '옥수수만큼 컸어요! 🌽', body_ko = '몸무게는 약 600g이에요. 이제 공간이 조금 좁아지고 있어요. 발차기가 더 세질 수 있어요, 미안해요! 🦶', title_nl = 'Ik ben zo groot als een maiskolf! 🌽', body_nl = 'Ongeveer 600 gram. Mijn plekje wordt wat krapper. Mijn trapjes kunnen harder worden, sorry! 🦶', title_pl = 'Jestem wielkości kolby kukurydzy! 🌽', body_pl = 'Około 600 gramów. Robi mi się trochę ciasno. Moje kopnięcia mogą być mocniejsze, przepraszam! 🦶', title_pt = 'Já sou do tamanho de uma maçaroca de milho! 🌽', body_pt = 'Cerca de 600 gramas. O meu espaço está a ficar apertado. Os meus pontapés podem ser mais fortes, desculpe! 🦶', title_sv = 'Nu är jag lika stor som en majskolv! 🌽', body_sv = 'Ungefär 600 gram. Nu börjar det bli lite trångt här. Mina sparkar kan bli starkare, förlåt! 🦶', title_vi = 'Con to bằng bắp ngô rồi! 🌽', body_vi = 'Con nặng khoảng 600 gram. Chỗ của con hơi chật rồi. Những cú đạp có thể mạnh hơn, mẹ thông cảm nhé! 🦶', title_zh = '我有一根玉米那么大啦！🌽', body_zh = '我大约600克了。现在空间有点挤，踢你可能会更有力，对不起啦！🦶' WHERE id = 'db0c5fae-71f1-477b-b321-634c423e0906' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Ya hiciste nuestra primera foto? 🤰', body_es = '¡Sube tu primera foto de Baby Bump a la galería! ✨', title_fr = 'Vous avez pris notre première photo ? 🤰', body_fr = 'Ajoutez votre première photo Baby Bump à la galerie ! ✨', title_hi = 'हमारी पहली फ़ोटो ली? 🤰', body_hi = 'गैलरी में अपनी पहली Baby Bump फ़ोटो अपलोड कीजिए! ✨', title_id = 'Sudah ambil foto pertama kita? 🤰', body_id = 'Unggah foto Baby Bump pertama Anda ke galeri! ✨', title_ja = '初めての写真、撮りましたか？🤰', body_ja = 'ギャラリーに初めてのマタニティフォトをアップしましょう！✨', title_ko = '우리 첫 사진 찍었어요? 🤰', body_ko = '갤러리에 첫 Baby Bump 사진을 올려 보세요! ✨', title_nl = 'Al onze eerste foto gemaakt? 🤰', body_nl = 'Upload je eerste Baby Bump-foto naar de galerij! ✨', title_pl = 'Zrobiłaś nasze pierwsze zdjęcie? 🤰', body_pl = 'Dodaj pierwsze zdjęcie brzuszka do galerii! ✨', title_pt = 'Já tirou a nossa primeira foto? 🤰', body_pt = 'Carregue a primeira foto da Baby Bump na galeria! ✨', title_sv = 'Har du tagit vårt första foto? 🤰', body_sv = 'Ladda upp ditt första Baby Bump-foto i galleriet! ✨', title_vi = 'Mẹ đã chụp tấm ảnh đầu tiên của chúng mình chưa? 🤰', body_vi = 'Tải ảnh Baby Bump đầu tiên lên thư viện nhé! ✨', title_zh = '拍好我们的第一张照片了吗？🤰', body_zh = '把第一张孕肚照上传到相册吧！✨' WHERE id = 'bb01f67b-68b6-46f0-9ecd-af5b6f80b28b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Cómo late mi corazón? 💓', body_es = '¿Estamos en el médico haciendo el NST? Qué alivio sientes al oír ese bum-bum...', title_fr = 'Comment bat mon cœur ? 💓', body_fr = 'On est chez le médecin pour le monitoring ? Quel soulagement quand vous entendez ce petit boum-boum...', title_hi = 'मेरा दिल कैसे धड़क रहा है? 💓', body_hi = 'क्या हम डॉक्टर के पास NST जाँच के लिए हैं? वह धक-धक की आवाज़ सुनकर आपको कितना सुकून मिलता है...', title_id = 'Bagaimana detak jantungku? 💓', body_id = 'Sedang tes NST di dokter? Betapa leganya Anda saat mendengar suara dug-dug itu...', title_ja = 'わたしの心臓、どんなふうに動いてる？💓', body_ja = '病院でNST検査中かな？あのドクドクという音を聞くと、ほっとしますよね...', title_ko = '제 심장은 어떻게 뛰고 있을까요? 💓', body_ko = '병원에서 NST 검사 중인가요? 그 콩닥콩닥 소리를 들으면 엄마 마음이 얼마나 편안해지는지...', title_nl = 'Hoe klopt mijn hartje? 💓', body_nl = 'Zijn we bij de dokter voor een CTG? Wat een opluchting als je dat boem-boem hoort...', title_pl = 'Jak bije moje serduszko? 💓', body_pl = 'Jesteśmy u lekarza na KTG? Jak bardzo się uspokajasz, gdy słyszysz to bum-bum...', title_pt = 'Como bate o meu coração? 💓', body_pt = 'Estamos no médico para o CTG? Que alívio sente quando ouve aquele tum-tum...', title_sv = 'Hur slår mitt hjärta? 💓', body_sv = 'Är vi hos läkaren för en CTG-undersökning? Så lättad du blir när du hör det där dunk-dunk-ljudet...', title_vi = 'Tim con đập thế nào nhỉ? 💓', body_vi = 'Mình đang đi đo NST ở chỗ bác sĩ à? Nghe tiếng thình thịch ấy, mẹ thấy yên lòng biết bao...', title_zh = '我的心跳怎么样？💓', body_zh = '我们在医院做胎心监护（NST）吗？听到那“咚咚”声时，你一定松了一口气吧……' WHERE id = 'e0f642a2-57ae-48a0-88a3-c592939d5139' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Estás comiendo dátiles? 🌴', body_es = '¡Vale la pena un intento delicioso para un parto natural!', title_fr = 'Vous mangez des dattes ? 🌴', body_fr = 'Un essai délicieux qui vaut la peine pour un accouchement naturel !', title_hi = 'खजूर खा रही हैं? 🌴', body_hi = 'नॉर्मल डिलीवरी के लिए यह स्वादिष्ट कोशिश करने लायक है!', title_id = 'Sudah makan kurma? 🌴', body_id = 'Layak dicoba dengan cara yang lezat untuk persalinan normal!', title_ja = 'デーツを食べていますか？🌴', body_ja = '自然分娩に向けて、おいしく試してみる価値ありです！', title_ko = '대추야자 드시고 있어요? 🌴', body_ko = '자연분만을 위해 맛있게 한번 시도해 볼 만해요!', title_nl = 'Eet je dadels? 🌴', body_nl = 'Een lekkere poging waard voor een natuurlijke bevalling!', title_pl = 'Jesz daktyle? 🌴', body_pl = 'Warto spróbować tego smacznego sposobu na poród naturalny!', title_pt = 'Está a comer tâmaras? 🌴', body_pt = 'Vale a pena uma tentativa deliciosa para um parto natural!', title_sv = 'Äter du dadlar? 🌴', body_sv = 'Ett gott försök som är värt det inför en naturlig förlossning!', title_vi = 'Mẹ có ăn chà là không? 🌴', body_vi = 'Một cách thử ngon miệng, đáng làm cho ca sinh thường!', title_zh = '今天吃椰枣了吗？🌴', body_zh = '为了自然分娩，这个美味的尝试值得一试！' WHERE id = 'a43fd2c0-9279-47da-b7ee-4898765553ab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Empieza un nuevo viaje! 🚀', body_es = 'Tu cuerpo se prepara para acoger un gran milagro. ¿Estás lista?', title_fr = 'Un nouveau voyage commence ! 🚀', body_fr = 'Votre corps se prépare à accueillir un grand miracle. Êtes-vous prête ?', title_hi = 'एक नया सफ़र शुरू होता है! 🚀', body_hi = 'आपका शरीर एक बड़े चमत्कार का घर बनने की तैयारी कर रहा है। क्या आप इसके लिए तैयार हैं?', title_id = 'Perjalanan baru dimulai! 🚀', body_id = 'Tubuh Anda bersiap menjadi rumah bagi keajaiban besar. Apakah Anda siap?', title_ja = '新しい旅のはじまり！🚀', body_ja = '体が大きな奇跡を迎える準備を始めています。心の準備はできていますか？', title_ko = '새로운 여정이 시작돼요! 🚀', body_ko = '몸이 커다란 기적을 맞이할 준비를 하고 있어요. 마음의 준비는 되셨나요?', title_nl = 'Een nieuwe reis begint! 🚀', body_nl = 'Je lichaam maakt zich klaar om een groot wonder te dragen. Ben jij er klaar voor?', title_pl = 'Zaczyna się nowa podróż! 🚀', body_pl = 'Twoje ciało przygotowuje się, by przyjąć wielki cud. Jesteś gotowa?', title_pt = 'Uma nova viagem começa! 🚀', body_pt = 'O seu corpo prepara-se para acolher um grande milagre. Está preparada?', title_sv = 'En ny resa börjar! 🚀', body_sv = 'Din kropp förbereder sig för att ta emot ett stort mirakel. Är du redo?', title_vi = 'Một hành trình mới bắt đầu! 🚀', body_vi = 'Cơ thể bạn đang chuẩn bị đón một phép màu lớn. Bạn đã sẵn sàng chưa?', title_zh = '新的旅程开始啦！🚀', body_zh = '你的身体正准备迎接一个伟大的奇迹。你准备好了吗？' WHERE id = 'e07ed45f-67ec-4ce6-a8d6-4499daea0b9d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Se te olvidaron las vitaminas? 💊', body_es = 'El ácido fólico es ahora tu mejor amigo. ¡Echa un vistazo a la sección Nutrición para una base sana de tu futuro bebé!', title_fr = 'Vous avez pensé à vos vitamines ? 💊', body_fr = 'L''acide folique est maintenant votre meilleur ami. Pour une base solide pour votre futur bébé, jetez un œil à la rubrique Nutrition !', title_hi = 'विटामिन भूल गईं? 💊', body_hi = 'फ़ोलिक एसिड अब आपका सबसे करीबी दोस्त है। होने वाले बच्चे की सेहतमंद नींव के लिए पोषण सेक्शन देखिए!', title_id = 'Lupa minum vitamin? 💊', body_id = 'Asam folat adalah sahabat terbaik Anda saat ini. Untuk fondasi yang sehat bagi calon bayi, lihat bagian Nutrisi!', title_ja = 'ビタミン、忘れていませんか？💊', body_ja = '今、葉酸はいちばんの味方です。未来の赤ちゃんの健やかな土台のために、「栄養」セクションをチェックしてみてください！', title_ko = '비타민 잊지 않으셨죠? 💊', body_ko = '지금 엽산은 가장 친한 친구예요. 미래의 아기를 위한 건강한 기초, 영양 섹션에서 확인해 보세요!', title_nl = 'Je vitamines vergeten? 💊', body_nl = 'Foliumzuur is nu je beste vriend. Kijk in het onderdeel Voeding voor een gezonde basis voor je toekomstige baby!', title_pl = 'Nie zapomniałaś o witaminach? 💊', body_pl = 'Kwas foliowy to teraz twój najlepszy przyjaciel. Zajrzyj do sekcji Odżywianie, by zadbać o zdrowe podstawy dla przyszłego dziecka!', title_pt = 'Esqueceu-se das vitaminas? 💊', body_pt = 'O ácido fólico é agora o seu melhor amigo. Para uma base saudável do seu futuro bebé, espreite a secção Nutrição!', title_sv = 'Har du glömt vitaminerna? 💊', body_sv = 'Folsyra är din bästa vän just nu. Kika in i Kost-avsnittet för en sund grund för ditt framtida barn!', title_vi = 'Bạn quên uống vitamin à? 💊', body_vi = 'Axit folic giờ là người bạn thân nhất của bạn. Hãy xem mục Dinh dưỡng để tạo nền tảng khỏe mạnh cho em bé tương lai!', title_zh = '忘记吃维生素了吗？💊', body_zh = '叶酸现在是你最好的朋友。为了未来宝宝健康的基础，去看看营养板块吧！' WHERE id = '3ff0a063-2126-4cd6-a3ce-f5e944bb5487' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Cómo te sientes hoy? 🌈', body_es = 'Al comienzo de esta nueva etapa tus emociones pueden cambiar. Anota cómo te sientes hoy en el Diario de ánimo y obsérvate.', title_fr = 'Comment vous sentez-vous aujourd''hui ? 🌈', body_fr = 'Au début de cette nouvelle étape, vos émotions peuvent changer. Notez vos ressentis du jour dans le Journal d''humeur et suivez-vous.', title_hi = 'आज आप कैसा महसूस कर रही हैं? 🌈', body_hi = 'नए दौर की शुरुआत में भावनाएँ बदल सकती हैं। आज की भावनाएँ मूड डायरी में लिखिए और खुद पर नज़र रखिए।', title_id = 'Bagaimana perasaan Anda hari ini? 🌈', body_id = 'Di awal babak baru ini, emosi Anda bisa naik turun. Catat perasaan Anda hari ini di Buku Harian Suasana Hati dan pantau diri Anda.', title_ja = '今日の気分はいかがですか？🌈', body_ja = '新しい時期の始まりには、気持ちが揺れ動くこともあります。「気分日記」に今日の気持ちを記録して、自分を見つめてみましょう。', title_ko = '오늘 기분은 어떠세요? 🌈', body_ko = '새로운 시기가 시작되면 감정이 오르내릴 수 있어요. 기분 일기에 오늘의 감정을 기록하고 스스로를 살펴보세요.', title_nl = 'Hoe voel je je vandaag? 🌈', body_nl = 'Aan het begin van deze nieuwe fase kunnen je emoties schommelen. Noteer je gevoelens van vandaag in het Stemmingsdagboek en volg hoe het met je gaat.', title_pl = 'Jak się dziś czujesz? 🌈', body_pl = 'Na początku nowego etapu emocje mogą się zmieniać. Zapisz dzisiejsze uczucia w Dzienniku nastroju i obserwuj siebie.', title_pt = 'Como se sente hoje? 🌈', body_pt = 'No início desta nova fase, as emoções podem oscilar. Registe hoje o que sente no Diário de Humor e acompanhe-se.', title_sv = 'Hur mår du i dag? 🌈', body_sv = 'I början av en ny period kan känslorna svänga. Skriv ner dagens känslor i Humördagboken och följ hur du mår.', title_vi = 'Hôm nay bạn thấy thế nào? 🌈', body_vi = 'Khi giai đoạn mới bắt đầu, cảm xúc của bạn có thể thay đổi. Hãy ghi lại cảm xúc hôm nay vào Nhật ký tâm trạng và theo dõi bản thân.', title_zh = '今天感觉怎么样？🌈', body_zh = '新阶段开始时，情绪可能会起伏不定。在心情日记里记下今天的感受，关注自己的状态。' WHERE id = 'a2855683-73b8-4bf4-af85-cc599724b360' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Por ahora es microscópico 🔬', body_es = 'Las grandes historias empiezan con partículas diminutas. Ahora tu futuro bebé es solo una idea, ¡pero su potencial es infinito!', title_fr = 'Encore microscopique pour l''instant 🔬', body_fr = 'Les grandes histoires commencent par de toutes petites choses. Pour l''instant, votre futur bébé n''est qu''une idée, mais son potentiel est infini !', title_hi = 'अभी तो सूक्ष्म है 🔬', body_hi = 'बड़ी कहानियाँ छोटे-छोटे कणों से शुरू होती हैं। अभी होने वाला बच्चा बस एक विचार जैसा है, पर उसकी संभावनाएँ अनंत हैं!', title_id = 'Untuk sekarang masih mikroskopis 🔬', body_id = 'Kisah besar dimulai dari partikel kecil. Saat ini calon bayi baru sebatas gagasan, tapi potensinya tak terbatas!', title_ja = '今はまだ顕微鏡サイズ 🔬', body_ja = '大きな物語は小さな粒から始まります。今の未来の赤ちゃんはまだアイデアのような存在ですが、可能性は無限大です！', title_ko = '아직은 현미경으로만 보여요 🔬', body_ko = '위대한 이야기는 아주 작은 것에서 시작돼요. 지금 미래의 아기는 하나의 생각일 뿐이지만, 가능성은 무한해요!', title_nl = 'Voorlopig nog microscopisch klein 🔬', body_nl = 'Grote verhalen beginnen met kleine deeltjes. Je toekomstige baby is nu nog maar een idee, maar het potentieel is eindeloos!', title_pl = 'Na razie jest mikroskopijne 🔬', body_pl = 'Wielkie historie zaczynają się od maleńkich drobinek. Teraz przyszłe dziecko jest tylko jak pomysł, ale jego potencjał jest nieskończony!', title_pt = 'Por enquanto, sou microscópico 🔬', body_pt = 'As grandes histórias começam com pequenas partículas. Neste momento, o futuro bebé é apenas uma ideia, mas o potencial é infinito!', title_sv = 'Än så länge mikroskopisk 🔬', body_sv = 'Stora berättelser börjar med små korn. Just nu är ditt framtida barn bara en idé, men möjligheterna är oändliga!', title_vi = 'Hiện tại vẫn còn siêu nhỏ 🔬', body_vi = 'Những câu chuyện lớn bắt đầu từ những hạt nhỏ bé. Giờ em bé tương lai mới chỉ như một ý tưởng, nhưng tiềm năng là vô hạn!', title_zh = '现在还只是微观大小 🔬', body_zh = '伟大的故事都从微小开始。此刻，未来的宝宝还只是一个念想，但潜力无限！' WHERE id = 'f1a0230f-d87a-49ad-b1c8-d849ef306a7f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Hora de desintoxicarse! 🚫', body_es = '¿Tabaco, alcohol o demasiada cafeína? Es el momento perfecto para despedirte de ellos. Mamá sana = comienzo sano.', title_fr = 'C''est l''heure de la détox ! 🚫', body_fr = 'Cigarettes, alcool ou trop de caféine ? C''est le moment idéal pour leur dire au revoir. Maman en bonne santé = bon départ.', title_hi = 'डिटॉक्स का समय! 🚫', body_hi = 'सिगरेट, शराब या ज़्यादा कैफ़ीन? इन्हें अलविदा कहने का यही सही समय है। स्वस्थ माँ = स्वस्थ शुरुआत।', title_id = 'Saatnya detoks! 🚫', body_id = 'Rokok, alkohol, atau kafein berlebih? Inilah saat yang tepat untuk berpisah dengan semuanya. Ibu sehat = awal yang sehat.', title_ja = 'デトックスのとき！🚫', body_ja = 'たばこ、お酒、カフェインのとりすぎ？今こそさよならするときです。健康なママ＝健やかなスタート。', title_ko = '디톡스할 시간이에요! 🚫', body_ko = '담배, 술, 과한 카페인? 이제 작별할 때예요. 건강한 엄마 = 건강한 시작.', title_nl = 'Tijd voor een detox! 🚫', body_nl = 'Sigaretten, alcohol of te veel cafeïne? Dit is hét moment om er afscheid van te nemen. Gezonde mama = gezonde start.', title_pl = 'Czas na detoks! 🚫', body_pl = 'Papierosy, alkohol czy za dużo kofeiny? To idealny moment, by się z nimi pożegnać. Zdrowa mama = zdrowy start.', title_pt = 'Hora da desintoxicação! 🚫', body_pt = 'Tabaco, álcool ou cafeína a mais? É o momento ideal para lhes dizer adeus. Mãe saudável = começo saudável.', title_sv = 'Dags för detox! 🚫', body_sv = 'Cigaretter, alkohol eller för mycket koffein? Nu är det perfekta tillfället att ta farväl av dem. Frisk mamma = frisk start.', title_vi = 'Đến lúc thải độc rồi! 🚫', body_vi = 'Thuốc lá, rượu bia hay quá nhiều caffeine? Đây là lúc thích hợp để nói lời tạm biệt. Mẹ khỏe = Khởi đầu khỏe.', title_zh = '该排毒啦！🚫', body_zh = '香烟、酒精或过量咖啡因？现在正是和它们告别的时候。健康的妈妈 = 健康的开始。' WHERE id = '137ef65d-9ea9-410c-9d5d-bbb4811b21f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Tienes tu botella de agua cerca? 💧', body_es = 'Ahora mantenerte hidratada es el doble de importante. No olvides completar tu cantidad diaria de agua.', title_fr = 'Votre bouteille d''eau est à portée de main ? 💧', body_fr = 'Bien s''hydrater est maintenant deux fois plus important. N''oubliez pas d''atteindre votre quantité d''eau quotidienne.', title_hi = 'पानी की बोतल पास है? 💧', body_hi = 'शरीर में पानी की कमी न होने देना अब दोगुना ज़रूरी है। रोज़ का पानी का लक्ष्य पूरा करना न भूलें।', title_id = 'Botol minum Anda ada di dekat Anda? 💧', body_id = 'Menjaga tubuh tetap terhidrasi kini dua kali lebih penting. Jangan lupa memenuhi kebutuhan air harian Anda.', title_ja = 'お水のボトル、そばにありますか？💧', body_ja = '今は水分補給が2倍大切です。1日に必要なお水の量をしっかりとりましょう。', title_ko = '물병은 가까이에 있나요? 💧', body_ko = '지금은 수분 섭취가 두 배로 중요해요. 하루 물 섭취량을 꼭 채워 주세요.', title_nl = 'Heb je je waterfles bij de hand? 💧', body_nl = 'Goed drinken is nu dubbel zo belangrijk. Vergeet niet je dagelijkse hoeveelheid water te halen.', title_pl = 'Masz pod ręką butelkę wody? 💧', body_pl = 'Nawodnienie organizmu jest teraz podwójnie ważne. Nie zapomnij wypić dziennej porcji wody.', title_pt = 'Tem a garrafa de água por perto? 💧', body_pt = 'Manter o corpo hidratado é agora duplamente importante. Não se esqueça de cumprir a sua meta diária de água.', title_sv = 'Har du vattenflaskan nära? 💧', body_sv = 'Att hålla kroppen återfuktad är dubbelt så viktigt nu. Glöm inte att dricka ditt dagliga vattenintag.', title_vi = 'Bình nước có bên cạnh bạn chưa? 💧', body_vi = 'Giữ cơ thể đủ nước giờ quan trọng gấp đôi. Đừng quên uống đủ lượng nước mỗi ngày nhé.', title_zh = '水杯在身边吗？💧', body_zh = '现在补水加倍重要。别忘了喝够每天的饮水量。' WHERE id = 'f4bccccc-158d-4658-9abe-6ea45b62e469' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Planea el futuro 💭', body_es = '¿Te apetece subir tu primera foto del «comienzo» al Álbum del embarazo?', title_fr = 'Planifiez l''avenir 💭', body_fr = 'Et si vous ajoutiez votre première photo du « début » à votre Album de grossesse ?', title_hi = 'भविष्य की योजना बनाइए 💭', body_hi = 'क्या आप प्रेग्नेंसी एल्बम में अपनी पहली ''शुरुआत'' वाली फ़ोटो अपलोड नहीं करना चाहेंगी?', title_id = 'Rencanakan masa depan 💭', body_id = 'Ingin mengunggah foto ''awal'' pertama Anda ke Album Kehamilan?', title_ja = '未来を思い描いて 💭', body_ja = 'マタニティアルバムに、最初の「はじまり」の写真をアップしてみませんか？', title_ko = '미래를 계획해요 💭', body_ko = '임신 앨범에 첫 ''시작'' 사진을 올려 보는 건 어때요?', title_nl = 'Plan de toekomst 💭', body_nl = 'Zin om je eerste ‘begin’-foto in je Zwangerschapsalbum te zetten?', title_pl = 'Zaplanuj przyszłość 💭', body_pl = 'Może dodasz pierwsze zdjęcie „na start” do Albumu ciąży?', title_pt = 'Planeie o futuro 💭', body_pt = 'Que tal carregar a sua primeira foto do "início" no Álbum da Gravidez?', title_sv = 'Planera framtiden 💭', body_sv = 'Vill du ladda upp ditt första ''början''-foto i Graviditetsalbumet?', title_vi = 'Lên kế hoạch cho tương lai 💭', body_vi = 'Bạn có muốn tải ảnh "khởi đầu" đầu tiên lên Album thai kỳ không?', title_zh = '规划未来 💭', body_zh = '要不要把第一张“起点”照片上传到孕期相册？' WHERE id = '29fd118b-28ca-4783-a20d-0dfe1f9257be' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Shhh... Estoy durmiendo 😴', body_es = 'Mi cerebro se desarrolla tan rápido que paso mucho tiempo dormido. Descansa tú también, mamá.', title_fr = 'Chut... Je dors 😴', body_fr = 'Mon cerveau se développe si vite que je dors beaucoup. Reposez-vous aussi, Maman.', title_hi = 'श्श्श... मैं सो रहा हूँ 😴', body_hi = 'मेरा दिमाग इतनी तेज़ी से विकसित हो रहा है कि मैं ज़्यादातर सोता रहता हूँ। आप भी आराम कीजिए, माँ।', title_id = 'Ssst... Aku sedang tidur 😴', body_id = 'Otakku berkembang begitu cepat sehingga aku banyak tidur. Anda juga istirahat ya, Bunda.', title_ja = 'シーッ...今ねんね中 😴', body_ja = '脳がすごい速さで発達しているから、ほとんど眠っているの。ママも休んでね。', title_ko = '쉿... 저 자고 있어요 😴', body_ko = '제 뇌가 아주 빠르게 자라서 대부분 잠을 자요. 엄마도 푹 쉬세요.', title_nl = 'Sst... Ik slaap 😴', body_nl = 'Mijn hersenen ontwikkelen zich zo snel dat ik veel slaap. Rust jij ook maar uit, mama.', title_pl = 'Ciii... Śpię 😴', body_pl = 'Mój mózg rozwija się tak szybko, że dużo czasu przesypiam. Ty też odpocznij, Mamo.', title_pt = 'Chiu... Estou a dormir 😴', body_pt = 'O meu cérebro desenvolve-se tão depressa que passo muito tempo a dormir. Descanse também, Mamã.', title_sv = 'Schhh... Jag sover 😴', body_sv = 'Min hjärna utvecklas så snabbt att jag sover det mesta av tiden. Vila du också, mamma.', title_vi = 'Suỵt... Con đang ngủ 😴', body_vi = 'Não con phát triển nhanh đến mức con ngủ rất nhiều. Mẹ cũng nghỉ ngơi đi nhé.', title_zh = '嘘……我在睡觉 😴', body_zh = '我的大脑发育得太快了，所以大部分时间都在睡觉。妈妈，你也休息一下吧。' WHERE id = 'e0c08939-6705-4af3-8c21-9e0d55be665b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Ponemos los cimientos 🏗️', body_es = 'Tu cuerpo se prepara para un nuevo milagro y la menstruación está por terminar. Tener reservas de ácido fólico (B9) es clave para una base sana de tu futuro bebé. ¿Has visto el menú variado de la sección Nutrición? 🥑', title_fr = 'On pose les fondations 🏗️', body_fr = 'Votre corps se prépare à un nouveau miracle, vos règles touchent à leur fin. Une réserve d''acide folique (B9) est essentielle pour une base solide pour votre futur bébé. Avez-vous vu le menu varié de la rubrique Nutrition ? 🥑', title_hi = 'नींव रख रहे हैं 🏗️', body_hi = 'आपका शरीर एक नए चमत्कार की तैयारी कर रहा है, पीरियड्स खत्म होने वाले हैं। होने वाले बच्चे की सेहतमंद नींव के लिए फ़ोलिक एसिड (B9) का भंडार ज़रूरी है। क्या आपने पोषण सेक्शन में भरपूर मेन्यू देखा? 🥑', title_id = 'Kita sedang meletakkan fondasi 🏗️', body_id = 'Tubuh Anda bersiap untuk keajaiban baru, dan menstruasi hampir selesai. Cadangan asam folat (B9) sangat penting untuk fondasi yang sehat bagi calon bayi. Sudah melihat menu lengkap di bagian Nutrisi? 🥑', title_ja = '土台づくり中 🏗️', body_ja = '体は新しい奇跡の準備をしていて、生理がもうすぐ終わります。未来の赤ちゃんの健やかな土台のために、葉酸（B9）を蓄えておくことが大切です。「栄養」セクションの充実したメニューはご覧になりましたか？🥑', title_ko = '기초를 다지고 있어요 🏗️', body_ko = '몸이 새로운 기적을 준비하고 있고, 생리가 곧 끝나요. 미래의 아기의 건강한 기초를 위해 엽산(B9)을 충분히 챙기는 것이 중요해요. 영양 섹션의 풍성한 메뉴를 보셨나요? 🥑', title_nl = 'We leggen de fundering 🏗️', body_nl = 'Je lichaam maakt zich klaar voor een nieuw wonder en je menstruatie is bijna voorbij. Een voorraad foliumzuur (B9) is essentieel voor een gezonde basis voor je toekomstige baby. Heb je het gevarieerde menu in het onderdeel Voeding al bekeken? 🥑', title_pl = 'Kładziemy fundamenty 🏗️', body_pl = 'Twoje ciało przygotowuje się na nowy cud, miesiączka dobiega końca. Zapas kwasu foliowego (B9) jest niezbędny dla zdrowych podstaw przyszłego dziecka. Widziałaś bogate menu w sekcji Odżywianie? 🥑', title_pt = 'Estamos a lançar os alicerces 🏗️', body_pt = 'O seu corpo prepara-se para um novo milagre e a menstruação está a terminar. Ter reservas de ácido fólico (B9) é essencial para uma base saudável do futuro bebé. Já viu o menu variado na secção Nutrição? 🥑', title_sv = 'Vi lägger grunden 🏗️', body_sv = 'Din kropp förbereder sig för ett nytt mirakel och mensen är snart slut. Ett förråd av folsyra (B9) är viktigt för en sund grund för ditt framtida barn. Har du kikat på den rika menyn i Kost-avsnittet? 🥑', title_vi = 'Đặt nền móng 🏗️', body_vi = 'Cơ thể bạn đang chuẩn bị cho một phép màu mới, kỳ kinh sắp kết thúc. Dự trữ axit folic (B9) là điều cần thiết cho nền tảng khỏe mạnh của em bé tương lai. Bạn đã xem thực đơn phong phú trong mục Dinh dưỡng chưa? 🥑', title_zh = '正在打地基 🏗️', body_zh = '你的身体正在为新的奇迹做准备，月经即将结束。为了未来宝宝健康的基础，储备叶酸（B9）必不可少。看过营养板块里丰富的菜单了吗？🥑' WHERE id = 'aa7e5901-964e-4a5b-a2e3-24bbf3210a04' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Dormir es algo muy dulce 😴', body_es = 'Hay que recargar energía. Antes de que lleguen las noches sin dormir, intenta dormir al menos 8 horas al día.', title_fr = 'Le sommeil, c''est précieux 😴', body_fr = 'Il faut faire le plein d''énergie. Avant l''arrivée des nuits blanches, essayez de dormir au moins 8 heures par jour.', title_hi = 'नींद कितनी मीठी चीज़ है 😴', body_hi = 'ऊर्जा जमा करनी है। रातों की नींद उड़ने से पहले, रोज़ कम से कम 8 घंटे सोने की कोशिश कीजिए।', title_id = 'Tidur itu nikmat 😴', body_id = 'Saatnya mengumpulkan energi. Sebelum malam-malam tanpa tidur tiba, usahakan tidur minimal 8 jam sehari.', title_ja = '睡眠は大切な宝物 😴', body_ja = 'エネルギーを蓄えておきましょう。眠れない夜がやってくる前に、1日に最低8時間は眠るようにしてください。', title_ko = '잠은 달콤한 거예요 😴', body_ko = '에너지를 모아 둘 때예요. 잠 못 드는 밤이 오기 전에 하루 최소 8시간은 자도록 해 보세요.', title_nl = 'Slaap is iets heerlijks 😴', body_nl = 'Tijd om energie op te laden. Probeer minstens 8 uur per dag te slapen, voordat de slapeloze nachten beginnen.', title_pl = 'Sen to słodka sprawa 😴', body_pl = 'Trzeba zbierać energię. Zanim nadejdą nieprzespane noce, staraj się spać co najmniej 8 godzin na dobę.', title_pt = 'Dormir é tão bom 😴', body_pt = 'É preciso ganhar energia. Antes de chegarem as noites sem dormir, tente dormir pelo menos 8 horas por dia.', title_sv = 'Sömn är något ljuvligt 😴', body_sv = 'Du behöver samla energi. Innan de sömnlösa nätterna kommer, försök sova minst 8 timmar per dygn.', title_vi = 'Giấc ngủ thật ngọt ngào 😴', body_vi = 'Cần tích trữ năng lượng. Trước khi những đêm mất ngủ đến, hãy cố gắng ngủ ít nhất 8 tiếng mỗi ngày.', title_zh = '睡眠是甜蜜的 😴', body_zh = '需要积攒能量啦。在不眠之夜到来之前，尽量每天至少睡8小时。' WHERE id = '9e6d0515-f2ff-48ac-93ec-f1d970c7ffc2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Activa el poder verde! 🥦', body_es = 'Las espinacas y el brócoli no son solo verduras, son un almacén natural de vitaminas. Añade hoy sin falta algo verde a tu menú.', title_fr = 'Faites le plein de vert ! 🥦', body_fr = 'Les épinards et le brocoli ne sont pas que des légumes, ce sont de vraies réserves naturelles de vitamines. Ajoutez du vert à votre menu aujourd''hui.', title_hi = 'हरियाली की ताकत लगाइए! 🥦', body_hi = 'पालक और ब्रोकली सिर्फ़ सब्ज़ियाँ नहीं, विटामिन का प्राकृतिक खज़ाना हैं। आज अपनी थाली में हरा रंग ज़रूर जोड़िए।', title_id = 'Nyalakan kekuatan hijau! 🥦', body_id = 'Bayam dan brokoli bukan sekadar sayuran, tetapi gudang vitamin alami. Pastikan menambahkan warna hijau ke menu Anda hari ini.', title_ja = '緑のパワーをオン！🥦', body_ja = 'ほうれん草やブロッコリーはただの野菜ではなく、天然のビタミンの宝庫です。今日はぜひメニューに緑を加えてください。', title_ko = '초록 파워를 켜세요! 🥦', body_ko = '시금치와 브로콜리는 그냥 채소가 아니라 천연 비타민 창고예요. 오늘 식단에 초록색을 꼭 더해 보세요.', title_nl = 'Zet de groene kracht in! 🥦', body_nl = 'Spinazie en broccoli zijn niet zomaar groenten, het zijn natuurlijke vitaminevoorraden. Voeg vandaag zeker wat groen toe aan je menu.', title_pl = 'Włącz zieloną moc! 🥦', body_pl = 'Szpinak i brokuły to nie tylko warzywa, ale naturalny magazyn witamin. Dodaj dziś koniecznie trochę zieleni do swojego menu.', title_pt = 'Ative o poder verde! 🥦', body_pt = 'Os espinafres e os brócolos não são apenas legumes, são reservas naturais de vitaminas. Junte hoje sem falta um pouco de verde ao seu menu.', title_sv = 'Sätt på den gröna kraften! 🥦', body_sv = 'Spenat och broccoli är inte bara grönsaker, de är naturliga vitaminförråd. Se till att få in något grönt i menyn i dag.', title_vi = 'Bật sức mạnh xanh lên! 🥦', body_vi = 'Rau bina và bông cải xanh không chỉ là rau, mà là kho vitamin tự nhiên. Hôm nay nhớ thêm màu xanh vào thực đơn nhé.', title_zh = '开启绿色能量！🥦', body_zh = '菠菜和西兰花不只是蔬菜，更是天然的维生素宝库。今天的餐桌上一定要加点绿色。' WHERE id = 'e9c7a1d0-36f4-4892-aa41-43d1c6c5e948' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Has elegido a tu médico? 👩‍⚕️', body_es = 'Busca desde ya al especialista en quien confiarás. Puedes revisar las opiniones en la sección Médicos y clínicas para decidirte.', title_fr = 'Avez-vous choisi votre médecin ? 👩‍⚕️', body_fr = 'Commencez dès maintenant à chercher le spécialiste en qui vous aurez confiance. Les avis de la rubrique Médecins et cliniques peuvent vous aider à choisir.', title_hi = 'क्या आपने डॉक्टर चुन लिया? 👩‍⚕️', body_hi = 'जिस विशेषज्ञ पर भरोसा करेंगी, उसे अभी से खोजिए। डॉक्टर और क्लिनिक सेक्शन में रिव्यू देखकर अपना चुनाव पक्का कर सकती हैं।', title_id = 'Sudah memilih dokter? 👩‍⚕️', body_id = 'Mulailah mencari spesialis yang bisa Anda percaya dari sekarang. Anda bisa memantapkan pilihan dengan membaca ulasan di bagian Dokter dan Klinik.', title_ja = 'お医者さんは決めましたか？👩‍⚕️', body_ja = '信頼できる専門医を今から探してみましょう。「医師とクリニック」セクションの口コミを見て、選択を固めることができます。', title_ko = '담당 의사는 정하셨나요? 👩‍⚕️', body_ko = '믿을 수 있는 전문의를 지금부터 알아보세요. 의사 및 병원 섹션의 후기를 보고 선택할 수 있어요.', title_nl = 'Heb je al een arts gekozen? 👩‍⚕️', body_nl = 'Zoek nu al een specialist die je vertrouwt. Bekijk de beoordelingen in het onderdeel Artsen en klinieken om je keuze te maken.', title_pl = 'Wybrałaś już lekarza? 👩‍⚕️', body_pl = 'Już teraz poszukaj specjalisty, któremu zaufasz. Opinie w sekcji Lekarze i kliniki pomogą ci podjąć decyzję.', title_pt = 'Já escolheu o seu médico? 👩‍⚕️', body_pt = 'Comece já a procurar o especialista em quem vai confiar. Pode afinar a sua escolha com as avaliações da secção Médicos e Clínicas.', title_sv = 'Har du valt din läkare? 👩‍⚕️', body_sv = 'Börja redan nu leta efter en specialist du kan lita på. Läs omdömena i avsnittet Läkare och kliniker och bestäm dig.', title_vi = 'Bạn đã chọn bác sĩ chưa? 👩‍⚕️', body_vi = 'Hãy tìm hiểu ngay từ bây giờ chuyên gia mà bạn tin tưởng. Bạn có thể xem đánh giá trong mục Bác sĩ và Phòng khám để chọn chính xác hơn.', title_zh = '选好医生了吗？👩‍⚕️', body_zh = '现在就开始了解你信任的专家吧。可以在医生与诊所板块查看评价，帮你做出选择。' WHERE id = '95c500c4-d966-4eca-85e3-f43263957e13' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Tu cuerpo te envía señales? 🌡️', body_es = 'Se acerca la ovulación. Presta atención a tu temperatura corporal, ¡son los días con más posibilidades!', title_fr = 'Votre corps vous envoie des signaux ? 🌡️', body_fr = 'L''ovulation approche. Surveillez votre température : ce sont vos jours les plus fertiles !', title_hi = 'शरीर संकेत दे रहा है? 🌡️', body_hi = 'ओव्यूलेशन का समय करीब है। शरीर के तापमान पर ध्यान दीजिए, ये सबसे ज़्यादा संभावना वाले दिन हैं!', title_id = 'Tubuh Anda memberi sinyal? 🌡️', body_id = 'Masa ovulasi semakin dekat. Perhatikan suhu tubuh Anda, inilah hari-hari dengan peluang tertinggi!', title_ja = '体がサインを出していますか？🌡️', body_ja = '排卵期が近づいています。基礎体温に注目して。チャンスがいちばん高い日です！', title_ko = '몸이 신호를 보내고 있나요? 🌡️', body_ko = '배란기가 다가오고 있어요. 체온을 잘 살펴보세요, 가능성이 가장 높은 날들이에요!', title_nl = 'Geeft je lichaam signalen? 🌡️', body_nl = 'Je ovulatie komt eraan. Let op je lichaamstemperatuur: dit zijn de dagen met de grootste kans!', title_pl = 'Twoje ciało daje sygnały? 🌡️', body_pl = 'Zbliża się owulacja. Zwracaj uwagę na temperaturę ciała, to dni największych szans!', title_pt = 'O seu corpo está a dar sinais? 🌡️', body_pt = 'A ovulação aproxima-se. Esteja atenta à temperatura corporal: são os dias com mais probabilidades!', title_sv = 'Skickar kroppen signaler? 🌡️', body_sv = 'Ägglossningen närmar sig. Håll koll på kroppstemperaturen, det är nu chansen är som störst!', title_vi = 'Cơ thể đang phát tín hiệu? 🌡️', body_vi = 'Thời kỳ rụng trứng đang đến gần. Hãy chú ý nhiệt độ cơ thể, đây là những ngày có cơ hội cao nhất!', title_zh = '身体在发出信号吗？🌡️', body_zh = '排卵期快到了。留意你的体温，这几天是机会最大的时候！' WHERE id = '572d6539-f881-4ec9-a3f9-b12c236e3b0d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Hora de nueces y almendras 🥜', body_es = 'Para picar, elige frutos secos en lugar de patatas fritas. El omega-3 lo necesitáis tú y tu futuro bebé.', title_fr = 'C''est l''heure des noix et des amandes 🥜', body_fr = 'Pour le goûter, choisissez des fruits secs plutôt que des chips. Les oméga-3 sont importants pour vous comme pour votre futur bébé.', title_hi = 'अखरोट और बादाम का समय 🥜', body_hi = 'नाश्ते में चिप्स नहीं, मेवे चुनिए। ओमेगा-3 आपके लिए भी ज़रूरी है और होने वाले बच्चे के लिए भी।', title_id = 'Saatnya kenari dan almon 🥜', body_id = 'Untuk camilan, pilih kacang-kacangan, bukan keripik. Omega-3 dibutuhkan oleh Anda dan calon bayi.', title_ja = 'クルミとアーモンドの時間 🥜', body_ja = 'おやつにはポテトチップスではなくナッツを選んで。オメガ3はママにも未来の赤ちゃんにも必要です。', title_ko = '호두와 아몬드 타임 🥜', body_ko = '간식으로 과자 대신 견과류를 골라 보세요. 오메가-3는 엄마와 미래의 아기 모두에게 필요해요.', title_nl = 'Tijd voor walnoten en amandelen 🥜', body_nl = 'Kies als tussendoortje noten in plaats van chips. Omega-3 is nodig voor jou én voor je toekomstige baby.', title_pl = 'Czas na orzechy i migdały 🥜', body_pl = 'Na przekąskę wybierz orzechy zamiast chipsów. Omega-3 jest potrzebne i tobie, i przyszłemu dziecku.', title_pt = 'Hora das nozes e amêndoas 🥜', body_pt = 'Para o lanche, escolha frutos secos em vez de batatas fritas. O ómega-3 faz falta à mãe e ao futuro bebé.', title_sv = 'Dags för valnötter och mandlar 🥜', body_sv = 'Välj nötter i stället för chips som mellanmål. Omega-3 behövs både för dig och för ditt framtida barn.', title_vi = 'Đến giờ óc chó và hạnh nhân 🥜', body_vi = 'Bữa phụ hãy chọn các loại hạt thay vì khoai tây chiên. Omega-3 cần cho cả bạn và em bé tương lai.', title_zh = '核桃和杏仁时间到 🥜', body_zh = '零食别选薯片，选坚果吧。你和未来的宝宝都需要Omega-3。' WHERE id = 'bd4effb9-20aa-4b2c-9886-28f1a8aa42f4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Dedícate tiempo 💆‍♀️', body_es = '¡Fuera las hormonas del estrés! Hoy mira tu película favorita o date una ducha tibia.', title_fr = 'Prenez du temps pour vous 💆‍♀️', body_fr = 'Chassons les hormones du stress ! Aujourd''hui, regardez votre film préféré ou prenez une douche tiède.', title_hi = 'अपने लिए समय निकालिए 💆‍♀️', body_hi = 'स्ट्रेस हार्मोन को भगाइए! आज अपनी पसंदीदा फ़िल्म देखिए या गुनगुने पानी से नहाइए।', title_id = 'Luangkan waktu untuk diri sendiri 💆‍♀️', body_id = 'Usir hormon stres! Hari ini tonton film favorit Anda atau mandi air hangat.', title_ja = '自分の時間を大切に 💆‍♀️', body_ja = 'ストレスホルモンを追い払おう！今日は好きな映画を観たり、ぬるめのシャワーを浴びたりしてくださいね。', title_ko = '나를 위한 시간을 가져요 💆‍♀️', body_ko = '스트레스 호르몬을 날려 버려요! 오늘은 좋아하는 영화를 보거나 따뜻한 샤워를 해 보세요.', title_nl = 'Neem tijd voor jezelf 💆‍♀️', body_nl = 'Weg met die stresshormonen! Kijk vandaag je favoriete film of neem een warme douche.', title_pl = 'Znajdź czas dla siebie 💆‍♀️', body_pl = 'Przeganiamy hormony stresu! Obejrzyj dziś ulubiony film albo weź ciepły prysznic.', title_pt = 'Reserve tempo para si 💆‍♀️', body_pt = 'Vamos afastar as hormonas do stress! Hoje, veja um filme de que gosta ou tome um duche morno.', title_sv = 'Ta tid för dig själv 💆‍♀️', body_sv = 'Vi jagar bort stresshormonerna! Se en film du gillar i dag eller ta en varm dusch.', title_vi = 'Dành thời gian cho bản thân 💆‍♀️', body_vi = 'Đuổi hormone căng thẳng đi nào! Hôm nay hãy xem một bộ phim yêu thích hoặc tắm nước ấm.', title_zh = '给自己留点时间 💆‍♀️', body_zh = '赶走压力激素！今天看一部喜欢的电影，或者洗个温水澡吧。' WHERE id = '186bdc98-bb17-499f-bf7e-d9ff9eaa5492' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'El comienzo más pequeño 🫧', body_es = 'Todavía no se ve a simple vista. Tu futuro bebé es solo una célula, ¡pero tiene grandes planes!', title_fr = 'Le plus petit des débuts 🫧', body_fr = 'Invisible à l''œil nu pour l''instant. Votre futur bébé n''est qu''une seule cellule, mais il a de grands projets !', title_hi = 'सबसे छोटी शुरुआत 🫧', body_hi = 'अभी आँखों से दिखता नहीं। होने वाला बच्चा अभी बस एक कोशिका है, पर उसके इरादे बड़े हैं!', title_id = 'Awal yang paling kecil 🫧', body_id = 'Belum terlihat oleh mata. Calon bayi baru satu sel, tapi rencananya besar!', title_ja = 'いちばん小さなはじまり 🫧', body_ja = 'まだ目には見えません。未来の赤ちゃんはたった1つの細胞ですが、大きな計画を持っています！', title_ko = '가장 작은 시작 🫧', body_ko = '아직 눈에는 보이지 않아요. 미래의 아기는 단 하나의 세포지만, 큰 계획을 품고 있어요!', title_nl = 'Het allerkleinste begin 🫧', body_nl = 'Nog niet met het blote oog te zien. Je toekomstige baby is maar één cel, maar heeft grote plannen!', title_pl = 'Najmniejszy początek 🫧', body_pl = 'Jeszcze nie widać go gołym okiem. Przyszłe dziecko to na razie jedna komórka, ale ma wielkie plany!', title_pt = 'O mais pequeno dos começos 🫧', body_pt = 'Ainda não se vê a olho nu. O futuro bebé é apenas uma célula, mas tem grandes planos!', title_sv = 'Den allra minsta början 🫧', body_sv = 'Ännu syns det inte med blotta ögat. Ditt framtida barn är bara en cell, men har stora planer!', title_vi = 'Khởi đầu nhỏ bé nhất 🫧', body_vi = 'Hiện tại vẫn chưa thể nhìn thấy bằng mắt. Em bé tương lai mới chỉ là một tế bào, nhưng đã có những kế hoạch lớn!', title_zh = '最小的开始 🫧', body_zh = '现在肉眼还看不见。未来的宝宝只是一个细胞，但它有很大的计划！' WHERE id = 'caca7263-c7a5-4d9a-92e5-c7d0658633f3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Ha llegado el momento mágico? ✨', body_es = 'La fecundación suele ocurrir por estos días. Aunque no lo notes, un proceso milagroso ya ha comenzado.', title_fr = 'Le moment magique est-il arrivé ? ✨', body_fr = 'La fécondation a généralement lieu vers ces jours-ci. Même si vous ne le sentez pas, un processus miraculeux a commencé.', title_hi = 'क्या जादुई पल आ गया? ✨', body_hi = 'निषेचन आमतौर पर इन्हीं दिनों में होता है। भले आपको महसूस न हो, चमत्कारी प्रक्रिया शुरू हो चुकी है।', title_id = 'Sudah tiba momen ajaibnya? ✨', body_id = 'Pembuahan biasanya terjadi di hari-hari ini. Meski tidak terasa, proses ajaib sudah dimulai.', title_ja = '魔法の瞬間はきた？✨', body_ja = '受精はたいていこの頃に起こります。気づかなくても、奇跡のプロセスはもう始まっています。', title_ko = '마법 같은 순간이 왔을까요? ✨', body_ko = '수정은 보통 이 무렵에 일어나요. 느끼지 못해도 기적 같은 과정이 이미 시작됐어요.', title_nl = 'Is het magische moment aangebroken? ✨', body_nl = 'De bevruchting vindt meestal rond deze dagen plaats. Ook al voel je het niet, er is een wonderlijk proces begonnen.', title_pl = 'Czy nadszedł magiczny moment? ✨', body_pl = 'Do zapłodnienia dochodzi zwykle w te dni. Nawet jeśli tego nie czujesz, cudowny proces już się rozpoczął.', title_pt = 'Chegou o momento mágico? ✨', body_pt = 'A fecundação costuma acontecer por estes dias. Mesmo sem sentir nada, um processo milagroso já começou.', title_sv = 'Har det magiska ögonblicket kommit? ✨', body_sv = 'Befruktningen sker oftast runt de här dagarna. Även om du inte känner något har en mirakulös process börjat.', title_vi = 'Khoảnh khắc kỳ diệu đã đến? ✨', body_vi = 'Sự thụ tinh thường diễn ra vào những ngày này. Dù bạn chưa cảm nhận được, quá trình kỳ diệu đã bắt đầu.', title_zh = '神奇的时刻到了吗？✨', body_zh = '受精通常发生在这几天。即使你感觉不到，奇妙的过程已经开始了。' WHERE id = 'c71b2b52-957c-4d0d-918e-02a81d0c792c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Bomba de proteínas 🍳', body_es = '¿Hay huevos en el desayuno? La proteína es esencial para renovar las células. ¡Buen provecho!', title_fr = 'Bombe de protéines 🍳', body_fr = 'Des œufs au petit-déjeuner ? Les protéines sont essentielles au renouvellement des cellules. Bon appétit !', title_hi = 'प्रोटीन का धमाका 🍳', body_hi = 'नाश्ते में अंडा है? कोशिकाओं के नवीनीकरण के लिए प्रोटीन ज़रूरी है। भरपेट खाइए!', title_id = 'Bom protein 🍳', body_id = 'Ada telur untuk sarapan? Protein penting untuk pembaruan sel. Selamat makan!', title_ja = 'たんぱく質パワー 🍳', body_ja = '朝ごはんに卵はありますか？細胞の生まれ変わりにはたんぱく質が欠かせません。召し上がれ！', title_ko = '단백질 폭탄 🍳', body_ko = '아침에 달걀 드셨어요? 세포가 새로워지려면 단백질이 중요해요. 맛있게 드세요!', title_nl = 'Eiwitbom 🍳', body_nl = 'Eieren bij het ontbijt? Eiwit is belangrijk voor de vernieuwing van cellen. Eet smakelijk!', title_pl = 'Bomba białkowa 🍳', body_pl = 'Masz jajka na śniadanie? Białko jest ważne dla odnowy komórek. Smacznego!', title_pt = 'Uma bomba de proteína 🍳', body_pt = 'Há ovos ao pequeno-almoço? A proteína é essencial para a renovação das células. Bom apetite!', title_sv = 'Proteinbomb 🍳', body_sv = 'Blir det ägg till frukost? Protein är viktigt för att cellerna ska förnyas. Smaklig måltid!', title_vi = 'Quả bom protein 🍳', body_vi = 'Bữa sáng có trứng không? Protein rất quan trọng cho sự đổi mới tế bào. Chúc ngon miệng!', title_zh = '蛋白质炸弹 🍳', body_zh = '早餐有鸡蛋吗？蛋白质对细胞更新很重要。祝你用餐愉快！' WHERE id = '00106d30-5d19-414e-a507-c025fa6d17d2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Salimos a caminar? 👟', body_es = 'El aire fresco te subirá el ánimo. Mira el programa de caminata suave en la sección Ejercicios.', title_fr = 'On va se promener ? 👟', body_fr = 'L''air frais va vous remonter le moral. Découvrez le programme de marche douce dans la rubrique Exercices.', title_hi = 'टहलने चलें? 👟', body_hi = 'ताज़ी हवा आपका मूड अच्छा कर देगी। एक्सरसाइज़ सेक्शन में हल्का वॉकिंग प्रोग्राम देखिए।', title_id = 'Jalan-jalan yuk? 👟', body_id = 'Udara segar akan memperbaiki suasana hati Anda. Lihat program jalan santai di bagian Latihan.', title_ja = 'お散歩に出かけませんか？👟', body_ja = '新鮮な空気で気分が上がります。「エクササイズ」セクションの軽いウォーキングプログラムをチェックしてみてください。', title_ko = '산책하러 나가 볼까요? 👟', body_ko = '맑은 공기가 기분을 북돋아 줄 거예요. 운동 섹션의 가벼운 걷기 프로그램을 확인해 보세요.', title_nl = 'Zullen we een wandeling maken? 👟', body_nl = 'Frisse lucht geeft je humeur een boost. Bekijk het rustige wandelprogramma in het onderdeel Oefeningen.', title_pl = 'Idziemy na spacer? 👟', body_pl = 'Świeże powietrze poprawi ci nastrój. Zajrzyj do programu lekkich spacerów w sekcji Ćwiczenia.', title_pt = 'Vamos dar um passeio? 👟', body_pt = 'O ar fresco vai melhorar o seu humor. Veja o programa de caminhada leve na secção Exercícios.', title_sv = 'Ska vi ta en promenad? 👟', body_sv = 'Frisk luft piggar upp humöret. Kolla in det lätta promenadprogrammet i avsnittet Träning.', title_vi = 'Đi dạo nhé? 👟', body_vi = 'Không khí trong lành sẽ giúp bạn vui hơn. Hãy xem chương trình đi bộ nhẹ nhàng trong mục Bài tập.', title_zh = '出去散散步吧？👟', body_zh = '新鲜空气会让你心情变好。看看运动板块里的轻松步行计划吧。' WHERE id = 'ff01c295-45c4-493a-ab43-5a6c543c478d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Tienes náuseas? 🤢', body_es = '¿Las mañanas se hacen difíciles? Un té de jengibre o agua con limón pueden ayudarte. No dejes el estómago vacío.', title_fr = 'Des nausées ? 🤢', body_fr = 'Les matins sont difficiles ? Une tisane au gingembre ou de l''eau citronnée peuvent vous soulager. Évitez d''avoir l''estomac vide.', title_hi = 'जी मिचला रहा है? 🤢', body_hi = 'सुबहें मुश्किल हो रही हैं? अदरक की चाय या नींबू पानी राहत दे सकता है। पेट खाली मत रखिए।', title_id = 'Merasa mual? 🤢', body_id = 'Pagi terasa berat? Teh jahe atau air lemon bisa membantu. Jangan biarkan perut kosong.', title_ja = '吐き気がありますか？🤢', body_ja = '朝がつらいですか？しょうが茶やレモン水が助けになるかもしれません。空腹にならないようにしましょう。', title_ko = '속이 메스꺼우세요? 🤢', body_ko = '아침이 힘드신가요? 생강차나 레몬물이 도움이 될 수 있어요. 공복은 피하세요.', title_nl = 'Misselijk? 🤢', body_nl = 'Zijn de ochtenden zwaar? Gemberthee of water met citroen kan helpen. Laat je maag niet leeg.', title_pl = 'Masz mdłości? 🤢', body_pl = 'Poranki są trudniejsze? Herbata imbirowa lub woda z cytryną mogą przynieść ulgę. Nie dopuszczaj do pustego żołądka.', title_pt = 'Sente náuseas? 🤢', body_pt = 'As manhãs estão difíceis? Um chá de gengibre ou água com limão podem ajudar. Não fique de estômago vazio.', title_sv = 'Mår du illa? 🤢', body_sv = 'Är morgnarna jobbiga? Ingefärste eller vatten med citron kan hjälpa. Låt inte magen vara tom.', title_vi = 'Buồn nôn à? 🤢', body_vi = 'Buổi sáng thấy khó chịu? Trà gừng hoặc nước chanh có thể giúp ích. Đừng để bụng đói nhé.', title_zh = '恶心想吐吗？🤢', body_zh = '早上越来越难熬？姜茶或柠檬水可能会有帮助。别让肚子空着。' WHERE id = '6f8a4fbb-f3ef-409d-a1cc-75f70eff873b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Vuelve tu energía? 🔋', body_es = '¿Cómo te sientes hoy? ¡Anótalo en el Diario de síntomas! ✅', title_fr = 'Votre énergie revient ? 🔋', body_fr = 'Comment vous sentez-vous aujourd''hui ? Notez-le dans votre Journal des symptômes ! ✅', title_hi = 'ऊर्जा लौट रही है? 🔋', body_hi = 'आज आप कैसा महसूस कर रही हैं? सिम्पटम डायरी में लिखिए! ✅', title_id = 'Energi Anda kembali? 🔋', body_id = 'Bagaimana perasaan Anda hari ini? Catat di Buku Harian Gejala! ✅', title_ja = '元気が戻ってきましたか？🔋', body_ja = '今日の体調はいかがですか？「症状日記」に記録しましょう！✅', title_ko = '에너지가 돌아오고 있나요? 🔋', body_ko = '오늘 기분은 어떠세요? 증상 일기에 기록해 보세요! ✅', title_nl = 'Komt je energie terug? 🔋', body_nl = 'Hoe voel je je vandaag? Noteer het in je Symptomendagboek! ✅', title_pl = 'Wraca ci energia? 🔋', body_pl = 'Jak się dziś czujesz? Zapisz to w Dzienniku objawów! ✅', title_pt = 'A energia está a voltar? 🔋', body_pt = 'Como se sente hoje? Registe no Diário de Sintomas! ✅', title_sv = 'Kommer energin tillbaka? 🔋', body_sv = 'Hur mår du i dag? Anteckna det i Symtomdagboken! ✅', title_vi = 'Năng lượng đang trở lại? 🔋', body_vi = 'Hôm nay bạn thấy thế nào? Ghi lại vào Nhật ký triệu chứng nhé! ✅', title_zh = '精力回来了吗？🔋', body_zh = '今天感觉怎么样？在症状日记里记一笔吧！✅' WHERE id = '113c2ffd-412e-42e7-9340-2d6ba48c6d05' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Gran obra en marcha! 🚧', body_es = 'Se están formando el cerebro y la columna vertebral. ¡Sigue tomando ácido fólico!', title_fr = 'Gros chantier en cours ! 🚧', body_fr = 'Le cerveau et la colonne vertébrale se forment. Continuez à prendre votre acide folique !', title_hi = 'ज़रूरी निर्माण चल रहा है! 🚧', body_hi = 'दिमाग और रीढ़ की हड्डी बन रही है। फ़ोलिक एसिड लेती रहिए!', title_id = 'Pembangunan penting sedang berlangsung! 🚧', body_id = 'Otak dan tulang belakang sedang terbentuk. Terus minum asam folat!', title_ja = '大事な工事が進行中！🚧', body_ja = '脳と脊髄がつくられています。葉酸を飲み続けてくださいね！', title_ko = '중요한 공사가 진행 중이에요! 🚧', body_ko = '뇌와 척추가 만들어지고 있어요. 엽산을 계속 챙겨 드세요!', title_nl = 'Belangrijke bouwwerkzaamheden! 🚧', body_nl = 'De hersenen en de wervelkolom worden gevormd. Blijf foliumzuur innemen!', title_pl = 'Trwa ważna budowa! 🚧', body_pl = 'Kształtuje się mózg i kręgosłup. Dalej przyjmuj kwas foliowy!', title_pt = 'Obras importantes em curso! 🚧', body_pt = 'O cérebro e a coluna vertebral estão a formar-se. Continue a tomar o ácido fólico!', title_sv = 'Viktigt bygge pågår! 🚧', body_sv = 'Hjärnan och ryggraden håller på att bildas. Fortsätt ta din folsyra!', title_vi = 'Công trình quan trọng đang thi công! 🚧', body_vi = 'Não và tủy sống đang hình thành. Tiếp tục uống axit folic nhé!', title_zh = '重要工程进行中！🚧', body_zh = '大脑和脊柱正在形成。继续坚持服用叶酸！' WHERE id = 'd2eb5bbc-3775-4f57-aa9a-087ca149ab57' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Náuseas matutinas? 🤢', body_es = 'Come una galleta salada antes de levantarte de la cama. Come poco y a menudo para mantener estable el azúcar en sangre.', title_fr = 'Nausées matinales ? 🤢', body_fr = 'Mangez quelques crackers salés avant même de vous lever. Mangez peu mais souvent pour garder une glycémie stable.', title_hi = 'मॉर्निंग सिकनेस? 🤢', body_hi = 'बिस्तर से उठने से पहले नमकीन क्रैकर खाइए। खून में शुगर स्थिर रखने के लिए थोड़ा-थोड़ा खाइए।', title_id = 'Mual di pagi hari? 🤢', body_id = 'Makan biskuit asin sebelum bangun dari tempat tidur. Makan sedikit-sedikit tapi sering agar gula darah tetap stabil.', title_ja = 'つわりがつらい？🤢', body_ja = '起き上がる前に、塩味のクラッカーを食べてみて。血糖値を安定させるために、少量ずつこまめに食べましょう。', title_ko = '아침 입덧이 있나요? 🤢', body_ko = '침대에서 일어나기 전에 짭짤한 크래커를 드세요. 혈당을 안정적으로 유지하려면 조금씩 자주 드세요.', title_nl = 'Ochtendmisselijkheid? 🤢', body_nl = 'Eet een paar zoute crackers voordat je opstaat. Eet vaak kleine beetjes om je bloedsuiker stabiel te houden.', title_pl = 'Poranne mdłości? 🤢', body_pl = 'Zjedz słone krakersy, zanim wstaniesz z łóżka. Jedz małe porcje, by utrzymać stały poziom cukru we krwi.', title_pt = 'Enjoos matinais? 🤢', body_pt = 'Coma uma bolacha salgada antes de se levantar da cama. Faça refeições pequenas e frequentes para manter o açúcar no sangue estável.', title_sv = 'Morgonillamående? 🤢', body_sv = 'Ät ett salt kex innan du kliver upp ur sängen. Ät små portioner ofta för att hålla blodsockret jämnt.', title_vi = 'Ốm nghén buổi sáng? 🤢', body_vi = 'Ăn bánh quy mặn trước khi rời giường. Ăn ít một, chia nhiều bữa để giữ đường huyết ổn định.', title_zh = '早晨恶心？🤢', body_zh = '起床前先吃几片咸饼干。少量多餐，帮助血糖保持稳定。' WHERE id = '90d7f6db-e46c-4431-84a4-08c7cb36dff8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Bum-bum... ¿Lo oyes? 💓', body_es = '¡Mi corazón empezó a latir! ¿Estás deseando oír este pequeño motor? ¡Apunta en el calendario la fecha de tu primera ecografía! 🖊️', title_fr = 'Boum-boum... Vous l''entendez ? 💓', body_fr = 'Mon cœur a commencé à battre ! Impatiente d''entendre ce petit moteur ? Notez votre première échographie dans le calendrier ! 🖊️', title_hi = 'धक-धक... सुन रही हैं? 💓', body_hi = 'मेरा दिल धड़कने लगा है! इस छोटे इंजन की आवाज़ सुनने को बेताब हैं? कैलेंडर में पहले अल्ट्रासाउंड का समय लिख लीजिए! 🖊️', title_id = 'Dug-dug... Terdengar? 💓', body_id = 'Jantungku mulai berdetak! Tidak sabar mendengar suara mesin kecil ini? Catat jadwal USG pertama di kalender! 🖊️', title_ja = 'ドクドク...聞こえる？💓', body_ja = '心臓が動きはじめたよ！この小さなエンジンの音を聞くのが待ちきれない？カレンダーに初めてのエコー検査の日を書き込んでね！🖊️', title_ko = '콩닥콩닥... 들리세요? 💓', body_ko = '제 심장이 뛰기 시작했어요! 이 작은 엔진 소리가 빨리 듣고 싶으시죠? 캘린더에 첫 초음파 날짜를 기록해 두세요! 🖊️', title_nl = 'Boem-boem... Hoor je het? 💓', body_nl = 'Mijn hart is begonnen met kloppen! Kun je niet wachten om dit kleine motortje te horen? Zet je eerste echo in de agenda! 🖊️', title_pl = 'Bum-bum... Słyszysz? 💓', body_pl = 'Moje serce zaczęło bić! Nie możesz się doczekać, by usłyszeć ten mały silniczek? Zapisz w kalendarzu termin pierwszego USG! 🖊️', title_pt = 'Tum-tum... Está a ouvir? 💓', body_pt = 'O meu coração começou a bater! Está ansiosa por ouvir este pequeno motor? Marque no calendário a data da primeira ecografia! 🖊️', title_sv = 'Dunk-dunk... Hör du? 💓', body_sv = 'Mitt hjärta har börjat slå! Längtar du efter att höra den lilla motorn? Skriv in tiden för första ultraljudet i kalendern! 🖊️', title_vi = 'Thình thịch... Mẹ nghe thấy không? 💓', body_vi = 'Tim con bắt đầu đập rồi! Mẹ có nóng lòng nghe tiếng "động cơ" nhỏ này không? Đánh dấu lịch siêu âm đầu tiên vào Lịch nhé! 🖊️', title_zh = '咚咚……你听到了吗？💓', body_zh = '我的心脏开始跳动啦！是不是迫不及待想听听这个小马达的声音？在日历上记下第一次B超的时间吧！🖊️' WHERE id = 'ee028003-7c13-49d6-a074-6279f0809a0e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Hora de la confirmación oficial! ✅', body_es = 'Si aún no has ido, pide cita con el médico. Encuentra el adecuado para ti en la sección Médicos.', title_fr = 'L''heure de la confirmation officielle ! ✅', body_fr = 'Si ce n''est pas encore fait, prenez rendez-vous chez le médecin. Trouvez celui qui vous convient dans la rubrique Médecins.', title_hi = 'आधिकारिक पुष्टि का समय! ✅', body_hi = 'अगर अभी तक नहीं गईं, तो डॉक्टर से अपॉइंटमेंट ले लीजिए। डॉक्टर सेक्शन में अपने लिए सही डॉक्टर ढूँढिए।', title_id = 'Saatnya konfirmasi resmi! ✅', body_id = 'Jika belum, buat janji dengan dokter. Temukan dokter yang cocok untuk Anda di bagian Dokter.', title_ja = '正式に確認するときです！✅', body_ja = 'まだなら、診察を予約しましょう。「医師」セクションでぴったりの先生を見つけてください。', title_ko = '공식 확인할 시간이에요! ✅', body_ko = '아직 안 가셨다면 진료를 예약하세요. 의사 섹션에서 나에게 맞는 의사를 찾아보세요.', title_nl = 'Tijd voor de officiële bevestiging! ✅', body_nl = 'Ben je nog niet geweest? Maak dan een afspraak bij de arts. Vind een passende arts in het onderdeel Artsen.', title_pl = 'Czas na oficjalne potwierdzenie! ✅', body_pl = 'Jeśli jeszcze nie byłaś, umów się na wizytę u lekarza. Znajdź odpowiedniego w sekcji Lekarze.', title_pt = 'Hora da confirmação oficial! ✅', body_pt = 'Se ainda não foi, marque uma consulta médica. Encontre o médico certo para si na secção Médicos.', title_sv = 'Dags för en officiell bekräftelse! ✅', body_sv = 'Om du inte redan har gjort det, boka ett läkarbesök. Hitta någon som passar dig i avsnittet Läkare.', title_vi = 'Đến lúc xác nhận chính thức! ✅', body_vi = 'Nếu chưa đi khám, hãy đặt lịch hẹn bác sĩ. Tìm bác sĩ phù hợp với mẹ trong mục Bác sĩ.', title_zh = '该正式确认啦！✅', body_zh = '如果还没去过，就预约看医生吧。在医生板块找到适合你的那一位。' WHERE id = 'b0910e0e-cc92-44f5-8046-b09a58173a6b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Los primeros latidos 💓', body_es = 'Aunque no lo oigas, ese pequeño corazón ya está funcionando. ¡Late más de 100 veces por minuto!', title_fr = 'Les premiers battements de cœur 💓', body_fr = 'Même si vous ne l''entendez pas, ce petit cœur s''est déjà mis en marche. Il bat plus de 100 fois par minute !', title_hi = 'पहली धड़कनें 💓', body_hi = 'भले आप सुन न पाएँ, वह छोटा सा दिल काम शुरू कर चुका है। एक मिनट में 100 से ज़्यादा बार धड़कता है!', title_id = 'Detak jantung pertama 💓', body_id = 'Meski Anda belum bisa mendengarnya, jantung kecil itu sudah bekerja. Berdetak lebih dari 100 kali per menit!', title_ja = '初めての心拍 💓', body_ja = 'まだ聞こえなくても、その小さな心臓はもう動きはじめています。1分間に100回以上も脈打っています！', title_ko = '첫 심장 박동 💓', body_ko = '아직 들리지 않아도 그 작은 심장은 이미 뛰고 있어요. 1분에 100번 넘게요!', title_nl = 'De eerste hartslagen 💓', body_nl = 'Ook al hoor je het niet, dat kleine hartje is al aan het werk. Het klopt meer dan 100 keer per minuut!', title_pl = 'Pierwsze bicie serca 💓', body_pl = 'Choć jeszcze tego nie słyszysz, to maleńkie serce już pracuje. Bije ponad 100 razy na minutę!', title_pt = 'Os primeiros batimentos 💓', body_pt = 'Mesmo que ainda não o ouça, aquele pequeno coração já começou a trabalhar. Bate mais de 100 vezes por minuto!', title_sv = 'De första hjärtslagen 💓', body_sv = 'Även om du inte hör det har det lilla hjärtat redan satt igång. Det slår över 100 gånger i minuten!', title_vi = 'Những nhịp tim đầu tiên 💓', body_vi = 'Dù mẹ chưa nghe thấy, trái tim nhỏ ấy đã bắt đầu hoạt động. Đập hơn 100 lần mỗi phút!', title_zh = '最初的心跳 💓', body_zh = '虽然你还听不到，但那颗小小的心脏已经开始工作了。每分钟跳动100多次！' WHERE id = '55b6e494-7a56-4309-af7f-8fd6e4c2696c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Olvidaste la vitamina? 😬', body_es = '¡El ácido fólico es la base de mi futura columna! Mira el Recordatorio de medicamentos: ¿ya tomaste la dosis de hoy? ✅', title_fr = 'Vous avez oublié votre vitamine ? 😬', body_fr = 'L''acide folique est la base de ma future colonne vertébrale ! Regardez votre Rappel de médicaments : avez-vous pris votre dose du jour ? ✅', title_hi = 'विटामिन भूल गईं? 😬', body_hi = 'फ़ोलिक एसिड मेरी होने वाली रीढ़ की नींव है! दवा रिमाइंडर देखिए, क्या आपने आज की खुराक ली? ✅', title_id = 'Lupa vitamin? 😬', body_id = 'Asam folat adalah fondasi tulang belakangku nanti! Cek Pengingat Obat, sudah minum dosis hari ini? ✅', title_ja = 'ビタミン、忘れちゃった？😬', body_ja = '葉酸はわたしの未来の背骨の土台なんだよ！「お薬リマインダー」を見てね、今日の分は飲んだ？✅', title_ko = '비타민 잊으셨어요? 😬', body_ko = '엽산은 제 미래 척추의 기초예요! 복약 알림을 확인해 보세요, 오늘 복용하셨나요? ✅', title_nl = 'Je vitamine vergeten? 😬', body_nl = 'Foliumzuur is de basis van mijn toekomstige ruggengraat! Kijk in je Medicijnherinnering: heb je je dosis van vandaag al genomen? ✅', title_pl = 'Zapomniałaś o witaminie? 😬', body_pl = 'Kwas foliowy to fundament mojego przyszłego kręgosłupa! Sprawdź Przypomnienie o lekach: wzięłaś już dzisiejszą dawkę? ✅', title_pt = 'Esqueceu-se da vitamina? 😬', body_pt = 'O ácido fólico é a base da minha futura coluna! Veja o Lembrete de Medicação: já tomou a dose de hoje? ✅', title_sv = 'Har du glömt vitaminet? 😬', body_sv = 'Folsyra är grunden för min framtida ryggrad! Kolla Medicinpåminnelsen, har du tagit dagens dos? ✅', title_vi = 'Quên uống vitamin rồi? 😬', body_vi = 'Axit folic là nền móng cho cột sống tương lai của con! Xem Nhắc nhở uống thuốc nhé, hôm nay mẹ đã uống liều chưa? ✅', title_zh = '忘记吃维生素了？😬', body_zh = '叶酸是我未来脊柱的基础！看看用药提醒，今天的剂量吃了吗？✅' WHERE id = '4268dd91-2b9a-483a-aa93-8f2b7d7809a9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Es normal el manchado? 🩸', body_es = 'No te asustes, puede ser sangrado de implantación. Si tienes dudas, mira la sección Médicos.', title_fr = 'Les petits saignements, c''est normal ? 🩸', body_fr = 'Pas de panique, il peut s''agir d''un saignement d''implantation. En cas de doute, consultez la rubrique Médecins.', title_hi = 'क्या स्पॉटिंग सामान्य है? 🩸', body_hi = 'घबराइए मत, यह इम्प्लांटेशन ब्लीडिंग हो सकती है। अगर शक हो, तो डॉक्टर सेक्शन देखिए।', title_id = 'Bercak darah itu normal? 🩸', body_id = 'Jangan takut, ini bisa jadi pendarahan implantasi. Jika ragu, lihat bagian Dokter.', title_ja = '少量の出血は普通？🩸', body_ja = '心配しないで、着床出血かもしれません。不安なときは「医師」セクションをご覧ください。', title_ko = '착상혈은 정상일까요? 🩸', body_ko = '걱정 마세요, 착상혈일 수 있어요. 의심스러우면 의사 섹션을 확인해 보세요.', title_nl = 'Is spotting normaal? 🩸', body_nl = 'Schrik niet, dit kan een innestelingsbloeding zijn. Twijfel je, kijk dan in het onderdeel Artsen.', title_pl = 'Czy plamienie jest normalne? 🩸', body_pl = 'Nie bój się, to może być krwawienie implantacyjne. Jeśli masz wątpliwości, zajrzyj do sekcji Lekarze.', title_pt = 'As pequenas perdas de sangue são normais? 🩸', body_pt = 'Não se assuste, pode ser uma hemorragia de implantação. Se tiver dúvidas, consulte a secção Médicos.', title_sv = 'Är småblödningar normala? 🩸', body_sv = 'Var inte rädd, det kan vara en implantationsblödning. Är du osäker, titta i avsnittet Läkare.', title_vi = 'Ra máu lấm tấm có bình thường không? 🩸', body_vi = 'Đừng lo, đây có thể là máu báo thai. Nếu còn băn khoăn, hãy xem mục Bác sĩ.', title_zh = '少量出血正常吗？🩸', body_zh = '别怕，这可能是着床出血。如有疑虑，请查看医生板块。' WHERE id = '45bd19ab-fec8-4848-87b2-8afc6fee3b1d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Eres una dama de hierro? 🥩', body_es = 'Tu volumen de sangre aumentará. Come carne roja o lentejas y dile stop a la anemia.', title_fr = 'Vous avez assez de fer ? 🥩', body_fr = 'Votre volume sanguin va augmenter. Mangez de la viande rouge ou des lentilles pour dire stop à l''anémie.', title_hi = 'आयरन लेडी हैं? 🥩', body_hi = 'आपके खून की मात्रा बढ़ेगी। रेड मीट या दाल खाकर एनीमिया को रोकिए।', title_id = 'Cukup zat besi? 🥩', body_id = 'Volume darah Anda akan bertambah. Makan daging merah atau lentil, dan katakan tidak pada anemia.', title_ja = '鉄分、とれていますか？🥩', body_ja = '血液量が増えていきます。赤身肉やレンズ豆を食べて、貧血を防ぎましょう。', title_ko = '철분 충분히 챙기고 있나요? 🥩', body_ko = '혈액량이 늘어날 거예요. 붉은 고기나 렌틸콩을 먹고 빈혈을 막아요.', title_nl = 'Ben jij een ijzersterke vrouw? 🥩', body_nl = 'Je bloedvolume neemt toe. Eet rood vlees of linzen en zeg nee tegen bloedarmoede.', title_pl = 'Żelazna dama? 🥩', body_pl = 'Objętość twojej krwi wzrośnie. Jedz czerwone mięso lub soczewicę i powiedz anemii stop.', title_pt = 'Está com o ferro em dia? 🥩', body_pt = 'O seu volume de sangue vai aumentar. Coma carne vermelha ou lentilhas e diga não à anemia.', title_sv = 'Är du en järnlady? 🥩', body_sv = 'Din blodvolym kommer att öka. Ät rött kött eller linser och säg stopp till blodbrist.', title_vi = 'Mẹ có đủ sắt không? 🥩', body_vi = 'Lượng máu của mẹ sẽ tăng lên. Hãy ăn thịt đỏ hoặc đậu lăng để nói không với thiếu máu.', title_zh = '铁补够了吗？🥩', body_zh = '你的血容量会增加。吃点红肉或扁豆，对贫血说不！' WHERE id = '549f62ec-94b7-42af-8ae8-87ad5504509a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Una espera emocionante... 🧘‍♀️', body_es = 'Se acerca la menstruación. Para reducir el estrés, escucha la sección Ruido blanco.', title_fr = 'Une attente pleine d''émotion... 🧘‍♀️', body_fr = 'Vos règles approchent. Pour réduire le stress, écoutez la rubrique Bruits blancs.', title_hi = 'रोमांचक इंतज़ार... 🧘‍♀️', body_hi = 'पीरियड्स का समय करीब है। तनाव कम करने के लिए व्हाइट नॉइज़ सेक्शन सुनिए।', title_id = 'Penantian yang mendebarkan... 🧘‍♀️', body_id = 'Waktu menstruasi semakin dekat. Untuk mengurangi stres, dengarkan bagian Suara Putih.', title_ja = 'ドキドキの待ち時間... 🧘‍♀️', body_ja = '生理予定日が近づいています。ストレスを減らすために、「ホワイトノイズ」セクションを聴いてみてください。', title_ko = '설레는 기다림... 🧘‍♀️', body_ko = '생리 예정일이 다가오고 있어요. 스트레스를 줄이려면 백색소음 섹션을 들어 보세요.', title_nl = 'Spannend afwachten... 🧘‍♀️', body_nl = 'Je menstruatie komt eraan. Luister naar het onderdeel Witte ruis om stress te verminderen.', title_pl = 'Pełne emocji oczekiwanie... 🧘‍♀️', body_pl = 'Zbliża się miesiączka. Posłuchaj sekcji Biały szum, by zmniejszyć stres.', title_pt = 'Uma espera emocionante... 🧘‍♀️', body_pt = 'A menstruação está a aproximar-se. Para reduzir o stress, ouça a secção Ruído Branco.', title_sv = 'Spänd väntan... 🧘‍♀️', body_sv = 'Mensen närmar sig. Lyssna på avsnittet Vitt brus för att minska stressen.', title_vi = 'Hồi hộp chờ đợi... 🧘‍♀️', body_vi = 'Kỳ kinh sắp đến. Hãy nghe mục Tiếng ồn trắng để giảm căng thẳng.', title_zh = '激动的等待……🧘‍♀️', body_zh = '月经时间快到了。听听白噪音板块，缓解一下压力吧。' WHERE id = '3829c3d1-13c3-4dcc-9b0a-b1c150f1dbf6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Has mirado el calendario? 🗓️', body_es = 'Si la menstruación se retrasa, ¿quizá es hora de hacer un test? ¡Comparte la buena noticia con nosotros!', title_fr = 'Vous avez regardé le calendrier ? 🗓️', body_fr = 'Vos règles sont en retard ? C''est peut-être le moment de faire un test. Partagez la bonne nouvelle avec nous !', title_hi = 'कैलेंडर देखा? 🗓️', body_hi = 'अगर पीरियड्स देर से हैं, तो शायद टेस्ट का समय है? खुशखबरी हमारे साथ बाँटिए!', title_id = 'Sudah cek kalender? 🗓️', body_id = 'Jika menstruasi terlambat, mungkin sudah waktunya tes? Bagikan kabar bahagianya kepada kami!', title_ja = 'カレンダーは見ましたか？🗓️', body_ja = '生理が遅れているなら、検査のタイミングかも？うれしいニュースをぜひ教えてください！', title_ko = '캘린더 확인하셨어요? 🗓️', body_ko = '생리가 늦어진다면 테스트해 볼 때일까요? 기쁜 소식을 저희와 나눠 주세요!', title_nl = 'Al in je kalender gekeken? 🗓️', body_nl = 'Is je menstruatie te laat? Misschien is het tijd voor een test? Deel het goede nieuws met ons!', title_pl = 'Zajrzałaś do kalendarza? 🗓️', body_pl = 'Jeśli miesiączka się spóźnia, może czas na test? Podziel się z nami dobrą nowiną!', title_pt = 'Já viu o calendário? 🗓️', body_pt = 'Se a menstruação está atrasada, talvez seja altura de fazer um teste? Partilhe a boa notícia connosco!', title_sv = 'Har du kollat kalendern? 🗓️', body_sv = 'Om mensen är sen kanske det är dags för ett test? Dela de glada nyheterna med oss!', title_vi = 'Bạn đã xem lịch chưa? 🗓️', body_vi = 'Nếu kỳ kinh bị trễ, có lẽ đã đến lúc thử thai? Hãy chia sẻ tin vui với chúng tôi nhé!', title_zh = '看过日历了吗？🗓️', body_zh = '如果月经推迟了，也许该测一测了？和我们分享好消息吧！' WHERE id = '648746b5-1de4-41ff-8fb8-976e17ef9c18' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Como una semilla de amapola 🌱', body_es = 'El bebé ya se está instalando en tu útero. Aunque es diminuto, su corazón empieza a formarse.', title_fr = 'Grand comme une graine de pavot 🌱', body_fr = 'Le bébé s''installe déjà dans votre ventre. Même s''il est tout petit, son cœur commence à se former.', title_hi = 'खसखस के दाने जितना 🌱', body_hi = 'बच्चा गर्भ में अपनी जगह बना रहा है। आकार छोटा है, पर उसका दिल बनना शुरू हो गया है।', title_id = 'Sebesar biji poppy 🌱', body_id = 'Bayi sudah menempati tempatnya di rahim. Meski ukurannya kecil, jantungnya mulai terbentuk.', title_ja = 'ケシの実くらい 🌱', body_ja = '赤ちゃんはもう子宮の中に居場所を見つけています。とても小さいけれど、心臓がつくられはじめています。', title_ko = '양귀비 씨앗만 해요 🌱', body_ko = '아기가 벌써 자궁 속에 자리를 잡고 있어요. 크기는 작아도 심장이 만들어지기 시작해요.', title_nl = 'Zo klein als een maanzaadje 🌱', body_nl = 'Je baby neemt al zijn plekje in je baarmoeder in. Het is nog piepklein, maar het hartje begint zich al te vormen.', title_pl = 'Jak ziarenko maku 🌱', body_pl = 'Dziecko zajmuje już swoje miejsce w twoim łonie. Choć jest maleńkie, jego serce zaczyna się kształtować.', title_pt = 'Como uma semente de papoila 🌱', body_pt = 'O bebé já está a instalar-se no útero. Apesar de ser pequenino, o coração começa a formar-se.', title_sv = 'Lika liten som ett vallmofrö 🌱', body_sv = 'Barnet hittar redan sin plats i livmodern. Även om det är litet börjar hjärtat att formas.', title_vi = 'Nhỏ như hạt anh túc 🌱', body_vi = 'Em bé đã tìm được chỗ trong bụng mẹ. Dù kích thước còn nhỏ, trái tim bé đang bắt đầu hình thành.', title_zh = '像罂粟籽一样大 🌱', body_zh = '宝宝已经在子宫里安家了。虽然个子很小，心脏已经开始形成。' WHERE id = '1466cb19-fd27-4f75-a79c-d709e1623239' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Como un ramillete de brócoli 🥦', body_es = 'Mi capa de grasa aumenta y mis brazos y piernas se ponen rellenitos.', title_fr = 'Grand comme un bouquet de brocoli 🥦', body_fr = 'Ma couche de graisse augmente, mes bras et mes jambes deviennent tout potelés.', title_hi = 'ब्रोकली के गुच्छे जितना 🥦', body_hi = 'मेरी चर्बी की परत बढ़ रही है, मेरे हाथ-पैर गोल-मटोल हो रहे हैं।', title_id = 'Seukuran kuntum brokoli 🥦', body_id = 'Lapisan lemakku bertambah, lengan dan kakiku makin montok.', title_ja = 'ブロッコリーの房くらい 🥦', body_ja = '脂肪が増えてきて、腕も脚もぷくぷくしてきたよ。', title_ko = '브로콜리 송이만 해요 🥦', body_ko = '이제 지방층이 늘어서 팔다리가 통통해지고 있어요.', title_nl = 'Zo groot als een broccoliroosje 🥦', body_nl = 'Mijn vetlaagje groeit en mijn armen en beentjes worden mollig.', title_pl = 'Jak różyczka brokułu 🥦', body_pl = 'Moja warstwa tłuszczu rośnie, rączki i nóżki robią się pulchne.', title_pt = 'Do tamanho de um raminho de brócolo 🥦', body_pt = 'A minha camada de gordura está a aumentar e os meus braços e pernas estão a ficar rechonchudos.', title_sv = 'Lika stor som en broccolibukett 🥦', body_sv = 'Nu ökar mitt fettlager och mina armar och ben blir knubbiga.', title_vi = 'To bằng một nhánh bông cải xanh 🥦', body_vi = 'Lớp mỡ của con đang dày lên, tay chân con ngày càng bụ bẫm.', title_zh = '像一小朵西兰花那么大 🥦', body_zh = '我的脂肪层在增加，胳膊和腿都变得肉嘟嘟的。' WHERE id = 'b119316e-3eaf-473d-92b5-cf9d282e6e05' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡El paquete de ADN está listo! 🧬', body_es = 'El color de ojos, el pelo y el sexo del bebé ya están codificados. ¿A quién crees que se parecerá?', title_fr = 'Le paquet ADN est prêt ! 🧬', body_fr = 'La couleur des yeux, les cheveux et le sexe du bébé sont déjà codés. À votre avis, à qui ressemblera-t-il ?', title_hi = 'DNA पैकेज तैयार! 🧬', body_hi = 'बच्चे की आँखों का रंग, बाल और लिंग पहले ही तय हो चुके हैं। आपको क्या लगता है, वह किस पर जाएगा?', title_id = 'Paket DNA sudah siap! 🧬', body_id = 'Warna mata, rambut, dan jenis kelamin bayi sudah tersandi. Menurut Anda, ia akan mirip siapa?', title_ja = 'DNAパッケージ完成！🧬', body_ja = '赤ちゃんの目の色、髪、性別はもう決まっています。誰に似ると思いますか？', title_ko = 'DNA 패키지 완성! 🧬', body_ko = '아기의 눈 색깔, 머리카락, 성별이 이미 정해졌어요. 누구를 닮을 것 같아요?', title_nl = 'Het DNA-pakketje is klaar! 🧬', body_nl = 'De oogkleur, het haar en het geslacht van je baby liggen al vast. Op wie denk je dat het gaat lijken?', title_pl = 'Pakiet DNA gotowy! 🧬', body_pl = 'Kolor oczu, włosy i płeć dziecka są już zakodowane. Jak myślisz, do kogo będzie podobne?', title_pt = 'O pacote de ADN está pronto! 🧬', body_pt = 'A cor dos olhos, o cabelo e o sexo do bebé já estão codificados. Com quem acha que se vai parecer?', title_sv = 'DNA-paketet är klart! 🧬', body_sv = 'Barnets ögonfärg, hår och kön är redan kodade. Vem tror du att barnet kommer att likna?', title_vi = 'Gói DNA đã sẵn sàng! 🧬', body_vi = 'Màu mắt, tóc và giới tính của em bé đã được mã hóa. Mẹ nghĩ bé sẽ giống ai?', title_zh = 'DNA包裹已准备好！🧬', body_zh = '宝宝的眼睛颜色、头发和性别都已经编码好了。你觉得会像谁呢？' WHERE id = 'ad5cb90c-5ee0-41f0-8e3f-90512dcf6636' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Fiesta de frutos rojos 🍓', body_es = '¿Frambuesas o fresas? Estas frutas llenas de antioxidantes reforzarán tu sistema inmunitario.', title_fr = 'Festival de baies 🍓', body_fr = 'Framboises ou fraises ? Riches en antioxydants, ces fruits vont renforcer votre immunité.', title_hi = 'बेरी की दावत 🍓', body_hi = 'रसभरी या स्ट्रॉबेरी? एंटीऑक्सीडेंट से भरे ये फल आपकी इम्युनिटी मज़बूत करेंगे।', title_id = 'Pesta buah beri 🍓', body_id = 'Raspberi atau stroberi? Buah-buahan kaya antioksidan ini akan memperkuat daya tahan tubuh Anda.', title_ja = 'ベリーの宴 🍓', body_ja = 'ラズベリーそれともイチゴ？抗酸化物質たっぷりのフルーツが免疫力を高めてくれます。', title_ko = '베리 파티 🍓', body_ko = '라즈베리, 아니면 딸기? 항산화 성분이 가득한 이 과일들이 면역력을 높여 줄 거예요.', title_nl = 'Een feest van bessen 🍓', body_nl = 'Frambozen of aardbeien? Deze vruchten zitten vol antioxidanten en versterken je weerstand.', title_pl = 'Owocowa uczta 🍓', body_pl = 'Maliny czy truskawki? Te owoce pełne przeciwutleniaczy wzmocnią twoją odporność.', title_pt = 'Festa de frutos vermelhos 🍓', body_pt = 'Framboesas ou morangos? Estas frutas cheias de antioxidantes vão reforçar a sua imunidade.', title_sv = 'Bärfest 🍓', body_sv = 'Hallon eller jordgubbar? De här antioxidantrika bären stärker ditt immunförsvar.', title_vi = 'Bữa tiệc quả mọng 🍓', body_vi = 'Mâm xôi hay dâu tây? Những loại quả giàu chất chống oxy hóa này sẽ tăng cường miễn dịch cho mẹ.', title_zh = '浆果盛宴 🍓', body_zh = '树莓还是草莓？这些富含抗氧化物的水果会增强你的免疫力。' WHERE id = '77a7a0c4-cbc4-4060-9824-f3657b9506c0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Hace falta hierro 🏗️', body_es = 'Estoy ocupado fabricando glóbulos rojos. Ayúdame: come ternera, espinacas o lentejas.', title_fr = 'Besoin de fer 🏗️', body_fr = 'Je suis occupé à fabriquer des globules rouges. Aidez-moi : mangez du bœuf, des épinards ou des lentilles.', title_hi = 'आयरन की ज़रूरत है 🏗️', body_hi = 'मैं लाल रक्त कोशिकाएँ बनाने में लगा हूँ। मेरी मदद कीजिए: बीफ़, पालक या दाल खाइए।', title_id = 'Butuh zat besi 🏗️', body_id = 'Aku sibuk membuat sel darah merah. Bantu aku: makan daging sapi, bayam, atau lentil.', title_ja = '鉄分が必要です 🏗️', body_ja = '赤血球をつくるのに忙しいの。牛肉、ほうれん草、レンズ豆を食べて、手伝ってね。', title_ko = '철분이 필요해요 🏗️', body_ko = '저는 적혈구를 만드느라 바빠요. 소고기, 시금치나 렌틸콩을 먹고 저를 도와주세요.', title_nl = 'IJzer nodig 🏗️', body_nl = 'Ik ben druk bezig met het maken van rode bloedcellen. Help me een handje: eet rundvlees, spinazie of linzen.', title_pl = 'Potrzebne żelazo 🏗️', body_pl = 'Tworzę teraz czerwone krwinki. Pomóż mi: jedz wołowinę, szpinak lub soczewicę.', title_pt = 'É preciso ferro 🏗️', body_pt = 'Estou ocupado a produzir glóbulos vermelhos. Ajude-me: coma carne de vaca, espinafres ou lentilhas.', title_sv = 'Järn behövs 🏗️', body_sv = 'Jag är upptagen med att tillverka röda blodkroppar. Hjälp mig: ät nötkött, spenat eller linser.', title_vi = 'Cần thêm sắt 🏗️', body_vi = 'Con đang bận tạo hồng cầu. Giúp con nhé: hãy ăn thịt bò, rau bina hoặc đậu lăng.', title_zh = '需要补铁啦 🏗️', body_zh = '我正忙着制造红细胞。帮帮我：吃点牛肉、菠菜或扁豆吧。' WHERE id = '5b28b973-6a08-480a-befc-a57bb7fa577b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Una revolución silenciosa 🤫', body_es = 'El óvulo fecundado se implanta en tu útero. Aunque no lo notes, está ocurriendo un proceso increíble.', title_fr = 'Une révolution silencieuse est en cours 🤫', body_fr = 'L''ovule fécondé s''installe dans votre utérus. Même si vous ne le sentez pas, un processus extraordinaire est en marche.', title_hi = 'एक चुपचाप क्रांति हो रही है 🤫', body_hi = 'निषेचित अंडा गर्भ में अपनी जगह बना रहा है। भले आपको महसूस न हो, एक शानदार प्रक्रिया चल रही है।', title_id = 'Revolusi diam-diam sedang terjadi 🤫', body_id = 'Sel telur yang telah dibuahi menempel di rahim Anda. Meski tidak terasa, proses luar biasa sedang berlangsung.', title_ja = '静かな革命が起きています 🤫', body_ja = '受精卵が子宮に着床します。気づかなくても、すばらしいプロセスが進んでいます。', title_ko = '조용한 혁명이 일어나고 있어요 🤫', body_ko = '수정란이 자궁에 자리를 잡고 있어요. 느끼지 못해도 놀라운 과정이 진행 중이에요.', title_nl = 'Er is een stille revolutie gaande 🤫', body_nl = 'Het bevruchte eitje nestelt zich in je baarmoeder. Ook al voel je het niet, er gebeurt iets geweldigs.', title_pl = 'Trwa cicha rewolucja 🤫', body_pl = 'Zapłodnione jajeczko zagnieżdża się w twojej macicy. Nawet jeśli tego nie czujesz, trwa niesamowity proces.', title_pt = 'Está a acontecer uma revolução silenciosa 🤫', body_pt = 'O óvulo fecundado está a instalar-se no útero. Mesmo sem sentir nada, está a decorrer um processo extraordinário.', title_sv = 'En tyst revolution pågår 🤫', body_sv = 'Det befruktade ägget fäster i livmodern. Även om du inte känner det pågår en fantastisk process.', title_vi = 'Một cuộc cách mạng thầm lặng đang diễn ra 🤫', body_vi = 'Trứng đã thụ tinh đang làm tổ trong tử cung. Dù bạn chưa cảm nhận được, một quá trình tuyệt vời đang diễn ra.', title_zh = '一场静悄悄的革命正在发生 🤫', body_zh = '受精卵正在子宫里着床。即使你感觉不到，了不起的过程正在进行。' WHERE id = 'c13826a2-03b2-4512-bcfb-084ebb8c2f13' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Calcio para los huesos 🥛', body_es = '¿Leche, yogur o queso? Hoy no te saltes los lácteos, son clave para el futuro esqueleto del bebé.', title_fr = 'Du calcium pour les os 🥛', body_fr = 'Lait, yaourt ou fromage ? Mangez absolument des produits laitiers aujourd''hui pour le futur squelette de bébé.', title_hi = 'हड्डियों के लिए कैल्शियम 🥛', body_hi = 'दूध, दही या पनीर? बच्चे के बनते कंकाल के लिए आज डेयरी ज़रूर खाइए।', title_id = 'Kalsium untuk tulang 🥛', body_id = 'Susu, yogurt, atau keju? Untuk kerangka bayi nanti, pastikan makan produk susu hari ini.', title_ja = '骨のためのカルシウム 🥛', body_ja = '牛乳、ヨーグルト、チーズ？赤ちゃんの未来の骨格のために、今日はぜひ乳製品をとりましょう。', title_ko = '뼈를 위한 칼슘 🥛', body_ko = '우유, 요거트, 아니면 치즈? 아기의 뼈대를 위해 오늘 유제품을 꼭 드세요.', title_nl = 'Calcium voor de botten 🥛', body_nl = 'Melk, yoghurt of kaas? Eet vandaag zeker zuivel voor het toekomstige skelet van je baby.', title_pl = 'Wapń na kości 🥛', body_pl = 'Mleko, jogurt czy ser? Zjedz dziś koniecznie nabiał dla przyszłego szkieletu dziecka.', title_pt = 'Cálcio para os ossos 🥛', body_pt = 'Leite, iogurte ou queijo? Coma hoje sem falta lacticínios para o futuro esqueleto do bebé.', title_sv = 'Kalcium för skelettet 🥛', body_sv = 'Mjölk, yoghurt eller ost? Ät mejeriprodukter i dag för barnets framtida skelett.', title_vi = 'Canxi cho xương 🥛', body_vi = 'Sữa, sữa chua hay phô mai? Hôm nay nhớ ăn chế phẩm từ sữa cho bộ xương tương lai của bé nhé.', title_zh = '为骨骼补钙 🥛', body_zh = '牛奶、酸奶还是奶酪？为了宝宝未来的骨骼，今天一定要吃些奶制品。' WHERE id = 'fb1313b6-50fc-44e5-80b6-0c243b450b62' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Sin fuerzas? Hay un motivo 🥱', body_es = 'La progesterona está aumentando. Si la cama te llama, no le digas que no, ¡descansa!', title_fr = 'Fatiguée ? Il y a une raison 🥱', body_fr = 'L''hormone progestérone augmente. Si votre lit vous appelle, ne lui dites pas non, reposez-vous !', title_hi = 'थकान है? इसकी वजह है 🥱', body_hi = 'प्रोजेस्टेरोन हार्मोन बढ़ रहा है। अगर बिस्तर बुला रहा है, तो मना मत कीजिए, आराम कीजिए!', title_id = 'Lemas? Ada alasannya 🥱', body_id = 'Hormon progesteron meningkat. Jika kasur memanggil, jangan menolak, istirahatlah!', title_ja = 'だるい？それには理由があります 🥱', body_ja = 'プロゲステロンというホルモンが増えています。ベッドに呼ばれたら断らずに、休んでくださいね！', title_ko = '기운이 없나요? 이유가 있어요 🥱', body_ko = '프로게스테론 호르몬이 늘고 있어요. 침대가 부르면 거절하지 말고 쉬세요!', title_nl = 'Uitgeput? Daar is een reden voor 🥱', body_nl = 'Het hormoon progesteron stijgt. Roept je bed je? Zeg geen nee en rust uit!', title_pl = 'Brak sił? Jest powód 🥱', body_pl = 'Rośnie poziom progesteronu. Jeśli łóżko cię woła, nie odmawiaj, odpocznij!', title_pt = 'Sem forças? Há uma razão 🥱', body_pt = 'A hormona progesterona está a aumentar. Se a cama a chama, não diga que não, descanse!', title_sv = 'Orkeslös? Det finns en anledning 🥱', body_sv = 'Hormonet progesteron ökar. Om sängen lockar, säg inte nej, vila!', title_vi = 'Mệt mỏi? Có lý do đấy 🥱', body_vi = 'Hormone progesterone đang tăng. Nếu chiếc giường gọi, đừng từ chối, hãy nghỉ ngơi nhé!', title_zh = '觉得乏力？这是有原因的 🥱', body_zh = '孕酮在升高。如果床在召唤你，别拒绝，好好休息！' WHERE id = '33a29a12-915d-4926-a3e0-77d719ad233b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'El milagro del agua con limón 🍋', body_es = 'Reduce las náuseas y limpia el cuerpo. La falta de agua puede causar dolor de cabeza.', title_fr = 'Le miracle de l''eau citronnée 🍋', body_fr = 'Elle atténue les nausées et purifie le corps. Le manque d''eau peut provoquer des maux de tête.', title_hi = 'नींबू पानी का कमाल 🍋', body_hi = 'यह जी मिचलाना कम करता है, शरीर को साफ़ करता है। पानी की कमी से सिरदर्द हो सकता है।', title_id = 'Keajaiban air lemon 🍋', body_id = 'Mengurangi mual dan membersihkan tubuh. Kurang minum bisa menyebabkan sakit kepala.', title_ja = 'レモン水の奇跡 🍋', body_ja = '吐き気をやわらげ、体をすっきりさせます。水分不足は頭痛の原因になることも。', title_ko = '레몬물의 기적 🍋', body_ko = '메스꺼움을 줄이고 몸을 깨끗하게 해 줘요. 수분이 부족하면 두통이 생길 수 있어요.', title_nl = 'Het wonder van water met citroen 🍋', body_nl = 'Het vermindert misselijkheid en reinigt je lichaam. Te weinig drinken kan hoofdpijn geven.', title_pl = 'Cud wody z cytryną 🍋', body_pl = 'Zmniejsza mdłości i oczyszcza organizm. Odwodnienie może wywołać ból głowy.', title_pt = 'O milagre da água com limão 🍋', body_pt = 'Reduz as náuseas e limpa o corpo. A desidratação pode causar dores de cabeça.', title_sv = 'Citronvattnets mirakel 🍋', body_sv = 'Det minskar illamåendet och renar kroppen. Vätskebrist kan ge huvudvärk.', title_vi = 'Phép màu của nước chanh 🍋', body_vi = 'Giúp giảm buồn nôn, thanh lọc cơ thể. Thiếu nước có thể gây đau đầu.', title_zh = '柠檬水的魔力 🍋', body_zh = '它能缓解恶心，帮身体排毒。缺水可能会引起头痛。' WHERE id = 'e7c343f8-73b3-41d3-a74d-ee9ee11dc752' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Se te agota la batería? 🔋', body_es = 'Tu energía puede agotarse rápido. Una siesta corta por la tarde te sentará muy bien.', title_fr = 'Batterie à plat ? 🔋', body_fr = 'Votre énergie peut s''épuiser vite. Une petite sieste l''après-midi vous fera le plus grand bien.', title_hi = 'बैटरी खत्म हो रही है? 🔋', body_hi = 'आपकी ऊर्जा जल्दी खत्म हो सकती है। दोपहर में छोटी सी झपकी आपको बहुत अच्छा महसूस कराएगी।', title_id = 'Baterai hampir habis? 🔋', body_id = 'Energi Anda bisa cepat habis. Tidur siang sebentar akan sangat membantu.', title_ja = '電池切れ寸前？🔋', body_ja = 'エネルギーがすぐに切れてしまうかもしれません。お昼に少しお昼寝すると、とても元気になれますよ。', title_ko = '배터리가 방전됐나요? 🔋', body_ko = '에너지가 금방 바닥날 수 있어요. 오후에 짧은 낮잠이 큰 도움이 될 거예요.', title_nl = 'Is je batterij leeg? 🔋', body_nl = 'Je energie kan snel opraken. Een kort middagdutje zal je heel goed doen.', title_pl = 'Bateria się wyczerpuje? 🔋', body_pl = 'Energia może szybko się kończyć. Krótka drzemka w południe dobrze ci zrobi.', title_pt = 'Bateria a acabar? 🔋', body_pt = 'A energia pode esgotar-se depressa. Uma pequena sesta à tarde vai fazer-lhe muito bem.', title_sv = 'Är batteriet slut? 🔋', body_sv = 'Energin kan ta slut snabbt. En kort tupplur på eftermiddagen kommer att göra dig gott.', title_vi = 'Hết pin rồi à? 🔋', body_vi = 'Năng lượng của mẹ có thể cạn nhanh. Một giấc ngủ ngắn buổi trưa sẽ rất tốt cho mẹ.', title_zh = '电量快耗尽了？🔋', body_zh = '你的精力可能很快就会用完。午后小睡一会儿会让你感觉好很多。' WHERE id = '06ad8151-63c5-48be-b794-51e51402550d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Necesito una piscina! 🏊‍♀️', body_es = 'Tú creas el agua en la que nado (el líquido amniótico), mamá. Entra en el Registro de agua. ¿Te has bebido un vaso de agua? ✅', title_fr = 'J''ai besoin d''une piscine ! 🏊‍♀️', body_fr = 'C''est vous qui créez l''eau dans laquelle je nage (le liquide amniotique), Maman. Ouvrez le Suivi d''hydratation. Avez-vous bu un verre d''eau ? ✅', title_hi = 'मुझे एक पूल चाहिए! 🏊‍♀️', body_hi = 'जिस पानी (एम्नियोटिक द्रव) में मैं तैरूँगा, उसे आप बनाती हैं, माँ। वॉटर ट्रैकर खोलिए। क्या आपने एक गिलास पानी पिया? ✅', title_id = 'Aku butuh kolam renang! 🏊‍♀️', body_id = 'Air tempatku berenang (cairan ketuban) Anda yang membuatnya, Bunda. Buka Pelacak Air. Sudah minum segelas air? ✅', title_ja = 'プールが必要なの！🏊‍♀️', body_ja = 'わたしが泳ぐお水（羊水）は、ママがつくってくれているの。「水分トラッカー」を開いてね。お水を1杯飲んだ？✅', title_ko = '저는 수영장이 필요해요! 🏊‍♀️', body_ko = '제가 헤엄치는 물(양수)은 엄마가 만들어요. 물 기록을 열어 보세요. 물 한 잔 드셨어요? ✅', title_nl = 'Ik heb een zwembad nodig! 🏊‍♀️', body_nl = 'Jij maakt het water waarin ik zwem (het vruchtwater), mama. Open je Waterteller. Heb je een glas water gedronken? ✅', title_pl = 'Potrzebuję basenu! 🏊‍♀️', body_pl = 'To ty tworzysz wodę, w której pływam (płyn owodniowy), Mamo. Zajrzyj do Licznika wody. Wypiłaś szklankę wody? ✅', title_pt = 'Preciso de uma piscina! 🏊‍♀️', body_pt = 'É a Mamã que cria a água onde eu nado (o líquido amniótico). Abra o Registo de Água. Já bebeu um copo de água? ✅', title_sv = 'Jag behöver en pool! 🏊‍♀️', body_sv = 'Det är du som skapar vattnet jag simmar i (fostervattnet), mamma. Öppna Vattenspåraren. Har du druckit ett glas vatten? ✅', title_vi = 'Con cần một bể bơi! 🏊‍♀️', body_vi = 'Mẹ ơi, nước con bơi (nước ối) là do mẹ tạo ra đấy. Vào Theo dõi uống nước nhé. Mẹ đã uống một cốc nước chưa? ✅', title_zh = '我需要一个泳池！🏊‍♀️', body_zh = '妈妈，我游泳的水（羊水）是你制造的。打开饮水记录，喝一杯水了吗？✅' WHERE id = 'ae668457-885f-4308-8392-39228dd44060' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Montaña rusa emocional 🎢', body_es = 'Reír y luego llorar... Las hormonas no te están volviendo loca, solo están trabajando.', title_fr = 'Montagnes russes émotionnelles 🎢', body_fr = 'Rire, puis pleurer... Les hormones ne vous rendent pas folle, elles travaillent, c''est tout.', title_hi = 'भावनाओं का झूला 🎢', body_hi = 'हँसना, फिर रोना... हार्मोन आपको पागल नहीं कर रहे, वे बस अपना काम कर रहे हैं।', title_id = 'Komidi putar emosi 🎢', body_id = 'Tertawa, lalu menangis... Hormon tidak membuat Anda gila, mereka hanya sedang bekerja.', title_ja = '感情のメリーゴーランド 🎢', body_ja = '笑ったと思ったら泣いたり...ホルモンのせいでおかしくなったわけではなく、ホルモンががんばって働いているだけです。', title_ko = '감정의 회전목마 🎢', body_ko = '웃다가 울다가... 호르몬 때문에 이상해진 게 아니라, 호르몬이 열심히 일하는 중이에요.', title_nl = 'Emotionele achtbaan 🎢', body_nl = 'Lachen, en dan weer huilen... Je hormonen maken je niet gek, ze zijn gewoon hard aan het werk.', title_pl = 'Emocjonalna karuzela 🎢', body_pl = 'Śmiech, a potem płacz... Hormony nie doprowadzają cię do szaleństwa, po prostu ciężko pracują.', title_pt = 'Carrossel emocional 🎢', body_pt = 'Rir e depois chorar... As hormonas não a estão a enlouquecer, estão apenas a trabalhar.', title_sv = 'Känslomässig karusell 🎢', body_sv = 'Skratta, sedan gråta... Hormonerna har inte gjort dig galen, de jobbar bara för fullt.', title_vi = 'Vòng quay cảm xúc 🎢', body_vi = 'Vừa cười xong lại khóc... Không phải hormone làm mẹ phát điên đâu, chúng chỉ đang làm việc thôi.', title_zh = '情绪过山车 🎢', body_zh = '一会儿笑，一会儿哭……不是你变奇怪了，是激素在忙着工作。' WHERE id = 'd2d789ff-23ab-49d2-829b-2a59a12e57ec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Estás sensible a los olores? 👃', body_es = 'No te obligues a comer lo que no te apetece. Mira alternativas en la sección Nutrición.', title_fr = 'Sensible aux odeurs ? 👃', body_fr = 'Ne vous forcez pas à manger ce que vous n''aimez pas. Trouvez des alternatives dans la rubrique Nutrition.', title_hi = 'गंध के प्रति संवेदनशील हैं? 👃', body_hi = 'जो खाना पसंद नहीं, उसे ज़बरदस्ती मत खाइए। विकल्पों के लिए पोषण सेक्शन देखिए।', title_id = 'Sensitif terhadap bau? 👃', body_id = 'Jangan memaksa makan makanan yang tidak Anda sukai. Lihat bagian Nutrisi untuk alternatifnya.', title_ja = 'においに敏感になっていますか？👃', body_ja = '苦手な食べ物を無理に食べなくて大丈夫。代わりの食べ物は「栄養」セクションをご覧ください。', title_ko = '냄새에 예민해졌나요? 👃', body_ko = '싫은 음식을 억지로 먹지 마세요. 대안은 영양 섹션에서 찾아보세요.', title_nl = 'Gevoelig voor geuren? 👃', body_nl = 'Dwing jezelf niet om eten te eten dat je niet lust. Kijk in het onderdeel Voeding voor alternatieven.', title_pl = 'Jesteś wrażliwa na zapachy? 👃', body_pl = 'Nie zmuszaj się do jedzenia tego, czego nie lubisz. Alternatywy znajdziesz w sekcji Odżywianie.', title_pt = 'Sensível aos cheiros? 👃', body_pt = 'Não se obrigue a comer o que não lhe apetece. Veja alternativas na secção Nutrição.', title_sv = 'Är du känslig för dofter? 👃', body_sv = 'Tvinga inte i dig mat du inte tycker om. Titta i Kost-avsnittet efter alternativ.', title_vi = 'Nhạy cảm với mùi? 👃', body_vi = 'Đừng ép mình ăn những món không thích. Xem mục Dinh dưỡng để tìm món thay thế nhé.', title_zh = '对气味很敏感？👃', body_zh = '不喜欢的食物别勉强吃。去营养板块看看替代选择吧。' WHERE id = 'b80da43f-4fa0-465f-a1f5-d415c59577d5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡El cerebro se desarrolla! 🧠', body_es = 'El tubo neural se está cerrando. No dejes el ácido fólico, ¡se están poniendo las bases de un futuro genio!', title_fr = 'Le cerveau se développe ! 🧠', body_fr = 'Le tube neural se ferme. N''arrêtez pas l''acide folique, on pose les bases d''un futur génie !', title_hi = 'दिमाग विकसित हो रहा है! 🧠', body_hi = 'न्यूरल ट्यूब बंद हो रही है। फ़ोलिक एसिड लेना बंद मत कीजिए, भविष्य के जीनियस की नींव रखी जा रही है!', title_id = 'Otak sedang berkembang! 🧠', body_id = 'Tabung saraf sedang menutup. Jangan berhenti minum asam folat, fondasi si jenius masa depan sedang dibangun!', title_ja = '脳が発達中！🧠', body_ja = '神経管が閉じようとしています。葉酸はやめずに続けて。未来の天才の土台がつくられています！', title_ko = '뇌가 자라고 있어요! 🧠', body_ko = '신경관이 닫히고 있어요. 엽산 복용을 멈추지 마세요, 미래 천재의 기초가 다져지고 있어요!', title_nl = 'De hersenen ontwikkelen zich! 🧠', body_nl = 'De neurale buis sluit zich. Stop niet met foliumzuur, de basis voor een toekomstig genie wordt gelegd!', title_pl = 'Mózg się rozwija! 🧠', body_pl = 'Cewa nerwowa się zamyka. Nie przerywaj przyjmowania kwasu foliowego, powstają fundamenty przyszłego geniusza!', title_pt = 'O cérebro está a desenvolver-se! 🧠', body_pt = 'O tubo neural está a fechar. Não pare de tomar o ácido fólico: estão a ser lançadas as bases de um futuro génio!', title_sv = 'Hjärnan utvecklas! 🧠', body_sv = 'Neuralröret sluter sig. Sluta inte ta folsyra, grunden för ett framtida geni läggs nu!', title_vi = 'Não đang phát triển! 🧠', body_vi = 'Ống thần kinh đang khép lại. Đừng ngừng uống axit folic, nền móng cho thiên tài tương lai đang được đặt!', title_zh = '大脑在发育！🧠', body_zh = '神经管正在闭合。别停用叶酸，未来小天才的基础正在打下！' WHERE id = 'e7025bb0-45af-4595-8380-1e2af3adb2b9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Té de jengibre al rescate! 🍵', body_es = '¿Las náuseas no te dejan? El jengibre calma el estómago. Hay recetas en la sección Nutrición.', title_fr = 'Le gingembre à la rescousse ! 🍵', body_fr = 'Les nausées ne vous lâchent pas ? Le gingembre apaise l''estomac. Vous trouverez des recettes dans la rubrique Nutrition.', title_hi = 'अदरक की चाय मदद को! 🍵', body_hi = 'जी मिचलाना पीछा नहीं छोड़ रहा? अदरक पेट को शांत करता है। पोषण सेक्शन में रेसिपी हैं।', title_id = 'Teh jahe datang membantu! 🍵', body_id = 'Mual tak kunjung reda? Jahe menenangkan perut. Ada resepnya di bagian Nutrisi.', title_ja = 'しょうが茶でひと休み！🍵', body_ja = '吐き気が続いていますか？しょうがは胃を落ち着かせてくれます。「栄養」セクションにレシピがあります。', title_ko = '생강차가 도와줄게요! 🍵', body_ko = '메스꺼움이 계속되나요? 생강은 위를 진정시켜 줘요. 영양 섹션에 레시피가 있어요.', title_nl = 'Gemberthee schiet te hulp! 🍵', body_nl = 'Blijft de misselijkheid? Gember kalmeert je maag. In het onderdeel Voeding vind je recepten.', title_pl = 'Herbata imbirowa na ratunek! 🍵', body_pl = 'Mdłości nie odpuszczają? Imbir uspokaja żołądek. Przepisy znajdziesz w sekcji Odżywianie.', title_pt = 'Chá de gengibre ao resgate! 🍵', body_pt = 'As náuseas não dão tréguas? O gengibre acalma o estômago. Há receitas na secção Nutrição.', title_sv = 'Ingefärste till undsättning! 🍵', body_sv = 'Släpper inte illamåendet? Ingefära lugnar magen. Det finns recept i Kost-avsnittet.', title_vi = 'Trà gừng đến cứu nguy! 🍵', body_vi = 'Cơn buồn nôn vẫn chưa buông tha? Gừng giúp dịu dạ dày. Mục Dinh dưỡng có công thức cho mẹ.', title_zh = '姜茶来帮忙！🍵', body_zh = '恶心还是缠着你？生姜能安抚肠胃。营养板块里有食谱。' WHERE id = '1af4d57c-0075-4fda-8ae2-57d6f0df3dd7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿El cansancio está en su punto máximo? 😴', body_es = 'Tu cuerpo trabaja como una fábrica de energía. ¡Una siesta corta por la tarde es tu derecho de mamá!', title_fr = 'Fatigue au maximum ? 😴', body_fr = 'Votre corps fonctionne comme une usine à énergie. Une petite sieste l''après-midi, c''est votre droit de maman !', title_hi = 'थकान चरम पर है? 😴', body_hi = 'आपका शरीर ऊर्जा की फ़ैक्ट्री की तरह काम कर रहा है। दोपहर की छोटी सी झपकी माँ बनने वाली का हक़ है!', title_id = 'Lelah mencapai puncaknya? 😴', body_id = 'Tubuh Anda bekerja seperti pabrik energi. Tidur siang sebentar adalah hak Anda sebagai calon ibu!', title_ja = '疲れがピーク？😴', body_ja = '体はエネルギー工場のようにフル稼働中。お昼の短い仮眠は、ママの権利です！', title_ko = '피로가 절정인가요? 😴', body_ko = '몸이 에너지 공장처럼 일하고 있어요. 오후의 짧은 낮잠은 엄마의 권리예요!', title_nl = 'Vermoeidheid op z’n hoogtepunt? 😴', body_nl = 'Je lichaam werkt als een energiecentrale. Een kort middagdutje is jouw recht als aanstaande mama!', title_pl = 'Zmęczenie na szczycie? 😴', body_pl = 'Twoje ciało pracuje jak fabryka energii. Krótka popołudniowa drzemka to twoje prawo jako mamy!', title_pt = 'Cansaço no máximo? 😴', body_pt = 'O seu corpo trabalha como uma fábrica de energia. Uma pequena sesta à tarde é um direito de mãe!', title_sv = 'Är tröttheten på topp? 😴', body_sv = 'Din kropp jobbar som en energifabrik. En kort tupplur på eftermiddagen är din rättighet som mamma!', title_vi = 'Mệt mỏi đạt đỉnh? 😴', body_vi = 'Cơ thể mẹ đang hoạt động như một nhà máy năng lượng. Ngủ trưa một chút là quyền của mẹ đấy!', title_zh = '疲惫达到顶峰了？😴', body_zh = '你的身体像一座能量工厂在运转。午后小睡是准妈妈的权利！' WHERE id = 'ee6d0fe8-1439-46ca-a99d-71bece3db7ff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Un dulce guisante 🟢', body_es = 'Unos 6 mm. Sus brazos y piernas empiezan a brotar como pequeños capullos. ¡Un pequeño nadador!', title_fr = 'Un adorable petit pois 🟢', body_fr = 'Environ 6 mm. Ses bras et ses jambes commencent à pousser comme de petits bourgeons. Petit nageur !', title_hi = 'एक प्यारा सा मटर का दाना 🟢', body_hi = 'लगभग 6 mm। हाथ और पैर छोटी कलियों की तरह निकलने लगे हैं। नन्हा तैराक!', title_id = 'Sebutir kacang polong yang manis 🟢', body_id = 'Sekitar 6 mm. Lengan dan kakinya mulai muncul seperti tunas kecil. Si perenang mungil!', title_ja = 'かわいいえんどう豆 🟢', body_ja = '約6 mm。腕や脚が小さなつぼみのように出てきています。小さなスイマーです！', title_ko = '달콤한 완두콩 한 알 🟢', body_ko = '약 6mm예요. 팔다리가 작은 새싹처럼 돋아나기 시작해요. 작은 수영 선수예요!', title_nl = 'Een lief erwtje 🟢', body_nl = 'Ongeveer 6 mm. Mijn armpjes en beentjes komen als kleine knopjes tevoorschijn. Een kleine zwemmer!', title_pl = 'Słodki groszek 🟢', body_pl = 'Około 6 mm. Rączki i nóżki zaczynają wyrastać jak małe pączki. Mały pływak!', title_pt = 'Uma doce ervilha 🟢', body_pt = 'Cerca de 6 mm. Os braços e as pernas começam a aparecer como pequenos rebentos. Um pequeno nadador!', title_sv = 'En söt liten ärta 🟢', body_sv = 'Ungefär 6 mm. Armar och ben börjar växa fram som små knoppar. En liten simmare!', title_vi = 'Một hạt đậu Hà Lan xinh xắn 🟢', body_vi = 'Khoảng 6 mm. Tay chân con bắt đầu nhú ra như những chồi non. Một vận động viên bơi lội tí hon!', title_zh = '一颗可爱的小豌豆 🟢', body_zh = '大约6 mm。胳膊和腿像小芽一样开始冒出来了。小小游泳健将！' WHERE id = '6a854983-edba-4550-9294-f82d79978af6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Como un coche de carreras! 🏎️', body_es = 'Su corazón late 100-160 veces por minuto. ¡El doble de rápido que el tuyo! Este sonido te parecerá música.', title_fr = 'Comme une voiture de course ! 🏎️', body_fr = 'Son cœur bat 100 à 160 fois par minute, deux fois plus vite que le vôtre ! Ce son sera une musique à vos oreilles.', title_hi = 'रेसिंग कार की तरह! 🏎️', body_hi = 'इसका दिल एक मिनट में 100-160 बार धड़कता है। आपके दिल से दोगुना तेज़! यह आवाज़ आपको संगीत जैसी लगेगी।', title_id = 'Seperti mobil balap! 🏎️', body_id = 'Jantungnya berdetak 100-160 kali per menit. Dua kali lebih cepat dari jantung Anda! Suara ini akan terdengar seperti musik bagi Anda.', title_ja = 'レーシングカーみたい！🏎️', body_ja = '心臓は1分間に100-160回も脈打っています。ママの2倍の速さ！この音は音楽のように聞こえるはずです。', title_ko = '경주용 자동차처럼! 🏎️', body_ko = '심장이 1분에 100-160번 뛰어요. 엄마보다 두 배나 빨라요! 이 소리는 음악처럼 들릴 거예요.', title_nl = 'Als een raceauto! 🏎️', body_nl = 'Het hartje klopt 100-160 keer per minuut. Twee keer zo snel als het jouwe! Dit geluid zal als muziek in je oren klinken.', title_pl = 'Jak samochód wyścigowy! 🏎️', body_pl = 'Jego serce bije 100-160 razy na minutę. Dwa razy szybciej niż twoje! Ten dźwięk będzie dla ciebie jak muzyka.', title_pt = 'Como um carro de corrida! 🏎️', body_pt = 'O coração bate 100-160 vezes por minuto. O dobro da velocidade do seu! Este som vai soar-lhe a música.', title_sv = 'Som en racerbil! 🏎️', body_sv = 'Hjärtat slår 100-160 gånger i minuten. Dubbelt så snabbt som ditt! Det ljudet kommer att låta som musik för dig.', title_vi = 'Như xe đua vậy! 🏎️', body_vi = 'Tim bé đập 100-160 lần mỗi phút. Nhanh gấp đôi tim mẹ! Âm thanh này sẽ như bản nhạc với mẹ.', title_zh = '像赛车一样快！🏎️', body_zh = '宝宝的心脏每分钟跳100-160次，比你的快一倍！这声音会像音乐一样动听。' WHERE id = '68d813b6-47ae-4b82-ac7f-506d3dacf437' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Hora de moverse 🧘‍♀️', body_es = '¿Te apetece moverte? ¿Vemos qué hay para ti en la sección Ejercicios?', title_fr = 'L''heure de bouger 🧘‍♀️', body_fr = 'Envie de bouger ? Voyons ce qui vous convient dans la rubrique Exercices.', title_hi = 'चलने-फिरने का समय 🧘‍♀️', body_hi = 'कुछ हलचल करना चाहती हैं? चलिए देखते हैं, एक्सरसाइज़ सेक्शन में आपके लिए क्या है?', title_id = 'Waktunya bergerak 🧘‍♀️', body_id = 'Ingin bergerak? Yuk, lihat apa saja yang cocok untuk Anda di bagian Latihan?', title_ja = '体を動かす時間 🧘‍♀️', body_ja = '体を動かしたい気分ですか？「エクササイズ」セクションでぴったりのものを見てみましょう。', title_ko = '움직일 시간 🧘‍♀️', body_ko = '몸을 움직이고 싶으세요? 운동 섹션에 나에게 맞는 게 뭐가 있는지 볼까요?', title_nl = 'Tijd om te bewegen 🧘‍♀️', body_nl = 'Zin om te bewegen? Zullen we kijken wat er in het onderdeel Oefeningen bij je past?', title_pl = 'Czas na ruch 🧘‍♀️', body_pl = 'Masz ochotę się poruszać? Zobaczmy, co dla ciebie jest w sekcji Ćwiczenia.', title_pt = 'Hora de mexer o corpo 🧘‍♀️', body_pt = 'Apetece-lhe mexer-se? Vamos ver o que há de adequado para si na secção Exercícios?', title_sv = 'Dags att röra på sig 🧘‍♀️', body_sv = 'Vill du röra på dig? Ska vi kolla vad som passar dig i avsnittet Träning?', title_vi = 'Đến giờ vận động 🧘‍♀️', body_vi = 'Mẹ muốn vận động? Cùng xem mục Bài tập có gì phù hợp với mẹ nhé?', title_zh = '该动一动啦 🧘‍♀️', body_zh = '想活动一下吗？来看看运动板块里有哪些适合你的吧？' WHERE id = '20943f1e-d4df-412e-9bff-ad93646d91c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Evita el estreñimiento 🏃‍♀️', body_es = 'En lugar de medicamentos, bebe mucha agua y come ciruelas pasas y kiwi.', title_fr = 'Évitez la constipation 🏃‍♀️', body_fr = 'Plutôt que des médicaments, buvez beaucoup d''eau et mangez des pruneaux et des kiwis.', title_hi = 'कब्ज़ से बचिए 🏃‍♀️', body_hi = 'दवा की जगह खूब पानी पीजिए, सूखा आलूबुखारा और कीवी खाइए।', title_id = 'Hindari sembelit 🏃‍♀️', body_id = 'Alih-alih obat, minum banyak air serta makan buah prune dan kiwi.', title_ja = '便秘を防ごう 🏃‍♀️', body_ja = '薬の代わりに、お水をたっぷり飲んで、プルーンやキウイを食べましょう。', title_ko = '변비를 피해요 🏃‍♀️', body_ko = '약 대신 물을 많이 마시고 말린 자두와 키위를 드세요.', title_nl = 'Voorkom verstopping 🏃‍♀️', body_nl = 'Drink in plaats van medicijnen veel water en eet gedroogde pruimen en kiwi.', title_pl = 'Uciekaj przed zaparciami 🏃‍♀️', body_pl = 'Zamiast leków pij dużo wody, jedz suszone śliwki i kiwi.', title_pt = 'Fuja da obstipação 🏃‍♀️', body_pt = 'Em vez de medicamentos, beba muita água e coma ameixas secas e kiwi.', title_sv = 'Undvik förstoppning 🏃‍♀️', body_sv = 'I stället för läkemedel: drick mycket vatten och ät katrinplommon och kiwi.', title_vi = 'Tránh táo bón 🏃‍♀️', body_vi = 'Thay vì dùng thuốc, hãy uống nhiều nước, ăn mận khô và kiwi.', title_zh = '远离便秘 🏃‍♀️', body_zh = '不用急着吃药，多喝水，吃些西梅干和猕猴桃。' WHERE id = '2781a73f-51c3-4a91-8e1e-4ee828c3f885' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Que no te baje el azúcar! 📉', body_es = 'Con el estómago vacío las náuseas aumentan. Lleva siempre galletas saladas o fruta deshidratada en el bolso.', title_fr = 'Gare à la baisse de glycémie ! 📉', body_fr = 'Les nausées augmentent quand l''estomac est vide. Gardez toujours des crackers ou des fruits secs dans votre sac.', title_hi = 'ब्लड शुगर गिरने न दें! 📉', body_hi = 'खाली पेट रहने पर जी ज़्यादा मिचलाता है। बैग में हमेशा क्रैकर या सूखे मेवे रखिए।', title_id = 'Jangan biarkan gula darah turun! 📉', body_id = 'Saat perut kosong, mual makin parah. Selalu bawa biskuit atau buah kering di tas Anda.', title_ja = '血糖値を下げないで！📉', body_ja = '空腹になると吐き気が強くなります。バッグにはいつもクラッカーやドライフルーツを入れておきましょう。', title_ko = '혈당이 떨어지지 않게! 📉', body_ko = '공복일 때 메스꺼움이 심해져요. 가방에 항상 크래커나 말린 과일을 넣어 두세요.', title_nl = 'Laat je bloedsuiker niet zakken! 📉', body_nl = 'Met een lege maag wordt misselijkheid erger. Heb altijd crackers of gedroogd fruit in je tas.', title_pl = 'Nie pozwól spaść cukrowi! 📉', body_pl = 'Gdy żołądek jest pusty, mdłości się nasilają. Zawsze miej w torebce krakersy lub suszone owoce.', title_pt = 'Não deixe o açúcar no sangue descer! 📉', body_pt = 'Com o estômago vazio, as náuseas aumentam. Tenha sempre bolachas ou fruta seca na mala.', title_sv = 'Låt inte blodsockret sjunka! 📉', body_sv = 'Illamåendet blir värre när magen är tom. Ha alltid kex eller torkad frukt i väskan.', title_vi = 'Đừng để đường huyết tụt! 📉', body_vi = 'Bụng đói sẽ dễ buồn nôn hơn. Luôn để sẵn bánh quy hoặc trái cây sấy trong túi nhé.', title_zh = '别让血糖掉下来！📉', body_zh = '空腹时恶心会加重。包里随时备些饼干或果干吧。' WHERE id = '1eea9abf-8e8e-49f8-aca7-b449e73948c5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Maratón de idas al baño? 🚻', body_es = 'Ir a menudo es normal. Tus riñones trabajan más. Pero no bebas menos agua, ¡bebe más!', title_fr = 'Marathon aux toilettes ? 🚻', body_fr = 'Y aller souvent, c''est normal : vos reins travaillent davantage. Mais ne buvez pas moins, buvez plus !', title_hi = 'टॉयलेट मैराथन? 🚻', body_hi = 'बार-बार जाना सामान्य है। आपकी किडनी ज़्यादा काम कर रही है। लेकिन पानी कम मत कीजिए, बढ़ाइए!', title_id = 'Maraton ke toilet? 🚻', body_id = 'Sering buang air kecil itu normal. Ginjal Anda bekerja lebih keras. Tapi jangan kurangi minum, justru tambah!', title_ja = 'トイレマラソン？🚻', body_ja = 'トイレが近いのは普通のこと。腎臓がたくさん働いているからです。でもお水は減らさず、増やしましょう！', title_ko = '화장실 마라톤? 🚻', body_ko = '자주 가는 건 정상이에요. 신장이 더 많이 일하고 있거든요. 그래도 물은 줄이지 말고 늘리세요!', title_nl = 'Toiletmarathon? 🚻', body_nl = 'Vaak plassen is normaal. Je nieren werken harder. Maar drink niet minder water, juist meer!', title_pl = 'Maraton do toalety? 🚻', body_pl = 'Częste wizyty są normalne. Twoje nerki pracują więcej. Ale nie ograniczaj wody, pij więcej!', title_pt = 'Maratona de idas à casa de banho? 🚻', body_pt = 'Ir muitas vezes é normal. Os rins estão a trabalhar mais. Mas não reduza a água, beba mais!', title_sv = 'Toalettmaraton? 🚻', body_sv = 'Det är normalt att gå ofta. Njurarna arbetar mer. Men dra inte ner på vattnet, drick mer!', title_vi = 'Chạy marathon vào nhà vệ sinh? 🚻', body_vi = 'Đi tiểu thường xuyên là bình thường. Thận của mẹ đang làm việc nhiều hơn. Nhưng đừng uống ít nước, hãy uống nhiều hơn!', title_zh = '厕所马拉松？🚻', body_zh = '尿频是正常的，你的肾脏工作量更大了。但别少喝水，要多喝！' WHERE id = '83b88cf3-52f6-408b-8331-beef50dfe19f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Tienes náuseas? ¡Perdona! 🥺', body_es = 'Las hormonas están de fiesta y la culpa es mía. ¿Te hago sentir mal? ¿Comemos una galleta salada? 🍪', title_fr = 'Des nausées ? Pardon ! 🥺', body_fr = 'Les hormones font la fête, et c''est ma faute. Je vous embête ? On mange des crackers salés ? 🍪', title_hi = 'जी मिचला रहा है? माफ़ करना! 🥺', body_hi = 'हार्मोन पार्टी कर रहे हैं, और वजह मैं हूँ। आपको तकलीफ़ दे रहा हूँ? नमकीन क्रैकर खाएँ? 🍪', title_id = 'Mual? Maaf ya! 🥺', body_id = 'Hormon sedang berpesta, dan akulah penyebabnya. Apakah aku menyusahkan Anda? Bagaimana kalau makan biskuit asin? 🍪', title_ja = '気持ち悪い？ごめんね！🥺', body_ja = 'ホルモンがパーティー中で、原因はわたしなの。つらくさせてる？塩味のクラッカーを食べようか？🍪', title_ko = '속이 메스꺼우세요? 미안해요! 🥺', body_ko = '호르몬이 파티 중인데, 범인은 저예요. 엄마를 힘들게 하나요? 짭짤한 크래커 먹을까요? 🍪', title_nl = 'Misselijk? Sorry! 🥺', body_nl = 'De hormonen geven een feestje en ik ben de schuldige. Zit ik je dwars? Zullen we een zoute cracker eten? 🍪', title_pl = 'Masz mdłości? Przepraszam! 🥺', body_pl = 'Hormony urządzają imprezę, a to moja wina. Dokuczam ci? Może zjemy słone krakersy? 🍪', title_pt = 'Está enjoada? Desculpe! 🥺', body_pt = 'As hormonas estão em festa e a culpa é minha. Estou a incomodá-la? Vamos comer umas bolachas salgadas? 🍪', title_sv = 'Mår du illa? Förlåt! 🥺', body_sv = 'Hormonerna har fest och det är mitt fel. Plågar jag dig? Ska vi äta ett salt kex? 🍪', title_vi = 'Mẹ buồn nôn à? Con xin lỗi! 🥺', body_vi = 'Hormone đang mở tiệc, và thủ phạm là con. Con làm mẹ khó chịu à? Mình ăn bánh quy mặn nhé? 🍪', title_zh = '恶心想吐？对不起！🥺', body_zh = '激素在开派对，罪魁祸首是我。让你难受了吗？吃点咸饼干吧？🍪' WHERE id = 'f2d72cc5-1dfe-472f-b0dd-cab7471cb46d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Día de pescado! 🐟', body_es = 'Elige pescado sin mercurio. El omega-3 es insustituible para el desarrollo del cerebro.', title_fr = 'Jour du poisson ! 🐟', body_fr = 'Choisissez des poissons sans mercure. Les oméga-3 sont irremplaçables pour le développement du cerveau.', title_hi = 'मछली का दिन! 🐟', body_hi = 'पारा-रहित मछली चुनिए। दिमाग के विकास के लिए ओमेगा-3 बेहद ज़रूरी है।', title_id = 'Hari ikan! 🐟', body_id = 'Pilih ikan yang bebas merkuri. Omega-3 tak tergantikan untuk perkembangan otak.', title_ja = 'お魚の日！🐟', body_ja = '水銀の少ない魚を選びましょう。オメガ3は脳の発達に欠かせません。', title_ko = '생선의 날! 🐟', body_ko = '수은이 없는 생선을 고르세요. 뇌 발달에 오메가-3는 꼭 필요해요.', title_nl = 'Visdag! 🐟', body_nl = 'Kies vis zonder kwik. Omega-3 is onmisbaar voor de ontwikkeling van de hersenen.', title_pl = 'Dzień ryby! 🐟', body_pl = 'Wybieraj ryby bez rtęci. Omega-3 jest niezastąpione dla rozwoju mózgu.', title_pt = 'Dia de peixe! 🐟', body_pt = 'Escolha peixe sem mercúrio. O ómega-3 é insubstituível para o desenvolvimento do cérebro.', title_sv = 'Fiskdag! 🐟', body_sv = 'Välj fisk utan kvicksilver. Omega-3 är oersättligt för hjärnans utveckling.', title_vi = 'Ngày ăn cá! 🐟', body_vi = 'Hãy chọn cá ít thủy ngân. Omega-3 không thể thiếu cho sự phát triển của não.', title_zh = '吃鱼日！🐟', body_zh = '选择不含汞的鱼。Omega-3对大脑发育不可替代。' WHERE id = '4395d8a1-8cd6-4561-9d88-e944bb78801d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Se forma su carita 👀', body_es = 'Se están formando sus ojos, nariz y orejas. Por ahora parecen puntitos oscuros, pero su carita va tomando forma.', title_fr = 'Son visage se forme 👀', body_fr = 'Ses yeux, son nez et ses oreilles apparaissent. Ce ne sont encore que des points sombres, mais ses traits se dessinent.', title_hi = 'चेहरा बन रहा है 👀', body_hi = 'आँखें, नाक और कान बन रहे हैं। अभी ये काले बिंदुओं जैसे हैं, पर चेहरे की रूपरेखा उभर रही है।', title_id = 'Wajahnya sedang terbentuk 👀', body_id = 'Mata, hidung, dan telinganya mulai terbentuk. Saat ini masih seperti titik-titik gelap, tapi wajahnya mulai tergambar.', title_ja = '顔ができてきています 👀', body_ja = '目、鼻、耳がつくられています。今はまだ黒い点のようですが、顔立ちが描かれはじめています。', title_ko = '얼굴이 만들어지고 있어요 👀', body_ko = '눈, 코, 귀가 생기고 있어요. 아직은 검은 점 같지만 얼굴 윤곽이 그려지고 있어요.', title_nl = 'Het gezichtje krijgt vorm 👀', body_nl = 'De ogen, de neus en de oren worden gevormd. Ze lijken nog op donkere stipjes, maar het gezichtje tekent zich af.', title_pl = 'Kształtuje się buzia 👀', body_pl = 'Powstają oczy, nos i uszy. Na razie wyglądają jak ciemne kropki, ale rysy już się zarysowują.', title_pt = 'O rosto está a formar-se 👀', body_pt = 'Os olhos, o nariz e as orelhas estão a formar-se. Por enquanto parecem pontinhos escuros, mas o rosto já se desenha.', title_sv = 'Ansiktet tar form 👀', body_sv = 'Ögon, näsa och öron bildas. Än så länge ser de ut som mörka prickar, men ansiktsdragen börjar synas.', title_vi = 'Khuôn mặt đang hình thành 👀', body_vi = 'Mắt, mũi và tai đang hình thành. Giờ chúng chỉ như những chấm đen, nhưng khuôn mặt bé đang dần hiện rõ.', title_zh = '小脸正在形成 👀', body_zh = '眼睛、鼻子和耳朵正在形成。现在看起来还像小黑点，但五官轮廓已经开始显现。' WHERE id = 'd24fadf2-1d24-4001-b4cd-1006ba1390b4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Dónde está la vitamina B6? 🍌', body_es = 'Plátano, aguacate o pollo... Esta vitamina puede aliviar las náuseas.', title_fr = 'Où trouver la vitamine B6 ? 🍌', body_fr = 'Banane, avocat ou poulet... Cette vitamine peut atténuer les nausées.', title_hi = 'विटामिन B6 कहाँ है? 🍌', body_hi = 'केला, एवोकाडो या चिकन... यह विटामिन जी मिचलाना कम कर सकता है।', title_id = 'Di mana Vitamin B6? 🍌', body_id = 'Pisang, alpukat, atau daging ayam... Vitamin ini dapat meringankan mual.', title_ja = 'ビタミンB6はどこ？🍌', body_ja = 'バナナ、アボカド、鶏肉...このビタミンは吐き気をやわらげてくれることがあります。', title_ko = '비타민 B6는 어디에? 🍌', body_ko = '바나나, 아보카도, 닭고기... 이 비타민은 메스꺼움을 덜어 줄 수 있어요.', title_nl = 'Waar zit vitamine B6? 🍌', body_nl = 'Banaan, avocado of kip... Deze vitamine kan misselijkheid verlichten.', title_pl = 'Gdzie jest witamina B6? 🍌', body_pl = 'Banany, awokado czy kurczak... Ta witamina może złagodzić mdłości.', title_pt = 'Onde está a vitamina B6? 🍌', body_pt = 'Banana, abacate ou frango... Esta vitamina pode aliviar as náuseas.', title_sv = 'Var finns vitamin B6? 🍌', body_sv = 'Banan, avokado eller kyckling... Det här vitaminet kan lindra illamående.', title_vi = 'Vitamin B6 ở đâu? 🍌', body_vi = 'Chuối, bơ hoặc thịt gà... Vitamin này có thể giúp giảm buồn nôn.', title_zh = '维生素B6在哪里？🍌', body_zh = '香蕉、牛油果或鸡肉……这种维生素可能有助于缓解恶心。' WHERE id = '98979663-767c-4d48-9b7b-786f81533442' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Fiesta de baile secreta! 💃', body_es = 'Aunque no lo notes, ya se mueve. Sus primeros movimientos son como pequeños temblores.', title_fr = 'Soirée dansante secrète ! 💃', body_fr = 'Même si vous ne le sentez pas, il bouge déjà. Ses premiers mouvements ressemblent à de petits tressaillements.', title_hi = 'सीक्रेट डांस पार्टी! 💃', body_hi = 'भले आपको महसूस न हो, वह हिलने-डुलने लगा है। उसकी पहली हरकतें बस हल्की फड़कन जैसी हैं।', title_id = 'Pesta dansa rahasia! 💃', body_id = 'Meski Anda belum merasakannya, ia sudah bergerak. Gerakan pertamanya hanya seperti kedutan kecil.', title_ja = 'ひみつのダンスパーティー！💃', body_ja = '気づかなくても、赤ちゃんはもう動いています。最初の動きは、ぴくっとするような小さなものです。', title_ko = '비밀 댄스 파티! 💃', body_ko = '느끼지 못해도 아기는 벌써 움직이고 있어요. 첫 움직임은 그저 작은 떨림 같아요.', title_nl = 'Geheim dansfeestje! 💃', body_nl = 'Ook al voel je het niet, je baby beweegt al. De eerste bewegingen zijn net kleine schokjes.', title_pl = 'Sekretna impreza taneczna! 💃', body_pl = 'Choć tego nie czujesz, ono już się porusza. Pierwsze ruchy są jak drobne drgnięcia.', title_pt = 'Uma festa de dança secreta! 💃', body_pt = 'Mesmo que não sinta, o bebé já se mexe. Os primeiros movimentos são apenas pequenos espasmos.', title_sv = 'Hemlig dansfest! 💃', body_sv = 'Även om du inte känner det rör sig barnet redan. De första rörelserna är bara som små ryckningar.', title_vi = 'Bữa tiệc khiêu vũ bí mật! 💃', body_vi = 'Dù mẹ chưa cảm nhận được, bé đã cử động rồi. Những cử động đầu tiên chỉ như những cái giật nhẹ.', title_zh = '秘密舞会！💃', body_zh = '即使你感觉不到，宝宝已经在动了。最初的动作就像轻轻的抽动。' WHERE id = 'b82ae448-8da6-41fb-9588-70bee70788e8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Encurtidos o chocolate? 🥒', body_es = 'Los antojos raros son normales. ¡Pero cuidado con el azúcar! En Nutrición hay sustitutos saludables.', title_fr = 'Cornichons ou chocolat ? 🥒', body_fr = 'Les envies bizarres sont normales. Mais attention au sucre ! La rubrique Nutrition propose des alternatives saines.', title_hi = 'अचार या चॉकलेट? 🥒', body_hi = 'अजीब क्रेविंग सामान्य है। लेकिन चीनी का ध्यान रखिए! पोषण में सेहतमंद विकल्प हैं।', title_id = 'Acar atau cokelat? 🥒', body_id = 'Ngidam yang aneh itu normal. Tapi perhatikan gula! Ada pengganti sehat di bagian Nutrisi.', title_ja = 'すっぱいもの？それともチョコ？🥒', body_ja = '変わったものが食べたくなるのは普通のこと。でも糖分には気をつけて！「栄養」に健康的な代わりのものがあります。', title_ko = '피클, 아니면 초콜릿? 🥒', body_ko = '이상한 입맛은 정상이에요. 그래도 설탕은 조심하세요! 영양 섹션에 건강한 대체 음식이 있어요.', title_nl = 'Augurk of chocolade? 🥒', body_nl = 'Vreemde trek is normaal. Maar let op suiker! In Voeding vind je gezonde alternatieven.', title_pl = 'Ogórki kiszone czy czekolada? 🥒', body_pl = 'Dziwne zachcianki są normalne. Ale uważaj na cukier! W sekcji Odżywianie są zdrowe zamienniki.', title_pt = 'Pickles ou chocolate? 🥒', body_pt = 'Os desejos estranhos são normais. Mas atenção ao açúcar! Há alternativas saudáveis na Nutrição.', title_sv = 'Inlagd gurka eller choklad? 🥒', body_sv = 'Konstiga sug är normala. Men håll koll på sockret! I Kost finns nyttiga alternativ.', title_vi = 'Đồ chua hay sô-cô-la? 🥒', body_vi = 'Thèm ăn kỳ lạ là bình thường. Nhưng hãy chú ý lượng đường! Mục Dinh dưỡng có những món thay thế lành mạnh.', title_zh = '酸黄瓜还是巧克力？🥒', body_zh = '奇怪的嘴馋很正常。但要注意糖分！营养板块里有健康的替代品。' WHERE id = '32c29664-93a4-4e94-bb42-a62ada8dcf6a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Has reducido la cafeína? ☕', body_es = 'No más de 1 taza al día. Dale una oportunidad al té descafeinado o a las infusiones.', title_fr = 'Moins de caféine ? ☕', body_fr = 'Pas plus d''une tasse par jour. Laissez une chance au thé déthéiné ou aux tisanes.', title_hi = 'कैफ़ीन कम किया? ☕', body_hi = 'दिन में 1 कप से ज़्यादा नहीं। डिकैफ़ या हर्बल चाय को मौका दीजिए।', title_id = 'Sudah mengurangi kafein? ☕', body_id = 'Tidak lebih dari 1 cangkir sehari. Coba teh tanpa kafein atau teh herbal.', title_ja = 'カフェイン、減らしましたか？☕', body_ja = '1日1杯までにしましょう。デカフェやハーブティーも試してみてください。', title_ko = '카페인 줄이셨나요? ☕', body_ko = '하루 1잔을 넘기지 마세요. 디카페인 차나 허브차를 시도해 보세요.', title_nl = 'Minder cafeïne? ☕', body_nl = 'Niet meer dan 1 kopje per dag. Geef cafeïnevrije thee of kruidenthee een kans.', title_pl = 'Ograniczyłaś kofeinę? ☕', body_pl = 'Nie więcej niż 1 filiżanka dziennie. Daj szansę herbacie bezkofeinowej lub ziołowej.', title_pt = 'Já reduziu a cafeína? ☕', body_pt = 'Não mais do que 1 chávena por dia. Dê uma oportunidade ao chá descafeinado ou às infusões.', title_sv = 'Har du dragit ner på koffeinet? ☕', body_sv = 'Högst 1 kopp om dagen. Ge koffeinfritt te eller örtte en chans.', title_vi = 'Mẹ đã giảm caffeine chưa? ☕', body_vi = 'Không quá 1 tách mỗi ngày. Hãy thử trà không caffeine hoặc trà thảo mộc.', title_zh = '减少咖啡因了吗？☕', body_zh = '每天不要超过1杯。试试无咖啡因茶或花草茶吧。' WHERE id = '6ff4b2b8-64a6-4583-a2a6-a17dcd93d858' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Estoy bailando! 🕺', body_es = 'Sus brazos y piernas se doblan. Hace acrobacias en tu vientre, pero tú aún no lo notas.', title_fr = 'Je danse ! 🕺', body_fr = 'Ses bras et ses jambes se plient. Il fait des acrobaties dans votre ventre, mais vous ne le sentez pas encore.', title_hi = 'मैं डांस कर रहा हूँ! 🕺', body_hi = 'उसके हाथ-पैर मुड़ रहे हैं। वह आपके गर्भ में करतब दिखा रहा है, पर आपको अभी महसूस नहीं होता।', title_id = 'Aku sedang menari! 🕺', body_id = 'Lengan dan kakinya menekuk. Ia sedang beraksi akrobatik di rahim Anda, tapi Anda belum merasakannya.', title_ja = 'ダンスしてるよ！🕺', body_ja = '腕や脚を曲げたり伸ばしたり。お腹の中でアクロバット中ですが、ママはまだ感じられません。', title_ko = '저 춤추고 있어요! 🕺', body_ko = '팔다리를 구부리고 있어요. 아기가 뱃속에서 곡예를 하고 있지만 아직은 느껴지지 않아요.', title_nl = 'Ik ben aan het dansen! 🕺', body_nl = 'De armpjes en beentjes buigen. Je baby doet aan acrobatiek in je buik, maar jij voelt het nog niet.', title_pl = 'Tańczę! 🕺', body_pl = 'Rączki i nóżki się zginają. Dziecko robi akrobacje w twoim brzuchu, ale ty jeszcze tego nie czujesz.', title_pt = 'Estou a dançar! 🕺', body_pt = 'Os braços e as pernas dobram-se. O bebé faz acrobacias no seu ventre, mas ainda não as sente.', title_sv = 'Jag dansar! 🕺', body_sv = 'Armar och ben böjs. Barnet gör akrobatik i din mage, men du känner det inte än.', title_vi = 'Con đang nhảy múa! 🕺', body_vi = 'Tay chân bé đang co duỗi. Bé đang nhào lộn trong bụng mẹ, nhưng mẹ vẫn chưa cảm nhận được.', title_zh = '我在跳舞！🕺', body_zh = '胳膊和腿在弯曲。宝宝在你肚子里表演杂技，只是你还感觉不到。' WHERE id = '75ccffd0-f3f8-457f-9109-f503ba1c9c27' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Una sopa de verduras? 🥣', body_es = 'Si tu estómago no tolera comidas pesadas, toma una sopa ligera. ¡Vitaminas y líquido a la vez!', title_fr = 'Une soupe de légumes ? 🥣', body_fr = 'Si votre estomac ne supporte pas les repas lourds, prenez une soupe légère. Des vitamines et de l''eau à la fois !', title_hi = 'सब्ज़ियों का सूप? 🥣', body_hi = 'अगर पेट भारी खाना नहीं पचा पा रहा, तो हल्का सूप पीजिए। विटामिन भी और तरल भी!', title_id = 'Sup sayur? 🥣', body_id = 'Jika perut Anda tidak bisa menerima makanan berat, makanlah sup ringan. Ada vitamin sekaligus cairan!', title_ja = '野菜スープはいかが？🥣', body_ja = '重い食事が受けつけないときは、軽いスープを。ビタミンも水分もとれます！', title_ko = '채소 수프 어때요? 🥣', body_ko = '속이 무거운 음식을 받지 않으면 가벼운 수프를 드세요. 비타민도 수분도 함께!', title_nl = 'Groentesoep? 🥣', body_nl = 'Kan je maag geen zware maaltijden aan? Eet dan een lichte soep. Vitamines én vocht!', title_pl = 'Zupa warzywna? 🥣', body_pl = 'Jeśli żołądek nie przyjmuje ciężkich potraw, zjedz lekką zupę. To i witaminy, i płyny!', title_pt = 'Sopa de legumes? 🥣', body_pt = 'Se o estômago não tolera refeições pesadas, coma uma sopa leve. Dá vitaminas e líquidos!', title_sv = 'Grönsakssoppa? 🥣', body_sv = 'Om magen inte klarar tung mat, ät en lätt soppa. Både vitaminer och vätska!', title_vi = 'Súp rau nhé? 🥣', body_vi = 'Nếu dạ dày không chịu được món nặng, hãy ăn súp nhẹ. Vừa có vitamin, vừa có nước!', title_zh = '来碗蔬菜汤？🥣', body_zh = '如果胃受不了油腻的饭菜，就喝点清淡的汤。既有维生素，又能补水！' WHERE id = '471326ec-b4e0-411d-b639-63ddc151da1f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Involucra también a papá 🗣️', body_es = 'Esta aventura no es solo tuya. Mirad juntos la primera ecografía y hablad de vuestros planes de futuro.', title_fr = 'Impliquez aussi Papa 🗣️', body_fr = 'Cette aventure n''est pas seulement la vôtre. Regardez ensemble la première échographie et parlez de vos projets.', title_hi = 'पापा को भी शामिल कीजिए 🗣️', body_hi = 'यह सिर्फ़ आपका सफ़र नहीं है। पहली अल्ट्रासाउंड तस्वीर साथ में देखिए, आगे की योजनाओं पर बात कीजिए।', title_id = 'Ajak Ayah juga 🗣️', body_id = 'Ini bukan hanya petualangan Anda. Lihat foto USG pertama bersama dan bicarakan rencana ke depan.', title_ja = 'パパも巻き込もう 🗣️', body_ja = 'これはママだけの冒険ではありません。初めてのエコー写真を一緒に見て、これからのことを話し合いましょう。', title_ko = '아빠도 함께해요 🗣️', body_ko = '이건 엄마만의 모험이 아니에요. 첫 초음파 사진을 함께 보고 미래 계획을 이야기해 보세요.', title_nl = 'Betrek papa erbij 🗣️', body_nl = 'Dit is niet alleen jouw avontuur. Bekijk samen de eerste echofoto en praat over jullie plannen.', title_pl = 'Zaangażuj tatę 🗣️', body_pl = 'To nie tylko twoja przygoda. Obejrzyjcie razem pierwsze zdjęcie z USG i porozmawiajcie o planach na przyszłość.', title_pt = 'Envolva também o pai 🗣️', body_pt = 'Esta aventura não é só sua. Vejam juntos a primeira imagem da ecografia e falem dos planos para o futuro.', title_sv = 'Ta med pappa också 🗣️', body_sv = 'Det här är inte bara ditt äventyr. Titta på den första ultraljudsbilden tillsammans och prata om era framtidsplaner.', title_vi = 'Rủ cả bố cùng tham gia 🗣️', body_vi = 'Đây không chỉ là hành trình của riêng mẹ. Hãy cùng nhau xem ảnh siêu âm đầu tiên và trò chuyện về những dự định tương lai.', title_zh = '让爸爸也参与进来 🗣️', body_zh = '这不只是你一个人的旅程。一起看第一张B超照片，聊聊未来的计划吧。' WHERE id = '3efe947d-4b4b-4c7f-9958-16d89faba8db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Se forma la capa de grasa 🧸', body_es = 'El bebé empieza a acumular grasa para mantenerse calentito.', title_fr = 'La couche de graisse se forme 🧸', body_fr = 'Bébé commence à faire des réserves de graisse pour se tenir chaud.', title_hi = 'चर्बी की परत बन रही है 🧸', body_hi = 'बच्चा गर्म रहने के लिए चर्बी जमा करना शुरू कर रहा है।', title_id = 'Lapisan lemak mulai terbentuk 🧸', body_id = 'Bayi mulai menimbun lemak agar tetap hangat.', title_ja = '脂肪の層ができてきます 🧸', body_ja = '赤ちゃんは体を温めるために、脂肪をたくわえはじめています。', title_ko = '지방층이 생기고 있어요 🧸', body_ko = '아기가 따뜻하게 지내려고 지방을 모으기 시작해요.', title_nl = 'Er vormt zich een vetlaagje 🧸', body_nl = 'Je baby begint vet op te slaan om warm te blijven.', title_pl = 'Tworzy się warstwa tłuszczu 🧸', body_pl = 'Dziecko zaczyna gromadzić tłuszcz, by było mu ciepło.', title_pt = 'A camada de gordura está a formar-se 🧸', body_pt = 'O bebé começa a acumular gordura para se manter quente.', title_sv = 'Ett fettlager bildas 🧸', body_sv = 'Barnet börjar samla fett för att hålla sig varmt.', title_vi = 'Lớp mỡ đang hình thành 🧸', body_vi = 'Em bé bắt đầu tích mỡ để giữ ấm.', title_zh = '脂肪层正在形成 🧸', body_zh = '宝宝开始储存脂肪来保暖了。' WHERE id = '5efd10b2-de1a-4b0e-b6df-24a9fc762806' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'No me pican los dientes... ¡todavía! 😬', body_es = 'Leche, yogur, queso... ¿Están hoy en tu lista de alimentación? 🥛', title_fr = 'Mes dents ne me grattent pas... pour l''instant ! 😬', body_fr = 'Lait, yaourt, fromage... Sont-ils sur votre liste de repas aujourd''hui ? 🥛', title_hi = 'मेरे मसूड़ों में खुजली नहीं... अभी तक! 😬', body_hi = 'दूध, दही, पनीर... क्या आज ये आपकी पोषण सूची में हैं? 🥛', title_id = 'Gusiku belum gatal... untuk saat ini! 😬', body_id = 'Susu, yogurt, keju... Apakah ini ada di daftar nutrisi Anda hari ini? 🥛', title_ja = '歯ぐきはまだかゆくないよ...今はね！😬', body_ja = '牛乳、ヨーグルト、チーズ...今日の食事リストに入っている？🥛', title_ko = '아직 잇몸이 간지럽지 않아요... 아직은요! 😬', body_ko = '우유, 요거트, 치즈... 오늘 식단에 들어 있나요? 🥛', title_nl = 'Mijn tandjes jeuken niet... nog niet! 😬', body_nl = 'Melk, yoghurt, kaas... Staan die vandaag op je voedingslijst? 🥛', title_pl = 'Dziąsła mnie nie swędzą... jeszcze! 😬', body_pl = 'Mleko, jogurt, ser... Czy są dziś na twojej liście posiłków? 🥛', title_pt = 'As gengivas não me fazem comichão... ainda! 😬', body_pt = 'Leite, iogurte, queijo... Estão hoje na sua lista de alimentação? 🥛', title_sv = 'Mina tänder kliar inte... än! 😬', body_sv = 'Mjölk, yoghurt, ost... Finns de på kostlistan i dag? 🥛', title_vi = 'Lợi con chưa ngứa... đâu! 😬', body_vi = 'Sữa, sữa chua, phô mai... Hôm nay danh sách dinh dưỡng có những món này không? 🥛', title_zh = '我的牙龈还不痒……暂时！😬', body_zh = '牛奶、酸奶、奶酪……今天的饮食清单里有它们吗？🥛' WHERE id = '410a1e31-b41d-4130-8526-c1b0f94d7fcb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Como una adolescente? 😳', body_es = 'Pueden salirte granitos en la cara. ¡Es cosa de las hormonas! Mantén la piel limpia y no te automediques.', title_fr = 'Comme une ado ? 😳', body_fr = 'Des boutons peuvent apparaître sur votre visage. C''est l''effet des hormones ! Gardez votre peau propre, sans médicaments.', title_hi = 'टीनेजर जैसी हालत? 😳', body_hi = 'चेहरे पर मुहाँसे हो सकते हैं। यह हार्मोन का काम है! त्वचा साफ़ रखिए, दवा मत लगाइए।', title_id = 'Seperti remaja? 😳', body_id = 'Jerawat bisa muncul di wajah Anda. Itu ulah hormon! Jaga kebersihan kulit dan jangan sembarangan memakai obat.', title_ja = '思春期みたい？😳', body_ja = '顔にニキビができることがあります。ホルモンのしわざです！肌を清潔に保ち、自己判断で薬を使わないでくださいね。', title_ko = '사춘기 같나요? 😳', body_ko = '얼굴에 뾰루지가 날 수 있어요. 호르몬 때문이에요! 피부를 깨끗하게 하고 약은 함부로 쓰지 마세요.', title_nl = 'Net een tiener? 😳', body_nl = 'Je kunt puistjes in je gezicht krijgen. Dat komt door de hormonen! Houd je huid schoon en gebruik geen medicijnen.', title_pl = 'Jak nastolatka? 😳', body_pl = 'Na twarzy mogą pojawić się pryszcze. To sprawka hormonów! Dbaj o czystość skóry, nie sięgaj po leki.', title_pt = 'Como uma adolescente? 😳', body_pt = 'Podem aparecer borbulhas no rosto. É obra das hormonas! Mantenha a pele limpa e não tome medicamentos.', title_sv = 'Som en tonåring? 😳', body_sv = 'Du kan få finnar i ansiktet. Det är hormonernas verk! Håll huden ren och ta inga läkemedel på eget bevåg.', title_vi = 'Như tuổi teen? 😳', body_vi = 'Mặt mẹ có thể nổi mụn. Là do hormone đấy! Giữ da sạch sẽ, đừng tự ý dùng thuốc.', title_zh = '像青春期一样？😳', body_zh = '脸上可能会冒痘痘，这是激素的作用！保持皮肤清洁，不要乱用药。' WHERE id = 'a94e0a87-fa0f-44bc-96ea-31a14e8e1954' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Problemas de estreñimiento? 🚽', body_es = 'Mucha agua y alimentos ricos en fibra son tus amigos. El kiwi y los orejones pueden hacer maravillas.', title_fr = 'Problème de constipation ? 🚽', body_fr = 'Beaucoup d''eau et des aliments riches en fibres sont vos alliés. Les kiwis et les abricots secs peuvent faire des miracles.', title_hi = 'कब्ज़ की परेशानी? 🚽', body_hi = 'खूब पानी और फ़ाइबर वाला खाना आपके दोस्त हैं। कीवी और सूखी खुबानी कमाल कर सकते हैं।', title_id = 'Masalah sembelit? 🚽', body_id = 'Banyak minum air dan makanan berserat adalah sahabat Anda. Kiwi dan aprikot kering bisa membuat keajaiban.', title_ja = '便秘に悩んでいますか？🚽', body_ja = 'たっぷりのお水と食物繊維の多い食べ物が味方です。キウイや干しあんずが効くこともあります。', title_ko = '변비 고민? 🚽', body_ko = '충분한 물과 섬유질 음식이 친구예요. 키위와 말린 살구가 기적을 일으킬 수 있어요.', title_nl = 'Last van verstopping? 🚽', body_nl = 'Veel water en vezelrijk eten zijn je vrienden. Kiwi en gedroogde abrikozen kunnen wonderen doen.', title_pl = 'Problem z zaparciami? 🚽', body_pl = 'Dużo wody i błonnika to twoi przyjaciele. Kiwi i suszone morele mogą zdziałać cuda.', title_pt = 'Problemas de obstipação? 🚽', body_pt = 'Muita água e alimentos ricos em fibra são seus amigos. O kiwi e os alperces secos podem fazer milagres.', title_sv = 'Problem med förstoppning? 🚽', body_sv = 'Mycket vatten och fiberrik mat är dina vänner. Kiwi och torkade aprikoser kan göra underverk.', title_vi = 'Bị táo bón? 🚽', body_vi = 'Nhiều nước và thực phẩm giàu chất xơ là bạn của mẹ. Kiwi và mơ khô có thể làm nên điều kỳ diệu.', title_zh = '便秘困扰？🚽', body_zh = '多喝水和高纤维食物是你的好朋友。猕猴桃和杏干可能会有奇效。' WHERE id = 'a8178689-8b83-4c18-aed1-047d8befc921' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'El agua de mi piscina ha bajado... 💧', body_es = 'Me encanta nadar en agua limpia y abundante. ¿Te bebes un vaso de agua por mí? 🥺', title_fr = 'Il manque d''eau dans ma piscine... 💧', body_fr = 'J''adore nager dans une eau propre et abondante. Vous buvez un verre d''eau pour moi ? 🥺', title_hi = 'मेरे पूल का पानी कम हो गया... 💧', body_hi = 'मुझे साफ़ और भरपूर पानी में तैरना पसंद है। मेरी खातिर एक गिलास पानी पी लेंगी? 🥺', title_id = 'Air kolamku berkurang... 💧', body_id = 'Aku suka berenang di air yang bersih dan melimpah. Maukah Anda minum segelas air demi aku? 🥺', title_ja = 'プールのお水が減ってきたよ... 💧', body_ja = 'きれいなお水がたっぷりの中で泳ぐのが好きなの。わたしのために、お水を1杯飲んでくれる？🥺', title_ko = '제 수영장 물이 줄었어요... 💧', body_ko = '저는 깨끗하고 넉넉한 물에서 헤엄치는 게 좋아요. 저를 위해 물 한 잔 드실래요? 🥺', title_nl = 'Er zit minder water in mijn zwembad... 💧', body_nl = 'Ik zwem graag in schoon en veel water. Drink je voor mij een glas water? 🥺', title_pl = 'W moim basenie ubywa wody... 💧', body_pl = 'Uwielbiam pływać w czystej, obfitej wodzie. Wypijesz dla mnie szklankę wody? 🥺', title_pt = 'A água da minha piscina está a baixar... 💧', body_pt = 'Adoro nadar em água limpa e abundante. Bebe um copo de água por mim, Mamã? 🥺', title_sv = 'Vattnet i min pool har minskat... 💧', body_sv = 'Jag älskar att simma i rent och rikligt vatten. Dricker du ett glas vatten för min skull? 🥺', title_vi = 'Nước bể bơi của con cạn bớt rồi... 💧', body_vi = 'Con thích bơi trong làn nước trong và nhiều. Vì con, mẹ uống thêm một cốc nước nhé? 🥺', title_zh = '我泳池的水变少了……💧', body_zh = '我喜欢在干净又充足的水里游泳。为了我，喝一杯水好吗？🥺' WHERE id = '54999531-d81c-49ad-a8e5-0a766a343a4f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te aprieto? ¡Perdona!', body_es = 'Aunque tu peso no aumente, estoy ampliando mi casa. Vamos a quitarnos ese pantalón ajustado y ponernos algo cómodo. 🤰', title_fr = 'Je vous serre ? Pardon !', body_fr = 'Même si votre poids n''a pas augmenté, j''agrandis ma maison. Enlevons ce pantalon serré et mettons quelque chose de confortable. 🤰', title_hi = 'आपको दबा रहा हूँ? माफ़ करना!', body_hi = 'भले वज़न न बढ़ा हो, मैं अपना घर बड़ा कर रहा हूँ। चलिए वह टाइट पैंट उतारकर कुछ आरामदायक पहनें। 🤰', title_id = 'Aku membuat Anda sesak? Maaf ya!', body_id = 'Meski berat badan belum bertambah, aku sedang memperluas rumahku. Yuk, lepas celana ketat itu dan pakai yang nyaman. 🤰', title_ja = 'きゅうくつ？ごめんね！', body_ja = '体重はあまり増えていなくても、わたしはお部屋を広げているよ。きついズボンは脱いで、楽な服を着ようね。🤰', title_ko = '답답하세요? 미안해요!', body_ko = '몸무게는 그대로여도 저는 집을 넓히고 있어요. 꽉 끼는 바지는 벗고 편한 옷을 입어요. 🤰', title_nl = 'Druk ik op je? Sorry!', body_nl = 'Ook al kom je nog niet aan, ik maak mijn huisje groter. Zullen we die strakke broek uittrekken en iets comfortabels aandoen? 🤰', title_pl = 'Ściskam cię? Przepraszam!', body_pl = 'Nawet jeśli twoja waga nie rośnie, ja powiększam swój domek. Zdejmijmy te ciasne spodnie i włóżmy coś wygodnego. 🤰', title_pt = 'Estou a apertá-la? Desculpe!', body_pt = 'Mesmo que o seu peso não tenha aumentado, estou a aumentar a minha casa. Vamos tirar essas calças apertadas e vestir algo confortável. 🤰', title_sv = 'Klämmer jag dig? Förlåt!', body_sv = 'Även om vikten inte har ökat så bygger jag ut mitt hem. Kom, vi tar av de trånga byxorna och sätter på något bekvämt. 🤰', title_vi = 'Con làm mẹ chật chội à? Xin lỗi mẹ!', body_vi = 'Dù cân nặng của mẹ chưa tăng, con đang mở rộng nhà mình rồi. Mình thay chiếc quần chật ra, mặc gì đó thoải mái nhé. 🤰', title_zh = '挤到你了吗？对不起！', body_zh = '虽然体重还没怎么增加，我已经在扩建我的小家了。把那条紧身裤换下来，穿点舒服的吧。🤰' WHERE id = '6fc47392-9629-4d33-8e40-e40e2521230e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Encurtidos o chocolate? 🍫', body_es = 'Mira la sección Nutrición, ¿qué hay de saludable hoy en el menú? 😋', title_fr = 'Cornichons ou chocolat ? 🍫', body_fr = 'Jetez un œil à la rubrique Nutrition : qu''y a-t-il de bon au menu aujourd''hui ? 😋', title_hi = 'अचार या चॉकलेट? 🍫', body_hi = 'पोषण सेक्शन देखिए, आज मेन्यू में क्या सेहतमंद है? 😋', title_id = 'Asam atau cokelat? 🍫', body_id = 'Lihat bagian Nutrisi, apa yang bermanfaat di menu hari ini? 😋', title_ja = 'すっぱいもの？それともチョコ？🍫', body_ja = '「栄養」セクションを見てみましょう。今日のメニューには体にいいものは何がある？😋', title_ko = '피클, 아니면 초콜릿? 🍫', body_ko = '영양 섹션을 확인해 보세요. 오늘 메뉴에는 어떤 건강한 음식이 있을까요? 😋', title_nl = 'Zuur of chocolade? 🍫', body_nl = 'Kijk in het onderdeel Voeding: wat staat er vandaag voor gezonds op het menu? 😋', title_pl = 'Kwaśne czy czekolada? 🍫', body_pl = 'Zajrzyj do sekcji Odżywianie: co zdrowego jest dziś w menu? 😋', title_pt = 'Pickles ou chocolate? 🍫', body_pt = 'Espreite a secção Nutrição: o que há de saudável no menu de hoje? 😋', title_sv = 'Surt eller choklad? 🍫', body_sv = 'Titta i Kost-avsnittet, vad finns det för nyttigt på menyn i dag? 😋', title_vi = 'Đồ chua hay Sô-cô-la? 🍫', body_vi = 'Xem mục Dinh dưỡng nhé, thực đơn hôm nay có gì bổ dưỡng? 😋', title_zh = '酸的还是巧克力？🍫', body_zh = '去营养板块看看，今天菜单上有什么健康美食？😋' WHERE id = '9fae4e34-d2bb-467a-bd40-2f0853238a4e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Empieza el sentido del gusto 👅', body_es = 'En su lengua se forman las papilas gustativas. Él también notará el sabor de lo que comes.', title_fr = 'Le goût se développe 👅', body_fr = 'Des papilles gustatives apparaissent sur sa langue. Il sentira lui aussi le goût de ce que vous mangez.', title_hi = 'स्वाद की शुरुआत 👅', body_hi = 'उसकी जीभ पर स्वाद कलिकाएँ बन रही हैं। आप जो खाती हैं, उसका स्वाद वह भी महसूस करेगा।', title_id = 'Indra pengecap mulai berkembang 👅', body_id = 'Kuncup pengecap mulai terbentuk di lidahku. Aku juga akan merasakan rasa makanan yang Anda makan.', title_ja = '味覚の発達がスタート 👅', body_ja = '舌に味を感じる味蕾ができています。ママが食べたものの味を、赤ちゃんも感じるようになります。', title_ko = '미각이 생기고 있어요 👅', body_ko = '혀에 미뢰가 생기고 있어요. 엄마가 먹는 음식의 맛을 아기도 느끼게 될 거예요.', title_nl = 'De smaak ontwikkelt zich 👅', body_nl = 'Er vormen zich smaakpapillen op de tong. Je baby gaat de smaak proeven van wat jij eet.', title_pl = 'Rozwija się zmysł smaku 👅', body_pl = 'Na jego języku tworzą się kubki smakowe. Będzie czuć smak tego, co jesz.', title_pt = 'O paladar está a começar 👅', body_pt = 'Estão a formar-se papilas gustativas na língua do bebé. Vai sentir também o sabor do que a mãe come.', title_sv = 'Smaksinnet vaknar 👅', body_sv = 'Smaklökar bildas på tungan. Barnet kommer också att känna smaken av maten du äter.', title_vi = 'Vị giác bắt đầu hình thành 👅', body_vi = 'Nụ vị giác đang hình thành trên lưỡi bé. Bé cũng sẽ cảm nhận được hương vị những món mẹ ăn.', title_zh = '味觉开始发育 👅', body_zh = '舌头上正在长出味蕾。你吃的食物味道，宝宝也会感受到。' WHERE id = 'c1f145fd-3d01-40af-8a31-7f261ae6105a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te molesta el olor de la carne? 🥩', body_es = '¡Necesitas proteína! Si no puedes comer carne, sustitúyela por lentejas, garbanzos o frutos secos.', title_fr = 'L''odeur de la viande vous dégoûte ? 🥩', body_fr = 'Il vous faut des protéines ! Si vous ne pouvez pas manger de viande, remplacez-la par des lentilles, des pois chiches ou des fruits à coque.', title_hi = 'मांस की गंध से दूर भागती हैं? 🥩', body_hi = 'प्रोटीन ज़रूरी है! अगर मांस नहीं खा पा रहीं, तो दाल, छोले या मेवों से उसकी जगह भरिए।', title_id = 'Menghindari bau daging? 🥩', body_id = 'Anda butuh protein! Jika tidak bisa makan daging, ganti dengan lentil, kacang arab, atau kacang-kacangan.', title_ja = 'お肉のにおいが苦手？🥩', body_ja = 'たんぱく質は必要です！お肉が食べられないなら、レンズ豆、ひよこ豆、ナッツで代用しましょう。', title_ko = '고기 냄새가 싫으세요? 🥩', body_ko = '단백질이 필요해요! 고기를 못 드시면 렌틸콩, 병아리콩이나 견과류로 대신하세요.', title_nl = 'Kun je de geur van vlees niet uitstaan? 🥩', body_nl = 'Je hebt eiwit nodig! Lukt vlees niet, vervang het dan door linzen, kikkererwten of noten.', title_pl = 'Unikasz zapachu mięsa? 🥩', body_pl = 'Potrzebujesz białka! Jeśli nie możesz jeść mięsa, zastąp je soczewicą, ciecierzycą lub orzechami.', title_pt = 'Foge do cheiro da carne? 🥩', body_pt = 'Precisa de proteína! Se não consegue comer carne, substitua-a por lentilhas, grão-de-bico ou frutos secos.', title_sv = 'Undviker du köttlukt? 🥩', body_sv = 'Du behöver protein! Om du inte kan äta kött, byt ut det mot linser, kikärtor eller nötter.', title_vi = 'Mẹ sợ mùi thịt? 🥩', body_vi = 'Cần protein đấy! Nếu không ăn được thịt, hãy thay bằng đậu lăng, đậu gà hoặc các loại hạt.', title_zh = '闻到肉味就想躲？🥩', body_zh = '蛋白质不能少！如果吃不下肉，可以用扁豆、鹰嘴豆或坚果代替。' WHERE id = 'e6b9a24b-da46-4708-9e5b-b659c3de661e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te aprieta el sujetador? 👙', body_es = 'Tu pecho crece y está más sensible. Es hora de pasarte a una ropa interior cómoda, tipo deportiva y sin aros.', title_fr = 'Votre soutien-gorge vous serre ? 👙', body_fr = 'Votre poitrine grossit et devient plus sensible. C''est le moment de passer à une lingerie confortable, type sport et sans armatures.', title_hi = 'ब्रा टाइट लग रही है? 👙', body_hi = 'आपके स्तन बड़े और संवेदनशील हो रहे हैं। आरामदायक, स्पोर्ट्स टाइप और बिना वायर वाली ब्रा पहनने का समय है।', title_id = 'Bra terasa sempit? 👙', body_id = 'Payudara Anda membesar dan makin sensitif. Saatnya beralih ke pakaian dalam yang nyaman, model olahraga, dan tanpa kawat.', title_ja = 'ブラがきつくなってきた？👙', body_ja = '胸が大きくなり、敏感になっています。楽なスポーツタイプのノンワイヤーの下着に替えるときです。', title_ko = '브래지어가 꽉 끼나요? 👙', body_ko = '가슴이 커지고 예민해지고 있어요. 편안한 스포츠형 노와이어 속옷으로 바꿀 때예요.', title_nl = 'Zit je bh te strak? 👙', body_nl = 'Je borsten worden groter en gevoeliger. Tijd voor comfortabel, sportief ondergoed zonder beugel.', title_pl = 'Biustonosz robi się ciasny? 👙', body_pl = 'Twoje piersi rosną i stają się wrażliwsze. Czas na wygodną, sportową bieliznę bez fiszbinów.', title_pt = 'O soutien está a ficar apertado? 👙', body_pt = 'O peito está a crescer e a ficar mais sensível. É altura de mudar para soutiens confortáveis, de desporto e sem aros.', title_sv = 'Sitter behån för tight? 👙', body_sv = 'Brösten växer och blir känsligare. Dags att byta till bekväma underkläder i sportmodell utan bygel.', title_vi = 'Áo ngực bị chật? 👙', body_vi = 'Ngực mẹ đang lớn và nhạy cảm hơn. Đã đến lúc chuyển sang đồ lót thể thao, thoải mái, không gọng.', title_zh = '文胸变紧了？👙', body_zh = '你的乳房在变大，也更敏感了。是时候换成舒适的运动款无钢圈内衣了。' WHERE id = '44977c78-f7ae-4f0e-9e98-b634c325ef0b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Tu cuerpo pide agua! 💧', body_es = 'La deshidratación puede causar dolor de cabeza. Entra en el Registro de agua y bébete un vaso. ✅', title_fr = 'Votre corps réclame de l''eau ! 💧', body_fr = 'Le manque d''eau peut donner mal à la tête. Ouvrez le Suivi d''hydratation et buvez un verre ! ✅', title_hi = 'आपका शरीर पानी माँग रहा है! 💧', body_hi = 'पानी की कमी से सिरदर्द हो सकता है। वॉटर ट्रैकर खोलिए और एक गिलास पानी पीजिए! ✅', title_id = 'Tubuh Anda butuh air! 💧', body_id = 'Kurang minum bisa menyebabkan sakit kepala. Buka Pelacak Air dan minum segelas air! ✅', title_ja = '体がお水を欲しがっています！💧', body_ja = '水分不足は頭痛の原因になることも。「水分トラッカー」を開いて、お水を1杯飲みましょう！✅', title_ko = '몸이 물을 원해요! 💧', body_ko = '수분이 부족하면 두통이 생길 수 있어요. 물 기록을 열고 한 잔 마셔요! ✅', title_nl = 'Je lichaam wil water! 💧', body_nl = 'Te weinig drinken kan hoofdpijn geven. Open de Waterteller en drink een glas! ✅', title_pl = 'Twoje ciało prosi o wodę! 💧', body_pl = 'Odwodnienie może wywołać ból głowy. Zajrzyj do Licznika wody i wypij szklankę! ✅', title_pt = 'O seu corpo pede água! 💧', body_pt = 'A desidratação pode causar dores de cabeça. Abra o Registo de Água e beba um copo! ✅', title_sv = 'Din kropp vill ha vatten! 💧', body_sv = 'Vätskebrist kan ge huvudvärk. Öppna Vattenspåraren och drick ett glas! ✅', title_vi = 'Cơ thể mẹ đang cần nước! 💧', body_vi = 'Thiếu nước có thể gây đau đầu. Vào Theo dõi uống nước và uống một cốc nhé! ✅', title_zh = '你的身体需要水！💧', body_zh = '缺水可能引起头痛。打开饮水记录，喝一杯吧！✅' WHERE id = '494e490f-741c-402a-90a1-087cb49feebd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Ya tiene carita humana! 👶', body_es = '¿Y ese famoso brillo del embarazo en tu cara? ✨ ¡Inmortaliza esta belleza en la Galería!', title_fr = 'Il a déjà un visage humain ! 👶', body_fr = 'Et ce fameux éclat de grossesse sur votre visage ? ✨ Immortalisez cette beauté dans la Galerie !', title_hi = 'अब उसका चेहरा इंसान जैसा है! 👶', body_hi = 'और आपके चेहरे पर वह मशहूर प्रेग्नेंसी ग्लो? ✨ इस खूबसूरती को गैलरी में हमेशा के लिए सहेज लीजिए!', title_id = 'Ia sudah berwajah manusia! 👶', body_id = 'Lalu bagaimana dengan Cahaya Kehamilan yang terkenal di wajah Anda? ✨ Abadikan kecantikan ini di Galeri!', title_ja = 'もう人間らしい顔つきに！👶', body_ja = 'そしてママの顔には、あの有名なマタニティグロウ？✨ この美しさをギャラリーに残しましょう！', title_ko = '아기가 이제 사람 얼굴을 갖췄어요! 👶', body_ko = '엄마 얼굴의 그 유명한 임신 광채는요? ✨ 이 아름다움을 갤러리에 남겨 보세요!', title_nl = 'Je baby heeft al een menselijk gezichtje! 👶', body_nl = 'En die bekende zwangerschapsgloed op jouw gezicht? ✨ Leg deze schoonheid vast in de Galerij!', title_pl = 'Ma już ludzką twarz! 👶', body_pl = 'A co z tym słynnym ciążowym blaskiem na twojej twarzy? ✨ Uwiecznij to piękno w Galerii!', title_pt = 'O bebé já tem um rosto humano! 👶', body_pt = 'E aquele famoso brilho da gravidez no seu rosto? ✨ Eternize esta beleza na Galeria!', title_sv = 'Nu har barnet ett mänskligt ansikte! 👶', body_sv = 'Och hur är det med den berömda graviditetsglöden i ditt ansikte? ✨ Förevig skönheten i Galleriet!', title_vi = 'Bé đã có gương mặt người rồi! 👶', body_vi = 'Còn vẻ Rạng rỡ thai kỳ nổi tiếng trên gương mặt mẹ thì sao? ✨ Hãy lưu giữ vẻ đẹp này trong Thư viện ảnh!', title_zh = '宝宝已经有了人的模样！👶', body_zh = '那你脸上著名的孕期光彩呢？✨ 在相册里留住这份美丽吧！' WHERE id = '91f2c1e3-6e09-405e-873b-1c7871ae42d1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Explosión de vitamina C 🍊', body_es = 'Naranja, kiwi o pimiento... ¡Mantén tus defensas fuertes como el acero, nada de ponerse enferma!', title_fr = 'Explosion de vitamine C 🍊', body_fr = 'Orange, kiwi ou poivron... Gardez une immunité d''acier, pas question de tomber malade !', title_hi = 'विटामिन C का धमाका 🍊', body_hi = 'संतरा, कीवी या शिमला मिर्च... अपनी इम्युनिटी फ़ौलाद जैसी मज़बूत रखिए, बीमार नहीं पड़ना है!', title_id = 'Ledakan Vitamin C 🍊', body_id = 'Jeruk, kiwi, atau paprika... Jaga daya tahan tubuh sekuat baja, jangan sampai sakit!', title_ja = 'ビタミンCをたっぷり 🍊', body_ja = 'オレンジ、キウイ、パプリカ...免疫力を鋼のように強く保って、風邪をひかないようにしましょう！', title_ko = '비타민 C 폭발 🍊', body_ko = '오렌지, 키위, 파프리카... 면역력을 강철처럼 튼튼하게 지켜요, 아프면 안 돼요!', title_nl = 'Een vitamine C-boost 🍊', body_nl = 'Sinaasappel, kiwi of paprika... Houd je weerstand zo sterk als staal, ziek worden is er niet bij!', title_pl = 'Wybuch witaminy C 🍊', body_pl = 'Pomarańcze, kiwi czy papryka... Utrzymaj odporność mocną jak stal, nie możesz chorować!', title_pt = 'Explosão de vitamina C 🍊', body_pt = 'Laranja, kiwi ou pimento... Mantenha a imunidade forte como aço, não pode ficar doente!', title_sv = 'C-vitaminexplosion 🍊', body_sv = 'Apelsin, kiwi eller paprika... Håll immunförsvaret starkt som stål, nu får du inte bli sjuk!', title_vi = 'Bùng nổ Vitamin C 🍊', body_vi = 'Cam, kiwi hay ớt chuông... Giữ hệ miễn dịch vững như thép, không được ốm đâu nhé!', title_zh = '维生素C大爆发 🍊', body_zh = '橙子、猕猴桃或甜椒……让免疫力像钢铁一样坚强，可不能生病！' WHERE id = '6632cd55-3fc2-4b5a-99ae-1934d4d07a48' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Los riñones se ponen a trabajar! 🚽', body_es = 'Parece increíble, pero ya hace pis. Traga líquido amniótico y lo expulsa. ¡Empieza el ciclo!', title_fr = 'Les reins se mettent au travail ! 🚽', body_fr = 'C''est incroyable, mais il fait déjà pipi. Il avale le liquide amniotique puis l''élimine. Le cycle commence !', title_hi = 'किडनी काम पर लग गई! 🚽', body_hi = 'यकीन नहीं होगा, पर वह अब पेशाब करने लगा है। वह एम्नियोटिक द्रव निगलता और बाहर निकालता है। चक्र शुरू!', title_id = 'Ginjal mulai bekerja! 🚽', body_id = 'Luar biasa, ia sudah bisa buang air kecil. Ia menelan dan mengeluarkan cairan ketuban. Siklusnya dimulai!', title_ja = '腎臓が働きはじめた！🚽', body_ja = '信じられないけれど、赤ちゃんはもうおしっこをしています。羊水を飲みこんでは出しているのです。循環のはじまりです！', title_ko = '신장이 일하기 시작했어요! 🚽', body_ko = '믿기 어렵지만 아기는 벌써 소변을 봐요. 양수를 삼키고 내보내요. 순환이 시작됐어요!', title_nl = 'De nieren zijn aan het werk! 🚽', body_nl = 'Ongelofelijk, maar je baby plast al. Het slikt vruchtwater in en scheidt het weer uit. De kringloop begint!', title_pl = 'Nerki ruszyły do pracy! 🚽', body_pl = 'To niesamowite, ale ono już siusia. Połyka płyn owodniowy i go wydala. Cykl się zaczyna!', title_pt = 'Os rins entraram em ação! 🚽', body_pt = 'É incrível, mas o bebé já faz xixi. Engole o líquido amniótico e expele-o. O ciclo começa!', title_sv = 'Njurarna har satt igång! 🚽', body_sv = 'Det är otroligt, men barnet kissar redan. Det sväljer och utsöndrar fostervatten. Kretsloppet börjar!', title_vi = 'Thận đã bắt đầu làm việc! 🚽', body_vi = 'Thật khó tin, nhưng bé đã biết đi tiểu. Bé nuốt và thải nước ối. Một chu trình bắt đầu!', title_zh = '肾脏开始工作了！🚽', body_zh = '难以置信，宝宝已经会尿尿了。吞下羊水再排出来，循环开始了！' WHERE id = '0839dbbd-18f9-4a16-8c8c-024d9b6c0fb5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Ya es como un pomelo! 🍊', body_es = 'Tu cintura puede ensancharse. ¿Han cambiado los números? ¡Anótalo en el Registro de peso! 📈', title_fr = 'Il est grand comme un pamplemousse ! 🍊', body_fr = 'Votre taille peut s''arrondir. Les chiffres ont changé ? Notez-les dans le Suivi du poids ! 📈', title_hi = 'चकोतरे जितना हो गया! 🍊', body_hi = 'आपकी कमर मोटी हो सकती है। क्या आँकड़े बदले? वेट ट्रैकर में लिखिए! 📈', title_id = 'Sudah seukuran jeruk bali! 🍊', body_id = 'Pinggang Anda mungkin mulai melebar. Angkanya berubah? Catat di Pelacak Berat Badan! 📈', title_ja = 'グレープフルーツくらいになりました！🍊', body_ja = 'ウエストが太くなってきたかも。数字は変わりましたか？「体重トラッカー」に記録しましょう！📈', title_ko = '자몽만큼 컸어요! 🍊', body_ko = '허리가 굵어질 수 있어요. 숫자가 바뀌었나요? 체중 기록에 남겨 보세요! 📈', title_nl = 'Zo groot als een grapefruit! 🍊', body_nl = 'Je taille kan voller worden. Zijn de cijfers veranderd? Noteer het in de Gewichtsteller! 📈', title_pl = 'Jest już wielkości grejpfruta! 🍊', body_pl = 'Twoja talia może się poszerzać. Liczby się zmieniły? Zapisz to w Liczniku wagi! 📈', title_pt = 'Já é do tamanho de uma toranja! 🍊', body_pt = 'A cintura pode estar a alargar. Os números mudaram? Registe no Registo de Peso! 📈', title_sv = 'Nu lika stor som en grapefrukt! 🍊', body_sv = 'Midjan kan bli bredare. Har siffrorna ändrats? Anteckna i Viktspåraren! 📈', title_vi = 'Bé to bằng quả bưởi chùm rồi! 🍊', body_vi = 'Vòng eo mẹ có thể to ra. Con số đã thay đổi chưa? Ghi lại vào Theo dõi cân nặng nhé! 📈', title_zh = '有一个西柚那么大啦！🍊', body_zh = '你的腰围可能变粗了。数字有变化吗？记到体重记录里吧！📈' WHERE id = 'd77d400f-027c-4514-b287-ee1cd4aff422' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Hora del cribado combinado? 🗓️', body_es = 'Las semanas 11-14 son importantes. Habla con tu médico para valorar el riesgo de síndrome de Down.', title_fr = 'L''heure du double test ? 🗓️', body_fr = 'La période entre 11 et 14 semaines est importante. Parlez à votre médecin du dépistage du risque de trisomie 21.', title_hi = 'डबल टेस्ट का समय? 🗓️', body_hi = '11-14 हफ़्तों के बीच का समय अहम है। डाउन सिंड्रोम का जोखिम जाँचने के लिए अपने डॉक्टर से बात कीजिए।', title_id = 'Waktunya double test? 🗓️', body_id = 'Minggu ke-11 sampai 14 sangat penting. Bicarakan dengan dokter untuk memeriksa risiko sindrom Down.', title_ja = 'ダブルテストの時期？🗓️', body_ja = '11-14週の間は大切な時期です。ダウン症のリスクを調べるために、お医者さんと相談しましょう。', title_ko = '이중 검사 시기인가요? 🗓️', body_ko = '11-14주 사이가 중요해요. 다운증후군 위험을 확인하려면 담당 의사와 상의하세요.', title_nl = 'Tijd voor de combinatietest? 🗓️', body_nl = 'De weken 11-14 zijn belangrijk. Praat met je arts over het onderzoek naar het risico op downsyndroom.', title_pl = 'Czas na test podwójny? 🗓️', body_pl = 'Okres między 11. a 14. tygodniem jest ważny. Porozmawiaj z lekarzem o sprawdzeniu ryzyka zespołu Downa.', title_pt = 'Hora do rastreio combinado? 🗓️', body_pt = 'O período entre as 11 e as 14 semanas é importante. Fale com o seu médico para avaliar o risco de síndrome de Down.', title_sv = 'Dags för KUB-test? 🗓️', body_sv = 'Veckorna 11-14 är viktiga. Prata med din läkare om att undersöka risken för Downs syndrom.', title_vi = 'Đến lúc làm Double test? 🗓️', body_vi = 'Khoảng tuần 11-14 rất quan trọng. Hãy trao đổi với bác sĩ để kiểm tra nguy cơ hội chứng Down.', title_zh = '该做早期唐筛了吗？🗓️', body_zh = '11-14周很关键。和医生聊聊，检查唐氏综合征的风险。' WHERE id = '5d87369c-e5c4-4b67-b09a-fc38d7a668d6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Hambre o sed? 🤔', body_es = 'A veces el cerebro los confunde. Primero bebe un vaso de agua; si sigues con hambre, entonces es hora de comer.', title_fr = 'Faim ou soif ? 🤔', body_fr = 'Parfois, le cerveau confond les deux. Buvez d''abord un verre d''eau : si vous avez encore faim, c''est l''heure de manger.', title_hi = 'भूख लगी है या प्यास? 🤔', body_hi = 'कभी-कभी दिमाग गड़बड़ा जाता है। पहले एक गिलास पानी पीजिए, फिर भी भूख लगे तो खाने का समय है।', title_id = 'Lapar atau haus? 🤔', body_id = 'Terkadang otak bisa keliru. Minum segelas air dulu, jika masih lapar, berarti memang waktunya makan.', title_ja = '空腹？それとものどが渇いてる？🤔', body_ja = '脳が取り違えることもあります。まずはお水を1杯飲んで、それでもお腹がすいていたら、ごはんの時間です。', title_ko = '배고픈 걸까요, 목마른 걸까요? 🤔', body_ko = '가끔 뇌가 헷갈려요. 먼저 물 한 잔을 마시고, 그래도 배고프면 식사할 시간이에요.', title_nl = 'Honger of dorst? 🤔', body_nl = 'Soms halen je hersenen die door elkaar. Drink eerst een glas water. Heb je daarna nog honger, dan is het tijd om te eten.', title_pl = 'Głodna czy spragniona? 🤔', body_pl = 'Czasem mózg się myli. Najpierw wypij szklankę wody, a jeśli nadal jesteś głodna, to czas na jedzenie.', title_pt = 'Fome ou sede? 🤔', body_pt = 'Às vezes o cérebro confunde-se. Beba primeiro um copo de água; se ainda tiver fome, então é hora de comer.', title_sv = 'Hungrig eller törstig? 🤔', body_sv = 'Ibland blandar hjärnan ihop dem. Drick först ett glas vatten, är du fortfarande hungrig är det dags att äta.', title_vi = 'Đói hay khát? 🤔', body_vi = 'Đôi khi não bị nhầm lẫn. Hãy uống một cốc nước trước, nếu vẫn đói thì đúng là đến giờ ăn rồi.', title_zh = '是饿了，还是渴了？🤔', body_zh = '有时大脑会混淆。先喝一杯水，如果还饿，那就是该吃饭了。' WHERE id = '9b258cde-4bf1-416d-abf2-57eb7d09c208' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Hora de gimnasia! 🤸', body_es = 'Ya cierra los puños y abre la boca. Aunque no lo notes, ¡dentro hay unas olimpiadas!', title_fr = 'L''heure de la gym ! 🤸', body_fr = 'Il serre déjà les poings et ouvre la bouche. Même si vous ne le sentez pas, ce sont les jeux olympiques à l''intérieur !', title_hi = 'जिम्नास्टिक का समय! 🤸', body_hi = 'वह अब मुट्ठी बंद करता है, मुँह खोलता है। भले आपको महसूस न हो, अंदर ओलंपिक चल रहा है!', title_id = 'Waktunya senam! 🤸', body_id = 'Ia sudah mengepalkan tangan dan membuka mulut. Meski Anda tidak merasakannya, di dalam sedang ada olimpiade!', title_ja = '体操の時間！🤸', body_ja = '赤ちゃんはもう手をにぎったり、口を開けたりしています。気づかなくても、お腹の中ではオリンピック開催中！', title_ko = '체조 시간이에요! 🤸', body_ko = '아기는 벌써 주먹을 쥐고 입을 벌려요. 느끼지 못해도 뱃속에서는 올림픽이 열리고 있어요!', title_nl = 'Tijd voor gymnastiek! 🤸', body_nl = 'Je baby balt al de handjes en opent het mondje. Ook al voel je het niet, binnen zijn de Olympische Spelen bezig!', title_pl = 'Czas na gimnastykę! 🤸', body_pl = 'Już zaciska rączki i otwiera buzię. Choć tego nie czujesz, w środku trwa olimpiada!', title_pt = 'Hora da ginástica! 🤸', body_pt = 'O bebé já fecha as mãos e abre a boca. Mesmo que não sinta, lá dentro decorrem uns Jogos Olímpicos!', title_sv = 'Gymnastikdags! 🤸', body_sv = 'Barnet knyter redan händerna och öppnar munnen. Även om du inte känner det pågår ett OS där inne!', title_vi = 'Đến giờ tập thể dục! 🤸', body_vi = 'Bé đã biết nắm tay, há miệng. Dù mẹ không cảm nhận được, bên trong đang diễn ra cả một kỳ Olympic!', title_zh = '体操时间到！🤸', body_zh = '宝宝已经会握拳、张嘴了。虽然你感觉不到，里面正在举办奥运会！' WHERE id = '827f46df-37d3-4f5e-80af-9e3b8db96d01' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Viene un peque muy listo! 🧠', body_es = 'El yodo es clave para el desarrollo del cerebro. ¿Tienes en tu menú sal yodada, pescado o lácteos?', title_fr = 'Un bébé malin arrive ! 🧠', body_fr = 'L''iode est indispensable au développement du cerveau. Sel iodé, poisson ou produits laitiers : sont-ils à votre menu ?', title_hi = 'होशियार बच्चा आ रहा है! 🧠', body_hi = 'दिमाग के विकास के लिए आयोडीन ज़रूरी है। क्या आयोडीन युक्त नमक, मछली या डेयरी उत्पाद आपके मेन्यू में हैं?', title_id = 'Si kecil yang cerdas akan datang! 🧠', body_id = 'Yodium sangat penting untuk perkembangan otak. Apakah garam beryodium, ikan, atau produk susu ada di menu Anda?', title_ja = 'かしこい赤ちゃんがやってくる！🧠', body_ja = 'ヨウ素は脳の発達に欠かせません。ヨウ素入りの塩、魚、乳製品はメニューにありますか？', title_ko = '똑똑한 아기가 오고 있어요! 🧠', body_ko = '요오드는 뇌 발달에 꼭 필요해요. 요오드 소금, 생선, 유제품이 식단에 있나요?', title_nl = 'Er komt een slimmerik aan! 🧠', body_nl = 'Jodium is essentieel voor de ontwikkeling van de hersenen. Staan gejodeerd zout, vis of zuivel op je menu?', title_pl = 'Nadchodzi mądre maleństwo! 🧠', body_pl = 'Jod jest niezbędny dla rozwoju mózgu. Czy w twoim menu jest sól jodowana, ryby lub nabiał?', title_pt = 'Vem aí um bebé inteligente! 🧠', body_pt = 'O iodo é essencial para o desenvolvimento do cérebro. Sal iodado, peixe ou lacticínios estão no seu menu?', title_sv = 'Ett klokt barn är på väg! 🧠', body_sv = 'Jod behövs för hjärnans utveckling. Finns joderat salt, fisk eller mejeriprodukter på din meny?', title_vi = 'Một em bé thông minh đang đến! 🧠', body_vi = 'I-ốt là điều kiện cần cho sự phát triển của não. Thực đơn của mẹ có muối i-ốt, cá hay các sản phẩm từ sữa không?', title_zh = '聪明宝宝要来啦！🧠', body_zh = '碘对大脑发育必不可少。你的菜单里有加碘盐、鱼或奶制品吗？' WHERE id = 'b247c7cf-7ded-4d8a-b64f-d3854d3be583' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Me estoy estirando! 🤸', body_es = 'Tú tampoco te quedes quieta, mamá. ¿Vemos los ejercicios suaves de yoga en la sección Ejercicios?', title_fr = 'Je m''étire ! 🤸', body_fr = 'Ne restez pas immobile non plus, Maman. On regarde les exercices de yoga doux dans la rubrique Exercices ?', title_hi = 'मैं अंगड़ाई ले रहा हूँ! 🤸', body_hi = 'आप भी एक जगह बैठी मत रहिए, माँ। एक्सरसाइज़ सेक्शन में हल्के योग आसन देखें?', title_id = 'Aku sedang meregangkan badan! 🤸', body_id = 'Anda juga jangan diam saja, Bunda. Yuk, lihat gerakan yoga ringan di bagian Latihan?', title_ja = 'ストレッチ中だよ！🤸', body_ja = 'ママもじっとしていないでね。「エクササイズ」セクションの軽いヨガを見てみない？', title_ko = '저 기지개 켜고 있어요! 🤸', body_ko = '엄마도 가만히 있지 마세요. 운동 섹션의 가벼운 요가 동작을 볼까요?', title_nl = 'Ik ben me aan het uitrekken! 🤸', body_nl = 'Blijf jij ook niet stilzitten, mama. Zullen we de rustige yogaoefeningen in het onderdeel Oefeningen bekijken?', title_pl = 'Przeciągam się! 🤸', body_pl = 'Ty też nie siedź bez ruchu, Mamo. Zajrzymy do lekkich ćwiczeń jogi w sekcji Ćwiczenia?', title_pt = 'Estou a espreguiçar-me! 🤸', body_pt = 'Não fique parada também, Mamã. Vamos ver os exercícios leves de ioga na secção Exercícios?', title_sv = 'Jag sträcker på mig! 🤸', body_sv = 'Sitt inte still du heller, mamma. Ska vi kolla de lätta yogarörelserna i avsnittet Träning?', title_vi = 'Con đang vươn vai! 🤸', body_vi = 'Mẹ cũng đừng ngồi yên nhé. Cùng xem các động tác yoga nhẹ nhàng trong mục Bài tập nhé?', title_zh = '我在伸懒腰！🤸', body_zh = '妈妈，你也别一直不动。看看运动板块里的轻柔瑜伽动作吧？' WHERE id = '9dfe8f42-50e3-422f-b528-dfdbb8ba5b68' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Que no te falte calcio 🥛', body_es = 'Se forman los brotes de los dientes. Requesón, queso o yogur... ¡Los necesita para su futura sonrisa!', title_fr = 'Ne manquez pas de calcium 🥛', body_fr = 'Les bourgeons des dents se forment. Fromage blanc, fromage ou yaourt... C''est important pour son futur sourire !', title_hi = 'कैल्शियम की कमी न हो 🥛', body_hi = 'दाँतों की कलियाँ बन रही हैं। पनीर, चीज़ या दही... ये उसकी आने वाली मुस्कान के लिए ज़रूरी हैं!', title_id = 'Jangan sampai kekurangan kalsium 🥛', body_id = 'Bakal gigi mulai terbentuk. Keju cottage, keju, atau yogurt... Dibutuhkan untuk senyumnya kelak!', title_ja = 'カルシウムを切らさずに 🥛', body_ja = '歯のもとができています。カッテージチーズ、チーズ、ヨーグルト...赤ちゃんの未来の笑顔のために必要です！', title_ko = '칼슘이 부족하지 않게 🥛', body_ko = '치아 싹이 생기고 있어요. 코티지치즈, 치즈, 요거트... 아기의 미래 미소를 위해 필요해요!', title_nl = 'Zorg voor genoeg calcium 🥛', body_nl = 'De tandknopjes worden gevormd. Kwark, kaas of yoghurt... nodig voor een toekomstige glimlach!', title_pl = 'Nie zapominaj o wapniu 🥛', body_pl = 'Tworzą się zawiązki zębów. Twarożek, ser czy jogurt... To potrzebne dla jego przyszłego uśmiechu!', title_pt = 'Que não falte cálcio 🥛', body_pt = 'Estão a formar-se os botões dos dentes. Requeijão, queijo ou iogurte... São precisos para o futuro sorriso do bebé!', title_sv = 'Se till att få i dig kalcium 🥛', body_sv = 'Tandanlagen bildas. Kvarg, ost eller yoghurt... Det behövs för barnets framtida leende!', title_vi = 'Đừng để thiếu canxi 🥛', body_vi = 'Mầm răng đang hình thành. Phô mai tươi, phô mai hay sữa chua... cần cho nụ cười tương lai của bé!', title_zh = '钙可别缺 🥛', body_zh = '牙胚正在形成。茅屋奶酪、奶酪或酸奶……为了宝宝未来的笑容，都需要！' WHERE id = '6d2e668d-18e8-41a3-a260-749a9ad4112f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te duele la cabeza? 🤕', body_es = 'No corras a tomar medicamentos. Una habitación oscura, una compresa fría o un masaje pueden sentarte mejor.', title_fr = 'Mal à la tête ? 🤕', body_fr = 'Ne vous précipitez pas sur les médicaments. Une pièce sombre, une compresse froide ou un massage peuvent mieux vous soulager.', title_hi = 'सिरदर्द है? 🤕', body_hi = 'दवा लेने की जल्दी मत कीजिए। अँधेरा कमरा, ठंडी पट्टी या मालिश ज़्यादा राहत दे सकती है।', title_id = 'Kepala pusing? 🤕', body_id = 'Jangan buru-buru minum obat. Ruangan gelap, kompres dingin, atau pijatan bisa lebih membantu.', title_ja = '頭が痛いですか？🤕', body_ja = 'すぐに薬に頼らないで。暗い部屋、冷たいタオル、マッサージのほうが効くこともあります。', title_ko = '머리가 아프세요? 🤕', body_ko = '서둘러 약을 먹지 마세요. 어두운 방, 차가운 찜질이나 마사지가 더 도움이 될 수 있어요.', title_nl = 'Hoofdpijn? 🤕', body_nl = 'Grijp niet meteen naar medicijnen. Een donkere kamer, een koud kompres of een massage kan beter helpen.', title_pl = 'Boli cię głowa? 🤕', body_pl = 'Nie spiesz się z lekami. Ciemny pokój, zimny okład lub masaż mogą pomóc bardziej.', title_pt = 'Dores de cabeça? 🤕', body_pt = 'Não se apresse a tomar medicamentos. Um quarto escuro, uma compressa fria ou uma massagem podem ajudar mais.', title_sv = 'Har du ont i huvudet? 🤕', body_sv = 'Skynda dig inte att ta läkemedel. Ett mörkt rum, en kall kompress eller massage kan hjälpa bättre.', title_vi = 'Mẹ bị đau đầu? 🤕', body_vi = 'Đừng vội uống thuốc. Một căn phòng tối, chườm lạnh hoặc xoa bóp có thể giúp ích hơn.', title_zh = '头疼吗？🤕', body_zh = '别急着吃药。暗一点的房间、冷敷或按摩可能更有效。' WHERE id = '36af91e4-7cdc-478f-b431-003ca4f4075f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Tu circulación va a tope! 🌊', body_es = 'Aumenta el volumen de sangre en tus venas y tu corazón trabaja más rápido. El agua es esencial para refrescar este sistema. ¡No olvides beber agua para no marearte! ✅', title_fr = 'Votre circulation s''emballe ! 🌊', body_fr = 'Votre volume sanguin augmente et votre cœur travaille plus vite. L''eau est essentielle pour refroidir ce système. Pensez à boire pour éviter les vertiges ! ✅', title_hi = 'रक्त संचार उफान पर! 🌊', body_hi = 'आपकी नसों में खून की मात्रा बढ़ रही है, दिल तेज़ी से काम कर रहा है। इस सिस्टम को ठंडा रखने के लिए पानी ज़रूरी है। चक्कर न आएँ, इसलिए पानी पीना न भूलें! ✅', title_id = 'Peredaran darah Anda meningkat! 🌊', body_id = 'Volume darah di pembuluh Anda bertambah dan jantung bekerja lebih cepat. Air penting untuk mendinginkan sistem ini. Jangan lupa minum agar tidak pusing! ✅', title_ja = '血の巡りが活発に！🌊', body_ja = '血管の中の血液量が増え、心臓が速く働いています。この仕組みを冷やすにはお水が欠かせません。めまいを防ぐために、お水を飲むのを忘れずに！✅', title_ko = '혈액 순환이 활발해요! 🌊', body_ko = '혈관 속 혈액량이 늘고 심장이 더 빨리 뛰고 있어요. 이 시스템을 식히려면 물이 꼭 필요해요. 어지럽지 않도록 물 마시는 걸 잊지 마세요! ✅', title_nl = 'Je bloedsomloop draait op volle toeren! 🌊', body_nl = 'De hoeveelheid bloed in je aderen neemt toe en je hart werkt sneller. Water is belangrijk om dit systeem koel te houden. Vergeet niet te drinken, zodat je niet duizelig wordt! ✅', title_pl = 'Twoje krążenie przyspiesza! 🌊', body_pl = 'W twoich żyłach przybywa krwi, a serce pracuje szybciej. Woda jest ważna, by ten system się nie przegrzewał. Pij wodę, żeby nie kręciło ci się w głowie! ✅', title_pt = 'A circulação está a todo o vapor! 🌊', body_pt = 'O volume de sangue nas suas veias está a aumentar e o coração trabalha mais depressa. A água é essencial para arrefecer este sistema. Não se esqueça de beber água para evitar tonturas! ✅', title_sv = 'Ditt blodomlopp går för fullt! 🌊', body_sv = 'Blodmängden i dina kärl ökar och hjärtat arbetar snabbare. Vatten är viktigt för att kyla systemet. Glöm inte att dricka vatten så att du inte blir yr! ✅', title_vi = 'Tuần hoàn máu đang dâng trào! 🌊', body_vi = 'Lượng máu trong mạch tăng lên, tim mẹ làm việc nhanh hơn. Nước rất cần để làm mát hệ thống này. Đừng quên uống nước để không bị chóng mặt nhé! ✅', title_zh = '血液循环在加速！🌊', body_zh = '你血管里的血量在增加，心脏跳得更快。给这个系统降温，水必不可少。为了避免头晕，别忘了喝水！✅' WHERE id = '17a77385-a0f0-43f1-b604-ef36e1b9f457' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Obras en marcha! 🏗️', body_es = '¡Tu bebé necesita calcio! Revisa los lácteos en la sección Nutrición. 🧀', title_fr = 'Travaux en cours ! 🏗️', body_fr = 'Votre bébé a besoin de calcium ! Découvrez les produits laitiers dans la rubrique Nutrition. 🧀', title_hi = 'निर्माण कार्य जारी है! 🏗️', body_hi = 'बच्चे को कैल्शियम चाहिए! पोषण सेक्शन में डेयरी उत्पाद देखिए। 🧀', title_id = 'Pembangunan sedang berlangsung! 🏗️', body_id = 'Bayi Anda butuh kalsium! Cek produk susu di bagian Nutrisi. 🧀', title_ja = '工事進行中！🏗️', body_ja = '赤ちゃんにはカルシウムが必要です！「栄養」セクションで乳製品をチェックしてみて。🧀', title_ko = '공사가 진행 중이에요! 🏗️', body_ko = '아기에게 칼슘이 필요해요! 영양 섹션에서 유제품을 확인해 보세요. 🧀', title_nl = 'Er wordt gebouwd! 🏗️', body_nl = 'Je baby heeft calcium nodig! Bekijk de zuivelproducten in het onderdeel Voeding. 🧀', title_pl = 'Trwają prace budowlane! 🏗️', body_pl = 'Twoje dziecko potrzebuje wapnia! Sprawdź nabiał w sekcji Odżywianie. 🧀', title_pt = 'Obras em curso! 🏗️', body_pt = 'O bebé precisa de cálcio! Veja os lacticínios na secção Nutrição. 🧀', title_sv = 'Byggarbete pågår! 🏗️', body_sv = 'Ditt barn behöver kalcium! Kolla mejeriprodukterna i Kost-avsnittet. 🧀', title_vi = 'Công trình đang thi công! 🏗️', body_vi = 'Em bé cần Canxi! Hãy xem các sản phẩm từ sữa trong mục Dinh dưỡng. 🧀', title_zh = '施工进行中！🏗️', body_zh = '宝宝需要钙！去营养板块看看奶制品吧。🧀' WHERE id = '75908864-8ad0-496c-8a26-f45ae3d7e742' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Di no a las estrías! 🧴', body_es = 'Aunque tu barriga aún no se note, hidrata tu piel. El aceite de almendras o de coco también calma el picor.', title_fr = 'Dites non aux vergetures ! 🧴', body_fr = 'Même si votre ventre ne se voit pas encore, hydratez votre peau. L''huile d''amande ou de coco calme aussi les démangeaisons.', title_hi = 'स्ट्रेच मार्क्स को ना कहिए! 🧴', body_hi = 'भले पेट अभी न दिखे, त्वचा को मॉइस्चराइज़ कीजिए। बादाम या नारियल तेल खुजली भी दूर करता है।', title_id = 'Katakan tidak pada stretch mark! 🧴', body_id = 'Meski perut belum membuncit, lembapkan kulit Anda. Minyak almon atau kelapa juga meredakan gatal.', title_ja = '妊娠線にノー！🧴', body_ja = 'お腹がまだ目立たなくても、肌を保湿しましょう。アーモンドオイルやココナッツオイルはかゆみもやわらげます。', title_ko = '튼살은 이제 그만! 🧴', body_ko = '아직 배가 나오지 않았어도 피부에 보습을 해 주세요. 아몬드 오일이나 코코넛 오일은 가려움도 덜어 줘요.', title_nl = 'Zeg nee tegen striemen! 🧴', body_nl = 'Ook al is je buik nog niet te zien, houd je huid soepel. Amandel- of kokosolie helpt ook tegen jeuk.', title_pl = 'Powiedz rozstępom nie! 🧴', body_pl = 'Choć brzuszka jeszcze nie widać, nawilżaj skórę. Olej migdałowy lub kokosowy łagodzi też swędzenie.', title_pt = 'Diga não às estrias! 🧴', body_pt = 'Mesmo que a barriga ainda não se note, hidrate a pele. O óleo de amêndoa ou de coco também alivia a comichão.', title_sv = 'Säg nej till bristningar! 🧴', body_sv = 'Även om magen inte syns än, återfukta huden. Mandel- eller kokosolja lindrar också klådan.', title_vi = 'Nói Không với rạn da! 🧴', body_vi = 'Dù bụng chưa lộ, hãy dưỡng ẩm cho da. Dầu hạnh nhân hoặc dầu dừa cũng giúp giảm ngứa.', title_zh = '对妊娠纹说不！🧴', body_zh = '即使肚子还没显，也要给皮肤保湿。杏仁油或椰子油还能止痒。' WHERE id = '2ba98fa8-fbf2-4460-81c1-96e992eb2cff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Hora de desvelar el secreto? 📢', body_es = 'El 1.er trimestre está por terminar. El riesgo ha bajado. ¿Lista para compartir la buena noticia con tus amigos?', title_fr = 'Le moment de révéler le secret ? 📢', body_fr = 'Le 1er trimestre touche à sa fin. Le risque a diminué. Prête à partager la bonne nouvelle avec vos amis ?', title_hi = 'राज़ खोलने का समय? 📢', body_hi = 'पहली तिमाही खत्म होने वाली है। जोखिम कम हो गया है। क्या आप खुशखबरी दोस्तों के साथ बाँटने को तैयार हैं?', title_id = 'Saatnya membuka rahasia? 📢', body_id = 'Trimester pertama hampir selesai. Risikonya sudah berkurang. Siap berbagi kabar bahagia dengan teman-teman?', title_ja = 'ひみつを打ち明けるとき？📢', body_ja = '妊娠初期がもうすぐ終わります。リスクは下がりました。うれしいニュースを友達に伝える準備はできていますか？', title_ko = '비밀을 밝힐 때일까요? 📢', body_ko = '임신 1기가 거의 끝나가요. 위험이 줄었어요. 기쁜 소식을 친구들과 나눌 준비가 됐나요?', title_nl = 'Tijd om het geheim te verklappen? 📢', body_nl = 'Het 1e trimester is bijna voorbij. Het risico is kleiner geworden. Ben je klaar om het goede nieuws met je vrienden te delen?', title_pl = 'Czas zdradzić sekret? 📢', body_pl = '1. trymestr dobiega końca. Ryzyko zmalało. Jesteś gotowa podzielić się dobrą nowiną z przyjaciółmi?', title_pt = 'Hora de revelar o segredo? 📢', body_pt = 'O 1.º trimestre está quase a terminar. O risco diminuiu. Está pronta para partilhar a boa notícia com os amigos?', title_sv = 'Dags att avslöja hemligheten? 📢', body_sv = 'Första trimestern är snart slut. Risken har minskat. Är du redo att dela de glada nyheterna med vänner?', title_vi = 'Đến lúc bật mí bí mật? 📢', body_vi = 'Tam cá nguyệt thứ 1 sắp kết thúc. Rủi ro đã giảm. Mẹ đã sẵn sàng chia sẻ tin vui với bạn bè chưa?', title_zh = '该公布秘密了吗？📢', body_zh = '孕早期快结束了，风险降低了。准备好和朋友们分享好消息了吗？' WHERE id = 'cbca369c-5e1a-4ee2-86f1-c37e9a851106' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡El esqueleto se fortalece! 🦴', body_es = 'Los cartílagos blandos se convierten en hueso. ¡Llena tus reservas de calcio para que tu peque esté fuerte!', title_fr = 'Le squelette se solidifie ! 🦴', body_fr = 'Les cartilages souples se transforment en os. Faites le plein de calcium pour que votre petit soit fort !', title_hi = 'कंकाल मज़बूत हो रहा है! 🦴', body_hi = 'नरम उपास्थि हड्डी में बदल रही है। कैल्शियम का भंडार भरिए, ताकि आपका नन्हा मज़बूत बने!', title_id = 'Kerangka mulai mengeras! 🦴', body_id = 'Tulang rawan yang lunak berubah menjadi tulang. Penuhi cadangan kalsium agar si kecil kuat!', title_ja = '骨格がしっかりしてきた！🦴', body_ja = 'やわらかい軟骨が骨に変わっていきます。カルシウムを補って、赤ちゃんを強くしてあげましょう！', title_ko = '뼈대가 단단해지고 있어요! 🦴', body_ko = '부드러운 연골이 뼈로 바뀌고 있어요. 아기가 튼튼하도록 칼슘을 충분히 채워 주세요!', title_nl = 'Het skelet wordt steviger! 🦴', body_nl = 'Zacht kraakbeen verandert in bot. Vul je calciumvoorraad aan, zodat je kleintje sterk wordt!', title_pl = 'Szkielet twardnieje! 🦴', body_pl = 'Miękkie chrząstki zmieniają się w kości. Uzupełnij zapas wapnia, by maleństwo było silne!', title_pt = 'O esqueleto está a ficar mais firme! 🦴', body_pt = 'As cartilagens moles estão a transformar-se em osso. Reforce as reservas de cálcio para o seu pequenino ficar forte!', title_sv = 'Skelettet blir hårdare! 🦴', body_sv = 'Mjukt brosk förvandlas till ben. Fyll på kalciumförrådet så att din lilla blir stark!', title_vi = 'Bộ xương đang cứng cáp! 🦴', body_vi = 'Sụn mềm đang chuyển thành xương. Hãy bổ sung canxi để bé yêu khỏe mạnh nhé!', title_zh = '骨骼在变硬！🦴', body_zh = '柔软的软骨正在变成骨头。补足钙储备，让宝宝更强壮！' WHERE id = 'c3c5cda3-e24a-4bf6-8134-243e683db4d1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Estás creando un océano! 🌊', body_es = 'El líquido amniótico se renueva. No olvides beber mucha agua para que tu bebé nade en una piscina limpia.', title_fr = 'Vous créez un océan ! 🌊', body_fr = 'Le liquide amniotique se renouvelle. Pensez à boire beaucoup d''eau pour que bébé nage dans une piscine bien propre.', title_hi = 'आप एक समंदर बना रही हैं! 🌊', body_hi = 'एम्नियोटिक द्रव नया होता रहता है। बच्चा साफ़ पूल में तैरे, इसके लिए खूब पानी पीना न भूलें।', title_id = 'Anda sedang menciptakan lautan! 🌊', body_id = 'Cairan ketuban terus diperbarui. Jangan lupa minum banyak air agar bayi berenang di kolam yang bersih.', title_ja = 'ママは海をつくっています！🌊', body_ja = '羊水が入れ替わっています。赤ちゃんがきれいなプールで泳げるように、お水をたっぷり飲むのを忘れずに。', title_ko = '엄마가 바다를 만들고 있어요! 🌊', body_ko = '양수가 새로워지고 있어요. 아기가 깨끗한 수영장에서 헤엄칠 수 있도록 물을 충분히 드세요.', title_nl = 'Jij maakt een oceaan! 🌊', body_nl = 'Het vruchtwater wordt ververst. Vergeet niet veel water te drinken, zodat je baby in een schoon zwembad zwemt.', title_pl = 'Tworzysz ocean! 🌊', body_pl = 'Płyn owodniowy się odnawia. Pij dużo wody, by dziecko pływało w czystym basenie.', title_pt = 'Está a criar um oceano! 🌊', body_pt = 'O líquido amniótico está a renovar-se. Não se esqueça de beber muita água para o bebé nadar numa piscina limpa.', title_sv = 'Du skapar ett hav! 🌊', body_sv = 'Fostervattnet förnyas. Glöm inte att dricka mycket vatten så att barnet kan simma i en ren pool.', title_vi = 'Mẹ đang tạo ra cả một đại dương! 🌊', body_vi = 'Nước ối đang được làm mới. Đừng quên uống nhiều nước để bé được bơi trong bể sạch nhé.', title_zh = '你在创造一片海洋！🌊', body_zh = '羊水在不断更新。别忘了多喝水，让宝宝在干净的泳池里游泳。' WHERE id = '0c81e884-eb3b-459e-9e4c-250ee35d9884' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te pica la barriga? 🌵', body_es = 'Es normal que pique cuando la piel se estira. Aplica aceite de almendras o una crema especial y relájate.', title_fr = 'Votre ventre vous gratte ? 🌵', body_fr = 'Quand la peau s''étire, les démangeaisons sont normales. Appliquez de l''huile d''amande ou une crème adaptée et détendez-vous.', title_hi = 'पेट में खुजली है? 🌵', body_hi = 'त्वचा खिंचने पर खुजली सामान्य है। बादाम का तेल या खास क्रीम लगाइए और आराम कीजिए।', title_id = 'Perut terasa gatal? 🌵', body_id = 'Gatal saat kulit meregang itu normal. Oleskan minyak almon atau krim khusus, lalu bersantailah.', title_ja = 'お腹がかゆい？🌵', body_ja = '皮膚が伸びるとかゆくなるのは普通のこと。アーモンドオイルや専用クリームを塗って、リラックスしましょう。', title_ko = '배가 가려우세요? 🌵', body_ko = '피부가 늘어나면서 가려운 건 정상이에요. 아몬드 오일이나 전용 크림을 바르고 편히 쉬세요.', title_nl = 'Jeukt je buik? 🌵', body_nl = 'Jeuk is normaal als de huid uitrekt. Smeer amandelolie of een speciale crème en ontspan.', title_pl = 'Swędzi cię brzuch? 🌵', body_pl = 'Swędzenie przy rozciąganiu skóry jest normalne. Posmaruj ją olejem migdałowym lub specjalnym kremem i odpocznij.', title_pt = 'A barriga faz comichão? 🌵', body_pt = 'É normal sentir comichão à medida que a pele estica. Aplique óleo de amêndoa ou um creme próprio e relaxe.', title_sv = 'Kliar magen? 🌵', body_sv = 'Det är normalt att det kliar när huden sträcks. Smörj in med mandelolja eller en särskild kräm och slappna av.', title_vi = 'Bụng mẹ bị ngứa? 🌵', body_vi = 'Ngứa khi da bị căng là bình thường. Thoa dầu hạnh nhân hoặc kem chuyên dụng và thư giãn nhé.', title_zh = '肚子发痒？🌵', body_zh = '皮肤被撑开时发痒很正常。涂点杏仁油或专用霜，放松一下吧。' WHERE id = '5b178828-ade2-47ab-8de7-afb567ca7a86' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Te llamaré mamá... 🥺', body_es = 'Se están formando mis cuerdas vocales. Ahora estoy en silencio, pero ¿sueñas con el día en que te hable por primera vez? Yo sí...', title_fr = 'Je vous appellerai Maman... 🥺', body_fr = 'Mes cordes vocales se forment. Je suis silencieux pour l''instant, mais rêvez-vous du jour où vous entendrez ma voix pour la première fois ? Moi, oui...', title_hi = 'मैं आपको माँ कहूँगा... 🥺', body_hi = 'मेरी वोकल कॉर्ड्स बन रही हैं। अभी मैं चुप हूँ, पर क्या आप उस दिन का सपना देखती हैं जब मैं पहली बार आपको पुकारूँगा? मैं देखता हूँ...', title_id = 'Aku akan memanggilmu Bunda... 🥺', body_id = 'Pita suaraku sedang terbentuk. Sekarang aku masih diam, tapi apakah Anda membayangkan hari ketika aku pertama kali memanggil Anda? Aku membayangkannya...', title_ja = 'ママって呼ぶからね... 🥺', body_ja = '声帯ができてきているよ。今は声を出せないけど、初めてママを呼ぶ日を夢見てる？わたしは夢見てるよ...', title_ko = '엄마라고 부를 거예요... 🥺', body_ko = '제 성대가 만들어지고 있어요. 지금은 소리가 없지만, 처음으로 엄마를 부를 그날을 꿈꾸고 있나요? 저는 꿈꿔요...', title_nl = 'Ik ga je mama noemen... 🥺', body_nl = 'Mijn stembanden worden gevormd. Ik ben nu nog stil, maar droom jij ook van de dag dat je mijn stem voor het eerst hoort? Ik wel...', title_pl = 'Będę mówić do ciebie Mamo... 🥺', body_pl = 'Kształtują się moje struny głosowe. Teraz jestem cicho, ale czy marzysz o dniu, gdy pierwszy raz się do ciebie odezwę? Ja tak...', title_pt = 'Vou chamar-lhe Mamã... 🥺', body_pt = 'As minhas cordas vocais estão a formar-se. Agora estou calado, mas sonha com o dia em que a vou chamar pela primeira vez? Eu sonho...', title_sv = 'Jag kommer att säga mamma till dig... 🥺', body_sv = 'Mina stämband bildas. Nu är jag tyst, men drömmer du om dagen när jag ropar på dig för första gången? Det gör jag...', title_vi = 'Con sẽ gọi mẹ là Mẹ... 🥺', body_vi = 'Dây thanh quản của con đang hình thành. Giờ con chưa có tiếng, nhưng mẹ có mơ về ngày con lần đầu gọi mẹ không? Con thì có...', title_zh = '我会叫你妈妈……🥺', body_zh = '我的声带正在形成。现在我还不会出声，你会憧憬我第一次叫你的那一天吗？我会……' WHERE id = 'a2d117f1-96df-4258-ab55-9a8d07073a66' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'La fibra es una heroína 🌾', body_es = 'Para mejorar la digestión, elige avena, verduras y fruta. En la sección Nutrición hay ensaladas deliciosas.', title_fr = 'Les fibres, ces héroïnes 🌾', body_fr = 'Pour une meilleure digestion, privilégiez l''avoine, les légumes et les fruits. La rubrique Nutrition propose de délicieuses salades.', title_hi = 'फ़ाइबर वाला खाना हीरो है 🌾', body_hi = 'पाचन सुधारने के लिए ओट्स, सब्ज़ियों और फलों को प्राथमिकता दीजिए। पोषण सेक्शन में स्वादिष्ट सलाद हैं।', title_id = 'Makanan berserat adalah pahlawan 🌾', body_id = 'Untuk melancarkan pencernaan, utamakan oat, sayuran, dan buah. Ada salad lezat di bagian Nutrisi.', title_ja = '食物繊維はヒーロー 🌾', body_ja = '消化を助けるために、オートミール、野菜、果物を選びましょう。「栄養」セクションにおいしいサラダがあります。', title_ko = '섬유질 음식이 영웅이에요 🌾', body_ko = '소화를 돕기 위해 귀리, 채소, 과일을 드세요. 영양 섹션에 맛있는 샐러드가 있어요.', title_nl = 'Vezels zijn helden 🌾', body_nl = 'Kies voor havermout, groente en fruit voor een betere spijsvertering. In het onderdeel Voeding vind je lekkere salades.', title_pl = 'Błonnik to bohater 🌾', body_pl = 'Dla lepszego trawienia wybieraj owsiankę, warzywa i owoce. W sekcji Odżywianie znajdziesz pyszne sałatki.', title_pt = 'As fibras são as heroínas 🌾', body_pt = 'Para melhorar a digestão, prefira aveia, legumes e fruta. Há saladas deliciosas na secção Nutrição.', title_sv = 'Fiberrik mat är en hjälte 🌾', body_sv = 'För bättre matsmältning, välj havre, grönsaker och frukt. Det finns goda sallader i Kost-avsnittet.', title_vi = 'Thực phẩm giàu chất xơ là người hùng 🌾', body_vi = 'Để tiêu hóa tốt hơn, hãy ưu tiên yến mạch, rau và trái cây. Mục Dinh dưỡng có nhiều món salad ngon.', title_zh = '膳食纤维是英雄 🌾', body_zh = '为了改善消化，多吃燕麦、蔬菜和水果。营养板块里有美味的沙拉。' WHERE id = '2743aaf7-db86-4143-a5f6-a342a96beb63' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Levantas peso? 🏋️‍♀️', body_es = 'El bebé ya acumula grasa y su esqueleto se endurece. ¡Estamos ganando peso rápido!', title_fr = 'Vous portez du poids ? 🏋️‍♀️', body_fr = 'Bébé fait déjà des réserves de graisse et son squelette se solidifie. On prend du poids rapidement !', title_hi = 'वज़न उठा रही हैं? 🏋️‍♀️', body_hi = 'बच्चा चर्बी की परत जमा कर रहा है और उसका कंकाल मज़बूत हो रहा है। हम तेज़ी से भारी हो रहे हैं!', title_id = 'Mengangkat beban? 🏋️‍♀️', body_id = 'Bayi sudah menimbun lapisan lemak dan kerangkanya mengeras. Kita bertambah berat dengan cepat!', title_ja = '重いものを持っていませんか？🏋️‍♀️', body_ja = '赤ちゃんはもう脂肪をたくわえ、骨格もしっかりしてきています。どんどん重くなっていきます！', title_ko = '무거운 걸 들고 있나요? 🏋️‍♀️', body_ko = '아기가 벌써 지방층을 쌓고 뼈대가 단단해지고 있어요. 빠르게 무거워지고 있어요!', title_nl = 'Til je zware dingen? 🏋️‍♀️', body_nl = 'Je baby slaat al vet op en het skelet wordt steviger. We worden snel zwaarder!', title_pl = 'Dźwigasz ciężary? 🏋️‍♀️', body_pl = 'Dziecko gromadzi już tkankę tłuszczową, a jego szkielet twardnieje. Szybko przybieramy na wadze!', title_pt = 'Está a levantar pesos? 🏋️‍♀️', body_pt = 'O bebé já está a acumular gordura e o esqueleto está a ficar mais firme. Estamos a ganhar peso depressa!', title_sv = 'Lyfter du tunga saker? 🏋️‍♀️', body_sv = 'Barnet samlar redan på sig ett fettlager och skelettet blir hårdare. Vi blir tyngre snabbt!', title_vi = 'Mẹ đang nâng vật nặng? 🏋️‍♀️', body_vi = 'Em bé đã tích lớp mỡ và bộ xương đang cứng cáp. Chúng mình đang nặng lên nhanh!', title_zh = '在提重物吗？🏋️‍♀️', body_zh = '宝宝已经在储存脂肪，骨骼也在变硬。我们长得飞快！' WHERE id = '0aec0374-a2a9-4f72-92ad-01577161b993' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡El flujo de nutrientes se acelera!', body_es = '¿Qué has comido hoy de saludable? ¡Revisa tu lista de Nutrición! 🥦', title_fr = 'L''apport en nutriments s''accélère !', body_fr = 'Qu''avez-vous mangé de bon aujourd''hui ? Consultez votre liste Nutrition ! 🥦', title_hi = 'पोषण का प्रवाह तेज़ हुआ!', body_hi = 'आज आपने क्या सेहतमंद खाया? पोषण सूची देखिए! 🥦', title_id = 'Aliran nutrisi makin cepat!', body_id = 'Apa makanan sehat yang Anda makan hari ini? Cek daftar Nutrisi! 🥦', title_ja = '栄養の流れがスピードアップ！', body_ja = '今日は体にいいものを何か食べましたか？「栄養」リストをチェックしましょう！🥦', title_ko = '영양 공급이 빨라졌어요!', body_ko = '오늘 어떤 건강한 음식을 드셨어요? 영양 목록을 확인해 보세요! 🥦', title_nl = 'De voedingsstroom versnelt!', body_nl = 'Wat heb jij vandaag voor gezonds gegeten? Bekijk je voedingslijst! 🥦', title_pl = 'Dopływ składników odżywczych przyspieszył!', body_pl = 'Co zdrowego dziś zjadłaś? Sprawdź listę w sekcji Odżywianie! 🥦', title_pt = 'O fluxo de nutrientes acelerou!', body_pt = 'O que comeu hoje de saudável? Veja a lista de Nutrição! 🥦', title_sv = 'Näringsflödet har ökat!', body_sv = 'Vad har du ätit nyttigt i dag? Kolla din kostlista! 🥦', title_vi = 'Dòng dưỡng chất đã tăng tốc!', body_vi = 'Hôm nay mẹ đã ăn gì bổ dưỡng? Xem danh sách Dinh dưỡng nhé! 🥦', title_zh = '营养输送加速了！', body_zh = '你今天吃了什么健康的东西？查看营养清单吧！🥦' WHERE id = '0e8f121b-aec8-4bf1-b771-2456d0bdda0c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Se chupa el dedo! 👍', body_es = 'En la ecografía puedes verle chupándose el pulgar. Es un entrenamiento del reflejo de succión para después del parto.', title_fr = 'Il suce son pouce ! 👍', body_fr = 'À l''échographie, vous pourrez peut-être le voir sucer son pouce. Il s''entraîne au réflexe de succion pour après la naissance.', title_hi = 'अँगूठा चूस रहा है! 👍', body_hi = 'अल्ट्रासाउंड में आप उसे अँगूठा चूसते देख सकती हैं। यह जन्म के बाद चूसने की आदत का अभ्यास है।', title_id = 'Ia mengisap jempol! 👍', body_id = 'Saat USG, Anda mungkin melihatnya mengisap jempol. Ini latihan refleks mengisap untuk setelah lahir.', title_ja = '指しゃぶりしています！👍', body_ja = 'エコー検査で、赤ちゃんが親指をしゃぶっている姿が見られるかも。生まれたあとの吸う反射の練習なのです。', title_ko = '손가락을 빨고 있어요! 👍', body_ko = '초음파 검사에서 아기가 엄지손가락을 빠는 모습을 볼 수도 있어요. 태어난 뒤 젖을 빠는 반사를 연습하는 거예요.', title_nl = 'Duimzuigen! 👍', body_nl = 'Bij een echo kun je je baby misschien op de duim zien zuigen. Zo oefent het de zuigreflex voor na de geboorte.', title_pl = 'Ssie kciuk! 👍', body_pl = 'Podczas USG możesz zobaczyć, jak ssie kciuk. To trening odruchu ssania po porodzie.', title_pt = 'Está a chuchar no dedo! 👍', body_pt = 'Na ecografia, pode vê-lo a chuchar no polegar. É um treino do reflexo de sucção para depois do nascimento.', title_sv = 'Barnet suger på tummen! 👍', body_sv = 'Vid ultraljudet kan du se barnet suga på tummen. Det är träning för sugreflexen efter födseln.', title_vi = 'Bé đang mút ngón tay! 👍', body_vi = 'Khi siêu âm, mẹ có thể thấy bé mút ngón cái. Đây là bài tập cho phản xạ bú sau khi sinh.', title_zh = '在吸手指！👍', body_zh = '做B超时，你可能会看到宝宝在吸大拇指。这是在练习出生后的吸吮反射。' WHERE id = 'e5a543f3-7d41-4d55-8690-ab14ba108363' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te gusta nadar? 🏊‍♀️', body_es = 'Vive dentro del agua. Para que el líquido amniótico esté limpio y abundante, tú también debes beber mucha agua durante el día.', title_fr = 'Vous aimez nager ? 🏊‍♀️', body_fr = 'Il vit dans l''eau. Pour que le liquide amniotique reste propre et abondant, buvez beaucoup d''eau tout au long de la journée.', title_hi = 'तैरना पसंद है? 🏊‍♀️', body_hi = 'वह पानी में रहता है। एम्नियोटिक द्रव साफ़ और भरपूर रहे, इसके लिए आपको दिन भर खूब पानी पीना चाहिए।', title_id = 'Suka berenang? 🏊‍♀️', body_id = 'Ia hidup di dalam air. Agar cairan ketuban tetap bersih dan cukup, Anda juga perlu banyak minum sepanjang hari.', title_ja = '泳ぐのは好き？🏊‍♀️', body_ja = '赤ちゃんは水の中で暮らしています。羊水をきれいにたっぷり保つために、1日を通してお水をたくさん飲みましょう。', title_ko = '수영 좋아하세요? 🏊‍♀️', body_ko = '아기는 물속에서 살아요. 양수가 깨끗하고 넉넉하도록 엄마도 하루 종일 물을 많이 드셔야 해요.', title_nl = 'Hou je van zwemmen? 🏊‍♀️', body_nl = 'Je baby leeft in het water. Drink de hele dag door veel water, zodat het vruchtwater schoon en ruim blijft.', title_pl = 'Lubisz pływać? 🏊‍♀️', body_pl = 'Ono żyje w wodzie. Aby płyn owodniowy był czysty i obfity, pij dużo wody w ciągu dnia.', title_pt = 'Gosta de nadar? 🏊‍♀️', body_pt = 'O bebé vive dentro de água. Para o líquido amniótico se manter limpo e abundante, beba muita água ao longo do dia.', title_sv = 'Gillar du att simma? 🏊‍♀️', body_sv = 'Barnet lever i vatten. För att fostervattnet ska vara rent och rikligt behöver du dricka mycket vatten under dagen.', title_vi = 'Mẹ thích bơi không? 🏊‍♀️', body_vi = 'Bé sống trong nước. Để nước ối sạch và dồi dào, mẹ cần uống nhiều nước trong ngày.', title_zh = '喜欢游泳吗？🏊‍♀️', body_zh = '宝宝生活在水里。为了让羊水干净又充足，你白天也要多喝水。' WHERE id = '1b07a663-2dbb-41a5-b9a0-2b4b252d015a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Sube la voz! 🗣️', body_es = 'Tu bebé ya oye con claridad tu voz y tus latidos. Empieza a cantarle nanas, le calman. 🎶', title_fr = 'Parlez plus fort ! 🗣️', body_fr = 'Bébé entend déjà clairement votre voix et les battements de votre cœur. Commencez à lui chanter des berceuses, cela l''apaise. 🎶', title_hi = 'आवाज़ ऊँची कीजिए! 🗣️', body_hi = 'बच्चा अब आपकी आवाज़ और दिल की धड़कन साफ़ सुनता है। उसे लोरी सुनाना शुरू कीजिए, इससे वह शांत होता है। 🎶', title_id = 'Keraskan suara Anda! 🗣️', body_id = 'Bayi sudah mendengar suara dan detak jantung Anda dengan jelas. Mulailah menyanyikan lagu nina bobo, itu menenangkannya. 🎶', title_ja = '声を聞かせて！🗣️', body_ja = '赤ちゃんはもうママの声や心臓の音をはっきり聞いています。子守唄を歌ってあげましょう。赤ちゃんが落ち着きます。🎶', title_ko = '목소리를 높여요! 🗣️', body_ko = '아기는 이제 엄마의 목소리와 심장 소리를 또렷하게 들어요. 자장가를 불러 주세요, 아기를 편안하게 해 줘요. 🎶', title_nl = 'Laat je stem horen! 🗣️', body_nl = 'Je baby hoort je stem en je hartslag al duidelijk. Begin met slaapliedjes zingen, dat werkt rustgevend. 🎶', title_pl = 'Mów głośniej! 🗣️', body_pl = 'Dziecko już wyraźnie słyszy twój głos i bicie serca. Zacznij śpiewać mu kołysanki, to je uspokaja. 🎶', title_pt = 'Fale mais alto! 🗣️', body_pt = 'O bebé já ouve com clareza a sua voz e o seu coração. Comece a cantar-lhe canções de embalar, isso acalma-o. 🎶', title_sv = 'Höj rösten! 🗣️', body_sv = 'Barnet hör nu tydligt din röst och dina hjärtslag. Börja sjunga vaggvisor, det lugnar barnet. 🎶', title_vi = 'Nói to lên nào! 🗣️', body_vi = 'Em bé đã nghe rõ giọng nói và nhịp tim của mẹ. Hãy bắt đầu hát ru cho bé, điều đó giúp bé bình tĩnh. 🎶', title_zh = '大声一点！🗣️', body_zh = '宝宝已经能清楚地听到你的声音和心跳了。开始给宝宝唱摇篮曲吧，这能让宝宝平静下来。🎶' WHERE id = '4e185ebb-b0f4-4552-9a03-4a4c79c95d4f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡La dama de hierro eres tú! 🦸‍♀️', body_es = 'Para evitar mareos, come carne roja o lentejas. Hay recetas en Nutrición.', title_fr = 'La Dame de fer, c''est vous ! 🦸‍♀️', body_fr = 'Pour éviter les vertiges, mangez de la viande rouge ou des lentilles. Vous trouverez des recettes dans la rubrique Nutrition.', title_hi = 'आयरन लेडी आप हैं! 🦸‍♀️', body_hi = 'चक्कर न आएँ, इसके लिए रेड मीट या दाल खाइए। पोषण में रेसिपी हैं।', title_id = 'Andalah Wanita Besi! 🦸‍♀️', body_id = 'Agar tidak pusing, makan daging merah atau lentil. Ada resepnya di bagian Nutrisi.', title_ja = 'アイアンレディはあなたです！🦸‍♀️', body_ja = 'めまいを防ぐために、赤身肉やレンズ豆を食べましょう。「栄養」にレシピがあります。', title_ko = '철의 여인은 바로 엄마예요! 🦸‍♀️', body_ko = '어지럽지 않도록 붉은 고기나 렌틸콩을 드세요. 영양 섹션에 레시피가 있어요.', title_nl = 'Jij bent de IJzeren Lady! 🦸‍♀️', body_nl = 'Eet rood vlees of linzen om duizeligheid te voorkomen. In Voeding vind je recepten.', title_pl = 'To ty jesteś Żelazną Damą! 🦸‍♀️', body_pl = 'Aby nie kręciło ci się w głowie, jedz czerwone mięso lub soczewicę. Przepisy są w sekcji Odżywianie.', title_pt = 'A Dama de Ferro é a mãe! 🦸‍♀️', body_pt = 'Para evitar tonturas, coma carne vermelha ou lentilhas. Há receitas na Nutrição.', title_sv = 'Du är en järnlady! 🦸‍♀️', body_sv = 'Ät rött kött eller linser för att slippa yrsel. Det finns recept i Kost.', title_vi = 'Mẹ chính là Người phụ nữ thép! 🦸‍♀️', body_vi = 'Để không bị chóng mặt, hãy ăn thịt đỏ hoặc đậu lăng. Mục Dinh dưỡng có công thức cho mẹ.', title_zh = '你就是铁娘子！🦸‍♀️', body_zh = '为了避免头晕，吃点红肉或扁豆吧。营养板块里有食谱。' WHERE id = '1228f5ed-c94b-45f8-bf5f-7e475683d6ed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te sangran las encías? 😬', body_es = 'Las hormonas vuelven sensibles las encías. Usa un cepillo suave y haz gárgaras con agua con sal.', title_fr = 'Vos gencives saignent ? 😬', body_fr = 'Les hormones rendent les gencives sensibles. Utilisez une brosse à dents souple et rincez-vous la bouche à l''eau salée.', title_hi = 'मसूड़ों से खून आता है? 😬', body_hi = 'हार्मोन मसूड़ों को संवेदनशील बना देते हैं। मुलायम ब्रश इस्तेमाल कीजिए और नमक वाले पानी से गरारे कीजिए।', title_id = 'Gusi berdarah? 😬', body_id = 'Hormon membuat gusi lebih sensitif. Gunakan sikat gigi lembut dan berkumur dengan air garam.', title_ja = '歯ぐきから出血？😬', body_ja = 'ホルモンの影響で歯ぐきが敏感になります。やわらかい歯ブラシを使い、塩水でうがいしましょう。', title_ko = '잇몸에서 피가 나나요? 😬', body_ko = '호르몬 때문에 잇몸이 예민해져요. 부드러운 칫솔을 쓰고 소금물로 가글하세요.', title_nl = 'Bloedend tandvlees? 😬', body_nl = 'Hormonen maken je tandvlees gevoelig. Gebruik een zachte tandenborstel en gorgel met zout water.', title_pl = 'Krwawią ci dziąsła? 😬', body_pl = 'Hormony uwrażliwiają dziąsła. Używaj miękkiej szczoteczki i płucz usta słoną wodą.', title_pt = 'As gengivas sangram? 😬', body_pt = 'As hormonas tornam as gengivas sensíveis. Use uma escova macia e bocheche com água e sal.', title_sv = 'Blöder tandköttet? 😬', body_sv = 'Hormonerna gör tandköttet känsligt. Använd en mjuk tandborste och skölj munnen med saltvatten.', title_vi = 'Lợi bị chảy máu? 😬', body_vi = 'Hormone khiến lợi nhạy cảm hơn. Hãy dùng bàn chải mềm và súc miệng bằng nước muối.', title_zh = '牙龈出血？😬', body_zh = '激素让牙龈变得敏感。用软毛牙刷，并用盐水漱口。' WHERE id = 'f99f033a-c9d9-464f-8a73-afdf2f8530ec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Te oigo, mamá! 👂', body_es = 'Los huesecillos del oído se endurecen. Ya reconoce el tono de tu voz, tu risa y tus latidos.', title_fr = 'Je vous entends, Maman ! 👂', body_fr = 'Les osselets de ses oreilles se solidifient. Il reconnaît déjà le ton de votre voix, votre rire et les battements de votre cœur.', title_hi = 'मैं आपको सुन रहा हूँ, माँ! 👂', body_hi = 'कान की हड्डियाँ मज़बूत हो रही हैं। वह अब आपकी आवाज़ का लहजा, हँसी और दिल की धड़कन पहचानता है।', title_id = 'Aku mendengarmu, Bunda! 👂', body_id = 'Tulang-tulang telinganya mengeras. Ia sudah mengenali nada suara, tawa, dan detak jantung Anda.', title_ja = 'ママの声、聞こえるよ！👂', body_ja = '耳の骨がしっかりしてきました。赤ちゃんはもうママの声のトーン、笑い声、心臓の音を聞き分けています。', title_ko = '엄마 목소리가 들려요! 👂', body_ko = '귓속뼈가 단단해지고 있어요. 아기는 벌써 엄마의 목소리 톤, 웃음소리, 심장 소리를 알아들어요.', title_nl = 'Ik hoor je, mama! 👂', body_nl = 'De gehoorbeentjes worden steviger. Je baby herkent al de toon van je stem, je lach en je hartslag.', title_pl = 'Słyszę cię, Mamo! 👂', body_pl = 'Kosteczki w uszach twardnieją. Już rozpoznaje ton twojego głosu, śmiech i bicie serca.', title_pt = 'Estou a ouvi-la, Mamã! 👂', body_pt = 'Os ossos do ouvido estão a ficar mais firmes. O bebé já reconhece o tom da sua voz, o seu riso e o seu coração.', title_sv = 'Jag hör dig, mamma! 👂', body_sv = 'Hörselbenen blir hårdare. Barnet känner redan igen tonen i din röst, ditt skratt och dina hjärtslag.', title_vi = 'Con nghe thấy mẹ rồi! 👂', body_vi = 'Xương tai đang cứng lại. Bé đã nhận ra giọng nói, tiếng cười và nhịp tim của mẹ.', title_zh = '妈妈，我听到你啦！👂', body_zh = '耳朵里的小骨头在变硬。宝宝已经能认出你的语调、笑声和心跳。' WHERE id = '5b358e1c-fd56-41ad-b947-12dea0b15c36' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'El esqueleto del bebé se fortalece🦴', body_es = 'Para que no agote tus reservas de calcio, toma leche, yogur o almendras.', title_fr = 'Le squelette de bébé se solidifie 🦴', body_fr = 'Pour qu''il n''épuise pas vos réserves de calcium, mangez du lait, du yaourt ou des amandes.', title_hi = 'बच्चे का कंकाल मज़बूत हो रहा है🦴', body_hi = 'ताकि वह आपके कैल्शियम का भंडार खत्म न कर दे, दूध, दही या बादाम खाइए।', title_id = 'Kerangka bayi mulai mengeras 🦴', body_id = 'Makan susu, yogurt, atau almon agar ia tidak menghabiskan cadangan kalsium Anda.', title_ja = '赤ちゃんの骨格がしっかりしてきた🦴', body_ja = 'ママのカルシウムが不足しないように、牛乳、ヨーグルト、アーモンドを食べましょう。', title_ko = '아기의 뼈대가 단단해지고 있어요🦴', body_ko = '엄마의 칼슘이 바닥나지 않도록 우유, 요거트나 아몬드를 드세요.', title_nl = 'Het skelet van je baby wordt steviger 🦴', body_nl = 'Eet melk, yoghurt of amandelen, zodat je calciumvoorraad niet opraakt.', title_pl = 'Szkielet dziecka twardnieje 🦴', body_pl = 'Jedz mleko, jogurt lub migdały, aby nie wyczerpało twoich zapasów wapnia.', title_pt = 'O esqueleto do bebé está a ficar mais firme🦴', body_pt = 'Para o bebé não esgotar as suas reservas de cálcio, coma leite, iogurte ou amêndoas.', title_sv = 'Barnets skelett blir hårdare🦴', body_sv = 'Ät mjölk, yoghurt eller mandlar så att barnet inte tömmer ditt kalciumförråd.', title_vi = 'Bộ xương của bé đang cứng cáp🦴', body_vi = 'Hãy ăn sữa, sữa chua hoặc hạnh nhân để bé không làm cạn dự trữ canxi của mẹ.', title_zh = '宝宝的骨骼在变硬 🦴', body_zh = '为了不让宝宝耗尽你的钙储备，喝点牛奶、酸奶或吃些杏仁吧。' WHERE id = 'e95b0195-5d3f-434c-9f11-c74aa50f4ba5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Duerme sobre el lado izquierdo 🛌', body_es = 'Dormir boca arriba puede dificultar la circulación. El lado izquierdo da más oxígeno a ti y a tu bebé.', title_fr = 'Dormez sur le côté gauche 🛌', body_fr = 'Dormir sur le dos peut gêner la circulation sanguine. Sur le côté gauche, vous et bébé recevez plus d''oxygène.', title_hi = 'बाईं करवट सोइए 🛌', body_hi = 'पीठ के बल सोने से रक्त संचार में दिक्कत हो सकती है। बाईं करवट आपको और बच्चे दोनों को ज़्यादा ऑक्सीजन देती है।', title_id = 'Tidurlah miring ke kiri 🛌', body_id = 'Tidur telentang bisa menghambat peredaran darah. Posisi miring ke kiri memberi lebih banyak oksigen untuk Anda dan bayi.', title_ja = '左側を下にして寝ましょう 🛌', body_ja = '仰向けに寝ると血の巡りが悪くなることがあります。左側を下にすると、ママにも赤ちゃんにもより多くの酸素が届きます。', title_ko = '왼쪽으로 누워 주무세요 🛌', body_ko = '똑바로 누우면 혈액 순환이 어려워질 수 있어요. 왼쪽으로 누우면 엄마와 아기 모두에게 산소가 더 많이 가요.', title_nl = 'Slaap op je linkerzij 🛌', body_nl = 'Op je rug slapen kan de bloedsomloop bemoeilijken. Op je linkerzij krijgen jij en je baby meer zuurstof.', title_pl = 'Śpij na lewym boku 🛌', body_pl = 'Spanie na plecach może utrudniać krążenie. Lewy bok daje więcej tlenu i tobie, i dziecku.', title_pt = 'Durma de lado, sobre o lado esquerdo 🛌', body_pt = 'Dormir de costas pode dificultar a circulação. O lado esquerdo dá mais oxigénio à mãe e ao bebé.', title_sv = 'Sov på vänster sida 🛌', body_sv = 'Att ligga på rygg kan försämra blodcirkulationen. Vänster sida ger mer syre både till dig och till barnet.', title_vi = 'Nằm nghiêng bên trái 🛌', body_vi = 'Nằm ngửa có thể cản trở tuần hoàn máu. Nằm nghiêng trái giúp cả mẹ và bé nhận nhiều oxy hơn.', title_zh = '向左侧睡 🛌', body_zh = '仰卧可能会影响血液循环。左侧卧能为你和宝宝提供更多氧气。' WHERE id = '22f8517a-e978-4689-beff-108150f23b01' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'El poder de las nueces y avellanas 🐿️', body_es = 'El omega-3 es importante para el desarrollo del cerebro. Lleva frutos secos en el bolso: sacian y alimentan la inteligencia de tu bebé.', title_fr = 'La force des noix 🐿️', body_fr = 'Les oméga-3 sont essentiels au développement du cerveau. Gardez des fruits secs dans votre sac : ils rassasient et nourrissent l''intelligence de bébé.', title_hi = 'अखरोट और हेज़लनट की ताकत 🐿️', body_hi = 'दिमाग के विकास के लिए ओमेगा-3 ज़रूरी है। बैग में मेवे रखिए: पेट भी भरा रहेगा और बच्चे की बुद्धि को पोषण भी मिलेगा।', title_id = 'Kekuatan kacang-kacangan 🐿️', body_id = 'Omega-3 penting untuk perkembangan otak. Bawa kacang di tas Anda: mengenyangkan sekaligus menutrisi kecerdasan bayi.', title_ja = 'クルミとヘーゼルナッツのパワー 🐿️', body_ja = 'オメガ3は脳の発達に大切です。バッグにナッツを入れておきましょう。お腹も満たされ、赤ちゃんの知能の栄養にもなります。', title_ko = '견과류 파워 🐿️', body_ko = '뇌 발달에 오메가-3가 중요해요. 가방에 견과류를 챙기세요. 든든하고 아기의 지능에도 영양을 줘요.', title_nl = 'De kracht van noten 🐿️', body_nl = 'Omega-3 is belangrijk voor de ontwikkeling van de hersenen. Neem noten mee in je tas: ze vullen en voeden het slimme koppie van je baby.', title_pl = 'Moc orzechów 🐿️', body_pl = 'Omega-3 jest ważne dla rozwoju mózgu. Noś orzechy w torebce: sycą i karmią inteligencję dziecka.', title_pt = 'O poder das nozes e avelãs 🐿️', body_pt = 'O ómega-3 é importante para o desenvolvimento do cérebro. Leve frutos secos na mala: saciam e alimentam a inteligência do bebé.', title_sv = 'Nötkraft 🐿️', body_sv = 'Omega-3 är viktigt för hjärnans utveckling. Ha nötter i väskan: de mättar och ger näring åt barnets intelligens.', title_vi = 'Sức mạnh của các loại hạt 🐿️', body_vi = 'Omega-3 rất quan trọng cho sự phát triển của não. Mang theo hạt trong túi: vừa no lâu, vừa nuôi dưỡng trí thông minh của bé.', title_zh = '坚果的力量 🐿️', body_zh = 'Omega-3对大脑发育很重要。包里带些坚果：既能顶饱，又能滋养宝宝的智力。' WHERE id = 'bc8843f7-6bd5-46ee-b8a3-e7c54310c8ea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Empieza la etapa dorada! ✨', body_es = '¡Enhorabuena! Has entrado en el 2.º trimestre. Tu energía aumenta y el riesgo baja. Ahora toca disfrutar del embarazo.', title_fr = 'L''âge d''or commence ! ✨', body_fr = 'Félicitations ! Vous entrez dans le 2e trimestre. Votre énergie augmente, le risque diminue. C''est le moment de profiter de votre grossesse.', title_hi = 'सुनहरा दौर शुरू! ✨', body_hi = 'बधाई हो! आप दूसरी तिमाही में पहुँच गईं। ऊर्जा बढ़ रही है, जोखिम घट रहा है। अब प्रेग्नेंसी का मज़ा लेने का समय है।', title_id = 'Masa keemasan dimulai! ✨', body_id = 'Selamat! Anda telah memasuki trimester ke-2. Energi bertambah, risiko berkurang. Kini saatnya menikmati kehamilan.', title_ja = '黄金期のスタート！✨', body_ja = 'おめでとうございます！妊娠中期に入りました。元気が出てきて、リスクも下がります。マタニティライフを楽しむときです。', title_ko = '황금기가 시작됐어요! ✨', body_ko = '축하해요! 임신 2기에 들어섰어요. 에너지는 늘고 위험은 줄어요. 이제 임신 기간을 즐길 때예요.', title_nl = 'De gouden periode is begonnen! ✨', body_nl = 'Gefeliciteerd! Je bent in het 2e trimester. Je energie neemt toe en het risico neemt af. Tijd om van je zwangerschap te genieten.', title_pl = 'Zaczął się złoty okres! ✨', body_pl = 'Gratulacje! Wkroczyłaś w 2. trymestr. Energii przybywa, ryzyko maleje. Teraz czas cieszyć się ciążą.', title_pt = 'Começou a fase dourada! ✨', body_pt = 'Parabéns! Entrou no 2.º trimestre. A energia aumenta e o risco diminui. Agora é hora de aproveitar a gravidez.', title_sv = 'Den gyllene perioden har börjat! ✨', body_sv = 'Grattis! Du har klivit in i andra trimestern. Energin ökar och risken minskar. Nu är det dags att njuta av graviditeten.', title_vi = 'Thời kỳ vàng đã bắt đầu! ✨', body_vi = 'Chúc mừng mẹ! Mẹ đã bước sang tam cá nguyệt thứ 2. Năng lượng tăng, rủi ro giảm. Giờ là lúc tận hưởng thai kỳ.', title_zh = '黄金期开始啦！✨', body_zh = '恭喜！你进入孕中期了。精力在恢复，风险在降低。现在该好好享受孕期了。' WHERE id = '6b4229bd-ff86-4124-a6db-5ad3cc3444fe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Hace falta una bomba de energía 💥', body_es = 'El bebé crece rápido. Carne roja, huevos o legumbres... No olvides reponer tus reservas de hierro y proteína.', title_fr = 'Besoin d''un coup de boost 💥', body_fr = 'Bébé grandit vite. Viande rouge, œufs ou légumineuses... N''oubliez pas de refaire le plein de fer et de protéines.', title_hi = 'एनर्जी बूस्ट चाहिए 💥', body_hi = 'बच्चा तेज़ी से बढ़ रहा है। रेड मीट, अंडे या दालें... आयरन और प्रोटीन का भंडार भरना न भूलें।', title_id = 'Butuh ledakan energi 💥', body_id = 'Bayi tumbuh dengan cepat. Daging merah, telur, atau kacang-kacangan... Jangan lupa penuhi cadangan zat besi dan protein.', title_ja = 'エネルギーチャージが必要 💥', body_ja = '赤ちゃんはぐんぐん成長しています。赤身肉、卵、豆類...鉄分とたんぱく質の補給を忘れずに。', title_ko = '에너지 폭탄이 필요해요 💥', body_ko = '아기가 빠르게 자라고 있어요. 붉은 고기, 달걀, 콩류... 철분과 단백질을 꼭 채워 주세요.', title_nl = 'Een energieboost nodig 💥', body_nl = 'Je baby groeit snel. Rood vlees, eieren of peulvruchten... Vergeet niet je ijzer- en eiwitvoorraad aan te vullen.', title_pl = 'Potrzebna bomba energetyczna 💥', body_pl = 'Dziecko szybko rośnie. Czerwone mięso, jajka czy rośliny strączkowe... Nie zapomnij uzupełnić żelaza i białka.', title_pt = 'Precisa de uma bomba de energia 💥', body_pt = 'O bebé cresce depressa. Carne vermelha, ovos ou leguminosas... Não se esqueça de repor as reservas de ferro e proteína.', title_sv = 'Du behöver en energibomb 💥', body_sv = 'Barnet växer snabbt. Rött kött, ägg eller baljväxter... Glöm inte att fylla på järn- och proteinförrådet.', title_vi = 'Cần một quả bom năng lượng 💥', body_vi = 'Em bé đang lớn rất nhanh. Thịt đỏ, trứng hay các loại đậu... Đừng quên bổ sung dự trữ sắt và protein nhé.', title_zh = '需要一颗能量炸弹 💥', body_zh = '宝宝在快速成长。红肉、鸡蛋或豆类……别忘了补充铁和蛋白质储备。' WHERE id = '0e5bf60f-0c98-4770-8559-a9df3a31089c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Es como un limón! 🍋', body_es = 'Mide unos 7-8 cm. Ya puede girar la cabeza y fruncir el ceño. ¡Sus gestos se están desarrollando!', title_fr = 'Il est grand comme un citron ! 🍋', body_fr = 'Environ 7-8 cm. Il peut déjà tourner la tête et froncer les sourcils. Ses mimiques se développent !', title_hi = 'नींबू जितना है! 🍋', body_hi = 'लगभग 7-8 cm। अब वह सिर घुमा सकता है, भौंहें सिकोड़ सकता है। उसके हाव-भाव विकसित हो रहे हैं!', title_id = 'Seukuran lemon! 🍋', body_id = 'Sekitar 7-8 cm. Ia sudah bisa memutar kepala dan mengerutkan dahi. Ekspresi wajahnya berkembang!', title_ja = 'レモンくらいの大きさ！🍋', body_ja = '約7-8 cm。もう頭を動かしたり、しかめっつらをしたりできます。表情が豊かになってきています！', title_ko = '레몬만 해요! 🍋', body_ko = '약 7-8cm예요. 벌써 고개를 돌리고 얼굴을 찡그릴 수 있어요. 표정이 발달하고 있어요!', title_nl = 'Zo groot als een citroen! 🍋', body_nl = 'Ongeveer 7-8 cm. Je baby kan al het hoofdje draaien en fronsen. De mimiek ontwikkelt zich!', title_pl = 'Jest wielkości cytryny! 🍋', body_pl = 'Około 7-8 cm. Już potrafi obrócić główkę i zmarszczyć brwi. Rozwija się mimika!', title_pt = 'Já é do tamanho de um limão! 🍋', body_pt = 'Cerca de 7-8 cm. Já consegue virar a cabeça e franzir a testa. As expressões faciais estão a desenvolver-se!', title_sv = 'Lika stor som en citron! 🍋', body_sv = 'Ungefär 7-8 cm. Barnet kan redan vrida på huvudet och rynka pannan. Ansiktsuttrycken utvecklas!', title_vi = 'To bằng quả chanh vàng! 🍋', body_vi = 'Khoảng 7-8 cm. Bé đã biết quay đầu, nhăn mặt. Biểu cảm của bé đang phát triển!', title_zh = '有一个柠檬那么大！🍋', body_zh = '大约7-8 cm。宝宝已经会转头、皱眉了，表情越来越丰富！' WHERE id = 'f6a83ba0-02bc-4279-b4c0-86ed3ee5b0ed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Revisa tu armario 👗', body_es = '¿No se abrochan los botones? Guarda los pantalones ajustados. Pásate a ropa holgada, cómoda y de tejidos naturales.', title_fr = 'Faites le tri dans votre armoire 👗', body_fr = 'Les boutons ne ferment plus ? Rangez les pantalons serrés. Passez à des vêtements amples, confortables et en tissus naturels.', title_hi = 'अपनी अलमारी पर नज़र डालिए 👗', body_hi = 'बटन नहीं लग रहे? टाइट पैंट रख दीजिए। ढीले, आरामदायक और प्राकृतिक कपड़े के कपड़े पहनिए।', title_id = 'Periksa lemari pakaian Anda 👗', body_id = 'Kancing tidak bisa ditutup? Simpan celana ketat. Beralihlah ke pakaian longgar dan nyaman dari bahan alami.', title_ja = 'クローゼットを見直そう 👗', body_ja = 'ボタンがとまらない？きついズボンはしまって、ゆったりとした天然素材の服に切り替えましょう。', title_ko = '옷장을 점검해 보세요 👗', body_ko = '단추가 안 잠기나요? 꽉 끼는 바지는 치워 두세요. 넉넉하고 편안한 천연 소재 옷으로 바꿔요.', title_nl = 'Neem je kledingkast eens door 👗', body_nl = 'Gaan de knopen niet meer dicht? Berg die strakke broeken op. Kies voor ruime, comfortabele kleding van natuurlijke stoffen.', title_pl = 'Przejrzyj szafę 👗', body_pl = 'Guziki się nie dopinają? Odłóż obcisłe spodnie. Przejdź na luźne, wygodne ubrania z naturalnych tkanin.', title_pt = 'Dê uma vista de olhos ao roupeiro 👗', body_pt = 'Os botões não fecham? Arrume as calças apertadas. Passe para roupa larga, confortável e de tecidos naturais.', title_sv = 'Gå igenom garderoben 👗', body_sv = 'Går knapparna inte att knäppa? Lägg undan de trånga byxorna. Byt till vida, bekväma kläder i naturmaterial.', title_vi = 'Xem lại tủ quần áo nào 👗', body_vi = 'Cúc áo không cài được nữa? Cất những chiếc quần bó đi. Hãy chuyển sang quần áo rộng rãi, thoải mái từ vải tự nhiên.', title_zh = '整理一下衣柜吧 👗', body_zh = '扣子扣不上了？把紧身裤收起来，换上宽松舒适的天然面料衣服吧。' WHERE id = '1a084eb2-2d29-44b6-a691-ad102b5c44de' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Niña o niño? 🩷💙', body_es = 'Los órganos sexuales terminan de formarse. Aunque cueste verlo en la ecografía, ¡ya sabe quién es! ¿Tú qué crees?', title_fr = 'Fille ou garçon ? 🩷💙', body_fr = 'Les organes génitaux finissent de se former. Même si c''est difficile à voir à l''échographie, lui sait déjà qui il est ! À votre avis ?', title_hi = 'लड़की या लड़का? 🩷💙', body_hi = 'जननांग पूरी तरह बन रहे हैं। अल्ट्रासाउंड में देखना मुश्किल हो सकता है, पर वह जानता है कि वह कौन है! आपको क्या लगता है?', title_id = 'Perempuan atau Laki-laki? 🩷💙', body_id = 'Organ kelaminnya terbentuk sempurna. Meski sulit terlihat di USG, ia sudah tahu siapa dirinya! Menurut Anda yang mana?', title_ja = '女の子？それとも男の子？🩷💙', body_ja = '生殖器がすっかり形づくられています。エコーではまだ見えにくくても、赤ちゃん自身はもう知っています！どちらだと思いますか？', title_ko = '딸일까요, 아들일까요? 🩷💙', body_ko = '생식기가 완전히 만들어지고 있어요. 초음파로는 아직 보기 어려워도 아기는 이미 자기가 누군지 알아요! 어느 쪽일 것 같아요?', title_nl = 'Meisje of jongen? 🩷💙', body_nl = 'De geslachtsorganen zijn volledig gevormd. Op de echo is het nog lastig te zien, maar je baby weet al wie het is! Wat denk jij?', title_pl = 'Dziewczynka czy chłopiec? 🩷💙', body_pl = 'Narządy płciowe w pełni się kształtują. Choć na USG trudno to zobaczyć, ono już wie, kim jest! Jak myślisz?', title_pt = 'Menina ou menino? 🩷💙', body_pt = 'Os órgãos genitais estão a formar-se por completo. Mesmo que seja difícil ver na ecografia, o bebé já sabe quem é! O que acha que é?', title_sv = 'Flicka eller pojke? 🩷💙', body_sv = 'Könsorganen är färdigbildade. Även om det är svårt att se på ultraljudet vet barnet redan vem det är! Vad tror du?', title_vi = 'Con gái hay Con trai? 🩷💙', body_vi = 'Cơ quan sinh dục đang hình thành hoàn chỉnh. Dù khó thấy trên siêu âm, bé đã biết mình là ai! Mẹ đoán là gì?', title_zh = '女孩还是男孩？🩷💙', body_zh = '生殖器官正在完全形成。虽然B超上可能还难以看出，宝宝已经知道自己是谁了！你猜是哪个？' WHERE id = '0b20c112-5b84-42c9-aa1a-637151b2cd33' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Día de spa? ✨', body_es = 'La piel del bebé se cubre con una crema especial para no arrugarse en el agua. ¿Y tú? ¡Dedícate tiempo hoy! 💆‍♀️', title_fr = 'Journée spa ? ✨', body_fr = 'La peau de bébé se couvre d''une crème spéciale pour ne pas se rider dans l''eau. Et vous ? Prenez du temps pour vous aujourd''hui ! 💆‍♀️', title_hi = 'SPA का दिन? ✨', body_hi = 'बच्चे की त्वचा पानी में सिकुड़े नहीं, इसलिए वह एक खास क्रीम से ढकी होती है। और आप? आज अपने लिए समय निकालिए! 💆‍♀️', title_id = 'Hari spa? ✨', body_id = 'Kulit bayi dilapisi krem khusus agar tidak keriput di dalam air. Bagaimana dengan Anda? Luangkan waktu untuk diri sendiri hari ini! 💆‍♀️', title_ja = 'スパの日？✨', body_ja = '赤ちゃんの肌は、水の中でふやけないように特別なクリームで覆われています。ママは？今日は自分のための時間をとりましょう！💆‍♀️', title_ko = '스파 데이 어때요? ✨', body_ko = '아기의 피부는 물속에서 쭈글쭈글해지지 않도록 특별한 크림으로 덮여 있어요. 엄마는요? 오늘은 나를 위한 시간을 가져 보세요! 💆‍♀️', title_nl = 'Tijd voor een spadag? ✨', body_nl = 'De huid van je baby wordt bedekt met een speciale crème, zodat die niet rimpelt in het water. En jij? Neem vandaag tijd voor jezelf! 💆‍♀️', title_pl = 'Dzień SPA? ✨', body_pl = 'Skóra dziecka pokrywa się specjalnym kremem, by nie marszczyła się w wodzie. A ty? Znajdź dziś czas dla siebie! 💆‍♀️', title_pt = 'Dia de spa? ✨', body_pt = 'A pele do bebé está coberta por um creme especial para não enrugar na água. E a mãe? Reserve hoje tempo para si! 💆‍♀️', title_sv = 'Spadag? ✨', body_sv = 'Barnets hud täcks av en särskild kräm så att den inte blir skrynklig i vattnet. Och du? Ta tid för dig själv i dag! 💆‍♀️', title_vi = 'Ngày SPA nhé? ✨', body_vi = 'Da bé được phủ một lớp kem đặc biệt để không bị nhăn trong nước. Còn mẹ thì sao? Hôm nay dành thời gian cho bản thân nhé! 💆‍♀️', title_zh = '今天是SPA日吗？✨', body_zh = '为了不在水里泡皱，宝宝的皮肤上覆盖着一层特殊的“护肤霜”。那你呢？今天给自己留点时间吧！💆‍♀️' WHERE id = '000cbfe1-b7f7-4d1c-8e2e-4509f7ace829' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡He visto la luz! 💡', body_es = 'Aunque tiene los párpados cerrados, nota la luz intensa. Si iluminas tu barriga con una linterna, puede girar la cara.', title_fr = 'J''ai vu la lumière ! 💡', body_fr = 'Même avec les paupières fermées, il perçoit une lumière forte. Si vous éclairez votre ventre avec une lampe, il peut détourner le visage.', title_hi = 'मुझे रोशनी दिखी! 💡', body_hi = 'पलकें बंद होने पर भी वह तेज़ रोशनी महसूस करता है। पेट पर टॉर्च डालें, तो वह चेहरा घुमा सकता है।', title_id = 'Aku melihat cahaya! 💡', body_id = 'Meski kelopak matanya tertutup, ia merasakan cahaya terang. Jika Anda menyorotkan senter ke perut, ia mungkin memalingkan wajah.', title_ja = '光が見えたよ！💡', body_ja = 'まぶたは閉じていても、赤ちゃんは強い光を感じます。お腹にライトを当てると、顔をそむけるかもしれません。', title_ko = '빛이 보여요! 💡', body_ko = '눈꺼풀은 감겨 있어도 강한 빛은 느껴요. 배에 손전등을 비추면 얼굴을 돌릴 수도 있어요.', title_nl = 'Ik zie het licht! 💡', body_nl = 'Ook met gesloten oogleden voelt je baby fel licht. Schijn je met een zaklamp op je buik, dan kan het zich afwenden.', title_pl = 'Widzę światło! 💡', body_pl = 'Choć ma zamknięte powieki, czuje mocne światło. Jeśli poświecisz latarką na brzuch, może odwrócić buzię.', title_pt = 'Vi a luz! 💡', body_pt = 'Mesmo com as pálpebras fechadas, o bebé sente a luz forte. Se apontar uma lanterna à barriga, pode virar o rosto.', title_sv = 'Jag ser ljuset! 💡', body_sv = 'Även med slutna ögonlock känner barnet starkt ljus. Om du lyser med en ficklampa på magen kan det vända bort ansiktet.', title_vi = 'Con thấy ánh sáng rồi! 💡', body_vi = 'Dù mí mắt vẫn nhắm, bé đã cảm nhận được ánh sáng mạnh. Nếu mẹ chiếu đèn pin vào bụng, bé có thể quay mặt đi.', title_zh = '我看到光啦！💡', body_zh = '虽然眼睑还闭着，宝宝已经能感觉到强光。如果你用手电筒照肚子，宝宝可能会把脸转开。' WHERE id = 'bec50930-1201-4fc9-8c19-535459114067' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Dónde están las llaves? 🔑', body_es = 'Los olvidos son normales. Tu cerebro está ocupado con algo más importante: ¡crear a un ser humano! Empieza a hacer listas.', title_fr = 'Où sont les clés ? 🔑', body_fr = 'Les trous de mémoire sont normaux. Votre cerveau est occupé à une tâche bien plus importante : créer un être humain ! Commencez à faire des listes.', title_hi = 'चाबी कहाँ है? 🔑', body_hi = 'भूलना सामान्य है। आपका दिमाग अभी ज़्यादा ज़रूरी काम में लगा है: एक इंसान बना रहा है! लिस्ट बनाना शुरू कीजिए।', title_id = 'Kuncinya di mana? 🔑', body_id = 'Mudah lupa itu normal. Otak Anda sedang sibuk dengan tugas yang lebih penting: menciptakan manusia! Mulailah membuat daftar.', title_ja = '鍵はどこ？🔑', body_ja = 'もの忘れは普通のこと。脳は今、もっと大切な仕事をしています。人間をつくっているのです！リストを書く習慣をつけましょう。', title_ko = '열쇠가 어디 있지? 🔑', body_ko = '깜빡하는 건 정상이에요. 지금 뇌는 더 중요한 일을 하고 있거든요. 바로 사람을 만드는 일이요! 목록을 적어 보세요.', title_nl = 'Waar zijn de sleutels? 🔑', body_nl = 'Vergeetachtigheid is normaal. Je hersenen zijn nu met iets veel belangrijkers bezig: een mens maken! Begin met lijstjes.', title_pl = 'Gdzie są klucze? 🔑', body_pl = 'Zapominanie jest normalne. Twój mózg zajmuje się teraz czymś ważniejszym: tworzy człowieka! Zacznij robić listy.', title_pt = 'Onde estão as chaves? 🔑', body_pt = 'Os esquecimentos são normais. O seu cérebro está ocupado com algo mais importante: criar um ser humano! Comece a fazer listas.', title_sv = 'Var är nycklarna? 🔑', body_sv = 'Glömska är normalt. Din hjärna är upptagen med något viktigare just nu: att skapa en människa! Börja skriva listor.', title_vi = 'Chìa khóa đâu rồi? 🔑', body_vi = 'Hay quên là bình thường. Não mẹ giờ đang bận một việc quan trọng hơn: tạo ra một con người! Hãy bắt đầu ghi danh sách nhé.', title_zh = '钥匙放哪儿了？🔑', body_zh = '健忘很正常。你的大脑正忙着更重要的事：创造一个人！开始列清单吧。' WHERE id = 'fcdb41b2-8b6a-4d75-be79-f72070d4756a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Calambres en las piernas? 🦵', body_es = 'Puede faltarte magnesio y calcio. Come plátano, almendras o yogur. ¡Y no olvides beber mucha agua!', title_fr = 'Des crampes aux jambes ? 🦵', body_fr = 'Il peut s''agir d''un manque de magnésium et de calcium. Mangez des bananes, des amandes ou du yaourt. Et buvez beaucoup d''eau !', title_hi = 'पैरों में ऐंठन? 🦵', body_hi = 'मैग्नीशियम और कैल्शियम की कमी हो सकती है। केला, बादाम या दही खाइए। खूब पानी पीना भी न भूलें!', title_id = 'Kaki kram? 🦵', body_id = 'Mungkin Anda kekurangan magnesium dan kalsium. Makan pisang, almon, atau yogurt. Jangan lupa banyak minum air!', title_ja = '脚がつりますか？🦵', body_ja = 'マグネシウムやカルシウムが不足しているのかもしれません。バナナ、アーモンド、ヨーグルトを食べましょう。お水をたっぷり飲むのも忘れずに！', title_ko = '다리에 쥐가 나나요? 🦵', body_ko = '마그네슘과 칼슘이 부족할 수 있어요. 바나나, 아몬드, 요거트를 드세요. 물도 충분히 마시는 것 잊지 마세요!', title_nl = 'Krampen in je benen? 🦵', body_nl = 'Dat kan door een tekort aan magnesium en calcium komen. Eet banaan, amandelen of yoghurt. En vergeet niet veel water te drinken!', title_pl = 'Łapią cię skurcze nóg? 🦵', body_pl = 'To może być niedobór magnezu i wapnia. Jedz banany, migdały lub jogurt. Pamiętaj też, by pić dużo wody!', title_pt = 'Cãibras nas pernas? 🦵', body_pt = 'Pode haver falta de magnésio e cálcio. Coma banana, amêndoas ou iogurte. E não se esqueça de beber muita água!', title_sv = 'Får du kramp i benen? 🦵', body_sv = 'Det kan bero på brist på magnesium och kalcium. Ät banan, mandlar eller yoghurt. Glöm inte heller att dricka mycket vatten!', title_vi = 'Bị chuột rút chân? 🦵', body_vi = 'Có thể mẹ đang thiếu Magie và Canxi. Hãy ăn chuối, hạnh nhân hoặc sữa chua. Đừng quên uống nhiều nước nhé!', title_zh = '腿抽筋了？🦵', body_zh = '可能是缺镁和钙。吃点香蕉、杏仁或酸奶，也别忘了多喝水！' WHERE id = '2ac8ff81-e925-4d31-8ac2-6b55896aedfb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Es como una pera! 🍐', body_es = 'Se alarga y su cuerpo se endereza. Ya puede mantener la cabeza totalmente erguida. ¡Él crece y tú estás más guapa!', title_fr = 'Il est grand comme une poire ! 🍐', body_fr = 'Il s''allonge et son corps se redresse. Il peut déjà bien tenir sa tête droite. Il grandit, et vous embellissez !', title_hi = 'नाशपाती जितना है! 🍐', body_hi = 'उसकी लंबाई बढ़ रही है, शरीर सीधा हो रहा है। अब वह सिर पूरी तरह सीधा रख सकता है। वह बढ़ रहा है, आप निखर रही हैं!', title_id = 'Seukuran buah pir! 🍐', body_id = 'Tubuhnya memanjang dan makin tegak. Ia sudah bisa menegakkan kepala sepenuhnya. Ia tumbuh, Anda makin cantik!', title_ja = '洋ナシくらいの大きさ！🍐', body_ja = '背が伸びて、体がまっすぐになってきました。もう頭をしっかり起こせます。赤ちゃんは大きくなり、ママはきれいになっていきます！', title_ko = '배만큼 컸어요! 🍐', body_ko = '키가 자라고 몸이 곧게 펴지고 있어요. 이제 고개를 완전히 들 수 있어요. 아기는 자라고, 엄마는 더 아름다워져요!', title_nl = 'Zo groot als een peer! 🍐', body_nl = 'Je baby wordt langer en het lijfje strekt zich. Het kan het hoofdje al helemaal rechtop houden. Je baby groeit en jij straalt!', title_pl = 'Jest wielkości gruszki! 🍐', body_pl = 'Rośnie i się prostuje. Już potrafi w pełni utrzymać główkę. Ono rośnie, a ty pięknieje!', title_pt = 'Do tamanho de uma pera! 🍐', body_pt = 'O bebé está a crescer e o corpo a endireitar-se. Já consegue manter a cabeça bem erguida. Ele cresce e a mãe fica mais bonita!', title_sv = 'Lika stor som ett päron! 🍐', body_sv = 'Barnet blir längre och kroppen rätar på sig. Nu kan det hålla huvudet helt upprätt. Barnet växer och du blir allt vackrare!', title_vi = 'To bằng quả lê rồi! 🍐', body_vi = 'Bé dài ra, cơ thể thẳng hơn. Giờ bé đã giữ được đầu thẳng hoàn toàn. Bé lớn lên, còn mẹ thì ngày càng xinh đẹp!', title_zh = '有一个梨那么大！🍐', body_zh = '宝宝在长高，身体越来越挺直，已经能把头完全抬起来了。宝宝在长大，你也越来越美！' WHERE id = '937d5186-cb49-4a6c-a7a2-0e5731c4ae78' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Sientes tirantez en la barriga? 😣', body_es = 'Evita los movimientos bruscos. Una ducha tibia o un masaje suave pueden aliviar el dolor.', title_fr = 'Votre ventre tire ? 😣', body_fr = 'Évitez les mouvements brusques. Une douche tiède ou un massage léger peuvent soulager la douleur.', title_hi = 'पेट में खिंचाव है? 😣', body_hi = 'अचानक हरकत मत कीजिए। गुनगुने पानी से नहाना या हल्की मालिश दर्द कम कर सकती है।', title_id = 'Perut terasa tertarik? 😣', body_id = 'Hindari gerakan mendadak. Mandi air hangat atau pijatan ringan bisa mengurangi rasa sakit.', title_ja = 'お腹が張る？😣', body_ja = '急な動きは避けましょう。ぬるめのシャワーや軽いマッサージで痛みがやわらぐことがあります。', title_ko = '배가 당기나요? 😣', body_ko = '갑자기 움직이지 마세요. 따뜻한 샤워나 가벼운 마사지가 통증을 덜어 줄 수 있어요.', title_nl = 'Trekt je buik? 😣', body_nl = 'Maak geen plotselinge bewegingen. Een warme douche of een lichte massage kan de pijn verlichten.', title_pl = 'Brzuch się napina? 😣', body_pl = 'Unikaj gwałtownych ruchów. Ciepły prysznic lub delikatny masaż mogą złagodzić ból.', title_pt = 'A barriga está a esticar? 😣', body_pt = 'Evite movimentos bruscos. Um duche morno ou uma massagem leve podem aliviar a dor.', title_sv = 'Spänner magen? 😣', body_sv = 'Undvik hastiga rörelser. En ljummen dusch eller lätt massage kan lindra smärtan.', title_vi = 'Bụng bị căng? 😣', body_vi = 'Đừng cử động đột ngột. Tắm nước ấm hoặc xoa bóp nhẹ có thể giúp giảm đau.', title_zh = '肚子发紧？😣', body_zh = '不要突然动作。温水澡或轻柔按摩可以缓解疼痛。' WHERE id = '77993f33-af63-4a22-9cb2-3af058c96f19' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Las huellas dactilares están listas! 🖐️', body_es = 'Esos dibujos únicos que nadie más en el mundo tiene ya se han formado. Ya es un individuo. ¿No es maravilloso?', title_fr = 'Les empreintes digitales sont prêtes ! 🖐️', body_fr = 'Ces motifs uniques, que personne d''autre au monde ne possède, sont déjà formés. C''est déjà une personne à part entière. Magnifique, non ?', title_hi = 'फ़िंगरप्रिंट तैयार! 🖐️', body_hi = 'दुनिया में किसी और के पास न होने वाले वे अनोखे निशान बन चुके हैं। वह अभी से एक अलग इंसान है। कमाल है ना?', title_id = 'Sidik jari sudah jadi! 🖐️', body_id = 'Pola unik yang tidak dimiliki siapa pun di dunia sudah terbentuk. Ia sudah menjadi pribadi sejak sekarang. Luar biasa, bukan?', title_ja = '指紋が完成！🖐️', body_ja = '世界で誰も持っていない、ユニークな模様がもうできあがりました。赤ちゃんはもう一人の個性ある人です。すばらしいと思いませんか？', title_ko = '지문이 완성됐어요! 🖐️', body_ko = '세상에 누구도 가지지 않은 그 고유한 무늬가 이미 생겼어요. 아기는 벌써 한 사람이에요. 놀랍지 않나요?', title_nl = 'De vingerafdrukken zijn klaar! 🖐️', body_nl = 'Die unieke patronen die niemand anders ter wereld heeft, zijn al gevormd. Je baby is nu al een individu. Geweldig toch?', title_pl = 'Odciski palców gotowe! 🖐️', body_pl = 'Ukształtowały się już te wyjątkowe wzory, jakich nie ma nikt na świecie. Już teraz jest odrębną osobą. Wspaniałe, prawda?', title_pt = 'As impressões digitais estão prontas! 🖐️', body_pt = 'Aqueles padrões únicos, que mais ninguém no mundo tem, já se formaram. O bebé já é um indivíduo. Não é fantástico?', title_sv = 'Fingeravtrycken är klara! 🖐️', body_sv = 'De unika mönstren som ingen annan i världen har är redan formade. Barnet är redan en egen individ. Fantastiskt, eller hur?', title_vi = 'Dấu vân tay đã sẵn sàng! 🖐️', body_vi = 'Những đường vân độc nhất, không ai trên thế giới có, đã hình thành. Bé đã là một cá thể riêng biệt. Thật tuyệt vời phải không?', title_zh = '指纹已完成！🖐️', body_zh = '那些世上独一无二的纹路已经形成了。宝宝从现在起就是一个独立的个体。是不是很神奇？' WHERE id = '0cc5cbcc-4e89-43b3-8303-b5765d583930' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te entra hambre enseguida? 😋', body_es = 'Tener más apetito es genial, pero comer por dos es un mito. Elige calorías de calidad: nueces, fruta, verduras.', title_fr = 'Vous avez vite faim ? 😋', body_fr = 'Un appétit qui augmente, c''est très bien, mais manger pour deux est un mythe. Choisissez des calories de qualité : noix, fruits, légumes.', title_hi = 'जल्दी भूख लगती है? 😋', body_hi = 'भूख बढ़ना बढ़िया है, पर दो लोगों का खाना एक मिथक है। अच्छी कैलोरी चुनिए: अखरोट, फल, सब्ज़ियाँ।', title_id = 'Cepat lapar? 😋', body_id = 'Nafsu makan meningkat itu bagus, tapi makan untuk dua orang itu mitos. Pilih kalori berkualitas: kacang kenari, buah, sayuran.', title_ja = 'すぐにお腹がすく？😋', body_ja = '食欲が増えるのはいいことですが、「2人分食べる」は迷信です。質のいいカロリーを選んで：ナッツ、果物、野菜。', title_ko = '금방 배가 고프세요? 😋', body_ko = '식욕이 느는 건 좋지만, 2인분 식사는 잘못된 상식이에요. 좋은 칼로리를 고르세요. 호두, 과일, 채소.', title_nl = 'Snel weer honger? 😋', body_nl = 'Meer eetlust is prima, maar eten voor twee is een mythe. Kies voor goede calorieën: noten, fruit, groente.', title_pl = 'Szybko robisz się głodna? 😋', body_pl = 'Większy apetyt jest super, ale jedzenie za dwoje to mit. Wybieraj wartościowe kalorie: orzechy, owoce, warzywa.', title_pt = 'Fica com fome depressa? 😋', body_pt = 'O aumento do apetite é ótimo, mas comer por dois é um mito. Escolha calorias de qualidade: nozes, fruta, legumes.', title_sv = 'Blir du snabbt hungrig? 😋', body_sv = 'Ökad aptit är toppen, men att äta för två är en myt. Välj kalorier av god kvalitet: nötter, frukt, grönsaker.', title_vi = 'Mẹ mau đói? 😋', body_vi = 'Ăn ngon miệng hơn là điều tốt, nhưng ăn cho hai người chỉ là lời đồn. Hãy chọn calo chất lượng: hạt óc chó, trái cây, rau.', title_zh = '总是很快就饿？😋', body_zh = '胃口变好很棒，但“一人吃两人补”是误区。选择优质热量：坚果、水果、蔬菜。' WHERE id = 'f36e06df-bab1-456a-b2ec-00d5e38377c7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Nariz tapada? 🤧', body_es = 'No estás enferma, es rinitis del embarazo. Usa un espray de agua salina y humidifica el aire de la habitación.', title_fr = 'Le nez bouché ? 🤧', body_fr = 'Vous n''êtes pas malade, c''est la rhinite de grossesse. Utilisez un spray d''eau salée et humidifiez l''air de la pièce.', title_hi = 'नाक बंद है? 🤧', body_hi = 'आप बीमार नहीं हैं, यह प्रेग्नेंसी राइनाइटिस है। सलाइन स्प्रे इस्तेमाल कीजिए और कमरे की हवा में नमी रखिए।', title_id = 'Hidung tersumbat? 🤧', body_id = 'Anda tidak sakit, ini rinitis kehamilan. Gunakan semprotan air garam dan lembapkan udara di kamar.', title_ja = '鼻がつまっていますか？🤧', body_ja = '風邪ではなく、妊娠性鼻炎です。生理食塩水のスプレーを使い、部屋を加湿しましょう。', title_ko = '코가 막히나요? 🤧', body_ko = '아픈 게 아니라 임신성 비염이에요. 식염수 스프레이를 쓰고 방을 촉촉하게 해 주세요.', title_nl = 'Verstopte neus? 🤧', body_nl = 'Je bent niet ziek, dit is zwangerschapsrinitis. Gebruik een zoutwaterspray en maak de lucht in je kamer vochtiger.', title_pl = 'Masz zatkany nos? 🤧', body_pl = 'Nie jesteś chora, to ciążowy nieżyt nosa. Używaj sprayu z solą morską i nawilżaj powietrze w pokoju.', title_pt = 'Nariz entupido? 🤧', body_pt = 'Não está doente, é rinite da gravidez. Use um spray de água salgada e humidifique o ar do quarto.', title_sv = 'Täppt i näsan? 🤧', body_sv = 'Du är inte sjuk, det är graviditetsrinit. Använd koksaltspray och fukta luften i rummet.', title_vi = 'Bị nghẹt mũi? 🤧', body_vi = 'Mẹ không ốm đâu, đây là viêm mũi thai kỳ. Hãy dùng xịt nước muối và làm ẩm không khí trong phòng.', title_zh = '鼻塞了？🤧', body_zh = '你没有生病，这是妊娠期鼻炎。用生理盐水喷雾，并给房间加湿。' WHERE id = '9c22925e-f028-48cf-85a0-9499c06415cb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Entrega rápida! 🚚', body_es = 'Cuando tengo hambre, puedo empezar a darte toquecitos. ¿Qué hay hoy de saludable en la sección Nutrición? 😋', title_fr = 'Livraison express ! 🚚', body_fr = 'Quand j''ai faim, je risque de vous donner des petits coups. Qu''y a-t-il de bon aujourd''hui dans la rubrique Nutrition ? 😋', title_hi = 'फ़ास्ट डिलीवरी! 🚚', body_hi = 'भूख लगने पर मैं आपको कोंचना शुरू कर सकता हूँ। आज पोषण सेक्शन में क्या सेहतमंद है? 😋', title_id = 'Pengiriman kilat! 🚚', body_id = 'Saat lapar, aku mungkin mulai menyenggol Anda. Apa yang bermanfaat untuk hari ini di bagian Nutrisi? 😋', title_ja = 'スピード配達中！🚚', body_ja = 'お腹がすくと、ママをつんつんしはじめるかも。今日は「栄養」セクションに何かいいものがある？😋', title_ko = '빠른 배송! 🚚', body_ko = '배고프면 엄마를 콕콕 찌르기 시작할지도 몰라요. 오늘 영양 섹션에는 어떤 좋은 음식이 있을까요? 😋', title_nl = 'Snelle levering! 🚚', body_nl = 'Als ik honger heb, kan ik je gaan porren. Wat is er vandaag voor gezonds in het onderdeel Voeding? 😋', title_pl = 'Szybka dostawa! 🚚', body_pl = 'Gdy jestem głodne, mogę zacząć cię szturchać. Co zdrowego jest dziś w sekcji Odżywianie? 😋', title_pt = 'Entrega rápida! 🚚', body_pt = 'Quando tenho fome, posso começar a dar-lhe uns toques. O que há de saudável hoje na secção Nutrição? 😋', title_sv = 'Snabb leverans! 🚚', body_sv = 'När jag är hungrig kan jag börja knuffa på dig. Vad finns det för nyttigt i Kost-avsnittet i dag? 😋', title_vi = 'Giao hàng nhanh! 🚚', body_vi = 'Khi đói, con có thể bắt đầu thúc mẹ đấy. Hôm nay mục Dinh dưỡng có gì bổ dưỡng nhỉ? 😋', title_zh = '快递加速中！🚚', body_zh = '我饿了的时候可能会开始戳你。营养板块今天有什么好吃又健康的？😋' WHERE id = '1ea8357f-773e-45c8-a5ce-b632b68c81c2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿El estreñimiento no se va? 🚽', body_es = 'La fibra y mucha agua son el mejor remedio. No te quedes quieta: un paseo diario pone en marcha el intestino.', title_fr = 'La constipation ne vous lâche pas ? 🚽', body_fr = 'Les fibres et beaucoup d''eau sont le meilleur remède. Ne restez pas immobile : une marche quotidienne fait travailler les intestins.', title_hi = 'कब्ज़ पीछा नहीं छोड़ रही? 🚽', body_hi = 'फ़ाइबर वाला खाना और खूब पानी सबसे अच्छी दवा है। बैठी मत रहिए, रोज़ की सैर आँतों को चलाती है।', title_id = 'Sembelit tak kunjung pergi? 🚽', body_id = 'Makanan berserat dan banyak minum adalah obat terbaik. Jangan diam saja, jalan kaki setiap hari membuat usus bekerja.', title_ja = '便秘が続いていますか？🚽', body_ja = '食物繊維の多い食べ物とたっぷりのお水がいちばんの薬です。じっとしていないで、毎日の散歩で腸を動かしましょう。', title_ko = '변비가 계속되나요? 🚽', body_ko = '섬유질 음식과 충분한 물이 최고의 약이에요. 가만히 있지 말고 매일 걸으면 장이 잘 움직여요.', title_nl = 'Blijft de verstopping? 🚽', body_nl = 'Vezelrijk eten en veel water zijn het beste medicijn. Blijf niet stilzitten, een dagelijkse wandeling zet je darmen aan het werk.', title_pl = 'Zaparcia nie odpuszczają? 🚽', body_pl = 'Błonnik i dużo wody to najlepsze lekarstwo. Nie siedź bez ruchu, codzienny spacer pobudza jelita.', title_pt = 'A obstipação não dá tréguas? 🚽', body_pt = 'Alimentos ricos em fibra e muita água são o melhor remédio. Não fique parada: uma caminhada diária põe o intestino a funcionar.', title_sv = 'Släpper inte förstoppningen? 🚽', body_sv = 'Fiberrik mat och mycket vatten är bästa medicinen. Sitt inte still, en daglig promenad får tarmarna att arbeta.', title_vi = 'Táo bón vẫn chưa hết? 🚽', body_vi = 'Thực phẩm giàu chất xơ và nhiều nước là liều thuốc tốt nhất. Đừng ngồi yên, đi bộ hằng ngày giúp ruột hoạt động.', title_zh = '便秘还没好？🚽', body_zh = '膳食纤维和多喝水是最好的良药。别总坐着不动，每天散步能让肠道动起来。' WHERE id = 'd03c23f6-2e1d-4083-b90a-157da0e6e6f4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Los huesos se endurecen! 🦴', body_es = 'Los cartílagos, blandos como goma, se convierten en hueso. ¡Llena tu reserva de calcio para que su esqueleto sea de acero!', title_fr = 'Les os se solidifient ! 🦴', body_fr = 'Les cartilages, souples comme du caoutchouc, se transforment en os. Remplissez vos réserves de calcium pour un squelette d''acier !', title_hi = 'हड्डियाँ मज़बूत हो रही हैं! 🦴', body_hi = 'रबर जैसी नरम उपास्थि हड्डी में बदल रही है। कैल्शियम का भंडार भरिए, ताकि बच्चे का कंकाल फ़ौलाद जैसा बने!', title_id = 'Tulang-tulang mengeras! 🦴', body_id = 'Tulang rawan yang lunak seperti karet berubah menjadi tulang. Penuhi gudang kalsium agar kerangka bayi sekuat baja!', title_ja = '骨がしっかりしてきた！🦴', body_ja = 'ゴムのようにやわらかい軟骨が骨に変わっていきます。カルシウムをたくわえて、赤ちゃんの骨格を鋼のように強くしましょう！', title_ko = '뼈가 단단해지고 있어요! 🦴', body_ko = '고무처럼 말랑한 연골이 뼈로 바뀌고 있어요. 아기의 뼈대가 강철처럼 튼튼하도록 칼슘을 채워 주세요!', title_nl = 'De botjes worden steviger! 🦴', body_nl = 'Kraakbeen, zacht als rubber, verandert in bot. Vul je calciumvoorraad aan, zodat het skelet van je baby sterk wordt als staal!', title_pl = 'Kości twardnieją! 🦴', body_pl = 'Miękkie jak guma chrząstki zmieniają się w kości. Uzupełnij zapas wapnia, by szkielet dziecka był mocny jak stal!', title_pt = 'Os ossos estão a ficar mais firmes! 🦴', body_pt = 'As cartilagens, moles como borracha, estão a transformar-se em osso. Encha o depósito de cálcio para o esqueleto do bebé ficar forte como aço!', title_sv = 'Skelettet blir hårdare! 🦴', body_sv = 'Brosk, mjukt som gummi, blir till ben. Fyll på kalciumförrådet så att barnets skelett blir starkt som stål!', title_vi = 'Xương đang cứng cáp! 🦴', body_vi = 'Sụn mềm như cao su đang chuyển thành xương. Hãy nạp đầy kho canxi để bộ xương của bé vững như thép!', title_zh = '骨骼在变硬！🦴', body_zh = '像橡皮一样柔软的软骨正在变成骨头。补满钙库，让宝宝的骨骼像钢铁一样结实！' WHERE id = '0deb48f1-6a30-484b-9569-decc49f2c37c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Adiós a los mareos! 🛑', body_es = 'Al aumentar tu volumen de sangre, necesitas más hierro. Espinacas, trigo sarraceno o carne roja... ¡Añádelos sin falta a tu menú!', title_fr = 'Fini les vertiges ! 🛑', body_fr = 'Avec l''augmentation de votre volume sanguin, vos besoins en fer grandissent. Épinards, sarrasin ou viande rouge... Ajoutez-les à votre menu !', title_hi = 'चक्कर को अलविदा! 🛑', body_hi = 'खून की मात्रा बढ़ने के साथ आयरन की ज़रूरत भी बढ़ती है। पालक, कुट्टू या रेड मीट... मेन्यू में ज़रूर जोड़िए!', title_id = 'Selamat tinggal pusing! 🛑', body_id = 'Seiring bertambahnya volume darah, kebutuhan zat besi meningkat. Bayam, soba, atau daging merah... Pastikan ada di menu Anda!', title_ja = 'めまいにさよなら！🛑', body_ja = '血液量が増えるにつれ、鉄分がもっと必要になります。ほうれん草、そば粉、赤身肉...ぜひメニューに加えてください！', title_ko = '어지러움은 이제 그만! 🛑', body_ko = '혈액량이 늘면 철분이 더 필요해요. 시금치, 메밀, 붉은 고기... 식단에 꼭 넣어 주세요!', title_nl = 'Weg met duizeligheid! 🛑', body_nl = 'Als je bloedvolume toeneemt, heb je meer ijzer nodig. Spinazie, boekweit of rood vlees... Zet het zeker op je menu!', title_pl = 'Koniec z zawrotami głowy! 🛑', body_pl = 'Gdy rośnie objętość krwi, potrzebujesz więcej żelaza. Szpinak, kasza gryczana czy czerwone mięso... Koniecznie dodaj je do menu!', title_pt = 'Acabe com as tonturas! 🛑', body_pt = 'À medida que o volume de sangue aumenta, precisa de mais ferro. Espinafres, trigo-sarraceno ou carne vermelha... Junte-os sem falta ao seu menu!', title_sv = 'Slut med yrseln! 🛑', body_sv = 'När blodmängden ökar behöver du mer järn. Spenat, bovete eller rött kött... Lägg till det i menyn!', title_vi = 'Tạm biệt chóng mặt! 🛑', body_vi = 'Khi lượng máu tăng, nhu cầu sắt cũng tăng. Rau bina, kiều mạch hay thịt đỏ... Nhớ thêm vào thực đơn nhé!', title_zh = '告别头晕！🛑', body_zh = '血容量增加，你对铁的需求也变多了。菠菜、荞麦或红肉……一定要加进菜单！' WHERE id = 'b9294383-8fdd-4af3-9a0e-31820d8761cf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Discoteca en tu barriga? 💃', body_es = '¡Aquí dentro estoy aprendiendo a dar volteretas! ¿Lo has notado?', title_fr = 'Soirée disco dans votre ventre ? 💃', body_fr = 'J''apprends à faire des saltos ici ! Vous l''avez senti ?', title_hi = 'पेट में डिस्को? 💃', body_hi = 'मैं अंदर कलाबाज़ी खाना सीख रहा हूँ! महसूस हुआ?', title_id = 'Ada disko di perut Anda? 💃', body_id = 'Aku sedang belajar salto di dalam sini! Terasa?', title_ja = 'お腹の中でディスコ？💃', body_ja = 'お腹の中で宙返りを練習中だよ！感じた？', title_ko = '뱃속에 디스코텍이? 💃', body_ko = '여기서 공중제비를 배우고 있어요! 느끼셨어요?', title_nl = 'Disco in je buik? 💃', body_nl = 'Ik leer hier een salto maken! Voelde je het?', title_pl = 'Dyskoteka w brzuchu? 💃', body_pl = 'Uczę się tu robić fikołki! Poczułaś?', title_pt = 'Discoteca na barriga? 💃', body_pt = 'Estou a aprender a dar cambalhotas aqui dentro! Sentiu?', title_sv = 'Disco i magen? 💃', body_sv = 'Jag lär mig göra kullerbyttor här inne! Kände du det?', title_vi = 'Vũ trường trong bụng mẹ? 💃', body_vi = 'Con đang tập lộn nhào trong này! Mẹ có cảm thấy không?', title_zh = '肚子里在开迪斯科？💃', body_zh = '我在里面学翻跟头！感觉到了吗？' WHERE id = '38d34d85-388f-49ed-9594-2287f8011443' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Tienes sueños raros? 😴', body_es = 'Las hormonas pueden convertir tus noches en una película. Tranquila, es normal. ¡Apunta tus sueños en el Diario de ánimo!', title_fr = 'Vous faites des rêves étranges ? 😴', body_fr = 'Les hormones peuvent transformer vos nuits en film. Pas d''inquiétude, c''est normal. Notez vos rêves dans le Journal d''humeur !', title_hi = 'अजीब सपने आ रहे हैं? 😴', body_hi = 'हार्मोन रातों को फ़िल्म बना सकते हैं। घबराइए मत, यह सामान्य है। अपने सपने मूड डायरी में लिखिए!', title_id = 'Mimpi yang aneh? 😴', body_id = 'Hormon bisa membuat malam terasa seperti film. Jangan takut, ini normal. Catat mimpi Anda di Buku Harian Suasana Hati!', title_ja = '不思議な夢を見ますか？😴', body_ja = 'ホルモンの影響で、夜が映画のようになることも。心配しないで、これは普通のことです。夢を「気分日記」に記録してみましょう！', title_ko = '이상한 꿈을 꾸나요? 😴', body_ko = '호르몬이 밤을 영화관으로 만들 수 있어요. 걱정 마세요, 정상이에요. 꿈을 기분 일기에 기록해 보세요!', title_nl = 'Vreemde dromen? 😴', body_nl = 'Hormonen kunnen je nachten in een film veranderen. Geen zorgen, dat is normaal. Noteer je dromen in je Stemmingsdagboek!', title_pl = 'Masz dziwne sny? 😴', body_pl = 'Hormony mogą zamienić noce w kino. Nie bój się, to normalne. Zapisuj sny w Dzienniku nastroju!', title_pt = 'Tem tido sonhos estranhos? 😴', body_pt = 'As hormonas podem transformar as noites num filme. Não se assuste, é normal. Registe os seus sonhos no Diário de Humor!', title_sv = 'Konstiga drömmar? 😴', body_sv = 'Hormonerna kan förvandla nätterna till bio. Var inte rädd, det är normalt. Skriv ner dina drömmar i Humördagboken!', title_vi = 'Mẹ hay mơ những giấc mơ lạ? 😴', body_vi = 'Hormone có thể biến đêm của mẹ thành rạp phim. Đừng lo, điều này bình thường. Ghi lại giấc mơ vào Nhật ký tâm trạng nhé!', title_zh = '做了奇怪的梦？😴', body_zh = '激素可能会把夜晚变成电影院。别怕，这很正常。把梦记在心情日记里吧！' WHERE id = '2496cef6-77ee-4345-81fb-7ae6ee89a5c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Se pone su propia crema natural! 🧴', body_es = 'Para que su piel no se arrugue, se cubre de una sustancia blanca parecida al queso llamada vérnix. ¡La crema protectora de la propia naturaleza!', title_fr = 'Il s''applique une crème naturelle ! 🧴', body_fr = 'Pour que sa peau ne se ride pas, elle se couvre d''une substance blanche ressemblant à du fromage, le vernix. La crème protectrice de la nature !', title_hi = 'प्राकृतिक क्रीम लगा रहा है! 🧴', body_hi = 'उसकी त्वचा सिकुड़े नहीं, इसलिए वह वर्निक्स नाम के सफ़ेद, पनीर जैसे पदार्थ से ढकी होती है। कुदरत की अपनी सुरक्षा क्रीम!', title_id = 'Mengoleskan krem alami! 🧴', body_id = 'Agar kulitnya tidak keriput, ia dilapisi zat putih seperti keju yang disebut verniks. Krem pelindung buatan alam!', title_ja = '天然のクリームを塗っています！🧴', body_ja = '肌がふやけないように、胎脂と呼ばれる白いチーズのような物質で覆われています。自然がくれた保護クリームです！', title_ko = '천연 크림을 바르고 있어요! 🧴', body_ko = '피부가 쭈글쭈글해지지 않도록 태지라는 하얀 치즈 같은 물질로 덮여요. 자연이 만든 보호 크림이에요!', title_nl = 'Je baby smeert zich in met natuurlijke crème! 🧴', body_nl = 'Om rimpelen te voorkomen, wordt de huid bedekt met een witte, kaasachtige laag: huidsmeer. De eigen beschermende crème van de natuur!', title_pl = 'Nakłada naturalny krem! 🧴', body_pl = 'Aby skóra się nie marszczyła, pokrywa ją biała, serowata maź płodowa. To naturalny krem ochronny!', title_pt = 'Está a pôr um creme natural! 🧴', body_pt = 'Para a pele não enrugar, o bebé fica coberto por uma substância branca, parecida com queijo, chamada vérnix. O creme protetor da própria natureza!', title_sv = 'Barnet smörjer in sig med naturlig kräm! 🧴', body_sv = 'För att huden inte ska bli skrynklig täcks den av ett vitt, ostliknande ämne som kallas fosterfett (vernix). Naturens egen skyddskräm!', title_vi = 'Bé tự thoa kem tự nhiên! 🧴', body_vi = 'Để da không bị nhăn, bé được phủ một lớp chất trắng như phô mai gọi là chất gây. Kem bảo vệ của chính thiên nhiên!', title_zh = '在涂天然护肤霜！🧴', body_zh = '为了不让皮肤起皱，宝宝身上覆盖着一层叫胎脂的白色奶酪状物质。这是大自然自带的保护霜！' WHERE id = 'a0a2da1d-904a-4c50-8ef1-d362ba476da8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Quién es el amigo del hierro? 🍊', body_es = 'Si tomas hierro, acompáñalo siempre de vitamina C. Así se absorbe mejor.', title_fr = 'Qui est l''ami du fer ? 🍊', body_fr = 'Si vous prenez du fer, associez-le toujours à de la vitamine C. Il est ainsi mieux absorbé.', title_hi = 'आयरन का दोस्त कौन है? 🍊', body_hi = 'अगर आप आयरन ले रही हैं, तो साथ में विटामिन C ज़रूर हो। इससे आयरन बेहतर सोखा जाता है।', title_id = 'Siapa sahabat zat besi? 🍊', body_id = 'Jika Anda mengonsumsi zat besi, pastikan disertai vitamin C. Dengan begitu zat besi lebih mudah diserap.', title_ja = '鉄分の友達は誰？🍊', body_ja = '鉄剤を飲んでいるなら、ビタミンCも一緒にとりましょう。そのほうが鉄分がよく吸収されます。', title_ko = '철분의 단짝은 누구? 🍊', body_ko = '철분제를 드신다면 비타민 C를 꼭 함께 드세요. 그러면 철분이 더 잘 흡수돼요.', title_nl = 'Wie is de beste vriend van ijzer? 🍊', body_nl = 'Neem je ijzer in? Combineer het dan altijd met vitamine C. Zo wordt ijzer beter opgenomen.', title_pl = 'Kto jest przyjacielem żelaza? 🍊', body_pl = 'Jeśli przyjmujesz żelazo, łącz je z witaminą C. Wtedy lepiej się wchłania.', title_pt = 'Quem é o amigo do ferro? 🍊', body_pt = 'Se toma ferro, junte-lhe sempre vitamina C. Assim o ferro é absorvido melhor.', title_sv = 'Vem är järnets vän? 🍊', body_sv = 'Om du tar järn, se till att få i dig C-vitamin samtidigt. Då tas järnet upp bättre.', title_vi = 'Ai là bạn thân của sắt? 🍊', body_vi = 'Nếu mẹ uống sắt, hãy kèm thêm vitamin C. Như vậy sắt được hấp thu tốt hơn.', title_zh = '铁的好朋友是谁？🍊', body_zh = '如果在补铁，一定要搭配维生素C，这样铁吸收得更好。' WHERE id = 'd4b39ae6-9d34-4c4d-8a69-951fc75c6f59' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te duele la espalda? 👠', body_es = 'Guarda los tacones en el armario, ¡es hora de estar cómoda! Elige calzado ortopédico.', title_fr = 'Mal au dos ? 👠', body_fr = 'Rangez les talons hauts dans l''armoire, place au confort ! Choisissez des chaussures orthopédiques.', title_hi = 'कमर में दर्द है? 👠', body_hi = 'हाई हील्स अलमारी में रख दीजिए, अब आराम का समय है! ऑर्थोपेडिक जूते चुनिए।', title_id = 'Punggung pegal? 👠', body_id = 'Simpan sepatu hak tinggi di lemari, saatnya nyaman! Pilih sepatu ortopedi.', title_ja = '腰が痛い？👠', body_ja = 'ハイヒールはクローゼットにしまって、快適さを優先するときです！整形外科用の靴を選びましょう。', title_ko = '허리가 아프세요? 👠', body_ko = '하이힐은 옷장에 넣어 두세요, 편안함이 우선이에요! 정형외과용 신발을 고르세요.', title_nl = 'Pijn in je rug? 👠', body_nl = 'Zet die hoge hakken in de kast, tijd voor comfort! Kies orthopedische schoenen.', title_pl = 'Boli cię krzyż? 👠', body_pl = 'Odstaw szpilki do szafy, czas na wygodę! Wybierz obuwie ortopedyczne.', title_pt = 'Dores nas costas? 👠', body_pt = 'Guarde os saltos altos no roupeiro, é hora do conforto! Escolha calçado ortopédico.', title_sv = 'Ont i ryggen? 👠', body_sv = 'Ställ in högklackade skor i garderoben, nu är det bekvämlighet som gäller! Välj ortopediska skor.', title_vi = 'Mẹ bị đau lưng? 👠', body_vi = 'Cất giày cao gót vào tủ thôi, đến lúc thoải mái rồi! Hãy chọn giày chỉnh hình.', title_zh = '腰疼吗？👠', body_zh = '把高跟鞋收进柜子，该舒服一点了！选择矫形鞋吧。' WHERE id = '9ad99447-3f71-4bc4-9dff-13a64a93c8f4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Sientes tirones en los costados? ⚡', body_es = 'Puede haber un pinchazo repentino. Tranquila, ¡solo estoy ampliando mi casa! Mira los movimientos relajantes de la sección Ejercicios. 🤸‍♀️', title_fr = 'Ça tire sur les côtés ? ⚡', body_fr = 'Une douleur soudaine peut survenir, pas d''inquiétude, j''agrandis simplement ma maison ! Essayez les mouvements relaxants de la rubrique Exercices. 🤸‍♀️', title_hi = 'पेट के किनारों में खिंचाव? ⚡', body_hi = 'अचानक चुभन हो सकती है, घबराइए मत, मैं बस अपना घर बड़ा कर रहा हूँ! एक्सरसाइज़ सेक्शन में आराम देने वाली एक्सरसाइज़ देखिए। 🤸‍♀️', title_id = 'Sisi perut terasa tertarik? ⚡', body_id = 'Bisa muncul nyeri tiba-tiba, jangan takut, aku hanya sedang memperluas rumahku! Coba gerakan relaksasi di bagian Latihan. 🤸‍♀️', title_ja = 'わき腹が張る？⚡', body_ja = '急にチクッとすることがあっても心配しないで、お部屋を広げているだけだよ！「エクササイズ」セクションのリラックスできる動きを見てみてね。🤸‍♀️', title_ko = '옆구리가 당기나요? ⚡', body_ko = '갑자기 콕 쑤실 수 있지만 걱정 마세요, 제가 집을 넓히는 중이에요! 운동 섹션의 이완 동작을 확인해 보세요. 🤸‍♀️', title_nl = 'Trekt het in je zijden? ⚡', body_nl = 'Je kunt plotseling een steek voelen, schrik niet, ik maak mijn huisje alleen groter! Bekijk de ontspannende oefeningen in het onderdeel Oefeningen. 🤸‍♀️', title_pl = 'Ciągnie cię w bokach? ⚡', body_pl = 'Może pojawić się nagłe kłucie. Nie bój się, po prostu powiększam swój domek! Sprawdź relaksujące ćwiczenia w sekcji Ćwiczenia. 🤸‍♀️', title_pt = 'Sente os lados a esticar? ⚡', body_pt = 'Pode sentir uma pontada súbita. Não se assuste, estou só a aumentar a minha casa! Veja os movimentos relaxantes na secção Exercícios. 🤸‍♀️', title_sv = 'Spänner det i sidorna? ⚡', body_sv = 'Det kan komma plötsliga hugg, var inte rädd, jag bygger bara ut mitt hem! Kolla de avslappnande övningarna i avsnittet Träning. 🤸‍♀️', title_vi = 'Hai bên bụng bị căng? ⚡', body_vi = 'Có thể có cơn đau nhói đột ngột, đừng sợ, con chỉ đang nới rộng nhà thôi! Xem các động tác thư giãn trong mục Bài tập nhé. 🤸‍♀️', title_zh = '两侧有牵拉感？⚡', body_zh = '可能会突然抽痛，别怕，我只是在扩建我的小家！看看运动板块里的放松动作吧。🤸‍♀️' WHERE id = 'a4dafbff-3c24-457e-81b5-bb659a58fa4b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Su pasaporte está listo! 🛂', body_es = 'Sus huellas dactilares ya están formadas. Tiene esos dibujos que nadie más en el mundo tiene. ¡Viene alguien único!', title_fr = 'Son passeport est prêt ! 🛂', body_fr = 'Ses empreintes digitales sont complètement formées. Ces motifs que personne d''autre au monde ne possède sont désormais à lui. Quelqu''un d''unique arrive !', title_hi = 'उसका पासपोर्ट तैयार है! 🛂', body_hi = 'फ़िंगरप्रिंट पूरी तरह बन गए। दुनिया में किसी और के पास न होने वाले वे निशान अब उसके पास हैं। एक अनोखा इंसान आ रहा है!', title_id = 'Paspornya sudah siap! 🛂', body_id = 'Sidik jarinya sudah terbentuk sempurna. Pola yang tidak dimiliki siapa pun di dunia kini ada padanya. Seseorang yang unik akan datang!', title_ja = 'パスポートの準備完了！🛂', body_ja = '指紋がすっかりできあがりました。世界で誰も持っていない模様が、もう赤ちゃんにあります。唯一無二の存在がやってきます！', title_ko = '여권이 준비됐어요! 🛂', body_ko = '지문이 완전히 만들어졌어요. 세상에 누구도 가지지 않은 그 무늬가 이제 아기에게 있어요. 특별한 아기가 오고 있어요!', title_nl = 'Het paspoort is klaar! 🛂', body_nl = 'De vingerafdrukken zijn volledig gevormd. Die patronen die niemand anders ter wereld heeft, zijn nu van je kleintje. Er komt iemand unieks aan!', title_pl = 'Paszport gotowy! 🛂', body_pl = 'Odciski palców są w pełni ukształtowane. Ma już wzory, jakich nie ma nikt na świecie. Nadchodzi ktoś wyjątkowy!', title_pt = 'O passaporte está pronto! 🛂', body_pt = 'As impressões digitais estão totalmente formadas. Aqueles padrões, que mais ninguém no mundo tem, já são dele. Vem aí alguém único!', title_sv = 'Passet är klart! 🛂', body_sv = 'Fingeravtrycken är färdigbildade. De mönster som ingen annan i världen har finns nu hos barnet. En unik person är på väg!', title_vi = 'Hộ chiếu của bé đã sẵn sàng! 🛂', body_vi = 'Dấu vân tay đã hình thành hoàn chỉnh. Những đường vân không ai trên thế giới có giờ đã thuộc về bé. Một người độc nhất đang đến!', title_zh = '宝宝的护照办好啦！🛂', body_zh = '指纹已经完全形成。那些世上独一无二的纹路已经属于宝宝了。一个独特的小生命要来啦！' WHERE id = '039c5d10-ebc0-436e-9936-a148242fd9a3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿El agua no te sabe a nada? 💧', body_es = 'Si te cuesta beber, prueba con pepino, sandía o agua con menta. La deshidratación da dolor de cabeza.', title_fr = 'L''eau n''a pas de goût ? 💧', body_fr = 'Si boire est difficile, essayez l''eau au concombre, à la pastèque ou à la menthe. Le manque d''eau donne mal à la tête.', title_hi = 'पानी बेस्वाद लगता है? 💧', body_hi = 'अगर पीना मुश्किल है, तो खीरा, तरबूज़ या पुदीने वाला पानी आज़माइए। पानी की कमी से सिरदर्द होता है।', title_id = 'Air terasa hambar? 💧', body_id = 'Jika sulit minum, coba air dengan mentimun, semangka, atau daun mint. Kurang minum menyebabkan sakit kepala.', title_ja = 'お水が味気ない？💧', body_ja = '飲みにくいときは、きゅうり、スイカ、ミント入りのお水を試してみて。水分不足は頭痛の原因になります。', title_ko = '물이 밍밍한가요? 💧', body_ko = '물 마시기가 힘들면 오이, 수박이나 민트 물을 드셔 보세요. 수분이 부족하면 두통이 생겨요.', title_nl = 'Smaakt water nergens naar? 💧', body_nl = 'Lukt drinken moeilijk? Probeer water met komkommer, watermeloen of munt. Te weinig drinken geeft hoofdpijn.', title_pl = 'Woda nie ma smaku? 💧', body_pl = 'Jeśli trudno ci pić, spróbuj wody z ogórkiem, arbuzem lub miętą. Odwodnienie powoduje ból głowy.', title_pt = 'A água não sabe a nada? 💧', body_pt = 'Se lhe custa beber, experimente pepino, melancia ou água com hortelã. A desidratação causa dores de cabeça.', title_sv = 'Smakar vattnet ingenting? 💧', body_sv = 'Om det är svårt att dricka, prova vatten med gurka, vattenmelon eller mynta. Vätskebrist ger huvudvärk.', title_vi = 'Nước nhạt nhẽo quá? 💧', body_vi = 'Nếu khó uống, hãy thử nước dưa chuột, dưa hấu hoặc nước bạc hà. Thiếu nước gây đau đầu đấy.', title_zh = '觉得水没味道？💧', body_zh = '如果喝水困难，试试黄瓜、西瓜或薄荷水。缺水会引起头痛。' WHERE id = 'f1613176-745a-48b4-a20e-1dee77f819cf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Mamá, te oigo! 👂', body_es = 'Tu voz me suena como una nana. Y tus latidos son el ritmo más bonito. Háblame más, quiero conocerte.', title_fr = 'Maman, je vous entends ! 👂', body_fr = 'Votre voix est comme une berceuse pour moi. Et les battements de votre cœur sont le plus beau des rythmes. Parlez-moi plus, je veux vous connaître.', title_hi = 'माँ, मैं आपको सुन रहा हूँ! 👂', body_hi = 'आपकी आवाज़ मुझे लोरी जैसी लगती है। और आपकी धड़कनें सबसे सुंदर लय हैं। मुझसे और बात कीजिए, मैं आपको जानना चाहता हूँ।', title_id = 'Bunda, aku mendengarmu! 👂', body_id = 'Suara Anda terdengar seperti lagu nina bobo bagiku. Detak jantung Anda adalah irama terindah. Ajak aku bicara lebih sering, aku ingin mengenal Anda.', title_ja = 'ママ、聞こえるよ！👂', body_ja = 'ママの声は子守唄みたい。心臓の音はいちばんすてきなリズムだよ。もっと話しかけてね、ママのことを知りたいの。', title_ko = '엄마, 목소리가 들려요! 👂', body_ko = '엄마 목소리는 저에게 자장가 같아요. 엄마의 심장 소리는 가장 아름다운 리듬이고요. 저와 더 많이 이야기해 주세요, 엄마를 알고 싶어요.', title_nl = 'Mama, ik hoor je! 👂', body_nl = 'Je stem klinkt als een slaapliedje voor mij, en je hartslag is het mooiste ritme. Praat meer met me, ik wil je leren kennen.', title_pl = 'Mamo, słyszę cię! 👂', body_pl = 'Twój głos brzmi dla mnie jak kołysanka, a bicie twojego serca to najpiękniejszy rytm. Mów do mnie więcej, chcę cię poznać.', title_pt = 'Mamã, estou a ouvi-la! 👂', body_pt = 'A sua voz soa-me como uma canção de embalar. E o bater do seu coração é o ritmo mais bonito. Fale mais comigo, quero conhecê-la.', title_sv = 'Mamma, jag hör dig! 👂', body_sv = 'Din röst låter som en vaggvisa för mig. Och dina hjärtslag är den vackraste rytmen. Prata mer med mig, jag vill lära känna dig.', title_vi = 'Mẹ ơi, con nghe thấy mẹ! 👂', body_vi = 'Giọng mẹ với con như lời ru. Còn nhịp tim của mẹ là giai điệu đẹp nhất. Hãy nói chuyện với con nhiều hơn, con muốn hiểu mẹ.', title_zh = '妈妈，我听到你啦！👂', body_zh = '你的声音对我来说就像摇篮曲，你的心跳是最美的节奏。多和我说说话吧，我想认识你。' WHERE id = 'f319fe10-d32c-42c4-938c-e7358782f1f1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Zinc: el héroe oculto 🛡️', body_es = 'Mis células se dividen rápido. ¡Necesito material de construcción! ¿Hay carne roja, queso o frutos secos en el menú?', title_fr = 'Le zinc : héros discret 🛡️', body_fr = 'Mes cellules se divisent très vite. J''ai besoin de matériaux de construction ! Viande rouge, fromage ou fruits à coque sont-ils au menu ?', title_hi = 'ज़िंक: छुपा हुआ हीरो 🛡️', body_hi = 'मेरी कोशिकाएँ तेज़ी से बँट रही हैं। मुझे निर्माण सामग्री चाहिए! क्या मेन्यू में रेड मीट, चीज़ या मेवे हैं?', title_id = 'Seng: pahlawan tersembunyi 🛡️', body_id = 'Sel-selku membelah dengan cepat. Aku butuh bahan bangunan! Apakah ada daging merah, keju, atau kacang-kacangan di menu?', title_ja = '亜鉛：隠れたヒーロー 🛡️', body_ja = '細胞がどんどん分裂しているの。建築材料が必要なんだ！赤身肉、チーズ、ナッツはメニューにある？', title_ko = '아연: 숨은 영웅 🛡️', body_ko = '제 세포가 빠르게 분열하고 있어요. 건축 재료가 필요해요! 붉은 고기, 치즈나 견과류가 식단에 있나요?', title_nl = 'Zink: de verborgen held 🛡️', body_nl = 'Mijn cellen delen zich razendsnel. Ik heb bouwmateriaal nodig! Staan rood vlees, kaas of noten op het menu?', title_pl = 'Cynk: ukryty bohater 🛡️', body_pl = 'Moje komórki szybko się dzielą. Potrzebuję materiałów budowlanych! Czy w menu jest czerwone mięso, ser lub orzechy?', title_pt = 'Zinco: o herói escondido 🛡️', body_pt = 'As minhas células dividem-se depressa. Preciso de material de construção! Há carne vermelha, queijo ou frutos secos no menu?', title_sv = 'Zink: den hemliga hjälten 🛡️', body_sv = 'Mina celler delar sig snabbt. Jag behöver byggmaterial! Finns rött kött, ost eller nötter på menyn?', title_vi = 'Kẽm: Người hùng thầm lặng 🛡️', body_vi = 'Tế bào của con đang phân chia rất nhanh. Con cần vật liệu xây dựng! Thực đơn có thịt đỏ, phô mai hay các loại hạt không mẹ?', title_zh = '锌：隐形英雄 🛡️', body_zh = '我的细胞在快速分裂，我需要建筑材料！菜单里有红肉、奶酪或坚果吗？' WHERE id = '08cbf45e-1a2d-4043-a7ff-cbce10cda3f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Lo has notado? ¡Una patada! ⚽', body_es = '¡Mamá, estoy despierto! Ese leve aleteo es mi forma de decirte hola. Pon la mano en tu barriga, ¿a lo mejor lo vuelvo a hacer?', title_fr = 'Vous l''avez senti ? Un coup de pied ! ⚽', body_fr = 'Maman, je suis réveillé ! Ce léger frémissement, c''est ma façon de vous dire bonjour. Posez la main sur votre ventre, je recommencerai peut-être ?', title_hi = 'महसूस हुआ? किक! ⚽', body_hi = 'माँ, मैं जाग रहा हूँ! वह हल्की फड़फड़ाहट मेरा ''हैलो'' है। पेट पर हाथ रखिए, शायद मैं फिर से करूँ?', title_id = 'Terasa? Tendangan! ⚽', body_id = 'Bunda, aku sudah bangun! Getaran ringan itu caraku menyapa Anda. Letakkan tangan di perut, mungkin aku melakukannya lagi?', title_ja = '感じた？キック！⚽', body_ja = 'ママ、起きてるよ！あのふわっとした動きは、わたしからの「こんにちは」なの。お腹に手を当ててみて、またやるかも？', title_ko = '느끼셨어요? 발차기! ⚽', body_ko = '엄마, 저 깨어 있어요! 그 가벼운 꿈틀거림은 제가 인사하는 거예요. 배에 손을 올려 보세요, 또 할지도 몰라요?', title_nl = 'Voelde je dat? Een trap! ⚽', body_nl = 'Mama, ik ben wakker! Dat zachte gefladder is mijn manier om hallo te zeggen. Leg je hand op je buik, misschien doe ik het nog een keer?', title_pl = 'Poczułaś? Kopnięcie! ⚽', body_pl = 'Mamo, nie śpię! To lekkie trzepotanie to moje „cześć”. Połóż dłoń na brzuchu, może zrobię to znowu?', title_pt = 'Sentiu? Um pontapé! ⚽', body_pt = 'Mamã, estou acordado! Aquele leve esvoaçar é a minha forma de lhe dizer olá. Ponha a mão na barriga, talvez eu volte a fazê-lo?', title_sv = 'Kände du? En spark! ⚽', body_sv = 'Mamma, jag är vaken! Det där lätta fladdret är mitt sätt att säga hej. Lägg handen på magen, kanske gör jag det igen?', title_vi = 'Mẹ cảm thấy không? Một cú đá! ⚽', body_vi = 'Mẹ ơi, con thức rồi! Cái rung nhẹ ấy là con chào mẹ đấy. Mẹ đặt tay lên bụng đi, biết đâu con lại làm nữa?', title_zh = '感觉到了吗？踢了一脚！⚽', body_zh = '妈妈，我醒着呢！那轻轻的颤动是我在跟你打招呼。把手放在肚子上，说不定我会再来一次？' WHERE id = '9cb3f2ab-0aed-4e06-977f-d372f91e236f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Niño o niña? 💙💗', body_es = 'Se acerca la ecografía para saber mi sexo. ¿Estás emocionada?', title_fr = 'Garçon ou fille ? 💙💗', body_fr = 'L''échographie pour découvrir mon sexe approche. Vous avez hâte ?', title_hi = 'लड़का या लड़की? 💙💗', body_hi = 'मेरा लिंग जानने वाले अल्ट्रासाउंड का समय करीब है। उत्साहित हैं?', title_id = 'Laki-laki atau Perempuan? 💙💗', body_id = 'Jadwal USG untuk mengetahui jenis kelaminku sudah dekat. Deg-degan?', title_ja = '男の子？それとも女の子？💙💗', body_ja = 'わたしの性別がわかるエコー検査がもうすぐだね。ドキドキしてる？', title_ko = '아들일까요, 딸일까요? 💙💗', body_ko = '제 성별을 알 수 있는 초음파 날이 다가오고 있어요. 설레세요?', title_nl = 'Jongen of meisje? 💙💗', body_nl = 'De echo waarop je mijn geslacht kunt zien komt eraan. Spannend?', title_pl = 'Chłopiec czy dziewczynka? 💙💗', body_pl = 'Zbliża się USG, na którym poznasz moją płeć. Jesteś podekscytowana?', title_pt = 'Menino ou menina? 💙💗', body_pt = 'Está a chegar a ecografia para saber o meu sexo. Está entusiasmada?', title_sv = 'Pojke eller flicka? 💙💗', body_sv = 'Ultraljudet där du kan få veta mitt kön närmar sig. Är du spänd?', title_vi = 'Con trai hay Con gái? 💙💗', body_vi = 'Sắp đến buổi siêu âm để biết giới tính của con rồi. Mẹ có hồi hộp không?', title_zh = '男孩还是女孩？💙💗', body_zh = '能看出我性别的B超快到了。你激动吗？' WHERE id = 'c42cae82-ff16-485c-8a26-23b4bfd30c8b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Tengo mi primer juguete!', body_es = 'Juego agarrando el cordón umbilical y a veces lo aprieto. Mis dedos ya están aprendiendo a agarrar.', title_fr = 'J''ai mon premier jouet !', body_fr = 'Je joue avec mon cordon ombilical, parfois je le serre. Mes doigts apprennent déjà à attraper.', title_hi = 'मेरा पहला खिलौना!', body_hi = 'मैं गर्भनाल पकड़कर खेलता हूँ, कभी-कभी दबा भी देता हूँ। मेरी उँगलियाँ पकड़ना सीख रही हैं।', title_id = 'Aku punya mainan pertama!', body_id = 'Aku bermain sambil memegang tali pusar, kadang meremasnya. Jari-jariku sudah belajar menggenggam.', title_ja = '初めてのおもちゃ！', body_ja = 'へその緒をつかんで遊んでいるよ、ときどきぎゅっとにぎるの。指がもうつかむことを覚えているよ。', title_ko = '제 첫 장난감이 생겼어요!', body_ko = '탯줄을 잡고 놀다가 가끔 꽉 쥐기도 해요. 제 손가락이 벌써 잡는 법을 배우고 있어요.', title_nl = 'Ik heb mijn eerste speeltje!', body_nl = 'Ik speel met de navelstreng en knijp er soms in. Mijn vingertjes leren al vastpakken.', title_pl = 'Mam pierwszą zabawkę!', body_pl = 'Bawię się pępowiną, czasem ją ściskam. Moje paluszki uczą się już chwytać.', title_pt = 'Tenho o meu primeiro brinquedo!', body_pt = 'Agarro o cordão umbilical e brinco com ele, às vezes aperto-o. Os meus dedos já estão a aprender a agarrar.', title_sv = 'Jag har min första leksak!', body_sv = 'Jag leker med navelsträngen och kramar den ibland. Mina fingrar lär sig redan att greppa.', title_vi = 'Con có món đồ chơi đầu tiên rồi!', body_vi = 'Con nắm dây rốn để chơi, đôi khi bóp nhẹ. Ngón tay con đang học cách cầm nắm.', title_zh = '我有了第一个玩具！', body_zh = '我抓着脐带玩，有时还会捏一捏。我的手指已经在学习抓握了。' WHERE id = '6ada1169-9af2-4ce3-bb7e-de40ea64dfd1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Hora de la gran cita! 🗓️', body_es = 'Entre las semanas 18-22 se hace la ecografía más detallada. Contarán mis dedos, mirarán mi corazón, todo. ¿Ya has pedido cita con el médico?', title_fr = 'Le grand rendez-vous ! 🗓️', body_fr = 'Entre 18 et 22 semaines a lieu l''échographie la plus détaillée. On va compter mes doigts, vérifier mon cœur, tout ! Avez-vous pris rendez-vous ?', title_hi = 'बड़ी मुलाकात का समय! 🗓️', body_hi = '18-22 हफ़्ते सबसे विस्तृत अल्ट्रासाउंड का समय है। वे मेरी उँगलियाँ, मेरा दिल, सब कुछ गिनेंगे। डॉक्टर से अपॉइंटमेंट ले लिया?', title_id = 'Saatnya pertemuan besar! 🗓️', body_id = 'Minggu ke-18 sampai 22 adalah waktu USG paling detail. Mereka akan menghitung jariku, jantungku, semuanya. Sudah buat janji dengan dokter?', title_ja = '大事な対面の日！🗓️', body_ja = '18-22週はいちばん詳しいエコー検査の時期だよ。指も心臓も、ぜんぶ数えてくれるの。予約はした？', title_ko = '중요한 만남의 시간이에요! 🗓️', body_ko = '18-22주는 가장 자세한 초음파를 보는 시기예요. 제 손가락, 심장, 모든 걸 세어 볼 거예요. 진료 예약하셨어요?', title_nl = 'Tijd voor de grote afspraak! 🗓️', body_nl = 'In week 18-22 vindt de meest uitgebreide echo plaats. Ze tellen mijn vingers, bekijken mijn hart, alles! Heb je al een afspraak gemaakt?', title_pl = 'Czas na wielkie spotkanie! 🗓️', body_pl = 'Tydzień 18-22 to czas najdokładniejszego USG. Policzą moje paluszki, sprawdzą serce, wszystko. Zapisałaś się do lekarza?', title_pt = 'Hora do grande encontro! 🗓️', body_pt = 'Entre as 18 e as 22 semanas faz-se a ecografia mais detalhada. Vão contar os meus dedos, ver o meu coração, tudo! Já marcou a consulta?', title_sv = 'Dags för det stora mötet! 🗓️', body_sv = 'Veckorna 18-22 är tiden för det mest detaljerade ultraljudet. De räknar mina fingrar, kollar mitt hjärta, allt! Har du bokat tid hos läkaren?', title_vi = 'Đến ngày hẹn quan trọng! 🗓️', body_vi = 'Tuần 18-22 là lúc siêu âm chi tiết nhất. Người ta sẽ đếm ngón tay, xem tim con, mọi thứ của con. Mẹ đã đặt lịch bác sĩ chưa?', title_zh = '重要的见面日！🗓️', body_zh = '18-22周是最详细的B超检查时间。医生会数我的手指、看我的心脏，检查一切。你预约好了吗？' WHERE id = '7529d4a8-1e26-4d8b-8bcf-18154f789283' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Pss, estoy durmiendo 😴', body_es = 'Yo también tengo mi horario de sueño, mamá. Cuando caminas, me meces y me duermo; cuando te tumbas, ¡me despierto y monto una discoteca! Perdona 😇', title_fr = 'Chut, je dors 😴', body_fr = 'Moi aussi j''ai mon rythme de sommeil, Maman. Quand vous marchez, je me berce et je dors, et quand vous vous allongez, je me réveille et je fais la fête ! Pardon 😇', title_hi = 'श्श्श, मैं सो रहा हूँ 😴', body_hi = 'मेरा भी सोने का शेड्यूल है, माँ। आप चलती हैं तो मैं झूलते हुए सो जाता हूँ, और आप लेटती हैं तो जागकर डिस्को करता हूँ! माफ़ करना 😇', title_id = 'Ssst, aku sedang tidur 😴', body_id = 'Aku juga punya jadwal tidur, Bunda. Saat Anda berjalan, aku terayun dan tertidur, tapi saat Anda berbaring, aku bangun dan berdisko! Maaf ya 😇', title_ja = 'シーッ、今ねんね中 😴', body_ja = 'わたしにも睡眠リズムがあるの、ママ。ママが歩くとゆらゆらして眠って、横になると起きてディスコをはじめちゃう！ごめんね 😇', title_ko = '쉿, 저 자고 있어요 😴', body_ko = '저도 수면 패턴이 있어요, 엄마. 엄마가 걸으면 흔들려서 잠들고, 누우면 깨어나서 춤을 춰요! 미안해요 😇', title_nl = 'Sst, ik slaap 😴', body_nl = 'Ik heb ook een slaapritme, mama. Als jij loopt, word ik in slaap gewiegd, en als jij gaat liggen, word ik wakker en geef ik een feestje! Sorry 😇', title_pl = 'Ciii, śpię 😴', body_pl = 'Ja też mam swój rytm snu, Mamo. Gdy chodzisz, kołyszę się i śpię, a gdy się kładziesz, budzę się i robię dyskotekę! Przepraszam 😇', title_pt = 'Chiu, estou a dormir 😴', body_pt = 'Eu também tenho horários de sono, Mamã. Quando caminha, sou embalado e adormeço; quando se deita, acordo e faço uma festa! Desculpe 😇', title_sv = 'Schh, jag sover 😴', body_sv = 'Jag har också mina sovtider, mamma. När du går vaggas jag till sömns, och när du lägger dig vaknar jag och har disco! Förlåt 😇', title_vi = 'Suỵt, con đang ngủ 😴', body_vi = 'Con cũng có giờ giấc ngủ, mẹ ạ. Khi mẹ đi lại, con được đung đưa và ngủ, còn khi mẹ nằm xuống, con thức dậy mở vũ trường! Xin lỗi mẹ 😇', title_zh = '嘘，我在睡觉 😴', body_zh = '妈妈，我也有自己的作息。你走路时，我被摇着睡着了；你躺下时，我就醒来开迪斯科！对不起啦 😇' WHERE id = '8731dd9d-3325-4b84-b0cd-b6cef3da8f89' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Ya llevas la mitad del camino! 🏁', body_es = '¡Enhorabuena! Ya has dejado atrás 20 semanas. Estás en el ecuador del embarazo. Eres increíble, ¡tienes que celebrarlo!', title_fr = 'La moitié du chemin est faite ! 🏁', body_fr = 'Félicitations ! 20 semaines déjà. Vous êtes à l''équateur de votre grossesse. Vous êtes formidable, ça se fête !', title_hi = 'आधा रास्ता पूरा! 🏁', body_hi = 'बधाई हो! 20 हफ़्ते पूरे हो गए। आप प्रेग्नेंसी की भूमध्य रेखा पर हैं। आप कमाल हैं, इसका जश्न मनाना चाहिए!', title_id = 'Separuh perjalanan sudah lewat! 🏁', body_id = 'Selamat! 20 minggu sudah terlewati. Anda berada di garis khatulistiwa kehamilan. Anda luar biasa, ini harus dirayakan!', title_ja = '折り返し地点！🏁', body_ja = 'おめでとうございます！20週が過ぎました。妊娠期間の折り返し地点です。あなたはすばらしい、お祝いしましょう！', title_ko = '절반이 지났어요! 🏁', body_ko = '축하해요! 20주가 지났어요. 임신 기간의 딱 절반에 왔어요. 정말 대단해요, 꼭 기념해야 해요!', title_nl = 'Halverwege! 🏁', body_nl = 'Gefeliciteerd! 20 weken achter de rug. Je bent op de evenaar van je zwangerschap. Je doet het fantastisch, dat moet gevierd worden!', title_pl = 'Połowa drogi za nami! 🏁', body_pl = 'Gratulacje! 20 tygodni za tobą. Jesteś na równiku ciąży. Jesteś wspaniała, trzeba to uczcić!', title_pt = 'Metade do caminho já está! 🏁', body_pt = 'Parabéns! 20 semanas já ficaram para trás. Está a meio da gravidez. É fantástica e merece celebrar!', title_sv = 'Halva vägen är avklarad! 🏁', body_sv = 'Grattis! 20 veckor har gått. Du är vid graviditetens ekvator. Du är fantastisk och det här ska firas!', title_vi = 'Đã đi được nửa chặng đường! 🏁', body_vi = 'Chúc mừng mẹ! 20 tuần đã qua. Mẹ đang ở đường xích đạo của thai kỳ. Mẹ thật tuyệt vời, điều này đáng để ăn mừng!', title_zh = '已经走完一半啦！🏁', body_zh = '恭喜！20周已经过去，你正站在孕期的“赤道线”上。你太棒了，值得好好庆祝一下！' WHERE id = '61323e5e-ad2b-4a40-a3f3-72d99e6d77ef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Cargando... 50% ⏳', body_es = '¡Enhorabuena! Hemos dejado atrás la mitad del camino. ¡Una foto en la Galería es perfecta para celebrar este día tan especial! ✨', title_fr = 'Loading... 50% ⏳', body_fr = 'Félicitations ! Nous avons fait la moitié du chemin. Une photo dans la Galerie serait parfaite pour fêter ce jour historique ! ✨', title_hi = 'Loading... 50% ⏳', body_hi = 'बधाई हो! हमने आधा रास्ता तय कर लिया। इस ऐतिहासिक दिन को मनाने के लिए गैलरी में एक फ़ोटो तो बनती है! ✨', title_id = 'Loading... 50% ⏳', body_id = 'Selamat! Kita sudah melewati separuh perjalanan. Untuk merayakan hari bersejarah ini, sebuah foto di Galeri pasti cocok! ✨', title_ja = '読み込み中... 50% ⏳', body_ja = 'おめでとう！半分まで来たね。この記念すべき日に、ギャラリーに写真を1枚残すのがぴったり！✨', title_ko = '로딩 중... 50% ⏳', body_ko = '축하해요! 우리 절반을 왔어요. 이 특별한 날을 기념하려면 갤러리에 사진 한 장이 딱이에요! ✨', title_nl = 'Loading... 50% ⏳', body_nl = 'Gefeliciteerd! We zijn halverwege. Een foto in de Galerij past perfect bij deze bijzondere dag! ✨', title_pl = 'Loading... 50% ⏳', body_pl = 'Gratulacje! Połowa drogi za nami. Ten wyjątkowy dzień warto uczcić zdjęciem w Galerii! ✨', title_pt = 'A carregar... 50% ⏳', body_pt = 'Parabéns! Já fizemos metade do caminho. Uma foto na Galeria fica a matar para assinalar este dia histórico! ✨', title_sv = 'Loading... 50% ⏳', body_sv = 'Grattis! Vi har klarat halva vägen. Ett foto i Galleriet passar perfekt för att fira den här historiska dagen! ✨', title_vi = 'Loading... 50% ⏳', body_vi = 'Chúc mừng mẹ! Chúng mình đã đi được nửa chặng đường. Một tấm ảnh trong Thư viện ảnh thật hợp để ghi dấu ngày đặc biệt này! ✨', title_zh = '加载中……50% ⏳', body_zh = '恭喜！我们已经走完一半的路。为了纪念这个特别的日子，在相册里放一张照片吧！✨' WHERE id = '5d030bf9-1346-4234-959d-a123523b7611' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Papá me notará?', body_es = 'Si pone la mano en tu barriga, quizá también le salude a él.❤️', title_fr = 'Papa pourra me sentir ?', body_fr = 'S''il pose sa main sur votre ventre, je lui dirai peut-être bonjour aussi.❤️', title_hi = 'क्या पापा मुझे महसूस करेंगे?', body_hi = 'अगर वे पेट पर हाथ रखें, तो शायद मैं उन्हें भी हैलो कहूँ।❤️', title_id = 'Apakah Ayah bisa merasakanku?', body_id = 'Kalau ia meletakkan tangannya di perut, mungkin aku akan menyapanya juga.❤️', title_ja = 'パパにもわかるかな？', body_ja = 'パパがお腹に手を当てたら、パパにもあいさつするかも。❤️', title_ko = '아빠도 저를 느낄 수 있을까요?', body_ko = '아빠가 배에 손을 올리면 아빠에게도 인사할지 몰라요.❤️', title_nl = 'Kan papa me voelen?', body_nl = 'Als hij zijn hand op je buik legt, zeg ik hem misschien ook gedag.❤️', title_pl = 'Czy tata mnie poczuje?', body_pl = 'Jeśli położy dłoń na brzuchu, może jemu też powiem cześć.❤️', title_pt = 'O pai vai sentir-me?', body_pt = 'Se ele puser a mão na sua barriga, talvez também lhe diga olá.❤️', title_sv = 'Kan pappa känna mig?', body_sv = 'Om han lägger handen på magen kanske jag säger hej till honom också.❤️', title_vi = 'Bố có cảm nhận được con không?', body_vi = 'Nếu bố đặt tay lên bụng, có khi con cũng sẽ chào bố.❤️', title_zh = '爸爸能感觉到我吗？', body_zh = '如果爸爸把手放在肚子上，也许我也会跟他打招呼。❤️' WHERE id = '5a1b20c0-b4ed-4031-8577-4c8ce7ee3faf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Tienes sueños de colores?', body_es = 'Los sueños del embarazo son como películas, ¿verdad? ¿Salgo yo en esos sueños? 😴', title_fr = 'Vous faites des rêves en couleur ?', body_fr = 'Les rêves de grossesse ressemblent à des films, n''est-ce pas ? Je suis dans vos rêves, moi aussi ? 😴', title_hi = 'रंगीन सपने आते हैं?', body_hi = 'प्रेग्नेंसी के सपने फ़िल्म जैसे होते हैं, है ना? क्या मैं भी उन सपनों में हूँ? 😴', title_id = 'Mimpi berwarna-warni?', body_id = 'Mimpi saat hamil bisa seperti film, bukan? Apakah aku juga ada di mimpi itu? 😴', title_ja = 'カラフルな夢を見ていますか？', body_ja = '妊娠中の夢は映画みたいでしょう？その夢にわたしも出てる？😴', title_ko = '알록달록한 꿈을 꾸나요?', body_ko = '임신 중 꿈은 영화 같죠? 그 꿈에 저도 나오나요? 😴', title_nl = 'Droom je in kleur?', body_nl = 'Zwangerschapsdromen zijn net films, toch? Speel ik ook in die dromen? 😴', title_pl = 'Śnią ci się kolorowe sny?', body_pl = 'Ciążowe sny są jak filmy, prawda? Czy ja też w nich jestem? 😴', title_pt = 'Tem tido sonhos coloridos?', body_pt = 'Os sonhos da gravidez parecem filmes, não é? Eu também apareço neles? 😴', title_sv = 'Drömmer du i färg?', body_sv = 'Graviditetsdrömmar är som filmer, eller hur? Är jag också med i dina drömmar? 😴', title_vi = 'Mẹ có mơ những giấc mơ đầy màu sắc?', body_vi = 'Giấc mơ khi mang thai như phim vậy, phải không mẹ? Con có trong những giấc mơ đó không? 😴', title_zh = '做彩色的梦了吗？', body_zh = '孕期的梦就像电影一样，对吧？梦里也有我吗？😴' WHERE id = 'dafe2e2c-e054-4c05-a7f0-7e5828a0bd40' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Estoy cogiendo el ritmo 🥁', body_es = 'Mi corazón late con precisión y practico la respiración. A veces tengo hipo.', title_fr = 'Je trouve mon rythme 🥁', body_fr = 'Mon cœur bat régulièrement et je m''entraîne à respirer. Parfois, j''ai le hoquet.', title_hi = 'मैं ताल पकड़ रहा हूँ 🥁', body_hi = 'मेरा दिल सही ताल में धड़कता है, मैं साँस लेने का अभ्यास कर रहा हूँ। कभी-कभी मुझे हिचकी आती है।', title_id = 'Aku menemukan irama 🥁', body_id = 'Jantungku berdetak teratur, dan aku berlatih bernapas. Kadang aku cegukan.', title_ja = 'リズムをとっているよ 🥁', body_ja = '心臓は規則正しく動いていて、呼吸の練習をしているの。ときどきしゃっくりも出るよ。', title_ko = '리듬을 타고 있어요 🥁', body_ko = '제 심장은 규칙적으로 뛰고, 숨 쉬는 연습을 하고 있어요. 가끔 딸꾹질도 해요.', title_nl = 'Ik vind mijn ritme 🥁', body_nl = 'Mijn hart klopt regelmatig en ik oefen met ademen. Soms heb ik de hik.', title_pl = 'Łapię rytm 🥁', body_pl = 'Moje serce bije miarowo, ćwiczę oddychanie. Czasem mam czkawkę.', title_pt = 'Estou a apanhar o ritmo 🥁', body_pt = 'O meu coração bate certinho e estou a treinar a respiração. Às vezes tenho soluços.', title_sv = 'Jag hittar rytmen 🥁', body_sv = 'Mitt hjärta slår jämnt och jag tränar på att andas. Ibland får jag hicka.', title_vi = 'Con đang bắt nhịp 🥁', body_vi = 'Tim con đập đều, con đang tập thở. Thỉnh thoảng con còn bị nấc cụt.', title_zh = '我找到节奏啦 🥁', body_zh = '我的心跳很稳，我在练习呼吸。有时还会打嗝。' WHERE id = '23bdc5ce-4bf9-4c06-b27f-3cf7672d0391' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Elige sabores! 👅', body_es = 'El sabor del líquido amniótico cambia según lo que comes. ¿Has comido guindilla? ¡Lo notará!', title_fr = 'Il découvre les saveurs ! 👅', body_fr = 'Le goût du liquide amniotique change selon ce que vous mangez. Vous avez mangé du piment ? Il le sentira !', title_hi = 'स्वाद चुन रहा है! 👅', body_hi = 'एम्नियोटिक द्रव का स्वाद आपके खाने के हिसाब से बदलता है। तीखी मिर्च खाई? उसे यह महसूस होगा!', title_id = 'Ia memilih rasa! 👅', body_id = 'Rasa cairan ketuban berubah sesuai makanan Anda. Makan cabai pedas? Ia akan merasakannya!', title_ja = '味を選んでいます！👅', body_ja = '羊水の味はママが食べたものによって変わります。辛いトウガラシを食べた？赤ちゃんも感じますよ！', title_ko = '맛을 고르고 있어요! 👅', body_ko = '양수의 맛은 엄마가 먹는 음식에 따라 달라져요. 매운 고추를 드셨나요? 아기도 느낄 거예요!', title_nl = 'Je baby proeft al! 👅', body_nl = 'De smaak van het vruchtwater verandert met wat jij eet. Pittige peper gegeten? Je baby proeft het!', title_pl = 'Wybiera smaki! 👅', body_pl = 'Smak płynu owodniowego zmienia się w zależności od tego, co jesz. Zjadłaś ostrą paprykę? Ono to poczuje!', title_pt = 'Está a escolher sabores! 👅', body_pt = 'O sabor do líquido amniótico muda conforme o que come. Comeu malagueta? O bebé vai senti-lo!', title_sv = 'Barnet väljer smaker! 👅', body_sv = 'Fostervattnets smak ändras efter vad du äter. Har du ätit chili? Det kommer barnet att känna!', title_vi = 'Bé đang chọn hương vị! 👅', body_vi = 'Vị của nước ối thay đổi theo những gì mẹ ăn. Mẹ ăn ớt cay à? Bé sẽ cảm nhận được đấy!', title_zh = '宝宝在挑选味道！👅', body_zh = '羊水的味道会随着你吃的东西而变化。吃辣椒了？宝宝会尝到的！' WHERE id = 'fae74e2f-98a8-45d5-8202-44383d0eb18a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Día de cuidarte 💅', body_es = 'Si te han salido manchas del embarazo, protégete del sol. ¿Qué tal si hoy te pones una mascarilla facial?', title_fr = 'Journée bien-être 💅', body_fr = 'Si des taches de grossesse apparaissent, protégez-vous du soleil. Et si vous vous offriez un masque pour le visage aujourd''hui ?', title_hi = 'अपनी देखभाल का दिन 💅', body_hi = 'अगर प्रेग्नेंसी के धब्बे दिख रहे हैं, तो धूप से बचिए। आज खुद के लिए एक फ़ेस मास्क कैसा रहेगा?', title_id = 'Hari merawat diri 💅', body_id = 'Jika muncul flek kehamilan, lindungi diri dari matahari. Bagaimana kalau memakai masker wajah hari ini?', title_ja = '自分をいたわる日 💅', body_ja = '妊娠によるシミができたら、日差しから肌を守りましょう。今日はフェイスマスクでもしてみませんか？', title_ko = '나를 돌보는 날 💅', body_ko = '임신 기미가 생겼다면 햇볕을 피하세요. 오늘은 얼굴 마스크팩을 해 보는 건 어때요?', title_nl = 'Verwendag 💅', body_nl = 'Heb je zwangerschapsvlekken? Bescherm je dan tegen de zon. Wat vind je van een gezichtsmasker vandaag?', title_pl = 'Dzień dbania o siebie 💅', body_pl = 'Jeśli pojawiły się przebarwienia ciążowe, chroń się przed słońcem. Może zrobisz sobie dziś maseczkę?', title_pt = 'Dia de cuidar de si 💅', body_pt = 'Se apareceram manchas da gravidez, proteja-se do sol. Que tal fazer hoje uma máscara facial?', title_sv = 'En dag för egenvård 💅', body_sv = 'Om du har fått graviditetsfläckar, skydda dig mot solen. Vad sägs om att unna dig en ansiktsmask i dag?', title_vi = 'Ngày chăm sóc bản thân 💅', body_vi = 'Nếu xuất hiện nám thai kỳ, hãy tránh nắng. Hôm nay mẹ đắp một chiếc mặt nạ cho mình nhé?', title_zh = '呵护自己的一天 💅', body_zh = '如果长了孕斑，要注意防晒。今天给自己敷个面膜怎么样？' WHERE id = 'b707fa58-b376-47be-9e74-acc0d0bc553a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te aprieta el pantalón? 👖', body_es = '¿Has anotado tu peso inicial en el Registro de peso? 📈', title_fr = 'Votre pantalon vous serre ? 👖', body_fr = 'Avez-vous noté votre poids de départ dans le Suivi du poids ? 📈', title_hi = 'पैंट टाइट लग रही है? 👖', body_hi = 'क्या आपने वेट ट्रैकर में शुरुआती वज़न दर्ज किया? 📈', title_id = 'Celana terasa sempit? 👖', body_id = 'Sudah mencatat berat badan awal di Pelacak Berat Badan? 📈', title_ja = 'ズボンがきつい？👖', body_ja = '「体重トラッカー」に最初の体重を記録しましたか？📈', title_ko = '바지가 꽉 끼나요? 👖', body_ko = '체중 기록에 시작 체중을 기록하셨나요? 📈', title_nl = 'Zit je broek te strak? 👖', body_nl = 'Heb je je startgewicht al in de Gewichtsteller genoteerd? 📈', title_pl = 'Spodnie robią się ciasne? 👖', body_pl = 'Zapisałaś swoją początkową wagę w Liczniku wagi? 📈', title_pt = 'As calças estão apertadas? 👖', body_pt = 'Já registou o seu peso inicial no Registo de Peso? 📈', title_sv = 'Sitter byxorna tajt? 👖', body_sv = 'Har du skrivit in din startvikt i Viktspåraren? 📈', title_vi = 'Quần bị chật rồi? 👖', body_vi = 'Mẹ đã ghi cân nặng ban đầu vào Theo dõi cân nặng chưa? 📈', title_zh = '裤子变紧了？👖', body_zh = '在体重记录里记下初始体重了吗？📈' WHERE id = '6389a83c-6f25-4ebf-a0ca-cf0883f3ce2a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Se te hinchan los pies? 👠', body_es = 'Puede empezar la hinchazón. En el trabajo o en casa, sube los pies siempre que puedas. ¡Elige calzado cómodo!', title_fr = 'Vos pieds gonflent ? 👠', body_fr = 'Des œdèmes peuvent apparaître. Au travail comme à la maison, surélevez vos jambes dès que possible. Choisissez des chaussures confortables !', title_hi = 'पैरों में सूजन है? 👠', body_hi = 'सूजन शुरू हो सकती है। काम पर हों या घर पर, जब हो सके पैर ऊपर रखिए। आरामदायक जूते चुनिए!', title_id = 'Kaki bengkak? 👠', body_id = 'Pembengkakan bisa mulai muncul. Di kantor atau di rumah, angkat kaki Anda sebisa mungkin. Pilih sepatu yang nyaman!', title_ja = '足がむくみますか？👠', body_ja = 'むくみが始まることがあります。職場でも家でも、できるだけ足を高くしましょう。楽な靴を選んでくださいね！', title_ko = '발이 붓나요? 👠', body_ko = '부종이 시작될 수 있어요. 회사에서나 집에서나 가능할 때마다 다리를 올려 두세요. 편한 신발을 고르세요!', title_nl = 'Dikke voeten? 👠', body_nl = 'Er kan vocht vast gaan zitten. Leg op je werk of thuis je benen zo vaak mogelijk omhoog. Kies comfortabele schoenen!', title_pl = 'Puchną ci nogi? 👠', body_pl = 'Mogą pojawić się obrzęki. W pracy i w domu, kiedy tylko możesz, unoś nogi. Wybieraj wygodne buty!', title_pt = 'Os pés estão inchados? 👠', body_pt = 'Podem começar os edemas. No trabalho ou em casa, eleve os pés sempre que puder. Escolha sapatos confortáveis!', title_sv = 'Svullnar fötterna? 👠', body_sv = 'Svullnad kan börja komma. På jobbet eller hemma, lägg upp fötterna när du kan. Välj bekväma skor!', title_vi = 'Chân bị phù? 👠', body_vi = 'Có thể bắt đầu bị phù. Ở nơi làm việc hay ở nhà, hãy kê chân cao khi có thể. Chọn giày thoải mái nhé!', title_zh = '脚肿了？👠', body_zh = '水肿可能开始出现。无论在单位还是在家，尽量把脚抬高。选双舒服的鞋吧！' WHERE id = '323b3eda-82d0-406d-9ef8-03c3ba37648c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Hip... Hip... 🤭', body_es = '¿Tu barriga da saltitos rítmicos? Tranquila, mamá, ¡es solo hipo! Estoy entrenando mi diafragma.', title_fr = 'Hic... Hic... 🤭', body_fr = 'Votre ventre sursaute en rythme ? Pas d''inquiétude, Maman, c''est juste le hoquet ! J''entraîne mon diaphragme.', title_hi = 'हिच... हिच... 🤭', body_hi = 'पेट लय में उछल रहा है? घबराइए मत, माँ, यह बस हिचकी है! मैं अपने डायाफ़्राम का अभ्यास कर रहा हूँ।', title_id = 'Hik... Hik... 🤭', body_id = 'Perut Anda melompat-lompat berirama? Jangan takut, Bunda, ini hanya cegukan! Aku sedang melatih diafragmaku.', title_ja = 'ひっく...ひっく... 🤭', body_ja = 'お腹がリズミカルにぴくぴくする？心配しないで、ママ、しゃっくりしてるだけ！横隔膜の練習中なの。', title_ko = '딸꾹... 딸꾹... 🤭', body_ko = '배가 규칙적으로 들썩이나요? 걱정 마세요, 엄마, 그냥 딸꾹질이에요! 횡격막을 연습하고 있어요.', title_nl = 'Hik... Hik... 🤭', body_nl = 'Springt je buik ritmisch op en neer? Geen zorgen, mama, ik heb gewoon de hik! Ik train mijn middenrif.', title_pl = 'Hik... Hik... 🤭', body_pl = 'Brzuch rytmicznie podskakuje? Nie bój się, Mamo, to tylko czkawka! Ćwiczę swoją przeponę.', title_pt = 'Hic... Hic... 🤭', body_pt = 'A barriga dá saltinhos ritmados? Não se assuste, Mamã, são só soluços! Estou a treinar o meu diafragma.', title_sv = 'Hick... Hick... 🤭', body_sv = 'Hoppar magen rytmiskt? Var inte rädd, mamma, det är bara hicka! Jag tränar min diafragma.', title_vi = 'Hức... Hức... 🤭', body_vi = 'Bụng mẹ giật nhịp nhàng? Đừng lo mẹ ơi, đó chỉ là con bị nấc thôi! Con đang tập cơ hoành.', title_zh = '嗝……嗝……🤭', body_zh = '肚子有节奏地一跳一跳？别怕，妈妈，我只是在打嗝！我在锻炼我的横膈膜。' WHERE id = 'e5b18866-69e0-4ac8-9b93-de4b2812e136' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Descubre su carita! 👶', body_es = 'Con las manos se toca la cara, la nariz e incluso el cordón umbilical. Su sentido del tacto se desarrolla. ¡Se está conociendo!', title_fr = 'Il découvre son visage ! 👶', body_fr = 'Avec ses mains, il touche son visage, son nez, et même son cordon ombilical. Son sens du toucher se développe. Il apprend à se connaître !', title_hi = 'अपना चेहरा खोज रहा है! 👶', body_hi = 'वह हाथों से अपना चेहरा, नाक, यहाँ तक कि गर्भनाल भी छूता है। छूने का एहसास विकसित हो रहा है। वह खुद को पहचान रहा है!', title_id = 'Ia menjelajahi wajahnya! 👶', body_id = 'Dengan tangannya ia menyentuh wajah, hidung, bahkan tali pusarnya. Indra perabanya berkembang. Ia mengenal dirinya sendiri!', title_ja = '顔を探検中！👶', body_ja = '手で顔や鼻、へその緒にまで触れています。触覚が発達中。自分のことを知ろうとしているのです！', title_ko = '얼굴을 탐험하고 있어요! 👶', body_ko = '손으로 얼굴, 코, 탯줄까지 만져요. 촉감이 발달하고 있어요. 아기가 자기 자신을 알아가고 있어요!', title_nl = 'Je baby ontdekt het gezichtje! 👶', body_nl = 'Met de handjes raakt je baby het gezicht, de neus en zelfs de navelstreng aan. De tastzin ontwikkelt zich. Je baby leert zichzelf kennen!', title_pl = 'Odkrywa swoją buzię! 👶', body_pl = 'Dotyka rączkami twarzy, nosa, a nawet pępowiny. Rozwija się zmysł dotyku. Poznaje siebie!', title_pt = 'Está a descobrir o rosto! 👶', body_pt = 'Toca com as mãos no rosto, no nariz e até no cordão umbilical. O tato está a desenvolver-se. Está a conhecer-se a si próprio!', title_sv = 'Barnet utforskar sitt ansikte! 👶', body_sv = 'Barnet rör vid ansiktet, näsan och till och med navelsträngen med händerna. Känseln utvecklas. Barnet lär känna sig själv!', title_vi = 'Bé đang khám phá khuôn mặt! 👶', body_vi = 'Bé dùng tay chạm vào mặt, mũi, cả dây rốn. Xúc giác đang phát triển. Bé đang làm quen với chính mình!', title_zh = '宝宝在探索自己的小脸！👶', body_zh = '宝宝用小手摸自己的脸、鼻子，甚至脐带。触觉正在发育，宝宝在认识自己！' WHERE id = 'b050527e-1e40-44a0-ab00-fb32d6abb570' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Pepinillos y helado? 🥒🍦', body_es = '¿Te apetecen mezclas raras? Son señales de tu cuerpo. Pero intenta mantener el azúcar y la sal con moderación.', title_fr = 'Cornichons et glace ? 🥒🍦', body_fr = 'Envie de mélanges étranges ? Ce sont des signaux de votre corps. Mais essayez de garder le sucre et le sel dans la norme.', title_hi = 'अचार और आइसक्रीम? 🥒🍦', body_hi = 'अजीब मेल खाने का मन है? ये आपके शरीर के संकेत हैं। लेकिन चीनी और नमक को सीमा में रखने की कोशिश कीजिए।', title_id = 'Acar dan es krim? 🥒🍦', body_id = 'Ingin kombinasi yang aneh? Itu sinyal dari tubuh Anda. Tapi usahakan gula dan garam tetap dalam batas normal.', title_ja = 'ピクルスとアイスクリーム？🥒🍦', body_ja = '変わった組み合わせが食べたくなる？体からのサインです。でも糖分と塩分はほどほどにしましょう。', title_ko = '피클과 아이스크림? 🥒🍦', body_ko = '이상한 조합이 당기나요? 몸이 보내는 신호예요. 그래도 설탕과 소금은 적당히 드세요.', title_nl = 'Augurk met ijs? 🥒🍦', body_nl = 'Zin in vreemde combinaties? Dat zijn signalen van je lichaam. Maar probeer suiker en zout binnen de perken te houden.', title_pl = 'Ogórki i lody? 🥒🍦', body_pl = 'Masz ochotę na dziwne połączenia? To sygnały twojego ciała. Ale staraj się utrzymać cukier i sól w normie.', title_pt = 'Pickles e gelado? 🥒🍦', body_pt = 'Apetecem-lhe misturas estranhas? São sinais do seu corpo. Mas tente manter o açúcar e o sal dentro do normal.', title_sv = 'Inlagd gurka och glass? 🥒🍦', body_sv = 'Vill du ha konstiga kombinationer? Det är kroppens signaler. Men försök hålla socker och salt på normal nivå.', title_vi = 'Dưa chua và kem? 🥒🍦', body_vi = 'Thèm những món kết hợp kỳ lạ? Đó là tín hiệu của cơ thể. Nhưng hãy cố giữ đường và muối ở mức vừa phải.', title_zh = '酸黄瓜配冰淇淋？🥒🍦', body_zh = '想吃奇怪的组合？这是身体在发出信号。不过尽量把糖和盐控制在合理范围内。' WHERE id = '866256da-856c-40a8-a2d6-0e562a2b89fa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Es como un coco! 🥥', body_es = 'Mide unos 28 cm. ¡Ya pesa más de medio kilo! Ahora da patadas más fuertes.', title_fr = 'Il est grand comme une noix de coco ! 🥥', body_fr = 'Environ 28 cm. Il pèse plus d''un demi-kilo ! Maintenant, ses coups de pied sont plus forts.', title_hi = 'नारियल जितना है! 🥥', body_hi = 'लगभग 28 cm। वज़न आधा किलो से ज़्यादा हो गया! अब वह और ज़ोर से किक मारता है।', title_id = 'Seukuran kelapa! 🥥', body_id = 'Sekitar 28 cm. Beratnya sudah lebih dari setengah kilo! Kini tendangannya makin kuat.', title_ja = 'ココナッツくらいの大きさ！🥥', body_ja = '約28 cm。体重は500 gを超えました！キックもどんどん力強くなっています。', title_ko = '코코넛만 해요! 🥥', body_ko = '약 28cm예요. 몸무게가 500g을 넘었어요! 이제 발차기가 더 세져요.', title_nl = 'Zo groot als een kokosnoot! 🥥', body_nl = 'Ongeveer 28 cm. Je baby weegt al meer dan een halve kilo! De trappen worden nu steviger.', title_pl = 'Jest wielkości kokosa! 🥥', body_pl = 'Około 28 cm. Waży już ponad pół kilo! Teraz kopie mocniej.', title_pt = 'Do tamanho de um coco! 🥥', body_pt = 'Cerca de 28 cm. Já passou do meio quilo! Agora dá pontapés mais fortes.', title_sv = 'Lika stor som en kokosnöt! 🥥', body_sv = 'Ungefär 28 cm. Vikten har passerat ett halvt kilo! Nu sparkar barnet ännu kraftigare.', title_vi = 'To bằng quả dừa rồi! 🥥', body_vi = 'Khoảng 28 cm. Cân nặng đã hơn nửa ký! Giờ bé đạp mạnh hơn rồi.', title_zh = '有一个椰子那么大！🥥', body_zh = '大约28 cm，体重超过半公斤了！现在宝宝踢得更有力了。' WHERE id = 'b5881822-5bbb-4123-8e83-7e5e1502c2a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Ponemos música? 🎶', body_es = '¡Mamá, oigo los sonidos de fuera! Las canciones que te gustan a ti también me gustan a mí. ¿Bailamos juntos?', title_fr = 'On met de la musique ? 🎶', body_fr = 'Maman, j''entends les sons du dehors ! J''aime aussi les chansons que vous aimez. On danse ensemble ?', title_hi = 'गाना लगाएँ? 🎶', body_hi = 'माँ, मुझे बाहर की आवाज़ें सुनाई देती हैं! आपके पसंदीदा गाने मुझे भी पसंद हैं। साथ में डांस करें?', title_id = 'Putar musik yuk? 🎶', body_id = 'Bunda, aku mendengar suara-suara di luar! Lagu-lagu kesukaan Anda juga kusukai. Kita berdansa bersama?', title_ja = '音楽をかけようか？🎶', body_ja = 'ママ、外の音が聞こえるよ！ママの好きな歌、わたしも大好き。一緒に踊ろうか？', title_ko = '음악 틀어 볼까요? 🎶', body_ko = '엄마, 바깥 소리가 들려요! 엄마가 좋아하는 노래는 저도 좋아요. 같이 춤출까요?', title_nl = 'Zullen we muziek opzetten? 🎶', body_nl = 'Mama, ik hoor de geluiden van buiten! Jouw lievelingsliedjes vind ik ook leuk. Zullen we samen dansen?', title_pl = 'Włączymy muzykę? 🎶', body_pl = 'Mamo, słyszę dźwięki z zewnątrz! Lubię piosenki, które ty lubisz. Zatańczymy razem?', title_pt = 'Pomos música? 🎶', body_pt = 'Mamã, ouço os sons lá de fora! Também gosto das músicas de que gosta. Vamos dançar juntos?', title_sv = 'Ska vi sätta på musik? 🎶', body_sv = 'Mamma, jag hör ljuden utanför! Låtarna du gillar gillar jag också. Ska vi dansa tillsammans?', title_vi = 'Mở nhạc nhé? 🎶', body_vi = 'Mẹ ơi, con nghe được âm thanh bên ngoài! Những bài hát mẹ thích, con cũng thích. Mình cùng nhảy nhé?', title_zh = '放点音乐吧？🎶', body_zh = '妈妈，我能听到外面的声音！你喜欢的歌我也喜欢。我们一起跳舞好吗？' WHERE id = 'b4b9bd27-17f0-4aee-8b06-793656f6ef67' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Mis ojos bailan...', body_es = 'Aunque tengo los párpados cerrados, ya sueño. ¿Qué crees que hay en mis sueños?', title_fr = 'Mes yeux dansent...', body_fr = 'Mes paupières sont fermées, mais je rêve déjà. À votre avis, de quoi je rêve ?', title_hi = 'मेरी आँखें नाच रही हैं...', body_hi = 'पलकें बंद हैं, फिर भी मैं सपने देखने लगा हूँ। आपको क्या लगता है, मेरे सपने में क्या है?', title_id = 'Mataku menari...', body_id = 'Meski kelopak mataku tertutup, aku sudah bermimpi. Menurut Anda, apa yang ada di mimpiku?', title_ja = '目がダンスしているよ...', body_ja = 'まぶたは閉じているけど、もう夢を見ているの。どんな夢だと思う？', title_ko = '제 눈이 춤을 춰요...', body_ko = '눈꺼풀은 감겨 있지만 벌써 꿈을 꿔요. 제가 무슨 꿈을 꿀 것 같아요?', title_nl = 'Mijn ogen dansen...', body_nl = 'Mijn oogleden zijn nog dicht, maar ik droom al. Waar denk jij dat ik over droom?', title_pl = 'Moje oczy tańczą...', body_pl = 'Choć moje powieki są zamknięte, już śnię. Jak myślisz, co mi się śni?', title_pt = 'Os meus olhos estão a dançar...', body_pt = 'Mesmo com as pálpebras fechadas, já sonho. O que acha que há nos meus sonhos?', title_sv = 'Mina ögon dansar...', body_sv = 'Även om mina ögonlock är stängda drömmer jag redan. Vad tror du att jag drömmer om?', title_vi = 'Mắt con đang nhảy múa...', body_vi = 'Dù mí mắt còn nhắm, con đã biết mơ rồi. Mẹ nghĩ con đang mơ gì?', title_zh = '我的眼睛在跳舞……', body_zh = '虽然眼睑还闭着，我已经会做梦了。你猜我梦见了什么？' WHERE id = '88a2f76b-bbca-49e6-a2ea-fe93e58a6be7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te arde el estómago? 🔥', body_es = 'El útero presiona el estómago. Come poco y a menudo. No te tumbes justo después de comer, siéntate erguida.', title_fr = 'Des brûlures d''estomac ? 🔥', body_fr = 'L''utérus appuie sur l''estomac. Mangez peu mais souvent. Ne vous allongez pas juste après le repas, restez assise bien droite.', title_hi = 'सीने में जलन? 🔥', body_hi = 'गर्भाशय पेट को दबा रहा है। थोड़ा-थोड़ा, पर बार-बार खाइए। खाने के तुरंत बाद मत लेटिए, सीधी बैठिए।', title_id = 'Perut terasa panas? 🔥', body_id = 'Rahim menekan lambung. Makan sedikit-sedikit tapi sering. Jangan langsung berbaring setelah makan, duduklah tegak.', title_ja = '胸やけがしますか？🔥', body_ja = '子宮が胃を押し上げています。少量ずつこまめに食べましょう。食後すぐに横にならず、まっすぐ座ってください。', title_ko = '속이 쓰리세요? 🔥', body_ko = '자궁이 위를 누르고 있어요. 조금씩 자주 드세요. 식사 직후에 눕지 말고 똑바로 앉으세요.', title_nl = 'Last van brandend maagzuur? 🔥', body_nl = 'Je baarmoeder drukt op je maag. Eet vaak kleine beetjes. Ga na het eten niet meteen liggen, maar zit rechtop.', title_pl = 'Pali cię w żołądku? 🔥', body_pl = 'Macica uciska żołądek. Jedz mało, ale często. Nie kładź się zaraz po jedzeniu, siedź prosto.', title_pt = 'Azia? 🔥', body_pt = 'O útero está a apertar o estômago. Coma pouco, mas muitas vezes. Não se deite logo depois de comer, sente-se direita.', title_sv = 'Halsbränna? 🔥', body_sv = 'Livmodern trycker på magsäcken. Ät lite men ofta. Lägg dig inte direkt efter maten, sitt upprätt.', title_vi = 'Bị ợ nóng? 🔥', body_vi = 'Tử cung đang chèn ép dạ dày. Hãy ăn ít một nhưng nhiều bữa. Đừng nằm ngay sau khi ăn, hãy ngồi thẳng.', title_zh = '烧心了？🔥', body_zh = '子宫在挤压胃。少量多餐，饭后不要马上躺下，坐直一点。' WHERE id = '302938ba-54dd-42b1-8785-76afddeea091' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Llega la recta final! 🏁', body_es = 'Últimos días del 2.º trimestre. ¡Duerme a gusto antes de que llegue la 3.ª etapa!', title_fr = 'La dernière ligne droite approche ! 🏁', body_fr = 'Ce sont les derniers jours du 2e trimestre. Dormez tout votre soûl avant le 3e !', title_hi = 'आखिरी सीधा रास्ता आ रहा है! 🏁', body_hi = 'दूसरी तिमाही के आखिरी दिन। तीसरा दौर आने से पहले जी भरकर सो लीजिए!', title_id = 'Lintasan terakhir sudah dekat! 🏁', body_id = 'Hari-hari terakhir trimester ke-2. Tidurlah sepuasnya sebelum tahap ke-3 tiba!', title_ja = 'ラストスパートが近づいています！🏁', body_ja = '妊娠中期の最後の日々です。後期に入る前に、たっぷり眠っておきましょう！', title_ko = '마지막 직선 코스가 다가와요! 🏁', body_ko = '임신 2기의 마지막 날들이에요. 3기가 오기 전에 실컷 주무세요!', title_nl = 'Het laatste rechte stuk komt eraan! 🏁', body_nl = 'De laatste dagen van het 2e trimester. Slaap zoveel je kunt voordat het 3e begint!', title_pl = 'Nadchodzi ostatnia prosta! 🏁', body_pl = 'Ostatnie dni 2. trymestru. Wyśpij się do syta, zanim przyjdzie 3. etap!', title_pt = 'Chega a reta final! 🏁', body_pt = 'Últimos dias do 2.º trimestre. Durma à vontade antes de chegar a 3.ª fase!', title_sv = 'Upploppet är här! 🏁', body_sv = 'De sista dagarna av andra trimestern. Sov så mycket du kan innan tredje fasen kommer!', title_vi = 'Chặng nước rút đến rồi! 🏁', body_vi = 'Những ngày cuối của tam cá nguyệt thứ 2. Hãy ngủ thật đã trước khi bước vào giai đoạn 3!', title_zh = '最后冲刺来啦！🏁', body_zh = '孕中期的最后几天。在第三阶段到来之前，好好睡个够吧！' WHERE id = '486ac2e6-38fa-429a-b2e0-197066312def' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Se te ha salido el ombligo? 🔘', body_es = 'Al crecer la barriga, el ombligo sobresale. Tranquila, ¡volverá a su sitio después del parto!', title_fr = 'Votre nombril ressort ? 🔘', body_fr = 'À mesure que le ventre grossit, le nombril ressort. Pas d''inquiétude, il redeviendra normal après l''accouchement !', title_hi = 'नाभि बाहर निकल आई? 🔘', body_hi = 'पेट बढ़ने के साथ नाभि उभर आती है। घबराइए मत, डिलीवरी के बाद ठीक हो जाएगी!', title_id = 'Pusar menonjol keluar? 🔘', body_id = 'Seiring perut membesar, pusar ikut menonjol. Jangan khawatir, setelah melahirkan akan kembali normal!', title_ja = 'おへそが出てきた？🔘', body_ja = 'お腹が大きくなるにつれ、おへそが出てくることがあります。心配しないで、産後には元に戻ります！', title_ko = '배꼽이 튀어나왔나요? 🔘', body_ko = '배가 커지면서 배꼽이 볼록 튀어나와요. 걱정 마세요, 출산 후에는 돌아와요!', title_nl = 'Steekt je navel naar buiten? 🔘', body_nl = 'Als je buik groeit, kan je navel naar buiten gaan staan. Geen zorgen, na de bevalling komt dat weer goed!', title_pl = 'Pępek ci wyskoczył? 🔘', body_pl = 'Gdy brzuch rośnie, pępek się uwypukla. Nie bój się, po porodzie wróci do normy!', title_pt = 'O umbigo saltou para fora? 🔘', body_pt = 'À medida que a barriga cresce, o umbigo fica saliente. Não se preocupe, volta ao normal depois do parto!', title_sv = 'Har naveln poppat ut? 🔘', body_sv = 'När magen växer buktar naveln ut. Var inte rädd, den blir som vanligt efter förlossningen!', title_vi = 'Rốn mẹ lồi ra? 🔘', body_vi = 'Khi bụng to lên, rốn sẽ lồi ra. Đừng lo, sau sinh sẽ trở lại bình thường!', title_zh = '肚脐凸出来了？🔘', body_zh = '肚子变大，肚脐就会鼓出来。别担心，生完宝宝会恢复的！' WHERE id = '473ac730-c42b-4a8b-8df8-3ff17fbbb8fc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Contracción o ensayo? 🤔', body_es = '¿Se te pone dura la barriga? Pueden ser contracciones falsas. El útero está ensayando para el parto. Si no duelen, es normal.', title_fr = 'Contraction ou entraînement ? 🤔', body_fr = 'Votre ventre durcit ? Il peut s''agir de fausses contractions. L''utérus s''entraîne pour l''accouchement. Si elles sont indolores, c''est normal.', title_hi = 'दर्द या अभ्यास? 🤔', body_hi = 'पेट सख्त हो रहा है? यह झूठा दर्द हो सकता है। गर्भाशय डिलीवरी का अभ्यास कर रहा है। अगर दर्द नहीं है, तो यह सामान्य है।', title_id = 'Kontraksi atau latihan? 🤔', body_id = 'Perut terasa mengeras? Ini bisa jadi kontraksi palsu. Rahim sedang berlatih untuk persalinan. Jika tidak nyeri, itu normal.', title_ja = '陣痛？それとも練習？🤔', body_ja = 'お腹が張りますか？前駆陣痛かもしれません。子宮がお産の練習をしているのです。痛みがなければ普通のことです。', title_ko = '진통일까, 연습일까? 🤔', body_ko = '배가 단단해지나요? 가진통일 수 있어요. 자궁이 출산을 연습하는 거예요. 아프지 않다면 정상이에요.', title_nl = 'Wee of oefening? 🤔', body_nl = 'Wordt je buik hard? Dit kunnen oefenweeën zijn. Je baarmoeder oefent voor de bevalling. Doet het geen pijn, dan is het normaal.', title_pl = 'Skurcz czy trening? 🤔', body_pl = 'Brzuch twardnieje? To mogą być skurcze przepowiadające. Macica ćwiczy przed porodem. Jeśli nie bolą, to normalne.', title_pt = 'Contração ou treino? 🤔', body_pt = 'A barriga fica dura? Podem ser contrações falsas. O útero está a treinar para o parto. Se não doem, é normal.', title_sv = 'Värk eller träning? 🤔', body_sv = 'Blir magen hård? Det kan vara förvärkar. Livmodern tränar inför förlossningen. Om det inte gör ont är det normalt.', title_vi = 'Cơn co thật hay tập dượt? 🤔', body_vi = 'Bụng mẹ cứng lại? Đó có thể là cơn co giả. Tử cung đang tập dượt cho ca sinh. Nếu không đau thì là bình thường.', title_zh = '宫缩还是演习？🤔', body_zh = '肚子发硬？这可能是假性宫缩，子宫在为分娩做练习。如果不痛，就是正常的。' WHERE id = '3993d773-d077-4047-afc5-47cd2550cb94' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Evita la comida salada 🧂', body_es = 'Si se te hinchan los pies, reduce la sal. Mucha agua y perejil pueden ayudar. ¿No te aprieta el anillo?', title_fr = 'Évitez les aliments salés 🧂', body_fr = 'Si vos pieds gonflent, réduisez le sel. Beaucoup d''eau et du persil peuvent aider. Votre bague ne vous serre pas le doigt ?', title_hi = 'नमकीन खाने से बचिए 🧂', body_hi = 'अगर पैर सूज रहे हैं, तो नमक कम कीजिए। खूब पानी और अजमोद मदद कर सकते हैं। अँगूठी उँगली में टाइट तो नहीं हो रही?', title_id = 'Hindari makanan asin 🧂', body_id = 'Jika kaki bengkak, kurangi garam. Banyak minum air dan peterseli bisa membantu. Cincin Anda tidak terasa sempit, kan?', title_ja = '塩辛いものは控えて 🧂', body_ja = '足がむくむなら、塩分を減らしましょう。たっぷりのお水とパセリが助けになることも。指輪がきつくなっていませんか？', title_ko = '짠 음식은 피해요 🧂', body_ko = '발이 부으면 소금을 줄이세요. 충분한 물과 파슬리가 도움이 될 수 있어요. 반지가 손가락에 끼지는 않나요?', title_nl = 'Laat zout eten staan 🧂', body_nl = 'Heb je dikke voeten? Eet dan minder zout. Veel water en peterselie kunnen helpen. Zit je ring niet te strak?', title_pl = 'Unikaj słonych potraw 🧂', body_pl = 'Jeśli puchną ci nogi, ogranicz sól. Dużo wody i natka pietruszki mogą pomóc. Obrączka nie robi się za ciasna?', title_pt = 'Fuja da comida salgada 🧂', body_pt = 'Se os pés incham, reduza o sal. Muita água e salsa podem ajudar. O anel não lhe está a apertar o dedo?', title_sv = 'Undvik salt mat 🧂', body_sv = 'Om fötterna svullnar, dra ner på saltet. Mycket vatten och persilja kan hjälpa. Sitter ringen trångt på fingret?', title_vi = 'Tránh đồ ăn mặn 🧂', body_vi = 'Nếu chân bị phù, hãy giảm muối. Uống nhiều nước và ăn rau mùi tây có thể giúp ích. Nhẫn có bị chật ở ngón tay không?', title_zh = '远离咸的食物 🧂', body_zh = '如果脚肿，就少吃盐。多喝水和吃香芹可能有帮助。戒指戴着没变紧吧？' WHERE id = '60d55b22-fbf7-460c-942e-d9f7e0731669' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡La pequeña fábrica se ha puesto en marcha! 🏭', body_es = 'Ya no es mi hígado, sino mi médula ósea la que fabrica células sanguíneas. Para ayudarme, ¿qué hay rico en hierro en Nutrición?', title_fr = 'La petite usine est en marche ! 🏭', body_fr = 'Ce n''est plus mon foie, mais ma moelle osseuse qui fabrique les cellules sanguines. Pour m''aider, qu''y a-t-il de riche en fer dans la rubrique Nutrition ?', title_hi = 'नन्ही फ़ैक्ट्री चालू हो गई! 🏭', body_hi = 'अब मेरा लिवर नहीं, बोन मैरो खून की कोशिकाएँ बनाता है। मेरी मदद के लिए पोषण में आयरन से भरपूर क्या है?', title_id = 'Pabrik kecil mulai bekerja! 🏭', body_id = 'Bukan lagi hatiku, kini sumsum tulangku yang memproduksi sel darah. Untuk membantuku, apa yang kaya zat besi di bagian Nutrisi?', title_ja = '小さな工場が稼働中！🏭', body_ja = '今は肝臓じゃなくて、骨髄が血液細胞をつくっているの。わたしを助けるために、「栄養」で鉄分たっぷりのものは何がある？', title_ko = '작은 공장이 가동됐어요! 🏭', body_ko = '이제 간이 아니라 골수가 혈액 세포를 만들어요. 저를 도와주려면 영양 섹션에서 철분이 풍부한 음식을 찾아볼까요?', title_nl = 'Het kleine fabriekje draait! 🏭', body_nl = 'Niet meer mijn lever, maar mijn beenmerg maakt nu bloedcellen. Wat is er in Voeding rijk aan ijzer om me te helpen?', title_pl = 'Mała fabryka ruszyła! 🏭', body_pl = 'Komórki krwi produkuje już nie moja wątroba, tylko szpik kostny. Co bogatego w żelazo masz w sekcji Odżywianie, żeby mi pomóc?', title_pt = 'A pequena fábrica entrou em funcionamento! 🏭', body_pt = 'Já não é o meu fígado, agora é a medula óssea que produz as células do sangue. Para me ajudar, o que há de rico em ferro na Nutrição?', title_sv = 'Den lilla fabriken har satt igång! 🏭', body_sv = 'Nu är det inte min lever utan min benmärg som tillverkar blodkroppar. Vad finns det järnrikt i Kost för att hjälpa mig?', title_vi = 'Nhà máy nhỏ đã hoạt động! 🏭', body_vi = 'Giờ không phải gan mà tủy xương của con sản xuất tế bào máu. Để giúp con, mục Dinh dưỡng có món nào giàu sắt nhỉ?', title_zh = '小工厂开工啦！🏭', body_zh = '现在不是我的肝脏，而是我的骨髓在制造血细胞。想帮帮我，营养板块里有哪些富含铁的食物？' WHERE id = '6de7574a-4dcf-48fd-a091-4641ee581b82' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Shhh, estoy durmiendo... 🤫', body_es = 'Mamá, ¿por qué no me muevo? Porque duermo la mayor parte del día. Cuando yo duermo, descansa tú también.', title_fr = 'Chut, je dors... 🤫', body_fr = 'Maman, pourquoi je ne bouge pas ? Parce que je dors la plus grande partie de la journée. Quand je dors, reposez-vous aussi.', title_hi = 'श्श्श, मैं सो रहा हूँ... 🤫', body_hi = 'माँ, मैं हिल क्यों नहीं रहा? क्योंकि मैं दिन का ज़्यादातर समय सोता हूँ। जब मैं सोऊँ, तब आप भी आराम कीजिए।', title_id = 'Ssst, aku sedang tidur... 🤫', body_id = 'Bunda, kenapa aku tidak bergerak? Karena aku tidur hampir sepanjang hari. Saat aku tidur, Anda juga istirahat ya.', title_ja = 'シーッ、ねんね中... 🤫', body_ja = 'ママ、どうして動かないのかって？1日のほとんどを眠って過ごしているからだよ。わたしが寝ているときは、ママも休んでね。', title_ko = '쉿, 저 자고 있어요... 🤫', body_ko = '엄마, 제가 왜 안 움직이냐고요? 하루 대부분을 자거든요. 제가 잘 때 엄마도 쉬세요.', title_nl = 'Sst, ik slaap... 🤫', body_nl = 'Mama, waarom beweeg ik niet? Omdat ik het grootste deel van de dag slaap. Rust jij ook als ik slaap.', title_pl = 'Ciii, śpię... 🤫', body_pl = 'Mamo, dlaczego się nie ruszam? Bo większość dnia przesypiam. Gdy ja śpię, ty też odpocznij.', title_pt = 'Chiu, estou a dormir... 🤫', body_pt = 'Mamã, porque não me mexo? Porque durmo a maior parte do dia. Quando eu durmo, descanse também.', title_sv = 'Schh, jag sover... 🤫', body_sv = 'Mamma, varför rör jag mig inte? För att jag sover större delen av dagen. Vila du också när jag sover.', title_vi = 'Suỵt, con đang ngủ... 🤫', body_vi = 'Mẹ ơi, sao con không cử động? Vì con ngủ gần hết cả ngày. Khi con ngủ, mẹ cũng nghỉ ngơi nhé.', title_zh = '嘘，我在睡觉……🤫', body_zh = '妈妈，我为什么不动？因为我一天大部分时间都在睡觉。我睡觉时，你也休息一下吧。' WHERE id = 'a2eb3d0f-d97b-4159-b6ca-2c03e31ea7ae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Hora del ejercicio secreto! 🧘‍♀️', body_es = 'No olvides los ejercicios de Kegel. Donde estés sentada, aprieta y suelta los músculos del suelo pélvico. ¡Te servirán en el parto!', title_fr = 'L''heure de l''exercice secret ! 🧘‍♀️', body_fr = 'N''oubliez pas les exercices de Kegel. Assise, contractez et relâchez les muscles du périnée. Ils vous serviront pendant l''accouchement !', title_hi = 'सीक्रेट एक्सरसाइज़ का समय! 🧘‍♀️', body_hi = 'कीगल एक्सरसाइज़ न भूलें। बैठे-बैठे पेल्विक फ़्लोर की मांसपेशियों को कसिए और छोड़िए। डिलीवरी में काम आएँगी!', title_id = 'Waktunya latihan rahasia! 🧘‍♀️', body_id = 'Jangan lupa senam Kegel. Sambil duduk, kencangkan lalu lepaskan otot dasar panggul. Akan berguna saat persalinan!', title_ja = 'ひみつのトレーニングの時間！🧘‍♀️', body_ja = 'ケーゲル体操を忘れずに。座ったまま骨盤底筋をぎゅっと締めて、ゆるめて。お産のときに役立ちます！', title_ko = '비밀 운동 시간! 🧘‍♀️', body_ko = '케겔 운동을 잊지 마세요. 앉은 자리에서 골반저근을 조였다 풀어 주세요. 출산할 때 필요해요!', title_nl = 'Tijd voor een geheime training! 🧘‍♀️', body_nl = 'Vergeet je bekkenbodemoefeningen niet. Span je bekkenbodemspieren aan en laat ze los terwijl je zit. Dat heb je nodig bij de bevalling!', title_pl = 'Czas na sekretny trening! 🧘‍♀️', body_pl = 'Pamiętaj o ćwiczeniach Kegla. Na siedząco napinaj i rozluźniaj mięśnie dna miednicy. Przydadzą się przy porodzie!', title_pt = 'Hora do treino secreto! 🧘‍♀️', body_pt = 'Não se esqueça dos exercícios de Kegel. Sentada, contraia e relaxe os músculos do pavimento pélvico. Vão ser precisos no parto!', title_sv = 'Dags för hemlig träning! 🧘‍♀️', body_sv = 'Glöm inte knipövningarna. Spänn och slappna av bäckenbottenmusklerna där du sitter. Det kommer du att ha nytta av vid förlossningen!', title_vi = 'Giờ tập bí mật! 🧘‍♀️', body_vi = 'Đừng quên bài tập Kegel. Ngồi tại chỗ, siết rồi thả cơ sàn chậu. Sẽ cần khi sinh đấy!', title_zh = '秘密锻炼时间！🧘‍♀️', body_zh = '别忘了凯格尔运动。坐着就能做：收紧再放松盆底肌。分娩时会用得上！' WHERE id = 'cb6d62d7-338e-4fb3-907d-9bfa587ddc19' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Primeros ensayos de respiración! 🫁', body_es = 'En mis pulmones se forma el surfactante. Esta sustancia me ayudará a respirar por primera vez cuando nazca. ¡Estoy practicando!', title_fr = 'Premiers exercices de respiration ! 🫁', body_fr = 'Du surfactant se forme dans mes poumons. Cette substance m''aidera à prendre ma première respiration à la naissance. Je m''entraîne !', title_hi = 'साँस की पहली प्रैक्टिस! 🫁', body_hi = 'मेरे फेफड़ों में सर्फ़ेक्टेंट बन रहा है। यह पदार्थ जन्म के समय मुझे पहली साँस लेने में मदद करेगा। मैं अभ्यास कर रहा हूँ!', title_id = 'Latihan napas pertama! 🫁', body_id = 'Surfaktan mulai terbentuk di paru-paruku. Zat ini akan membantuku mengambil napas pertama saat lahir. Aku sedang berlatih!', title_ja = '初めての呼吸の練習！🫁', body_ja = '肺にサーファクタントができているよ。生まれたときに最初の呼吸をするのを助けてくれる物質なの。練習中だよ！', title_ko = '첫 호흡 연습! 🫁', body_ko = '제 폐에 계면활성제가 생기고 있어요. 이 물질이 태어날 때 첫 숨을 쉬도록 도와줄 거예요. 연습 중이에요!', title_nl = 'De eerste ademhalingsoefeningen! 🫁', body_nl = 'In mijn longen wordt surfactant aangemaakt. Die stof helpt me bij mijn eerste ademteug na de geboorte. Ik ben aan het oefenen!', title_pl = 'Pierwsze ćwiczenia oddechowe! 🫁', body_pl = 'W moich płucach powstaje surfaktant. Ta substancja pomoże mi wziąć pierwszy oddech po urodzeniu. Ćwiczę!', title_pt = 'Primeiros treinos de respiração! 🫁', body_pt = 'Nos meus pulmões está a formar-se surfactante. Esta substância vai ajudar-me a respirar pela primeira vez quando nascer. Estou a treinar!', title_sv = 'De första andningsövningarna! 🫁', body_sv = 'Surfaktant bildas i mina lungor. Det ämnet hjälper mig att ta mitt första andetag när jag föds. Jag tränar!', title_vi = 'Những bài tập thở đầu tiên! 🫁', body_vi = 'Phổi con đang tạo ra chất surfactant. Chất này sẽ giúp con hít hơi thở đầu tiên khi chào đời. Con đang tập đây!', title_zh = '最初的呼吸练习！🫁', body_zh = '我的肺里正在生成表面活性物质。出生时，它会帮助我完成第一次呼吸。我在练习呢！' WHERE id = '26be4f7a-020a-4656-9916-24ee79dcc7a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Qué ha sido ese ruido, mamá? 🔊', body_es = 'Los ruidos repentinos me sobresaltan. Cuando tú estás tranquila, yo también. ¿Me cantas una nana?', title_fr = 'C''était quoi ce bruit, Maman ? 🔊', body_fr = 'Les bruits soudains me font sursauter. Quand vous êtes calme, je suis calme aussi. Vous me chantez une berceuse ?', title_hi = 'वह आवाज़ क्या थी, माँ? 🔊', body_hi = 'अचानक शोर से मैं चौंक जाता हूँ। जब आप शांत होती हैं, मैं भी शांत रहता हूँ। मुझे लोरी सुनाएँगी?', title_id = 'Suara apa itu, Bunda? 🔊', body_id = 'Aku kaget mendengar suara keras yang tiba-tiba. Saat Anda tenang, aku juga tenang. Maukah Anda menyanyikan lagu nina bobo untukku?', title_ja = '今の音はなに、ママ？🔊', body_ja = '急な大きな音にびっくりしちゃう。ママが落ち着いていると、わたしも落ち着くの。子守唄を歌ってくれる？', title_ko = '엄마, 그게 무슨 소리였어요? 🔊', body_ko = '갑작스러운 소음에 깜짝 놀라요. 엄마가 차분하면 저도 차분해요. 자장가 불러 주실래요?', title_nl = 'Wat was dat voor geluid, mama? 🔊', body_nl = 'Van plotselinge geluiden schrik ik. Als jij rustig bent, ben ik ook rustig. Wil je een slaapliedje voor me zingen?', title_pl = 'Co to był za dźwięk, Mamo? 🔊', body_pl = 'Nagły hałas mnie wzdryga. Gdy ty jesteś spokojna, ja też jestem spokojne. Zaśpiewasz mi kołysankę?', title_pt = 'Que som foi aquele, Mamã? 🔊', body_pt = 'Os barulhos repentinos assustam-me. Quando está calma, eu também fico calmo. Pode cantar-me uma canção de embalar?', title_sv = 'Vad var det för ljud, mamma? 🔊', body_sv = 'Jag hoppar till av plötsligt oväsen. När du är lugn är jag också lugn. Kan du sjunga en vaggvisa för mig?', title_vi = 'Tiếng gì thế mẹ? 🔊', body_vi = 'Con giật mình khi có tiếng ồn đột ngột. Khi mẹ bình tĩnh, con cũng bình tĩnh. Mẹ hát ru cho con nhé?', title_zh = '妈妈，那是什么声音？🔊', body_zh = '突然的噪音会吓我一跳。你平静时，我也平静。能给我唱首摇篮曲吗？' WHERE id = 'ba959c1d-a66b-4198-9703-7d204b6d9029' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Tú eres mi cuna... 💤', body_es = 'Cuando caminas, me balanceo y me duermo. ¡Y cuando te paras, me despierto! ¿Seguimos con los paseos suaves para dormirme? 🚶‍♀️', title_fr = 'Mon berceau, c''est vous... 💤', body_fr = 'Quand vous marchez, je me berce et je m''endors. Quand vous vous arrêtez, je me réveille ! On continue les petites promenades pour m''endormir ? 🚶‍♀️', title_hi = 'आप ही मेरा पालना हैं... 💤', body_hi = 'आप चलती हैं तो मैं झूलते हुए सो जाता हूँ। आप रुकती हैं तो जाग जाता हूँ! मुझे सुलाने के लिए हल्की सैर जारी रखें? 🚶‍♀️', title_id = 'Andalah buaianku... 💤', body_id = 'Saat Anda berjalan, aku terayun lalu tertidur. Saat Anda berhenti, aku bangun! Kita lanjutkan jalan santai untuk menidurkanku? 🚶‍♀️', title_ja = 'ママはわたしのゆりかご... 💤', body_ja = 'ママが歩くと、ゆらゆら揺れて眠っちゃう。ママが止まると目が覚めるの！わたしを寝かしつけるために、軽いお散歩を続けようか？🚶‍♀️', title_ko = '엄마가 제 요람이에요... 💤', body_ko = '엄마가 걸으면 저는 흔들리며 잠들어요. 엄마가 멈추면 깨어나요! 저를 재우려면 가벼운 산책을 계속할까요? 🚶‍♀️', title_nl = 'Jij bent mijn wiegje... 💤', body_nl = 'Als jij loopt, word ik in slaap gewiegd. Als je stilstaat, word ik wakker! Zullen we rustige wandelingen blijven maken om me in slaap te wiegen? 🚶‍♀️', title_pl = 'Ty jesteś moją kołyską... 💤', body_pl = 'Gdy chodzisz, kołyszę się i zasypiam. A gdy się zatrzymujesz, budzę się! Chodźmy dalej na lekkie spacery, żeby mnie usypiać? 🚶‍♀️', title_pt = 'O meu berço é a Mamã... 💤', body_pt = 'Quando caminha, sou embalado e adormeço. Quando para, acordo! Continuamos com os passeios leves para me fazer adormecer? 🚶‍♀️', title_sv = 'Du är min vagga... 💤', body_sv = 'När du går vaggas jag till sömns. Och när du stannar vaknar jag! Ska vi fortsätta med lätta promenader för att söva mig? 🚶‍♀️', title_vi = 'Mẹ là chiếc nôi của con... 💤', body_vi = 'Khi mẹ đi lại, con được đung đưa và ngủ. Khi mẹ dừng lại, con thức dậy! Mình tiếp tục đi bộ nhẹ nhàng để ru con ngủ nhé? 🚶‍♀️', title_zh = '你就是我的摇篮……💤', body_zh = '你走路时，我被摇着睡着了；你停下来，我就醒了！为了哄我睡觉，我们继续轻松散步好吗？🚶‍♀️' WHERE id = '52571825-8dff-470b-9a01-2096ca6a9ef9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Has bebido el agua con azúcar? 🥤', body_es = 'La prueba de diabetes gestacional es importante. Hazla sin falta, por mi salud y por la tuya.', title_fr = 'Vous avez bu l''eau sucrée ? 🥤', body_fr = 'Le test du diabète gestationnel est important. Faites-le absolument, pour ma santé comme pour la vôtre.', title_hi = 'मीठा पानी पिया? 🥤', body_hi = 'जेस्टेशनल डायबिटीज़ टेस्ट ज़रूरी है। मेरी और आपकी सेहत के लिए यह जाँच ज़रूर कराइए।', title_id = 'Sudah minum air gula? 🥤', body_id = 'Tes diabetes gestasional itu penting. Pastikan diperiksa, demi kesehatanku dan kesehatan Anda.', title_ja = '甘い水は飲みましたか？🥤', body_ja = '妊娠糖尿病の検査は大切です。わたしのためにもママのためにも、必ず受けてね。', title_ko = '포도당 음료 드셨어요? 🥤', body_ko = '임신성 당뇨 검사는 중요해요. 저와 엄마의 건강을 위해 꼭 검사받으세요.', title_nl = 'Suikerwater gedronken? 🥤', body_nl = 'De test op zwangerschapsdiabetes is belangrijk. Laat je zeker testen, voor mijn gezondheid en voor de jouwe.', title_pl = 'Wypiłaś słodką wodę? 🥤', body_pl = 'Test na cukrzycę ciążową jest ważny. Koniecznie go zrób, dla mojego i twojego zdrowia.', title_pt = 'Bebeu a água com açúcar? 🥤', body_pt = 'O teste da diabetes gestacional é importante. Faça-o sem falta, pela minha saúde e pela sua.', title_sv = 'Har du druckit sockervatten? 🥤', body_sv = 'Testet för graviditetsdiabetes är viktigt. Se till att göra det, både för min och för din hälsa.', title_vi = 'Mẹ đã uống nước đường chưa? 🥤', body_vi = 'Xét nghiệm tiểu đường thai kỳ rất quan trọng. Hãy nhớ đi kiểm tra vì sức khỏe của cả con và mẹ.', title_zh = '喝过糖水了吗？🥤', body_zh = '妊娠糖尿病筛查很重要。为了我和你的健康，一定要去检查。' WHERE id = '1184b7b9-b4b5-43fa-a2bc-fd09d7701438' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Tienes una línea en la barriga? ➖', body_es = 'La línea nigra es cosa de las hormonas. Tranquila, desaparecerá después del parto. ¡Estás preciosa de todas formas!', title_fr = 'Une ligne sur votre ventre ? ➖', body_fr = 'La ligne brune (linea nigra) est due aux hormones. Pas d''inquiétude, elle disparaîtra après l''accouchement. Vous êtes belle telle que vous êtes !', title_hi = 'पेट पर रेखा है? ➖', body_hi = 'लिनिया नाइग्रा हार्मोन का काम है। घबराइए मत, डिलीवरी के बाद मिट जाएगी। आप हर रूप में सुंदर हैं!', title_id = 'Ada garis di perut? ➖', body_id = 'Linea Nigra adalah ulah hormon. Jangan khawatir, akan memudar setelah melahirkan. Anda cantik dalam keadaan apa pun!', title_ja = 'お腹に線がある？➖', body_ja = '正中線はホルモンのしわざです。心配しないで、産後には消えていきます。どんなあなたも美しいです！', title_ko = '배에 줄이 생겼나요? ➖', body_ko = '임신선(Linea Nigra)은 호르몬 때문이에요. 걱정 마세요, 출산 후에 사라져요. 엄마는 어떤 모습이든 아름다워요!', title_nl = 'Een streep op je buik? ➖', body_nl = 'De linea nigra komt door de hormonen. Geen zorgen, na de bevalling vervaagt hij. Je bent mooi zoals je bent!', title_pl = 'Masz kreskę na brzuchu? ➖', body_pl = 'Linea nigra to sprawka hormonów. Nie bój się, po porodzie zniknie. Jesteś piękna w każdej odsłonie!', title_pt = 'Tem uma linha na barriga? ➖', body_pt = 'A linea nigra é obra das hormonas. Não se preocupe, desaparece depois do parto. É bonita de qualquer forma!', title_sv = 'Har du fått ett streck på magen? ➖', body_sv = 'Linea nigra beror på hormonerna. Var inte rädd, den försvinner efter förlossningen. Du är vacker hur du än ser ut!', title_vi = 'Bụng mẹ có đường kẻ? ➖', body_vi = 'Đường Linea Nigra là do hormone. Đừng lo, nó sẽ mờ đi sau sinh. Mẹ đẹp trong mọi dáng vẻ!', title_zh = '肚子上有条线？➖', body_zh = '妊娠黑线是激素的作用。别担心，生完宝宝后会消失。你怎样都很美！' WHERE id = '27ba2d28-f6c7-4448-bd98-0c87bc789c84' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Mis posibilidades de sobrevivir han aumentado! 🌟', body_es = '¡Ya tengo 24 semanas! Médicamente ya se me considera viable. Es una etapa muy importante, mamá.', title_fr = 'Mes chances de vivre ont augmenté ! 🌟', body_fr = 'J''ai 24 semaines ! Médicalement, je suis désormais considéré comme viable. C''est une très grande étape, Maman.', title_hi = 'मेरे जीने की संभावना बढ़ गई! 🌟', body_hi = 'मैं 24 हफ़्ते का हो गया! चिकित्सा की दृष्टि से अब मुझे जीवित रहने में सक्षम माना जाता है। यह बहुत बड़ा पड़ाव है, माँ।', title_id = 'Peluangku untuk bertahan hidup meningkat! 🌟', body_id = 'Usiaku sudah 24 minggu! Secara medis, aku kini dianggap mampu bertahan hidup. Ini tonggak yang sangat besar, Bunda.', title_ja = '生きる力が高まったよ！🌟', body_ja = '24週になったよ！医学的には、もうお腹の外でも生きられる可能性があるとされるの。これはとても大きな節目なんだよ、ママ。', title_ko = '살아갈 가능성이 커졌어요! 🌟', body_ko = '24주가 됐어요! 의학적으로 이제 생존 가능하다고 봐요. 정말 큰 이정표예요, 엄마.', title_nl = 'Mijn kansen zijn gestegen! 🌟', body_nl = 'Ik ben 24 weken! Medisch gezien ben ik nu levensvatbaar. Dit is een hele grote mijlpaal, mama.', title_pl = 'Moje szanse wzrosły! 🌟', body_pl = 'Mam już 24 tygodnie! Z medycznego punktu widzenia jestem już zdolne do przeżycia. To bardzo ważny etap, Mamo.', title_pt = 'As minhas hipóteses de sobreviver aumentaram! 🌟', body_pt = 'Já tenho 24 semanas! Do ponto de vista médico, já sou considerado viável. É uma etapa enorme, Mamã.', title_sv = 'Mina chanser att klara mig har ökat! 🌟', body_sv = 'Jag är 24 veckor! Medicinskt räknas jag nu som livsduglig. Det är en väldigt stor milstolpe, mamma.', title_vi = 'Cơ hội sống của con đã tăng! 🌟', body_vi = 'Con được 24 tuần rồi! Về mặt y khoa, con đã được coi là có khả năng sống. Đây là một cột mốc rất lớn, mẹ ạ.', title_zh = '我的存活机会变大啦！🌟', body_zh = '我24周啦！从医学上讲，我已经被认为具有存活能力了。妈妈，这是一个非常重要的里程碑。' WHERE id = '352b7abf-9862-4591-888e-8f478b7b349c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te arde el estómago? 🔥', body_es = 'No arde porque me salga pelo, sino porque el útero presiona tu estómago. No te tumbes justo después de comer, siéntate erguida.', title_fr = 'Des brûlures d''estomac ? 🔥', body_fr = 'Ce n''est pas parce que mes cheveux poussent, mais parce que l''utérus appuie sur l''estomac que ça brûle. Ne vous allongez pas juste après le repas, restez assise bien droite.', title_hi = 'सीने में जलन? 🔥', body_hi = 'जलन मेरे बाल उगने से नहीं, बल्कि गर्भाशय के पेट को दबाने से होती है। खाने के तुरंत बाद मत लेटिए, सीधी बैठिए।', title_id = 'Perut terasa panas? 🔥', body_id = 'Rasa panas itu bukan karena rambutku tumbuh, tapi karena rahim menekan lambung. Jangan langsung berbaring setelah makan, duduklah tegak.', title_ja = '胸やけがしますか？🔥', body_ja = '胸やけは髪が生えているからじゃなくて、子宮が胃を押しているからなの。食べたらすぐに横にならず、まっすぐ座ってね。', title_ko = '속이 쓰리세요? 🔥', body_ko = '제 머리카락이 자라서가 아니라 자궁이 위를 눌러서 속이 쓰린 거예요. 식사 직후에 눕지 말고 똑바로 앉으세요.', title_nl = 'Last van brandend maagzuur? 🔥', body_nl = 'Het brandt niet omdat mijn haar groeit, maar omdat je baarmoeder op je maag drukt. Ga na het eten niet meteen liggen, maar zit rechtop.', title_pl = 'Pali cię w żołądku? 🔥', body_pl = 'Pali nie dlatego, że rosną mi włosy, tylko dlatego, że macica uciska żołądek. Nie kładź się zaraz po jedzeniu, siedź prosto.', title_pt = 'Azia? 🔥', body_pt = 'A azia não é por causa do meu cabelo a crescer, é porque o útero aperta o estômago. Não se deite logo depois de comer, sente-se direita.', title_sv = 'Halsbränna? 🔥', body_sv = 'Det svider inte för att mitt hår växer, utan för att livmodern trycker på magsäcken. Lägg dig inte direkt efter maten, sitt upprätt.', title_vi = 'Bị ợ nóng? 🔥', body_vi = 'Không phải do tóc con mọc đâu, mà do tử cung chèn ép dạ dày nên mẹ bị nóng rát. Đừng nằm ngay sau khi ăn, hãy ngồi thẳng.', title_zh = '烧心了？🔥', body_zh = '烧心不是因为我在长头发，而是因为子宫在挤压胃。饭后不要马上躺下，坐直一点。' WHERE id = '48f71f64-0f7f-494d-bb7e-d0d4e9ee139b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Mamá, me aburro! 🤸', body_es = 'Cuando estás quieta, me despierto. Acaríciate la barriga, ¿a lo mejor te respondo con una patadita?', title_fr = 'Maman, je m''ennuie ! 🤸', body_fr = 'Quand vous êtes immobile, je me réveille. Caressez votre ventre, je vous répondrai peut-être par un petit coup de pied ?', title_hi = 'माँ, मैं बोर हो रहा हूँ! 🤸', body_hi = 'जब आप शांत रहती हैं, मैं जाग जाता हूँ। पेट सहलाइए, शायद मैं एक छोटी सी किक से जवाब दूँ?', title_id = 'Bunda, aku bosan! 🤸', body_id = 'Saat Anda diam, aku bangun. Elus perut Anda, mungkin aku membalas dengan tendangan kecil?', title_ja = 'ママ、退屈だよ！🤸', body_ja = 'ママがじっとしていると、わたしは目が覚めるの。お腹をなでてみて、小さなキックでお返事するかも？', title_ko = '엄마, 심심해요! 🤸', body_ko = '엄마가 가만히 있으면 저는 깨어나요. 배를 쓰다듬어 보세요, 작은 발차기로 대답할지도 몰라요?', title_nl = 'Mama, ik verveel me! 🤸', body_nl = 'Als jij stilzit, word ik wakker. Aai over je buik, misschien antwoord ik met een klein trapje?', title_pl = 'Mamo, nudzę się! 🤸', body_pl = 'Gdy jesteś w bezruchu, ja się budzę. Pogłaszcz brzuch, może odpowiem ci małym kopnięciem?', title_pt = 'Mamã, estou aborrecido! 🤸', body_pt = 'Quando está quieta, eu acordo. Faça uma festa na barriga, talvez lhe responda com um pontapezinho?', title_sv = 'Mamma, jag har tråkigt! 🤸', body_sv = 'När du är stilla vaknar jag. Smeka magen, kanske svarar jag med en liten spark?', title_vi = 'Mẹ ơi, con chán quá! 🤸', body_vi = 'Khi mẹ ngồi yên, con thức dậy. Mẹ xoa bụng đi, biết đâu con sẽ đáp lại bằng một cú đạp nhỏ?', title_zh = '妈妈，我好无聊！🤸', body_zh = '你安静下来时，我就醒了。摸摸肚子，说不定我会踢一脚回应你？' WHERE id = '20bf8c66-4b67-4eac-9759-383a08875de7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te aprietan los zapatos? 👟', body_es = 'Tu número de pie puede aumentar. Ahora lo importante no es el estilo, sino la comodidad. ¡Pásate a unas zapatillas amplias!', title_fr = 'Vos chaussures vous serrent ? 👟', body_fr = 'Votre pointure peut augmenter. Maintenant, c''est le confort qui compte, pas le style. Passez à des baskets bien larges !', title_hi = 'जूते टाइट हो रहे हैं? 👟', body_hi = 'आपके जूते का साइज़ बढ़ सकता है। अब स्टाइल नहीं, आराम ज़रूरी है। खुले स्पोर्ट्स शूज़ पहनिए!', title_id = 'Sepatu terasa sempit? 👟', body_id = 'Ukuran kaki Anda bisa bertambah. Sekarang yang penting kenyamanan, bukan gaya. Beralihlah ke sepatu olahraga yang longgar!', title_ja = '靴がきつくなってきた？👟', body_ja = '足のサイズが大きくなることがあります。今はおしゃれより快適さが大切。ゆったりしたスニーカーに替えましょう！', title_ko = '신발이 꽉 끼나요? 👟', body_ko = '발 치수가 커질 수 있어요. 지금은 스타일보다 편안함이 중요해요. 넉넉한 운동화로 바꾸세요!', title_nl = 'Knellen je schoenen? 👟', body_nl = 'Je schoenmaat kan groter worden. Nu gaat comfort voor stijl. Kies ruime sportschoenen!', title_pl = 'Buty cię uwierają? 👟', body_pl = 'Rozmiar stopy może się zwiększyć. Teraz liczy się wygoda, nie styl. Przejdź na luźne buty sportowe!', title_pt = 'Os sapatos estão a apertar? 👟', body_pt = 'O número dos pés pode aumentar. Agora importa o conforto, não o estilo. Passe para ténis largos!', title_sv = 'Klämmer skorna? 👟', body_sv = 'Din skostorlek kan öka. Nu är det bekvämlighet och inte stil som gäller. Byt till rymliga sneakers!', title_vi = 'Giày bị chật? 👟', body_vi = 'Cỡ chân của mẹ có thể tăng. Giờ thoải mái quan trọng hơn phong cách. Hãy chuyển sang giày thể thao rộng rãi!', title_zh = '鞋子变紧了？👟', body_zh = '你的鞋码可能会变大。现在舒适比时尚更重要。换上宽松的运动鞋吧！' WHERE id = '526f7ea7-3f69-40d2-905e-c2bffa0601cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Mi pelo coge color! 🎨', body_es = 'Ha empezado la lotería genética. ¿Rubio, moreno o pelirrojo? Se está formando el pigmento de mi pelo. ¿A quién crees que me pareceré?', title_fr = 'Mes cheveux prennent leur couleur ! 🎨', body_fr = 'La loterie génétique a commencé. Blond, brun ou roux ? Le pigment de mes cheveux se forme. À votre avis, à qui vais-je ressembler ?', title_hi = 'मेरे बालों को रंग मिल रहा है! 🎨', body_hi = 'जेनेटिक लॉटरी शुरू! सुनहरे, काले या भूरे-लाल? मेरे बालों का रंग बन रहा है। आपको क्या लगता है, मैं किस पर जाऊँगा?', title_id = 'Rambutku mulai berwarna! 🎨', body_id = 'Lotre genetik sudah dimulai. Pirang, hitam, atau merah? Pigmen rambutku mulai terbentuk. Menurut Anda aku akan mirip siapa?', title_ja = '髪に色がついてきたよ！🎨', body_ja = '遺伝子のくじ引きが始まったよ。金髪？黒髪？それとも赤毛？髪の色素ができているの。誰に似ると思う？', title_ko = '제 머리카락에 색이 생기고 있어요! 🎨', body_ko = '유전자 복권이 시작됐어요. 금발, 흑발, 아니면 빨간 머리? 머리카락 색소가 생기고 있어요. 제가 누구를 닮을 것 같아요?', title_nl = 'Mijn haar krijgt kleur! 🎨', body_nl = 'De genetische loterij is begonnen. Blond, donker of rood? Het pigment van mijn haar wordt aangemaakt. Op wie denk je dat ik ga lijken?', title_pl = 'Moje włosy nabierają koloru! 🎨', body_pl = 'Zaczęła się genetyczna loteria. Blond, czarne czy rude? Powstaje pigment moich włosów. Jak myślisz, do kogo będę podobne?', title_pt = 'O meu cabelo está a ganhar cor! 🎨', body_pt = 'A lotaria genética começou. Loiro, moreno ou ruivo? Está a formar-se o pigmento do meu cabelo. Com quem acha que me vou parecer?', title_sv = 'Mitt hår får färg! 🎨', body_sv = 'Det genetiska lotteriet har börjat. Blond, mörk eller rödhårig? Pigmentet i mitt hår bildas. Vem tror du att jag kommer att likna?', title_vi = 'Tóc con đang lên màu! 🎨', body_vi = 'Xổ số di truyền đã bắt đầu. Vàng, đen hay đỏ? Sắc tố tóc của con đang hình thành. Mẹ nghĩ con sẽ giống ai?', title_zh = '我的头发在上色！🎨', body_zh = '基因彩票开奖啦。金发、黑发还是红发？我的头发色素正在形成。你觉得我会像谁？' WHERE id = '2383cc1a-d388-4623-bfbc-9b03b5278f79' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Harta de la hinchazón? 🎈', body_es = 'Paradoja: beber agua reduce el edema. Alimentos jugosos como el pepino y la sandía también pueden ayudarte. Aléjate de la sal.', title_fr = 'Marre des gonflements ? 🎈', body_fr = 'Paradoxe : boire de l''eau réduit les œdèmes. Les aliments riches en eau comme le concombre et la pastèque peuvent aussi aider. Évitez le sel.', title_hi = 'सूजन से परेशान हैं? 🎈', body_hi = 'अजीब पर सच: पानी पीने से सूजन कम होती है। खीरा, तरबूज़ जैसे रसीले खाने भी मदद कर सकते हैं। नमक से दूर रहिए।', title_id = 'Bosan dengan bengkak? 🎈', body_id = 'Paradoks: minum air justru mengurangi edema. Makanan berair seperti mentimun dan semangka juga bisa membantu. Jauhi garam.', title_ja = 'むくみにうんざり？🎈', body_ja = '意外ですが、お水を飲むとむくみが減ります。きゅうりやスイカなど水分の多い食べ物も助けになります。塩分は控えましょう。', title_ko = '붓기에 지쳤나요? 🎈', body_ko = '역설이지만 물을 마시면 부종이 줄어요. 오이, 수박 같은 수분 많은 음식도 도움이 돼요. 소금은 멀리하세요.', title_nl = 'Genoeg van het opgezwollen gevoel? 🎈', body_nl = 'Een paradox: water drinken vermindert vocht vasthouden. Waterrijk eten zoals komkommer en watermeloen kan ook helpen. Blijf weg van zout.', title_pl = 'Masz dość obrzęków? 🎈', body_pl = 'Paradoks: picie wody zmniejsza obrzęki. Pomóc mogą też soczyste produkty, jak ogórek czy arbuz. Trzymaj się z dala od soli.', title_pt = 'Farta do inchaço? 🎈', body_pt = 'Paradoxo: beber água reduz o edema. Alimentos ricos em água, como pepino e melancia, também podem ajudar. Afaste-se do sal.', title_sv = 'Trött på svullnaden? 🎈', body_sv = 'En paradox: att dricka vatten minskar svullnaden. Vattenrik mat som gurka och vattenmelon kan också hjälpa. Håll dig borta från salt.', title_vi = 'Chán ngấy chuyện bị phù? 🎈', body_vi = 'Nghịch lý: uống nước giúp giảm phù. Thực phẩm mọng nước như dưa chuột, dưa hấu cũng có thể giúp ích. Tránh xa muối nhé.', title_zh = '受够了水肿？🎈', body_zh = '听起来矛盾：喝水反而能减轻水肿。黄瓜、西瓜等多汁食物也能帮忙。少吃盐。' WHERE id = 'd07f0b6e-c86e-44de-8e9f-d89a09f2ec43' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Me estoy poniendo colorado...', body_es = '¡Mi piel ya no es transparente como el cristal! Mis capilares se llenan de sangre y me pongo rosado. ¡Por tu circulación, no olvides beber tu agua con el Registro de agua! 🥤', title_fr = 'Je rosis...', body_fr = 'Ma peau n''est plus transparente comme du verre ! Mes capillaires se remplissent de sang et je deviens tout rose. Pour votre circulation, n''oubliez pas de boire avec le Suivi d''hydratation ! 🥤', title_hi = 'मैं गुलाबी हो रहा हूँ...', body_hi = 'मेरी त्वचा अब काँच जैसी पारदर्शी नहीं रही! मेरी केशिकाएँ खून से भर रही हैं, मेरा रंग गुलाबी हो रहा है। अपने रक्त संचार के लिए वॉटर ट्रैकर से पानी पीना न भूलें! 🥤', title_id = 'Aku jadi kemerahan...', body_id = 'Kulitku tidak lagi bening seperti kaca! Kapilerku terisi darah dan warnaku jadi merah muda. Demi peredaran darah Anda, jangan lupa minum air lewat Pelacak Air! 🥤', title_ja = '赤くなってきたよ...', body_ja = 'わたしの肌は、もうガラスみたいに透き通っていないの！毛細血管に血がめぐって、ピンク色になってきたよ。ママの血の巡りのために、「水分トラッカー」でお水を飲むのを忘れないでね！🥤', title_ko = '저 볼이 빨개져요...', body_ko = '제 피부는 이제 유리처럼 투명하지 않아요! 모세혈관에 피가 차서 분홍빛이 되고 있어요. 엄마의 혈액 순환을 위해 물 기록으로 물 마시는 걸 잊지 마세요! 🥤', title_nl = 'Ik bloos...', body_nl = 'Mijn huid is niet meer doorzichtig als glas! Mijn haarvaatjes vullen zich met bloed en ik word roze. Vergeet voor je eigen bloedsomloop niet je water te drinken met de Waterteller! 🥤', title_pl = 'Rumienię się...', body_pl = 'Moja skóra nie jest już przezroczysta jak szkło! Naczynia włosowate wypełniają się krwią, robię się różowe. Dla swojego krążenia pamiętaj o wodzie z Licznika wody! 🥤', title_pt = 'Estou a ficar corado...', body_pt = 'A minha pele já não é transparente como vidro! Os capilares enchem-se de sangue e a minha cor fica rosada. Para a sua circulação, não se esqueça de beber água com o Registo de Água! 🥤', title_sv = 'Jag rodnar...', body_sv = 'Min hud är inte längre genomskinlig som glas! Mina kapillärer fylls med blod och jag blir rosa. Glöm inte att dricka ditt vatten i Vattenspåraren för ditt blodomlopp! 🥤', title_vi = 'Con đang ửng hồng...', body_vi = 'Da con không còn trong suốt như thủy tinh nữa! Mao mạch đầy máu, màu da con chuyển hồng. Để tuần hoàn tốt, mẹ đừng quên uống nước với Theo dõi uống nước nhé! 🥤', title_zh = '我脸红啦……', body_zh = '我的皮肤不再像玻璃一样透明了！毛细血管充满了血液，我变成了粉红色。为了你的血液循环，别忘了在饮水记录里喝够水！🥤' WHERE id = 'fec31592-3149-479f-9be0-155a720e090b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Oigo a papá? 🗣️', body_es = 'La voz de un hombre llega más profunda y la oigo mejor. Habla con papá, que me lea un cuento.', title_fr = 'J''entends Papa ? 🗣️', body_fr = 'Une voix d''homme est plus grave et je l''entends mieux. Parlez à Papa, qu''il me lise une histoire.', title_hi = 'क्या मुझे पापा सुनाई दे रहे हैं? 🗣️', body_hi = 'मर्दाना आवाज़ गहराई तक पहुँचती है और मैं उसे बेहतर सुनता हूँ। पापा से बात कीजिए, वे मुझे कहानी सुनाएँ।', title_id = 'Aku mendengar suara Ayah? 🗣️', body_id = 'Suara pria terdengar lebih dalam, dan aku bisa mendengarnya lebih baik. Bicaralah dengan Ayah, minta ia membacakan dongeng untukku.', title_ja = 'パパの声が聞こえる？🗣️', body_ja = '男の人の声は低くて響くから、よく聞こえるの。パパに話しかけて、お話を読んでもらってね。', title_ko = '아빠 목소리가 들리나요? 🗣️', body_ko = '남자 목소리는 더 깊게 울려서 더 잘 들려요. 아빠와 이야기해서 저에게 동화를 읽어 달라고 해 주세요.', title_nl = 'Hoor ik papa? 🗣️', body_nl = 'Een mannenstem klinkt dieper en die hoor ik beter. Praat met papa, laat hem me een verhaaltje voorlezen.', title_pl = 'Czy słyszę tatę? 🗣️', body_pl = 'Męski głos dociera głębiej i słyszę go lepiej. Porozmawiaj z tatą, niech przeczyta mi bajkę.', title_pt = 'É o pai que estou a ouvir? 🗣️', body_pt = 'A voz masculina é mais grave e ouço-a melhor. Fale com o pai, peça-lhe que me leia uma história.', title_sv = 'Hör jag pappa? 🗣️', body_sv = 'En mansröst når djupare in och jag hör den bättre. Prata med pappa, be honom läsa en saga för mig.', title_vi = 'Con nghe thấy tiếng bố? 🗣️', body_vi = 'Giọng nam trầm hơn nên con nghe rõ hơn. Mẹ nói với bố đi, để bố đọc truyện cho con nghe.', title_zh = '我听到爸爸的声音了吗？🗣️', body_zh = '男性的声音更低沉，我听得更清楚。和爸爸说说话，让他给我讲个故事吧。' WHERE id = '5b81d2cf-3568-4e53-b14d-b0aeaec2f43f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Eres mi escudo!', body_es = 'Mi sistema inmunitario se está formando y me pasas anticuerpos. Me proteges de las enfermedades, mamá. ❤️', title_fr = 'Vous êtes mon bouclier !', body_fr = 'Mon système immunitaire se forme, vos anticorps passent jusqu''à moi. Vous me protégez des maladies, Maman. ❤️', title_hi = 'आप मेरी ढाल हैं!', body_hi = 'मेरी इम्यून सिस्टम बन रही है, आपसे मुझे एंटीबॉडी मिल रही हैं। आप मुझे बीमारियों से बचा रही हैं, माँ। ❤️', title_id = 'Andalah perisaiku!', body_id = 'Sistem kekebalanku sedang terbentuk, antibodi mengalir dari Anda kepadaku. Anda melindungiku dari penyakit, Bunda. ❤️', title_ja = 'ママはわたしの盾だよ！', body_ja = '免疫の仕組みができてきて、ママから抗体が届いているの。病気から守ってくれてありがとう、ママ。❤️', title_ko = '엄마는 저의 방패예요!', body_ko = '제 면역 체계가 만들어지고 있고, 엄마에게서 항체가 전해져요. 엄마가 저를 병으로부터 지켜 주고 있어요. ❤️', title_nl = 'Jij bent mijn schild!', body_nl = 'Mijn afweersysteem wordt gevormd en ik krijg antistoffen van jou. Je beschermt me tegen ziektes, mama. ❤️', title_pl = 'Jesteś moją tarczą!', body_pl = 'Kształtuje się mój układ odpornościowy, przechodzą do mnie twoje przeciwciała. Chronisz mnie przed chorobami, Mamo. ❤️', title_pt = 'A Mamã é o meu escudo!', body_pt = 'O meu sistema imunitário está a formar-se e recebo os seus anticorpos. Está a proteger-me das doenças, Mamã. ❤️', title_sv = 'Du är min sköld!', body_sv = 'Mitt immunförsvar byggs upp och antikroppar går över från dig till mig. Du skyddar mig mot sjukdomar, mamma. ❤️', title_vi = 'Mẹ là tấm khiên của con!', body_vi = 'Hệ miễn dịch của con đang hình thành, kháng thể từ mẹ truyền sang con. Mẹ đang bảo vệ con khỏi bệnh tật đấy, mẹ ơi. ❤️', title_zh = '你是我的盾牌！', body_zh = '我的免疫系统正在形成，抗体从你身上传给我。妈妈，你在保护我不生病。❤️' WHERE id = 'cf9fd374-f357-4b58-bc32-9c2c7983b9f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te dan calambres? 🦶', body_es = '¿Se te encoge la pantorrilla por la noche? Te falta magnesio. Plátano, almendras o yogur... Tus músculos necesitan alivio.', title_fr = 'Des crampes ? 🦶', body_fr = 'Des crampes au mollet la nuit ? C''est un manque de magnésium. Banane, amandes ou yaourt... Vos muscles ont besoin de se détendre.', title_hi = 'ऐंठन हो रही है? 🦶', body_hi = 'रात में पिंडलियों में ऐंठन? मैग्नीशियम की कमी है। केला, बादाम या दही... मांसपेशियों को आराम चाहिए।', title_id = 'Kram? 🦶', body_id = 'Betis kram di malam hari? Anda kekurangan magnesium. Pisang, almon, atau yogurt... Otot butuh relaksasi.', title_ja = '足がつりますか？🦶', body_ja = '夜にふくらはぎがつる？マグネシウム不足かもしれません。バナナ、アーモンド、ヨーグルト...筋肉をいたわってあげましょう。', title_ko = '쥐가 나나요? 🦶', body_ko = '밤에 종아리에 쥐가 나나요? 마그네슘이 부족한 거예요. 바나나, 아몬드, 요거트... 근육에 휴식이 필요해요.', title_nl = 'Last van kramp? 🦶', body_nl = 'Kramp in je kuit ''s nachts? Je hebt te weinig magnesium. Banaan, amandelen of yoghurt... Je spieren hebben ontspanning nodig.', title_pl = 'Łapią cię skurcze? 🦶', body_pl = 'Nocą łapie cię skurcz łydki? Brakuje magnezu. Banan, migdały czy jogurt... Mięśnie potrzebują ulgi.', title_pt = 'Cãibras? 🦶', body_pt = 'Cãibras na barriga da perna à noite? Falta magnésio. Banana, amêndoas ou iogurte... Os músculos precisam de alívio.', title_sv = 'Får du kramp? 🦶', body_sv = 'Kramp i vaden på natten? Det saknas magnesium. Banan, mandlar eller yoghurt... Musklerna behöver avslappning.', title_vi = 'Bị chuột rút? 🦶', body_vi = 'Bắp chân bị chuột rút ban đêm? Có thể do thiếu magie. Chuối, hạnh nhân hoặc sữa chua... Cơ bắp cần được thư giãn.', title_zh = '抽筋了？🦶', body_zh = '夜里小腿抽筋？可能是缺镁。香蕉、杏仁或酸奶……肌肉需要放松一下。' WHERE id = '6631a482-e880-499b-a108-1eb7cfe533ac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡He abierto los ojos! 👀', body_es = 'Aunque está oscuro, ya puedo abrir los párpados. Parpadeo. ¡Queda poco para el día en que vea el mundo!', title_fr = 'J''ai ouvert les yeux ! 👀', body_fr = 'Même s''il fait noir, je peux déjà ouvrir mes paupières. Je cligne des cils. Bientôt, je verrai le monde !', title_hi = 'मैंने आँखें खोलीं! 👀', body_hi = 'अँधेरा है, फिर भी मैं अब पलकें खोल सकता हूँ। पलकें झपकाता हूँ। दुनिया देखने का दिन ज़्यादा दूर नहीं!', title_id = 'Aku membuka mata! 👀', body_id = 'Meski gelap, aku sudah bisa membuka kelopak mata. Aku mengedipkan bulu mataku. Tak lama lagi aku akan melihat dunia!', title_ja = '目を開けたよ！👀', body_ja = '真っ暗だけど、もうまぶたを開けられるの。まばたきもしているよ。世界を見る日まで、あと少し！', title_ko = '눈을 떴어요! 👀', body_ko = '깜깜하지만 이제 눈꺼풀을 뜰 수 있어요. 눈을 깜빡여요. 세상을 볼 날이 얼마 남지 않았어요!', title_nl = 'Mijn ogen zijn open! 👀', body_nl = 'Ook al is het donker, ik kan mijn oogleden al openen. Ik knipper met mijn wimpers. Het duurt niet lang meer voordat ik de wereld zie!', title_pl = 'Otwieram oczy! 👀', body_pl = 'Choć jest ciemno, już potrafię otwierać powieki. Mrugam rzęsami. Już niedługo zobaczę świat!', title_pt = 'Abri os olhos! 👀', body_pt = 'Apesar de estar escuro, já consigo abrir as pálpebras. Pestanejo. Falta pouco para o dia em que vou ver o mundo!', title_sv = 'Jag har öppnat ögonen! 👀', body_sv = 'Även om det är mörkt kan jag redan öppna ögonlocken. Jag blinkar med ögonfransarna. Snart är dagen här då jag får se världen!', title_vi = 'Con mở mắt rồi! 👀', body_vi = 'Dù trong này tối, con đã có thể mở mí mắt rồi. Con chớp hàng mi. Sắp đến ngày con được nhìn thấy thế giới rồi!', title_zh = '我睁开眼睛啦！👀', body_zh = '虽然这里很暗，我已经能睁开眼睑，还会眨眼睫毛。离我看见世界的那天不远啦！' WHERE id = '67d7589f-358a-44b0-9ee8-70aca8b6ffc6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Llega la luz, mamá! ☀️', body_es = '¡Parpadeo! Si el sol da en tu barriga, veo ese brillo. ¿De qué color es el mundo?', title_fr = 'La lumière arrive, Maman ! ☀️', body_fr = 'Je cligne des yeux ! Si le soleil tombe sur votre ventre, je vois cette lumière. De quelle couleur est le monde ?', title_hi = 'रोशनी आ रही है, माँ! ☀️', body_hi = 'मैं पलकें झपका रहा हूँ! अगर आपके पेट पर धूप पड़े, तो मुझे वह चमक दिखती है। दुनिया किस रंग की है?', title_id = 'Ada cahaya, Bunda! ☀️', body_id = 'Aku mengedipkan mata! Jika matahari menyinari perut Anda, aku melihat kilaunya. Dunia itu berwarna apa?', title_ja = '光が来たよ、ママ！☀️', body_ja = 'まばたきしてるよ！お腹に日が当たると、その明るさが見えるの。世界はどんな色をしているの？', title_ko = '빛이 들어와요, 엄마! ☀️', body_ko = '저 눈을 깜빡여요! 엄마 배에 햇빛이 비치면 그 밝은 빛이 보여요. 세상은 무슨 색일까요?', title_nl = 'Daar komt het licht, mama! ☀️', body_nl = 'Ik knipper met mijn ogen! Als de zon op je buik schijnt, zie ik die gloed. Welke kleur heeft de wereld?', title_pl = 'Nadchodzi światło, Mamo! ☀️', body_pl = 'Mrugam oczami! Gdy słońce pada na twój brzuch, widzę ten blask. Jakiego koloru jest świat?', title_pt = 'Vem aí a luz, Mamã! ☀️', body_pt = 'Estou a pestanejar! Se o sol bater na sua barriga, vejo aquele brilho. De que cor é o mundo?', title_sv = 'Ljuset kommer, mamma! ☀️', body_sv = 'Jag blinkar! Om solen lyser på din mage ser jag skenet. Vilken färg har världen?', title_vi = 'Ánh sáng đến rồi, mẹ ơi! ☀️', body_vi = 'Con đang chớp mắt! Nếu nắng chiếu vào bụng mẹ, con thấy được ánh sáng ấy. Thế giới có màu gì hả mẹ?', title_zh = '妈妈，光来啦！☀️', body_zh = '我在眨眼睛！如果阳光照在你肚子上，我能看到那份明亮。世界是什么颜色的呢？' WHERE id = '6a3d4aec-a08e-46ec-9845-95181acaa958' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Hora de la crema 🧴', body_es = 'Tu barriga crece rápido y la piel se estira. Para evitar el picor, aplica crema hidratante cada día.', title_fr = 'L''heure de la crème 🧴', body_fr = 'Votre ventre grossit vite et la peau s''étire. Pour éviter les démangeaisons, appliquez une crème hydratante chaque jour.', title_hi = 'क्रीम लगाने का समय 🧴', body_hi = 'आपका पेट तेज़ी से बढ़ रहा है, त्वचा खिंच रही है। खुजली से बचने के लिए रोज़ मॉइस्चराइज़र लगाइए।', title_id = 'Waktunya memakai krem 🧴', body_id = 'Perut Anda membesar dengan cepat dan kulit meregang. Untuk mencegah gatal, oleskan pelembap setiap hari.', title_ja = 'クリームを塗る時間 🧴', body_ja = 'お腹がどんどん大きくなり、皮膚が伸びています。かゆみを防ぐために、毎日保湿クリームを塗りましょう。', title_ko = '크림 바를 시간이에요 🧴', body_ko = '배가 빠르게 커지고 피부가 늘어나고 있어요. 가려움을 막으려면 매일 보습제를 발라 주세요.', title_nl = 'Tijd om in te smeren 🧴', body_nl = 'Je buik groeit snel en je huid rekt uit. Smeer elke dag een vochtinbrengende crème tegen de jeuk.', title_pl = 'Czas na krem 🧴', body_pl = 'Brzuch szybko rośnie, skóra się rozciąga. Aby zapobiec swędzeniu, codziennie nakładaj krem nawilżający.', title_pt = 'Hora do creme 🧴', body_pt = 'A barriga cresce depressa e a pele estica. Para prevenir a comichão, aplique hidratante todos os dias.', title_sv = 'Dags att smörja in sig 🧴', body_sv = 'Magen växer snabbt och huden sträcks. Smörj in med fuktkräm varje dag för att förebygga klåda.', title_vi = 'Đến giờ thoa kem rồi 🧴', body_vi = 'Bụng mẹ lớn nhanh, da bị căng ra. Để tránh ngứa, hãy thoa kem dưỡng ẩm mỗi ngày.', title_zh = '该涂霜啦 🧴', body_zh = '肚子长得很快，皮肤被撑开。为了防止发痒，每天涂保湿霜吧。' WHERE id = '79b3dcb1-a984-4729-ab92-c057730e6f8d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'La primera vacuna viene de ti 🛡️', body_es = 'Le pasas anticuerpos. Le protegerán durante los primeros meses después del parto.', title_fr = 'Le premier vaccin vient de vous 🛡️', body_fr = 'Vos anticorps passent jusqu''à lui. Ils le protégeront pendant ses premiers mois après la naissance.', title_hi = 'पहला टीका आपसे 🛡️', body_hi = 'आपसे उसे एंटीबॉडी मिल रही हैं। ये जन्म के बाद के पहले महीनों में उसकी रक्षा करेंगी।', title_id = 'Vaksin pertama dari Anda 🛡️', body_id = 'Antibodi mengalir dari Anda kepadanya. Ini akan melindunginya di bulan-bulan pertama setelah lahir.', title_ja = '最初の予防接種はママから 🛡️', body_ja = 'ママから赤ちゃんへ抗体が届いています。これが生まれてから最初の数か月、赤ちゃんを守ってくれます。', title_ko = '첫 백신은 엄마에게서 🛡️', body_ko = '엄마의 항체가 아기에게 전해지고 있어요. 이 항체가 태어난 후 첫 몇 달 동안 아기를 지켜 줄 거예요.', title_nl = 'De eerste bescherming komt van jou 🛡️', body_nl = 'Jouw antistoffen gaan over op je baby. Dat beschermt je baby in de eerste maanden na de geboorte.', title_pl = 'Pierwsza szczepionka od ciebie 🛡️', body_pl = 'Przechodzą do niego twoje przeciwciała. Będą je chronić w pierwszych miesiącach po porodzie.', title_pt = 'A primeira vacina vem da Mamã 🛡️', body_pt = 'Os seus anticorpos passam para o bebé. Vão protegê-lo nos primeiros meses depois do nascimento.', title_sv = 'Det första vaccinet kommer från dig 🛡️', body_sv = 'Antikroppar går över från dig till barnet. De skyddar barnet under de första månaderna efter födseln.', title_vi = 'Liều bảo vệ đầu tiên từ mẹ 🛡️', body_vi = 'Kháng thể từ mẹ truyền sang bé. Điều này sẽ bảo vệ bé trong những tháng đầu sau sinh.', title_zh = '第一份“疫苗”来自你 🛡️', body_zh = '抗体正从你身上传给宝宝。这会在出生后的头几个月保护宝宝。' WHERE id = '11db6f3d-a2eb-4392-b358-993a953c992e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Pepinillos en salmuera? ¡No! 🚫', body_es = 'Si se te hinchan los pies, reduce la sal al mínimo. Los encurtidos están ricos, pero causan edema. Pásate al agua con limón.', title_fr = 'Des cornichons ? Non ! 🚫', body_fr = 'Si vos pieds gonflent, réduisez le sel au minimum. Les pickles, c''est bon, mais ça favorise les œdèmes. Passez à l''eau citronnée.', title_hi = 'नमकीन अचार? नहीं! 🚫', body_hi = 'अगर पैर सूज रहे हैं, तो नमक कम से कम कीजिए। अचार स्वादिष्ट है, पर सूजन बढ़ाता है। नींबू पानी पीजिए।', title_id = 'Acar asin? Jangan! 🚫', body_id = 'Jika kaki bengkak, kurangi garam sebisa mungkin. Acar memang enak, tapi menyebabkan edema. Ganti dengan air lemon.', title_ja = 'ピクルス？今はダメ！🚫', body_ja = '足がむくむなら、塩分は最小限に。漬物はおいしいけれど、むくみの原因になります。レモン水に替えましょう。', title_ko = '짠 오이피클? 안 돼요! 🚫', body_ko = '발이 부으면 소금을 최소한으로 줄이세요. 피클은 맛있지만 부종을 만들어요. 레몬물로 바꿔 보세요.', title_nl = 'Zure augurk? Nee! 🚫', body_nl = 'Heb je dikke voeten? Beperk zout dan tot een minimum. Zuur is lekker, maar zorgt voor vocht vasthouden. Kies water met citroen.', title_pl = 'Kiszone ogórki? Nie! 🚫', body_pl = 'Jeśli puchną ci nogi, ogranicz sól do minimum. Kiszonki są smaczne, ale powodują obrzęki. Przejdź na wodę z cytryną.', title_pt = 'Pickles? Não! 🚫', body_pt = 'Se os pés incham, reduza o sal ao mínimo. Os pickles são saborosos, mas causam edema. Passe para água com limão.', title_sv = 'Saltgurka? Nej! 🚫', body_sv = 'Om fötterna svullnar, dra ner saltet till ett minimum. Inlagt är gott men ger svullnad. Byt till vatten med citron.', title_vi = 'Dưa muối? Không! 🚫', body_vi = 'Nếu chân bị phù, hãy giảm muối tối đa. Đồ muối chua thì ngon, nhưng gây phù. Chuyển sang nước chanh nhé.', title_zh = '咸黄瓜？不行！🚫', body_zh = '如果脚肿，就把盐降到最低。腌菜虽然好吃，但会引起水肿。换成柠檬水吧。' WHERE id = 'ecec560e-f533-42fa-b81c-743ce51e2fa4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'El mundo es muy ruidoso... 🔊', body_es = 'Mis oídos son tan sensibles que oigo hasta los pitidos de fuera. ¿Nos calmamos un poco? Ponme el sonido de lluvia de Ruido blanco y echemos una cabezadita juntos. 🌧️', title_fr = 'Le monde est si bruyant... 🔊', body_fr = 'Mes oreilles sont devenues si sensibles que j''entends même les klaxons dehors. On se calme un peu ? Mettez-moi le bruit de la pluie dans les Bruits blancs, et faisons une petite sieste ensemble. 🌧️', title_hi = 'दुनिया बहुत शोर वाली है... 🔊', body_hi = 'मेरे कान इतने संवेदनशील हो गए हैं कि बाहर की आवाज़ें भी सुनता हूँ। थोड़ा शांत हो जाएँ? व्हाइट नॉइज़ में बारिश की आवाज़ चलाइए, साथ में झपकी लें। 🌧️', title_id = 'Dunia ini sangat bising... 🔊', body_id = 'Telingaku sudah begitu peka sampai klakson di luar pun terdengar. Kita tenang sebentar? Putarkan suara hujan dari Suara Putih, ayo kita terlelap bersama. 🌧️', title_ja = '世界ってにぎやか... 🔊', body_ja = '耳がとても敏感になって、外の音まで聞こえるの。少し静かにしようか？「ホワイトノイズ」で雨の音をかけて、一緒にうとうとしよう。🌧️', title_ko = '세상은 너무 시끄러워요... 🔊', body_ko = '제 귀가 아주 예민해져서 바깥 경적 소리까지 들려요. 조금 차분해질까요? 백색소음에서 빗소리를 틀어 주세요, 함께 꾸벅꾸벅 졸아요. 🌧️', title_nl = 'De wereld is zo lawaaierig... 🔊', body_nl = 'Mijn oren zijn zo gevoelig geworden dat ik zelfs het getoeter buiten hoor. Zullen we wat tot rust komen? Zet het regengeluid in Witte ruis voor me aan, dan doezelen we samen weg. 🌧️', title_pl = 'Świat jest bardzo głośny... 🔊', body_pl = 'Moje uszy są tak wrażliwe, że słyszę nawet klaksony na zewnątrz. Wyciszymy się trochę? Włącz mi szum deszczu z sekcji Biały szum i zdrzemnijmy się razem. 🌧️', title_pt = 'O mundo é muito barulhento... 🔊', body_pt = 'Os meus ouvidos estão tão sensíveis que até ouço as buzinas lá fora. Acalmamos um pouco? Ponha-me o som da chuva no Ruído Branco e vamos dormitar juntos. 🌧️', title_sv = 'Världen är så högljudd... 🔊', body_sv = 'Mina öron har blivit så känsliga att jag till och med hör signalerna utanför. Ska vi lugna ner oss lite? Sätt på regnljudet i Vitt brus, så slumrar vi tillsammans. 🌧️', title_vi = 'Thế giới ồn ào quá... 🔊', body_vi = 'Tai con nhạy đến mức nghe được cả tiếng còi bên ngoài. Mình yên tĩnh một chút nhé? Mẹ mở tiếng mưa trong Tiếng ồn trắng đi, mình cùng chợp mắt. 🌧️', title_zh = '世界好吵啊……🔊', body_zh = '我的耳朵变得特别灵敏，连外面的喇叭声都听得到。我们安静一会儿好吗？在白噪音里给我放雨声，我们一起打个盹。🌧️' WHERE id = 'eb78f9b1-0793-4172-8289-9ad69826fa75' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Bienvenido, 3.er trimestre! 🏁', body_es = '¡Ha empezado la última etapa! Ahora tu cuerpo pesará más, pero ya se ve la meta. ¡Paciencia, mamá!', title_fr = 'Bienvenue, 3e trimestre ! 🏁', body_fr = 'La dernière étape a commencé ! Votre corps va s''alourdir, mais la ligne d''arrivée est en vue. Patience, Maman !', title_hi = 'स्वागत है, तीसरी तिमाही! 🏁', body_hi = 'आखिरी दौर शुरू! अब आपका शरीर और भारी होगा, पर फ़िनिश लाइन दिख रही है। धैर्य रखिए, माँ!', title_id = 'Selamat datang, Trimester ke-3! 🏁', body_id = 'Tahap terakhir dimulai! Tubuh Anda akan terasa lebih berat, tapi garis finis sudah terlihat. Bersabarlah, Bunda!', title_ja = 'ようこそ、妊娠後期！🏁', body_ja = '最後のステージが始まりました！これから体は重くなりますが、ゴールはもう見えています。がんばって、ママ！', title_ko = '어서 와요, 임신 3기! 🏁', body_ko = '마지막 단계가 시작됐어요! 이제 몸은 더 무거워지겠지만 결승선이 보여요. 조금만 더 힘내요, 엄마!', title_nl = 'Welkom, 3e trimester! 🏁', body_nl = 'De laatste fase is begonnen! Je lichaam wordt nu zwaarder, maar de finish is in zicht. Hou vol, mama!', title_pl = 'Witaj, 3. trymestrze! 🏁', body_pl = 'Zaczął się ostatni etap! Twoje ciało będzie teraz cięższe, ale meta jest już w zasięgu wzroku. Bądź cierpliwa, Mamo!', title_pt = 'Bem-vindo, 3.º trimestre! 🏁', body_pt = 'A fase final começou! O corpo vai ficar mais pesado, mas a meta já está à vista. Tenha paciência, Mamã!', title_sv = 'Välkommen, tredje trimestern! 🏁', body_sv = 'Slutfasen har börjat! Nu blir kroppen tyngre, men mållinjen syns. Ha tålamod, mamma!', title_vi = 'Chào mừng Tam cá nguyệt thứ 3! 🏁', body_vi = 'Giai đoạn cuối đã bắt đầu! Giờ cơ thể mẹ sẽ nặng nề hơn, nhưng vạch đích đã ở trước mắt. Kiên nhẫn nhé, mẹ ơi!', title_zh = '欢迎来到孕晚期！🏁', body_zh = '最后阶段开始了！身体会越来越沉，但终点线已经在眼前。妈妈，要有耐心！' WHERE id = '2a7b5422-c620-43f8-9faf-09db6234cc0f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Uy! ¿Qué ha sido ese ruido? 😳', body_es = 'Me he sobresaltado con el portazo. Oigo muy bien, mamá. Pon música tranquila y descansemos juntos.', title_fr = 'Oh ! C''était quoi ce bruit ? 😳', body_fr = 'J''ai sursauté quand la porte a claqué. J''entends très bien, Maman. Mettez une musique douce, reposons-nous ensemble.', title_hi = 'अरे! वह आवाज़ क्या थी? 😳', body_hi = 'दरवाज़ा ज़ोर से बंद हुआ तो मैं चौंक गया। मेरी सुनने की शक्ति बहुत अच्छी है, माँ। हल्का संगीत लगाइए, साथ में आराम करें।', title_id = 'Ups! Suara apa itu? 😳', body_id = 'Aku kaget saat pintu dibanting. Pendengaranku sangat baik, Bunda. Putar musik yang tenang, kita bersantai bersama.', title_ja = 'わっ！今の音はなに？😳', body_ja = 'ドアがバタンと閉まって、びっくりしちゃった。耳がとてもいいの、ママ。静かな音楽をかけて、一緒に休もう。', title_ko = '깜짝! 그게 무슨 소리였어요? 😳', body_ko = '문이 쾅 닫혀서 깜짝 놀랐어요. 제 청력은 아주 좋아요, 엄마. 잔잔한 음악을 틀고 같이 쉬어요.', title_nl = 'Oei! Wat was dat voor geluid? 😳', body_nl = 'Ik schrok toen de deur dichtsloeg. Mijn gehoor is heel goed, mama. Zet rustige muziek op, dan ontspannen we samen.', title_pl = 'Hop! Co to był za dźwięk? 😳', body_pl = 'Wzdrygam się, gdy trzaskają drzwi. Mam bardzo dobry słuch, Mamo. Włącz spokojną muzykę, odpocznijmy razem.', title_pt = 'Ups! Que som foi aquele? 😳', body_pt = 'Assustei-me quando a porta bateu. Ouço muito bem, Mamã. Ponha música calma e vamos descansar juntos.', title_sv = 'Hoppsan! Vad var det för ljud? 😳', body_sv = 'Jag hoppade till när dörren smällde igen. Jag hör väldigt bra, mamma. Sätt på lugn musik, så vilar vi tillsammans.', title_vi = 'Ối! Tiếng gì vậy? 😳', body_vi = 'Con giật mình khi cửa đóng sầm. Tai con thính lắm, mẹ ạ. Mẹ mở nhạc nhẹ đi, mình cùng nghỉ ngơi.', title_zh = '哎呀！那是什么声音？😳', body_zh = '门砰的一声把我吓了一跳。妈妈，我的听力很好。放点轻柔的音乐，我们一起休息吧。' WHERE id = '153927df-2197-4033-aa1c-31dfbfdf9083' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Se me ha destapado la nariz! 👃', body_es = 'Mis fosas nasales estaban tapadas y ahora se han abierto. Estoy practicando para respirar.', title_fr = 'Mon nez s''est débouché ! 👃', body_fr = 'Mes narines étaient bouchées, maintenant elles sont ouvertes. Je m''entraîne à respirer.', title_hi = 'मेरी नाक खुल गई! 👃', body_hi = 'मेरे नथुने बंद थे, अब खुल गए। मैं साँस लेने का अभ्यास कर रहा हूँ।', title_id = 'Hidungku sudah terbuka! 👃', body_id = 'Lubang hidungku tadinya tersumbat, sekarang sudah terbuka. Aku berlatih bernapas.', title_ja = '鼻が通ったよ！👃', body_ja = '鼻の穴がふさがっていたけど、今は開いたの。呼吸の練習をしているよ。', title_ko = '제 코가 뚫렸어요! 👃', body_ko = '콧구멍이 막혀 있었는데 이제 열렸어요. 숨 쉬는 연습을 하고 있어요.', title_nl = 'Mijn neus is open! 👃', body_nl = 'Mijn neusgaatjes zaten dicht, nu zijn ze open. Ik oefen met ademhalen.', title_pl = 'Mój nosek się odetkał! 👃', body_pl = 'Moje dziurki w nosie były zatkane, a teraz się otworzyły. Ćwiczę oddychanie.', title_pt = 'O meu nariz desentupiu! 👃', body_pt = 'As minhas narinas estavam tapadas, agora abriram. Estou a treinar para respirar.', title_sv = 'Min näsa har öppnats! 👃', body_sv = 'Mina näsborrar var tilltäppta, nu har de öppnats. Jag tränar på att andas.', title_vi = 'Mũi con thông rồi! 👃', body_vi = 'Lỗ mũi con trước bị bít, giờ đã thông. Con đang tập thở đây.', title_zh = '我的鼻子通啦！👃', body_zh = '我的鼻孔原来是堵着的，现在通了。我在练习呼吸。' WHERE id = '4de979ce-b173-440f-bc60-e4d333797f19' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿La digestión va lenta? 🐌', body_es = 'La progesterona ralentiza el intestino. Los orejones, las ciruelas y el pan con salvado pueden ser tu salvación.', title_fr = 'Digestion paresseuse ? 🐌', body_fr = 'La progestérone ralentit les intestins. Les abricots secs, les pruneaux et le pain au son peuvent vous sauver.', title_hi = 'पाचन सुस्त हो गया? 🐌', body_hi = 'प्रोजेस्टेरोन आँतों को धीमा कर देता है। सूखी खुबानी, आलूबुखारा और चोकर वाली रोटी आपकी मदद कर सकती हैं।', title_id = 'Pencernaan jadi malas? 🐌', body_id = 'Progesteron memperlambat kerja usus. Aprikot kering, prune, dan roti gandum bisa menjadi penyelamat Anda.', title_ja = '消化がのんびりしている？🐌', body_ja = 'プロゲステロンは腸の動きをゆっくりにします。干しあんず、プルーン、全粒粉パンが救世主になってくれるかも。', title_ko = '소화가 느려졌나요? 🐌', body_ko = '프로게스테론이 장의 움직임을 느리게 해요. 말린 살구, 자두, 통밀빵이 구세주가 될 수 있어요.', title_nl = 'Luie spijsvertering? 🐌', body_nl = 'Progesteron vertraagt je darmen. Gedroogde abrikozen, pruimen en volkorenbrood kunnen je redding zijn.', title_pl = 'Trawienie zwolniło? 🐌', body_pl = 'Progesteron spowalnia jelita. Suszone morele, śliwki i chleb z otrębami mogą cię uratować.', title_pt = 'A digestão ficou preguiçosa? 🐌', body_pt = 'A progesterona torna o intestino mais lento. Alperces secos, ameixas e pão integral podem ser a sua salvação.', title_sv = 'Har matsmältningen blivit lat? 🐌', body_sv = 'Progesteron gör tarmarna långsammare. Torkade aprikoser, plommon och fullkornsbröd kan bli din räddning.', title_vi = 'Tiêu hóa lười biếng? 🐌', body_vi = 'Progesterone làm ruột chậm lại. Mơ khô, mận và bánh mì cám có thể là cứu tinh của mẹ.', title_zh = '消化变慢了？🐌', body_zh = '孕酮会让肠道变慢。杏干、西梅和麸皮面包可能会是你的救星。' WHERE id = '2efc37a3-7408-4f42-8512-00545c8b1565' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Construye un castillo de cojines! 🏰', body_es = '¿No duermes cómoda? Pon una almohada entre las piernas y bajo la barriga. ¡El apoyo es clave!', title_fr = 'Construisez un château de coussins ! 🏰', body_fr = 'Vous n''arrivez pas à dormir confortablement ? Placez un coussin entre vos jambes et sous votre ventre. Le soutien, c''est essentiel !', title_hi = 'तकियों का किला बनाइए! 🏰', body_hi = 'आराम से सो नहीं पा रहीं? पैरों के बीच और पेट के नीचे तकिया रखिए। सहारा ज़रूरी है!', title_id = 'Bangun benteng bantal! 🏰', body_id = 'Sulit tidur nyenyak? Letakkan bantal di antara kaki dan di bawah perut. Topangan itu penting!', title_ja = 'クッションのお城をつくろう！🏰', body_ja = 'うまく眠れませんか？脚の間とお腹の下にクッションを置いてみて。支えが大切です！', title_ko = '베개 성을 쌓아요! 🏰', body_ko = '편하게 잠들기 어려운가요? 다리 사이와 배 아래에 베개를 놓아 보세요. 받쳐 주는 게 중요해요!', title_nl = 'Bouw een kussenfort! 🏰', body_nl = 'Lig je niet lekker? Leg een kussen tussen je benen en onder je buik. Steun is essentieel!', title_pl = 'Zbuduj zamek z poduszek! 🏰', body_pl = 'Nie możesz wygodnie spać? Włóż poduszkę między nogi i pod brzuch. Podparcie to podstawa!', title_pt = 'Construa um castelo de almofadas! 🏰', body_pt = 'Não consegue dormir confortável? Ponha uma almofada entre as pernas e outra debaixo da barriga. O apoio é essencial!', title_sv = 'Bygg ett kuddslott! 🏰', body_sv = 'Svårt att sova bekvämt? Lägg en kudde mellan benen och under magen. Stöd är A och O!', title_vi = 'Xây lâu đài gối nào! 🏰', body_vi = 'Không ngủ thoải mái được? Kê gối giữa hai chân và dưới bụng. Có điểm tựa là điều cần thiết!', title_zh = '搭个枕头城堡！🏰', body_zh = '睡不舒服？在两腿之间和肚子下面垫个枕头。支撑很重要！' WHERE id = '32fe315d-64ad-42bb-8357-047270382c70' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Soy un maestro del yoga! 🦶', body_es = 'No te lo vas a creer, ¡pero puedo agarrarme el dedo del pie y metérmelo en la boca! Soy muy flexible. ¿Y a ti te cuesta agacharte?', title_fr = 'Je suis un maître du yoga ! 🦶', body_fr = 'Vous n''allez pas me croire, mais je peux attraper mon orteil et le mettre dans ma bouche ! Je suis très souple. Et vous, vous avez du mal à vous pencher ?', title_hi = 'मैं योग मास्टर हूँ! 🦶', body_hi = 'यकीन नहीं होगा, पर मैं अपने पैर का अँगूठा पकड़कर मुँह में डाल सकता हूँ! मैं बहुत लचीला हूँ। और आपको झुकने में दिक्कत होती है?', title_id = 'Aku ahli yoga! 🦶', body_id = 'Anda tidak akan percaya, tapi aku bisa memegang jari kakiku dan memasukkannya ke mulut! Aku sangat lentur. Sedangkan Anda, sulit membungkuk?', title_ja = 'ヨガの達人だよ！🦶', body_ja = '信じられないかもしれないけど、足の指をつかんで口に入れられるの！とってもやわらかいんだよ。ママはかがむのが大変になってきた？', title_ko = '저는 요가 달인이에요! 🦶', body_ko = '믿기 어렵겠지만 저는 발가락을 잡아서 입에 넣을 수 있어요! 아주 유연하거든요. 엄마는 허리 숙이기 힘드시죠?', title_nl = 'Ik ben een yogameester! 🦶', body_nl = 'Je gelooft het niet, maar ik kan mijn teen pakken en in mijn mond stoppen! Ik ben heel lenig. En jij, heb je moeite met bukken?', title_pl = 'Joga to moja specjalność! 🦶', body_pl = 'Nie uwierzysz, ale potrafię złapać palec u stopy i włożyć go do buzi! Jestem bardzo giętkie. A tobie trudno się schylać?', title_pt = 'Sou um mestre de ioga! 🦶', body_pt = 'Não vai acreditar, mas consigo agarrar o dedo do pé e pô-lo na boca! Sou muito flexível. E a Mamã, custa-lhe dobrar-se?', title_sv = 'Jag är en yogamästare! 🦶', body_sv = 'Du kommer inte att tro det, men jag kan ta tag i min tå och stoppa den i munnen! Jag är väldigt smidig. Och du, har du svårt att böja dig?', title_vi = 'Con là bậc thầy yoga! 🦶', body_vi = 'Mẹ không tin đâu, nhưng con có thể nắm ngón chân cho vào miệng! Con dẻo lắm. Còn mẹ thì khó cúi người lắm phải không?', title_zh = '我是瑜伽大师！🦶', body_zh = '你可能不信，我能抓住脚趾放进嘴里！我超级柔软。你弯腰是不是越来越难了？' WHERE id = '99d63bff-e50d-4a8d-89f1-525eee8af207' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡He abierto los ojos! 👀', body_es = 'Mamá, no te lo vas a creer, pero he levantado las pestañas. Aunque esté oscuro, mi mirada ya se está formando. ¡Queda poco para verte!', title_fr = 'J''ai ouvert les yeux ! 👀', body_fr = 'Maman, vous n''allez pas me croire, mais j''ai levé mes cils. Même s''il fait noir, mon regard se forme déjà. Bientôt, je vous verrai !', title_hi = 'मैंने आँखें खोलीं! 👀', body_hi = 'माँ, यकीन नहीं होगा, पर मैंने पलकें उठाईं। अँधेरा है, फिर भी मेरी नज़र बन रही है। आपको देखने में ज़्यादा देर नहीं!', title_id = 'Aku membuka mata! 👀', body_id = 'Bunda, Anda tidak akan percaya, tapi aku sudah mengangkat bulu mataku. Meski gelap, penglihatanku mulai terbentuk. Tak lama lagi aku bisa melihat Anda!', title_ja = '目を開けたよ！👀', body_ja = 'ママ、信じられないかもしれないけど、まつげを持ち上げたよ。暗いけど、もう目で見る力が育っているの。ママに会えるまであと少し！', title_ko = '눈을 떴어요! 👀', body_ko = '엄마, 믿기 어렵겠지만 저 눈꺼풀을 들어 올렸어요. 깜깜해도 벌써 시선이 생기고 있어요. 엄마를 볼 날이 얼마 남지 않았어요!', title_nl = 'Mijn ogen zijn open! 👀', body_nl = 'Mama, je gelooft het niet, maar ik heb mijn oogleden opgetild. Ook al is het donker, mijn blik ontwikkelt zich al. Het duurt niet lang meer voordat ik je zie!', title_pl = 'Otwieram oczy! 👀', body_pl = 'Mamo, nie uwierzysz, ale unoszę już powieki. Choć jest ciemno, mój wzrok już się kształtuje. Niedługo cię zobaczę!', title_pt = 'Abri os olhos! 👀', body_pt = 'Mamã, não vai acreditar, mas levantei as pestanas. Apesar de estar escuro, o meu olhar já se está a formar. Falta pouco para a ver!', title_sv = 'Jag har öppnat ögonen! 👀', body_sv = 'Mamma, du kommer inte att tro det, men jag har lyft på ögonfransarna. Även om det är mörkt börjar min blick ta form. Snart får jag se dig!', title_vi = 'Con mở mắt rồi! 👀', body_vi = 'Mẹ ơi, mẹ không tin đâu, con đã nhấc được hàng mi lên. Dù trong này tối, ánh nhìn của con đang hình thành. Sắp được nhìn thấy mẹ rồi!', title_zh = '我睁开眼睛啦！👀', body_zh = '妈妈，你可能不信，我抬起了睫毛。虽然很暗，我的目光已经在形成。很快就能见到你了！' WHERE id = '9c19e501-078c-4145-9bf4-28096c2e69da' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Tu estómago es un incendio? 🔥', body_es = 'El útero empuja el estómago hacia arriba. Beber leche o comer un puñado de almendras crudas puede apagar el ardor.', title_fr = 'Votre estomac est en feu ? 🔥', body_fr = 'L''utérus pousse l''estomac vers le haut. Boire du lait ou manger une poignée d''amandes crues peut éteindre le feu.', title_hi = 'पेट में आग लगी है? 🔥', body_hi = 'गर्भाशय पेट को ऊपर की ओर दबा रहा है। दूध पीना या मुट्ठी भर कच्चे बादाम खाना जलन शांत कर सकता है।', title_id = 'Lambung terasa terbakar? 🔥', body_id = 'Rahim menekan lambung ke atas. Minum susu atau makan segenggam almon mentah bisa meredakan rasa panasnya.', title_ja = '胃が燃えているみたい？🔥', body_ja = '子宮が胃を押し上げています。牛乳を飲んだり、生のアーモンドをひとつかみ食べたりすると、胸やけがおさまることがあります。', title_ko = '속이 불타는 것 같나요? 🔥', body_ko = '자궁이 위를 위로 밀어 올리고 있어요. 우유 한 잔이나 생아몬드 한 줌이 속쓰림을 달래 줄 수 있어요.', title_nl = 'Staat je maag in brand? 🔥', body_nl = 'Je baarmoeder duwt je maag omhoog. Een glas melk of een handje rauwe amandelen kan het branden blussen.', title_pl = 'Żołądek płonie? 🔥', body_pl = 'Macica wypycha żołądek w górę. Szklanka mleka lub garść surowych migdałów mogą ugasić pieczenie.', title_pt = 'O estômago está a arder? 🔥', body_pt = 'O útero empurra o estômago para cima. Beber leite ou comer uma mão-cheia de amêndoas cruas pode apagar o ardor.', title_sv = 'Brinner det i magen? 🔥', body_sv = 'Livmodern trycker upp magsäcken. Ett glas mjölk eller en näve råa mandlar kan släcka branden.', title_vi = 'Dạ dày như bốc lửa? 🔥', body_vi = 'Tử cung đẩy dạ dày lên trên. Uống sữa hoặc ăn một nắm hạnh nhân sống có thể dập tắt cơn nóng rát.', title_zh = '胃里像着了火？🔥', body_zh = '子宫把胃往上顶。喝点牛奶或吃一把生杏仁，可能会帮你“灭火”。' WHERE id = 'c1685f6c-ebb8-432c-88df-49144f8b19c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Preparamos el nido? 🐣', body_es = 'Mi cuna, mi ropita... ¡Preparad la lista con papá en Compras compartidas! 📝', title_fr = 'On prépare le nid ? 🐣', body_fr = 'Mon lit, mes petits vêtements... Préparez la liste avec Papa dans les Courses partagées ! 📝', title_hi = 'घोंसला बना रहे हैं? 🐣', body_hi = 'मेरा पालना, मेरे छोटे कपड़े... पापा के साथ मिलकर साझा शॉपिंग में लिस्ट तैयार कीजिए! 📝', title_id = 'Kita membangun sarang? 🐣', body_id = 'Tempat tidurku, baju-baju mungilku... Siapkan daftarnya bersama Ayah di Belanja Bersama! 📝', title_ja = '巣づくり中？🐣', body_ja = 'わたしのベビーベッド、小さなお洋服...パパと一緒に「共有ショッピング」でリストをつくってね！📝', title_ko = '둥지를 만들어 볼까요? 🐣', body_ko = '제 아기 침대, 작은 옷들... 공동 쇼핑에서 아빠와 함께 목록을 준비해 보세요! 📝', title_nl = 'Zijn we aan het nestelen? 🐣', body_nl = 'Mijn bedje, mijn kleine kleertjes... Maak de lijst samen met papa in Gedeelde boodschappen! 📝', title_pl = 'Wijemy gniazdko? 🐣', body_pl = 'Moje łóżeczko, malutkie ubranka... Przygotujcie listę razem z tatą we Wspólnych zakupach! 📝', title_pt = 'Estamos a preparar o ninho? 🐣', body_pt = 'O meu berço, as minhas roupinhas... Preparem a lista com o pai nas Compras Partilhadas! 📝', title_sv = 'Bygger vi bo? 🐣', body_sv = 'Min säng, mina små kläder... Gör listan tillsammans med pappa i Gemensam shopping! 📝', title_vi = 'Mình đang làm tổ à? 🐣', body_vi = 'Giường của con, quần áo bé xíu của con... Hãy cùng bố chuẩn bị danh sách trong Mua sắm chung nhé! 📝', title_zh = '在筑巢吗？🐣', body_zh = '我的小床、我的小衣服……和爸爸一起在共享购物里列好清单吧！📝' WHERE id = '0a1c9fc7-d6fb-46ee-b640-782093d821ef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Tu grupo sanguíneo es negativo? 🩸', body_es = 'Es una semana clave para las mamás con Rh negativo. Puede que necesites una inyección de inmunoglobulina. ¡Habla con tu médico!', title_fr = 'Votre groupe sanguin est négatif ? 🩸', body_fr = 'C''est une semaine importante pour les mamans de rhésus négatif. Une injection d''immunoglobulines peut être nécessaire. Parlez-en à votre médecin !', title_hi = 'आपका ब्लड ग्रुप नेगेटिव है? 🩸', body_hi = 'Rh नेगेटिव माँओं के लिए यह अहम हफ़्ता है। इम्युनोग्लोबुलिन इंजेक्शन की ज़रूरत हो सकती है। अपने डॉक्टर से बात कीजिए!', title_id = 'Rhesus darah Anda negatif? 🩸', body_id = 'Ini minggu yang penting bagi ibu dengan rhesus negatif. Suntikan imunoglobulin mungkin diperlukan. Bicarakan dengan dokter Anda!', title_ja = '血液型がRhマイナスですか？🩸', body_ja = 'Rhマイナスのママにとって大切な週です。免疫グロブリンの注射が必要になることがあります。お医者さんと相談しましょう！', title_ko = '혈액형이 Rh 음성인가요? 🩸', body_ko = 'Rh 음성 엄마에게 중요한 주예요. 면역글로불린 주사가 필요할 수 있어요. 담당 의사와 상의하세요!', title_nl = 'Is je bloedgroep resusnegatief? 🩸', body_nl = 'Voor resusnegatieve moeders is dit een belangrijke week. Een injectie met immunoglobuline kan nodig zijn. Praat met je arts!', title_pl = 'Masz ujemną grupę krwi? 🩸', body_pl = 'To ważny tydzień dla mam z ujemnym czynnikiem Rh. Może być potrzebny zastrzyk immunoglobuliny. Porozmawiaj z lekarzem!', title_pt = 'O seu grupo sanguíneo é negativo? 🩸', body_pt = 'Esta é uma semana crítica para as mães Rh negativo. Pode ser necessária uma injeção de imunoglobulina. Fale com o seu médico!', title_sv = 'Är din blodgrupp Rh-negativ? 🩸', body_sv = 'En kritisk vecka för Rh-negativa mammor. En spruta med immunglobulin kan behövas. Prata med din läkare!', title_vi = 'Nhóm máu của mẹ là Rh âm? 🩸', body_vi = 'Đây là tuần quan trọng với các mẹ có Rh âm. Có thể cần tiêm immunoglobulin. Hãy trao đổi với bác sĩ!', title_zh = '你是Rh阴性血吗？🩸', body_zh = '对Rh阴性的妈妈来说，这是关键的一周。可能需要注射免疫球蛋白。和医生谈谈吧！' WHERE id = 'f8beb64f-d6c0-4f9c-a2ac-a26ff5b8a6ea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Sus pestañas han crecido! 👁️', body_es = 'Abre y cierra los ojos. Distingue la luz de la oscuridad. Si iluminas tu barriga con una linterna, girará la cara. ¿Quieres probar?', title_fr = 'Ses cils ont poussé ! 👁️', body_fr = 'Il ouvre et ferme les yeux. Il distingue la lumière de l''obscurité. Si vous éclairez votre ventre avec une lampe, il tournera le visage. Vous voulez essayer ?', title_hi = 'पलकें लंबी हो गईं! 👁️', body_hi = 'वह आँखें खोलता-बंद करता है। रोशनी और अँधेरे में फ़र्क करता है। पेट पर टॉर्च डालेंगी, तो चेहरा घुमा लेगा। आज़माना चाहेंगी?', title_id = 'Bulu matanya memanjang! 👁️', body_id = 'Ia membuka dan menutup mata. Ia membedakan terang dan gelap. Jika Anda menyorotkan senter ke perut, ia akan memalingkan wajah. Ingin mencoba?', title_ja = 'まつげが伸びてきた！👁️', body_ja = '目を開けたり閉じたりして、明るさと暗さを見分けています。お腹にライトを当てると、顔をそむけるかも。試してみますか？', title_ko = '속눈썹이 길어졌어요! 👁️', body_ko = '아기가 눈을 떴다 감았다 해요. 빛과 어둠을 구별해요. 배에 손전등을 비추면 얼굴을 돌릴 거예요. 해 볼래요?', title_nl = 'De wimpers zijn langer geworden! 👁️', body_nl = 'Je baby doet de ogen open en dicht en onderscheidt licht en donker. Schijn je met een zaklamp op je buik, dan draait het zijn gezichtje weg. Zin om het te proberen?', title_pl = 'Rzęsy urosły! 👁️', body_pl = 'Otwiera i zamyka oczy. Odróżnia światło od ciemności. Jeśli poświecisz latarką na brzuch, odwróci buzię. Chcesz spróbować?', title_pt = 'As pestanas cresceram! 👁️', body_pt = 'O bebé abre e fecha os olhos. Distingue a luz da escuridão. Se apontar uma lanterna à barriga, vai virar o rosto. Quer experimentar?', title_sv = 'Ögonfransarna har blivit längre! 👁️', body_sv = 'Barnet öppnar och sluter ögonen. Det skiljer på ljus och mörker. Om du lyser med en ficklampa på magen vänder det bort ansiktet. Vill du prova?', title_vi = 'Hàng mi đã dài ra! 👁️', body_vi = 'Bé mở mắt rồi nhắm mắt. Bé phân biệt được sáng và tối. Nếu mẹ chiếu đèn pin vào bụng, bé sẽ quay mặt đi. Mẹ muốn thử không?', title_zh = '睫毛变长啦！👁️', body_zh = '宝宝会睁眼闭眼了，还能分辨光亮和黑暗。如果用手电筒照肚子，宝宝会把脸转开。想试试吗？' WHERE id = '6e18672f-c08d-4df7-a33d-ffe41885dcb7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Pescado, pescado, pescado! 🐟', body_es = 'Es cuando mi cerebro se desarrolla más rápido. Necesito omega-3. ¿Comes pescado 2 veces por semana?', title_fr = 'Du poisson, du poisson, du poisson ! 🐟', body_fr = 'C''est la période où mon cerveau se développe le plus vite. J''ai besoin d''oméga-3. Vous mangez du poisson 2 fois par semaine ?', title_hi = 'मछली, मछली, मछली! 🐟', body_hi = 'यह मेरे दिमाग के सबसे तेज़ विकास का समय है। मुझे ओमेगा-3 चाहिए। क्या आप हफ़्ते में 2 बार मछली खाती हैं?', title_id = 'Ikan, ikan, ikan! 🐟', body_id = 'Inilah masa otakku berkembang paling cepat. Aku butuh Omega-3. Apakah Anda makan ikan 2 kali seminggu?', title_ja = 'お魚、お魚、お魚！🐟', body_ja = '今は脳がいちばん速く発達する時期なの。オメガ3が必要だよ。週に2回、お魚を食べてる？', title_ko = '생선, 생선, 생선! 🐟', body_ko = '제 뇌가 가장 빠르게 자라는 시기예요. 오메가-3가 필요해요. 일주일에 2번 생선 드시고 있어요?', title_nl = 'Vis, vis, vis! 🐟', body_nl = 'Mijn hersenen ontwikkelen zich nu het snelst. Ik heb omega-3 nodig. Eet je 2 keer per week vis?', title_pl = 'Ryba, ryba, ryba! 🐟', body_pl = 'Teraz mój mózg rozwija się najszybciej. Potrzebuję omega-3. Jesz rybę 2 razy w tygodniu?', title_pt = 'Peixe, peixe, peixe! 🐟', body_pt = 'É a fase em que o meu cérebro se desenvolve mais depressa. Preciso de ómega-3. Come peixe 2 vezes por semana?', title_sv = 'Fisk, fisk, fisk! 🐟', body_sv = 'Det här är tiden då min hjärna utvecklas snabbast. Jag behöver omega-3. Äter du fisk 2 gånger i veckan?', title_vi = 'Cá, cá và cá! 🐟', body_vi = 'Đây là lúc não con phát triển nhanh nhất. Con cần Omega-3. Mẹ có ăn cá 2 lần mỗi tuần không?', title_zh = '鱼，鱼，还是鱼！🐟', body_zh = '现在是我大脑发育最快的时候。我需要Omega-3。你每周吃两次鱼吗？' WHERE id = '382ecc0d-761f-4375-83d6-da7672e029c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Estoy aquí, mamá! 👋', body_es = 'A veces me calmo y a veces bailo. ¿Cuentas mis patadas? Todo va bien, solo que tengo menos espacio.', title_fr = 'Je suis là, Maman ! 👋', body_fr = 'Parfois je suis calme, parfois je danse. Vous comptez mes coups de pied ? Tout va bien, je manque juste de place.', title_hi = 'मैं यहाँ हूँ, माँ! 👋', body_hi = 'कभी मैं शांत रहता हूँ, कभी डांस करता हूँ। मेरी किक गिनती हैं? सब ठीक है, बस मेरी जगह कम हो रही है।', title_id = 'Aku di sini, Bunda! 👋', body_id = 'Kadang aku tenang, kadang aku menari. Anda menghitung tendanganku? Semuanya baik-baik saja, hanya ruanganku makin sempit.', title_ja = 'ここにいるよ、ママ！👋', body_ja = '静かなときもあれば、踊っているときもあるよ。キックを数えてる？大丈夫、ただお部屋が狭くなってきただけだよ。', title_ko = '저 여기 있어요, 엄마! 👋', body_ko = '가끔은 조용하고, 가끔은 춤을 춰요. 제 발차기를 세고 있나요? 다 괜찮아요, 그냥 공간이 좁아지고 있을 뿐이에요.', title_nl = 'Ik ben hier, mama! 👋', body_nl = 'Soms ben ik rustig, soms dans ik. Tel je mijn trappen? Alles is in orde, ik krijg alleen minder ruimte.', title_pl = 'Jestem tu, Mamo! 👋', body_pl = 'Czasem się uspokajam, a czasem tańczę. Liczysz moje kopnięcia? Wszystko w porządku, po prostu robi mi się ciasno.', title_pt = 'Estou aqui, Mamã! 👋', body_pt = 'Às vezes fico calmo, outras vezes danço. Está a contar os meus pontapés? Está tudo bem, só o meu espaço está a ficar apertado.', title_sv = 'Jag är här, mamma! 👋', body_sv = 'Ibland är jag lugn, ibland dansar jag. Räknar du mina sparkar? Allt är som det ska, det börjar bara bli trångt här.', title_vi = 'Con ở đây, mẹ ơi! 👋', body_vi = 'Lúc thì con yên lặng, lúc thì con nhảy múa. Mẹ có đếm cú đạp của con không? Mọi thứ đều ổn, chỉ là chỗ của con chật dần.', title_zh = '妈妈，我在这儿！👋', body_zh = '我有时安静，有时跳舞。你在数我的胎动吗？一切都好，只是我的空间越来越小了。' WHERE id = '6c259c3a-0864-4b21-9205-87b10a98dab6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Tienes venitas en las piernas? 🕸️', body_es = 'Pueden aparecer varices. No estés de pie mucho tiempo. Por la tarde, túmbate con las piernas apoyadas en la pared.', title_fr = 'Des petites veines sur les jambes ? 🕸️', body_fr = 'Des varices peuvent apparaître. Évitez de rester debout longtemps. Le soir, allongez-vous les jambes appuyées contre le mur.', title_hi = 'पैरों पर नसों का जाल? 🕸️', body_hi = 'वैरिकोज़ नसें हो सकती हैं। देर तक खड़ी मत रहिए। शाम को पैर दीवार पर टिकाकर लेटिए।', title_id = 'Ada jaring di kaki Anda? 🕸️', body_id = 'Varises bisa muncul. Jangan berdiri terlalu lama. Di malam hari, berbaringlah dengan kaki bersandar ke dinding.', title_ja = '脚に網目のような血管？🕸️', body_ja = '静脈瘤ができることがあります。長時間立ちっぱなしは避けましょう。夕方は脚を壁にもたせかけて横になってください。', title_ko = '다리에 핏줄이 보이나요? 🕸️', body_ko = '정맥류가 생길 수 있어요. 오래 서 있지 마세요. 저녁에는 다리를 벽에 기대어 올리고 누우세요.', title_nl = 'Adertjes op je benen? 🕸️', body_nl = 'Er kunnen spataderen ontstaan. Sta niet te lang. Ga ''s avonds liggen met je benen tegen de muur.', title_pl = 'Pajączki na nogach? 🕸️', body_pl = 'Mogą pojawić się żylaki. Nie stój zbyt długo. Wieczorem połóż się z nogami opartymi o ścianę.', title_pt = 'Tem uma rede de veias nas pernas? 🕸️', body_pt = 'Podem surgir varizes. Não fique muito tempo de pé. À noite, deite-se com as pernas encostadas à parede.', title_sv = 'Har du nät på benen? 🕸️', body_sv = 'Åderbråck kan uppstå. Stå inte upp länge i taget. På kvällarna, lägg dig ner med benen uppåt mot väggen.', title_vi = 'Chân mẹ có mạng nhện? 🕸️', body_vi = 'Có thể xuất hiện giãn tĩnh mạch. Đừng đứng quá lâu. Buổi tối hãy nằm gác chân lên tường.', title_zh = '腿上出现青筋了？🕸️', body_zh = '可能会出现静脉曲张。不要长时间站着。晚上把腿靠在墙上躺一会儿吧。' WHERE id = '90084ac3-06b5-4f06-ab1a-792e7c238804' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'La fábrica de sangre se ha puesto en marcha 🩸', body_es = 'Hasta ahora era el hígado, pero ahora es la médula ósea la que fabrica células sanguíneas. ¡Es la preparación para una vida independiente!', title_fr = 'L''usine à sang est en marche 🩸', body_fr = 'Jusqu''ici, c''était le foie, maintenant c''est la moelle osseuse qui fabrique les cellules sanguines. C''est la préparation à une vie autonome !', title_hi = 'खून की फ़ैक्ट्री चालू हो गई 🩸', body_hi = 'अब तक लिवर खून की कोशिकाएँ बनाता था, अब बोन मैरो बनाता है। यह आत्मनिर्भर जीवन की तैयारी है!', title_id = 'Pabrik darah mulai bekerja 🩸', body_id = 'Selama ini hati, kini sumsum tulang yang memproduksi sel darah. Ini persiapan untuk hidup mandiri!', title_ja = '血液工場が稼働中 🩸', body_ja = 'これまでは肝臓が、今は骨髄が血液細胞をつくっています。ひとりで生きていくための準備です！', title_ko = '혈액 공장이 가동됐어요 🩸', body_ko = '지금까지는 간이, 이제는 골수가 혈액 세포를 만들어요. 독립적인 삶을 위한 준비예요!', title_nl = 'De bloedfabriek draait 🩸', body_nl = 'Tot nu toe maakte de lever bloedcellen, nu doet het beenmerg dat. Een voorbereiding op een zelfstandig leven!', title_pl = 'Fabryka krwi ruszyła 🩸', body_pl = 'Do tej pory komórki krwi produkowała wątroba, a teraz szpik kostny. To przygotowanie do samodzielnego życia!', title_pt = 'A fábrica de sangue entrou em funcionamento 🩸', body_pt = 'Até agora era o fígado, mas agora é a medula óssea que produz as células do sangue. É a preparação para uma vida independente!', title_sv = 'Blodfabriken har satt igång 🩸', body_sv = 'Hittills har levern tillverkat blodkropparna, nu gör benmärgen det. Det är förberedelser för ett självständigt liv!', title_vi = 'Nhà máy máu đã hoạt động 🩸', body_vi = 'Trước giờ là gan, còn giờ tủy xương sản xuất tế bào máu. Đây là bước chuẩn bị cho cuộc sống tự lập!', title_zh = '造血工厂开工啦 🩸', body_zh = '之前是肝脏在制造血细胞，现在换成了骨髓。这是在为独立生活做准备！' WHERE id = '7a6fc4a8-e1e2-4415-a61f-8af42944c1a1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'La pareja hierro + vitamina C 🥩🍊', body_es = 'Contra el riesgo de anemia: cuando comas carne, bebe zumo de naranja. La vitamina C duplica la absorción del hierro.', title_fr = 'Le duo fer + vitamine C 🥩🍊', body_fr = 'Contre le risque d''anémie : quand vous mangez de la viande, buvez du jus d''orange. La vitamine C double l''absorption du fer.', title_hi = 'आयरन+विटामिन C की जोड़ी 🥩🍊', body_hi = 'एनीमिया से बचने के लिए: मांस खाते समय साथ में संतरे का जूस पीजिए। विटामिन C आयरन का अवशोषण 2 गुना बढ़ा देता है।', title_id = 'Pasangan zat besi + vitamin C 🥩🍊', body_id = 'Untuk mencegah anemia: saat makan daging, minumlah jus jeruk. Vitamin C meningkatkan penyerapan zat besi hingga 2 kali lipat.', title_ja = '鉄分とビタミンCのコンビ 🥩🍊', body_ja = '貧血予防のために、お肉を食べるときはオレンジジュースを一緒に。ビタミンCで鉄分の吸収が2倍になります。', title_ko = '철분+비타민 C 단짝 🥩🍊', body_ko = '빈혈 예방 팁: 고기를 먹을 때 오렌지 주스를 함께 드세요. 비타민 C는 철분 흡수를 2배로 높여 줘요.', title_nl = 'Het duo ijzer + vitamine C 🥩🍊', body_nl = 'Tegen bloedarmoede: drink sinaasappelsap bij je vlees. Vitamine C verdubbelt de opname van ijzer.', title_pl = 'Duet żelazo + witamina C 🥩🍊', body_pl = 'Przeciw anemii: do mięsa pij sok pomarańczowy. Witamina C 2 razy zwiększa wchłanianie żelaza.', title_pt = 'A dupla ferro + vitamina C 🥩🍊', body_pt = 'Contra o risco de anemia: quando comer carne, beba sumo de laranja. A vitamina C duplica a absorção do ferro.', title_sv = 'Duon järn + C-vitamin 🥩🍊', body_sv = 'Mot blodbrist: drick apelsinjuice när du äter kött. C-vitamin fördubblar upptaget av järn.', title_vi = 'Cặp đôi Sắt + Vitamin C 🥩🍊', body_vi = 'Phòng ngừa thiếu máu: Khi ăn thịt, hãy uống kèm nước cam. Vitamin C giúp tăng hấp thu sắt gấp 2 lần.', title_zh = '铁+维生素C黄金搭档 🥩🍊', body_zh = '预防贫血：吃肉时配一杯橙汁。维生素C能让铁的吸收提高2倍。' WHERE id = 'c0cb44c3-4840-4ac8-9cb6-1e444e960d76' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Una col grande 🥬', body_es = 'Mi piel se alisa y mis mofletes se llenan. ¡Estoy deseando verte!', title_fr = 'Un gros chou 🥬', body_fr = 'Ma peau devient lisse, mes joues se remplissent. J''ai hâte de vous voir !', title_hi = 'एक बड़ी पत्तागोभी 🥬', body_hi = 'मेरी त्वचा चिकनी हो रही है, गाल भर रहे हैं। आपको देखने के लिए बेताब हूँ!', title_id = 'Sebesar kubis 🥬', body_id = 'Kulitku makin halus, pipiku makin berisi. Aku tidak sabar ingin melihat Anda!', title_ja = '大きなキャベツくらい 🥬', body_ja = '肌がなめらかになって、ほっぺがふっくらしてきたよ。ママに会うのが待ちきれない！', title_ko = '커다란 양배추만 해요 🥬', body_ko = '제 피부가 매끈해지고 볼이 통통해지고 있어요. 엄마를 빨리 보고 싶어요!', title_nl = 'Een grote kool 🥬', body_nl = 'Mijn huid wordt gladder en mijn wangetjes voller. Ik kan niet wachten om je te zien!', title_pl = 'Duża główka kapusty 🥬', body_pl = 'Moja skóra się wygładza, policzki się zaokrąglają. Nie mogę się doczekać, aż cię zobaczę!', title_pt = 'Uma couve grande 🥬', body_pt = 'A minha pele está a ficar lisa e as bochechas a encher. Estou ansioso por a ver!', title_sv = 'Ett stort kålhuvud 🥬', body_sv = 'Min hud blir slätare och kinderna fylligare. Jag längtar efter att få se dig!', title_vi = 'Một bắp cải to 🥬', body_vi = 'Da con mịn hơn, má con căng tròn. Con nóng lòng được gặp mẹ!', title_zh = '一颗大白菜那么大 🥬', body_zh = '我的皮肤越来越光滑，脸蛋越来越圆。好想快点见到你！' WHERE id = '5f837347-a4f8-48d6-bc79-6f4d3e4ab2ed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te falta el aire? 😮‍💨', body_es = 'Al subir, presiono tu diafragma. Intenta respirar hondo, mamá. Queda poco, pronto bajaré.', title_fr = 'Vous manquez de souffle ? 😮‍💨', body_fr = 'En montant, j''appuie sur votre diaphragme. Essayez de respirer profondément, Maman. Bientôt, je vais descendre.', title_hi = 'साँस नहीं ले पा रहीं? 😮‍💨', body_hi = 'मैं जैसे-जैसे ऊपर आता हूँ, आपके डायाफ़्राम को दबाता हूँ। गहरी साँस लेने की कोशिश कीजिए, माँ। थोड़े दिन और, मैं नीचे उतर जाऊँगा।', title_id = 'Sulit bernapas? 😮‍💨', body_id = 'Saat aku naik, aku menekan diafragma Anda. Cobalah bernapas dalam-dalam, Bunda. Sebentar lagi aku akan turun.', title_ja = '息苦しい？😮‍💨', body_ja = 'わたしが上のほうへ行くと、横隔膜を押しちゃうの。深呼吸してみてね、ママ。もう少ししたら下に降りるからね。', title_ko = '숨이 차세요? 😮‍💨', body_ko = '제가 위로 올라가면서 횡격막을 누르고 있어요. 깊게 숨을 쉬어 보세요, 엄마. 조금만 기다리면 아래로 내려갈 거예요.', title_nl = 'Kortademig? 😮‍💨', body_nl = 'Als ik hoger kom te liggen, druk ik op je middenrif. Probeer diep adem te halen, mama. Nog even, dan zak ik.', title_pl = 'Brakuje ci tchu? 😮‍💨', body_pl = 'Gdy przesuwam się w górę, uciskam twoją przeponę. Staraj się oddychać głęboko, Mamo. Już niedługo zejdę niżej.', title_pt = 'Falta-lhe o ar? 😮‍💨', body_pt = 'Ao subir, aperto o seu diafragma. Tente respirar fundo, Mamã. Falta pouco para eu descer.', title_sv = 'Svårt att andas? 😮‍💨', body_sv = 'När jag kommer högre upp trycker jag på din diafragma. Försök andas djupt, mamma. Snart sjunker jag nedåt.', title_vi = 'Mẹ thấy khó thở? 😮‍💨', body_vi = 'Con càng lên cao, càng chèn vào cơ hoành của mẹ. Mẹ cố hít thở sâu nhé. Sắp rồi, con sẽ xuống thấp thôi.', title_zh = '喘不过气？😮‍💨', body_zh = '我往上长，就会压到你的横膈膜。妈妈，试着深呼吸。快了，我很快就会往下走。' WHERE id = 'a1284943-8afb-4514-a518-910d7434b8db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Cómo será mi carácter? ✨', body_es = '¿Testarudo o sensible? ¿Qué dice mi signo según mi fecha de nacimiento? ¿Encajo con tu signo? ¡Vamos a mirar el Horóscopo! 🌠', title_fr = 'Quel sera mon caractère ? ✨', body_fr = 'Têtu ou sensible ? Que dit mon signe selon ma date de naissance ? Suis-je compatible avec votre signe ? Regardons l''Horoscope ! 🌠', title_hi = 'मेरा स्वभाव कैसा होगा? ✨', body_hi = 'ज़िद्दी या भावुक? मेरी जन्म तिथि के हिसाब से मेरी राशि क्या कहती है? क्या मैं आपकी राशि से मेल खाता हूँ? चलिए राशिफल देखें! 🌠', title_id = 'Bagaimana sifatku nanti? ✨', body_id = 'Keras kepala atau perasa? Apa kata zodiakku berdasarkan tanggal lahirku? Apakah aku cocok dengan zodiak Anda? Yuk, lihat Ramalan Bintang! 🌠', title_ja = 'どんな性格になるかな？✨', body_ja = '頑固？それとも感受性豊か？わたしの予定日からみると、星座は何かな？ママの星座と相性はいい？「星占い」を見てみよう！🌠', title_ko = '제 성격은 어떨까요? ✨', body_ko = '고집쟁이일까요, 감성파일까요? 제 출산 예정일로 보면 별자리는 뭐라고 할까요? 엄마 별자리와 잘 맞을까요? 별자리 운세를 봐요! 🌠', title_nl = 'Wat voor karakter krijg ik? ✨', body_nl = 'Koppig of gevoelig? Wat zegt mijn sterrenbeeld op basis van mijn uitgerekende datum? Pas ik bij jouw sterrenbeeld? Laten we de Horoscoop bekijken! 🌠', title_pl = 'Jaki będę mieć charakter? ✨', body_pl = 'Upór czy wrażliwość? Co mówi mój znak zodiaku według daty porodu? Czy pasuję do twojego znaku? Zajrzyjmy do Horoskopu! 🌠', title_pt = 'Como vai ser o meu feitio? ✨', body_pt = 'Teimoso ou sensível? O que diz o meu signo, segundo a data prevista do parto? Combinamos com o seu signo? Vamos ver o Horóscopo! 🌠', title_sv = 'Hur kommer min personlighet att bli? ✨', body_sv = 'Envis eller känslosam? Vad säger mitt stjärntecken utifrån mitt beräknade födelsedatum? Passar jag ihop med ditt tecken? Kom, vi tittar i Horoskopet! 🌠', title_vi = 'Tính cách của con sẽ thế nào? ✨', body_vi = 'Bướng bỉnh hay đa cảm? Cung hoàng đạo theo ngày sinh của con nói gì? Con có hợp với cung của mẹ không? Mình cùng xem Tử vi nhé! 🌠', title_zh = '我的性格会是什么样？✨', body_zh = '倔强还是感性？按我的预产期，我的星座会是什么？和你的星座合得来吗？一起去看看星座运势吧！🌠' WHERE id = '283efed7-5c27-4325-a5d1-abc7b9874001' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te duelen las costillas? 🥊', body_es = 'Perdona, mamá, tengo poco espacio. Cuando estiro las piernas, te doy en las costillas. Sentarte recta puede ayudarte.', title_fr = 'Mal aux côtes ? 🥊', body_fr = 'Pardon Maman, je manque de place. Quand j''étire mes jambes, je touche vos côtes. Vous asseoir bien droite peut vous aider.', title_hi = 'पसलियों में दर्द? 🥊', body_hi = 'माफ़ करना माँ, मेरे पास जगह कम है। पैर फैलाता हूँ तो आपकी पसलियों से टकराता हूँ। सीधा बैठना आपकी मदद कर सकता है।', title_id = 'Tulang rusuk sakit? 🥊', body_id = 'Maaf, Bunda, ruanganku sempit. Saat aku meluruskan kaki, aku mengenai tulang rusuk Anda. Duduk tegak bisa membantu.', title_ja = '肋骨が痛い？🥊', body_ja = 'ごめんね、ママ、お部屋が狭いの。脚を伸ばすとママの肋骨に当たっちゃう。まっすぐ座ると楽になるかも。', title_ko = '갈비뼈가 아프세요? 🥊', body_ko = '미안해요 엄마, 자리가 좁아요. 다리를 뻗으면 엄마 갈비뼈에 닿아요. 똑바로 앉으면 도움이 될 수 있어요.', title_nl = 'Pijn aan je ribben? 🥊', body_nl = 'Sorry, mama, ik heb weinig ruimte. Als ik mijn benen strek, raak ik je ribben. Rechtop zitten kan je helpen.', title_pl = 'Bolą cię żebra? 🥊', body_pl = 'Przepraszam, Mamo, mam mało miejsca. Gdy prostuję nóżki, trafiam w twoje żebra. Siedzenie prosto może ci pomóc.', title_pt = 'Dores nas costelas? 🥊', body_pt = 'Desculpe, Mamã, tenho pouco espaço. Quando estico as pernas, bato nas suas costelas. Sentar-se direita pode ajudar.', title_sv = 'Gör revbenen ont? 🥊', body_sv = 'Förlåt mamma, jag har ont om plats. När jag sträcker ut benen når jag dina revben. Att sitta rak kan hjälpa dig.', title_vi = 'Xương sườn bị đau? 🥊', body_vi = 'Xin lỗi mẹ, chỗ con chật quá. Khi duỗi chân, con chạm vào xương sườn của mẹ. Ngồi thẳng có thể giúp mẹ dễ chịu hơn.', title_zh = '肋骨疼？🥊', body_zh = '对不起妈妈，我的空间太小了。我伸腿时会碰到你的肋骨。坐直一点可能会好些。' WHERE id = '2d850fd8-33a5-4d99-8d38-9501167a4a14' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Cuentas las patadas? 🦶', body_es = 'Ya se está formando mi patrón de movimientos. Entra en el Contador de patadas y sigue mi actividad. ¿Todo en orden?', title_fr = 'Vous comptez mes coups de pied ? 🦶', body_fr = 'Mon rythme de mouvements se met en place. Ouvrez le Compteur de coups de pied et suivez mon activité. Tout va bien ?', title_hi = 'किक गिनती हैं? 🦶', body_hi = 'अब मेरी हलचल का एक पैटर्न बन रहा है। किक काउंटर खोलिए और मेरी गतिविधि पर नज़र रखिए। सब ठीक है?', title_id = 'Menghitung tendangan? 🦶', body_id = 'Pola gerakanku mulai terbentuk. Buka Penghitung Tendangan dan pantau aktivitasku. Semuanya baik-baik saja?', title_ja = 'キックを数えてる？🦶', body_ja = '動きのリズムができてきたよ。「キックカウンター」を開いて、わたしの動きをチェックしてね。すべて順調？', title_ko = '발차기를 세고 있나요? 🦶', body_ko = '이제 움직임 패턴이 생기고 있어요. 태동 카운터에서 제 활동을 살펴보세요. 모든 게 괜찮나요?', title_nl = 'Tel je mijn trappen? 🦶', body_nl = 'Ik krijg nu een vast bewegingspatroon. Open de Schoppenteller en volg mijn activiteit. Is alles in orde?', title_pl = 'Liczysz kopnięcia? 🦶', body_pl = 'Kształtuje się już mój rytm ruchów. Zajrzyj do Licznika kopnięć i śledź moją aktywność. Wszystko w porządku?', title_pt = 'Está a contar os pontapés? 🦶', body_pt = 'O meu padrão de movimentos já se está a formar. Abra o Contador de Pontapés e acompanhe a minha atividade. Está tudo bem?', title_sv = 'Räknar du sparkarna? 🦶', body_sv = 'Nu formas ett rörelsemönster. Öppna Sparkräknaren och följ min aktivitet. Är allt som det ska?', title_vi = 'Mẹ có đếm cú đạp không? 🦶', body_vi = 'Nhịp cử động của con đã hình thành. Vào Đếm cú đạp và theo dõi hoạt động của con nhé. Mọi thứ ổn chứ?', title_zh = '在数胎动吗？🦶', body_zh = '我的活动规律正在形成。打开胎动计数器，记录我的活动吧。一切都好吗？' WHERE id = '881c71cb-32af-4e22-9bf1-839ae870e7a5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡A mi cerebro le salen arrugas! 🧠', body_es = 'Antes era liso y ahora se forman pliegues y surcos. Eso significa que se ponen en marcha miles de millones de neuronas. ¡Viene un genio!', title_fr = 'Mon cerveau se plisse ! 🧠', body_fr = 'Avant il était lisse, maintenant des plis et des sillons apparaissent. Des milliards de neurones se mettent au travail. Un génie arrive !', title_hi = 'मेरे दिमाग में सिलवटें बन रही हैं! 🧠', body_hi = 'पहले यह चिकना था, अब इसमें सिलवटें और खाँचे बन रहे हैं। इसका मतलब है अरबों न्यूरॉन काम पर लग गए। जीनियस आ रहा है!', title_id = 'Otakku mulai berlipat! 🧠', body_id = 'Dulu halus, kini muncul lipatan dan alur. Artinya miliaran neuron mulai bekerja. Si jenius akan datang!', title_ja = '脳にしわができてきたよ！🧠', body_ja = '前はつるつるだったけど、今はしわや溝ができてきたの。何十億もの神経細胞が働きはじめたってこと。天才がやってくるよ！', title_ko = '제 뇌에 주름이 생겨요! 🧠', body_ko = '전에는 매끈했는데 이제 주름과 고랑이 생기고 있어요. 수십억 개의 뉴런이 일하기 시작했다는 뜻이에요. 천재가 오고 있어요!', title_nl = 'Mijn hersenen krijgen plooien! 🧠', body_nl = 'Eerst waren ze glad, nu ontstaan er plooien en groeven. Dat betekent dat miljarden neuronen aan het werk gaan. Er komt een genie aan!', title_pl = 'Mój mózg się marszczy! 🧠', body_pl = 'Wcześniej był gładki, a teraz powstają zakręty i bruzdy. To znaczy, że ruszają miliardy neuronów. Nadchodzi geniusz!', title_pt = 'O meu cérebro está a ganhar rugas! 🧠', body_pt = 'Antes era liso, agora estão a formar-se rugas e sulcos. Isto significa que milhares de milhões de neurónios estão a entrar em ação. Vem aí um génio!', title_sv = 'Min hjärna får veck! 🧠', body_sv = 'Förut var den slät, nu bildas veck och fåror. Det betyder att miljarder nervceller sätter igång. Ett geni är på väg!', title_vi = 'Não con đang có nếp nhăn! 🧠', body_vi = 'Trước kia não phẳng, giờ đã xuất hiện các nếp và rãnh. Điều đó nghĩa là hàng tỷ tế bào thần kinh đang hoạt động. Một thiên tài đang đến!', title_zh = '我的大脑长出褶皱啦！🧠', body_zh = '以前很光滑，现在出现了褶皱和沟回。这意味着数十亿神经元开始工作了。小天才要来啦！' WHERE id = '9d46b716-6bee-4533-9dcb-2ebd6327811f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿El reflujo te agota? 🔥', body_es = '¿El ácido del estómago te sube a la garganta? Mascar chicle después de comer o beber leche tibia puede ayudarte.', title_fr = 'Le reflux vous fatigue ? 🔥', body_fr = 'L''acide de l''estomac remonte dans la gorge ? Mâcher un chewing-gum après le repas ou boire du lait tiède peut aider.', title_hi = 'रिफ़्लक्स से थक गईं? 🔥', body_hi = 'पेट का एसिड गले तक आता है? खाने के बाद च्युइंग गम चबाना या गुनगुना दूध पीना मदद कर सकता है।', title_id = 'Refluks membuat Anda lelah? 🔥', body_id = 'Asam lambung naik ke tenggorokan? Mengunyah permen karet atau minum susu hangat setelah makan bisa membantu.', title_ja = '逆流性の胸やけでつらい？🔥', body_ja = '胃酸がのどまで上がってきますか？食後にガムをかんだり、温かい牛乳を飲んだりすると楽になることがあります。', title_ko = '역류 때문에 힘드세요? 🔥', body_ko = '위산이 목까지 올라오나요? 식후에 껌을 씹거나 따뜻한 우유를 마시면 도움이 될 수 있어요.', title_nl = 'Last van reflux? 🔥', body_nl = 'Komt het maagzuur in je keel? Kauwgom na het eten of een glas warme melk kan helpen.', title_pl = 'Męczy cię refluks? 🔥', body_pl = 'Kwas żołądkowy podchodzi do gardła? Pomóc może żucie gumy po jedzeniu lub ciepłe mleko.', title_pt = 'O refluxo está a cansá-la? 🔥', body_pt = 'O ácido do estômago sobe até à garganta? Mastigar pastilha elástica depois das refeições ou beber leite morno pode ajudar.', title_sv = 'Tröttar sura uppstötningar ut dig? 🔥', body_sv = 'Kommer magsyran upp i halsen? Att tugga tuggummi efter maten eller dricka ljummen mjölk kan hjälpa.', title_vi = 'Trào ngược làm mẹ mệt mỏi? 🔥', body_vi = 'Axit dạ dày trào lên cổ họng? Nhai kẹo cao su sau bữa ăn hoặc uống sữa ấm có thể giúp ích.', title_zh = '胃酸反流让你疲惫？🔥', body_zh = '胃酸涌到喉咙？饭后嚼口香糖或喝杯温牛奶可能会有帮助。' WHERE id = 'b2fb0049-069a-46c3-bea3-307a0c34873c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Has pensado en la bolsa? 👜', body_es = '¡No es demasiado pronto! Echa un vistazo a la lista de la Bolsa del hospital. Completar lo que falta desde ya reduce el estrés.', title_fr = 'Vous avez pensé à votre sac ? 👜', body_fr = 'Ce n''est pas trop tôt ! Jetez un œil à la liste Valise de maternité. Compléter ce qui manque dès maintenant réduira le stress.', title_hi = 'बैग के बारे में सोचा? 👜', body_hi = 'अभी जल्दी नहीं है! हॉस्पिटल बैग की लिस्ट देखिए। कमी वाली चीज़ें अभी से पूरी करने से तनाव कम होगा।', title_id = 'Sudah memikirkan tas Anda? 👜', body_id = 'Tidak terlalu cepat! Lihat daftar Tas Rumah Sakit. Melengkapi yang kurang dari sekarang akan mengurangi stres.', title_ja = '入院バッグのこと、考えた？👜', body_ja = '早すぎることはありません！「入院バッグ」リストを見てみましょう。足りないものを今のうちにそろえると、ストレスが減ります。', title_ko = '출산 가방 생각해 보셨어요? 👜', body_ko = '이르지 않아요! 출산 가방 목록을 살펴보세요. 부족한 것을 미리 채워 두면 스트레스가 줄어요.', title_nl = 'Al aan je tas gedacht? 👜', body_nl = 'Het is niet te vroeg! Bekijk de checklist Ziekenhuistas. Als je wat ontbreekt nu al aanvult, heb je minder stress.', title_pl = 'Myślałaś o torbie? 👜', body_pl = 'To nie za wcześnie! Zajrzyj do listy Torba do szpitala. Uzupełnienie braków już teraz zmniejszy stres.', title_pt = 'Já pensou na mala? 👜', body_pt = 'Não é cedo! Veja a lista da Mala da Maternidade. Completar já o que falta reduz o stress.', title_sv = 'Har du tänkt på väskan? 👜', body_sv = 'Det är inte för tidigt! Kika på listan för BB-väskan. Att fylla på det som saknas redan nu minskar stressen.', title_vi = 'Mẹ đã nghĩ đến túi đồ đi sinh chưa? 👜', body_vi = 'Không còn sớm đâu! Hãy xem danh sách Túi đồ đi sinh. Bổ sung những thứ còn thiếu từ bây giờ sẽ giúp giảm căng thẳng.', title_zh = '想过待产包了吗？👜', body_zh = '现在不算早！看看待产包清单，提前补齐缺的东西能减少压力。' WHERE id = '8e4d973a-778f-424e-8c3a-935a1a80329f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te cuento un secreto? 🤫', body_es = 'Cuando duermes, me duermo soñando con tu voz. ¿A quién crees que veo en sueños? ¡A ti, claro! 🥰', title_fr = 'Je vous dis un secret ? 🤫', body_fr = 'Quand vous dormez, je m''endors en rêvant de votre voix. À votre avis, qui je vois dans mes rêves ? Vous, bien sûr ! 🥰', title_hi = 'एक राज़ बताऊँ? 🤫', body_hi = 'आप सोती हैं, तो मैं आपकी आवाज़ के ख्याल में सो जाता हूँ। बताइए, मैं सपने में किसे देखता हूँ? बेशक, आपको! 🥰', title_id = 'Mau dengar rahasia? 🤫', body_id = 'Saat Anda tidur, aku terlelap sambil membayangkan suara Anda. Menurut Anda, siapa yang ada di mimpiku? Tentu saja Anda! 🥰', title_ja = 'ひみつを教えてあげようか？🤫', body_ja = 'ママが眠るとき、ママの声を思い浮かべながら眠りにつくの。夢で誰に会っていると思う？もちろんママだよ！🥰', title_ko = '비밀 하나 알려 드릴까요? 🤫', body_ko = '엄마가 잘 때 저는 엄마 목소리를 떠올리며 잠들어요. 제가 꿈에서 누구를 볼까요? 당연히 엄마죠! 🥰', title_nl = 'Zal ik je een geheimpje vertellen? 🤫', body_nl = 'Als jij slaapt, val ik in slaap met de herinnering aan je stem. Raad eens wie ik in mijn dromen zie? Jou natuurlijk! 🥰', title_pl = 'Zdradzić ci sekret? 🤫', body_pl = 'Gdy śpisz, zasypiam, marząc o twoim głosie. Jak myślisz, kogo widzę we śnie? Oczywiście ciebie! 🥰', title_pt = 'Posso contar-lhe um segredo? 🤫', body_pt = 'Quando dorme, adormeço a sonhar com a sua voz. Quem acha que vejo nos meus sonhos? A Mamã, claro! 🥰', title_sv = 'Ska jag berätta en hemlighet? 🤫', body_sv = 'När du sover somnar jag med drömmen om din röst. Vem tror du att jag drömmer om? Dig, så klart! 🥰', title_vi = 'Con kể mẹ một bí mật nhé? 🤫', body_vi = 'Khi mẹ ngủ, con chìm vào giấc ngủ cùng hình bóng giọng nói của mẹ. Mẹ đoán xem con mơ thấy ai? Tất nhiên là mẹ rồi! 🥰', title_zh = '告诉你一个秘密？🤫', body_zh = '你睡着时，我想着你的声音入睡。你猜我梦见了谁？当然是你！🥰' WHERE id = '5e65c444-b9a6-406f-9ff5-56e21f7ef978' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Eso era chocolate? 🍫', body_es = '¡Mmm, el sabor ha llegado hasta aquí! Ahora tengo energía de sobra. ¡Bailemos, mamá! 💃', title_fr = 'C''était du chocolat ? 🍫', body_fr = 'Mmm, le goût est arrivé jusqu''ici ! Maintenant, je déborde d''énergie. On danse, Maman ! 💃', title_hi = 'वह चॉकलेट थी? 🍫', body_hi = 'म्म्म, उसका स्वाद यहाँ तक पहुँच गया! अब मेरी ऊर्जा उमड़ रही है। चलिए डांस करें, माँ! 💃', title_id = 'Tadi itu cokelat? 🍫', body_id = 'Mmm, rasanya sampai ke sini! Sekarang energiku meluap-luap. Ayo kita menari, Bunda! 💃', title_ja = '今のはチョコレート？🍫', body_ja = 'んー、味がここまで届いたよ！元気があふれてきちゃった。一緒に踊ろう、ママ！💃', title_ko = '방금 그거 초콜릿이었어요? 🍫', body_ko = '음, 그 맛이 여기까지 왔어요! 이제 에너지가 넘쳐요. 같이 춤춰요, 엄마! 💃', title_nl = 'Was dat chocolade? 🍫', body_nl = 'Mmm, die smaak kwam helemaal tot hier! Ik zit nu boordevol energie. Kom, laten we dansen, mama! 💃', title_pl = 'Czy to była czekolada? 🍫', body_pl = 'Mmm, ten smak dotarł aż tutaj! Teraz energia mnie rozpiera. Zatańczmy, Mamo! 💃', title_pt = 'Aquilo era chocolate? 🍫', body_pt = 'Hmm, o sabor chegou até aqui! Agora estou cheio de energia. Vamos dançar, Mamã! 💃', title_sv = 'Var det choklad? 🍫', body_sv = 'Mmm, smaken nådde ända hit in! Nu sprudlar jag av energi. Kom, vi dansar, mamma! 💃', title_vi = 'Vừa rồi là sô-cô-la à? 🍫', body_vi = 'Mmm, vị ngọt đến tận đây luôn! Giờ năng lượng của con tràn trề. Mình cùng nhảy nhé, mẹ ơi! 💃', title_zh = '刚才是巧克力吗？🍫', body_zh = '嗯，味道都传到这儿来了！现在我精力满满。妈妈，我们一起跳舞吧！💃' WHERE id = 'd7852d04-73e0-436f-88c1-c1f3779215e1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Soy como una calabaza! 🎃', body_es = '¡Mis mofletes están tan gorditos que te darán ganas de morderlos! Tengo poco espacio, pero me encanta estar cerca de ti.', title_fr = 'Je suis grand comme une citrouille ! 🎃', body_fr = 'Mes joues deviennent si rondes que vous aurez envie de les croquer ! Je manque de place, mais c''est si bon d''être près de vous.', title_hi = 'मैं कद्दू जितना हूँ! 🎃', body_hi = 'मेरे गाल इतने गोल-मटोल हो रहे हैं कि आप उन्हें काटना चाहेंगी! जगह तंग है, पर आपके करीब रहना अच्छा लगता है।', title_id = 'Aku sudah seukuran labu! 🎃', body_id = 'Pipiku makin tembam sampai Anda ingin menggigitnya! Ruanganku sempit, tapi senang rasanya berada dekat dengan Anda.', title_ja = 'かぼちゃくらいになったよ！🎃', body_ja = 'ほっぺがぷくぷくになってきて、かじりたくなっちゃうかも！お部屋は狭いけど、ママのそばにいられてうれしいよ。', title_ko = '저는 호박만 해요! 🎃', body_ko = '볼이 너무 통통해져서 깨물고 싶어질 거예요! 자리는 좁지만 엄마 곁에 있어서 좋아요.', title_nl = 'Ik ben zo groot als een pompoen! 🎃', body_nl = 'Mijn wangetjes worden zo bol dat je er straks in wilt knijpen! Het is krap hier, maar ik vind het fijn om zo dicht bij je te zijn.', title_pl = 'Jestem wielkości dyni! 🎃', body_pl = 'Moje policzki tak się zaokrąglają, że będziesz chciała mnie schrupać! Mam ciasno, ale dobrze być blisko ciebie.', title_pt = 'Sou do tamanho de uma abóbora! 🎃', body_pt = 'As minhas bochechas estão a ficar tão gordinhas que vai querer trincá-las! O espaço é apertado, mas é bom estar perto de si.', title_sv = 'Jag är lika stor som en pumpa! 🎃', body_sv = 'Mina kinder blir så knubbiga att du kommer att vilja tugga på dem! Det är trångt här, men det är skönt att vara nära dig.', title_vi = 'Con to bằng quả bí ngô rồi! 🎃', body_vi = 'Má con phúng phính đến mức mẹ sẽ muốn cắn yêu! Chỗ của con chật, nhưng được gần mẹ thật thích.', title_zh = '我有一个南瓜那么大！🎃', body_zh = '我的脸蛋胖得让你忍不住想咬一口！这里有点挤，但能离你这么近真好。' WHERE id = 'cbb3164b-a073-4125-89bc-aa96300b8738' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Estoy cabeza abajo! 🙃', body_es = '¡Es curioso ver la vida del revés! Me estoy preparando para el parto, mamá. En esta posición estoy más cerca de ti.', title_fr = 'J''ai la tête en bas ! 🙃', body_fr = 'Voir la vie à l''envers, c''est amusant ! Je me prépare pour la naissance, Maman. Dans cette position, je suis encore plus près de vous.', title_hi = 'मैं उल्टा हो गया हूँ! 🙃', body_hi = 'दुनिया को उल्टा देखना मज़ेदार है! मैं जन्म की तैयारी कर रहा हूँ, माँ। इस पोज़िशन में मैं आपके और करीब हूँ।', title_id = 'Aku sudah jungkir balik! 🙃', body_id = 'Seru juga melihat hidup dari posisi terbalik! Aku sedang bersiap untuk lahir, Bunda. Di posisi ini aku lebih dekat dengan Anda.', title_ja = '逆さまになったよ！🙃', body_ja = '逆さまに見る世界っておもしろい！お産の準備をしているよ、ママ。この姿勢だと、ママにもっと近いんだ。', title_ko = '거꾸로 섰어요! 🙃', body_ko = '세상을 거꾸로 보니 재밌어요! 출산 준비 중이에요, 엄마. 이 자세에서는 엄마와 더 가까워요.', title_nl = 'Ik sta op mijn kop! 🙃', body_nl = 'Het leven ondersteboven zien is best leuk! Ik maak me klaar voor de geboorte, mama. In deze houding ben ik nog dichter bij je.', title_pl = 'Stoję na głowie! 🙃', body_pl = 'Ciekawie jest widzieć świat do góry nogami! Przygotowuję się do porodu, Mamo. W tej pozycji jestem bliżej ciebie.', title_pt = 'Estou de cabeça para baixo! 🙃', body_pt = 'Ver a vida ao contrário é interessante! Estou a preparar-me para o parto, Mamã. Nesta posição estou mais perto de si.', title_sv = 'Jag står på huvudet! 🙃', body_sv = 'Det är spännande att se livet upp och ner! Jag förbereder mig för födseln, mamma. I den här ställningen är jag ännu närmare dig.', title_vi = 'Con lộn ngược đầu rồi! 🙃', body_vi = 'Nhìn đời lộn ngược thật thú vị! Con đang chuẩn bị chào đời, mẹ ạ. Ở tư thế này con gần mẹ hơn.', title_zh = '我倒立啦！🙃', body_zh = '倒着看世界真有趣！妈妈，我在为出生做准备。这个姿势让我离你更近。' WHERE id = '24a71b37-df5d-44b3-a005-e5736c2b3038' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Se te pone dura la barriga? 🤰', body_es = '¡No tengas miedo, mi ángel! Es solo un ensayo. ¡Nos preparamos como un equipo para el gran día!', title_fr = 'Votre ventre durcit ? 🤰', body_fr = 'N''ayez pas peur, mon ange ! Ce n''est qu''un entraînement. Nous nous préparons en équipe pour le grand jour !', title_hi = 'पेट सख्त हो रहा है? 🤰', body_hi = 'घबराइए मत, मेरी परी! यह बस अभ्यास है। हम एक टीम की तरह उस बड़े दिन की तैयारी कर रहे हैं!', title_id = 'Perut terasa mengeras? 🤰', body_id = 'Jangan takut, Malaikatku! Ini hanya latihan. Kita bersiap untuk hari besar itu sebagai satu tim!', title_ja = 'お腹が張る？🤰', body_ja = '心配しないで、ママ！これはただの練習だよ。わたしたちはチームで、大切な日に向けて準備しているの！', title_ko = '배가 단단해지나요? 🤰', body_ko = '걱정 마세요, 나의 천사! 이건 그냥 연습이에요. 우리는 한 팀으로 그 큰날을 준비하고 있어요!', title_nl = 'Wordt je buik hard? 🤰', body_nl = 'Geen zorgen, lieverd! Dit is maar een oefening. We bereiden ons als team voor op de grote dag!', title_pl = 'Brzuch ci twardnieje? 🤰', body_pl = 'Nie bój się, Aniołku! To tylko trening. Jako zespół przygotowujemy się do wielkiego dnia!', title_pt = 'A barriga fica dura? 🤰', body_pt = 'Não se assuste, meu Anjo! É só um treino. Somos uma equipa a preparar-se para o grande dia!', title_sv = 'Blir magen hård? 🤰', body_sv = 'Var inte rädd, min ängel! Det är bara träning. Vi förbereder oss som ett lag inför den stora dagen!', title_vi = 'Bụng mẹ cứng lại? 🤰', body_vi = 'Đừng sợ, thiên thần của con! Đây chỉ là tập dượt thôi. Chúng mình là một đội, cùng chuẩn bị cho ngày trọng đại!', title_zh = '肚子发硬？🤰', body_zh = '别怕，我的天使！这只是演习。我们是一个团队，正在为那个重要的日子做准备！' WHERE id = '2bb496d6-7982-41e7-af5d-07497cf28d32' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Ha llegado la voz de papá! 🧔', body_es = 'Cuando oigo su voz, mi corazón late más fuerte. ¡Dile que yo también estoy aquí y le saludo! 👋', title_fr = 'J''entends la voix de Papa ! 🧔', body_fr = 'Quand j''entends sa voix, mon cœur bat plus fort. Dites-lui que je suis là aussi et que je lui dis bonjour ! 👋', title_hi = 'पापा की आवाज़ आई! 🧔', body_hi = 'उनकी आवाज़ सुनकर मेरा दिल और ज़ोर से धड़कता है। उनसे कहिए कि मैं भी यहाँ हूँ, हैलो कह रहा हूँ! 👋', title_id = 'Ada suara Ayah! 🧔', body_id = 'Saat mendengar suaranya, jantungku berdetak lebih kencang. Katakan padanya aku juga di sini dan menyapanya! 👋', title_ja = 'パパの声が聞こえた！🧔', body_ja = 'パパの声を聞くと、心臓がもっとドキドキするの。わたしもここにいて、あいさつしてるよって伝えてね！👋', title_ko = '아빠 목소리가 들려요! 🧔', body_ko = '아빠 목소리를 들으면 제 심장이 더 세게 뛰어요. 저도 여기서 인사하고 있다고 전해 주세요! 👋', title_nl = 'Daar is papa’s stem! 🧔', body_nl = 'Als ik zijn stem hoor, klopt mijn hart nog harder. Zeg hem dat ik er ook ben en hem gedag zeg! 👋', title_pl = 'Słychać głos taty! 🧔', body_pl = 'Gdy słyszę jego głos, moje serce bije mocniej. Powiedz mu, że ja też tu jestem i mówię cześć! 👋', title_pt = 'Ouvi a voz do pai! 🧔', body_pt = 'Quando o ouço, o meu coração bate mais forte. Diga-lhe que também estou aqui a dizer olá! 👋', title_sv = 'Där kom pappas röst! 🧔', body_sv = 'När jag hör hans röst slår mitt hjärta hårdare. Säg till honom att jag också är här och säger hej! 👋', title_vi = 'Có tiếng bố rồi! 🧔', body_vi = 'Khi nghe tiếng bố, tim con đập mạnh hơn. Mẹ nói với bố là con cũng ở đây, con chào bố nhé! 👋', title_zh = '爸爸的声音来啦！🧔', body_zh = '听到爸爸的声音，我的心跳得更快了。告诉他，我也在这儿，跟他打招呼呢！👋' WHERE id = '6c2d3dce-218d-4319-8647-5e91a8fe5c40' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Dale fuerza a mis huesos! 💪', body_es = 'Necesito calcio, mamá. Si te tomas un vaso de leche o un yogur, ¡los dos seremos superfuertes! 🥛', title_fr = 'Donnez de la force à mes os ! 💪', body_fr = 'J''ai besoin de calcium, Maman. Si vous buvez un verre de lait ou mangez un yaourt, nous serons tous les deux super forts ! 🥛', title_hi = 'मेरी हड्डियों को ताकत दीजिए! 💪', body_hi = 'मुझे कैल्शियम चाहिए, माँ। आप एक गिलास दूध या दही लें, तो हम दोनों सुपर स्ट्रॉन्ग बन जाएँगे! 🥛', title_id = 'Kuatkan tulang-tulangku! 💪', body_id = 'Aku butuh kalsium, Bunda. Jika Anda minum segelas susu atau yogurt, kita berdua akan jadi super kuat! 🥛', title_ja = '骨を強くして！💪', body_ja = 'カルシウムが必要なの、ママ。牛乳かヨーグルトを1杯飲んだら、2人ともパワーアップだよ！🥛', title_ko = '제 뼈에 힘을 주세요! 💪', body_ko = '칼슘이 필요해요, 엄마. 우유나 요거트 한 잔이면 우리 둘 다 슈퍼 튼튼해질 거예요! 🥛', title_nl = 'Geef mijn botjes kracht! 💪', body_nl = 'Ik heb calcium nodig, mama. Als je een glas melk of yoghurt neemt, worden we allebei supersterk! 🥛', title_pl = 'Daj siłę moim kościom! 💪', body_pl = 'Potrzebuję wapnia, Mamo. Jeśli wypijesz szklankę mleka lub jogurtu, oboje będziemy super silni! 🥛', title_pt = 'Dê força aos meus ossos! 💪', body_pt = 'Preciso de cálcio, Mamã. Se beber um copo de leite ou comer um iogurte, ficamos os dois superfortes! 🥛', title_sv = 'Ge mina ben styrka! 💪', body_sv = 'Jag behöver kalcium, mamma. Om du dricker ett glas mjölk eller äter yoghurt blir vi båda superstarka! 🥛', title_vi = 'Cho xương con thêm sức mạnh! 💪', body_vi = 'Con cần canxi, mẹ ơi. Nếu mẹ uống một cốc sữa hoặc ăn sữa chua, cả hai mình sẽ siêu khỏe! 🥛', title_zh = '给我的骨头加油！💪', body_zh = '妈妈，我需要钙。你喝一杯牛奶或酸奶，我们俩都会变得超级强壮！🥛' WHERE id = '8564b0d7-d9cc-487d-822b-1f8072415eb2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Toc, toc! ¿Quién hay ahí? ✊', body_es = '¿A veces te hacen daño mis patadas? Perdona 🥺 Solo quiero tocarte.', title_fr = 'Toc-toc ! Qui est là ? ✊', body_fr = 'Mes coups de pied vous font parfois mal ? Pardon 🥺 Je veux juste vous toucher.', title_hi = 'खट-खट! कौन है वहाँ? ✊', body_hi = 'मेरी किक कभी-कभी दर्द देती है? माफ़ करना 🥺 मैं बस आपको छूना चाहता हूँ।', title_id = 'Tok-tok! Siapa di sana? ✊', body_id = 'Tendanganku kadang menyakiti Anda? Maaf ya 🥺 Aku hanya ingin menyentuh Anda.', title_ja = 'トントン！誰かいる？✊', body_ja = 'キックが痛いときもある？ごめんね 🥺 ただママに触れたいだけなの。', title_ko = '똑똑! 거기 누구 있어요? ✊', body_ko = '제 발차기가 가끔 아프게 하나요? 미안해요 🥺 그냥 엄마를 만지고 싶어서요.', title_nl = 'Klop klop! Wie is daar? ✊', body_nl = 'Doen mijn trappen soms pijn? Sorry 🥺 Ik wil je gewoon aanraken.', title_pl = 'Puk-puk! Kto tam? ✊', body_pl = 'Moje kopnięcia czasem cię bolą? Przepraszam 🥺 Po prostu chcę cię dotknąć.', title_pt = 'Toc-toc! Quem está aí? ✊', body_pt = 'Os meus pontapés às vezes magoam? Desculpe 🥺 Só quero tocar-lhe.', title_sv = 'Knack-knack! Vem där? ✊', body_sv = 'Gör mina sparkar ibland ont? Förlåt 🥺 Jag vill bara röra vid dig.', title_vi = 'Cốc cốc! Ai đó? ✊', body_vi = 'Những cú đạp của con đôi khi làm mẹ đau à? Con xin lỗi 🥺 Con chỉ muốn chạm vào mẹ thôi.', title_zh = '咚咚！谁在那儿？✊', body_zh = '我的踢动有时会弄疼你吗？对不起 🥺 我只是想碰碰你。' WHERE id = '15ce00b6-4caf-41e5-8ad8-51691c8f30be' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te cuesta respirar? 😮‍💨', body_es = 'He subido un poco y presiono tus pulmones. Perdona, mamá, ¡pronto bajaré y respirarás tranquila! 🤞', title_fr = 'Vous manquez de souffle ? 😮‍💨', body_fr = 'Je suis un peu monté, j''appuie sur vos poumons. Pardon Maman, je vais bientôt descendre et vous respirerez mieux ! 🤞', title_hi = 'साँस फूल रही है? 😮‍💨', body_hi = 'मैं थोड़ा ऊपर आ गया हूँ, आपके फेफड़ों को दबा रहा हूँ। माफ़ करना माँ, जल्द ही नीचे उतर जाऊँगा और आप आराम से साँस ले सकेंगी! 🤞', title_id = 'Napas terasa sesak? 😮‍💨', body_id = 'Aku naik sedikit dan menekan paru-paru Anda. Maaf, Bunda, sebentar lagi aku akan turun dan Anda bisa bernapas lega! 🤞', title_ja = '息が苦しい？😮‍💨', body_ja = '少し上に上がって、ママの肺を押しちゃってるの。ごめんね、ママ、もうすぐ下に降りるから、楽に息ができるようになるよ！🤞', title_ko = '숨이 가쁘세요? 😮‍💨', body_ko = '제가 조금 위로 올라와서 엄마 폐를 누르고 있어요. 미안해요 엄마, 곧 아래로 내려가면 편하게 숨 쉬실 거예요! 🤞', title_nl = 'Kortademig? 😮‍💨', body_nl = 'Ik ben wat hoger gaan liggen en druk op je longen. Sorry, mama, ik zak straks weer en dan kun je weer vrij ademen! 🤞', title_pl = 'Brakuje ci tchu? 😮‍💨', body_pl = 'Jestem teraz trochę wyżej i uciskam twoje płuca. Przepraszam, Mamo, niedługo zejdę niżej i będziesz swobodnie oddychać! 🤞', title_pt = 'Falta-lhe o fôlego? 😮‍💨', body_pt = 'Subi um bocadinho e estou a apertar os seus pulmões. Desculpe, Mamã, em breve vou descer e vai respirar à vontade! 🤞', title_sv = 'Blir du andfådd? 😮‍💨', body_sv = 'Jag har flyttat mig lite uppåt och trycker på dina lungor. Förlåt mamma, snart sjunker jag nedåt och du kan andas lättare! 🤞', title_vi = 'Mẹ thấy khó thở? 😮‍💨', body_vi = 'Con lên cao một chút, đang chèn vào phổi của mẹ. Xin lỗi mẹ, con sẽ sớm xuống thấp và mẹ sẽ thở dễ hơn! 🤞', title_zh = '呼吸不畅？😮‍💨', body_zh = '我往上挪了一点，压到了你的肺。对不起妈妈，我很快就会往下走，你就能轻松呼吸啦！🤞' WHERE id = 'b989ed16-7146-4f41-9b58-332ae708a0f2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Notaré tu olor...', body_es = '¿Piensas en el momento en que me tendrás en brazos? ¡Yo crezco cada día soñando con ese momento, mamá! 🌸', title_fr = 'Je sentirai votre odeur...', body_fr = 'Vous pensez au moment où vous me prendrez dans vos bras ? Moi, je grandis chaque jour en rêvant de ce moment, Maman ! 🌸', title_hi = 'मैं आपकी खुशबू पहचानूँगा...', body_hi = 'क्या आप उस पल के बारे में सोचती हैं जब मुझे गोद में लेंगी? मैं हर दिन उसी पल के सपने के साथ बढ़ रहा हूँ, माँ! 🌸', title_id = 'Aku akan mencium aroma Anda...', body_id = 'Apakah Anda membayangkan saat menggendongku? Aku tumbuh setiap hari sambil memimpikan saat itu, Bunda! 🌸', title_ja = 'ママのにおいを感じるよ...', body_ja = 'わたしを抱っこする瞬間を思い浮かべてる？わたしは毎日その瞬間を夢見ながら大きくなっているよ、ママ！🌸', title_ko = '엄마 냄새를 느낄 거예요...', body_ko = '저를 품에 안을 그 순간을 상상하나요? 저는 매일 그 순간을 꿈꾸며 자라고 있어요, 엄마! 🌸', title_nl = 'Ik ga je geur ruiken...', body_nl = 'Denk jij ook aan het moment dat je me in je armen neemt? Ik groei elke dag met die droom, mama! 🌸', title_pl = 'Poczuję twój zapach...', body_pl = 'Myślisz o chwili, gdy weźmiesz mnie w ramiona? Ja rosnę każdego dnia, marząc o tej chwili, Mamo! 🌸', title_pt = 'Vou sentir o seu cheiro...', body_pt = 'Pensa no momento em que me vai pegar ao colo? Eu cresço todos os dias a sonhar com esse momento, Mamã! 🌸', title_sv = 'Jag kommer att känna din doft...', body_sv = 'Tänker du på ögonblicket när du får ta mig i famnen? Jag växer varje dag med drömmen om det ögonblicket, mamma! 🌸', title_vi = 'Con sẽ cảm nhận được mùi của mẹ...', body_vi = 'Mẹ có nghĩ về khoảnh khắc mẹ ôm con vào lòng không? Con lớn lên mỗi ngày với giấc mơ về khoảnh khắc ấy, mẹ ơi! 🌸', title_zh = '我会闻到你的味道……', body_zh = '你在想把我抱进怀里的那一刻吗？妈妈，我每天都梦着那一刻长大！🌸' WHERE id = '030e064d-37b0-4189-9cde-718dbc4298a7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Mi casa se queda pequeña... 🏠', body_es = 'Mis movimientos se convierten en puñetazos y codazos. ¿Todo va bien? ¡Vamos a mirar juntos el Contador de patadas!', title_fr = 'Ma maison devient étroite... 🏠', body_fr = 'Mes mouvements se transforment en coups de poing et de coude. Tout va bien ? Vérifions ensemble le Compteur de coups de pied !', title_hi = 'मेरा घर तंग हो रहा है... 🏠', body_hi = 'मेरी हरकतें मुक्कों और कोहनियों में बदल रही हैं। सब ठीक है? चलिए साथ में किक काउंटर देखें!', title_id = 'Rumahku makin sempit... 🏠', body_id = 'Gerakanku berubah menjadi pukulan tinju dan siku. Semuanya baik-baik saja? Yuk, cek Penghitung Tendangan bersama!', title_ja = 'お部屋が狭くなってきた... 🏠', body_ja = '動きがパンチやひじ打ちに変わってきたよ。すべて順調？一緒に「キックカウンター」をチェックしよう！', title_ko = '집이 좁아지고 있어요... 🏠', body_ko = '제 움직임이 주먹질과 팔꿈치 치기로 바뀌고 있어요. 다 괜찮나요? 함께 태동 카운터를 확인해 봐요!', title_nl = 'Mijn huisje wordt krap... 🏠', body_nl = 'Mijn bewegingen worden stoten met vuistjes en ellebogen. Is alles in orde? Laten we samen de Schoppenteller bekijken!', title_pl = 'Mój domek robi się ciasny... 🏠', body_pl = 'Moje ruchy zamieniają się w ciosy pięści i łokci. Wszystko w porządku? Sprawdźmy razem Licznik kopnięć!', title_pt = 'A minha casa está a ficar apertada... 🏠', body_pt = 'Os meus movimentos estão a transformar-se em murros e cotoveladas. Está tudo bem? Vamos ver juntos o Contador de Pontapés!', title_sv = 'Mitt hem blir trångt... 🏠', body_sv = 'Mina rörelser blir till knytnävsslag och armbågsstötar. Är allt som det ska? Kom, vi kollar Sparkräknaren tillsammans!', title_vi = 'Nhà con chật dần... 🏠', body_vi = 'Cử động của con giờ thành những cú đấm và thúc khuỷu tay. Mọi thứ ổn chứ? Mình cùng kiểm tra Đếm cú đạp nhé!', title_zh = '我的家越来越小了……🏠', body_zh = '我的动作变成了小拳头和胳膊肘的撞击。一切都好吗？我们一起看看胎动计数器吧！' WHERE id = 'e03f95b4-ad0c-4331-ae04-096968066425' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Necesitas aire 🌿', body_es = '¿Salimos hoy de casa a tomar un té en un sitio tranquilo y con aire limpio? ¡Mira los Lugares para mamás!', title_fr = 'Vous avez besoin d''air 🌿', body_fr = 'Et si on sortait aujourd''hui boire un thé dans un endroit calme et bien aéré ? Découvrez les Lieux adaptés aux mamans !', title_hi = 'आपको ताज़ी हवा चाहिए 🌿', body_hi = 'आज घर से निकलकर किसी आरामदायक, साफ़ हवा वाली जगह चाय पिएँ? माँ के लिए अनुकूल जगहें देखिए!', title_id = 'Anda butuh udara segar 🌿', body_id = 'Bagaimana kalau hari ini keluar rumah dan minum teh di tempat yang nyaman dan berudara segar? Lihat Tempat Ramah Ibu!', title_ja = '新鮮な空気が必要です 🌿', body_ja = '今日はおでかけして、空気のきれいな落ち着いた場所でお茶でもどう？「ママにやさしいスポット」を見てみてね！', title_ko = '바람을 쐬어야 해요 🌿', body_ko = '오늘은 집을 나서서 공기 좋고 편안한 곳에서 차 한잔할까요? 엄마 친화 장소를 확인해 보세요!', title_nl = 'Je hebt frisse lucht nodig 🌿', body_nl = 'Zullen we vandaag de deur uitgaan en thee drinken op een rustige plek met frisse lucht? Kijk eens bij Mamavriendelijke plekken!', title_pl = 'Potrzebujesz powietrza 🌿', body_pl = 'Może wyjdziemy dziś z domu i napijemy się herbaty w spokojnym miejscu ze świeżym powietrzem? Zajrzyj do Miejsc przyjaznych mamom!', title_pt = 'Precisa de ar fresco 🌿', body_pt = 'Hoje saímos de casa e bebemos um chá num sítio tranquilo e com ar puro? Veja os Locais Amigos das Mães!', title_sv = 'Du behöver frisk luft 🌿', body_sv = 'Ska vi gå ut i dag och dricka te på ett lugnt ställe med frisk luft? Titta i Mammavänliga platser!', title_vi = 'Mẹ cần không khí trong lành 🌿', body_vi = 'Hôm nay mình ra ngoài, uống trà ở một nơi yên tĩnh, thoáng đãng nhé? Xem mục Địa điểm thân thiện với mẹ nào!', title_zh = '你需要透透气 🌿', body_zh = '今天出门找个舒适、空气清新的地方喝杯茶吧？看看妈妈友好场所！' WHERE id = '76a21abd-5509-4070-92f1-19d3342eec20' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Ese gran día... ✨', body_es = 'Sin prisa, pero vamos preparando la bolsa poco a poco. ¿Vemos qué hay en la lista de la Bolsa del hospital?', title_fr = 'Le grand jour... ✨', body_fr = 'Ne nous précipitons pas, mais commençons à préparer notre sac petit à petit. On regarde ce qu''il y a dans la liste Valise de maternité ?', title_hi = 'वह बड़ा दिन... ✨', body_hi = 'जल्दबाज़ी नहीं, पर धीरे-धीरे बैग तैयार करते हैं। चलिए देखें, हॉस्पिटल बैग की लिस्ट में क्या है?', title_id = 'Hari besar itu... ✨', body_id = 'Tidak perlu terburu-buru, tapi mari kemas tas kita sedikit demi sedikit. Yuk, lihat apa saja di daftar Tas Rumah Sakit?', title_ja = '大切な日... ✨', body_ja = '急がなくていいけど、少しずつバッグの準備をしようね。「入院バッグ」リストに何があるか見てみよう？', title_ko = '그 큰날... ✨', body_ko = '서두르지 말고 가방을 천천히 싸 봐요. 출산 가방 목록에 뭐가 있는지 볼까요?', title_nl = 'Die grote dag... ✨', body_nl = 'Geen haast, maar laten we langzaam onze tas inpakken. Zullen we kijken wat er op de checklist Ziekenhuistas staat?', title_pl = 'Ten wielki dzień... ✨', body_pl = 'Nie spieszmy się, ale powoli pakujmy torbę. Zobaczmy, co jest na liście Torba do szpitala?', title_pt = 'O grande dia... ✨', body_pt = 'Sem pressas, mas vamos preparando a mala aos poucos. Vamos ver o que há na lista da Mala da Maternidade?', title_sv = 'Den stora dagen... ✨', body_sv = 'Vi behöver inte stressa, men låt oss packa väskan lite i taget. Ska vi kolla vad som står på listan för BB-väskan?', title_vi = 'Ngày trọng đại ấy... ✨', body_vi = 'Không cần vội, nhưng mình hãy từ từ chuẩn bị túi đồ. Cùng xem danh sách Túi đồ đi sinh có gì nhé?', title_zh = '那个重要的日子……✨', body_zh = '不着急，但我们可以慢慢收拾待产包了。看看待产包清单里有什么吧？' WHERE id = '24bc4a35-8099-475a-bea1-67cccf403b8e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Cómo me vas a llamar? 👶', body_es = 'Si aún no lo has decidido, mirad con papá la lista de Nombres de bebé. ¿Cuál me queda mejor?', title_fr = 'Comment allez-vous m''appeler ? 👶', body_fr = 'Si vous n''avez pas encore décidé, regardez la liste des Prénoms de bébé avec Papa. Lequel me va le mieux ?', title_hi = 'आप मुझे किस नाम से बुलाएँगी? 👶', body_hi = 'अगर अभी तय नहीं किया, तो पापा के साथ बेबी नेम्स की लिस्ट देखिए। मुझ पर कौन सा नाम सबसे ज़्यादा जँचेगा?', title_id = 'Aku akan diberi nama apa? 👶', body_id = 'Jika belum memutuskan, lihat daftar Nama Bayi bersama Ayah. Nama mana yang paling cocok untukku?', title_ja = 'わたしの名前はなんにする？👶', body_ja = 'まだ決めていなかったら、パパと一緒に「ベビーネーム」リストを見てみてね。わたしにいちばん似合うのはどれかな？', title_ko = '저를 뭐라고 부를 거예요? 👶', body_ko = '아직 정하지 않았다면 아빠와 함께 아기 이름 목록을 살펴보세요. 저에게 어떤 이름이 가장 잘 어울릴까요?', title_nl = 'Hoe ga je me noemen? 👶', body_nl = 'Nog geen keuze gemaakt? Bekijk samen met papa de lijst Babynamen. Welke naam past het best bij mij?', title_pl = 'Jak mnie nazwiesz? 👶', body_pl = 'Jeśli jeszcze nie zdecydowałaś, przejrzyjcie z tatą listę Imiona dla dzieci. Które najbardziej do mnie pasuje?', title_pt = 'Como me vai chamar? 👶', body_pt = 'Se ainda não decidiu, veja com o pai a lista de Nomes de Bebé. Qual é que me fica melhor?', title_sv = 'Vad ska du kalla mig? 👶', body_sv = 'Om du inte har bestämt dig än, kika på listan Babynamn tillsammans med pappa. Vilket passar mig bäst?', title_vi = 'Mẹ sẽ đặt tên con là gì? 👶', body_vi = 'Nếu mẹ chưa quyết định, hãy cùng bố xem danh sách Tên cho bé. Tên nào hợp với con nhất?', title_zh = '你会叫我什么名字？👶', body_zh = '如果还没决定，就和爸爸一起看看宝宝名字列表吧。哪个最适合我？' WHERE id = 'c28b4b45-5df1-4c21-963d-2cd627f1bb02' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Mi habitación, mi cuna, mis cositas... 🐣', body_es = '¿Has comprado todo lo que necesitamos? Mira los Productos recomendados, quizá se te haya olvidado algo.', title_fr = 'Ma chambre, mon lit, mes petites affaires... 🐣', body_fr = 'Avez-vous acheté tout ce dont nous avons besoin ? Jetez un œil aux Produits recommandés, peut-être avez-vous oublié quelque chose.', title_hi = 'मेरा कमरा, मेरा पालना, मेरी छोटी-छोटी चीज़ें... 🐣', body_hi = 'क्या हमें जो चाहिए, वह सब खरीद लिया? सुझाए गए प्रोडक्ट देखिए, शायद कुछ छूट गया हो।', title_id = 'Kamarku, tempat tidurku, barang-barang mungilku... 🐣', body_id = 'Sudah membeli semua yang kita perlukan? Lihat Produk Rekomendasi, mungkin ada yang terlupa.', title_ja = 'わたしのお部屋、ベビーベッド、小さなもの... 🐣', body_ja = '必要なものはぜんぶそろった？「おすすめ商品」を見てみて、何か忘れているかも。', title_ko = '제 방, 제 침대, 작은 물건들... 🐣', body_ko = '필요한 건 다 사셨어요? 추천 제품을 확인해 보세요, 뭔가 빠졌을지도 몰라요.', title_nl = 'Mijn kamer, mijn bedje, mijn kleine spulletjes... 🐣', body_nl = 'Heb je alles gekocht wat we nodig hebben? Kijk bij Aanbevolen producten, misschien is er iets vergeten.', title_pl = 'Mój pokój, łóżeczko, malutkie rzeczy... 🐣', body_pl = 'Kupiłaś wszystko, czego potrzebujemy? Zajrzyj do Polecanych produktów, może o czymś zapomniałaś.', title_pt = 'O meu quarto, o meu berço, as minhas coisinhas... 🐣', body_pt = 'Já comprou tudo o que precisamos? Veja os Produtos Recomendados, talvez falte alguma coisa.', title_sv = 'Mitt rum, min säng, mina små saker... 🐣', body_sv = 'Har du köpt allt vi behöver? Titta i Rekommenderade produkter, kanske har något glömts bort.', title_vi = 'Phòng của con, giường của con, đồ dùng bé xíu của con... 🐣', body_vi = 'Mẹ đã mua đủ mọi thứ mình cần chưa? Xem Sản phẩm gợi ý nhé, biết đâu có món bị quên.', title_zh = '我的房间、小床、小物件……🐣', body_zh = '我们需要的东西都买齐了吗？看看推荐商品，也许漏了什么。' WHERE id = 'c121195f-505c-434b-b2d9-c9f6d23b400a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Los músculos del útero se preparan para el parto.', body_es = 'Tranquila, es solo un ensayo. Si el dolor se repite a menudo, ¡revisa el intervalo con el Contador de contracciones!', title_fr = 'Les muscles de l''utérus se préparent à l''accouchement.', body_fr = 'Pas d''inquiétude, ce n''est qu''un entraînement. Si la douleur devient fréquente, vérifiez l''intervalle avec le Minuteur de contractions !', title_hi = 'गर्भाशय की मांसपेशियाँ डिलीवरी की तैयारी कर रही हैं।', body_hi = 'घबराइए मत, यह बस अभ्यास है। अगर दर्द बार-बार हो, तो कॉन्ट्रैक्शन टाइमर से अंतराल जाँचिए!', title_id = 'Otot rahim bersiap untuk persalinan.', body_id = 'Jangan takut, ini hanya latihan. Jika nyeri makin sering, cek jaraknya dengan Pengukur Kontraksi!', title_ja = '子宮の筋肉がお産の準備をしています。', body_ja = '心配しないで、これはただの練習です。痛みが頻繁になったら、「陣痛タイマー」で間隔を確認しましょう！', title_ko = '자궁 근육이 출산을 준비하고 있어요.', body_ko = '걱정 마세요, 그냥 연습이에요. 통증이 자주 오면 진통 측정기로 간격을 확인하세요!', title_nl = 'Je baarmoederspieren bereiden zich voor op de bevalling.', body_nl = 'Schrik niet, dit is maar een oefening. Komt de pijn vaak, controleer dan de tussenpozen met je Weeënteller!', title_pl = 'Mięśnie macicy przygotowują się do porodu.', body_pl = 'Nie bój się, to tylko trening. Jeśli ból pojawia się często, sprawdź odstępy w Liczniku skurczów!', title_pt = 'Os músculos do útero estão a preparar-se para o parto.', body_pt = 'Não se assuste, é só um treino. Se a dor ficar frequente, verifique o intervalo com o Contador de Contrações!', title_sv = 'Livmoderns muskler förbereder sig för förlossningen.', body_sv = 'Var inte rädd, det är bara träning. Om smärtan kommer ofta, kolla intervallen med Värkmätaren!', title_vi = 'Cơ tử cung đang chuẩn bị cho ca sinh.', body_vi = 'Đừng sợ, đây chỉ là tập dượt. Nếu cơn đau đến thường xuyên, hãy kiểm tra khoảng cách bằng Đo cơn co!', title_zh = '子宫肌肉正在为分娩做准备。', body_zh = '别怕，这只是演习。如果疼痛越来越频繁，用宫缩计时器查看间隔吧！' WHERE id = 'c3f0f3b0-ee69-4cef-beda-1bb1348e7009' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Mi manicura está lista!', body_es = 'No te lo vas a creer, pero mis uñas ya llegan a la punta de los dedos.', title_fr = 'Ma manucure est prête !', body_fr = 'Vous n''allez pas me croire, mais mes ongles arrivent déjà au bout de mes doigts.', title_hi = 'मेरा मैनीक्योर तैयार है!', body_hi = 'यकीन नहीं होगा, मेरे नाखून अब उँगलियों के सिरों तक पहुँच गए हैं।', title_id = 'Manikurku sudah siap!', body_id = 'Anda tidak akan percaya, kuku-kukuku sudah mencapai ujung jari.', title_ja = 'ネイルの準備完了！', body_ja = '信じられないかもしれないけど、爪がもう指先まで伸びたよ。', title_ko = '제 손톱 관리 완료!', body_ko = '믿기 어렵겠지만 제 손톱이 벌써 손가락 끝까지 자랐어요.', title_nl = 'Mijn manicure is klaar!', body_nl = 'Je gelooft het niet, maar mijn nageltjes reiken al tot mijn vingertopjes.', title_pl = 'Mój manicure gotowy!', body_pl = 'Nie uwierzysz, ale moje paznokcie sięgają już czubków palców.', title_pt = 'A minha manicura está pronta!', body_pt = 'Não vai acreditar, mas as minhas unhas já chegam às pontas dos dedos.', title_sv = 'Min manikyr är klar!', body_sv = 'Du kommer inte att tro det, men mina naglar har redan nått fingertopparna.', title_vi = 'Móng tay con đã sẵn sàng!', body_vi = 'Mẹ không tin đâu, móng tay con đã dài đến đầu ngón rồi.', title_zh = '我的美甲做好啦！', body_zh = '你可能不信，我的指甲已经长到指尖了。' WHERE id = '8dfa3145-c829-45b1-afeb-aa3c0845ee68' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Aumentan las visitas al médico! 🩺', body_es = '¿Ya has decidido el hospital y el médico para el parto? ¡Echa un vistazo a la lista de Médicos y clínicas! ✅', title_fr = 'Les rendez-vous chez le médecin se multiplient ! 🩺', body_fr = 'Avez-vous choisi la maternité et le médecin pour l''accouchement ? Jetez un œil à la liste Médecins et cliniques ! ✅', title_hi = 'डॉक्टर की मुलाकातें बढ़ रही हैं! 🩺', body_hi = 'क्या आपने डिलीवरी के लिए अस्पताल और डॉक्टर तय कर लिए? डॉक्टर और क्लिनिक की लिस्ट देखिए! ✅', title_id = 'Kunjungan ke dokter makin sering! 🩺', body_id = 'Sudah memastikan rumah sakit dan dokter untuk persalinan? Lihat daftar Dokter dan Klinik! ✅', title_ja = '健診が増えてきます！🩺', body_ja = '出産する病院とお医者さんは決まりましたか？「医師とクリニック」リストを見てみましょう！✅', title_ko = '진료가 잦아지고 있어요! 🩺', body_ko = '출산할 병원과 의사를 정하셨나요? 의사 및 병원 목록을 살펴보세요! ✅', title_nl = 'Meer afspraken bij de arts! 🩺', body_nl = 'Weet je al in welk ziekenhuis en bij welke arts je gaat bevallen? Bekijk de lijst Artsen en klinieken! ✅', title_pl = 'Coraz więcej wizyt u lekarza! 🩺', body_pl = 'Wybrałaś już szpital i lekarza do porodu? Zajrzyj do listy Lekarze i kliniki! ✅', title_pt = 'As consultas médicas estão a aumentar! 🩺', body_pt = 'Já definiu o hospital e o médico para o parto? Veja a lista de Médicos e Clínicas! ✅', title_sv = 'Läkarbesöken blir fler! 🩺', body_sv = 'Har du bestämt sjukhus och läkare för förlossningen? Kika på listan Läkare och kliniker! ✅', title_vi = 'Lịch khám bác sĩ dày hơn! 🩺', body_vi = 'Mẹ đã chọn được bệnh viện và bác sĩ đỡ đẻ chưa? Xem danh sách Bác sĩ và Phòng khám nhé! ✅', title_zh = '产检越来越频繁了！🩺', body_zh = '确定好分娩的医院和医生了吗？看看医生与诊所列表吧！✅' WHERE id = '59ee96ac-8001-4e85-87e8-bcbd686717cb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Ahora ríes y ahora lloras?', body_es = 'Las hormonas vuelven a jugar. El miedo al parto y la alegría del encuentro van juntos. Desahógate en el Diario de ánimo y relájate. ❤️', title_fr = 'Vous riez, puis vous pleurez ?', body_fr = 'Les hormones jouent encore des tours. La peur de l''accouchement et la joie des retrouvailles se mêlent. Videz votre cœur dans le Journal d''humeur et détendez-vous. ❤️', title_hi = 'कभी हँसी, कभी आँसू?', body_hi = 'हार्मोन फिर खेल खेल रहे हैं। डिलीवरी का डर और मिलने की खुशी एक साथ हैं। अपना दिल मूड डायरी में हल्का कीजिए, आराम कीजिए। ❤️', title_id = 'Sebentar tertawa, sebentar menangis?', body_id = 'Hormon sedang bermain lagi. Takut melahirkan dan bahagia akan bertemu bercampur jadi satu. Curahkan isi hati di Buku Harian Suasana Hati dan bersantailah. ❤️', title_ja = '笑ったり泣いたり？', body_ja = 'ホルモンがまたいたずらしています。お産への不安と、赤ちゃんに会えるうれしさが入りまじる時期。「気分日記」に気持ちを書き出して、ほっとしましょう。❤️', title_ko = '웃다가 울다가 하나요?', body_ko = '호르몬이 또 장난을 치고 있어요. 출산에 대한 두려움과 만남의 기쁨이 함께 있죠. 기분 일기에 마음을 털어놓고 편히 쉬세요. ❤️', title_nl = 'Het ene moment lachen, het andere huilen?', body_nl = 'De hormonen spelen weer spelletjes. Angst voor de bevalling en blijdschap om elkaar te ontmoeten gaan hand in hand. Stort je hart uit in je Stemmingsdagboek en ontspan. ❤️', title_pl = 'Raz się śmiejesz, raz płaczesz?', body_pl = 'Hormony znów płatają figle. Strach przed porodem miesza się z radością ze spotkania. Wylej serce w Dzienniku nastroju i odpocznij. ❤️', title_pt = 'Ora ri, ora chora?', body_pt = 'As hormonas voltam a pregar partidas. O medo do parto e a alegria do encontro andam juntos. Desabafe no Diário de Humor e relaxe. ❤️', title_sv = 'Ena stunden skrattar du, nästa gråter du?', body_sv = 'Hormonerna spelar dig spratt igen. Rädslan för förlossningen och glädjen över att träffas blandas. Lätta ditt hjärta i Humördagboken och slappna av. ❤️', title_vi = 'Lúc cười, lúc khóc?', body_vi = 'Hormone lại bày trò rồi. Nỗi sợ sinh nở và niềm vui được gặp con đan xen. Hãy trút lòng vào Nhật ký tâm trạng và thư giãn nhé. ❤️', title_zh = '一会儿笑，一会儿哭？', body_zh = '激素又在捣乱了。对分娩的害怕和即将相见的喜悦交织在一起。在心情日记里倾诉一下，放松吧。❤️' WHERE id = 'ca64b110-70d5-455b-a30e-4c256cab3188' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Me pasas superpoderes! 🛡️', body_es = '¡No te pongas enferma, mamá! Tus defensas serán mi primera armadura. ¡Somos un equipo invencible! 💪', title_fr = 'Vous me transmettez des super-pouvoirs ! 🛡️', body_fr = 'Ne tombez pas malade, Maman ! Votre immunité sera ma première armure. Nous sommes une équipe invincible ! 💪', title_hi = 'आपसे मुझे सुपर पावर मिल रही है! 🛡️', body_hi = 'बीमार मत पड़िए, माँ! आपकी इम्युनिटी मेरा पहला कवच होगी। हम एक अजेय टीम हैं! 💪', title_id = 'Kekuatan super mengalir dari Anda kepadaku! 🛡️', body_id = 'Jangan sakit ya, Bunda! Kekebalan tubuh Anda akan menjadi baju zirah pertamaku. Kita tim yang tak terkalahkan! 💪', title_ja = 'ママからスーパーパワーが届いているよ！🛡️', body_ja = '病気にならないでね、ママ！ママの免疫が、わたしの最初のよろいになるの。わたしたちは無敵のチームだよ！💪', title_ko = '엄마에게서 슈퍼 파워를 받아요! 🛡️', body_ko = '아프지 마세요, 엄마! 엄마의 면역력이 제 첫 갑옷이 될 거예요. 우리는 무적의 팀이에요! 💪', title_nl = 'Ik krijg superkrachten van jou! 🛡️', body_nl = 'Word niet ziek, mama! Jouw afweer wordt mijn eerste harnas. Wij zijn een onverslaanbaar team! 💪', title_pl = 'Przechodzi do mnie twoja supermoc! 🛡️', body_pl = 'Nie choruj, Mamo! Twoja odporność będzie moją pierwszą zbroją. Jesteśmy niepokonaną drużyną! 💪', title_pt = 'Recebo superpoderes da Mamã! 🛡️', body_pt = 'Não fique doente, Mamã! A sua imunidade vai ser a minha primeira armadura. Somos uma equipa imbatível! 💪', title_sv = 'Jag får superkrafter från dig! 🛡️', body_sv = 'Bli inte sjuk, mamma! Ditt immunförsvar blir min första rustning. Vi är ett oslagbart lag! 💪', title_vi = 'Siêu năng lực truyền từ mẹ sang con! 🛡️', body_vi = 'Đừng ốm nhé mẹ! Miễn dịch của mẹ sẽ là bộ giáp đầu tiên của con. Chúng mình là đội bất bại! 💪', title_zh = '超能力正从你身上传给我！🛡️', body_zh = '妈妈，别生病哦！你的免疫力会是我的第一副盔甲。我们是无敌组合！💪' WHERE id = '715eeefe-c617-4bf3-bb6a-6c3fba21c1f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Otra vez sin sueño? 🥺', body_es = 'Yo, en cambio, duermo plácidamente. Cierra los ojos, imagíname... ¿A lo mejor nuestros sueños se juntan? 🌙', title_fr = 'Encore une insomnie ? 🥺', body_fr = 'Moi, je dors à poings fermés. Fermez les yeux, imaginez-moi... Peut-être que nos rêves se rejoindront ? 🌙', title_hi = 'फिर से नींद उड़ गई? 🥺', body_hi = 'और मैं चैन से सो रहा हूँ। आँखें बंद कीजिए, मेरा सपना देखिए... शायद हमारे सपने मिल जाएँ? 🌙', title_id = 'Susah tidur lagi? 🥺', body_id = 'Sementara aku tidur nyenyak. Pejamkan mata, bayangkan aku... Mungkin mimpi kita akan bertemu? 🌙', title_ja = 'また眠れないの？🥺', body_ja = 'わたしはすやすや眠ってるよ。目を閉じて、わたしを思い浮かべて...夢の中で会えるかも？🌙', title_ko = '또 잠이 안 오나요? 🥺', body_ko = '저는 새근새근 자고 있어요. 눈을 감고 저를 떠올려 보세요... 우리 꿈이 만날지도 몰라요? 🌙', title_nl = 'Kun je weer niet slapen? 🥺', body_nl = 'Ik slaap heerlijk. Doe je ogen dicht en droom van mij... Misschien komen onze dromen samen? 🌙', title_pl = 'Znowu nie możesz zasnąć? 🥺', body_pl = 'A ja śpię słodko jak suseł. Zamknij oczy, wyobraź sobie mnie... Może nasze sny się spotkają? 🌙', title_pt = 'O sono fugiu outra vez? 🥺', body_pt = 'E eu durmo que nem um anjo. Feche os olhos, sonhe comigo... Talvez os nossos sonhos se encontrem? 🌙', title_sv = 'Har sömnen flytt igen? 🥺', body_sv = 'Själv sover jag sött. Blunda och dröm om mig... Kanske möts våra drömmar? 🌙', title_vi = 'Lại mất ngủ rồi à? 🥺', body_vi = 'Còn con thì ngủ say sưa. Mẹ nhắm mắt lại, nghĩ về con... Biết đâu giấc mơ của mình gặp nhau? 🌙', title_zh = '又睡不着了？🥺', body_zh = '我可睡得正香呢。闭上眼睛，想着我……也许我们会在梦里相见？🌙' WHERE id = 'c1070439-01ff-45b2-8b26-5012c32a3638' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Mis huesos se ponen duros como piedras! 🦴', body_es = 'Pero para eso te robo tus reservas... ¡Perdona! 🙈 ¿Hacemos las paces si te tomas un vaso de leche? 🥛', title_fr = 'Mes os deviennent durs comme la pierre ! 🦴', body_fr = 'Mais pour cela, je vous vole vos réserves... Pardon ! 🙈 Si vous buvez un verre de lait, on fait la paix ? 🥛', title_hi = 'मेरी हड्डियाँ पत्थर जैसी हो रही हैं! 🦴', body_hi = 'पर इसके लिए मैं आपका भंडार चुरा रहा हूँ... माफ़ करना! 🙈 एक गिलास दूध पी लें, तो सुलह कर लें? 🥛', title_id = 'Tulang-tulangku jadi sekeras batu! 🦴', body_id = 'Tapi untuk itu aku mencuri cadangan Anda... Maaf ya! 🙈 Kalau Anda minum segelas susu, kita baikan? 🥛', title_ja = '骨が石みたいに強くなるよ！🦴', body_ja = 'でもそのために、ママの蓄えをちょっともらっちゃってるの...ごめんね！🙈 牛乳を1杯飲んでくれたら、仲直りできる？🥛', title_ko = '제 뼈가 돌처럼 단단해지고 있어요! 🦴', body_ko = '그런데 그러려고 엄마의 칼슘을 훔치고 있어요... 미안해요! 🙈 우유 한 잔 드시면 화해할까요? 🥛', title_nl = 'Mijn botjes worden zo hard als steen! 🦴', body_nl = 'Maar daarvoor pik ik wat van jouw voorraad... Sorry! 🙈 Als je een glas melk drinkt, is het dan weer goed? 🥛', title_pl = 'Moje kości twardnieją jak kamień! 🦴', body_pl = 'Ale żeby tak było, podkradam twoje zapasy... Przepraszam! 🙈 Jeśli wypijesz szklankę mleka, pogodzimy się? 🥛', title_pt = 'Os meus ossos estão a ficar duros como pedra! 🦴', body_pt = 'Mas para isso estou a roubar as suas reservas... Desculpe! 🙈 Se beber um copo de leite, fazemos as pazes? 🥛', title_sv = 'Mina ben blir hårda som sten! 🦴', body_sv = 'Men för det snor jag ditt förråd... Förlåt! 🙈 Blir vi sams om du dricker ett glas mjölk? 🥛', title_vi = 'Xương con cứng như đá! 🦴', body_vi = 'Nhưng để làm vậy, con lấy trộm dự trữ của mẹ... Xin lỗi mẹ! 🙈 Mẹ uống một cốc sữa, mình làm lành nhé? 🥛', title_zh = '我的骨头变得像石头一样硬！🦴', body_zh = '不过为此我偷了你的储备……对不起！🙈 你喝一杯牛奶，我们就和好吧？🥛' WHERE id = '8be6aa28-e9ad-4b76-b7b7-9a3182c371dc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Canta otra vez esa canción! 🎶', body_es = 'Tu voz me da tanta calma... Cuando cantas, yo bailo aquí dentro, ¿lo notas? 💃', title_fr = 'Chantez encore cette chanson ! 🎶', body_fr = 'Votre voix m''apaise tellement... Quand vous chantez, je danse à l''intérieur, vous le sentez ? 💃', title_hi = 'वह गाना फिर से गाइए! 🎶', body_hi = 'आपकी आवाज़ मुझे इतना सुकून देती है... आप गाती हैं, तो मैं अंदर डांस करता हूँ, महसूस होता है? 💃', title_id = 'Nyanyikan lagu itu sekali lagi! 🎶', body_id = 'Suara Anda begitu menenangkanku... Saat Anda bernyanyi, aku menari di dalam, terasa? 💃', title_ja = 'あの歌をもう一度歌って！🎶', body_ja = 'ママの声を聞くと、とても安心するの...ママが歌うと、お腹の中で踊っちゃう。感じる？💃', title_ko = '그 노래 한 번 더 불러 주세요! 🎶', body_ko = '엄마 목소리는 정말 편안해요... 엄마가 노래하면 저는 안에서 춤을 춰요, 느껴지세요? 💃', title_nl = 'Zing dat liedje nog eens! 🎶', body_nl = 'Je stem geeft me zoveel rust... Als jij zingt, dans ik hier binnen, voel je het? 💃', title_pl = 'Zaśpiewaj tę piosenkę jeszcze raz! 🎶', body_pl = 'Twój głos daje mi tyle spokoju... Gdy śpiewasz, tańczę w środku, czujesz? 💃', title_pt = 'Cante outra vez aquela canção! 🎶', body_pt = 'A sua voz acalma-me tanto... Quando canta, eu danço aqui dentro, sente? 💃', title_sv = 'Sjung den där låten igen! 🎶', body_sv = 'Din röst lugnar mig så mycket... När du sjunger dansar jag här inne, känner du det? 💃', title_vi = 'Mẹ hát lại bài đó đi! 🎶', body_vi = 'Giọng mẹ làm con thấy thật bình yên... Khi mẹ hát, con nhảy múa bên trong, mẹ có cảm thấy không? 💃', title_zh = '那首歌再唱一遍！🎶', body_zh = '你的声音让我好安心……你唱歌时，我在里面跳舞，感觉到了吗？💃' WHERE id = '80a0c6d7-ffbe-49de-90ea-da3074257deb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Las paredes se me echan encima! 🏠', body_es = 'Me he quedado sin espacio, mamá. Estiro la pierna y te doy en las costillas... Si te he hecho daño, ¿te lo curo con un beso? 💋', title_fr = 'Les murs se rapprochent ! 🏠', body_fr = 'Je manque vraiment de place, Maman. J''étire ma jambe, elle touche vos côtes... Si je vous ai fait mal, un bisou et ça passe ? 💋', title_hi = 'दीवारें मुझ पर आ रही हैं! 🏠', body_hi = 'मेरी जगह बहुत तंग हो गई है, माँ। पैर फैलाता हूँ, तो आपकी पसली से टकराता है... दर्द हुआ हो, तो चूमकर ठीक कर दूँ? 💋', title_id = 'Dinding-dinding mendekatiku! 🏠', body_id = 'Ruanganku sudah sangat sempit, Bunda. Saat aku meluruskan kaki, kena tulang rusuk Anda... Kalau sakit, boleh kucium biar sembuh? 💋', title_ja = '壁が迫ってくる！🏠', body_ja = 'お部屋がすっかり狭くなったよ、ママ。脚を伸ばすと肋骨に当たっちゃう...痛かったら、チュッとしてあげるね？💋', title_ko = '벽이 저에게 다가와요! 🏠', body_ko = '자리가 정말 좁아졌어요, 엄마. 다리를 뻗으면 엄마 갈비뼈에 닿아요... 아팠다면 뽀뽀해서 낫게 해 줄까요? 💋', title_nl = 'De muren komen op me af! 🏠', body_nl = 'Ik heb echt weinig ruimte, mama. Als ik mijn been strek, raak ik je ribben... Heb ik je pijn gedaan? Dan geef ik er een kusje op! 💋', title_pl = 'Ściany na mnie napierają! 🏠', body_pl = 'Mam już naprawdę ciasno, Mamo. Prostuję nóżkę i trafiam w twoje żebro... Jeśli zabolało, pocałuję i przejdzie? 💋', title_pt = 'As paredes estão a apertar-me! 🏠', body_pt = 'O meu espaço está mesmo apertado, Mamã. Estico a perna e bato nas suas costelas... Se a magoei, dou-lhe um beijinho para passar? 💋', title_sv = 'Väggarna kryper närmare! 🏠', body_sv = 'Det har blivit riktigt trångt, mamma. Jag sträcker ut benet och det träffar ditt revben... Om det gjorde ont, får jag pussa så det går över? 💋', title_vi = 'Tường đang ép sát con! 🏠', body_vi = 'Chỗ con chật lắm rồi, mẹ ơi. Con duỗi chân là chạm vào xương sườn của mẹ... Nếu làm mẹ đau, con thơm một cái là hết nhé? 💋', title_zh = '墙壁朝我挤过来啦！🏠', body_zh = '妈妈，我的空间太挤了。我一伸腿就碰到你的肋骨……要是弄疼你了，亲一亲就好了吧？💋' WHERE id = '8a02111b-8b8b-4912-a2f8-2e33ed9f29ac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Has planchado mi ropa? 👗', body_es = 'Ya me llega su olor. ¡Sé que estás deseando verme con esa ropita! 🥰', title_fr = 'Avez-vous repassé mes vêtements ? 👗', body_fr = 'Je sens déjà leur odeur. Je sais que vous avez hâte de me voir dedans ! 🥰', title_hi = 'मेरे कपड़े इस्त्री कर दिए? 👗', body_hi = 'उनकी खुशबू अभी से मुझ तक आ रही है। मुझे उन कपड़ों में देखने के लिए आप बेताब हैं, मुझे पता है! 🥰', title_id = 'Baju-bajuku sudah disetrika? 👗', body_id = 'Aromanya sudah tercium olehku sekarang. Aku tahu Anda tidak sabar melihatku memakainya! 🥰', title_ja = 'わたしのお洋服、アイロンかけた？👗', body_ja = 'もうにおいが届いてくるよ。あのお洋服を着たわたしを見るのが待ちきれないでしょ、知ってるよ！🥰', title_ko = '제 옷 다림질하셨어요? 👗', body_ko = '벌써 그 옷 냄새가 나는 것 같아요. 그 옷을 입은 저를 빨리 보고 싶으시죠, 알아요! 🥰', title_nl = 'Heb je mijn kleertjes gestreken? 👗', body_nl = 'Ik ruik ze nu al. Ik weet dat je niet kunt wachten om me erin te zien! 🥰', title_pl = 'Wyprasowałaś moje ubranka? 👗', body_pl = 'Już czuję ich zapach. Wiem, że nie możesz się doczekać, aż mnie w nich zobaczysz! 🥰', title_pt = 'Já passou a ferro as minhas roupinhas? 👗', body_pt = 'Já lhes sinto o cheiro. Sei que está ansiosa por me ver com elas vestidas! 🥰', title_sv = 'Har du strukit mina kläder? 👗', body_sv = 'Jag känner redan doften av dem. Jag vet att du längtar efter att se mig i de där kläderna! 🥰', title_vi = 'Mẹ đã là quần áo cho con chưa? 👗', body_vi = 'Con đã ngửi thấy mùi của chúng từ bây giờ. Con biết mẹ nóng lòng được thấy con mặc những bộ đồ ấy! 🥰', title_zh = '我的小衣服熨好了吗？👗', body_zh = '我现在就能闻到它们的味道了。我知道你迫不及待想看我穿上它们！🥰' WHERE id = 'd8af3bb6-0839-43e8-86c1-22d12e84c887' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Estoy revisando el camino! 🔦', body_es = 'Tengo la cabeza hacia abajo, mirando la puerta de salida. Tú solo respira hondo, ¡todo saldrá genial!', title_fr = 'J''inspecte le chemin ! 🔦', body_fr = 'J''ai la tête en bas, je regarde vers la sortie. Respirez simplement profondément, tout va très bien se passer !', title_hi = 'मैं रास्ता जाँच रहा हूँ! 🔦', body_hi = 'मेरा सिर नीचे है, मैं बाहर निकलने के दरवाज़े की ओर देख रहा हूँ। आप बस गहरी साँस लीजिए, सब बढ़िया होगा!', title_id = 'Aku memeriksa jalan! 🔦', body_id = 'Kepalaku di bawah, aku menghadap pintu keluar. Anda cukup tarik napas dalam-dalam, semuanya akan berjalan lancar!', title_ja = '道を確認中！🔦', body_ja = '頭を下にして、出口のほうを見ているよ。ママは深呼吸するだけでいいの、すべてうまくいくよ！', title_ko = '길을 살펴보고 있어요! 🔦', body_ko = '머리를 아래로 두고 출구를 보고 있어요. 엄마는 깊게 숨만 쉬세요, 다 잘될 거예요!', title_nl = 'Ik verken de weg! 🔦', body_nl = 'Mijn hoofd ligt naar beneden en ik kijk naar de uitgang. Haal jij maar diep adem, alles komt goed!', title_pl = 'Sprawdzam drogę! 🔦', body_pl = 'Moja główka jest na dole, patrzę w stronę wyjścia. Ty tylko oddychaj głęboko, wszystko będzie świetnie!', title_pt = 'Estou a verificar o caminho! 🔦', body_pt = 'Tenho a cabeça para baixo, a olhar para a porta de saída. Respire fundo, vai correr tudo muito bem!', title_sv = 'Jag kollar vägen! 🔦', body_sv = 'Mitt huvud är nedåt och jag tittar mot utgången. Andas bara djupt, allt kommer att gå jättebra!', title_vi = 'Con đang kiểm tra đường đi! 🔦', body_vi = 'Đầu con hướng xuống, con đang nhìn về phía cửa ra. Mẹ chỉ cần hít thở sâu, mọi thứ sẽ ổn thôi!', title_zh = '我在探路！🔦', body_zh = '我头朝下，正望着出口。你只要深呼吸，一切都会很好！' WHERE id = '2c4aee4a-e8a9-4bb3-96b6-16fd76a9994b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿De quién es esa mano tan calentita? 🖐️', body_es = '¿Es papá? Cuando noto su caricia, me calmo. Dile que yo también he puesto la mano, ¡choca esos cinco! ✋', title_fr = 'À qui est cette main toute chaude ? 🖐️', body_fr = 'C''est Papa ? Quand je sens son toucher, je me calme. Dites-lui que j''ai posé ma main aussi, tope là ! ✋', title_hi = 'यह किसका गर्म हाथ है? 🖐️', body_hi = 'पापा हैं? उनका स्पर्श महसूस करके मैं शांत हो जाता हूँ। उनसे कहिए, मैंने भी हाथ रखा है, हाई-फ़ाइव! ✋', title_id = 'Tangan hangat siapa itu? 🖐️', body_id = 'Ayahkah? Saat merasakan sentuhannya, aku jadi tenang. Katakan padanya aku juga menempelkan tanganku, tos! ✋', title_ja = 'この温かい手は誰の？🖐️', body_ja = 'パパかな？パパに触れられると、落ち着くの。わたしも手を当てたよって伝えて、ハイタッチしよう！✋', title_ko = '이 따뜻한 손은 누구 손이에요? 🖐️', body_ko = '아빠예요? 아빠 손길을 느끼면 마음이 편해져요. 저도 손을 댔다고 전해 주세요, 하이파이브해요! ✋', title_nl = 'Van wie is die warme hand? 🖐️', body_nl = 'Is dat papa? Als ik zijn aanraking voel, word ik rustig. Zeg hem dat ik mijn hand er ook tegen leg, geef me de vijf! ✋', title_pl = 'Czyja to ciepła dłoń? 🖐️', body_pl = 'To tata? Gdy czuję jego dotyk, uspokajam się. Powiedz mu, że ja też przykładam rączkę, przybijmy piątkę! ✋', title_pt = 'De quem é esta mão quentinha? 🖐️', body_pt = 'É o pai? Quando sinto o toque dele, acalmo-me. Diga-lhe que também pus a minha mão, vamos bater cinco! ✋', title_sv = 'Vems varma hand är det? 🖐️', body_sv = 'Är det pappa? När jag känner hans beröring blir jag lugn. Säg till honom att jag också har lagt min hand där, vi gör high five! ✋', title_vi = 'Bàn tay ấm áp của ai đây? 🖐️', body_vi = 'Là bố phải không? Khi cảm nhận cái chạm của bố, con thấy bình yên. Mẹ nói với bố là con cũng đặt tay lên rồi, đập tay nào! ✋', title_zh = '这是谁温暖的手？🖐️', body_zh = '是爸爸吗？感觉到他的抚摸，我就平静下来。告诉他，我也把手放上来了，击个掌吧！✋' WHERE id = '1f094983-199a-44c0-ba29-5474fcd1ba0b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Tengo los ojos como platos! 👀', body_es = 'Aunque está oscuro, lo observo todo. ¿Me pareceré a ti o a papá? ¿Habéis apostado? 😄', title_fr = 'J''ai les yeux grands ouverts ! 👀', body_fr = 'Même s''il fait noir, j''observe tout. Je me demande si je vous ressemble ou si je ressemble à Papa ? Vous avez parié ? 😄', title_hi = 'मेरी आँखें खुली हैं! 👀', body_hi = 'अँधेरा है, फिर भी मैं सब देख रहा हूँ। पता नहीं मैं आप जैसा दिखूँगा या पापा जैसा? आप दोनों ने शर्त लगाई है? 😄', title_id = 'Mataku terbuka lebar! 👀', body_id = 'Meski gelap, aku mengamati semuanya. Aku mirip Anda atau Ayah, ya? Sudah taruhan? 😄', title_ja = '目をぱっちり開けてるよ！👀', body_ja = '暗いけど、ぜんぶ見てるよ。ママに似てるかな、それともパパ？2人で賭けをした？😄', title_ko = '눈을 크게 떴어요! 👀', body_ko = '깜깜하지만 다 지켜보고 있어요. 제가 엄마를 닮았을까요, 아빠를 닮았을까요? 내기하셨어요? 😄', title_nl = 'Ik heb mijn ogen wijd open! 👀', body_nl = 'Ook al is het donker, ik volg alles. Zou ik op jou lijken of op papa? Hebben jullie al gewed? 😄', title_pl = 'Mam szeroko otwarte oczy! 👀', body_pl = 'Choć jest ciemno, wszystko obserwuję. Ciekawe, czy jestem podobne do ciebie, czy do taty? Założyliście się? 😄', title_pt = 'Tenho os olhos bem abertos! 👀', body_pt = 'Apesar de estar escuro, observo tudo. Será que me pareço consigo ou com o pai? Já fizeram apostas? 😄', title_sv = 'Jag spärrar upp ögonen! 👀', body_sv = 'Även om det är mörkt följer jag allt. Undrar om jag liknar dig eller pappa? Har ni slagit vad? 😄', title_vi = 'Con mở to mắt rồi! 👀', body_vi = 'Dù tối, con vẫn quan sát mọi thứ. Không biết con giống mẹ hay giống bố nhỉ? Bố mẹ đã cá cược chưa? 😄', title_zh = '我把眼睛睁得大大的！👀', body_zh = '虽然很暗，我在观察一切。我会像你还是像爸爸呢？你们打赌了吗？😄' WHERE id = '586cf1f5-c7b6-4014-aa9e-8da51416de7e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Shhh... ¡Estoy durmiendo! 😴', body_es = 'Mi cerebro se desarrolla tan rápido que necesito dormir mucho. ¿Te unes, mamá? 🛌', title_fr = 'Chut... Je dors ! 😴', body_fr = 'Mon cerveau se développe si vite que j''ai besoin de beaucoup dormir. Vous me rejoignez, Maman ? 🛌', title_hi = 'श्श्श... मैं सो रहा हूँ! 😴', body_hi = 'मेरा दिमाग इतनी तेज़ी से विकसित हो रहा है कि मुझे बहुत नींद चाहिए। आप भी मेरे साथ सोएँगी, माँ? 🛌', title_id = 'Ssst... Aku sedang tidur! 😴', body_id = 'Otakku berkembang begitu cepat sehingga aku butuh banyak tidur. Mau ikut tidur denganku, Bunda? 🛌', title_ja = 'シーッ...ねんね中！😴', body_ja = '脳がとても速く発達しているから、たくさん眠らなきゃいけないの。ママも一緒に寝る？🛌', title_ko = '쉿... 저 자고 있어요! 😴', body_ko = '제 뇌가 아주 빠르게 자라서 잠을 많이 자야 해요. 엄마도 같이 잘래요? 🛌', title_nl = 'Sst... Ik slaap! 😴', body_nl = 'Mijn hersenen ontwikkelen zich zo snel dat ik veel slaap nodig heb. Doe je mee, mama? 🛌', title_pl = 'Ciii... Śpię! 😴', body_pl = 'Mój mózg rozwija się tak szybko, że potrzebuję dużo snu. Dołączysz do mnie, Mamo? 🛌', title_pt = 'Chiu... Estou a dormir! 😴', body_pt = 'O meu cérebro desenvolve-se tão depressa que preciso de dormir muito. Junta-se a mim, Mamã? 🛌', title_sv = 'Schh... Jag sover! 😴', body_sv = 'Min hjärna utvecklas så snabbt att jag behöver mycket sömn. Vilar du med mig, mamma? 🛌', title_vi = 'Suỵt... Con đang ngủ! 😴', body_vi = 'Não con phát triển nhanh đến mức con cần ngủ rất nhiều. Mẹ ngủ cùng con nhé? 🛌', title_zh = '嘘……我在睡觉！😴', body_zh = '我的大脑发育得太快，需要很多睡眠。妈妈，你也一起睡吧？🛌' WHERE id = '450a79a5-c3df-4f37-ba9e-30274759f7a8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Estás cambiando cosas en casa? 🌪️', body_es = 'Quieres limpiarlo todo, ordenar los armarios... ¡Es el instinto de anidación! Pero no te canses, necesito una mamá descansada.', title_fr = 'Vous changez tout à la maison ? 🌪️', body_fr = 'Vous avez envie de tout nettoyer, de ranger les placards... C''est l''instinct de nidification ! Mais ne vous épuisez pas, j''ai besoin d''une maman reposée.', title_hi = 'घर में बदलाव कर रही हैं? 🌪️', body_hi = 'हर जगह साफ़ करने, अलमारियाँ सजाने का मन है... यह घोंसला बनाने की प्रवृत्ति है! पर खुद को थकाइए मत, मुझे आराम की हुई माँ चाहिए।', title_id = 'Sedang menata ulang rumah? 🌪️', body_id = 'Ingin membersihkan semuanya, merapikan lemari... Ini naluri bersarang! Tapi jangan terlalu lelah, aku butuh ibu yang tenang.', title_ja = 'お部屋の模様替え中？🌪️', body_ja = 'あちこち掃除したり、クローゼットを整理したくなったり...これは「巣づくり本能」です！でも無理はしないで、わたしには元気なママが必要なの。', title_ko = '집을 바꾸고 있나요? 🌪️', body_ko = '여기저기 청소하고 옷장을 정리하고 싶나요... 둥지 본능이에요! 그래도 무리하지 마세요, 저는 편안한 엄마가 필요해요.', title_nl = 'Ben je het huis aan het veranderen? 🌪️', body_nl = 'Je wilt alles schoonmaken en de kasten opruimen... Dat is het nestdrang-instinct! Maar put jezelf niet uit, ik heb een uitgeruste mama nodig.', title_pl = 'Robisz zmiany w domu? 🌪️', body_pl = 'Chcesz wszystko sprzątać, układać szafy... To instynkt wicia gniazda! Ale nie przemęczaj się, potrzebuję wypoczętej mamy.', title_pt = 'Está a fazer mudanças em casa? 🌪️', body_pt = 'Apetece-lhe limpar tudo e arrumar os armários... É o instinto de fazer o ninho! Mas não se canse, preciso de uma mãe descansada.', title_sv = 'Ändrar du om hemma? 🌪️', body_sv = 'Du vill städa överallt och ordna i garderoberna... Det är boinstinkten! Men trötta inte ut dig, jag behöver en utvilad mamma.', title_vi = 'Mẹ đang sắp xếp lại nhà cửa? 🌪️', body_vi = 'Mẹ muốn dọn dẹp mọi nơi, sắp xếp lại tủ... Đó là bản năng Làm tổ! Nhưng đừng để mình mệt, con cần một người mẹ thư thái.', title_zh = '在家里大变样？🌪️', body_zh = '想把每个角落都打扫干净、把柜子整理好……这就是筑巢本能！但别累着自己，我需要一个休息好的妈妈。' WHERE id = 'be58ff2d-88eb-4c07-a49c-bb64ed9da351' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Aquí está todo muy apretado! 🏠', body_es = 'Quiero girarme, pero no tengo sitio. Si saco el codo, tu barriga se verá torcida. ¡Te reirás al verla! 😄', title_fr = 'Il y a vraiment peu de place ici ! 🏠', body_fr = 'Je veux me retourner, mais je n''ai pas de place. Si je sors mon coude, votre ventre aura l''air tout de travers. Vous allez rire en le voyant ! 😄', title_hi = 'यहाँ बहुत तंगी है! 🏠', body_hi = 'मैं मुड़ना चाहता हूँ, पर जगह नहीं है। कोहनी बाहर निकालूँ, तो आपका पेट टेढ़ा दिखेगा। देखकर आप हँसेंगी! 😄', title_id = 'Di sini sempit sekali! 🏠', body_id = 'Aku ingin berbalik, tapi tidak ada ruang. Kalau aku menonjolkan siku, perut Anda akan terlihat miring. Anda pasti tertawa melihatnya! 😄', title_ja = 'ここ、ほんとに狭いよ！🏠', body_ja = '向きを変えたいけど、スペースがないの。ひじを突き出すと、ママのお腹がいびつに見えちゃう。見たら笑っちゃうかも！😄', title_ko = '여기 정말 좁아요! 🏠', body_ko = '돌고 싶은데 자리가 없어요. 팔꿈치를 내밀면 엄마 배가 삐뚤어 보일 거예요. 보고 웃으실걸요! 😄', title_nl = 'Het is hier echt krap! 🏠', body_nl = 'Ik wil draaien, maar ik heb geen ruimte. Als ik mijn elleboog uitsteek, ziet je buik er scheef uit. Daar moet je vast om lachen! 😄', title_pl = 'Tu jest naprawdę ciasno! 🏠', body_pl = 'Chcę się obrócić, ale nie mam miejsca. Jeśli wystawię łokieć, twój brzuch będzie wyglądał krzywo. Popatrzysz i się zaśmiejesz! 😄', title_pt = 'Aqui está mesmo apertado! 🏠', body_pt = 'Quero virar-me, mas não tenho espaço. Se espetar o cotovelo, a sua barriga vai ficar torta. Vai olhar e rir-se! 😄', title_sv = 'Här är det riktigt trångt! 🏠', body_sv = 'Jag vill vända mig, men har ingen plats. Om jag sticker ut armbågen ser magen sned ut. Du kommer att skratta när du ser det! 😄', title_vi = 'Trong này chật chội quá! 🏠', body_vi = 'Con muốn xoay người, nhưng không còn chỗ. Nếu con chìa khuỷu tay ra, bụng mẹ sẽ méo đi. Mẹ nhìn rồi bật cười cho xem! 😄', title_zh = '这里太挤啦！🏠', body_zh = '我想翻身，可是没有空间。如果我把胳膊肘顶出去，你的肚子会歪歪的。你看了一定会笑！😄' WHERE id = 'd4a9673c-e78e-49b9-8680-f5a870142dec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Necesito grasas! 🥑', body_es = 'Aguacate, nueces o aceite de oliva... ¡Que esté rellenito depende de ti!', title_fr = 'J''ai besoin de bonnes graisses ! 🥑', body_fr = 'Avocat, noix ou huile d''olive... C''est à vous de me rendre tout potelé !', title_hi = 'मुझे फ़ैट चाहिए! 🥑', body_hi = 'एवोकाडो, अखरोट या ऑलिव ऑयल... मुझे गोल-मटोल बनाना आपके हाथ में है!', title_id = 'Aku butuh lemak! 🥑', body_id = 'Alpukat, kenari, atau minyak zaitun... Membuatku montok ada di tangan Anda!', title_ja = 'いい脂質が必要なの！🥑', body_ja = 'アボカド、クルミ、オリーブオイル...わたしをぷくぷくにするのはママ次第だよ！', title_ko = '저는 지방이 필요해요! 🥑', body_ko = '아보카도, 호두, 올리브유... 저를 통통하게 만드는 건 엄마 손에 달렸어요!', title_nl = 'Ik heb vetten nodig! 🥑', body_nl = 'Avocado, walnoten of olijfolie... Het ligt in jouw handen om mij lekker mollig te maken!', title_pl = 'Potrzebuję tłuszczu! 🥑', body_pl = 'Awokado, orzechy włoskie czy oliwa z oliwek... To od ciebie zależy, czy będę pulchne!', title_pt = 'Preciso de gordura! 🥑', body_pt = 'Abacate, nozes ou azeite... Deixar-me gordinho está nas suas mãos!', title_sv = 'Jag behöver fett! 🥑', body_sv = 'Avokado, valnötter eller olivolja... Det är du som kan göra mig knubbig!', title_vi = 'Con cần chất béo! 🥑', body_vi = 'Bơ, óc chó hay dầu ô liu... Làm con bụ bẫm là nhờ mẹ đấy!', title_zh = '我需要脂肪！🥑', body_zh = '牛油果、核桃或橄榄油……能不能把我养得胖嘟嘟，就看你啦！' WHERE id = 'ad62dd64-4e59-4e08-8d87-d88f11192fd8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Tu corazón es mi nana... 💓', body_es = 'Tengo la cabeza hacia abajo y mi oído está más cerca de tu corazón. Ese ritmo es la única música que me calma.', title_fr = 'Votre cœur est ma berceuse... 💓', body_fr = 'J''ai la tête en bas, mon oreille est plus près de votre cœur. Ce rythme est la seule musique qui m''apaise.', title_hi = 'आपका दिल मेरी लोरी है... 💓', body_hi = 'मेरा सिर नीचे है, मेरे कान आपके दिल के और करीब हैं। यह लय ही वह संगीत है जो मुझे शांत करता है।', title_id = 'Detak jantung Anda adalah nina boboku... 💓', body_id = 'Kepalaku di bawah, telingaku lebih dekat ke jantung Anda. Irama ini satu-satunya musik yang menenangkanku.', title_ja = 'ママの心臓の音はわたしの子守唄... 💓', body_ja = '頭が下にあるから、耳がママの心臓に近いの。このリズムだけが、わたしを落ち着かせてくれる音楽なんだ。', title_ko = '엄마 심장 소리는 제 자장가예요... 💓', body_ko = '머리가 아래로 와서 제 귀가 엄마 심장에 더 가까워졌어요. 이 리듬은 저를 달래 주는 단 하나의 음악이에요.', title_nl = 'Jouw hart is mijn slaapliedje... 💓', body_nl = 'Mijn hoofd ligt naar beneden, mijn oor is dichter bij jouw hart. Dat ritme is de enige muziek die me kalmeert.', title_pl = 'Twoje serce to moja kołysanka... 💓', body_pl = 'Moja główka jest na dole, a ucho bliżej twojego serca. Ten rytm to jedyna muzyka, która mnie uspokaja.', title_pt = 'O seu coração é a minha canção de embalar... 💓', body_pt = 'Tenho a cabeça para baixo e o ouvido mais perto do seu coração. Este ritmo é a única música que me acalma.', title_sv = 'Ditt hjärta är min vaggvisa... 💓', body_sv = 'Mitt huvud är nedåt och mitt öra är närmare ditt hjärta. Den rytmen är den enda musiken som lugnar mig.', title_vi = 'Nhịp tim mẹ là lời ru của con... 💓', body_vi = 'Đầu con hướng xuống, tai con gần tim mẹ hơn. Nhịp điệu này là bản nhạc duy nhất giúp con bình yên.', title_zh = '你的心跳是我的摇篮曲……💓', body_zh = '我头朝下，耳朵离你的心更近了。这个节奏是唯一能让我平静的音乐。' WHERE id = '7ab48424-114b-4f93-bf60-a6a791cf5a3b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Está lista mi habitación? 🧸', body_es = '¿Miras mi cuna y te pones a soñar? ¡Estoy deseando abrazar el juguete que has dejado ahí! 🥰', title_fr = 'Ma chambre est prête ? 🧸', body_fr = 'Vous regardez mon berceau en rêvassant ? J''ai hâte de câliner la peluche que vous y avez mise ! 🥰', title_hi = 'मेरा कमरा तैयार है? 🧸', body_hi = 'मेरे पालने को देखकर सपनों में खो जाती हैं? वहाँ रखे खिलौने को गले लगाने के लिए मैं बेताब हूँ! 🥰', title_id = 'Kamarku sudah siap? 🧸', body_id = 'Anda memandangi tempat tidurku sambil melamun? Aku tidak sabar memeluk mainan yang Anda letakkan di sana! 🥰', title_ja = 'わたしのお部屋は準備できた？🧸', body_ja = 'ベビーベッドを見ながら夢をふくらませてる？そこに置いてくれたおもちゃを抱きしめるのが待ちきれないよ！🥰', title_ko = '제 방은 준비됐어요? 🧸', body_ko = '제 아기 침대를 보며 꿈에 빠지시나요? 거기 놓아 둔 인형을 안을 날이 너무 기다려져요! 🥰', title_nl = 'Is mijn kamer klaar? 🧸', body_nl = 'Kijk je naar mijn wiegje en droom je weg? Ik kan niet wachten om het knuffeltje te knuffelen dat je erin hebt gelegd! 🥰', title_pl = 'Mój pokój jest gotowy? 🧸', body_pl = 'Patrzysz na moje łóżeczko i odpływasz w marzeniach? Nie mogę się doczekać, aż przytulę zabawkę, którą tam położyłaś! 🥰', title_pt = 'O meu quarto está pronto? 🧸', body_pt = 'Olha para o meu berço e perde-se em sonhos? Estou ansioso por abraçar o brinquedo que lá pôs! 🥰', title_sv = 'Är mitt rum klart? 🧸', body_sv = 'Tittar du på min säng och drömmer dig bort? Jag längtar efter att krama leksaken du har lagt där! 🥰', title_vi = 'Phòng của con xong chưa? 🧸', body_vi = 'Mẹ có nhìn chiếc nôi của con và mơ mộng không? Con nóng lòng được ôm món đồ chơi mẹ đặt ở đó! 🥰', title_zh = '我的房间准备好了吗？🧸', body_zh = '看着我的小床发呆吗？我迫不及待想抱住你放在那里的玩具！🥰' WHERE id = '1eaf3d66-fce7-4349-aeaf-3af62fb5c512' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Estoy bajando, ¿lo notas? ⬇️', body_es = 'Me estoy colocando entre los huesos de tu pelvis. Ahora respirarás mejor, ¡pero irás al baño más a menudo! 🤭', title_fr = 'Je descends, vous le sentez ? ⬇️', body_fr = 'Je m''installe dans votre bassin. Vous respirerez mieux, mais vous courrez plus souvent aux toilettes ! 🤭', title_hi = 'मैं नीचे उतर रहा हूँ, महसूस हुआ? ⬇️', body_hi = 'मैं आपकी श्रोणि की हड्डियों के बीच बैठ रहा हूँ। अब आप आराम से साँस ले सकेंगी, पर टॉयलेट जल्दी-जल्दी भागना पड़ेगा! 🤭', title_id = 'Aku turun, terasa? ⬇️', body_id = 'Aku menempatkan diri di antara tulang panggul Anda. Sekarang Anda akan bernapas lebih lega, tapi akan lebih sering ke toilet! 🤭', title_ja = '下に降りてきたよ、感じる？⬇️', body_ja = '骨盤の間におさまってきているの。これで息は楽になるけど、トイレはもっと近くなっちゃうよ！🤭', title_ko = '아래로 내려가고 있어요, 느껴지세요? ⬇️', body_ko = '골반 사이에 자리 잡고 있어요. 이제 숨쉬기는 편해지지만 화장실은 더 자주 가게 될 거예요! 🤭', title_nl = 'Ik zak naar beneden, voel je het? ⬇️', body_nl = 'Ik nestel me tussen je bekkenbotten. Je kunt nu makkelijker ademen, maar je moet wel vaker naar de wc! 🤭', title_pl = 'Schodzę niżej, czujesz? ⬇️', body_pl = 'Układam się między kośćmi miednicy. Teraz będzie ci się łatwiej oddychać, ale częściej będziesz biegać do toalety! 🤭', title_pt = 'Estou a descer, sente? ⬇️', body_pt = 'Estou a instalar-me entre os ossos da bacia. Agora vai respirar melhor, mas vai correr mais vezes à casa de banho! 🤭', title_sv = 'Jag sjunker nedåt, känner du det? ⬇️', body_sv = 'Jag lägger mig tillrätta mellan dina bäckenben. Nu kan du andas lättare, men du kommer att springa på toaletten oftare! 🤭', title_vi = 'Con đang xuống thấp, mẹ có cảm thấy không? ⬇️', body_vi = 'Con đang nằm gọn giữa xương chậu của mẹ. Giờ mẹ sẽ thở dễ hơn, nhưng sẽ phải chạy vào nhà vệ sinh thường xuyên hơn! 🤭', title_zh = '我在往下降，感觉到了吗？⬇️', body_zh = '我正在骨盆里安顿下来。现在你呼吸会更顺畅，但会更频繁地跑厕所！🤭' WHERE id = '23ae0c73-2d4e-42be-98d5-a256a7fc152c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Mis defensas se fortalecen 🛡️', body_es = 'Los anticuerpos que me pasas me preparan para el mundo de los microbios. ¡Tu leche también me protegerá, mamá!', title_fr = 'Mon immunité se renforce 🛡️', body_fr = 'Les anticorps que vous me transmettez me préparent au monde des microbes. Votre lait me protégera aussi, Maman !', title_hi = 'मेरी इम्युनिटी मज़बूत हो रही है 🛡️', body_hi = 'आपसे मुझे मिलने वाली एंटीबॉडी मुझे कीटाणुओं की दुनिया के लिए तैयार करती हैं। आपका दूध भी मेरी रक्षा करेगा, माँ!', title_id = 'Kekebalanku makin kuat 🛡️', body_id = 'Antibodi dari Anda mempersiapkanku menghadapi dunia kuman. ASI Anda juga akan melindungiku, Bunda!', title_ja = '免疫が強くなってきたよ 🛡️', body_ja = 'ママから届く抗体が、ばい菌の世界に向けてわたしを準備してくれているの。ママのおっぱいもわたしを守ってくれるよ、ママ！', title_ko = '제 면역력이 강해지고 있어요 🛡️', body_ko = '엄마에게서 받은 항체가 저를 세균의 세상에 대비시켜 줘요. 엄마 젖도 저를 지켜 줄 거예요, 엄마!', title_nl = 'Mijn afweer wordt sterker 🛡️', body_nl = 'De antistoffen die ik van jou krijg, bereiden me voor op de wereld vol bacteriën. Jouw melk gaat me ook beschermen, mama!', title_pl = 'Moja odporność rośnie 🛡️', body_pl = 'Przeciwciała, które dostaję od ciebie, przygotowują mnie na świat mikrobów. Twoje mleko też będzie mnie chronić, Mamo!', title_pt = 'A minha imunidade está a ficar mais forte 🛡️', body_pt = 'Os anticorpos que recebo de si preparam-me para o mundo dos micróbios. O seu leite também me vai proteger, Mamã!', title_sv = 'Mitt immunförsvar blir starkare 🛡️', body_sv = 'Antikropparna som går över från dig förbereder mig för bakteriernas värld. Din mjölk kommer också att skydda mig, mamma!', title_vi = 'Miễn dịch của con đang mạnh lên 🛡️', body_vi = 'Kháng thể truyền từ mẹ sang chuẩn bị cho con bước vào thế giới vi khuẩn. Sữa mẹ cũng sẽ bảo vệ con, mẹ ơi!', title_zh = '我的免疫力在增强 🛡️', body_zh = '从你身上传来的抗体，正帮我准备迎接充满细菌的世界。妈妈，你的乳汁也会保护我！' WHERE id = '10bb8281-56bc-44a1-b78e-8cb23edb7f86' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Dónde está mi primera ropita? 👕', body_es = '¿Has preparado la bolsa del hospital? Acaricia ese pequeño pelele que me vas a poner...', title_fr = 'Où est ma première tenue ? 👕', body_fr = 'Avez-vous préparé la valise de maternité ? Caressez ce petit body que vous me mettrez...', title_hi = 'मेरे पहले कपड़े कहाँ हैं? 👕', body_hi = 'हॉस्पिटल बैग तैयार किया? वह छोटा सा रोम्पर सहलाइए, जो आप मुझे पहनाएँगी...', title_id = 'Di mana baju pertamaku? 👕', body_id = 'Sudah mengemas tas rumah sakit? Elus baju terusan mungil yang akan Anda pakaikan padaku...', title_ja = 'わたしの最初のお洋服はどこ？👕', body_ja = '入院バッグの準備はできた？わたしに着せてくれる小さなロンパースを、そっとなでてみて...', title_ko = '제 첫 옷은 어디 있어요? 👕', body_ko = '출산 가방은 싸셨어요? 저에게 입힐 그 작은 우주복을 쓰다듬어 보세요...', title_nl = 'Waar is mijn eerste pakje? 👕', body_nl = 'Heb je de ziekenhuistas ingepakt? Aai eens over dat kleine rompertje dat je me gaat aantrekken...', title_pl = 'Gdzie moje pierwsze ubranko? 👕', body_pl = 'Spakowałaś torbę do szpitala? Pogłaszcz ten malutki pajacyk, w który mnie ubierzesz...', title_pt = 'Onde está a minha primeira roupinha? 👕', body_pt = 'Já preparou a mala da maternidade? Faça uma festa àquele babygrow pequenino que me vai vestir...', title_sv = 'Var är mina första kläder? 👕', body_sv = 'Har du packat BB-väskan? Stryk med handen över den lilla sparkdräkten du ska klä mig i...', title_vi = 'Bộ đồ đầu tiên của con đâu rồi? 👕', body_vi = 'Mẹ đã chuẩn bị túi đồ đi sinh chưa? Hãy vuốt ve bộ áo liền quần bé xíu mẹ sẽ mặc cho con...', title_zh = '我的第一件衣服在哪儿？👕', body_zh = '待产包收拾好了吗？摸摸那件你要给我穿的小连体衣吧……' WHERE id = '2e44c870-ae65-48e2-ad71-57a350b34616' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Quiero verte! 👀', body_es = 'Tengo los ojos abiertos, pero aquí está oscuro. Cuento los días para ver tu cara y tu sonrisa. ¡Queda poco! ⏳', title_fr = 'Je veux vous voir ! 👀', body_fr = 'Mes yeux sont ouverts, mais il fait noir ici. Je compte les jours avant de voir votre visage et votre sourire. Plus très longtemps ! ⏳', title_hi = 'मैं आपको देखना चाहता हूँ! 👀', body_hi = 'मेरी आँखें खुली हैं, पर यहाँ अँधेरा है। आपका चेहरा, आपकी मुस्कान देखने के लिए दिन गिन रहा हूँ। थोड़ा ही बाकी है! ⏳', title_id = 'Aku ingin melihat Anda! 👀', body_id = 'Mataku terbuka, tapi di sini gelap. Aku menghitung hari untuk melihat wajah dan senyum Anda. Sebentar lagi! ⏳', title_ja = 'ママに会いたい！👀', body_ja = '目は開いているけど、ここは真っ暗。ママの顔や笑顔を見られる日を指折り数えているよ。あと少し！⏳', title_ko = '엄마를 보고 싶어요! 👀', body_ko = '제 눈은 떠 있지만 여기는 깜깜해요. 엄마 얼굴과 미소를 볼 날을 손꼽아 기다려요. 얼마 안 남았어요! ⏳', title_nl = 'Ik wil je zien! 👀', body_nl = 'Mijn ogen zijn open, maar het is donker hier. Ik tel de dagen tot ik je gezicht en je lach zie. Nog even! ⏳', title_pl = 'Chcę cię zobaczyć! 👀', body_pl = 'Mam otwarte oczy, ale tu jest ciemno. Liczę dni, by zobaczyć twoją twarz i uśmiech. Już niedługo! ⏳', title_pt = 'Quero vê-la! 👀', body_pt = 'Tenho os olhos abertos, mas aqui está escuro. Conto os dias para ver o seu rosto e o seu sorriso. Falta pouco! ⏳', title_sv = 'Jag vill se dig! 👀', body_sv = 'Mina ögon är öppna, men här är det mörkt. Jag räknar dagarna tills jag får se ditt ansikte och ditt leende. Snart! ⏳', title_vi = 'Con muốn được nhìn thấy mẹ! 👀', body_vi = 'Mắt con mở, nhưng trong này tối lắm. Con đếm từng ngày để được thấy gương mặt và nụ cười của mẹ. Sắp rồi! ⏳', title_zh = '我想见到你！👀', body_zh = '我的眼睛睁着，但这里很暗。我在数着日子，等着看你的脸和笑容。快了！⏳' WHERE id = 'deba1190-6096-4dec-88eb-70e669fb3ccb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Mi piel se alisa! 🧖‍♀️', body_es = 'Se me cae el vello y aumenta mi capa de grasa. Me preparo para tus caricias, mamá. ¡Voy a ser suavecito! ☁️', title_fr = 'Ma peau devient toute douce ! 🧖‍♀️', body_fr = 'Mon duvet tombe, ma couche de graisse augmente. Je me prépare à vos caresses, Maman. Je serai tout doux ! ☁️', title_hi = 'मेरी त्वचा चिकनी हो रही है! 🧖‍♀️', body_hi = 'मेरे रोएँ झड़ रहे हैं, चर्बी की परत बढ़ रही है। मैं आपके कोमल स्पर्श की तैयारी कर रहा हूँ, माँ। मैं बहुत मुलायम बनूँगा! ☁️', title_id = 'Kulitku makin halus! 🧖‍♀️', body_id = 'Bulu-bulu halusku rontok, lapisan lemakku bertambah. Aku bersiap untuk sentuhan lembut Anda, Bunda. Aku akan sangat lembut! ☁️', title_ja = '肌がすべすべになってきたよ！🧖‍♀️', body_ja = 'うぶ毛が抜けて、脂肪がついてきているの。ママのやさしいタッチに向けて準備中だよ、ママ。ふわふわになるからね！☁️', title_ko = '제 피부가 매끈해지고 있어요! 🧖‍♀️', body_ko = '솜털은 빠지고 지방층은 늘고 있어요. 엄마의 부드러운 손길을 맞을 준비 중이에요, 엄마. 저 말랑말랑할 거예요! ☁️', title_nl = 'Mijn huid wordt gladder! 🧖‍♀️', body_nl = 'Mijn donshaartjes vallen uit en mijn vetlaagje groeit. Ik maak me klaar voor jouw zachte aanraking, mama. Ik word heel zacht! ☁️', title_pl = 'Moja skóra się wygładza! 🧖‍♀️', body_pl = 'Meszek mi wypada, tłuszczyku przybywa. Przygotowuję się na twój delikatny dotyk, Mamo. Będę mięciutkie! ☁️', title_pt = 'A minha pele está a ficar lisinha! 🧖‍♀️', body_pt = 'Os meus pelinhos estão a cair e a camada de gordura aumenta. Estou a preparar-me para o seu toque delicado, Mamã. Vou ser fofinho! ☁️', title_sv = 'Min hud blir slätare! 🧖‍♀️', body_sv = 'Mitt fjun faller av och fettlagret växer. Jag förbereder mig för din ömma beröring, mamma. Jag kommer att vara mjuk! ☁️', title_vi = 'Da con mịn màng hơn rồi! 🧖‍♀️', body_vi = 'Lông tơ của con đang rụng, lớp mỡ dày lên. Con đang chuẩn bị cho cái chạm dịu dàng của mẹ. Con sẽ mềm mại lắm! ☁️', title_zh = '我的皮肤越来越光滑！🧖‍♀️', body_zh = '我的胎毛在脱落，脂肪层在增加。妈妈，我在为你温柔的抚摸做准备。我会软软的！☁️' WHERE id = 'eff2a55b-f3e4-4d2a-b53a-483716c9d978' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Estoy cogiendo fuerzas! ⚡', body_es = '¿No me muevo mucho? Tranquila. Ahora necesito dormir. Estoy acumulando energía para el gran día. ¡Descansa tú también! 🛌', title_fr = 'Je rassemble mes forces ! ⚡', body_fr = 'Je ne bouge pas beaucoup ? Pas d''inquiétude. J''ai besoin de sommeil maintenant. Je fais le plein d''énergie pour le grand jour. Reposez-vous aussi ! 🛌', title_hi = 'मैं ताकत जुटा रहा हूँ! ⚡', body_hi = 'मैं ज़्यादा हिल नहीं रहा? घबराइए मत। अब मुझे नींद चाहिए। बड़े दिन के लिए ऊर्जा जमा कर रहा हूँ। आप भी आराम कीजिए! 🛌', title_id = 'Aku sedang mengumpulkan tenaga! ⚡', body_id = 'Aku jarang bergerak? Jangan takut. Sekarang aku butuh tidur. Aku mengumpulkan energi untuk hari besar. Anda juga istirahat ya! 🛌', title_ja = '力をためているよ！⚡', body_ja = 'あまり動かない？心配しないで。今は睡眠が必要なの。大切な日のためにエネルギーをためているよ。ママも休んでね！🛌', title_ko = '힘을 모으고 있어요! ⚡', body_ko = '제가 많이 안 움직이나요? 걱정 마세요. 지금은 잠이 필요해요. 큰날을 위해 에너지를 모으는 중이에요. 엄마도 쉬세요! 🛌', title_nl = 'Ik verzamel kracht! ⚡', body_nl = 'Beweeg ik niet zo veel? Geen zorgen. Ik heb nu slaap nodig. Ik spaar energie voor de grote dag. Rust jij ook! 🛌', title_pl = 'Zbieram siły! ⚡', body_pl = 'Mało się ruszam? Nie bój się. Teraz potrzebuję snu. Zbieram energię na wielki dzień. Ty też odpocznij! 🛌', title_pt = 'Estou a ganhar forças! ⚡', body_pt = 'Não me mexo muito? Não se assuste. Agora preciso de dormir. Estou a juntar energia para o grande dia. Descanse também! 🛌', title_sv = 'Jag samlar kraft! ⚡', body_sv = 'Rör jag mig inte så mycket? Var inte rädd. Nu behöver jag sömn. Jag samlar energi inför den stora dagen. Vila du också! 🛌', title_vi = 'Con đang tích lũy sức mạnh! ⚡', body_vi = 'Con không cử động nhiều à? Đừng lo. Giờ con cần ngủ. Con đang tích năng lượng cho ngày trọng đại. Mẹ cũng nghỉ ngơi nhé! 🛌', title_zh = '我在积蓄力量！⚡', body_zh = '我动得不多？别怕。现在我需要睡觉，在为那个重要的日子攒能量。你也休息吧！🛌' WHERE id = 'b4ebdd4a-9196-4b7e-a71f-fdfdc053ec32' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Has notado mi codo? 💪', body_es = '¡Perdona, mamá! Quiero estirarme, pero no tengo sitio. ¿Te ríes de mí cuando tu barriga se ve torcida? 😄', title_fr = 'Vous avez senti mon coude ? 💪', body_fr = 'Pardon, Maman ! Je veux m''étirer, mais je n''ai pas de place. Vous riez quand votre ventre prend des formes bizarres ? 😄', title_hi = 'मेरी कोहनी महसूस हुई? 💪', body_hi = 'माफ़ करना, माँ! अंगड़ाई लेना चाहता हूँ, पर जगह नहीं है। पेट टेढ़ा-मेढ़ा दिखता है तो मुझ पर हँसती हैं? 😄', title_id = 'Terasa sikuku? 💪', body_id = 'Maaf, Bunda! Aku ingin menggeliat, tapi tidak ada ruang. Apakah Anda menertawakanku saat perut Anda terlihat mencong? 😄', title_ja = 'ひじを感じた？💪', body_ja = 'ごめんね、ママ！伸びをしたいけど、スペースがないの。お腹がでこぼこになると、わたしを見て笑っちゃう？😄', title_ko = '제 팔꿈치 느끼셨어요? 💪', body_ko = '미안해요, 엄마! 기지개를 켜고 싶은데 자리가 없어요. 배가 울퉁불퉁해 보일 때 저 보고 웃으시죠? 😄', title_nl = 'Voelde je mijn elleboog? 💪', body_nl = 'Sorry, mama! Ik wil me uitrekken, maar ik heb geen ruimte. Moet je lachen als je buik er scheef uitziet? 😄', title_pl = 'Poczułaś mój łokieć? 💪', body_pl = 'Przepraszam, Mamo! Chcę się przeciągnąć, ale nie mam miejsca. Śmiejesz się ze mnie, gdy brzuch wygląda krzywo? 😄', title_pt = 'Sentiu o meu cotovelo? 💪', body_pt = 'Desculpe, Mamã! Quero espreguiçar-me, mas não tenho espaço. Ri-se de mim quando a barriga fica toda torta? 😄', title_sv = 'Kände du min armbåge? 💪', body_sv = 'Förlåt, mamma! Jag vill sträcka på mig, men har ingen plats. Skrattar du åt mig när magen ser knölig ut? 😄', title_vi = 'Mẹ có cảm thấy khuỷu tay con không? 💪', body_vi = 'Xin lỗi mẹ! Con muốn vươn vai mà chẳng có chỗ. Bụng mẹ méo xệch đi, mẹ có cười con không? 😄', title_zh = '感觉到我的胳膊肘了吗？💪', body_zh = '对不起，妈妈！我想伸个懒腰，可是没有空间。看到肚子歪歪扭扭的，你会笑我吗？😄' WHERE id = '222ef9f4-b496-4bfc-b795-b205f25d7c39' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Caminas como un pingüino? 🤭', body_es = 'Como he bajado, tu forma de andar ha cambiado. ¡Pero de cualquier forma y con cualquier paso, eres la mamá más guapa del mundo! ❤️', title_fr = 'Vous marchez comme un pingouin ? 🤭', body_fr = 'Votre démarche a changé parce que je suis descendu. Mais quelle que soit votre allure, vous êtes la plus belle maman du monde ! ❤️', title_hi = 'पेंगुइन की तरह चल रही हैं? 🤭', body_hi = 'मैं नीचे उतर आया, इसलिए आपकी चाल बदल गई। पर आप हर रूप में, हर चाल में दुनिया की सबसे सुंदर माँ हैं! ❤️', title_id = 'Berjalan seperti penguin? 🤭', body_id = 'Cara jalan Anda berubah karena aku sudah turun. Tapi dalam keadaan apa pun, dengan langkah apa pun, Anda tetap ibu tercantik di dunia! ❤️', title_ja = 'ペンギンみたいに歩いてる？🤭', body_ja = 'わたしが下に降りたから、歩き方が変わったんだね。でもどんな姿でも、どんな歩き方でも、ママは世界一きれいなママだよ！❤️', title_ko = '펭귄처럼 걷고 있나요? 🤭', body_ko = '제가 아래로 내려와서 걸음걸이가 바뀌었어요. 그래도 엄마는 어떤 모습, 어떤 걸음이든 세상에서 가장 예쁜 엄마예요! ❤️', title_nl = 'Loop je als een pinguïn? 🤭', body_nl = 'Omdat ik ben gezakt, loop je anders. Maar hoe je ook bent en hoe je ook loopt, je bent de mooiste mama van de wereld! ❤️', title_pl = 'Chodzisz jak pingwinek? 🤭', body_pl = 'Twój chód się zmienił, bo jestem teraz niżej. Ale w każdej chwili i na każdym kroku jesteś najpiękniejszą mamą na świecie! ❤️', title_pt = 'Anda como um pinguim? 🤭', body_pt = 'O seu andar mudou porque eu desci. Mas, de qualquer forma e a cada passo, é a mãe mais bonita do mundo! ❤️', title_sv = 'Går du som en pingvin? 🤭', body_sv = 'Din gång har ändrats för att jag har sjunkit nedåt. Men hur du än ser ut och hur du än går är du världens vackraste mamma! ❤️', title_vi = 'Mẹ đi lạch bạch như chim cánh cụt? 🤭', body_vi = 'Vì con xuống thấp nên dáng đi của mẹ thay đổi. Nhưng dù thế nào, với mỗi bước đi, mẹ vẫn là người mẹ đẹp nhất thế giới! ❤️', title_zh = '走路像企鹅？🤭', body_zh = '因为我往下降了，你走路的样子变了。但无论怎样、怎么走，你都是世界上最美的妈妈！❤️' WHERE id = '4659f949-94b4-4bda-af43-5053a4d85dd9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Hip... Hip... 😲', body_es = '¡Otra vez tengo hipo! Estoy entrenando mi diafragma. Si tu barriga da saltitos rítmicos, ¡que sepas que soy yo!', title_fr = 'Hic... Hic... 😲', body_fr = 'J''ai encore le hoquet ! J''entraîne mon diaphragme. Si votre ventre sursaute en rythme, c''est moi !', title_hi = 'हिच... हिच... 😲', body_hi = 'फिर से हिचकी आ गई! मैं अपने डायाफ़्राम का अभ्यास कर रहा हूँ। पेट लय में उछले, तो समझिए यह मैं हूँ!', title_id = 'Hik... Hik... 😲', body_id = 'Aku cegukan lagi! Aku sedang melatih diafragmaku. Jika perut Anda melompat-lompat berirama, itu aku!', title_ja = 'ひっく...ひっく... 😲', body_ja = 'またしゃっくりが出ちゃった！横隔膜の練習中なの。お腹がリズミカルにぴくぴくしたら、わたしだと思ってね！', title_ko = '딸꾹... 딸꾹... 😲', body_ko = '또 딸꾹질이에요! 횡격막을 연습하고 있어요. 배가 규칙적으로 들썩이면 저인 줄 아세요!', title_nl = 'Hik... Hik... 😲', body_nl = 'Ik heb weer de hik! Ik train mijn middenrif. Springt je buik ritmisch op en neer, dan weet je dat ik het ben!', title_pl = 'Hik... Hik... 😲', body_pl = 'Znowu mam czkawkę! Ćwiczę przeponę. Jeśli twój brzuch rytmicznie podskakuje, wiedz, że to ja!', title_pt = 'Hic... Hic... 😲', body_pt = 'Soluços outra vez! Estou a treinar o diafragma. Se a barriga dá saltinhos ritmados, já sabe que sou eu!', title_sv = 'Hick... Hick... 😲', body_sv = 'Jag har fått hicka igen! Jag tränar min diafragma. Om magen hoppar rytmiskt vet du att det är jag!', title_vi = 'Hức... Hức... 😲', body_vi = 'Con lại bị nấc rồi! Con đang tập cơ hoành. Nếu bụng mẹ giật nhịp nhàng, mẹ biết đó là con nhé!', title_zh = '嗝……嗝……😲', body_zh = '我又打嗝啦！我在锻炼横膈膜。如果肚子有节奏地跳动，那就是我！' WHERE id = 'fa6077ec-5cef-4d3a-887a-ecb99696e48f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Hemos ido al médico? 👩‍⚕️', body_es = '¡Ese gel frío en la barriga me hace cosquillas! 🙈 Pero sé que oír mis latidos te da tranquilidad.', title_fr = 'On a vu le médecin ? 👩‍⚕️', body_fr = 'Ce gel froid sur le ventre me chatouille ! 🙈 Mais je sais qu''entendre mon cœur battre vous apaise.', title_hi = 'डॉक्टर से मिल आए? 👩‍⚕️', body_hi = 'वह ठंडा जेल मेरे पेट पर लगता है तो गुदगुदी होती है! 🙈 पर मेरी धड़कन सुनकर आपको सुकून मिलता है, मुझे पता है।', title_id = 'Sudah bertemu dokter? 👩‍⚕️', body_id = 'Gel dingin itu membuatku geli saat menyentuh perut! 🙈 Tapi aku tahu, mendengar detak jantungku membuat Anda tenang.', title_ja = 'お医者さんに会った？👩‍⚕️', body_ja = 'あの冷たいジェルがお腹に触れると、くすぐったいの！🙈 でもわたしの心臓の音を聞くと、ママは安心するよね。知ってるよ。', title_ko = '의사 선생님 만났어요? 👩‍⚕️', body_ko = '차가운 젤이 배에 닿으면 간지러워요! 🙈 그래도 제 심장 소리를 들으면 엄마 마음이 편해지는 거 알아요.', title_nl = 'Zijn we bij de dokter geweest? 👩‍⚕️', body_nl = 'Die koude gel op je buik kietelt me! 🙈 Maar ik weet dat mijn hartslag horen je rust geeft.', title_pl = 'Byliśmy u lekarza? 👩‍⚕️', body_pl = 'Gdy ten zimny żel dotyka brzucha, łaskocze mnie! 🙈 Ale wiem, że słuchanie bicia mojego serca daje ci spokój.', title_pt = 'Fomos ao médico? 👩‍⚕️', body_pt = 'Aquele gel frio na barriga faz-me cócegas! 🙈 Mas sei que ouvir o meu coração lhe dá paz.', title_sv = 'Har vi träffat läkaren? 👩‍⚕️', body_sv = 'När den kalla gelen hamnar på magen kittlas det! 🙈 Men jag vet att det ger dig ro att höra mina hjärtslag.', title_vi = 'Mình đã gặp bác sĩ chưa? 👩‍⚕️', body_vi = 'Lớp gel lạnh chạm vào bụng làm con nhột quá! 🙈 Nhưng con biết nghe tiếng tim con đập giúp mẹ yên lòng.', title_zh = '见过医生了吗？👩‍⚕️', body_zh = '那冰凉的耦合剂碰到肚子时，我觉得好痒！🙈 但我知道，听到我的心跳会让你很安心。' WHERE id = 'ac593045-989b-4db2-a1c0-5cf1b85a8800' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Somos un equipo! 🤝', body_es = 'Cuando lleguen las contracciones, no tengas miedo. Respira hondo. ¡Lo conseguiremos juntos, te lo prometo!', title_fr = 'Nous sommes une équipe ! 🤝', body_fr = 'Quand les contractions arriveront, n''ayez pas peur. Respirez profondément. Nous y arriverons ensemble, c''est promis !', title_hi = 'हम एक टीम हैं! 🤝', body_hi = 'जब दर्द शुरू हो, घबराइए मत। गहरी साँस लीजिए। हम मिलकर कर लेंगे, मेरा वादा है!', title_id = 'Kita satu tim! 🤝', body_id = 'Saat kontraksi datang, jangan takut. Tarik napas dalam-dalam. Kita pasti bisa bersama, aku janji!', title_ja = 'わたしたちはチームだよ！🤝', body_ja = '陣痛が来ても怖がらないで。深呼吸してね。一緒に乗り越えられるよ、約束する！', title_ko = '우리는 한 팀이에요! 🤝', body_ko = '진통이 와도 두려워하지 마세요. 깊게 숨을 쉬세요. 우리 함께 해낼 거예요, 약속해요!', title_nl = 'Wij zijn een team! 🤝', body_nl = 'Wees niet bang als de weeën komen. Haal diep adem. Samen gaan we het redden, dat beloof ik!', title_pl = 'Jesteśmy drużyną! 🤝', body_pl = 'Gdy przyjdą skurcze, nie bój się. Oddychaj głęboko. Razem damy radę, obiecuję!', title_pt = 'Somos uma equipa! 🤝', body_pt = 'Quando vierem as contrações, não tenha medo. Respire fundo. Juntos vamos conseguir, prometo!', title_sv = 'Vi är ett lag! 🤝', body_sv = 'Var inte rädd när värkarna kommer. Andas djupt. Vi klarar det tillsammans, jag lovar!', title_vi = 'Chúng mình là một đội! 🤝', body_vi = 'Khi cơn co đến, đừng sợ. Hãy hít thở sâu. Chúng mình sẽ cùng làm được, con hứa đấy!', title_zh = '我们是一个团队！🤝', body_zh = '宫缩来时别害怕。深呼吸。我们一起一定能做到，我保证！' WHERE id = 'f1b0e4ba-30ba-4a1d-82af-0d740c3ae044' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Las bolsas están en la puerta? 🎒', body_es = 'En cualquier momento puedo decir «¡Sorpresa!». ¿Has metido en la bolsa ese primer gorrito que me vas a poner? No quiero pasar frío. 🧢', title_fr = 'Les sacs sont près de la porte ? 🎒', body_fr = 'Je peux vous dire « Surprise ! » à tout moment. Avez-vous mis dans le sac le premier petit bonnet que vous me mettrez ? Je ne veux pas avoir froid. 🧢', title_hi = 'बैग दरवाज़े पर हैं? 🎒', body_hi = 'मैं कभी भी ''सरप्राइज़!'' कह सकता हूँ। जो पहली टोपी आप मुझे पहनाएँगी, वह बैग में रख दी? मुझे ठंड नहीं लगनी चाहिए। 🧢', title_id = 'Tas sudah di dekat pintu? 🎒', body_id = 'Aku bisa bilang Kejutan! kapan saja. Sudah memasukkan topi pertama yang akan Anda pakaikan padaku ke tas? Aku tidak mau kedinginan. 🧢', title_ja = 'バッグは玄関に置いてある？🎒', body_ja = 'いつ「サプライズ！」って言ってもおかしくないよ。わたしにかぶせてくれる最初の帽子、バッグに入れた？寒いのはいやだな。🧢', title_ko = '가방은 문 앞에 있나요? 🎒', body_ko = '언제든 깜짝! 하고 나타날 수 있어요. 저에게 씌울 첫 모자는 가방에 넣으셨어요? 춥고 싶지 않아요. 🧢', title_nl = 'Staan de tassen bij de deur? 🎒', body_nl = 'Ik kan elk moment ‘Verrassing!’ roepen. Heb je dat eerste mutsje dat je me opzet in de tas gedaan? Ik wil het niet koud hebben. 🧢', title_pl = 'Torby stoją przy drzwiach? 🎒', body_pl = 'W każdej chwili mogę powiedzieć: Niespodzianka! Włożyłaś do torby tę pierwszą czapeczkę dla mnie? Nie chcę zmarznąć. 🧢', title_pt = 'As malas estão à porta? 🎒', body_pt = 'A qualquer momento posso dizer "Surpresa!". Já pôs na mala o primeiro gorro que me vai vestir? Não quero ter frio. 🧢', title_sv = 'Står väskorna vid dörren? 🎒', body_sv = 'Jag kan säga ''Överraskning!'' när som helst. Har du lagt ner den första lilla mössan du ska sätta på mig i väskan? Jag vill inte frysa. 🧢', title_vi = 'Túi đồ đã để ở cửa chưa? 🎒', body_vi = 'Bất cứ lúc nào con cũng có thể nói "Bất ngờ chưa!". Mẹ đã cho chiếc mũ đầu tiên của con vào túi chưa? Con không muốn bị lạnh. 🧢', title_zh = '包放在门口了吗？🎒', body_zh = '我随时可能给你一个“惊喜！”。你给我准备的第一顶小帽子放进包里了吗？我可不想着凉。🧢' WHERE id = '8bb10475-6f0a-4fa8-839d-6d4d4f784276' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Queda poco para la meta! 🏆', body_es = '¡Terminan las 37 semanas! Ya estamos a término temprano. ¡Es decir, aunque naciera hoy, mis pulmones están listos para respirar!', title_fr = 'La ligne d''arrivée est proche ! 🏆', body_fr = '37 semaines déjà ! Nous sommes à terme précoce. Même si je naissais aujourd''hui, mes poumons seraient prêts à respirer !', title_hi = 'फ़िनिश लाइन करीब है! 🏆', body_hi = '37 हफ़्ते पूरे हो रहे हैं! हम अर्ली टर्म में हैं। यानी आज भी जन्म लूँ, तो मेरे फेफड़े साँस लेने को तैयार हैं!', title_id = 'Garis finis sudah dekat! 🏆', body_id = '37 minggu hampir selesai! Kita sudah masuk masa Cukup Bulan Awal. Artinya, meski aku lahir hari ini, paru-paruku sudah siap bernapas!', title_ja = 'ゴールまであと少し！🏆', body_ja = '37週が終わるよ！もう「正期産」の時期に入ったの。今日生まれても、わたしの肺は呼吸する準備ができているよ！', title_ko = '결승선이 코앞이에요! 🏆', body_ko = '37주가 끝나가요! 이제 조기 만삭 시기예요. 오늘 태어나더라도 제 폐는 숨 쉴 준비가 됐어요!', title_nl = 'De finish is dichtbij! 🏆', body_nl = '37 weken zijn bijna voorbij! We zijn nu à terme. Ook als ik vandaag geboren word, zijn mijn longen klaar om te ademen!', title_pl = 'Meta już blisko! 🏆', body_pl = 'Kończy się 37. tydzień! Jesteśmy już w okresie wczesnego terminu. Nawet gdybym urodziło się dziś, moje płuca są gotowe do oddychania!', title_pt = 'Falta pouco para a meta! 🏆', body_pt = 'As 37 semanas estão a terminar! Já estamos no termo precoce. Ou seja, mesmo que nascesse hoje, os meus pulmões estão prontos para respirar!', title_sv = 'Snart i mål! 🏆', body_sv = '37 veckor är snart slut! Nu är vi fullgångna. Även om jag föds i dag är mina lungor redo att andas!', title_vi = 'Sắp về đích rồi! 🏆', body_vi = 'Tuần 37 sắp kết thúc! Chúng mình đã vào giai đoạn Đủ tháng sớm. Nghĩa là dù con chào đời hôm nay, phổi con cũng đã sẵn sàng để thở!', title_zh = '终点就在眼前！🏆', body_zh = '37周快满了！我们已经进入早足月期。也就是说，就算我今天出生，我的肺也已经准备好呼吸了！' WHERE id = '884382e7-c971-4251-a601-ff9e5d8d7bc2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'He soñado contigo... 💤', body_es = 'Tu voz, tu olor, tu calor... ¡Estoy deseando despertar y abrazarte de verdad, mamá!', title_fr = 'Je vous ai vue en rêve... 💤', body_fr = 'Votre voix, votre odeur, votre chaleur... J''ai hâte de me réveiller et de vous serrer pour de vrai, Maman !', title_hi = 'मैंने सपने में आपको देखा... 💤', body_hi = 'आपकी आवाज़, आपकी खुशबू, आपकी गर्माहट... जागकर सच में आपको गले लगाने के लिए बेताब हूँ, माँ!', title_id = 'Aku memimpikan Anda... 💤', body_id = 'Suara Anda, aroma Anda, kehangatan Anda... Aku tidak sabar untuk bangun dan benar-benar memeluk Anda, Bunda!', title_ja = '夢でママに会ったよ... 💤', body_ja = 'ママの声、におい、ぬくもり...目を覚まして、本当にママに抱きしめてもらえる日が待ちきれないよ、ママ！', title_ko = '꿈에서 엄마를 봤어요... 💤', body_ko = '엄마의 목소리, 냄새, 따스함... 깨어나서 진짜로 엄마를 안고 싶어요, 엄마!', title_nl = 'Ik zag je in mijn droom... 💤', body_nl = 'Je stem, je geur, je warmte... Ik kan niet wachten om wakker te worden en je echt te knuffelen, mama!', title_pl = 'Śniłaś mi się... 💤', body_pl = 'Twój głos, zapach, ciepło... Nie mogę się doczekać, aż się obudzę i naprawdę cię przytulę, Mamo!', title_pt = 'Sonhei consigo... 💤', body_pt = 'A sua voz, o seu cheiro, o seu calor... Estou ansioso por acordar e abraçá-la de verdade, Mamã!', title_sv = 'Jag drömde om dig... 💤', body_sv = 'Din röst, din doft, din värme... Jag längtar efter att vakna och verkligen få krama dig, mamma!', title_vi = 'Con mơ thấy mẹ... 💤', body_vi = 'Giọng nói, mùi hương, hơi ấm của mẹ... Con nóng lòng được thức dậy và thật sự ôm mẹ, mẹ ơi!', title_zh = '我在梦里见到你了……💤', body_zh = '你的声音、你的味道、你的温暖……妈妈，我迫不及待想醒来真正拥抱你！' WHERE id = '9848ae06-dfd4-4fde-8a6f-3787325bfeb8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Se te ha puesto dura la barriga? 🤰', body_es = '¿Es solo un ensayo o ya vengo? Si tienes dudas, abre el Contador de contracciones. Te dirá con exactitud: ¿al hospital o a la cama?', title_fr = 'Votre ventre a durci ? 🤰', body_fr = 'C''est juste un entraînement, ou j''arrive ? En cas de doute, ouvrez le Minuteur de contractions. Il vous dira exactement : à la maternité ou au lit ?', title_hi = 'पेट सख्त हो गया? 🤰', body_hi = 'यह बस अभ्यास है, या मैं आ रहा हूँ? अगर शक हो, तो कॉन्ट्रैक्शन टाइमर खोलिए। वह आपको ठीक-ठीक बताएगा: अस्पताल या बिस्तर?', title_id = 'Perut mengeras? 🤰', body_id = 'Ini hanya latihan, atau aku sudah mau datang? Jika ragu, buka Pengukur Kontraksi. Ia akan memberi tahu dengan tepat: ke rumah sakit atau kembali tidur?', title_ja = 'お腹が張った？🤰', body_ja = 'ただの練習？それとも、わたしが出てくるところ？迷ったら「陣痛タイマー」を開いてね。病院に行くべきか、ベッドに戻るべきか、ちゃんと教えてくれるよ。', title_ko = '배가 단단해졌나요? 🤰', body_ko = '그냥 연습일까요, 아니면 제가 오는 걸까요? 헷갈리면 진통 측정기를 열어 보세요. 병원으로 갈지, 침대로 갈지 정확히 알려 줄 거예요.', title_nl = 'Wordt je buik hard? 🤰', body_nl = 'Is het maar een oefening, of kom ik eraan? Twijfel je, open dan de Weeënteller. Die vertelt je precies: naar het ziekenhuis of terug naar bed?', title_pl = 'Brzuch stwardniał? 🤰', body_pl = 'To tylko trening, czy już nadchodzę? Jeśli masz wątpliwości, otwórz Licznik skurczów. Powie ci dokładnie: do szpitala czy do łóżka?', title_pt = 'A barriga ficou dura? 🤰', body_pt = 'É só um treino ou estou a chegar? Se tiver dúvidas, abra o Contador de Contrações. Ele diz-lhe ao certo: hospital ou cama?', title_sv = 'Har magen blivit hård? 🤰', body_sv = 'Är det bara träning eller är jag på väg? Om du är osäker, öppna Värkmätaren. Den säger exakt: till sjukhuset eller tillbaka i sängen?', title_vi = 'Bụng mẹ cứng lại? 🤰', body_vi = 'Đây chỉ là tập dượt, hay con sắp ra rồi? Nếu mẹ nghi ngờ, hãy mở Đo cơn co. Nó sẽ cho mẹ biết chính xác: Đến bệnh viện hay về giường?', title_zh = '肚子发硬了？🤰', body_zh = '这只是演习，还是我要来了？如果不确定，打开宫缩计时器。它会准确告诉你：该去医院，还是回床上睡觉？' WHERE id = '7461f26e-8ba4-4a54-a57e-84bed4745dfc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Sigo aquí! 👋', body_es = 'Tengo muy poco sitio, por eso me muevo menos. Pero si estás preocupada, entra en el Contador de patadas. ¡Contemos juntos! 🦶', title_fr = 'Je suis toujours là ! 👋', body_fr = 'Je manque de place, alors je bouge moins. Mais si vous êtes inquiète, ouvrez le Compteur de coups de pied. Comptons ensemble ! 🦶', title_hi = 'मैं अभी भी यहाँ हूँ! 👋', body_hi = 'मेरी जगह बहुत तंग है, इसलिए कम हिलता हूँ। पर अगर आप चिंतित हैं, तो किक काउंटर खोलिए। चलिए साथ में गिनें! 🦶', title_id = 'Aku masih di sini! 👋', body_id = 'Ruanganku sangat sempit, jadi aku jarang bergerak. Tapi jika Anda khawatir, buka Penghitung Tendangan. Yuk, kita hitung bersama! 🦶', title_ja = 'まだここにいるよ！👋', body_ja = 'お部屋がとても狭いから、あまり動かないの。でも心配なら「キックカウンター」を開いてね。一緒に数えよう！🦶', title_ko = '저 아직 여기 있어요! 👋', body_ko = '자리가 너무 좁아서 조금만 움직여요. 그래도 걱정되면 태동 카운터를 열어 보세요. 함께 세어 봐요! 🦶', title_nl = 'Ik ben er nog steeds! 👋', body_nl = 'Ik heb heel weinig ruimte, dus ik beweeg minder. Maar maak je je zorgen, open dan de Schoppenteller. Laten we samen tellen! 🦶', title_pl = 'Wciąż tu jestem! 👋', body_pl = 'Mam bardzo ciasno, więc mniej się ruszam. Ale jeśli się martwisz, zajrzyj do Licznika kopnięć. Policzmy razem! 🦶', title_pt = 'Ainda estou aqui! 👋', body_pt = 'O meu espaço é muito apertado, por isso mexo-me pouco. Mas, se estiver preocupada, abra o Contador de Pontapés. Vamos contar juntos! 🦶', title_sv = 'Jag är fortfarande här! 👋', body_sv = 'Det är väldigt trångt, därför rör jag mig mindre. Men om du är orolig, öppna Sparkräknaren. Kom, vi räknar tillsammans! 🦶', title_vi = 'Con vẫn ở đây! 👋', body_vi = 'Chỗ con chật lắm, nên con ít cử động. Nhưng nếu mẹ lo, hãy vào Đếm cú đạp. Mình cùng đếm nhé! 🦶', title_zh = '我还在这儿！👋', body_zh = '我的空间太挤了，所以动得少。但如果你担心，打开胎动计数器，我们一起数吧！🦶' WHERE id = '0e2e37ee-dd10-44ae-98a1-2379b737ce2b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Has metido mis calcetines? 🧦', body_es = '¡No quiero pasar frío, mamá! Revisa por última vez la lista de la Bolsa del hospital. ¿Está ahí mi primer pelele? 🥰', title_fr = 'Vous avez mis mes chaussettes ? 🧦', body_fr = 'Je ne veux pas avoir froid, Maman ! Vérifiez une dernière fois la liste Valise de maternité. Ma première grenouillère y est ? 🥰', title_hi = 'मेरे मोज़े रख दिए? 🧦', body_hi = 'मुझे ठंड नहीं लगनी चाहिए, माँ! हॉस्पिटल बैग की लिस्ट आखिरी बार जाँचिए। मेरा पहला रोम्पर उसमें है? 🥰', title_id = 'Sudah memasukkan kaus kakiku? 🧦', body_id = 'Aku tidak mau kedinginan, Bunda! Cek sekali lagi daftar Tas Rumah Sakit. Apakah baju terusan pertamaku ada di sana? 🥰', title_ja = 'わたしの靴下、入れてくれた？🧦', body_ja = '寒いのはいやだよ、ママ！「入院バッグ」リストを最後にもう一度チェックしてね。わたしの最初のロンパースは入ってる？🥰', title_ko = '제 양말 챙기셨어요? 🧦', body_ko = '추운 건 싫어요, 엄마! 출산 가방 목록을 마지막으로 확인해 주세요. 제 첫 우주복이 들어 있나요? 🥰', title_nl = 'Heb je mijn sokjes ingepakt? 🧦', body_nl = 'Ik wil het niet koud hebben, mama! Controleer de checklist Ziekenhuistas nog één keer. Zit mijn eerste rompertje erin? 🥰', title_pl = 'Spakowałaś moje skarpetki? 🧦', body_pl = 'Nie chcę marznąć, Mamo! Sprawdź ostatni raz listę Torba do szpitala. Czy jest tam mój pierwszy pajacyk? 🥰', title_pt = 'Já pôs as minhas meias? 🧦', body_pt = 'Não quero ter frio, Mamã! Veja uma última vez a lista da Mala da Maternidade. O meu primeiro babygrow está lá? 🥰', title_sv = 'Har du packat mina sockor? 🧦', body_sv = 'Jag vill inte frysa, mamma! Gå igenom listan för BB-väskan en sista gång. Finns min första sparkdräkt där? 🥰', title_vi = 'Mẹ đã cho tất của con vào chưa? 🧦', body_vi = 'Con không muốn bị lạnh đâu, mẹ ơi! Hãy kiểm tra danh sách Túi đồ đi sinh lần cuối. Bộ đồ liền thân đầu tiên của con có ở đó không? 🥰', title_zh = '我的袜子放进去了吗？🧦', body_zh = '妈妈，我可不想着凉！最后再检查一遍待产包清单。我的第一件连体衣在里面吗？🥰' WHERE id = '0add760f-e392-4d33-9e33-dd2c593a0a0c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿No puedes dormir? 🥺', body_es = '¿No te entra el sueño? Vamos a escuchar ya los sonidos que me pondrás cuando nazca. La sección Ruido blanco nos calmará a los dos. 🌊', title_fr = 'Vous n''arrivez pas à dormir ? 🥺', body_fr = 'Le sommeil ne vient pas ? Écoutons dès maintenant les sons que vous me ferez écouter à ma naissance. La rubrique Bruits blancs nous apaisera tous les deux. 🌊', title_hi = 'नींद नहीं आ रही? 🥺', body_hi = 'आँखों में नींद नहीं? चलिए, जो आवाज़ें आप मुझे जन्म के बाद सुनाएँगी, उन्हें अभी से सुनें। व्हाइट नॉइज़ सेक्शन हम दोनों को शांत करेगा। 🌊', title_id = 'Tidak bisa tidur? 🥺', body_id = 'Mata sulit terpejam? Yuk, dengarkan dari sekarang suara-suara yang akan Anda putar untukku setelah lahir. Bagian Suara Putih akan menenangkan kita berdua. 🌊', title_ja = '眠れないの？🥺', body_ja = 'なかなか眠れない？生まれたらわたしに聞かせてくれる音を、今から一緒に聴こう。「ホワイトノイズ」がわたしたち2人を落ち着かせてくれるよ。🌊', title_ko = '잠이 안 오나요? 🥺', body_ko = '잠이 안 오세요? 제가 태어나면 들려줄 소리를 지금부터 함께 들어요. 백색소음 섹션이 우리 둘 다 편안하게 해 줄 거예요. 🌊', title_nl = 'Kun je niet slapen? 🥺', body_nl = 'Lukt het niet om in slaap te vallen? Laten we nu al luisteren naar de geluiden die je me na de geboorte laat horen. Het onderdeel Witte ruis kalmeert ons allebei. 🌊', title_pl = 'Nie możesz spać? 🥺', body_pl = 'Sen nie przychodzi? Posłuchajmy już teraz dźwięków, które będziesz mi puszczać po urodzeniu. Sekcja Biały szum uspokoi nas oboje. 🌊', title_pt = 'Não consegue dormir? 🥺', body_pt = 'O sono não chega? Vamos já ouvir os sons que me vai pôr quando eu nascer. A secção Ruído Branco acalma-nos aos dois. 🌊', title_sv = 'Kan du inte sova? 🥺', body_sv = 'Kommer sömnen inte? Kom, vi lyssnar redan nu på ljuden du ska spela för mig när jag har fötts. Avsnittet Vitt brus lugnar oss båda. 🌊', title_vi = 'Mẹ không ngủ được? 🥺', body_vi = 'Mắt mẹ không chịu nhắm? Mình cùng nghe trước những âm thanh mẹ sẽ mở cho con khi con chào đời nhé. Mục Tiếng ồn trắng sẽ giúp cả hai mình bình yên. 🌊', title_zh = '睡不着吗？🥺', body_zh = '毫无睡意？来，我们现在就听听我出生后你要放给我听的声音吧。白噪音能让我们俩都平静下来。🌊' WHERE id = 'c98ad2e9-dab2-435c-b719-03a62f1368f2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡He hecho la maleta y espero en la puerta! 🚪', body_es = '¡38 semanas! Ya estoy oficialmente listo para nacer. Mis pulmones, mi cerebro, todo está completo.', title_fr = 'Ma valise est prête, j''attends à la porte ! 🚪', body_fr = '38 semaines ! Je suis officiellement prêt à naître. Mes poumons, mon cerveau, tout est complet.', title_hi = 'सूटकेस पैक करके दरवाज़े पर इंतज़ार कर रहा हूँ! 🚪', body_hi = '38 हफ़्ते! अब मैं आधिकारिक तौर पर जन्म लेने के लिए तैयार हूँ। मेरे फेफड़े, मेरा दिमाग, सब कुछ पूरा है।', title_id = 'Koperku sudah siap, aku menunggu di depan pintu! 🚪', body_id = '38 minggu! Aku sudah resmi siap untuk lahir. Paru-paruku, otakku, semuanya sudah lengkap.', title_ja = '荷物をまとめて、ドアの前で待ってるよ！🚪', body_ja = '38週！もう正式に生まれる準備ができたよ。肺も脳も、ぜんぶ完成しているの。', title_ko = '짐을 싸고 문 앞에서 기다리고 있어요! 🚪', body_ko = '38주! 이제 공식적으로 태어날 준비가 됐어요. 폐도, 뇌도, 모든 게 완성됐어요.', title_nl = 'Mijn koffer is gepakt en ik sta bij de deur! 🚪', body_nl = '38 weken! Ik ben nu officieel klaar om geboren te worden. Mijn longen, mijn hersenen, alles is af.', title_pl = 'Walizka spakowana, czekam przy drzwiach! 🚪', body_pl = '38 tygodni! Jestem już oficjalnie gotowe do narodzin. Płuca, mózg, wszystko jest gotowe.', title_pt = 'Fiz as malas e estou à espera junto à porta! 🚪', body_pt = '38 semanas! Já estou oficialmente pronto para nascer. Os pulmões, o cérebro, está tudo pronto.', title_sv = 'Jag har packat väskan och väntar vid dörren! 🚪', body_sv = '38 veckor! Nu är jag officiellt redo att födas. Mina lungor, min hjärna, allt är klart.', title_vi = 'Con đã xếp xong hành lý, đang chờ ở cửa! 🚪', body_vi = '38 tuần! Con đã chính thức sẵn sàng chào đời. Phổi, não, mọi thứ của con đều đã hoàn chỉnh.', title_zh = '我已经收拾好行李，在门口等着啦！🚪', body_zh = '38周！我已经正式准备好出生了。我的肺、大脑，一切都已就绪。' WHERE id = '73f5c761-83f4-4b9c-ab8c-ebbbc23c1ad2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Qué harás si rompes aguas? 💦', body_es = '¡Nada de pánico! Lee el artículo «Las 3 señales principales del parto» en la sección Blog.', title_fr = 'Que ferez-vous si vous perdez les eaux ? 💦', body_fr = 'Pas de panique ! Lisez l''article « Les 3 principaux signes de l''accouchement » dans la rubrique Blog.', title_hi = 'पानी की थैली फटे तो क्या करेंगी? 💦', body_hi = 'घबराना नहीं है! ब्लॉग सेक्शन में ''डिलीवरी के 3 मुख्य संकेत'' लेख पढ़िए।', title_id = 'Apa yang akan Anda lakukan jika ketuban pecah? 💦', body_id = 'Jangan panik! Baca artikel 3 tanda utama persalinan di bagian Blog.', title_ja = '破水したらどうする？💦', body_ja = 'あわてなくて大丈夫！ブログの「お産が始まる3つのサイン」の記事を読んでおきましょう。', title_ko = '양수가 터지면 어떻게 할 거예요? 💦', body_ko = '당황하지 마세요! 블로그 섹션에서 ''출산의 3가지 주요 신호'' 글을 읽어 보세요.', title_nl = 'Wat doe je als je vliezen breken? 💦', body_nl = 'Niet in paniek raken! Lees het artikel ‘3 belangrijke tekenen van de bevalling’ in het onderdeel Blog.', title_pl = 'Co zrobisz, gdy odejdą wody? 💦', body_pl = 'Bez paniki! Przeczytaj artykuł „3 główne oznaki porodu” w sekcji Blog.', title_pt = 'O que vai fazer se as águas rebentarem? 💦', body_pt = 'Nada de pânico! Leia o artigo "Os 3 principais sinais do parto" na secção Blogue.', title_sv = 'Vad gör du om vattnet går? 💦', body_sv = 'Ingen panik! Läs artikeln ''Förlossningens 3 viktigaste tecken'' i bloggen.', title_vi = 'Nếu vỡ ối, mẹ sẽ làm gì? 💦', body_vi = 'Không hoảng loạn nhé! Hãy đọc bài viết "3 dấu hiệu chính của chuyển dạ" trong mục Blog.', title_zh = '如果破水了，你会怎么做？💦', body_zh = '不要慌！去博客板块读一读《分娩的3个主要征兆》这篇文章。' WHERE id = 'b02641e8-c8b3-4941-8bbc-12e86e7720ae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Me estoy deslizando hacia abajo... ⬇️', body_es = 'Sé que presiono los huesos de tu pelvis. Pero es el único camino para llegar a ti. ¡Mi mamá tan valiente! ❤️', title_fr = 'Je glisse vers le bas... ⬇️', body_fr = 'J''appuie sur les os de votre bassin, je sais. Mais c''est le seul chemin pour vous retrouver. Ma maman si courageuse ! ❤️', title_hi = 'मैं नीचे खिसक रहा हूँ... ⬇️', body_hi = 'मुझे पता है, मैं आपकी श्रोणि की हड्डियों पर दबाव डाल रहा हूँ। पर आपसे मिलने का यही एक रास्ता है। मेरी सहनशील माँ! ❤️', title_id = 'Aku meluncur ke bawah... ⬇️', body_id = 'Aku tahu aku menekan tulang panggul Anda. Tapi inilah satu-satunya jalan untuk bertemu Anda. Bundaku yang tangguh! ❤️', title_ja = '下に降りてきてるよ... ⬇️', body_ja = '骨盤を押しているのはわかってるよ。でもこれが、ママに会うためのたったひとつの道なの。がんばり屋のわたしのママ！❤️', title_ko = '아래로 내려가고 있어요... ⬇️', body_ko = '엄마 골반을 누르고 있는 거 알아요. 그래도 이게 엄마를 만나러 가는 유일한 길이에요. 씩씩한 우리 엄마! ❤️', title_nl = 'Ik zak naar beneden... ⬇️', body_nl = 'Ik weet dat ik op je bekken druk. Maar dit is de enige weg om bij jou te komen. Mijn dappere mama! ❤️', title_pl = 'Zsuwam się niżej... ⬇️', body_pl = 'Wiem, że uciskam kości miednicy. Ale to jedyna droga, by do ciebie dotrzeć. Moja dzielna Mamo! ❤️', title_pt = 'Estou a deslizar para baixo... ⬇️', body_pt = 'Sei que estou a pressionar os ossos da bacia. Mas é o único caminho para chegar até si. A minha Mamã tão resistente! ❤️', title_sv = 'Jag glider nedåt... ⬇️', body_sv = 'Jag vet att jag trycker på dina bäckenben. Men det är det enda sättet för mig att få träffa dig. Min tåliga mamma! ❤️', title_vi = 'Con đang trượt xuống... ⬇️', body_vi = 'Con biết con đang đè lên xương chậu của mẹ. Nhưng đó là con đường duy nhất để con đến với mẹ. Người mẹ kiên cường của con! ❤️', title_zh = '我在往下滑……⬇️', body_zh = '我知道我在压着你的骨盆。但这是我和你相见的唯一途径。我坚强的妈妈！❤️' WHERE id = '8013f167-1549-4b4a-8e28-e01b854ddc4c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Noches sin dormir? 🥱', body_es = 'A medida que se acerca el parto, puede costarte más dormirte. Es tu cuerpo preparándote para el modo bebé.', title_fr = 'Nuits sans sommeil ? 🥱', body_fr = 'À l''approche de l''accouchement, vous endormir peut devenir plus difficile. C''est votre corps qui vous prépare au mode bébé.', title_hi = 'नींद रहित रातें? 🥱', body_hi = 'डिलीवरी करीब आने पर नींद आना मुश्किल हो सकता है। यह आपका शरीर आपको बेबी मोड के लिए तैयार कर रहा है।', title_id = 'Malam tanpa tidur? 🥱', body_id = 'Menjelang persalinan, tidur bisa makin sulit. Ini cara tubuh mempersiapkan Anda untuk mode bayi.', title_ja = '眠れない夜？🥱', body_ja = '出産が近づくと、寝つきが悪くなることがあります。これは体が赤ちゃんとの生活リズムに向けて準備しているのです。', title_ko = '잠 못 드는 밤? 🥱', body_ko = '출산이 다가올수록 잠들기 어려워질 수 있어요. 몸이 아기 모드에 대비하는 거예요.', title_nl = 'Slapeloze nachten? 🥱', body_nl = 'Hoe dichter de bevalling, hoe moeilijker in slaap vallen kan worden. Zo bereidt je lichaam je voor op de babymodus.', title_pl = 'Nieprzespane noce? 🥱', body_pl = 'Im bliżej porodu, tym trudniej może być zasnąć. To twoje ciało przygotowuje cię do trybu niemowlęcego.', title_pt = 'Noites sem dormir? 🥱', body_pt = 'À medida que o parto se aproxima, adormecer pode tornar-se mais difícil. É o seu corpo a prepará-la para o ritmo do bebé.', title_sv = 'Sömnlösa nätter? 🥱', body_sv = 'När förlossningen närmar sig kan det bli svårare att somna. Det är kroppens sätt att förbereda dig för bebisläget.', title_vi = 'Những đêm mất ngủ? 🥱', body_vi = 'Càng gần ngày sinh, việc vào giấc có thể càng khó. Đó là cách cơ thể chuẩn bị cho mẹ bước vào chế độ em bé.', title_zh = '睡不着的夜晚？🥱', body_zh = '临近分娩，入睡可能会变得更难。这是身体在让你提前适应宝宝的作息。' WHERE id = 'd154d2c7-ec75-47ac-ba69-4fbe92885614' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Cómo late mi corazón? 💓', body_es = 'Cuando me eches de menos, pon la mano en tu barriga. Nuestros corazones laten a la vez. Todo va bien, solo esperamos el día del encuentro. 🗓️', title_fr = 'Comment bat mon cœur ? 💓', body_fr = 'Quand je vous manque, posez la main sur votre ventre. Nos cœurs battent ensemble. Tout va bien, nous attendons simplement le jour de notre rencontre. 🗓️', title_hi = 'मेरा दिल कैसे धड़क रहा है? 💓', body_hi = 'जब मेरी याद आए, पेट पर हाथ रखिए। हमारे दिल एक साथ धड़कते हैं। सब ठीक है, हम बस मिलने के दिन का इंतज़ार कर रहे हैं। 🗓️', title_id = 'Bagaimana detak jantungku? 💓', body_id = 'Saat rindu, letakkan tangan di perut Anda. Jantung kita berdetak bersama. Semuanya baik-baik saja, kita hanya menunggu hari pertemuan. 🗓️', title_ja = 'わたしの心臓、どんなふうに動いてる？💓', body_ja = 'さみしくなったら、お腹に手を当ててね。わたしたちの心臓はひとつになって動いているよ。すべて順調、あとは会える日を待つだけ。🗓️', title_ko = '제 심장은 어떻게 뛰고 있을까요? 💓', body_ko = '제가 보고 싶을 땐 배에 손을 얹어 보세요. 우리 심장은 함께 뛰어요. 다 괜찮아요, 만날 날을 기다리고 있을 뿐이에요. 🗓️', title_nl = 'Hoe klopt mijn hartje? 💓', body_nl = 'Als je me mist, leg dan je hand op je buik. Onze harten kloppen als één. Alles is in orde, we wachten alleen op de dag dat we elkaar ontmoeten. 🗓️', title_pl = 'Jak bije moje serduszko? 💓', body_pl = 'Gdy tęsknisz, połóż dłoń na brzuchu. Nasze serca biją jak jedno. Wszystko w porządku, po prostu czekamy na dzień spotkania. 🗓️', title_pt = 'Como bate o meu coração? 💓', body_pt = 'Quando sentir saudades, ponha a mão na barriga. Os nossos corações batem como um só. Está tudo bem, estamos só à espera do dia do encontro. 🗓️', title_sv = 'Hur slår mitt hjärta? 💓', body_sv = 'När du saknar mig, lägg handen på magen. Våra hjärtan slår som ett. Allt är som det ska, vi väntar bara på dagen då vi möts. 🗓️', title_vi = 'Tim con đập thế nào nhỉ? 💓', body_vi = 'Khi nhớ con, mẹ hãy đặt tay lên bụng. Tim chúng mình đập cùng một nhịp. Mọi thứ đều ổn, mình chỉ đang chờ ngày gặp mặt thôi. 🗓️', title_zh = '我的心跳怎么样？💓', body_zh = '想我的时候，就把手放在肚子上。我们的心一起跳动。一切都好，我们只是在等待相见的那一天。🗓️' WHERE id = 'b3effc18-3aca-4ae1-9929-0aa55b124180' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Toc, toc, soy yo! ✊', body_es = '¿Las contracciones van y vienen? No pierdas tiempo, pulsa el botón del Contador de contracciones. Si los intervalos se acortan, ¡el gran día es hoy! 🚑', title_fr = 'Toc-toc, c''est moi ! ✊', body_fr = 'Les contractions vont et viennent ? Ne perdez pas de temps, appuyez sur le Minuteur de contractions. Si les intervalles raccourcissent, le grand jour, c''est aujourd''hui ! 🚑', title_hi = 'खट-खट, मैं हूँ! ✊', body_hi = 'पेट में दर्द आ-जा रहा है? समय बर्बाद मत कीजिए, कॉन्ट्रैक्शन टाइमर का बटन दबाइए। अगर अंतराल घट रहे हैं, तो बड़ा दिन आज ही है! 🚑', title_id = 'Tok-tok, ini aku! ✊', body_id = 'Perut terasa nyeri datang dan pergi? Jangan buang waktu, tekan tombol Pengukur Kontraksi. Jika jaraknya makin pendek, berarti hari besarnya adalah hari ini! 🚑', title_ja = 'トントン、わたしだよ！✊', body_ja = 'お腹の痛みが来たり引いたりしてる？迷わず「陣痛タイマー」のボタンを押してね。間隔が短くなっていたら、今日がその日かも！🚑', title_ko = '똑똑, 저예요! ✊', body_ko = '진통이 왔다 갔다 하나요? 시간 낭비하지 말고 진통 측정기 버튼을 누르세요. 간격이 줄어든다면 바로 오늘이 그날이에요! 🚑', title_nl = 'Klop klop, ik ben het! ✊', body_nl = 'Komen en gaan de weeën? Verlies geen tijd en druk op de knop Weeënteller. Worden de tussenpozen korter, dan is vandaag de grote dag! 🚑', title_pl = 'Puk-puk, to ja! ✊', body_pl = 'Skurcze przychodzą i odchodzą? Nie trać czasu, naciśnij przycisk Licznik skurczów. Jeśli odstępy się skracają, wielki dzień jest dziś! 🚑', title_pt = 'Toc-toc, sou eu! ✊', body_pt = 'As contrações vão e vêm? Não perca tempo, carregue no Contador de Contrações. Se os intervalos estiverem a diminuir, o grande dia é hoje! 🚑', title_sv = 'Knack-knack, det är jag! ✊', body_sv = 'Kommer och går värkarna i magen? Slösa inte tid, tryck på knappen Värkmätare. Om intervallen blir kortare är den stora dagen i dag! 🚑', title_vi = 'Cốc cốc, là con đây! ✊', body_vi = 'Cơn co đến rồi đi? Đừng chần chừ, hãy nhấn nút Đo cơn co. Nếu khoảng cách ngắn dần, ngày trọng đại chính là hôm nay! 🚑', title_zh = '咚咚，是我！✊', body_zh = '肚子一阵一阵地疼？别耽误时间，按下宫缩计时器。如果间隔越来越短，那么今天就是那个重要的日子！🚑' WHERE id = '777b97b8-95e9-4f43-a5c2-c68495d48777' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Ha llegado el oro líquido? ✨', body_es = 'Puede salir un líquido amarillento del pecho: es la primera vacuna del bebé. Lee sobre la lactancia en el Blog. 📖', title_fr = 'L''or liquide est arrivé ? ✨', body_fr = 'Un liquide jaunâtre peut s''écouler des seins : c''est le premier vaccin de bébé. Lisez nos articles sur l''allaitement dans les Blogs. 📖', title_hi = 'सुनहरा दूध आया? ✨', body_hi = 'स्तनों से पीला सा तरल निकल सकता है, और यह बच्चे का पहला टीका है। ब्लॉग में स्तनपान के बारे में पढ़िए। 📖', title_id = 'Susu Emas sudah keluar? ✨', body_id = 'Cairan kekuningan bisa keluar dari payudara, dan inilah vaksin pertama bayi. Baca tentang menyusui di Blog. 📖', title_ja = '「黄金のミルク」が出てきた？✨', body_ja = '胸から黄色っぽい液が出ることがあります。これは赤ちゃんにとって最初の予防接種、初乳です。ブログで授乳について読んでみましょう。📖', title_ko = '황금 젖이 나왔나요? ✨', body_ko = '가슴에서 노르스름한 액체가 나올 수 있어요. 이건 아기의 첫 백신이에요. 블로그에서 모유 수유에 대해 읽어 보세요. 📖', title_nl = 'Is het vloeibare goud er al? ✨', body_nl = 'Er kan gelig vocht uit je borsten komen: dat is de eerste ‘vaccinatie’ van je baby. Lees meer over borstvoeding in de blogs. 📖', title_pl = 'Pojawiło się płynne złoto? ✨', body_pl = 'Z piersi może wypływać żółtawy płyn, to pierwsza szczepionka dziecka. Przeczytaj o karmieniu piersią na blogu. 📖', title_pt = 'Chegou o leite dourado? ✨', body_pt = 'Pode sair um líquido amarelado do peito, que é a primeira vacina do bebé. Leia sobre amamentação nos blogues. 📖', title_sv = 'Har det flytande guldet kommit? ✨', body_sv = 'En gulaktig vätska kan komma från brösten, och det är barnets första vaccin. Läs om amning i bloggen. 📖', title_vi = 'Sữa vàng đã về chưa? ✨', body_vi = 'Ngực có thể tiết ra chất lỏng màu vàng nhạt, đó là liều vắc-xin đầu tiên của bé. Hãy đọc về việc cho con bú trong mục Blog nhé. 📖', title_zh = '“液体黄金”来了吗？✨', body_zh = '乳房可能会流出淡黄色的液体，这是宝宝的第一份“疫苗”。去博客里读读关于母乳喂养的内容吧。📖' WHERE id = '23425b07-63ff-4191-a065-718ed3a783d1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Falsa o verdadera? 🤔', body_es = '¿La barriga se endurece y se relaja? Si las contracciones no son regulares, son falsas. Para estar segura, ¡abre el Contador de contracciones y compruébalo!', title_fr = 'Fausse ou vraie ? 🤔', body_fr = 'Votre ventre durcit puis se relâche ? Si les contractions ne sont pas régulières, ce sont de fausses contractions. Pour en être sûre, ouvrez le Minuteur de contractions et testez !', title_hi = 'झूठा या असली? 🤔', body_hi = 'पेट सख्त होकर ढीला हो जाता है? अगर दर्द नियमित नहीं है, तो झूठा है। पक्का करने के लिए कॉन्ट्रैक्शन टाइमर खोलकर जाँचिए!', title_id = 'Palsu atau Asli? 🤔', body_id = 'Perut mengeras lalu mengendur? Jika kontraksinya tidak teratur, itu kontraksi palsu. Untuk memastikan, buka Pengukur Kontraksi dan coba!', title_ja = '前駆陣痛？それとも本陣痛？🤔', body_ja = 'お腹が張ったりゆるんだりしますか？間隔が不規則なら、前駆陣痛です。確かめるには「陣痛タイマー」を開いて測ってみましょう！', title_ko = '가진통일까, 진진통일까? 🤔', body_ko = '배가 단단해졌다 풀렸다 하나요? 진통이 규칙적이지 않으면 가진통이에요. 확실히 하려면 진통 측정기를 열어 확인해 보세요!', title_nl = 'Oefenwee of echte wee? 🤔', body_nl = 'Wordt je buik hard en weer zacht? Zijn de weeën niet regelmatig, dan zijn het oefenweeën. Open de Weeënteller en test het om zeker te zijn!', title_pl = 'Fałszywe czy prawdziwe? 🤔', body_pl = 'Brzuch twardnieje i mięknie? Jeśli skurcze nie są regularne, to skurcze przepowiadające. Aby mieć pewność, otwórz Licznik skurczów i sprawdź!', title_pt = 'Falsa ou verdadeira? 🤔', body_pt = 'A barriga fica dura e depois relaxa? Se as contrações não forem regulares, são falsas. Para ter a certeza, abra o Contador de Contrações e teste!', title_sv = 'Förvärkar eller riktiga värkar? 🤔', body_sv = 'Blir magen hård och mjuk om vartannat? Om värkarna inte är regelbundna är det förvärkar. Öppna Värkmätaren och testa för att vara säker!', title_vi = 'Giả hay Thật? 🤔', body_vi = 'Bụng mẹ cứng lên rồi mềm lại? Nếu các cơn co không đều thì đó là cơn co giả. Để chắc chắn, hãy mở Đo cơn co và kiểm tra!', title_zh = '假性还是真性宫缩？🤔', body_zh = '肚子一会儿发硬一会儿放松？如果宫缩不规律，就是假性的。想确认的话，打开宫缩计时器测一测！' WHERE id = '85c5a987-f8eb-414a-99b9-ec981bbc08cd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Ha salido el tapón? 🩸', body_es = 'Si ha salido un flujo espeso, significa que el cuello del útero empieza a abrirse. Tranquila, es solo una señal para prepararte.', title_fr = 'Le bouchon muqueux ? 🩸', body_fr = 'Si un liquide épais s''est écoulé, cela signifie que le col de l''utérus commence à s''ouvrir. Pas de panique, c''est simplement le signal pour vous préparer.', title_hi = 'निशान दिखा? 🩸', body_hi = 'अगर गाढ़ा स्राव निकला है, तो गर्भाशय ग्रीवा खुलना शुरू हो रही है। घबराइए मत, यह बस तैयार होने का संकेत है।', title_id = 'Muncul tanda? 🩸', body_id = 'Jika keluar lendir kental, berarti leher rahim mulai membuka. Jangan takut, ini hanya sinyal untuk bersiap.', title_ja = 'おしるしはありましたか？🩸', body_ja = '粘り気のあるおりものが出たら、子宮口が開きはじめているサインです。心配しないで、準備を始める合図にすぎません。', title_ko = '이슬이 비쳤나요? 🩸', body_ko = '끈적한 분비물이 나왔다면 자궁경부가 열리기 시작했다는 뜻이에요. 걱정 마세요, 준비하라는 신호일 뿐이에요.', title_nl = 'Slijmprop verloren? 🩸', body_nl = 'Is er dik slijm vrijgekomen? Dan begint je baarmoedermond open te gaan. Geen zorgen, dit is gewoon een teken om je klaar te maken.', title_pl = 'Odszedł czop śluzowy? 🩸', body_pl = 'Jeśli pojawiła się gęsta wydzielina, szyjka macicy zaczyna się otwierać. Nie bój się, to tylko sygnał, by się przygotować.', title_pt = 'Saiu o rolhão mucoso? 🩸', body_pt = 'Se saiu um corrimento espesso, significa que o colo do útero está a começar a abrir. Não se assuste, é apenas um sinal para se preparar.', title_sv = 'Har slemproppen gått? 🩸', body_sv = 'Om en seg flytning har kommit betyder det att livmoderhalsen börjar öppna sig. Var inte rädd, det är bara en signal att göra sig redo.', title_vi = 'Có dấu hiệu báo chưa? 🩸', body_vi = 'Nếu thấy dịch nhầy đặc, nghĩa là cổ tử cung bắt đầu mở. Đừng sợ, đây chỉ là tín hiệu để chuẩn bị.', title_zh = '见红了吗？🩸', body_zh = '如果流出了黏稠的分泌物，说明宫颈开始打开了。别怕，这只是该做准备的信号。' WHERE id = '55b51f8f-337f-485f-a7bb-0d388895d70b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Plaf! ¿Qué ha sido ese ruido? 💦', body_es = 'Si rompes aguas, no te asustes. Respira hondo y avisa a tu médico. ¡Ya voy! 🌊', title_fr = 'Splash ! C''était quoi ce bruit ? 💦', body_fr = 'Si vous perdez les eaux, pas de panique. Respirez profondément et prévenez votre médecin. J''arrive ! 🌊', title_hi = 'छपाक! यह कैसी आवाज़ थी? 💦', body_hi = 'अगर पानी की थैली फटे, तो घबराइए मत। बस गहरी साँस लीजिए और अपने डॉक्टर को बताइए। मैं आ रहा हूँ! 🌊', title_id = 'Byur! Suara apa itu? 💦', body_id = 'Jika ketuban pecah, jangan panik. Tarik napas dalam-dalam dan beri tahu dokter Anda. Aku datang! 🌊', title_ja = 'パシャッ！今の音はなに？💦', body_ja = '破水しても、あわてないでね。深呼吸して、お医者さんに連絡してね。わたし、もうすぐ行くよ！🌊', title_ko = '철썩! 이게 무슨 소리예요? 💦', body_ko = '양수가 터져도 당황하지 마세요. 깊게 숨을 쉬고 담당 의사에게 알리세요. 제가 가고 있어요! 🌊', title_nl = 'Plons! Wat was dat? 💦', body_nl = 'Als je vliezen breken, raak niet in paniek. Haal diep adem en laat het je arts weten. Ik kom eraan! 🌊', title_pl = 'Chlup! Co to był za dźwięk? 💦', body_pl = 'Jeśli odejdą ci wody, nie panikuj. Po prostu weź głęboki oddech i daj znać lekarzowi. Nadchodzę! 🌊', title_pt = 'Splash! Que som foi este? 💦', body_pt = 'Se as águas rebentarem, não entre em pânico. Respire fundo e avise o seu médico. Estou a chegar! 🌊', title_sv = 'Plask! Vad var det för ljud? 💦', body_sv = 'Om vattnet går, få inte panik. Andas bara djupt och meddela din läkare. Jag kommer! 🌊', title_vi = 'Tõm! Tiếng gì vậy? 💦', body_vi = 'Nếu vỡ ối, đừng hoảng loạn. Chỉ cần hít thở sâu và báo cho bác sĩ. Con đang đến đây! 🌊', title_zh = '啪！这是什么声音？💦', body_zh = '如果破水了，不要慌。深呼吸，然后通知你的医生。我要来啦！🌊' WHERE id = 'e3c60e6b-f031-49de-9d1e-df5e6adaec56' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Hay que echar el estrés! 😮‍💨', body_es = '¿Estás nerviosa? Aprende ya las técnicas de respiración para el parto de la sección Ejercicios. Te harán mucha falta durante las contracciones.', title_fr = 'Chassons le stress ! 😮‍💨', body_fr = 'Vous êtes émue ? Apprenez dès maintenant les techniques de respiration pour l''accouchement dans la rubrique Exercices. Elles vous seront très utiles pendant les contractions.', title_hi = 'तनाव भगाना है! 😮‍💨', body_hi = 'उत्साहित हैं? एक्सरसाइज़ सेक्शन में डिलीवरी के लिए साँस लेने की तकनीकें अभी से सीखिए। दर्द के दौरान ये बहुत काम आएँगी।', title_id = 'Saatnya mengusir stres! 😮‍💨', body_id = 'Deg-degan? Pelajari teknik Napas Persalinan di bagian Latihan dari sekarang. Ini akan sangat berguna saat kontraksi.', title_ja = 'ストレスを追い払おう！😮‍💨', body_ja = 'ドキドキしていますか？「エクササイズ」セクションの「お産の呼吸法」を今から練習しましょう。陣痛のときにきっと役立ちます。', title_ko = '스트레스를 날려 버려요! 😮‍💨', body_ko = '긴장되나요? 운동 섹션의 분만 호흡법을 지금부터 익혀 두세요. 진통할 때 아주 큰 도움이 될 거예요.', title_nl = 'Weg met de stress! 😮‍💨', body_nl = 'Spannend? Leer nu al de ademhalingstechnieken voor de bevalling in het onderdeel Oefeningen. Die heb je hard nodig tijdens de weeën.', title_pl = 'Trzeba przegonić stres! 😮‍💨', body_pl = 'Denerwujesz się? Naucz się już teraz technik oddychania porodowego z sekcji Ćwiczenia. Bardzo przydadzą ci się podczas skurczów.', title_pt = 'É preciso afastar o stress! 😮‍💨', body_pt = 'Está nervosa? Aprenda já as técnicas de respiração para o parto na secção Exercícios. Vão ser muito úteis durante as contrações.', title_sv = 'Dags att jaga bort stressen! 😮‍💨', body_sv = 'Är du nervös? Lär dig redan nu andningsteknikerna för förlossningen i avsnittet Träning. Du kommer att ha stor nytta av dem under värkarna.', title_vi = 'Phải xua tan căng thẳng thôi! 😮‍💨', body_vi = 'Mẹ hồi hộp à? Hãy học ngay các kỹ thuật Thở khi sinh trong mục Bài tập. Mẹ sẽ rất cần chúng khi có cơn co.', title_zh = '赶走压力！😮‍💨', body_zh = '紧张吗？现在就去运动板块学习分娩呼吸法吧。宫缩时你会非常需要它。' WHERE id = 'a7c9fb31-732f-48c9-869e-cb25de2cc6bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Han disminuido mis patadas? 🦶', body_es = '¡No tengo sitio, mamá! Pero debes notar mis movimientos. Si tienes dudas, come algo dulce y entra en el Contador de patadas.', title_fr = 'Mes coups de pied ont diminué ? 🦶', body_fr = 'Je n''ai plus de place, Maman ! Mais vous devez sentir mes mouvements. En cas de doute, mangez quelque chose de sucré et ouvrez le Compteur de coups de pied.', title_hi = 'मेरी किक कम हो गईं? 🦶', body_hi = 'मेरे पास जगह नहीं है, माँ! फिर भी आपको मेरी हरकतें महसूस होनी चाहिए। अगर शक हो, तो कुछ मीठा खाइए और किक काउंटर खोलिए।', title_id = 'Tendanganku berkurang? 🦶', body_id = 'Ruanganku sudah habis, Bunda! Tapi Anda tetap harus merasakan gerakanku. Jika ragu, makan sesuatu yang manis dan buka Penghitung Tendangan.', title_ja = 'キックが減った？🦶', body_ja = 'スペースがないの、ママ！でも動きは感じられるはずだよ。心配なときは、甘いものを食べてから「キックカウンター」を開いてね。', title_ko = '제 발차기가 줄었나요? 🦶', body_ko = '자리가 없어요, 엄마! 그래도 제 움직임은 느껴져야 해요. 걱정되면 달콤한 걸 드시고 태동 카운터를 열어 보세요.', title_nl = 'Trap ik minder? 🦶', body_nl = 'Ik heb geen ruimte, mama! Maar je moet mijn bewegingen wel voelen. Twijfel je, eet dan iets zoets en open de Schoppenteller.', title_pl = 'Kopię mniej? 🦶', body_pl = 'Nie mam miejsca, Mamo! Ale powinnaś czuć moje ruchy. Jeśli masz wątpliwości, zjedz coś słodkiego i zajrzyj do Licznika kopnięć.', title_pt = 'Os meus pontapés diminuíram? 🦶', body_pt = 'Não tenho espaço, Mamã! Mas deve sentir os meus movimentos. Se tiver dúvidas, coma algo doce e abra o Contador de Pontapés.', title_sv = 'Har mina sparkar blivit färre? 🦶', body_sv = 'Jag har ingen plats, mamma! Men du ska ändå känna mina rörelser. Om du är osäker, ät något sött och öppna Sparkräknaren.', title_vi = 'Con đạp ít đi? 🦶', body_vi = 'Con hết chỗ rồi, mẹ ơi! Nhưng mẹ vẫn phải cảm nhận được cử động của con. Nếu nghi ngờ, hãy ăn chút đồ ngọt và vào Đếm cú đạp.', title_zh = '我的胎动变少了？🦶', body_zh = '妈妈，我没有空间啦！但你应该还能感觉到我在动。如有疑虑，吃点甜的，然后打开胎动计数器。' WHERE id = '508da239-e1ff-41bc-b69e-7ac41310e57b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Tienes los documentos? 📄', body_es = 'DNI, resultados de análisis... Revisa la bolsa por última vez. ¿Has marcado todo en la lista de la Bolsa del hospital? ✅', title_fr = 'Les papiers sont prêts ? 📄', body_fr = 'Carte d''identité, résultats d''analyses... Vérifiez votre sac une dernière fois. Avez-vous tout coché dans la liste Valise de maternité ? ✅', title_hi = 'दस्तावेज़ अपनी जगह पर हैं? 📄', body_hi = 'पहचान पत्र, जाँच रिपोर्ट... बैग को आखिरी बार देखिए। क्या हॉस्पिटल बैग की लिस्ट में सब पर टिक लगा दिया? ✅', title_id = 'Dokumen sudah siap? 📄', body_id = 'Kartu identitas, hasil tes... Cek tas Anda sekali lagi. Sudah mencentang semuanya di daftar Tas Rumah Sakit? ✅', title_ja = '書類はそろっていますか？📄', body_ja = '身分証明書、検査結果...バッグを最後にもう一度確認しましょう。「入院バッグ」リストにすべてチェックを入れましたか？✅', title_ko = '서류는 챙기셨어요? 📄', body_ko = '신분증, 검사 결과지... 가방을 마지막으로 확인하세요. 출산 가방 목록에 모두 체크하셨나요? ✅', title_nl = 'Liggen je documenten klaar? 📄', body_nl = 'Identiteitsbewijs, uitslagen van onderzoeken... Kijk nog één keer in je tas. Heb je alles afgevinkt op de checklist Ziekenhuistas? ✅', title_pl = 'Dokumenty na miejscu? 📄', body_pl = 'Dowód osobisty, wyniki badań... Ostatni raz sprawdź torbę. Odhaczyłaś wszystko na liście Torba do szpitala? ✅', title_pt = 'Os documentos estão no sítio? 📄', body_pt = 'Cartão de cidadão, resultados das análises... Veja a mala uma última vez. Já marcou tudo na lista da Mala da Maternidade? ✅', title_sv = 'Ligger dokumenten på plats? 📄', body_sv = 'Id-kort, provsvar... Titta i väskan en sista gång. Har du bockat av allt på listan för BB-väskan? ✅', title_vi = 'Giấy tờ đã sẵn sàng chưa? 📄', body_vi = 'Căn cước, kết quả xét nghiệm... Kiểm tra túi lần cuối nhé. Mẹ đã đánh dấu đủ mọi thứ trong danh sách Túi đồ đi sinh chưa? ✅', title_zh = '证件准备好了吗？📄', body_zh = '身份证、化验结果……最后再检查一遍包。待产包清单上的每一项都打勾了吗？✅' WHERE id = '94a030ca-34dd-44fe-9971-596b00948ae5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Cierra los ojos... 😌', body_es = 'No tengas miedo al parto. Imagina el momento en que me tengas en brazos por primera vez. Ese olor te hará olvidar todo el dolor.', title_fr = 'Fermez les yeux... 😌', body_fr = 'N''ayez pas peur de l''accouchement. Imaginez simplement le moment où vous me prendrez dans vos bras pour la première fois. Mon odeur vous fera oublier toute la douleur.', title_hi = 'आँखें बंद कीजिए... 😌', body_hi = 'डिलीवरी से डरिए मत। बस उस पल की कल्पना कीजिए जब आप मुझे पहली बार गोद में लेंगी। वह खुशबू सारे दर्द भुला देगी।', title_id = 'Pejamkan mata... 😌', body_id = 'Jangan takut melahirkan. Bayangkan saja saat Anda menggendongku untuk pertama kalinya. Aroma itu akan membuat Anda melupakan semua rasa sakit.', title_ja = '目を閉じて... 😌', body_ja = 'お産を怖がらないで。初めてわたしを抱っこする瞬間だけを思い浮かべて。わたしのにおいが、痛みをぜんぶ忘れさせてくれるよ。', title_ko = '눈을 감아 보세요... 😌', body_ko = '출산을 두려워하지 마세요. 저를 처음 품에 안을 그 순간만 떠올려 보세요. 그 냄새가 모든 아픔을 잊게 해 줄 거예요.', title_nl = 'Doe je ogen dicht... 😌', body_nl = 'Wees niet bang voor de bevalling. Denk aan het moment dat je me voor het eerst in je armen houdt. Die geur laat je alle pijn vergeten.', title_pl = 'Zamknij oczy... 😌', body_pl = 'Nie bój się porodu. Wyobraź sobie chwilę, gdy pierwszy raz weźmiesz mnie w ramiona. Ten zapach sprawi, że zapomnisz o całym bólu.', title_pt = 'Feche os olhos... 😌', body_pt = 'Não tenha medo do parto. Imagine apenas o momento em que me vai pegar ao colo pela primeira vez. Aquele cheiro vai fazê-la esquecer todas as dores.', title_sv = 'Blunda... 😌', body_sv = 'Var inte rädd för förlossningen. Föreställ dig bara ögonblicket när du tar mig i famnen för första gången. Den doften får dig att glömma all smärta.', title_vi = 'Nhắm mắt lại nào... 😌', body_vi = 'Đừng sợ sinh nở. Chỉ cần hình dung khoảnh khắc mẹ lần đầu ôm con vào lòng. Mùi hương ấy sẽ khiến mẹ quên hết mọi đau đớn.', title_zh = '闭上眼睛……😌', body_zh = '不要害怕分娩。想象一下你第一次把我抱进怀里的那一刻。那份气息会让你忘记所有的疼痛。' WHERE id = '8d62f4d6-0c1f-4d76-ad37-4f81f9b3a9c0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'El cérvix (cuello del útero) 🗝️', body_es = '¡Hay un trabajo secreto en marcha! El cuello del útero se ablanda, se adelgaza y se abre. Aunque no lo notes, tu cuerpo me está abriendo la puerta.', title_fr = 'Le col de l''utérus 🗝️', body_fr = 'Un travail secret est en cours ! Le col de l''utérus se ramollit, s''amincit et s''ouvre. Même si vous ne le sentez pas, votre corps m''ouvre la porte.', title_hi = 'सर्विक्स (गर्भाशय ग्रीवा) 🗝️', body_hi = 'गुप्त काम चल रहा है! गर्भाशय ग्रीवा नरम, पतली हो रही है और खुल रही है। भले आपको महसूस न हो, आपका शरीर मेरे लिए दरवाज़ा खोल रहा है।', title_id = 'Serviks (leher rahim) 🗝️', body_id = 'Ada pekerjaan rahasia! Leher rahim melunak, menipis, dan membuka. Meski tidak terasa, tubuh Anda sedang membukakan pintu untukku.', title_ja = '子宮頸部（子宮口）🗝️', body_ja = 'ひそかな準備が進んでいます！子宮口がやわらかく、薄くなり、開いていきます。気づかなくても、体が赤ちゃんのために扉を開けているのです。', title_ko = '자궁경부 🗝️', body_ko = '비밀 작업이 진행 중이에요! 자궁경부가 부드러워지고, 얇아지고, 열리고 있어요. 느끼지 못해도 엄마 몸이 저를 위해 문을 열고 있어요.', title_nl = 'Cervix (baarmoedermond) 🗝️', body_nl = 'Er wordt in het geheim gewerkt! De baarmoedermond wordt zachter, dunner en gaat open. Ook al voel je het niet, je lichaam zet de deur voor mij open.', title_pl = 'Szyjka macicy 🗝️', body_pl = 'Trwa tajna praca! Szyjka macicy mięknie, skraca się i otwiera. Choć tego nie czujesz, twoje ciało otwiera przede mną drzwi.', title_pt = 'O colo do útero 🗝️', body_pt = 'Há um trabalho secreto em curso! O colo do útero está a amolecer, a adelgaçar e a abrir. Mesmo que não sinta, o seu corpo está a abrir-me a porta.', title_sv = 'Cervix (livmoderhalsen) 🗝️', body_sv = 'Ett hemligt arbete pågår! Livmoderhalsen mjukas upp, tunnas ut och öppnar sig. Även om du inte känner det öppnar kroppen dörren för mig.', title_vi = 'Cổ tử cung 🗝️', body_vi = 'Một nhiệm vụ bí mật đang diễn ra! Cổ tử cung đang mềm ra, mỏng đi và mở dần. Dù mẹ không cảm nhận được, cơ thể mẹ đang mở cánh cửa đón con.', title_zh = '宫颈 🗝️', body_zh = '秘密任务进行中！宫颈正在变软、变薄并打开。虽然你感觉不到，你的身体正在为我打开大门。' WHERE id = 'c87d28dc-caee-4571-989c-8e696b1ae968' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Hoy es el día? 🗓️', body_es = '¡Se han cumplido 40 semanas! El calendario marca hoy. ¿Vengo ya o me hago un poco más de rogar? ¡Puedo darte una sorpresa en cualquier momento! ¡Prepárate! 🎁', title_fr = 'C''est le jour J ? 🗓️', body_fr = '40 semaines tout rond ! Le calendrier indique aujourd''hui. J''arrive, ou je me fais encore un peu désirer ? Je peux vous surprendre à tout moment ! Soyez prête ! 🎁', title_hi = 'क्या आज वही दिन है? 🗓️', body_hi = '40 हफ़्ते पूरे हो गए! कैलेंडर आज का दिन दिखा रहा है। आऊँ, या थोड़े नखरे और करूँ? मैं कभी भी सरप्राइज़ दे सकता हूँ! तैयार रहिए! 🎁', title_id = 'Apakah hari ini harinya? 🗓️', body_id = 'Genap 40 minggu! Kalender menunjuk hari ini. Aku datang, atau sedikit jual mahal dulu? Aku bisa memberi kejutan kapan saja! Bersiaplah! 🎁', title_ja = '今日がその日？🗓️', body_ja = '40週になったよ！カレンダーは今日を指しているね。もう出ていこうかな、それとももう少しじらそうかな？いつサプライズしてもおかしくないよ！準備してね！🎁', title_ko = '오늘이 그날일까요? 🗓️', body_ko = '40주가 꽉 찼어요! 달력은 오늘을 가리켜요. 지금 갈까요, 아니면 조금 더 애태울까요? 언제든 깜짝 등장할 수 있어요! 준비하세요! 🎁', title_nl = 'Is het vandaag zover? 🗓️', body_nl = '40 weken zijn voorbij! De kalender wijst vandaag aan. Kom ik nu, of laat ik je nog even wachten? Ik kan je elk moment verrassen! Wees er klaar voor! 🎁', title_pl = 'Czy to dziś? 🗓️', body_pl = 'Minęło 40 tygodni! Kalendarz wskazuje dzisiejszy dzień. Przychodzę, czy jeszcze trochę się podroczę? W każdej chwili mogę zrobić niespodziankę! Bądź gotowa! 🎁', title_pt = 'Hoje é o dia? 🗓️', body_pt = 'Completaram-se 40 semanas! O calendário marca hoje. Venho já ou faço-me esperar mais um pouco? Posso fazer uma surpresa a qualquer momento! Esteja pronta! 🎁', title_sv = 'Är det i dag? 🗓️', body_sv = '40 veckor har gått! Kalendern visar i dag. Kommer jag nu eller ska jag spela svårflirtad lite till? Jag kan överraska när som helst! Var redo! 🎁', title_vi = 'Hôm nay là ngày ấy? 🗓️', body_vi = 'Đã tròn 40 tuần! Lịch chỉ đúng hôm nay. Con ra ngay, hay làm nũng thêm chút nữa? Con có thể tạo bất ngờ bất cứ lúc nào! Sẵn sàng nhé! 🎁', title_zh = '今天就是那一天吗？🗓️', body_zh = '满40周啦！日历指向了今天。我是现在就来，还是再撒会儿娇？我随时可能给你惊喜！做好准备！🎁' WHERE id = '76e46ae6-114d-4692-9572-4e285ec80590' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡No llego tarde! 👑', body_es = '¡Es que las estrellas salen las últimas al escenario, mamá! Me haré un poco de rogar y luego llegaré. ¡Paciencia! 😌', title_fr = 'Je ne suis pas en retard ! 👑', body_fr = 'Ce sont les stars qui montent sur scène en dernier, Maman ! Je me fais encore un peu désirer, puis j''arrive. Patience ! 😌', title_hi = 'मैं लेट नहीं हुआ! 👑', body_hi = 'बस सितारे मंच पर सबसे आखिर में आते हैं, माँ! थोड़े नखरे और करूँगा, फिर आ जाऊँगा। धैर्य रखिए! 😌', title_id = 'Aku tidak terlambat! 👑', body_id = 'Para bintang memang selalu tampil paling akhir, Bunda! Aku jual mahal sebentar lagi, lalu aku datang. Bersabarlah! 😌', title_ja = '遅れてなんかいないよ！👑', body_ja = 'スターは最後に登場するものなんだよ、ママ！もう少しだけじらしたら、行くからね。待っててね！😌', title_ko = '저 늦은 거 아니에요! 👑', body_ko = '스타는 원래 마지막에 무대에 오르거든요, 엄마! 조금만 더 애태우고 갈게요. 조금만 기다려 주세요! 😌', title_nl = 'Ik ben niet te laat! 👑', body_nl = 'Sterren komen gewoon als laatste op, mama! Ik laat je nog even wachten, daarna kom ik. Heb geduld! 😌', title_pl = 'Nie spóźniam się! 👑', body_pl = 'Po prostu gwiazdy wchodzą na scenę ostatnie, Mamo! Jeszcze trochę się podroczę, a potem przyjdę. Bądź cierpliwa! 😌', title_pt = 'Não estou atrasado! 👑', body_pt = 'As estrelas são sempre as últimas a entrar em cena, Mamã! Vou fazer-me esperar mais um pouco e depois chego. Tenha paciência! 😌', title_sv = 'Jag är inte sen! 👑', body_sv = 'Det är bara stjärnorna som kliver in på scenen sist, mamma! Jag spelar svårflirtad lite till, sedan kommer jag. Ha tålamod! 😌', title_vi = 'Con không đến muộn đâu! 👑', body_vi = 'Chỉ là Ngôi sao luôn xuất hiện sau cùng thôi, mẹ ơi! Con làm nũng thêm chút nữa rồi sẽ ra. Kiên nhẫn nhé! 😌', title_zh = '我没有迟到！👑', body_zh = '妈妈，明星总是最后登场！让我再撒会儿娇，然后就来。要有耐心哦！😌' WHERE id = '98686d18-af97-4647-942d-188f1dec2753' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¡Es que estoy engordando! ⚖️', body_es = 'Cada día que me quedo aquí, me pongo un poco más rellenito. Mis mofletes se vuelven más dulces, pero tu trabajo se complica. ¡Perdona! 🙈', title_fr = 'C''est que je grossis ! ⚖️', body_fr = 'Chaque jour passé ici me rend un peu plus potelé. Mes joues deviennent adorables, mais votre tâche devient plus difficile. Pardon ! 🙈', title_hi = 'मैं तो मोटा हो रहा हूँ! ⚖️', body_hi = 'यहाँ रहने के हर दिन के साथ मैं थोड़ा और गोल-मटोल हो रहा हूँ। मेरे गाल और प्यारे हो रहे हैं, पर आपका काम मुश्किल हो रहा है। माफ़ करना! 🙈', title_id = 'Aku kan sedang menambah berat badan! ⚖️', body_id = 'Setiap hari aku di sini, aku makin montok. Pipiku makin menggemaskan, tapi tugas Anda makin berat. Maaf ya! 🙈', title_ja = 'だって、ふっくらしてきてるんだもん！⚖️', body_ja = 'ここにいる毎日で、少しずつぷくぷくになっているの。ほっぺはかわいくなるけど、ママは大変になっちゃう。ごめんね！🙈', title_ko = '저 살이 찌고 있잖아요! ⚖️', body_ko = '여기 하루 더 있을 때마다 조금씩 더 통통해져요. 제 볼은 더 귀여워지지만 엄마는 더 힘들어지죠. 미안해요! 🙈', title_nl = 'Ik word steeds molliger! ⚖️', body_nl = 'Elke dag dat ik hier blijf, word ik een beetje molliger. Mijn wangetjes worden schattiger, maar voor jou wordt het zwaarder. Sorry! 🙈', title_pl = 'Przecież przybieram na wadze! ⚖️', body_pl = 'Każdego dnia tutaj robię się trochę bardziej pulchne. Moje policzki są coraz słodsze, ale tobie jest coraz trudniej. Przepraszam! 🙈', title_pt = 'Afinal, estou a engordar! ⚖️', body_pt = 'Cada dia que fico aqui, fico um pouco mais gordinho. As minhas bochechas ficam mais fofas, mas a sua tarefa fica mais difícil. Desculpe! 🙈', title_sv = 'Jag blir ju rundare! ⚖️', body_sv = 'För varje dag jag stannar här blir jag lite knubbigare. Mina kinder blir sötare, men ditt jobb blir tyngre. Förlåt! 🙈', title_vi = 'Con đang tăng cân mà! ⚖️', body_vi = 'Mỗi ngày ở lại đây, con lại bụ bẫm hơn một chút. Má con đáng yêu hơn, nhưng việc của mẹ khó hơn. Xin lỗi mẹ! 🙈', title_zh = '我在长胖嘛！⚖️', body_zh = '我在这里多待一天，就更胖嘟嘟一点。我的脸蛋越来越可爱，你却越来越辛苦。对不起！🙈' WHERE id = '0247f27e-7ddb-489d-b670-ca491d8ccd50' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Has metido algo de picar en la bolsa? 🍫', body_es = '¡Después del parto tendrás mucha hambre! Añade a la Bolsa del hospital tus galletas o tu chocolate favorito.', title_fr = 'Vous avez mis un en-cas dans le sac ? 🍫', body_fr = 'Vous aurez très faim après l''accouchement ! Ajoutez vos biscuits ou votre chocolat préférés à la Valise de maternité.', title_hi = 'बैग में स्नैक्स रखे? 🍫', body_hi = 'डिलीवरी के बाद आपको बहुत भूख लगेगी! हॉस्पिटल बैग में अपने पसंदीदा बिस्किट या चॉकलेट रख लीजिए।', title_id = 'Sudah memasukkan camilan ke tas? 🍫', body_id = 'Setelah melahirkan Anda akan sangat lapar! Tambahkan biskuit atau cokelat favorit Anda ke Tas Rumah Sakit.', title_ja = 'バッグにおやつは入れた？🍫', body_ja = '産後はとてもお腹がすきますよ！「入院バッグ」に好きなクッキーやチョコレートを加えましょう。', title_ko = '가방에 간식 넣으셨어요? 🍫', body_ko = '출산 후에는 엄청 배고플 거예요! 출산 가방에 좋아하는 쿠키나 초콜릿을 넣어 두세요.', title_nl = 'Iets lekkers in je tas gedaan? 🍫', body_nl = 'Na de bevalling heb je flinke honger! Doe je favoriete koekjes of chocolade in je Ziekenhuistas.', title_pl = 'Spakowałaś przekąskę? 🍫', body_pl = 'Po porodzie będziesz bardzo głodna! Dodaj do Torby do szpitala ulubione ciastka lub czekoladę.', title_pt = 'Pôs snacks na mala? 🍫', body_pt = 'Depois do parto vai ter muita fome! Junte à Mala da Maternidade as suas bolachas ou o chocolate de que mais gosta.', title_sv = 'Har du packat snacks i väskan? 🍫', body_sv = 'Du kommer att bli väldigt hungrig efter förlossningen! Lägg till dina favoritkex eller choklad i BB-väskan.', title_vi = 'Mẹ đã cho đồ ăn vặt vào túi chưa? 🍫', body_vi = 'Sau khi sinh mẹ sẽ đói lắm đấy! Hãy thêm bánh quy hoặc sô-cô-la mẹ thích vào Túi đồ đi sinh.', title_zh = '包里放零食了吗？🍫', body_zh = '生完宝宝你会非常饿！在待产包里放些你喜欢的饼干或巧克力吧。' WHERE id = '87267b60-6c8e-4a16-ba93-8c4128e465bd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Envejece la placenta? 🍂', body_es = '¿El médico revisa la cantidad de líquido? Si sigo recibiendo oxígeno, no hay problema. Son solo nuestros últimos días.', title_fr = 'Le placenta vieillit ? 🍂', body_fr = 'Le médecin vérifie la quantité de liquide ? Si je reçois toujours de l''oxygène, il n''y a pas de problème. Ce sont simplement nos derniers jours.', title_hi = 'प्लेसेंटा पुराना हो रहा है? 🍂', body_hi = 'डॉक्टर पानी की मात्रा जाँच रहे हैं? अगर मुझे अभी भी ऑक्सीजन मिल रही है, तो कोई समस्या नहीं। ये बस हमारे आखिरी दिन हैं।', title_id = 'Plasenta menua? 🍂', body_id = 'Dokter memeriksa jumlah air ketuban? Jika oksigen masih sampai kepadaku, berarti tidak ada masalah. Ini hanya hari-hari terakhir kita.', title_ja = '胎盤が老化している？🍂', body_ja = 'お医者さんが羊水の量を確認してる？わたしにまだ酸素が届いていれば、問題ないよ。ただ、最後の日々を過ごしているだけ。', title_ko = '태반이 노화하고 있나요? 🍂', body_ko = '의사 선생님이 양수량을 확인하나요? 저에게 산소가 계속 오고 있다면 문제없어요. 그저 우리의 마지막 날들이에요.', title_nl = 'Veroudert de placenta? 🍂', body_nl = 'Controleert de arts de hoeveelheid vruchtwater? Zolang ik nog zuurstof krijg, is er geen probleem. Het zijn gewoon onze laatste dagen.', title_pl = 'Łożysko się starzeje? 🍂', body_pl = 'Lekarz sprawdza ilość wód? Jeśli wciąż dociera do mnie tlen, nie ma problemu. To po prostu nasze ostatnie dni.', title_pt = 'A placenta está a envelhecer? 🍂', body_pt = 'O médico está a verificar a quantidade de líquido? Se ainda recebo oxigénio, não há problema. São só os nossos últimos dias.', title_sv = 'Åldras moderkakan? 🍂', body_sv = 'Kontrollerar läkaren mängden fostervatten? Så länge jag får syre är det inga problem. Det är bara våra sista dagar.', title_vi = 'Bánh nhau đang lão hóa? 🍂', body_vi = 'Bác sĩ đang kiểm tra lượng nước ối? Nếu con vẫn nhận đủ oxy thì không có vấn đề gì. Chỉ là những ngày cuối của chúng mình thôi.', title_zh = '胎盘在老化？🍂', body_zh = '医生在检查羊水量吗？只要我还能得到氧气，就没有问题。这只是我们最后的几天。' WHERE id = '8ec6da93-6997-4754-83f8-6c1f12fd0335' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Te dieron contracciones por la noche? 🌙', body_es = 'Ese dolor que te despierta... ¿Es de verdad? No pierdas tiempo, pon en marcha el Contador de contracciones. ¡Quizá esta noche sea LA NOCHE! 🚑', title_fr = 'Une contraction cette nuit ? 🌙', body_fr = 'Cette douleur qui vous réveille... C''est la vraie ? Ne perdez pas de temps, lancez le Minuteur de contractions. Cette nuit est peut-être LA NUIT ! 🚑', title_hi = 'रात में दर्द उठा? 🌙', body_hi = 'नींद से जगाने वाला वह दर्द... क्या असली है? समय बर्बाद मत कीजिए, कॉन्ट्रैक्शन टाइमर चालू कीजिए। शायद आज की रात वही रात है! 🚑', title_id = 'Kontraksi di malam hari? 🌙', body_id = 'Rasa sakit yang membangunkan Anda... Apakah asli? Jangan buang waktu, nyalakan Pengukur Kontraksi. Mungkin malam ini adalah MALAM ITU! 🚑', title_ja = '夜中に陣痛が来た？🌙', body_ja = '眠りから起こされるあの痛み...本物？迷わず「陣痛タイマー」をスタートしてね。今夜が「その夜」かも！🚑', title_ko = '밤에 진통이 왔나요? 🌙', body_ko = '잠을 깨우는 그 통증... 진짜일까요? 시간 낭비하지 말고 진통 측정기를 켜세요. 어쩌면 오늘 밤이 바로 그 밤이에요! 🚑', title_nl = 'Kreeg je vannacht weeën? 🌙', body_nl = 'Die pijn die je wakker maakt... Is het echt? Verlies geen tijd en start de Weeënteller. Misschien is vannacht DE NACHT! 🚑', title_pl = 'Złapały cię skurcze w nocy? 🌙', body_pl = 'Ten ból, który budzi cię ze snu... Czy to prawdziwe? Nie trać czasu, włącz Licznik skurczów. Może to właśnie TA NOC! 🚑', title_pt = 'Teve contrações à noite? 🌙', body_pt = 'Aquela dor que a acorda... É verdadeira? Não perca tempo, ligue o Contador de Contrações. Talvez esta noite seja A NOITE! 🚑', title_sv = 'Fick du värkar i natt? 🌙', body_sv = 'Smärtan som väckte dig... Är den på riktigt? Slösa inte tid, starta Värkmätaren. Kanske är det i natt det händer! 🚑', title_vi = 'Đêm qua mẹ bị co thắt? 🌙', body_vi = 'Cơn đau làm mẹ tỉnh giấc... Có phải thật không? Đừng chần chừ, hãy bật Đo cơn co. Biết đâu đêm nay chính là ĐÊM ẤY! 🚑', title_zh = '夜里宫缩了？🌙', body_zh = '把你从睡梦中疼醒的感觉……是真的吗？别耽误时间，打开宫缩计时器。也许今晚就是那一晚！🚑' WHERE id = '5b55999e-5ad0-4f78-afa8-f94623d8adca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Ha llegado la orden de evacuación? 📢', body_es = '¿El médico habla de inducir el parto? Tranquila. Lo importante es que llegue sano y salvo a tus brazos. ¡El camino da igual!', title_fr = 'L''ordre d''évacuation est arrivé ? 📢', body_fr = 'Le médecin parle de déclenchement ? N''ayez pas peur. L''essentiel, c''est que j''arrive sain et sauf dans vos bras. Peu importe le chemin !', title_hi = 'निकलने का आदेश आ गया? 📢', body_hi = 'डॉक्टर इंड्यूस करने की बात कर रहे हैं? घबराइए मत। सबसे ज़रूरी है कि मैं सही-सलामत आपकी गोद में आऊँ। रास्ता मायने नहीं रखता!', title_id = 'Perintah evakuasi sudah datang? 📢', body_id = 'Dokter menyarankan induksi? Jangan takut. Yang terpenting aku tiba di pelukan Anda dengan selamat. Jalannya tidak masalah!', title_ja = '出動命令が来た？📢', body_ja = 'お医者さんが陣痛促進って言ってる？怖がらないで。大切なのは、わたしが無事にママの腕の中に来ること。どんな道でもかまわないよ！', title_ko = '대피 명령이 내려졌나요? 📢', body_ko = '의사 선생님이 유도분만을 이야기하나요? 걱정 마세요. 중요한 건 제가 무사히 엄마 품에 오는 거예요. 어떤 길이든 상관없어요!', title_nl = 'Tijd om te vertrekken? 📢', body_nl = 'Heeft de arts het over inleiden? Wees niet bang. Het belangrijkste is dat ik veilig in je armen kom. Hoe maakt niet uit!', title_pl = 'Przyszedł rozkaz ewakuacji? 📢', body_pl = 'Lekarz mówi o indukcji porodu? Nie bój się. Najważniejsze, żebym bezpiecznie trafiło w twoje ramiona. Droga nie ma znaczenia!', title_pt = 'Chegou a ordem de evacuação? 📢', body_pt = 'O médico fala em indução do parto? Não tenha medo. O mais importante é eu chegar são e salvo aos seus braços. O caminho não importa!', title_sv = 'Har utrymningsordern kommit? 📢', body_sv = 'Pratar läkaren om igångsättning? Var inte rädd. Det viktigaste är att jag kommer välbehållen till din famn. Vägen spelar ingen roll!', title_vi = 'Đã có lệnh xuất phát? 📢', body_vi = 'Bác sĩ nói đến khởi phát chuyển dạ? Đừng sợ. Điều quan trọng là con đến với vòng tay mẹ bình an. Con đường nào cũng được!', title_zh = '撤离命令来了？📢', body_zh = '医生说要催产？别害怕。最重要的是我平平安安地来到你怀里。哪条路都一样！' WHERE id = '1f7612ce-6ffd-41c2-b5d1-de2a40214c65' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Tu última foto de embarazada... 📸', body_es = 'Mira esta barriga por última vez. Quizá mañana ya esté en tus brazos. ¡Siéntete orgullosa de tu cuerpo milagroso, mamá!', title_fr = 'Votre dernière photo de grossesse... 📸', body_fr = 'Regardez ce ventre une dernière fois. Demain, je serai peut-être dans vos bras. Soyez fière de votre corps miraculeux, Maman !', title_hi = 'आपकी आखिरी प्रेग्नेंसी फ़ोटो... 📸', body_hi = 'इस पेट को आखिरी बार देखिए। शायद कल मैं आपकी गोद में होऊँगा। अपने चमत्कारी शरीर पर गर्व कीजिए, माँ!', title_id = 'Foto kehamilan terakhir Anda... 📸', body_id = 'Lihatlah perut ini untuk terakhir kalinya. Besok mungkin aku sudah dalam pelukan Anda. Banggalah dengan tubuh ajaib Anda, Bunda!', title_ja = '最後のマタニティフォト... 📸', body_ja = 'このお腹を最後によく見ておいて。明日にはママの腕の中にいるかもしれないよ。奇跡の体を誇りに思ってね、ママ！', title_ko = '마지막 임신 사진... 📸', body_ko = '이 배를 마지막으로 바라보세요. 내일이면 제가 엄마 품에 있을지도 몰라요. 기적 같은 엄마의 몸을 자랑스러워하세요, 엄마!', title_nl = 'Je laatste zwangerschapsfoto... 📸', body_nl = 'Kijk nog één keer naar deze buik. Morgen lig ik misschien al in je armen. Wees trots op je wonderlijke lichaam, mama!', title_pl = 'Ostatnie ciążowe zdjęcie... 📸', body_pl = 'Spójrz ostatni raz na ten brzuch. Jutro może będę już w twoich ramionach. Bądź dumna ze swojego cudownego ciała, Mamo!', title_pt = 'A sua última foto de grávida... 📸', body_pt = 'Olhe uma última vez para esta barriga. Amanhã talvez já esteja no seu colo. Orgulhe-se deste corpo milagroso, Mamã!', title_sv = 'Ditt sista gravidfoto... 📸', body_sv = 'Titta på den här magen en sista gång. I morgon kanske jag ligger i din famn. Var stolt över din mirakulösa kropp, mamma!', title_vi = 'Tấm ảnh bầu cuối cùng của mẹ... 📸', body_vi = 'Hãy nhìn chiếc bụng này lần cuối. Ngày mai có lẽ con đã nằm trong vòng tay mẹ. Hãy tự hào về cơ thể kỳ diệu của mình, mẹ ơi!', title_zh = '最后一张孕期照片……📸', body_zh = '最后再看一眼这个肚子吧。也许明天我就在你怀里了。妈妈，为你神奇的身体感到骄傲吧！' WHERE id = '4f2c691b-071d-4e41-bb69-0e7f415e73df' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Una ayuda natural 🍍', body_es = 'Se dice que los dátiles y la piña ablandan el cuello del útero. Añádelos hoy a tu menú desde la sección Nutrición. 🥗', title_fr = 'Un coup de pouce naturel 🍍', body_fr = 'On dit que les dattes et l''ananas ramollissent le col de l''utérus. Ajoutez-les à votre menu aujourd''hui grâce à la rubrique Nutrition. 🥗', title_hi = 'प्राकृतिक तरीके से मदद 🍍', body_hi = 'कहा जाता है कि खजूर और अनानास गर्भाशय ग्रीवा को नरम करते हैं। आज पोषण सेक्शन से इन्हें अपने मेन्यू में जोड़िए। 🥗', title_id = 'Bantuan dengan cara alami 🍍', body_id = 'Kurma dan nanas konon dapat melunakkan leher rahim. Tambahkan ke menu Anda hari ini lewat bagian Nutrisi. 🥗', title_ja = '自然な方法でサポート 🍍', body_ja = 'デーツやパイナップルは子宮口をやわらかくすると言われています。「栄養」セクションで、今日のメニューに加えてみましょう。🥗', title_ko = '자연스러운 방법으로 도와요 🍍', body_ko = '대추야자와 파인애플이 자궁경부를 부드럽게 한다고 해요. 영양 섹션에서 오늘 식단에 추가해 보세요. 🥗', title_nl = 'Natuurlijke hulp 🍍', body_nl = 'Van dadels en ananas wordt gezegd dat ze de baarmoedermond zachter maken. Zet ze vandaag op je menu in het onderdeel Voeding. 🥗', title_pl = 'Naturalna pomoc 🍍', body_pl = 'Mówi się, że daktyle i ananas zmiękczają szyjkę macicy. Dodaj je dziś do menu w sekcji Odżywianie. 🥗', title_pt = 'Uma ajuda natural 🍍', body_pt = 'Diz-se que as tâmaras e o ananás amolecem o colo do útero. Junte-os hoje ao seu menu com a secção Nutrição. 🥗', title_sv = 'Naturlig hjälp 🍍', body_sv = 'Det sägs att dadlar och ananas mjukar upp livmoderhalsen. Lägg till dem i din meny i dag i Kost-avsnittet. 🥗', title_vi = 'Hỗ trợ theo cách tự nhiên 🍍', body_vi = 'Người ta nói chà là và dứa giúp làm mềm cổ tử cung. Hôm nay hãy thêm chúng vào thực đơn trong mục Dinh dưỡng nhé. 🥗', title_zh = '自然的助力 🍍', body_zh = '据说椰枣和菠萝能让宫颈变软。在营养板块把它们加入你今天的菜单吧。🥗' WHERE id = 'e6c910e7-1cd4-4a57-af91-421a76624e12' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Latidos del corazón... ❤️', body_es = 'Pasadas las 40 semanas, la monitorización (NST) es importante para revisar el estado de la placenta. Asegúrate de que todo va bien.', title_fr = 'Les battements de cœur... ❤️', body_fr = 'Après 40 semaines, un monitoring (NST) est important pour vérifier l''état du placenta. Assurez-vous que tout va bien.', title_hi = 'दिल की धड़कनें... ❤️', body_hi = '40 हफ़्ते पार होने पर प्लेसेंटा की स्थिति जाँचने के लिए CTG (NST) जाँच ज़रूरी है। पक्का कर लीजिए कि सब ठीक है।', title_id = 'Detak jantung... ❤️', body_id = 'Setelah lewat 40 minggu, pemeriksaan CTG (NST) penting untuk memeriksa kondisi plasenta. Pastikan semuanya baik-baik saja.', title_ja = '心臓の音... ❤️', body_ja = '40週を過ぎたら、胎盤の状態を確認するためにNST検査が大切です。すべて順調か確認しましょう。', title_ko = '심장 박동... ❤️', body_ko = '40주가 지나면 태반 상태를 확인하기 위해 태동 검사(NST)가 중요해요. 모든 게 괜찮은지 확인하세요.', title_nl = 'Hartslagen... ❤️', body_nl = 'Na 40 weken is een CTG belangrijk om de toestand van de placenta te controleren. Zorg dat je zeker weet dat alles in orde is.', title_pl = 'Bicie serca... ❤️', body_pl = 'Po 40. tygodniu ważne jest badanie KTG, by sprawdzić stan łożyska. Upewnij się, że wszystko jest w porządku.', title_pt = 'Os batimentos do coração... ❤️', body_pt = 'Depois das 40 semanas, é importante fazer um CTG (NST) para verificar o estado da placenta. Certifique-se de que está tudo bem.', title_sv = 'Hjärtslag... ❤️', body_sv = 'Efter 40 veckor är en CTG-undersökning viktig för att kontrollera moderkakans tillstånd. Se till att allt är som det ska.', title_vi = 'Nhịp tim... ❤️', body_vi = 'Khi đã qua 40 tuần, đo tim thai bằng máy CTG (NST) rất quan trọng để kiểm tra tình trạng bánh nhau. Hãy chắc chắn mọi thứ đều ổn.', title_zh = '心跳声……❤️', body_zh = '过了40周，做胎心监护（NST）检查胎盘的状况很重要。确认一切正常。' WHERE id = '0b2b54c8-9ff4-43bd-80a3-8a3a373a1975' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = '¿Subimos escaleras? 🪜', body_es = '¡Indícame el camino! Subir escaleras o hacer sentadillas puede ayudarme a bajar. Mira la sección Ejercicios.', title_fr = 'On monte les escaliers ? 🪜', body_fr = 'Montrez-moi le chemin ! Monter les escaliers ou faire des squats peut m''aider à descendre. Jetez un œil à la rubrique Exercices.', title_hi = 'सीढ़ियाँ चढ़ें? 🪜', body_hi = 'मुझे रास्ता दिखाइए! सीढ़ियाँ चढ़ना या स्क्वैट करना मुझे नीचे खिसका सकता है। एक्सरसाइज़ सेक्शन देखिए।', title_id = 'Naik tangga yuk? 🪜', body_id = 'Tunjukkan jalannya padaku! Naik tangga atau squat bisa membantuku turun. Lihat bagian Latihan.', title_ja = '階段を上ってみる？🪜', body_ja = '道を教えて！階段の上り下りやスクワットで、わたしが下に降りやすくなるかも。「エクササイズ」セクションを見てね。', title_ko = '계단 올라가 볼까요? 🪜', body_ko = '저에게 길을 안내해 주세요! 계단 오르기나 스쿼트가 제가 내려가는 데 도움이 될 수 있어요. 운동 섹션을 확인해 보세요.', title_nl = 'Zullen we de trap op gaan? 🪜', body_nl = 'Wijs me de weg! Traplopen of squatten kan me helpen zakken. Kijk in het onderdeel Oefeningen.', title_pl = 'Pochodzimy po schodach? 🪜', body_pl = 'Wskaż mi drogę! Chodzenie po schodach lub przysiady mogą pomóc mi zejść niżej. Zajrzyj do sekcji Ćwiczenia.', title_pt = 'Vamos subir escadas? 🪜', body_pt = 'Mostre-me o caminho! Subir escadas ou fazer agachamentos pode ajudar-me a descer. Veja a secção Exercícios.', title_sv = 'Ska vi gå i trappor? 🪜', body_sv = 'Visa mig vägen! Att gå i trappor eller göra knäböj kan hjälpa mig att glida nedåt. Titta i avsnittet Träning.', title_vi = 'Leo cầu thang nhé? 🪜', body_vi = 'Chỉ đường cho con nào! Leo cầu thang hoặc squat có thể giúp con xuống thấp. Xem mục Bài tập nhé.', title_zh = '去爬爬楼梯？🪜', body_zh = '给我指路吧！爬楼梯或深蹲可以帮我往下走。看看运动板块吧。' WHERE id = '52d95173-f625-471a-8fd4-bc36c2714133' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.pregnancy_day_notifications SET title_es = 'Aquí dentro se está muy bien 🌡️', body_es = 'Calentito, oscuro y cómodo... Si te digo que no quiero salir, ¿no te enfadarás? 🥺 ¡Es broma, ya voy!', title_fr = 'On est vraiment bien ici 🌡️', body_fr = 'Chaud, sombre et confortable... Vous ne m''en voudrez pas si je dis que je ne veux pas sortir ? 🥺 Je plaisante, j''arrive !', title_hi = 'यहाँ मौसम बहुत अच्छा है 🌡️', body_hi = 'गर्म, अँधेरा और आरामदायक... अगर मैं कहूँ कि बाहर नहीं आना चाहता, तो आप नाराज़ तो नहीं होंगी? 🥺 मज़ाक कर रहा हूँ, आ रहा हूँ!', title_id = 'Di sini cuacanya sangat nyaman 🌡️', body_id = 'Hangat, gelap, dan nyaman... Anda tidak marah kan kalau aku bilang tidak mau keluar? 🥺 Bercanda, aku datang!', title_ja = 'ここはとっても快適だよ 🌡️', body_ja = '温かくて、暗くて、心地いい...出たくないって言ったら、怒る？🥺 冗談だよ、今行くね！', title_ko = '여기 날씨가 아주 좋아요 🌡️', body_ko = '따뜻하고, 어둡고, 아늑해요... 나가기 싫다고 하면 화내지 않을 거죠? 🥺 농담이에요, 갈게요!', title_nl = 'Het is hier heerlijk 🌡️', body_nl = 'Warm, donker en knus... Word je boos als ik zeg dat ik er niet uit wil? 🥺 Grapje, ik kom eraan!', title_pl = 'Tutaj jest bardzo przyjemnie 🌡️', body_pl = 'Ciepło, ciemno i wygodnie... Nie pogniewasz się, jeśli powiem, że nie chcę wychodzić? 🥺 Żartuję, już idę!', title_pt = 'Aqui o tempo está ótimo 🌡️', body_pt = 'Quentinho, escuro e confortável... Não se zanga se eu disser que não quero sair, pois não? 🥺 Estou a brincar, já vou!', title_sv = 'Här inne är det jätteskönt 🌡️', body_sv = 'Varmt, mörkt och mysigt... Blir du inte arg om jag säger att jag inte vill komma ut? 🥺 Skojar bara, jag kommer!', title_vi = 'Trong này dễ chịu lắm 🌡️', body_vi = 'Ấm áp, tối và thoải mái... Nếu con nói con không muốn ra, mẹ có giận con không? 🥺 Con đùa thôi, con đến đây!', title_zh = '这里的“天气”真好 🌡️', body_zh = '温暖、黑暗又舒适……如果我说不想出来，你不会生气吧？🥺 开玩笑的，我来啦！' WHERE id = 'c54d6aec-cbfd-44de-8deb-f24fc551c345' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El aire fresco os sentará bien a los dos. 🌳', title_fr = 'L''air frais vous fera du bien à tous les deux. 🌳', title_hi = 'ताज़ी हवा आप दोनों के लिए अच्छी रहेगी। 🌳', title_id = 'Udara segar akan baik untuk Anda berdua. 🌳', title_ja = '新鮮な空気は2人にとっていいことです。🌳', title_ko = '맑은 공기는 두 사람 모두에게 좋아요. 🌳', title_nl = 'Frisse lucht doet jullie allebei goed. 🌳', title_pl = 'Świeże powietrze dobrze wam obojgu zrobi. 🌳', title_pt = 'O ar puro vai fazer bem aos dois. 🌳', title_sv = 'Frisk luft gör er båda gott. 🌳', title_vi = 'Không khí trong lành tốt cho cả hai mẹ con. 🌳', title_zh = '新鲜空气对你们俩都有好处。🌳' WHERE id = '0e6fe355-3307-4562-8e24-f479625f3ff6' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ropa que desafía la lógica 👗', title_fr = 'Des tenues illogiques 👗', title_hi = 'उलझन भरे कपड़े 👗', title_id = 'Pakaian yang membingungkan 👗', title_ja = '迷ってしまう服装 👗', title_ko = '엉뚱한 옷차림 👗', title_nl = 'Onlogische kleding 👗', title_pl = 'Ubrania wbrew logice 👗', title_pt = 'Roupa sem lógica 👗', title_sv = 'Kläder som trotsar logiken 👗', title_vi = 'Mặc đồ trái lẽ thường 👗', title_zh = '不合逻辑的穿衣 👗' WHERE id = '4085929a-ec71-4c5c-a693-62bb796910ba' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Silencio inteligente 🤫', body_es = '¿Los ruidos repentinos le despiertan cuando se está durmiendo? Controla el límite de decibelios de la habitación con el Medidor de sonido.', title_fr = 'Un silence intelligent 🤫', body_fr = 'Les bruits soudains le réveillent quand il s''endort ? Surveillez la limite de décibels de la pièce avec le Sonomètre.', title_hi = 'स्मार्ट खामोशी 🤫', body_hi = 'सोते समय अचानक की आवाज़ें उसे जगा देती हैं? साउंड मीटर से कमरे की डेसिबल सीमा पर नज़र रखिए।', title_id = 'Keheningan cerdas 🤫', body_id = 'Suara tiba-tiba membangunkannya saat hendak tidur? Pantau batas desibel kamar dengan Pengukur Suara.', title_ja = 'かしこい静けさ 🤫', body_ja = '寝入りばなに急な物音で起きてしまう？「サウンドメーター」で部屋の音量の上限をチェックしましょう。', title_ko = '똑똑한 고요함 🤫', body_ko = '잠들 때 갑작스러운 소리에 깨나요? 소음 측정기로 방의 데시벨 한도를 관리하세요.', title_nl = 'Slimme stilte 🤫', body_nl = 'Wordt je baby wakker van plotselinge geluiden als hij in slaap valt? Houd met de Geluidsmeter de decibelgrens in de kamer in de gaten.', title_pl = 'Mądra cisza 🤫', body_pl = 'Nagłe dźwięki budzą je, gdy zasypia? Kontroluj limit decybeli w pokoju z Miernikiem dźwięku.', title_pt = 'Silêncio inteligente 🤫', body_pt = 'Quando está a adormecer, os sons repentinos acordam-no? Controle o limite de decibéis do quarto com o Medidor de Som.', title_sv = 'Smart tystnad 🤫', body_sv = 'Väcks barnet av plötsliga ljud när det håller på att somna? Håll koll på decibelgränsen i rummet med Ljudmätaren.', title_vi = 'Sự yên tĩnh thông minh 🤫', body_vi = 'Khi bé đang vào giấc, những tiếng động đột ngột làm bé thức? Hãy dùng Đo âm thanh để kiểm soát ngưỡng decibel trong phòng.', title_zh = '智能安静 🤫', body_zh = '宝宝快睡着时，突然的声音会把宝宝吵醒？用分贝仪监控房间的分贝限度。' WHERE id = 'e7ddb2bb-cbd6-4f99-9f52-7fc0bb34e7ba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lo cojo yo solo! 🧸', body_es = '¿Estira la mano con precisión hacia los juguetes colgantes? Su coordinación ojo-mano se fortalece. Anímale con objetos de distintos colores.', title_fr = 'Je vais l''attraper tout seul ! 🧸', body_fr = 'Il tend la main avec précision vers les jouets suspendus ? Sa coordination œil-main se renforce. Encouragez-le avec des objets de différentes couleurs.', title_hi = 'मैं खुद पकड़ूँगा! 🧸', body_hi = 'लटके खिलौनों की ओर बिल्कुल सही हाथ बढ़ाता है? आँख और हाथ का तालमेल मज़बूत हो रहा है। अलग-अलग रंगों की चीज़ों से उसका हौसला बढ़ाइए।', title_id = 'Aku pegang sendiri! 🧸', body_id = 'Ia meraih mainan gantung dengan sangat tepat? Koordinasi mata dan tangannya makin kuat. Semangati ia dengan benda-benda berwarna berbeda.', title_ja = '自分でつかむよ！🧸', body_ja = 'つり下げたおもちゃに、正確に手を伸ばしていますか？目と手の協調が強くなっています。いろいろな色のもので、やる気を引き出してあげましょう。', title_ko = '제가 잡을래요! 🧸', body_ko = '매달린 장난감에 정확하게 손을 뻗나요? 눈과 손의 협응력이 강해지고 있어요. 다양한 색의 물건으로 아기를 북돋아 주세요.', title_nl = 'Ik pak het zelf! 🧸', body_nl = 'Reikt je baby heel precies naar hangend speelgoed? De oog-handcoördinatie wordt sterker. Moedig hem aan met dingen in verschillende kleuren.', title_pl = 'Złapię to! 🧸', body_pl = 'Sięga po wiszące zabawki z pełną precyzją? Wzmacnia się koordynacja oko-ręka. Zachęcaj go przedmiotami w różnych kolorach.', title_pt = 'Eu é que agarro! 🧸', body_pt = 'Estica a mão com toda a precisão para os brinquedos pendurados? A coordenação olho-mão está a ficar mais forte. Estimule-o com objetos de cores diferentes.', title_sv = 'Jag håller själv! 🧸', body_sv = 'Sträcker sig barnet med full precision efter hängande leksaker? Koordinationen mellan öga och hand blir starkare. Uppmuntra med saker i olika färger.', title_vi = 'Con tự cầm! 🧸', body_vi = 'Bé với chính xác tới đồ chơi treo? Phối hợp tay và mắt đang mạnh hơn. Hãy khuyến khích bé bằng những đồ vật nhiều màu sắc.', title_zh = '我自己来抓！🧸', body_zh = '宝宝能准确地伸手去够挂着的玩具了？手眼协调能力在增强。用不同颜色的物品鼓励宝宝吧。' WHERE id = '3e7220fc-a665-4ed2-8b95-f202d84e92a8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Descubre sus manos! 👐', body_es = 'Ya puede llevarse las manos a la boca.', title_fr = 'Il découvre ses mains ! 👐', body_fr = 'Il peut déjà porter ses mains à sa bouche.', title_hi = 'अपने हाथ खोज रहा है! 👐', body_hi = 'वह अब अपने हाथ मुँह तक ले जा सकता है।', title_id = 'Ia menjelajahi tangannya! 👐', body_id = 'Ia kini sudah bisa memasukkan tangannya ke mulut.', title_ja = '手を発見しています！👐', body_ja = '赤ちゃんはもう手を口に持っていけるようになりました。', title_ko = '손을 발견하고 있어요! 👐', body_ko = '아기가 이제 손을 입으로 가져갈 수 있어요.', title_nl = 'Je baby ontdekt de handjes! 👐', body_nl = 'Je baby kan de handjes al naar het mondje brengen.', title_pl = 'Odkrywa swoje rączki! 👐', body_pl = 'Potrafi już wkładać rączki do buzi.', title_pt = 'Está a descobrir as mãos! 👐', body_pt = 'O bebé já consegue levar as mãos à boca.', title_sv = 'Barnet upptäcker sina händer! 👐', body_sv = 'Nu kan barnet föra händerna till munnen.', title_vi = 'Bé đang khám phá đôi tay! 👐', body_vi = 'Bé đã có thể đưa tay lên miệng.', title_zh = '宝宝在探索自己的小手！👐', body_zh = '宝宝已经能把小手放进嘴里了。' WHERE id = '756d2914-ecb6-4838-adb6-d312a4bc59a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Eres muy fuerte! ✨', body_es = 'Aunque a veces cueste, ¡eres una mamá increíble!', title_fr = 'Vous êtes si forte ! ✨', body_fr = 'Même si c''est parfois difficile, vous êtes une maman formidable !', title_hi = 'आप बहुत मज़बूत हैं! ✨', body_hi = 'भले कभी-कभी मुश्किल हो, आप एक शानदार माँ हैं!', title_id = 'Anda sangat kuat! ✨', body_id = 'Meski kadang sulit, Anda ibu yang luar biasa!', title_ja = 'あなたはとても強い人です！✨', body_ja = '大変なときもあるけれど、あなたはすばらしいママです！', title_ko = '엄마는 정말 강해요! ✨', body_ko = '가끔 힘들어도 엄마는 정말 멋진 엄마예요!', title_nl = 'Je bent zo sterk! ✨', body_nl = 'Ook al is het soms zwaar, je bent een geweldige mama!', title_pl = 'Jesteś bardzo silna! ✨', body_pl = 'Choć czasem jest trudno, jesteś wspaniałą mamą!', title_pt = 'É muito forte! ✨', body_pt = 'Mesmo que às vezes seja difícil, é uma mãe fantástica!', title_sv = 'Du är så stark! ✨', body_sv = 'Även om det ibland är svårt är du en fantastisk mamma!', title_vi = 'Mẹ thật mạnh mẽ! ✨', body_vi = 'Dù đôi khi khó khăn, mẹ vẫn là người mẹ tuyệt vời!', title_zh = '你非常坚强！✨', body_zh = '虽然有时很难，但你是一位了不起的妈妈！' WHERE id = 'c86bd995-9231-4eae-b8e0-8f84d6a46b62' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Sonrisas sociales! 😊', body_es = 'Su dulce sonrisa se lleva todo tu cansancio.', title_fr = 'Les sourires sociaux ! 😊', body_fr = 'Son doux sourire efface toute votre fatigue.', title_hi = 'सामाजिक मुस्कानें! 😊', body_hi = 'उसकी प्यारी मुस्कान आपकी सारी थकान दूर कर देती है।', title_id = 'Senyum sosial! 😊', body_id = 'Senyum manisnya menghapus semua lelah Anda.', title_ja = '人に向けた笑顔！😊', body_ja = '赤ちゃんのかわいい笑顔が、疲れをぜんぶ吹き飛ばしてくれます。', title_ko = '사회적 미소! 😊', body_ko = '아기의 달콤한 미소가 모든 피로를 녹여 줘요.', title_nl = 'Sociale lachjes! 😊', body_nl = 'Die lieve glimlach neemt al je vermoeidheid weg.', title_pl = 'Uśmiechy społeczne! 😊', body_pl = 'Jego słodki uśmiech zabiera całe twoje zmęczenie.', title_pt = 'Sorrisos sociais! 😊', body_pt = 'O sorriso ternurento dele leva todo o seu cansaço.', title_sv = 'Sociala leenden! 😊', body_sv = 'Barnets söta leende tar bort all din trötthet.', title_vi = 'Nụ cười giao tiếp! 😊', body_vi = 'Nụ cười ngọt ngào của bé xua tan mọi mệt mỏi của mẹ.', title_zh = '社交性微笑！😊', body_zh = '宝宝甜甜的笑容能赶走你所有的疲惫。' WHERE id = '818c91c1-bd54-42c5-8ac8-1505ae1830ab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mientras tu bebé duerme, descansa tú también! 😴', body_es = 'No olvides anotar cómo te sientes hoy en el Diario de ánimo.', title_fr = 'Reposez-vous pendant que bébé dort ! 😴', body_fr = 'N''oubliez pas de noter dans le Journal d''humeur comment vous vous sentez aujourd''hui.', title_hi = 'बच्चा सोए, तो आप भी आराम कीजिए! 😴', body_hi = 'आज आप कैसा महसूस कर रही हैं, यह मूड डायरी में लिखना न भूलें।', title_id = 'Saat bayi tidur, Anda juga istirahat! 😴', body_id = 'Jangan lupa menulis perasaan Anda hari ini di Buku Harian Suasana Hati.', title_ja = '赤ちゃんが眠っている間に、ママも休んで！😴', body_ja = '今日の気分を「気分日記」に書くのを忘れずに。', title_ko = '아기가 잘 때 엄마도 쉬세요! 😴', body_ko = '오늘 기분을 기분 일기에 기록하는 것 잊지 마세요.', title_nl = 'Rust ook uit als je baby slaapt! 😴', body_nl = 'Vergeet niet in je Stemmingsdagboek te schrijven hoe je je vandaag voelt.', title_pl = 'Gdy dziecko śpi, ty też odpocznij! 😴', body_pl = 'Nie zapomnij zapisać w Dzienniku nastroju, jak się dziś czujesz.', title_pt = 'Enquanto o bebé dorme, descanse também! 😴', body_pt = 'Não se esqueça de registar no Diário de Humor como se sente hoje.', title_sv = 'Vila du också när barnet sover! 😴', body_sv = 'Glöm inte att skriva ner hur du mår i dag i Humördagboken.', title_vi = 'Khi bé ngủ, mẹ cũng nghỉ ngơi nhé! 😴', body_vi = 'Đừng quên ghi lại cảm xúc hôm nay vào Nhật ký tâm trạng.', title_zh = '宝宝睡觉时，你也休息一下！😴', body_zh = '别忘了在心情日记里写下今天的感受。' WHERE id = '96187549-321c-4f4b-8ab6-e849804b2e3f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te reconoce a ti y tu voz! 😍', body_es = 'Fíjate en cómo se alegra cuando entras en la habitación. 😊', title_fr = 'Il vous reconnaît, vous et votre voix ! 😍', body_fr = 'Remarquez comme il est content quand vous entrez dans la pièce. 😊', title_hi = 'वह आपको और आपकी आवाज़ पहचानता है! 😍', body_hi = 'देखिए, आप कमरे में आती हैं तो वह कितना खुश होता है। 😊', title_id = 'Ia mengenali Anda dan suara Anda! 😍', body_id = 'Perhatikan betapa senangnya ia saat Anda masuk ke kamar. 😊', title_ja = 'ママとママの声がわかります！😍', body_ja = 'ママが部屋に入ってきたとき、赤ちゃんがどんなに喜ぶか見てみましょう。😊', title_ko = '엄마와 엄마 목소리를 알아봐요! 😍', body_ko = '엄마가 방에 들어올 때 아기가 얼마나 기뻐하는지 보세요. 😊', title_nl = 'Je baby herkent jou en je stem! 😍', body_nl = 'Let eens op hoe blij je baby wordt als je de kamer binnenkomt. 😊', title_pl = 'Rozpoznaje ciebie i twój głos! 😍', body_pl = 'Zobacz, jak się cieszy, gdy wchodzisz do pokoju. 😊', title_pt = 'Reconhece-a a si e à sua voz! 😍', body_pt = 'Repare como fica contente quando entra no quarto. 😊', title_sv = 'Barnet känner igen dig och din röst! 😍', body_sv = 'Lägg märke till hur glad barnet blir när du kommer in i rummet. 😊', title_vi = 'Bé nhận ra mẹ và giọng nói của mẹ! 😍', body_vi = 'Hãy để ý bé vui thế nào khi mẹ bước vào phòng. 😊', title_zh = '宝宝认得你和你的声音！😍', body_zh = '留意你走进房间时宝宝有多开心。😊' WHERE id = 'c1c4c9b0-cdd8-4321-a494-3bb43739df94' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Ha cambiado tu idea del día y la noche? 🛌', body_es = 'Sigue el horario de sueño y las rutinas diarias desde la app, y cuando duerma, cierra tú también los ojos.', title_fr = 'Jour et nuit ont changé de sens ? 🛌', body_fr = 'Suivez le rythme de sommeil et les normes quotidiennes dans l''application, et fermez les yeux quand il dort.', title_hi = 'दिन-रात का मतलब बदल गया? 🛌', body_hi = 'ऐप में नींद का शेड्यूल और रोज़ के मानक देखिए, और जब वह सोए तो आप भी आँखें बंद कर लीजिए।', title_id = 'Konsep siang dan malam sudah berubah? 🛌', body_id = 'Pantau jadwal tidur dan angka harian di aplikasi, dan saat ia tidur, pejamkan mata Anda juga.', title_ja = '昼と夜の感覚が変わりましたか？🛌', body_ja = '睡眠リズムと1日の目安をアプリで記録して、赤ちゃんが眠ったらママも目を閉じましょう。', title_ko = '낮과 밤의 개념이 바뀌었나요? 🛌', body_ko = '앱으로 수면 패턴과 하루 기준치를 확인하고, 아기가 잘 때 엄마도 눈을 붙이세요.', title_nl = 'Is je dag-nachtritme veranderd? 🛌', body_nl = 'Volg het slaapritme en de dagelijkse normen in de app, en doe je ogen ook dicht als je baby slaapt.', title_pl = 'Zmieniło się twoje pojęcie dnia i nocy? 🛌', body_pl = 'Śledź w aplikacji rytm snu i dzienne normy, a gdy dziecko śpi, ty też zamknij oczy.', title_pt = 'O dia e a noite trocaram-se? 🛌', body_pt = 'Acompanhe na app o horário de sono e as rotinas diárias, e quando o bebé dormir, feche também os olhos.', title_sv = 'Har natt och dag bytt plats? 🛌', body_sv = 'Följ sömnrytmen och de dagliga normerna i appen, och blunda du också när barnet sover.', title_vi = 'Khái niệm ngày đêm đã thay đổi? 🛌', body_vi = 'Theo dõi giấc ngủ và các chỉ số hằng ngày của bé trong ứng dụng, khi bé ngủ, mẹ cũng nhắm mắt nghỉ ngơi nhé.', title_zh = '昼夜颠倒了？🛌', body_zh = '在应用里追踪宝宝的睡眠规律和每日参考标准，宝宝睡觉时，你也闭上眼睛休息吧。' WHERE id = '2df49d87-7d2b-44bb-bb5a-a25b24863389' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hora de estar boca abajo! 🐢', body_es = 'Unos minutos al día boca abajo fortalecen los músculos de su cuello.', title_fr = 'Sur le ventre ! 🐢', body_fr = 'Quelques minutes par jour sur le ventre renforcent les muscles de son cou.', title_hi = 'पेट के बल का समय! 🐢', body_hi = 'रोज़ कुछ मिनट पेट के बल लेटना उसकी गर्दन की मांसपेशियाँ मज़बूत करता है।', title_id = 'Waktunya tengkurap! 🐢', body_id = 'Tengkurap beberapa menit setiap hari menguatkan otot lehernya.', title_ja = 'うつぶせ遊びの時間！🐢', body_ja = '1日に数分うつぶせにすると、首の筋肉が鍛えられます。', title_ko = '엎드려 있기 시간! 🐢', body_ko = '하루 몇 분씩 엎드려 있으면 목 근육이 튼튼해져요.', title_nl = 'Tijd voor buikligging! 🐢', body_nl = 'Elke dag een paar minuten op de buik liggen versterkt de nekspieren.', title_pl = 'Czas na brzuszek! 🐢', body_pl = 'Kilka minut dziennie na brzuszku wzmacnia mięśnie szyi.', title_pt = 'Hora de estar de barriga para baixo! 🐢', body_pt = 'Ficar alguns minutos por dia de barriga para baixo fortalece os músculos do pescoço.', title_sv = 'Dags för magläge! 🐢', body_sv = 'Några minuter på magen varje dag stärker nackmusklerna.', title_vi = 'Giờ nằm sấp! 🐢', body_vi = 'Nằm sấp vài phút mỗi ngày giúp cơ cổ của bé khỏe hơn.', title_zh = '趴趴时间！🐢', body_zh = '每天趴几分钟，能增强宝宝的颈部肌肉。' WHERE id = '228ed9a7-6c09-4e18-b632-934b4149caf5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' 