UPDATE public.mommy_day_notifications SET title_es = '¡Mantiene la cabeza más erguida! 🐢', body_es = 'Convierte los ejercicios boca abajo en un juego.', title_fr = 'Il tient sa tête plus droite ! 🐢', body_fr = 'Transformez les exercices sur le ventre en jeu.', title_hi = 'सिर और सीधा रखता है! 🐢', body_hi = 'पेट के बल वाली एक्सरसाइज़ को मज़ेदार बनाइए।', title_id = 'Kepalanya makin tegak! 🐢', body_id = 'Jadikan latihan tengkurap sebagai permainan.', title_ja = '頭をよりしっかり起こせるように！🐢', body_ja = 'うつぶせの練習を楽しい遊びに変えましょう。', title_ko = '고개를 더 똑바로 들어요! 🐢', body_ko = '엎드려 있기 운동을 놀이로 바꿔 보세요.', title_nl = 'Je baby houdt het hoofdje steeds rechter! 🐢', body_nl = 'Maak van de buikligging een feestje.', title_pl = 'Trzyma główkę coraz wyżej! 🐢', body_pl = 'Zamień ćwiczenia na brzuszku w zabawę.', title_pt = 'Segura a cabeça mais direita! 🐢', body_pt = 'Transforme os exercícios de barriga para baixo numa brincadeira.', title_sv = 'Barnet håller huvudet mer upprätt! 🐢', body_sv = 'Gör övningarna i magläge till en lek.', title_vi = 'Bé ngẩng đầu thẳng hơn! 🐢', body_vi = 'Hãy biến bài tập nằm sấp thành trò chơi vui nhộn.', title_zh = '头抬得更高啦！🐢', body_zh = '让趴趴练习变成游戏吧。' WHERE id = 'fa5fc8d8-4263-4a99-9f46-297b1d6ea219' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue su desarrollo paso a paso. 📏', body_es = '¿Se te ha olvidado introducir el perímetro craneal, la talla y el peso en el Registro de peso? Anótalo ahora.', title_fr = 'Suivez son développement pas à pas. 📏', body_fr = 'Avez-vous oublié de saisir le périmètre crânien, la taille et le poids dans le Suivi du poids ? Notez-les maintenant.', title_hi = 'विकास पर कदम-दर-कदम नज़र रखिए। 📏', body_hi = 'सिर का घेरा, लंबाई और वज़न वेट ट्रैकर में दर्ज करना भूल गईं? अभी दर्ज कीजिए।', title_id = 'Pantau perkembangannya langkah demi langkah. 📏', body_id = 'Lupa memasukkan data lingkar kepala, tinggi, dan berat ke Pelacak Berat Badan? Catat sekarang.', title_ja = '成長を一歩ずつ見守りましょう。📏', body_ja = '頭囲、身長、体重のデータを「体重トラッカー」に入力し忘れていませんか？今すぐ記録しましょう。', title_ko = '성장을 한 걸음씩 기록해요. 📏', body_ko = '머리둘레, 키, 몸무게를 체중 기록에 입력하는 걸 잊으셨나요? 지금 기록하세요.', title_nl = 'Volg de ontwikkeling stap voor stap. 📏', body_nl = 'Ben je vergeten de hoofdomtrek, lengte en het gewicht in te voeren in de Gewichtstracker? Doe het nu.', title_pl = 'Śledź rozwój krok po kroku. 📏', body_pl = 'Zapomniałaś wpisać obwód głowy, wzrost i wagę do Licznika wagi? Zapisz je teraz.', title_pt = 'Acompanhe o desenvolvimento passo a passo. 📏', body_pt = 'Esqueceu-se de introduzir o perímetro cefálico, a altura e o peso no Registo de Peso? Registe agora.', title_sv = 'Följ utvecklingen steg för steg. 📏', body_sv = 'Har du glömt att skriva in huvudomfång, längd och vikt i Viktspåraren? Gör det nu.', title_vi = 'Theo dõi sự phát triển từng bước. 📏', body_vi = 'Mẹ đã quên nhập vòng đầu, chiều cao và cân nặng vào Theo dõi cân nặng? Ghi lại ngay nhé.', title_zh = '一步步记录成长。📏', body_zh = '忘记把头围、身高和体重录入体重记录了吗？现在就记下来吧。' WHERE id = 'ded576fe-d3fa-4078-9b83-36eaf5b495d5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Enhorabuena, ya lleváis 2 semanas! 🎈', body_es = 'Para celebrar este pequeño aniversario, usa los temas divertidos de la sección Sesión de fotos del bebé.', title_fr = 'Félicitations, déjà 2 semaines ! 🎈', body_fr = 'Pour fêter ce petit anniversaire, profitez des thèmes amusants de la rubrique Séance photo bébé.', title_hi = 'बधाई हो, आप 2 हफ़्ते के हो गए! 🎈', body_hi = 'इस छोटी सी सालगिरह को मनाने के लिए बेबी फ़ोटोशूट सेक्शन की मज़ेदार थीम इस्तेमाल कीजिए।', title_id = 'Selamat, sudah 2 minggu! 🎈', body_id = 'Untuk merayakan momen kecil ini, gunakan tema-tema menarik di bagian Pemotretan Bayi.', title_ja = 'おめでとうございます、もう2週間！🎈', body_ja = 'このちょっとした記念日をお祝いするために、「ベビーフォトセッション」の楽しいテーマを使ってみましょう。', title_ko = '축하해요, 벌써 2주가 됐어요! 🎈', body_ko = '이 작은 기념일을 축하하려면 아기 사진 촬영 섹션의 재미있는 테마를 활용해 보세요.', title_nl = 'Gefeliciteerd, al 2 weken! 🎈', body_nl = 'Gebruik de leuke thema’s in het onderdeel Babyfotoshoot om dit kleine jubileum te vieren.', title_pl = 'Gratulacje, to już 2 tygodnie! 🎈', body_pl = 'Aby uczcić ten mały jubileusz, skorzystaj z ciekawych motywów w sekcji Sesja zdjęciowa dziecka.', title_pt = 'Parabéns, o bebé já tem 2 semanas! 🎈', body_pt = 'Para celebrar este pequeno aniversário, use os temas divertidos da secção Sessão Fotográfica do Bebé.', title_sv = 'Grattis, nu har ni klarat 2 veckor! 🎈', body_sv = 'Fira den här lilla milstolpen med de roliga temana i avsnittet Babyfotografering.', title_vi = 'Chúc mừng, bé đã được 2 tuần tuổi! 🎈', body_vi = 'Để kỷ niệm cột mốc nhỏ này, hãy dùng các chủ đề thú vị trong mục Chụp ảnh cho bé.', title_zh = '恭喜，宝宝2周啦！🎈', body_zh = '用宝宝写真板块里有趣的主题，庆祝这个小小的纪念日吧。' WHERE id = '7bc61271-cc44-4b34-a12b-faa852a23b6c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El reflejo de succión de tu bebé es muy fuerte! 🍼', body_es = 'Sigue cada toma con el temporizador para asegurarte de que se queda saciado.', title_fr = 'Le réflexe de succion de bébé est très fort ! 🍼', body_fr = 'Suivez chaque tétée avec le minuteur pour vous assurer qu''il mange à sa faim.', title_hi = 'आपके बच्चे की चूसने की प्रवृत्ति बहुत मज़बूत है! 🍼', body_hi = 'टाइमर से हर फ़ीडिंग पर नज़र रखिए और पक्का कीजिए कि उसका पेट भर रहा है।', title_id = 'Refleks mengisap bayi Anda sangat kuat! 🍼', body_id = 'Pantau setiap sesi menyusu dengan pengatur waktu untuk memastikan ia cukup kenyang.', title_ja = '赤ちゃんの吸う力はとても強い！🍼', body_ja = '毎回の授乳をタイマーで記録して、赤ちゃんがしっかり満たされているか確認しましょう。', title_ko = '아기의 빠는 반사가 아주 강해요! 🍼', body_ko = '수유할 때마다 타이머로 기록하며 아기가 충분히 먹는지 확인하세요.', title_nl = 'De zuigreflex van je baby is heel sterk! 🍼', body_nl = 'Volg elke voeding met de timer, zodat je zeker weet dat je baby genoeg binnenkrijgt.', title_pl = 'Odruch ssania dziecka jest bardzo silny! 🍼', body_pl = 'Śledź każde karmienie timerem, by mieć pewność, że dziecko się najada.', title_pt = 'O reflexo de sucção do bebé é muito forte! 🍼', body_pt = 'Acompanhe cada mamada com o temporizador para ter a certeza de que o bebé fica saciado.', title_sv = 'Ditt barns sugreflex är väldigt stark! 🍼', body_sv = 'Följ varje matning med timern och se till att barnet blir mätt.', title_vi = 'Phản xạ bú của bé rất mạnh! 🍼', body_vi = 'Theo dõi từng cữ bú bằng bộ hẹn giờ để chắc chắn bé được bú no.', title_zh = '宝宝的吸吮反射非常强！🍼', body_zh = '用计时器记录每一次喂养，确保宝宝吃饱。' WHERE id = '0ed5afeb-bfa9-4fba-a6c1-40d487f8789c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Preparación para dormir por la noche. 🌙', body_es = 'Antes de dormir, ajusta la temperatura de la habitación y pon en marcha el temporizador de sueño de Anacan.', title_fr = 'Préparation à la nuit. 🌙', body_fr = 'Avant le coucher, réglez la température de la chambre et lancez le minuteur de sommeil d''Anacan.', title_hi = 'रात की नींद की तैयारी। 🌙', body_hi = 'सोने से पहले कमरे का तापमान ठीक कीजिए और Anacan का स्लीप टाइमर शुरू कीजिए।', title_id = 'Persiapan tidur malam. 🌙', body_id = 'Sebelum tidur, atur suhu kamar dan mulai pengatur waktu tidur Anacan.', title_ja = '夜の睡眠の準備。🌙', body_ja = '寝る前に部屋の温度を調整して、Anacanの睡眠タイマーをスタートしましょう。', title_ko = '밤잠 준비. 🌙', body_ko = '자기 전에 방 온도를 맞추고 Anacan 수면 타이머를 시작하세요.', title_nl = 'Klaar voor de nacht. 🌙', body_nl = 'Regel voor het slapengaan de temperatuur in de kamer en start de slaaptimer van Anacan.', title_pl = 'Przygotowanie do nocnego snu. 🌙', body_pl = 'Przed snem ustaw temperaturę w pokoju i włącz timer snu w Anacan.', title_pt = 'Preparação para o sono da noite. 🌙', body_pt = 'Antes de dormir, ajuste a temperatura do quarto e ligue o temporizador de sono do Anacan.', title_sv = 'Förberedelser för nattsömnen. 🌙', body_sv = 'Ställ in temperaturen i rummet före läggdags och starta Anacans sömntimer.', title_vi = 'Chuẩn bị cho giấc ngủ đêm. 🌙', body_vi = 'Trước khi ngủ, hãy điều chỉnh nhiệt độ phòng và bật bộ hẹn giờ ngủ của Anacan.', title_zh = '为夜间睡眠做准备。🌙', body_zh = '睡前调好房间温度，然后启动Anacan的睡眠计时器。' WHERE id = 'b42303f7-3c77-46e1-97e5-9a1b1e60430c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hoy solo emociones positivas! ✨', body_es = 'Abre tu Diario de ánimo y anota el momento en que tu bebé más te ha hecho reír. ¡Anacan AI te escucha!', title_fr = 'Aujourd''hui, que des émotions positives ! ✨', body_fr = 'Ouvrez votre Journal d''humeur et notez le moment où votre bébé vous a le plus fait rire. Anacan AI vous écoute !', title_hi = 'आज सिर्फ़ अच्छी भावनाएँ! ✨', body_hi = 'मूड डायरी खोलिए और वह पल लिखिए जब बच्चे ने आपको सबसे ज़्यादा हँसाया। Anacan AI सुन रहा है!', title_id = 'Hari ini hanya emosi positif! ✨', body_id = 'Buka Buku Harian Suasana Hati dan catat momen ketika bayi Anda paling membuat Anda tertawa. Anacan AI mendengarkan Anda!', title_ja = '今日はポジティブな気持ちだけ！✨', body_ja = '「気分日記」を開いて、赤ちゃんがいちばん笑わせてくれた瞬間を記録しましょう。Anacan AIが聞いています！', title_ko = '오늘은 긍정적인 감정만! ✨', body_ko = '기분 일기를 열고 아기가 엄마를 가장 많이 웃게 한 순간을 기록해 보세요. Anacan AI가 들어 드릴게요!', title_nl = 'Vandaag alleen positieve emoties! ✨', body_nl = 'Open je Stemmingsdagboek en noteer het moment waarop je baby je het hardst liet lachen. Anacan AI luistert naar je!', title_pl = 'Dziś tylko pozytywne emocje! ✨', body_pl = 'Otwórz Dziennik nastroju i zapisz chwilę, w której dziecko najbardziej cię rozśmieszyło. Anacan AI cię słucha!', title_pt = 'Hoje, só emoções positivas! ✨', body_pt = 'Abra o Diário de Humor e registe o momento em que o bebé mais a fez rir. O Anacan AI está a ouvi-la!', title_sv = 'I dag bara positiva känslor! ✨', body_sv = 'Öppna Humördagboken och skriv ner stunden då barnet fick dig att skratta mest. Anacan AI lyssnar!', title_vi = 'Hôm nay chỉ toàn cảm xúc tích cực! ✨', body_vi = 'Mở Nhật ký tâm trạng và ghi lại khoảnh khắc bé làm mẹ cười nhiều nhất. Anacan AI đang lắng nghe mẹ!', title_zh = '今天只要正能量！✨', body_zh = '打开心情日记，记下宝宝今天最让你开心的时刻。Anacan AI在倾听！' WHERE id = 'e9631c46-1105-44f2-b850-b1671ee6df45' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Te sientes sensible sin motivo? 😢', body_es = '¡Es totalmente natural! Puedes compartir lo que sientes y recibir apoyo en Anacan AI o en nuestra Comunidad.', title_fr = 'Vous êtes à fleur de peau sans raison ? 😢', body_fr = 'C''est tout à fait naturel ! Partagez vos ressentis et trouvez du soutien avec Anacan AI ou dans notre Communauté.', title_hi = 'बिना वजह भावुक हो रही हैं? 😢', body_hi = 'यह बिल्कुल स्वाभाविक है! Anacan AI या हमारी कम्युनिटी में अपनी भावनाएँ बाँटिए और सहारा पाइए।', title_id = 'Mudah terharu tanpa alasan? 😢', body_id = 'Ini sangat wajar! Anda bisa berbagi perasaan dan mendapat dukungan di Anacan AI atau di Komunitas kami.', title_ja = '理由もなく涙もろくなる？😢', body_ja = 'これはまったく自然なことです！Anacan AIやコミュニティで気持ちを分かち合い、サポートを受けることができます。', title_ko = '이유 없이 마음이 여려지나요? 😢', body_ko = '아주 자연스러운 일이에요! Anacan AI나 커뮤니티에서 마음을 나누고 위로를 받을 수 있어요.', title_nl = 'Ben je zomaar emotioneel? 😢', body_nl = 'Dat is heel normaal! Deel je gevoelens met Anacan AI of in onze Community en vind steun.', title_pl = 'Bez powodu jesteś płaczliwa? 😢', body_pl = 'To zupełnie naturalne! Możesz podzielić się uczuciami i otrzymać wsparcie w Anacan AI lub w naszej Społeczności.', title_pt = 'Sente-se frágil sem razão? 😢', body_pt = 'É perfeitamente natural! Pode partilhar o que sente e receber apoio no Anacan AI ou na nossa Comunidade.', title_sv = 'Känner du dig skör utan anledning? 😢', body_sv = 'Det är helt naturligt! Du kan dela dina känslor och få stöd hos Anacan AI eller i vår Community.', title_vi = 'Mẹ hay tủi thân không rõ lý do? 😢', body_vi = 'Điều này hoàn toàn tự nhiên! Mẹ có thể chia sẻ cảm xúc và nhận hỗ trợ từ Anacan AI hoặc Cộng đồng của chúng tôi.', title_zh = '莫名想哭？😢', body_zh = '这完全是正常的！你可以在Anacan AI或我们的社区里分享感受，获得支持。' WHERE id = 'da08e82c-f1b1-4615-9a78-803ac91a2d92' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hora de pasear al aire libre! ☀️', body_es = '¿Buscas un sitio adecuado para ir con el bebé donde puedas descansar a gusto? No te pierdas nuestro blog Lugares para mamás.', title_fr = 'L''heure d''une promenade au grand air ! ☀️', body_fr = 'Vous cherchez un endroit où vous détendre, adapté aux enfants ? Jetez un œil à notre blog Lieux adaptés aux mamans.', title_hi = 'खुली हवा में सैर का समय! ☀️', body_hi = 'आराम करने लायक, बच्चे के साथ जाने लायक जगह ढूँढ रही हैं? हमारा माँ के लिए अनुकूल जगहें ब्लॉग ज़रूर देखिए।', title_id = 'Waktunya jalan-jalan di udara terbuka! ☀️', body_id = 'Mencari tempat yang nyaman untuk bersantai dan cocok untuk membawa anak? Pastikan melihat blog Tempat Ramah Ibu kami.', title_ja = '外でお散歩の時間！☀️', body_ja = '赤ちゃん連れでゆっくりできる場所を探していますか？「ママにやさしいスポット」のブログをぜひチェックしてください。', title_ko = '바깥 산책 시간이에요! ☀️', body_ko = '아기와 함께 편히 쉴 수 있는 곳을 찾고 있나요? 엄마 친화 장소 블로그를 꼭 확인해 보세요.', title_nl = 'Tijd voor een wandeling buiten! ☀️', body_nl = 'Op zoek naar een plek waar je fijn kunt ontspannen en die geschikt is voor een uitje met je kind? Bekijk zeker onze blog Mamavriendelijke plekken.', title_pl = 'Czas na spacer na świeżym powietrzu! ☀️', body_pl = 'Szukasz miejsca, w którym odpoczniesz i które nadaje się na wyjście z dzieckiem? Koniecznie zajrzyj na nasz blog Miejsca przyjazne mamom.', title_pt = 'Hora de passear ao ar livre! ☀️', body_pt = 'Procura um sítio adequado para ir com o bebé, onde possa descansar à vontade? Não deixe de ver o nosso blogue Locais Amigos das Mães.', title_sv = 'Dags för promenad i friska luften! ☀️', body_sv = 'Letar du efter ett barnvänligt ställe där du kan vila? Kika in i vår blogg Mammavänliga platser.', title_vi = 'Đến giờ dạo chơi ngoài trời! ☀️', body_vi = 'Mẹ đang tìm nơi phù hợp để đưa bé đi và thư giãn thoải mái? Hãy xem blog Địa điểm thân thiện với mẹ nhé.', title_zh = '户外散步时间到！☀️', body_zh = '在找可以放松、适合带宝宝去的地方？一定要看看我们的妈妈友好场所博客。' WHERE id = 'ef4b3736-bd78-46e0-af19-3bceb15bf443' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lee y aprende cuando tengas tiempo. 📚', body_es = 'Los artículos más útiles sobre el desarrollo y el cuidado del recién nacido te esperan en la sección Blog.', title_fr = 'Lisez et apprenez dès que vous avez le temps. 📚', body_fr = 'Les articles les plus utiles sur le développement et les soins des nouveau-nés vous attendent dans la rubrique Blogs.', title_hi = 'जब समय मिले, पढ़िए और सीखिए। 📚', body_hi = 'नवजात शिशुओं के विकास और देखभाल पर सबसे उपयोगी लेख ब्लॉग सेक्शन में आपका इंतज़ार कर रहे हैं।', title_id = 'Membaca dan belajarlah saat ada waktu. 📚', body_id = 'Artikel paling bermanfaat tentang perkembangan dan perawatan bayi baru lahir menanti Anda di bagian Blog.', title_ja = '時間があるときに読んで学びましょう。📚', body_ja = '新生児の発達とお世話に役立つ記事が、ブログで待っています。', title_ko = '틈날 때마다 읽고 배워요. 📚', body_ko = '신생아 발달과 돌봄에 관한 가장 유용한 글이 블로그 섹션에서 기다리고 있어요.', title_nl = 'Lees en leer wanneer je tijd hebt. 📚', body_nl = 'De nuttigste artikelen over de ontwikkeling en verzorging van pasgeborenen vind je in het onderdeel Blogs.', title_pl = 'Czytaj i ucz się, gdy masz chwilę. 📚', body_pl = 'Najbardziej przydatne artykuły o rozwoju i pielęgnacji noworodków czekają w sekcji Blogi.', title_pt = 'Leia e aprenda sempre que tiver tempo. 📚', body_pt = 'Na secção Blogues esperam-na os artigos mais úteis sobre o desenvolvimento e os cuidados do recém-nascido.', title_sv = 'Läs och lär dig när du hinner. 📚', body_sv = 'De mest användbara artiklarna om nyföddas utveckling och skötsel väntar på dig i Bloggen.', title_vi = 'Có thời gian thì hãy đọc và tìm hiểu. 📚', body_vi = 'Những bài viết hữu ích nhất về sự phát triển và chăm sóc trẻ sơ sinh đang chờ mẹ trong mục Blog.', title_zh = '有空就读一读、学一学。📚', body_zh = '博客板块里有关于新生儿发育和护理最实用的文章等着你。' WHERE id = '498afb20-12cf-4e99-872a-93ae66ffadf8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se acerca la revisión del primer mes. ⚖️', body_es = 'Asegúrate de haber anotado el aumento de peso y talla de tu bebé hasta ahora en la sección Seguimiento del desarrollo.', title_fr = 'La visite du premier mois approche. ⚖️', body_fr = 'Vérifiez que vous avez bien noté la prise de poids et de taille de votre bébé dans la rubrique Suivi de croissance.', title_hi = 'पहले महीने की जाँच करीब है। ⚖️', body_hi = 'पक्का कीजिए कि अब तक के बच्चे के वज़न और लंबाई की बढ़त ग्रोथ ट्रैकर सेक्शन में दर्ज है।', title_id = 'Pemeriksaan bulan pertama sudah dekat. ⚖️', body_id = 'Pastikan Anda sudah mencatat pertambahan berat dan tinggi bayi sejauh ini di bagian Pelacak Pertumbuhan.', title_ja = '1か月健診が近づいています。⚖️', body_ja = 'これまでの体重と身長の増え方を「成長トラッカー」に記録しておきましょう。', title_ko = '첫 달 검진이 다가와요. ⚖️', body_ko = '지금까지의 몸무게와 키 성장을 성장 기록 섹션에 입력했는지 확인하세요.', title_nl = 'De controle na de eerste maand komt eraan. ⚖️', body_nl = 'Zorg dat je de groei in gewicht en lengte van je baby tot nu toe hebt genoteerd in het onderdeel Groeitracker.', title_pl = 'Zbliża się badanie po pierwszym miesiącu. ⚖️', body_pl = 'Upewnij się, że dotychczasowy przyrost wagi i wzrostu dziecka jest zapisany w sekcji Śledzenie rozwoju.', title_pt = 'A consulta do primeiro mês está a chegar. ⚖️', body_pt = 'Confirme que registou na secção Registo de Crescimento o aumento de peso e altura do bebé até agora.', title_sv = 'Första månadskontrollen närmar sig. ⚖️', body_sv = 'Se till att du har skrivit in barnets vikt- och längdökning hittills i Tillväxtspåraren.', title_vi = 'Sắp đến buổi khám tháng đầu tiên. ⚖️', body_vi = 'Hãy chắc chắn mẹ đã ghi lại mức tăng cân nặng và chiều cao của bé đến nay trong mục Theo dõi phát triển.', title_zh = '满月体检快到了。⚖️', body_zh = '确认已经把宝宝到目前为止的体重和身高增长记录在成长记录板块里。' WHERE id = 'a1d43ae2-7007-4910-b05d-6c1d71529cf9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Su atención aumenta! 👀', body_es = 'Ya distingue mejor los colores de contraste blanco y negro. No olvides usar tarjetas de estimulación durante el tummy time.', title_fr = 'Son attention augmente ! 👀', body_fr = 'Il distingue mieux les couleurs contrastées noir et blanc. Pensez à utiliser des cartes d''éveil pendant le tummy time.', title_hi = 'ध्यान बढ़ रहा है! 👀', body_hi = 'वह अब काले-सफ़ेद कंट्रास्ट रंगों को बेहतर पहचानता है। टमी टाइम के दौरान फ़्लैश कार्ड इस्तेमाल करना न भूलें।', title_id = 'Perhatiannya meningkat! 👀', body_id = 'Ia kini lebih mudah membedakan warna kontras hitam-putih. Jangan lupa menggunakan kartu stimulasi saat tummy time.', title_ja = '集中力がアップ！👀', body_ja = '赤ちゃんはもう白黒のコントラストをよりはっきり見分けられます。うつぶせ遊びのときに、知育カードを使うのを忘れずに。', title_ko = '집중력이 자라고 있어요! 👀', body_ko = '아기가 이제 흑백 대비 색을 더 잘 구별해요. 엎드려 있기 할 때 초점책 카드를 활용해 보세요.', title_nl = 'De aandacht groeit! 👀', body_nl = 'Je baby ziet zwart-witcontrasten al beter. Vergeet niet om tijdens de buikligging contrastkaarten te gebruiken.', title_pl = 'Uwaga się wydłuża! 👀', body_pl = 'Już lepiej rozróżnia kontrastowe czarno-białe kolory. Podczas leżenia na brzuszku korzystaj z kart kontrastowych.', title_pt = 'A atenção está a aumentar! 👀', body_pt = 'O bebé já distingue melhor as cores de alto contraste, preto e branco. Não se esqueça de usar cartões de estimulação durante o tummy time.', title_sv = 'Uppmärksamheten ökar! 👀', body_sv = 'Barnet ser nu svartvita kontraster bättre. Glöm inte att använda kontrastkort under magläget (tummy time).', title_vi = 'Khả năng chú ý tăng lên! 👀', body_vi = 'Bé đã phân biệt màu tương phản đen trắng rõ hơn.  Đừng quên dùng thẻ kích thích thị giác khi cho bé nằm sấp.', title_zh = '注意力在提升！👀', body_zh = '宝宝现在能更好地分辨黑白对比色了。趴趴时间别忘了用上黑白卡。' WHERE id = '2b4adff1-6ebf-471c-9dc4-e4e39cc16323' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se te ha olvidado con qué pecho le diste? 🤱', body_es = 'Marca con el temporizador si es el pecho derecho o el izquierdo, ¡y deja que el Seguimiento de tomas lo recuerde todo!', title_fr = 'Vous avez oublié de quel côté vous avez allaité ? 🤱', body_fr = 'Notez sein droit ou gauche avec le minuteur, et laissez l''outil Suivi des repas tout retenir !', title_hi = 'भूल गईं कि किस तरफ़ से दूध पिलाया? 🤱', body_hi = 'टाइमर से दायाँ या बायाँ स्तन दर्ज कीजिए, फ़ीडिंग ट्रैकर सब याद रखेगा!', title_id = 'Lupa payudara mana yang terakhir menyusui? 🤱', body_id = 'Catat payudara kanan atau kiri dengan pengatur waktu, biarkan alat Pemantau Menyusu mengingat semuanya!', title_ja = 'どちらの胸で授乳したか忘れちゃった？🤱', body_ja = 'タイマーで右か左かを記録して、授乳記録ツールにぜんぶ覚えてもらいましょう！', title_ko = '어느 쪽 가슴으로 수유했는지 잊으셨나요? 🤱', body_ko = '타이머로 오른쪽, 왼쪽을 기록하세요. 수유 기록 도구가 모두 기억해 줄 거예요!', title_nl = 'Vergeten aan welke borst je baby dronk? 🤱', body_nl = 'Noteer met de timer of het de rechter- of linkerborst was, dan onthoudt de Voedingstracker alles!', title_pl = 'Zapomniałaś, z której piersi karmiłaś? 🤱', body_pl = 'Zaznaczaj w timerze prawą lub lewą pierś, a narzędzie do śledzenia karmienia wszystko zapamięta!', title_pt = 'Esqueceu-se de qual foi a mama da última vez? 🤱', body_pt = 'Registe com o temporizador se foi a mama direita ou a esquerda, e o Registo de Alimentação guarda tudo!', title_sv = 'Har du glömt vilket bröst du ammade från? 🤱', body_sv = 'Anteckna höger eller vänster bröst med timern, så kommer verktyget Matningskoll ihåg allt!', title_vi = 'Mẹ quên đã cho bú bên ngực nào? 🤱', body_vi = 'Ghi lại bên trái hay bên phải bằng bộ hẹn giờ, để Theo dõi cữ bú nhớ mọi thứ giúp mẹ!', title_zh = '忘了上次喂的是哪一侧？🤱', body_zh = '用计时器记录左侧或右侧，让喂养记录工具帮你记住一切！' WHERE id = '5e1b47e3-2994-433f-a7c8-b1e6a121de30' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Tus estadísticas semanales están listas! 📊', body_es = 'Entra en la app para analizar cómo has cumplido últimamente con el sueño y las tomas recomendadas.', title_fr = 'Vos statistiques de la semaine sont prêtes ! 📊', body_fr = 'Ouvrez l''application pour analyser comment vous avez suivi les normes de sommeil et de repas ces derniers jours.', title_hi = 'आपके हफ़्ते के आँकड़े तैयार हैं! 📊', body_hi = 'पिछले दिनों में नींद और फ़ीडिंग के मानकों का कितना पालन हुआ, इसका विश्लेषण करने के लिए ऐप खोलिए।', title_id = 'Statistik mingguan Anda sudah siap! 📊', body_id = 'Buka aplikasi untuk menganalisis seberapa baik Anda mengikuti angka tidur dan menyusu dalam beberapa hari terakhir.', title_ja = '1週間のデータができました！📊', body_ja = 'アプリを開いて、ここ数日の睡眠と授乳の目安をどれくらい守れているか分析しましょう。', title_ko = '주간 통계가 준비됐어요! 📊', body_ko = '최근 수면과 수유 기준치를 얼마나 지켰는지 앱에서 분석해 보세요.', title_nl = 'Je weekstatistieken zijn klaar! 📊', body_nl = 'Open de app om te zien hoe goed je de afgelopen dagen de slaap- en voedingsnormen hebt gehaald.', title_pl = 'Twoje tygodniowe statystyki są gotowe! 📊', body_pl = 'Wejdź do aplikacji i sprawdź, jak w ostatnich dniach trzymaliście się norm snu i karmienia.', title_pt = 'As suas estatísticas semanais estão prontas! 📊', body_pt = 'Entre na app para analisar como têm sido cumpridas as horas de sono e de alimentação nos últimos dias.', title_sv = 'Din veckostatistik är klar! 📊', body_sv = 'Öppna appen och analysera hur väl ni har följt sömn- och matningsnormerna de senaste dagarna.', title_vi = 'Thống kê hằng tuần đã sẵn sàng! 📊', body_vi = 'Vào ứng dụng để phân tích mấy ngày qua mẹ đã duy trì định mức ngủ và cữ bú thế nào.', title_zh = '你的每周统计已生成！📊', body_zh = '打开应用，分析一下最近几天睡眠和喂养参考量的完成情况。' WHERE id = '77ad5a07-cc0a-4fb4-b323-d177412300b1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Te cuesta dormirle? 🎶', body_es = 'Pon la herramienta Ruido blanco de la app y deja que tu bebé duerma profundamente, como en el vientre materno.', title_fr = 'Bébé a du mal à s''endormir ? 🎶', body_fr = 'Activez l''outil Bruits blancs de l''application pour que votre bébé s''endorme profondément, comme dans le ventre de sa maman.', title_hi = 'सुलाने में मुश्किल हो रही है? 🎶', body_hi = 'हमारे ऐप में व्हाइट नॉइज़ चलाइए, ताकि आपका बच्चा गर्भ की तरह गहरी नींद सो जाए।', title_id = 'Kesulitan menidurkan bayi? 🎶', body_id = 'Nyalakan alat Suara Putih di aplikasi kami agar bayi Anda tidur nyenyak seperti di dalam rahim.', title_ja = '寝かしつけに苦労していますか？🎶', body_ja = 'アプリの「ホワイトノイズ」をオンにして、赤ちゃんがお腹の中にいたときのように深い眠りにつけるようにしましょう。', title_ko = '아기 재우기가 힘드세요? 🎶', body_ko = '앱의 백색소음을 틀어 주세요. 아기가 엄마 뱃속에 있을 때처럼 깊이 잠들 거예요.', title_nl = 'Moeite om je baby in slaap te krijgen? 🎶', body_nl = 'Zet de tool Witte ruis in onze app aan, zodat je baby diep in slaap valt, net als in de buik.', title_pl = 'Trudno ci uśpić dziecko? 🎶', body_pl = 'Włącz Biały szum w naszej aplikacji, by dziecko zasnęło głęboko, jak w brzuchu mamy.', title_pt = 'Tem dificuldade em adormecer o bebé? 🎶', body_pt = 'Ligue o Ruído Branco da nossa app para o bebé adormecer profundamente, como no ventre da mãe.', title_sv = 'Svårt att få barnet att somna? 🎶', body_sv = 'Sätt på verktyget Vitt brus i appen, så att barnet somnar djupt precis som i magen.', title_vi = 'Khó ru bé ngủ? 🎶', body_vi = 'Hãy bật công cụ Tiếng ồn trắng trong ứng dụng, để bé ngủ sâu như khi còn trong bụng mẹ.', title_zh = '哄睡有困难？🎶', body_zh = '打开应用里的白噪音工具，让宝宝像在妈妈肚子里时一样进入深度睡眠。' WHERE id = 'fee5ed13-dd9c-4182-b62b-254289a55cec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El aire libre abre el apetito! 🌳', body_es = 'Procura sacar a tu bebé al aire libre cada día. Es muy beneficioso para ti y para tu bebé.', title_fr = 'L''air frais ouvre l''appétit ! 🌳', body_fr = 'Pensez à sortir votre bébé au grand air chaque jour. C''est très bénéfique pour vous comme pour lui.', title_hi = 'ताज़ी हवा भूख बढ़ाती है! 🌳', body_hi = 'बच्चे को रोज़ खुली हवा में ले जाने का ध्यान रखिए। यह आपके और बच्चे दोनों के लिए बहुत फ़ायदेमंद है।', title_id = 'Udara segar membangkitkan selera makan! 🌳', body_id = 'Usahakan membawa bayi Anda ke udara terbuka setiap hari. Ini sangat bermanfaat bagi Anda dan bayi.', title_ja = '新鮮な空気で食欲アップ！🌳', body_ja = '毎日赤ちゃんを外に連れ出すようにしましょう。ママにも赤ちゃんにもとても有益です。', title_ko = '맑은 공기가 식욕을 돋워요! 🌳', body_ko = '매일 아기와 함께 바깥 공기를 쐬어 주세요. 엄마와 아기 모두에게 아주 좋아요.', title_nl = 'Frisse lucht geeft trek! 🌳', body_nl = 'Neem je baby elke dag mee naar buiten. Dat is heel goed voor jou en voor je baby.', title_pl = 'Świeże powietrze pobudza apetyt! 🌳', body_pl = 'Pamiętaj, by codziennie wychodzić z dzieckiem na zewnątrz. To bardzo zdrowe i dla ciebie, i dla niego.', title_pt = 'O ar puro abre o apetite! 🌳', body_pt = 'Não deixe de levar o bebé a apanhar ar todos os dias. É muito benéfico para a mãe e para o bebé.', title_sv = 'Frisk luft ger aptit! 🌳', body_sv = 'Se till att ta ut barnet i friska luften varje dag. Det är väldigt nyttigt både för dig och för barnet.', title_vi = 'Không khí trong lành giúp ăn ngon! 🌳', body_vi = 'Hãy chú ý đưa bé ra ngoài trời mỗi ngày. Điều này rất có lợi cho cả mẹ và bé.', title_zh = '新鲜空气让胃口大开！🌳', body_zh = '记得每天带宝宝出门呼吸新鲜空气。这对你和宝宝都非常有益。' WHERE id = '8fac7e6d-3d63-4646-99a7-c927a088e849' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mejora la calidad de tu leche. 🍲', body_es = 'Para comer sano y rico, echa un vistazo a la sección de Recetas saludables de la app.', title_fr = 'Améliorez la qualité de votre lait. 🍲', body_fr = 'Pour manger sainement et avec plaisir, jetez un œil à la rubrique Recettes saines de l''application.', title_hi = 'अपने दूध की गुणवत्ता बढ़ाइए। 🍲', body_hi = 'सेहतमंद और स्वादिष्ट खाने के लिए ऐप का सेहतमंद रेसिपी सेक्शन देखिए।', title_id = 'Tingkatkan kualitas ASI Anda. 🍲', body_id = 'Untuk makan sehat dan lezat, lihat bagian Resep Sehat di aplikasi.', title_ja = '母乳の質を高めましょう。🍲', body_ja = '健康的でおいしい食事のために、アプリの「ヘルシーレシピ」セクションをのぞいてみましょう。', title_ko = '모유의 질을 높여요. 🍲', body_ko = '건강하고 맛있게 드시려면 앱의 건강한 레시피 섹션을 살펴보세요.', title_nl = 'Verbeter de kwaliteit van je melk. 🍲', body_nl = 'Kijk voor gezond en lekker eten in het onderdeel Gezonde recepten in de app.', title_pl = 'Popraw jakość swojego mleka. 🍲', body_pl = 'Aby jeść zdrowo i smacznie, zajrzyj do sekcji Zdrowe przepisy w aplikacji.', title_pt = 'Melhore a qualidade do seu leite. 🍲', body_pt = 'Para uma alimentação saudável e saborosa, veja a secção Receitas Saudáveis da app.', title_sv = 'Förbättra kvaliteten på din mjölk. 🍲', body_sv = 'För hälsosam och god mat, kika in i avsnittet Hälsosamma recept i appen.', title_vi = 'Nâng cao chất lượng sữa mẹ. 🍲', body_vi = 'Để ăn uống lành mạnh và ngon miệng, hãy xem mục Công thức lành mạnh trong ứng dụng.', title_zh = '提升母乳质量。🍲', body_zh = '想吃得健康又美味，就看看应用里的健康食谱板块吧。' WHERE id = 'dd0fbf42-9f2a-4cb9-8c66-db4c46ee2124' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cordón umbilical debe estar seco y limpio. ⏱️', body_es = 'Si el cordón umbilical se moja, hay que secarlo bien y aplicar cada día la solución antiséptica que haya indicado el médico.', title_fr = 'Le cordon ombilical doit rester sec et propre. ⏱️', body_fr = 'Si le cordon ombilical est mouillé, il faut bien le sécher et appliquer chaque jour la solution antiseptique prescrite par le médecin.', title_hi = 'गर्भनाल सूखी और साफ़ रहनी चाहिए। ⏱️', body_hi = 'अगर गर्भनाल गीली हो जाए, तो उसे ज़रूर सुखाइए और डॉक्टर का बताया एंटीसेप्टिक घोल रोज़ लगाइए।', title_id = 'Tali pusar harus tetap kering dan bersih. ⏱️', body_id = 'Jika tali pusar basah, harus segera dikeringkan, dan larutan antiseptik yang diresepkan dokter harus digunakan setiap hari.', title_ja = 'へその緒は乾燥させて清潔に保ちましょう。⏱️', body_ja = 'へその緒がぬれたら、しっかり乾かし、お医者さんに処方された消毒液を毎日使いましょう。', title_ko = '탯줄은 건조하고 깨끗하게 유지해야 해요. ⏱️', body_ko = '탯줄이 젖으면 꼭 말려 주고, 의사가 처방한 소독액을 매일 사용해야 해요.', title_nl = 'De navelstomp moet droog en schoon blijven. ⏱️', body_nl = 'Wordt de navelstomp nat, droog hem dan goed af en gebruik dagelijks de antiseptische oplossing die je arts heeft voorgeschreven.', title_pl = 'Kikut pępowiny musi być suchy i czysty. ⏱️', body_pl = 'Jeśli kikut pępowiny się zamoczy, trzeba go osuszyć i codziennie stosować środek antyseptyczny zalecony przez lekarza.', title_pt = 'O coto umbilical deve manter-se seco e limpo. ⏱️', body_pt = 'Se o coto umbilical se molhar, deve ser bem seco e a solução antisséptica receitada pelo médico deve ser aplicada diariamente.', title_sv = 'Navelstumpen ska hållas torr och ren. ⏱️', body_sv = 'Om navelstumpen blir blöt ska den torkas ordentligt och den antiseptiska lösning som läkaren har ordinerat användas varje dag.', title_vi = 'Cuống rốn cần được giữ khô và sạch. ⏱️', body_vi = 'Nếu cuống rốn bị ướt, cần lau khô và dùng dung dịch sát khuẩn mà bác sĩ chỉ định mỗi ngày.', title_zh = '脐带残端要保持干燥清洁。⏱️', body_zh = '如果脐带残端弄湿了，一定要擦干，并每天使用医生开的消毒液。' WHERE id = '45b225f1-1304-44c7-93ed-fd6649d6138a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Date las gracias! 💖', body_es = 'Has dejado atrás el primer mes, el más difícil. Entra en el Diario de ánimo y anota la hazaña de este mes.', title_fr = 'Remerciez-vous ! 💖', body_fr = 'Vous avez franchi le premier mois, le plus difficile. Ouvrez le Journal d''humeur et notez vos exploits de ce mois.', title_hi = 'खुद को धन्यवाद दीजिए! 💖', body_hi = 'आपने पहला और सबसे मुश्किल महीना पार कर लिया। मूड डायरी खोलकर इस महीने की अपनी बहादुरी दर्ज कीजिए।', title_id = 'Berterima kasihlah pada diri sendiri! 💖', body_id = 'Anda sudah melewati bulan pertama yang paling sulit. Buka Buku Harian Suasana Hati dan catat kepahlawanan Anda bulan ini.', title_ja = '自分にありがとうを！💖', body_ja = '最初の、そしていちばん大変な1か月を乗り越えました。「気分日記」を開いて、今月のがんばりを記録しましょう。', title_ko = '스스로에게 고마워하세요! 💖', body_ko = '처음이자 가장 힘든 한 달을 지나왔어요. 기분 일기를 열고 이번 달의 활약을 기록해 보세요.', title_nl = 'Bedank jezelf! 💖', body_nl = 'Je hebt de eerste en zwaarste maand achter de rug. Open je Stemmingsdagboek en leg je heldendaden van deze maand vast.', title_pl = 'Podziękuj sobie! 💖', body_pl = 'Pierwszy i najtrudniejszy miesiąc masz za sobą. Otwórz Dziennik nastroju i zapisz swój bohaterski miesiąc.', title_pt = 'Agradeça a si mesma! 💖', body_pt = 'Deixou para trás o primeiro mês, o mais difícil. Abra o Diário de Humor e registe o seu heroísmo deste mês.', title_sv = 'Tacka dig själv! 💖', body_sv = 'Du har klarat den första och svåraste månaden. Öppna Humördagboken och anteckna din hjältebragd den här månaden.', title_vi = 'Hãy cảm ơn chính mình! 💖', body_vi = 'Mẹ đã vượt qua tháng đầu tiên, tháng khó khăn nhất. Hãy vào Nhật ký tâm trạng và ghi lại sự anh hùng của mẹ tháng này.', title_zh = '谢谢你自己！💖', body_zh = '你已经走过了第一个、也是最难的一个月。打开心情日记，记下这个月的英雄壮举吧。' WHERE id = 'ed8acfc1-dd31-48da-a8f2-04bd91f60de7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se desordena la rutina de la tarde? 🌙', body_es = 'No te preocupes. Elige el sonido de latidos en Ruido blanco para que se sienta tan seguro como en el vientre materno.', title_fr = 'La routine du soir est chamboulée ? 🌙', body_fr = 'Pas d''inquiétude. Choisissez le son des battements de cœur dans les Bruits blancs pour qu''il se sente en sécurité, comme dans le ventre de sa maman.', title_hi = 'शाम का रूटीन बिगड़ रहा है? 🌙', body_hi = 'चिंता मत कीजिए। व्हाइट नॉइज़ में दिल की धड़कन की आवाज़ चुनिए, ताकि वह गर्भ की तरह सुरक्षित महसूस करे।', title_id = 'Rutinitas malam berantakan? 🌙', body_id = 'Jangan khawatir. Pilih suara detak jantung dari Suara Putih agar ia merasa aman seperti di dalam rahim.', title_ja = '夜のリズムが乱れていますか？🌙', body_ja = '心配いりません。「ホワイトノイズ」から心臓の音を選んで、お腹の中にいたときのように安心させてあげましょう。', title_ko = '저녁 루틴이 흐트러졌나요? 🌙', body_ko = '걱정 마세요. 백색소음에서 심장 소리를 골라 주면 아기가 엄마 뱃속에 있을 때처럼 안심할 거예요.', title_nl = 'Loopt het avondritme in de war? 🌙', body_nl = 'Geen zorgen. Kies het hartslaggeluid in Witte ruis, zodat je baby zich net zo veilig voelt als in de buik.', title_pl = 'Wieczorna rutyna się rozsypuje? 🌙', body_pl = 'Nie martw się. Wybierz w Białym szumie dźwięk bicia serca, by dziecko czuło się bezpiecznie jak w brzuchu mamy.', title_pt = 'A rotina da noite está desregulada? 🌙', body_pt = 'Não se preocupe. Escolha o som do batimento cardíaco no Ruído Branco para o bebé se sentir seguro como no ventre da mãe.', title_sv = 'Spricker kvällsrutinen? 🌙', body_sv = 'Oroa dig inte. Välj hjärtslagsljudet i Vitt brus så att barnet känner sig lika tryggt som i magen.', title_vi = 'Nếp sinh hoạt buổi tối bị xáo trộn? 🌙', body_vi = 'Đừng lo. Hãy chọn âm thanh nhịp tim trong Tiếng ồn trắng để bé thấy an toàn như khi còn trong bụng mẹ.', title_zh = '晚间作息被打乱了？🌙', body_zh = '别担心。在白噪音里选择心跳声，让宝宝像在妈妈肚子里时一样感到安全。' WHERE id = '2037f6e8-905d-4847-8172-fdba3ba09cf5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'A veces solo necesitamos un descanso. ☕', body_es = 'Cuando tu bebé duerma, pon en marcha el temporizador de sueño y reserva un rato tranquilo para ti.', title_fr = 'Parfois, on a juste besoin d''une pause. ☕', body_fr = 'Pendant que votre bébé dort, lancez le minuteur de sommeil et accordez-vous un moment de calme.', title_hi = 'कभी-कभी हमें बस एक ब्रेक चाहिए। ☕', body_hi = 'बच्चा सोए, तो स्लीप टाइमर चालू कीजिए और अपने लिए शांत समय निकालिए।', title_id = 'Terkadang kita hanya butuh jeda. ☕', body_id = 'Saat bayi Anda tidur, nyalakan pengatur waktu tidur dan sisihkan waktu tenang untuk diri sendiri.', title_ja = 'ときには休憩が必要です。☕', body_ja = '赤ちゃんが眠ったら睡眠タイマーをオンにして、自分のための静かな時間をとりましょう。', title_ko = '가끔은 그저 쉼이 필요해요. ☕', body_ko = '아기가 잘 때 수면 타이머를 켜고 나만의 조용한 시간을 가져 보세요.', title_nl = 'Soms hebben we gewoon een pauze nodig. ☕', body_nl = 'Zet de Slaaptimer aan als je baby slaapt en neem rustig tijd voor jezelf.', title_pl = 'Czasem po prostu potrzebujemy przerwy. ☕', body_pl = 'Gdy dziecko śpi, włącz timer snu i znajdź spokojną chwilę dla siebie.', title_pt = 'Às vezes, só precisamos de uma pausa. ☕', body_pt = 'Quando o bebé dormir, ligue o temporizador de sono e reserve um momento tranquilo para si.', title_sv = 'Ibland behöver vi bara en paus. ☕', body_sv = 'Starta sömntimern när barnet sover och ta en lugn stund för dig själv.', title_vi = 'Đôi khi mình chỉ cần nghỉ một chút. ☕', body_vi = 'Khi bé ngủ, hãy bật Bộ hẹn giờ ngủ và dành cho mình một khoảng thời gian yên tĩnh.', title_zh = '有时我们只是需要歇一歇。☕', body_zh = '宝宝睡觉时打开睡眠计时器，给自己留一段安静的时光。' WHERE id = '63fcc8ee-0343-4d14-8f0d-e6d98a5377e8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pasa más tiempo despierto. ⏱️', body_es = 'Para jugar con él y apoyar su desarrollo, lee las ideas de juego de la sección Blog.', title_fr = 'Ses périodes d''éveil s''allongent. ⏱️', body_fr = 'Pour jouer avec lui et soutenir son développement, lisez les idées de jeux de la rubrique Blogs.', title_hi = 'जागने का समय बढ़ रहा है। ⏱️', body_hi = 'उसके साथ खेलने और उसके विकास में मदद के लिए ब्लॉग सेक्शन में खेल के सुझाव पढ़िए।', title_id = 'Waktu terjaganya makin panjang. ⏱️', body_id = 'Baca saran bermain di bagian Blog untuk bermain bersamanya dan mendukung perkembangannya.', title_ja = '起きている時間が長くなってきました。⏱️', body_ja = '赤ちゃんと遊んで発達をサポートするために、ブログの遊びのアイデアを読んでみましょう。', title_ko = '깨어 있는 시간이 길어지고 있어요. ⏱️', body_ko = '아기와 놀며 발달을 도우려면 블로그 섹션의 놀이 추천 글을 읽어 보세요.', title_nl = 'De wakkere periodes worden langer. ⏱️', body_nl = 'Lees de speltips in het onderdeel Blogs om met je baby te spelen en de ontwikkeling te ondersteunen.', title_pl = 'Czuwanie trwa coraz dłużej. ⏱️', body_pl = 'Przeczytaj w sekcji Blogi propozycje zabaw, by bawić się z dzieckiem i wspierać jego rozwój.', title_pt = 'O tempo acordado está a aumentar. ⏱️', body_pt = 'Para brincar com o bebé e apoiar o desenvolvimento, leia as sugestões de brincadeiras na secção Blogues.', title_sv = 'Den vakna tiden blir längre. ⏱️', body_sv = 'Läs lektipsen i Bloggen för att leka med barnet och stödja utvecklingen.', title_vi = 'Thời gian thức của bé dài hơn. ⏱️', body_vi = 'Hãy đọc gợi ý trò chơi trong mục Blog để chơi cùng bé và hỗ trợ bé phát triển.', title_zh = '清醒时间越来越长。⏱️', body_zh = '想和宝宝玩耍并促进发育，就读读博客板块里的游戏建议吧。' WHERE id = 'b61a8e62-d1c0-449f-9d5b-6bb72079c512' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Una alimentación rica en vitaminas es muy importante para las mamás! 🥗', body_es = 'Echa un vistazo a la sección de Recetas saludables y recupera fuerzas.', title_fr = 'Une alimentation riche en vitamines est essentielle pour les mamans ! 🥗', body_fr = 'Parcourez la rubrique Recettes saines et retrouvez vos forces.', title_hi = 'माँओं के लिए विटामिन से भरपूर खाना बहुत ज़रूरी है! 🥗', body_hi = 'सेहतमंद रेसिपी सेक्शन देखिए और अपनी ताकत वापस पाइए।', title_id = 'Nutrisi kaya vitamin sangat penting bagi ibu! 🥗', body_id = 'Lihat bagian Resep Sehat dan pulihkan kekuatan Anda.', title_ja = 'ママのビタミンたっぷりの食事はとても大切！🥗', body_ja = '「ヘルシーレシピ」セクションをのぞいて、体力を回復しましょう。', title_ko = '엄마의 비타민 가득한 식사가 정말 중요해요! 🥗', body_ko = '건강한 레시피 섹션을 살펴보고 기운을 되찾으세요.', title_nl = 'Vitaminerijk eten is heel belangrijk voor mama’s! 🥗', body_nl = 'Kijk in het onderdeel Gezonde recepten en herwin je kracht.', title_pl = 'Bogata w witaminy dieta mamy jest bardzo ważna! 🥗', body_pl = 'Zajrzyj do sekcji ze zdrowymi przepisami i odzyskaj siły.', title_pt = 'Uma alimentação rica em vitaminas é muito importante para as mães! 🥗', body_pt = 'Veja a secção de receitas saudáveis e recupere as forças.', title_sv = 'Vitaminrik kost är väldigt viktig för mammor! 🥗', body_sv = 'Kika in i avsnittet Hälsosamma recept och återfå dina krafter.', title_vi = 'Chế độ ăn giàu vitamin rất quan trọng với mẹ! 🥗', body_vi = 'Hãy xem mục Công thức lành mạnh và lấy lại sức khỏe nhé.', title_zh = '妈妈摄入丰富的维生素非常重要！🥗', body_zh = '看看健康食谱板块，恢复你的体力吧。' WHERE id = 'a63353e6-5360-4f33-ba4b-ae8f83d9831a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Preparación para el próximo mes. 🛒', body_es = 'Si buscas pañales y productos de cuidado para su nuevo mes, los Productos recomendados te ayudarán sin duda.', title_fr = 'Préparez le mois prochain. 🛒', body_fr = 'Vous cherchez des couches et des produits de soin adaptés à ce nouveau mois ? Les Produits recommandés vous aideront à coup sûr.', title_hi = 'अगले महीने की तैयारी। 🛒', body_hi = 'अगर नए महीने के लिए सही डायपर और देखभाल की चीज़ें ढूँढ रही हैं, तो सुझाए गए प्रोडक्ट ज़रूर काम आएँगे।', title_id = 'Persiapan untuk bulan berikutnya. 🛒', body_id = 'Jika Anda mencari popok dan perlengkapan perawatan yang sesuai untuk bulan barunya, Produk Rekomendasi pasti akan membantu.', title_ja = '来月の準備。🛒', body_ja = '新しい月に合ったおむつやケア用品を探しているなら、「おすすめ商品」がきっと役に立ちます。', title_ko = '다음 달 준비. 🛒', body_ko = '새로운 달에 맞는 기저귀와 돌봄 용품을 찾고 있다면 추천 제품이 꼭 도움이 될 거예요.', title_nl = 'Klaar voor de volgende maand. 🛒', body_nl = 'Op zoek naar luiers en verzorgingsproducten voor de nieuwe maand? Aanbevolen producten helpt je zeker verder.', title_pl = 'Przygotowania do kolejnego miesiąca. 🛒', body_pl = 'Jeśli szukasz pieluszek i kosmetyków na nowy miesiąc, sekcja Polecane produkty na pewno ci pomoże.', title_pt = 'Preparação para o próximo mês. 🛒', body_pt = 'Se procura fraldas e produtos de higiene adequados ao novo mês, os Produtos Recomendados vão ajudá-la de certeza.', title_sv = 'Förberedelser för nästa månad. 🛒', body_sv = 'Om du letar efter blöjor och skötselprodukter som passar den nya månaden hjälper Rekommenderade produkter dig.', title_vi = 'Chuẩn bị cho tháng tới. 🛒', body_vi = 'Nếu mẹ đang tìm tã và đồ chăm sóc phù hợp với tháng mới, mục Sản phẩm gợi ý chắc chắn sẽ giúp ích.', title_zh = '为下个月做准备。🛒', body_zh = '如果在找适合新月龄的尿布和护理用品，推荐商品一定能帮到你。' WHERE id = '111e6f27-8aef-4cfb-a5ab-60fea52474e0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Eres una mamá maravillosa! ✨', body_es = 'Ya lleváis 30 días juntos. Añade al Álbum del bebé un collage que muestre la diferencia entre el primer día y hoy.', title_fr = 'Vous êtes une maman parfaite ! ✨', body_fr = 'Déjà 30 jours ensemble. Ajoutez à l''Album de bébé un collage montrant la différence entre le premier jour et aujourd''hui.', title_hi = 'आप एक बेहतरीन माँ हैं! ✨', body_hi = 'आप 30 दिन से साथ हैं। बेबी एल्बम में पहले दिन और आज का फ़र्क दिखाने वाला कोलाज जोड़िए।', title_id = 'Anda ibu yang sempurna! ✨', body_id = 'Sudah 30 hari Anda bersama. Tambahkan kolase ke Album Bayi yang menunjukkan perbedaan hari pertama dan hari ini.', title_ja = 'あなたは完璧なママです！✨', body_ja = '一緒に過ごして30日。初日と今日の違いがわかるコラージュを「ベビーアルバム」に追加しましょう。', title_ko = '엄마는 완벽한 엄마예요! ✨', body_ko = '함께한 지 벌써 30일이에요. 첫날과 오늘의 차이를 보여 주는 콜라주를 아기 앨범에 추가해 보세요.', title_nl = 'Je bent een geweldige mama! ✨', body_nl = 'Jullie zijn al 30 dagen samen. Zet een collage in het Babyalbum die het verschil laat zien tussen de eerste dag en vandaag.', title_pl = 'Jesteś wspaniałą mamą! ✨', body_pl = 'Jesteście razem już 30 dni. Dodaj do Albumu dziecka kolaż, który pokaże różnicę między pierwszym dniem a dzisiejszym.', title_pt = 'É uma mãe perfeita! ✨', body_pt = 'Já estão juntos há 30 dias. Junte ao Álbum do Bebé uma colagem que mostre a diferença entre o primeiro dia e hoje.', title_sv = 'Du är en underbar mamma! ✨', body_sv = 'Nu har ni varit tillsammans i 30 dagar. Lägg till ett collage i Babyalbumet som visar skillnaden mellan första dagen och i dag.', title_vi = 'Mẹ là người mẹ hoàn hảo! ✨', body_vi = 'Đã 30 ngày mẹ con bên nhau. Hãy thêm vào Album của bé một bức ghép ảnh cho thấy sự khác biệt giữa ngày đầu tiên và hôm nay.', title_zh = '你是一位完美的妈妈！✨', body_zh = '你们已经在一起30天了。在宝宝相册里加一张对比第一天和今天的拼图吧。' WHERE id = '713d2aac-0316-483d-9c46-781631bb7e21' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal la talla y el peso? 📏', body_es = 'Anota los nuevos datos en la sección Seguimiento del desarrollo y analiza su curva de crecimiento personal.', title_fr = 'Comment évoluent sa taille et son poids ? 📏', body_fr = 'Notez les nouvelles mesures dans la rubrique Suivi de croissance et analysez sa courbe personnalisée.', title_hi = 'लंबाई और वज़न कैसे बढ़ रहे हैं? 📏', body_hi = 'ग्रोथ ट्रैकर सेक्शन में नए आँकड़े दर्ज कीजिए और व्यक्तिगत विकास चार्ट का विश्लेषण कीजिए।', title_id = 'Bagaimana pertambahan tinggi dan beratnya? 📏', body_id = 'Catat angka terbaru di bagian Pelacak Pertumbuhan dan analisis grafik pertumbuhan pribadinya.', title_ja = '身長と体重の伸びはどうですか？📏', body_ja = '「成長トラッカー」に新しいデータを記録して、あなただけの成長グラフをチェックしましょう。', title_ko = '키와 몸무게는 잘 늘고 있나요? 📏', body_ko = '성장 기록 섹션에 새 수치를 입력하고 나만의 성장 그래프를 분석해 보세요.', title_nl = 'Hoe gaat het met lengte en gewicht? 📏', body_nl = 'Noteer de nieuwe metingen in het onderdeel Groeitracker en bekijk de persoonlijke groeicurve.', title_pl = 'Jak rośnie wzrost i waga? 📏', body_pl = 'Zapisz nowe wyniki w sekcji Śledzenie rozwoju i przeanalizuj osobisty wykres rozwoju.', title_pt = 'Como está o crescimento em altura e peso? 📏', body_pt = 'Registe os novos valores na secção Registo de Crescimento e analise a curva de crescimento personalizada.', title_sv = 'Hur går det med längd och vikt? 📏', body_sv = 'Anteckna de nya måtten i Tillväxtspåraren och analysera den personliga tillväxtkurvan.', title_vi = 'Chiều cao và cân nặng tăng thế nào? 📏', body_vi = 'Ghi các chỉ số mới vào mục Theo dõi phát triển và phân tích biểu đồ tăng trưởng riêng của bé.', title_zh = '身高和体重增长得怎么样？📏', body_zh = '在成长记录板块记下新数据，分析宝宝的专属成长曲线。' WHERE id = '5bfad78e-cb6a-405d-8517-a356018909ca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡En busca de aire fresco! 🌳', body_es = 'Para un paseo cómodo con tu bebé, elige un sitio cercano al que se pueda entrar con el cochecito.', title_fr = 'En quête d''air frais ! 🌳', body_fr = 'Pour une promenade agréable avec bébé, choisissez un lieu proche accessible en poussette.', title_hi = 'ताज़ी हवा की तलाश में! 🌳', body_hi = 'बच्चे के साथ आराम से सैर के लिए पास की ऐसी जगह चुनिए जहाँ प्रैम लेकर जा सकें।', title_id = 'Mencari udara segar! 🌳', body_id = 'Untuk jalan-jalan nyaman bersama bayi, pilih tempat terdekat yang bisa dimasuki dengan kereta bayi.', title_ja = '新鮮な空気を求めて！🌳', body_ja = '赤ちゃんと快適にお散歩するために、ベビーカーで入れる近くの場所を選びましょう。', title_ko = '맑은 공기를 찾아서! 🌳', body_ko = '아기와 편하게 산책하려면 유모차로 들어갈 수 있는 가까운 장소를 골라 보세요.', title_nl = 'Op zoek naar frisse lucht! 🌳', body_nl = 'Kies voor een fijne wandeling met je baby een plek in de buurt die toegankelijk is met de kinderwagen.', title_pl = 'W poszukiwaniu świeżego powietrza! 🌳', body_pl = 'Na wygodny spacer z dzieckiem wybierz pobliskie miejsce, do którego wjedziesz wózkiem.', title_pt = 'À procura de ar puro! 🌳', body_pt = 'Para um passeio tranquilo com o bebé, escolha um local próximo com acesso para carrinhos de bebé.', title_sv = 'På jakt efter frisk luft! 🌳', body_sv = 'För en bekväm promenad med barnet, välj ett ställe i närheten där man kan komma in med barnvagn.', title_vi = 'Đi tìm không khí trong lành! 🌳', body_vi = 'Để dạo chơi thoải mái cùng bé, hãy chọn địa điểm gần nhà mà xe đẩy có thể vào được.', title_zh = '寻找新鲜空气！🌳', body_zh = '想和宝宝舒舒服服地散步，就选一个附近能推婴儿车进去的地方。' WHERE id = 'd87d1938-6445-47b1-b0eb-19c7a9941726' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Anacan AI siempre está a tu lado! 🤖', body_es = '¿Tienes preguntas sobre la rutina de sueño? Escribe a nuestra inteligencia artificial y te responderá al momento.', title_fr = 'Anacan AI est toujours à vos côtés ! 🤖', body_fr = 'Des questions sur son rythme de sommeil ? Écrivez à notre intelligence artificielle, elle vous répondra tout de suite.', title_hi = 'Anacan AI हमेशा आपके साथ है! 🤖', body_hi = 'नींद के रूटीन के बारे में सवाल हैं? हमारे AI को लिखिए, वह तुरंत जवाब देगा।', title_id = 'Anacan AI selalu ada untuk Anda! 🤖', body_id = 'Ada pertanyaan tentang pola tidur? Tulis ke kecerdasan buatan kami, ia akan langsung menjawab.', title_ja = 'Anacan AIはいつもそばに！🤖', body_ja = '睡眠リズムについて質問がありますか？AIに書きこめば、すぐに答えてくれます。', title_ko = 'Anacan AI가 언제나 곁에 있어요! 🤖', body_ko = '수면 패턴에 대해 궁금한 게 있나요? AI에게 물어보면 바로 답해 드려요.', title_nl = 'Anacan AI staat altijd voor je klaar! 🤖', body_nl = 'Vragen over het slaapritme? Schrijf onze AI, je krijgt meteen antwoord.', title_pl = 'Anacan AI jest zawsze przy tobie! 🤖', body_pl = 'Masz pytania o rytm snu? Napisz do naszej sztucznej inteligencji, odpowie od razu.', title_pt = 'O Anacan AI está sempre consigo! 🤖', body_pt = 'Tem perguntas sobre o horário de sono? Escreva à nossa inteligência artificial, que responde de imediato.', title_sv = 'Anacan AI finns alltid vid din sida! 🤖', body_sv = 'Har du frågor om sömnrytmen? Skriv till vår AI så svarar den direkt.', title_vi = 'Anacan AI luôn ở bên mẹ! 🤖', body_vi = 'Mẹ có câu hỏi về nếp ngủ? Hãy nhắn cho trí tuệ nhân tạo của chúng tôi, câu trả lời sẽ có ngay.', title_zh = 'Anacan AI一直在你身边！🤖', body_zh = '对睡眠规律有疑问？给我们的人工智能发消息，它会立刻回答你。' WHERE id = 'fa1d2aaa-c80f-46e8-82ed-6c8fa2ce54f1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Aumenta su capacidad de concentración! 👀', body_es = 'Fíjate en cómo sigue los objetos de la habitación. Para leer más sobre su desarrollo, entra en el Blog.', title_fr = 'Sa capacité de concentration augmente ! 👀', body_fr = 'Regardez comme il suit les objets de la pièce. Pour en savoir plus sur son développement, ouvrez les Blogs.', title_hi = 'ध्यान लगाने की क्षमता बढ़ रही है! 👀', body_hi = 'देखिए वह कमरे की चीज़ों को कैसे नज़रों से पीछा करता है। विकास के बारे में और पढ़ने के लिए ब्लॉग देखिए।', title_id = 'Kemampuan fokusnya meningkat! 👀', body_id = 'Perhatikan bagaimana ia mengikuti benda-benda di kamar. Buka Blog untuk membaca lebih lanjut tentang perkembangannya.', title_ja = '集中する力が伸びています！👀', body_ja = '部屋の中のものを目で追う様子を見てみましょう。発達についてもっと知りたいときは、ブログをご覧ください。', title_ko = '집중하는 능력이 자라고 있어요! 👀', body_ko = '아기가 방 안의 물건을 어떻게 눈으로 따라가는지 보세요. 발달에 대해 더 알고 싶다면 블로그를 방문하세요.', title_nl = 'Het concentratievermogen groeit! 👀', body_nl = 'Kijk hoe je baby de dingen in de kamer volgt. Lees meer over de ontwikkeling in de Blogs.', title_pl = 'Rośnie umiejętność skupienia uwagi! 👀', body_pl = 'Zobacz, jak śledzi wzrokiem przedmioty w pokoju. Więcej o rozwoju przeczytasz na Blogu.', title_pt = 'A capacidade de concentração está a aumentar! 👀', body_pt = 'Veja como segue os objetos do quarto com o olhar. Para ler mais sobre o desenvolvimento, visite os Blogues.', title_sv = 'Förmågan att koncentrera sig ökar! 👀', body_sv = 'Se hur barnet följer sakerna i rummet med blicken. Gå in i Bloggen för att läsa mer om utvecklingen.', title_vi = 'Khả năng tập trung tăng lên! 👀', body_vi = 'Hãy xem bé dõi theo đồ vật trong phòng thế nào. Vào mục Blog để đọc thêm về sự phát triển của bé.', title_zh = '专注力在增强！👀', body_zh = '看看宝宝是怎样追视房间里的物品的。想了解更多发育知识，就去看看博客吧。' WHERE id = '0ac0ad4d-776b-416d-a345-c0bddd639ff1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Las mamás necesitan energía! 🍳', body_es = 'Recupera fuerzas con un batido rico y fácil de preparar de las Recetas saludables.', title_fr = 'Les mamans ont besoin d''énergie ! 🍳', body_fr = 'Retrouvez vos forces avec un délicieux smoothie facile à préparer, tiré des recettes saines.', title_hi = 'माँओं को ऊर्जा चाहिए! 🍳', body_hi = 'सेहतमंद रेसिपी से आसानी से बनने वाली स्वादिष्ट स्मूदी से अपनी ताकत लौटाइए।', title_id = 'Ibu butuh energi! 🍳', body_id = 'Pulihkan tenaga Anda dengan smoothie lezat yang mudah dibuat dari Resep Sehat.', title_ja = 'ママにはエネルギーが必要！🍳', body_ja = 'ヘルシーレシピのかんたんでおいしいスムージーで、元気を取り戻しましょう。', title_ko = '엄마에게는 에너지가 필요해요! 🍳', body_ko = '건강한 레시피의 간단하고 맛있는 스무디로 기운을 되찾으세요.', title_nl = 'Mama’s hebben energie nodig! 🍳', body_nl = 'Herwin je kracht met een lekkere, makkelijke smoothie uit Gezonde recepten.', title_pl = 'Mamy potrzebują energii! 🍳', body_pl = 'Odzyskaj siły dzięki pysznemu, łatwemu smoothie z sekcji Zdrowe przepisy.', title_pt = 'As mães precisam de energia! 🍳', body_pt = 'Recupere as forças com um smoothie saboroso e fácil de fazer das receitas saudáveis.', title_sv = 'Mammor behöver energi! 🍳', body_sv = 'Återfå krafterna med en god och lättlagad smoothie från Hälsosamma recept.', title_vi = 'Mẹ cần năng lượng! 🍳', body_vi = 'Hãy phục hồi sức lực với một ly sinh tố ngon, dễ làm từ Công thức lành mạnh.', title_zh = '妈妈需要能量！🍳', body_zh = '用健康食谱里一款简单美味的奶昔恢复体力吧。' WHERE id = 'c7ce3717-a6e8-4d86-ba21-d6964fb4fd5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Suelta el cansancio del día. 🛁', body_es = 'Dedícate un tiempo y relájate escribiendo cómo te sientes hoy en el Diario de ánimo.', title_fr = 'Chassez la fatigue de la journée. 🛁', body_fr = 'Prenez du temps pour vous et détendez-vous en écrivant vos ressentis du jour dans le Journal d''humeur.', title_hi = 'दिन की थकान उतारिए। 🛁', body_hi = 'अपने लिए समय निकालिए और आज की भावनाएँ मूड डायरी में लिखकर आराम कीजिए।', title_id = 'Lepaskan lelah hari ini. 🛁', body_id = 'Luangkan waktu untuk diri sendiri dan bersantailah dengan menuliskan perasaan Anda hari ini di Buku Harian Suasana Hati.', title_ja = '1日の疲れをリセット。🛁', body_ja = '自分のための時間をとって、今日の気持ちを「気分日記」に書いてリラックスしましょう。', title_ko = '하루의 피로를 날려 버려요. 🛁', body_ko = '나를 위한 시간을 가지고, 오늘의 감정을 기분 일기에 적으며 편히 쉬세요.', title_nl = 'Schud de vermoeidheid van de dag van je af. 🛁', body_nl = 'Neem tijd voor jezelf en ontspan door je gevoelens van vandaag in je Stemmingsdagboek te schrijven.', title_pl = 'Zrzuć z siebie zmęczenie dnia. 🛁', body_pl = 'Znajdź czas dla siebie i odpocznij, zapisując dzisiejsze uczucia w Dzienniku nastroju.', title_pt = 'Livre-se do cansaço do dia. 🛁', body_pt = 'Reserve tempo para si e relaxe escrevendo o que sente hoje no Diário de Humor.', title_sv = 'Skaka av dig dagens trötthet. 🛁', body_sv = 'Ta tid för dig själv och slappna av genom att skriva ner dagens känslor i Humördagboken.', title_vi = 'Gác lại mệt mỏi của ngày. 🛁', body_vi = 'Dành thời gian cho bản thân và thư giãn bằng cách viết cảm xúc hôm nay vào Nhật ký tâm trạng.', title_zh = '卸下一天的疲惫。🛁', body_zh = '给自己一点时间，把今天的感受写进心情日记，放松一下。' WHERE id = '282baeb2-eb26-44cb-9eff-2eb2d88677a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le cuesta dormirse? 🌙', body_es = 'Elige en Ruido blanco el sonido de las olas del mar y descansa tú también mientras se queda profundamente dormido.', title_fr = 'Il a du mal à s''endormir ? 🌙', body_fr = 'Choisissez le bruit des vagues dans les Bruits blancs, et reposez-vous pendant qu''il s''endort profondément.', title_hi = 'सोने में मुश्किल हो रही है? 🌙', body_hi = 'व्हाइट नॉइज़ में समुद्र की लहरों की आवाज़ चुनिए, वह गहरी नींद में जाए तो आप भी आराम कीजिए।', title_id = 'Sulit tertidur? 🌙', body_id = 'Pilih suara ombak laut dari Suara Putih, dan saat ia terlelap, Anda pun beristirahat.', title_ja = 'なかなか寝つけない？🌙', body_ja = '「ホワイトノイズ」から波の音を選んで、赤ちゃんが深い眠りにつく間、ママも休みましょう。', title_ko = '잠들기 힘들어하나요? 🌙', body_ko = '백색소음에서 파도 소리를 골라 주세요. 아기가 깊이 잠드는 동안 엄마도 쉬세요.', title_nl = 'Moeite met inslapen? 🌙', body_nl = 'Kies het geluid van oceaangolven in Witte ruis en rust zelf ook uit terwijl je baby diep in slaap valt.', title_pl = 'Trudno mu zasnąć? 🌙', body_pl = 'Wybierz w Białym szumie szum fal oceanu, a gdy dziecko zapadnie w głęboki sen, ty też odpocznij.', title_pt = 'Tem dificuldade em adormecer? 🌙', body_pt = 'Escolha o som das ondas do mar no Ruído Branco e descanse enquanto ele adormece profundamente.', title_sv = 'Svårt att somna? 🌙', body_sv = 'Välj ljudet av havsvågor i Vitt brus och vila du också medan barnet somnar djupt.', title_vi = 'Bé khó vào giấc? 🌙', body_vi = 'Hãy chọn âm thanh sóng biển trong Tiếng ồn trắng, khi bé chìm vào giấc ngủ sâu, mẹ cũng nghỉ ngơi nhé.', title_zh = '入睡困难？🌙', body_zh = '在白噪音里选择海浪声，宝宝沉沉睡去时，你也休息一下。' WHERE id = '77d01c80-0ffb-4089-a192-db04bf909aa1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Prepárate para las sonrisas! 😊', body_es = 'Las sonrisas sociales pueden empezar en cualquier momento. Ten el móvil a mano.', title_fr = 'Préparez-vous aux sourires ! 😊', body_fr = 'Les sourires sociaux peuvent arriver à tout moment. Gardez votre téléphone à portée de main.', title_hi = 'मुस्कान के लिए तैयार रहिए! 😊', body_hi = 'सामाजिक मुस्कानें कभी भी शुरू हो सकती हैं। फ़ोन तैयार रखिए।', title_id = 'Bersiaplah untuk senyumannya! 😊', body_id = 'Senyum sosial bisa dimulai kapan saja. Siapkan ponsel Anda.', title_ja = '笑顔の準備はいいですか？😊', body_ja = '人に向けた笑顔がいつ始まってもおかしくありません。スマホを準備しておきましょう。', title_ko = '미소를 맞을 준비를 하세요! 😊', body_ko = '사회적 미소가 언제든 시작될 수 있어요. 휴대폰을 준비해 두세요.', title_nl = 'Klaar voor de eerste lachjes! 😊', body_nl = 'De sociale glimlach kan elk moment beginnen. Houd je telefoon bij de hand.', title_pl = 'Przygotuj się na uśmiechy! 😊', body_pl = 'Uśmiechy społeczne mogą pojawić się w każdej chwili. Miej telefon pod ręką.', title_pt = 'Prepare-se para os sorrisos! 😊', body_pt = 'Os sorrisos sociais podem começar a qualquer momento. Tenha o telemóvel à mão.', title_sv = 'Gör dig redo för leenden! 😊', body_sv = 'De sociala leendena kan börja när som helst. Ha telefonen redo.', title_vi = 'Sẵn sàng đón nụ cười! 😊', body_vi = 'Nụ cười giao tiếp có thể bắt đầu bất cứ lúc nào. Hãy để sẵn điện thoại nhé.', title_zh = '准备迎接微笑吧！😊', body_zh = '社交性微笑随时可能出现。把手机准备好。' WHERE id = '367f3154-4760-43d6-b507-b914372b7538' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te reconoce por tu olor y tu voz! 👃', body_es = 'Por eso, cuando sales de la habitación, tu bebé se siente inquieto e inseguro.', title_fr = 'Il vous reconnaît à votre odeur et à votre voix ! 👃', body_fr = 'C''est pourquoi, quand vous quittez la pièce, votre bébé se sent agité et en danger.', title_hi = 'वह आपको आपकी खुशबू और आवाज़ से पहचानता है! 👃', body_hi = 'इसीलिए जब आप कमरे से दूर जाती हैं, तो बच्चा बेचैन और असुरक्षित महसूस करता है।', title_id = 'Ia mengenali Anda dari aroma dan suara! 👃', body_id = 'Karena itu, saat Anda menjauh dari kamar, bayi Anda merasa gelisah dan tidak aman.', title_ja = '赤ちゃんはにおいと声でママがわかります！👃', body_ja = 'だからママが部屋から離れると、赤ちゃんは落ち着かず、不安を感じるのです。', title_ko = '아기는 엄마의 냄새와 목소리로 엄마를 알아봐요! 👃', body_ko = '그래서 엄마가 방에서 멀어지면 아기는 불안하고 위험하다고 느껴요.', title_nl = 'Je baby herkent je aan je geur en je stem! 👃', body_nl = 'Daarom voelt je baby zich onrustig en onveilig als je de kamer uitgaat.', title_pl = 'Rozpoznaje cię po zapachu i głosie! 👃', body_pl = 'Dlatego gdy wychodzisz z pokoju, dziecko czuje niepokój i zagrożenie.', title_pt = 'O bebé reconhece-a pelo cheiro e pela voz! 👃', body_pt = 'Por isso, quando sai do quarto, o bebé sente-se inquieto e em perigo.', title_sv = 'Barnet känner igen dig på doften och rösten! 👃', body_sv = 'Därför känner sig barnet oroligt och otryggt när du går ut ur rummet.', title_vi = 'Bé nhận ra mẹ qua mùi hương và giọng nói! 👃', body_vi = 'Vì vậy khi mẹ rời khỏi phòng, bé cảm thấy bất an, như gặp nguy hiểm.', title_zh = '宝宝通过气味和声音认出你！👃', body_zh = '所以当你离开房间时，宝宝会感到不安，觉得不安全。' WHERE id = 'e8719824-5aaa-4cf3-a9a0-c265fa3bf36c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Se oyen los primeros gorjeos! 🗣️', body_es = 'Para apoyar el desarrollo del lenguaje, repite tú también los sonidos que hace y háblale.', title_fr = 'On entend les premiers « areuh » ! 🗣️', body_fr = 'Pour soutenir son langage, répétez les sons qu''il fait et parlez-lui.', title_hi = 'पहली ''आ-गू'' आवाज़ें सुनाई दे रही हैं! 🗣️', body_hi = 'भाषा के विकास में मदद के लिए आप भी उसकी आवाज़ें दोहराइए और उससे बात कीजिए।', title_id = 'Suara ocehan pertama mulai terdengar! 🗣️', body_id = 'Untuk mendukung perkembangan bahasanya, tirukan suara yang ia keluarkan dan ajak ia bicara.', title_ja = '初めての「アーウー」が聞こえます！🗣️', body_ja = '言葉の発達をサポートするために、赤ちゃんの声をまねして話しかけてあげましょう。', title_ko = '첫 옹알이 소리가 들려요! 🗣️', body_ko = '언어 발달을 도우려면 아기가 내는 소리를 따라 하며 말을 걸어 주세요.', title_nl = 'De eerste brabbelgeluidjes! 🗣️', body_nl = 'Herhaal de geluidjes die je baby maakt en praat terug om de taalontwikkeling te ondersteunen.', title_pl = 'Słychać pierwsze gaworzenie! 🗣️', body_pl = 'Aby wspierać rozwój mowy, powtarzaj dźwięki, które wydaje, i rozmawiaj z nim.', title_pt = 'Já se ouvem os primeiros "agu"! 🗣️', body_pt = 'Para apoiar o desenvolvimento da linguagem, repita os sons que o bebé faz e fale com ele.', title_sv = 'De första jollrande ljuden hörs! 🗣️', body_sv = 'För att stödja språkutvecklingen, upprepa ljuden barnet gör och prata med det.', title_vi = 'Đã nghe thấy những tiếng "a-ưm" đầu tiên! 🗣️', body_vi = 'Để hỗ trợ bé phát triển ngôn ngữ, mẹ hãy lặp lại những âm bé phát ra và trò chuyện với bé.', title_zh = '听到第一声“啊咕”啦！🗣️', body_zh = '为了促进语言发育，你也模仿宝宝发出的声音，和宝宝聊天吧。' WHERE id = 'afe3841b-76da-4cfe-9cf7-b2077153f607' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comodidad también fuera de casa. ☕', body_es = '¿Planeas quedar con amigas? No salgas de casa sin mirar nuestro mapa de Lugares para mamás.', title_fr = 'Du confort, même hors de chez vous. ☕', body_fr = 'Vous prévoyez de voir des amies ? Ne quittez pas la maison sans consulter notre carte des Lieux adaptés aux mamans.', title_hi = 'घर से बाहर भी आराम। ☕', body_hi = 'दोस्तों से मिलने की योजना है? हमारा माँ के लिए अनुकूल जगहों का नक्शा देखे बिना घर से मत निकलिए।', title_id = 'Nyaman juga di luar rumah. ☕', body_id = 'Berencana bertemu teman? Jangan keluar rumah sebelum melihat peta Tempat Ramah Ibu kami.', title_ja = 'おでかけ先でも快適に。☕', body_ja = '友達と会う予定ですか？「ママにやさしいスポット」マップを見てから出かけましょう。', title_ko = '집 밖에서도 편안하게. ☕', body_ko = '친구들과 만날 계획인가요? 엄마 친화 장소 지도를 확인하고 나서세요.', title_nl = 'Ook buitenshuis comfortabel. ☕', body_nl = 'Een afspraak met vriendinnen gepland? Ga niet de deur uit zonder onze kaart Mamavriendelijke plekken te bekijken.', title_pl = 'Wygoda także poza domem. ☕', body_pl = 'Planujesz spotkanie z przyjaciółkami? Nie wychodź z domu bez zajrzenia na naszą mapę Miejsc przyjaznych mamom.', title_pt = 'Conforto também fora de casa. ☕', body_pt = 'Está a planear encontrar-se com amigos? Não saia de casa sem ver o nosso mapa de Locais Amigos das Mães.', title_sv = 'Bekvämt även utanför hemmet. ☕', body_sv = 'Planerar du att träffa vänner? Gå inte hemifrån utan att titta på vår karta Mammavänliga platser.', title_vi = 'Thoải mái cả khi ra ngoài. ☕', body_vi = 'Mẹ định hẹn gặp bạn bè? Đừng ra khỏi nhà khi chưa xem bản đồ Địa điểm thân thiện với mẹ.', title_zh = '出门在外也能舒舒服服。☕', body_zh = '打算和朋友见面？出门前先看看我们的妈妈友好场所地图。' WHERE id = '22e06076-dd91-4e1b-834c-b78c42879a13' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rutina mejora la calidad del sueño. 🛁', body_es = 'Báñale, dale el pecho y pon en marcha el temporizador de sueño para analizar su sueño diario en la app.', title_fr = 'La routine améliore la qualité du sommeil. 🛁', body_fr = 'Donnez le bain, la tétée, puis lancez le minuteur de sommeil pour suivre son sommeil quotidien dans l''application.', title_hi = 'रूटीन नींद की गुणवत्ता बढ़ाता है। 🛁', body_hi = 'नहलाइए, दूध पिलाइए और स्लीप टाइमर चालू करके ऐप में रोज़ की नींद का विश्लेषण कीजिए।', title_id = 'Rutinitas meningkatkan kualitas tidur. 🛁', body_id = 'Mandikan, susui, lalu nyalakan pengatur waktu tidur dan lakukan analisis tidur harian di aplikasi.', title_ja = '生活リズムで睡眠の質がアップ。🛁', body_ja = 'お風呂に入れて授乳したら、睡眠タイマーをオンにして、1日の睡眠をアプリで分析しましょう。', title_ko = '루틴은 수면의 질을 높여요. 🛁', body_ko = '목욕시키고 수유한 뒤 수면 타이머를 켜서 앱에서 하루 수면을 분석해 보세요.', title_nl = 'Een vast ritme zorgt voor betere slaap. 🛁', body_nl = 'Doe je baby in bad, geef de borst, zet de slaaptimer aan en houd de dagelijkse slaapanalyse bij in de app.', title_pl = 'Rutyna poprawia jakość snu. 🛁', body_pl = 'Wykąp, nakarm i włącz timer snu, a dzienną analizę snu prowadź w aplikacji.', title_pt = 'A rotina melhora a qualidade do sono. 🛁', body_pt = 'Dê banho, amamente e ligue o temporizador de sono para acompanhar na app a análise diária do sono.', title_sv = 'En rutin förbättrar sömnkvaliteten. 🛁', body_sv = 'Bada, amma och starta sömntimern för att göra den dagliga sömnanalysen i appen.', title_vi = 'Nếp sinh hoạt giúp ngủ ngon hơn. 🛁', body_vi = 'Tắm cho bé, cho bú và bật bộ hẹn giờ ngủ để phân tích giấc ngủ hằng ngày trong ứng dụng.', title_zh = '规律作息能提升睡眠质量。🛁', body_zh = '洗澡、喂奶，然后启动睡眠计时器，在应用里分析每天的睡眠。' WHERE id = '56603835-e00b-48c0-82ab-bbdf1844d6ac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El tiempo boca abajo se alarga! 🐢', body_es = 'Ya mantiene la cabeza más erguida. Incluye en tu rutina diaria estos ejercicios que fortalecen los músculos del cuello.', title_fr = 'Le temps sur le ventre s''allonge ! 🐢', body_fr = 'Il tient sa tête plus droite. Intégrez ces exercices qui renforcent les muscles du cou à votre routine quotidienne.', title_hi = 'पेट के बल का समय बढ़ रहा है! 🐢', body_hi = 'वह अब सिर ज़्यादा सीधा रखता है। गर्दन की मांसपेशियाँ मज़बूत करने वाली ये एक्सरसाइज़ अपने रोज़ के रूटीन में शामिल कीजिए।', title_id = 'Waktu tengkurap makin lama! 🐢', body_id = 'Ia kini menegakkan kepalanya lebih mantap. Masukkan latihan penguat otot leher ini ke rutinitas harian Anda.', title_ja = 'うつぶせ遊びの時間が長くなってきました！🐢', body_ja = 'もう頭をよりしっかり起こせるようになっています。首の筋肉を鍛えるこの運動を、毎日のリズムに取り入れましょう。', title_ko = '엎드려 있는 시간이 길어져요! 🐢', body_ko = '아기가 이제 고개를 더 똑바로 들어요. 목 근육을 튼튼하게 하는 이 운동을 매일 루틴에 넣어 보세요.', title_nl = 'De buikligging duurt langer! 🐢', body_nl = 'Je baby houdt het hoofdje al steviger rechtop. Neem deze oefeningen voor de nekspieren op in je dagelijkse routine.', title_pl = 'Czas na brzuszku się wydłuża! 🐢', body_pl = 'Już pewniej trzyma główkę. Włącz te ćwiczenia wzmacniające mięśnie szyi do codziennej rutyny.', title_pt = 'O tempo de barriga para baixo está a aumentar! 🐢', body_pt = 'O bebé já segura a cabeça mais direita. Inclua na rotina diária estes exercícios que fortalecem os músculos do pescoço.', title_sv = 'Magläget blir längre! 🐢', body_sv = 'Barnet håller nu huvudet mer upprätt. Gör de här övningarna som stärker nackmusklerna till en del av er dagliga rutin.', title_vi = 'Thời gian nằm sấp dài hơn! 🐢', body_vi = 'Bé đã giữ đầu thẳng hơn. Hãy đưa những bài tập tăng cường cơ cổ này vào nếp sinh hoạt hằng ngày.', title_zh = '趴趴时间越来越长！🐢', body_zh = '宝宝已经能把头抬得更稳了。把这些增强颈部肌肉的练习加入日常安排吧。' WHERE id = '173da4aa-4d6e-4106-ab0c-34773a383b02' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Miramos tus estadísticas de pañales? 📊', body_es = 'Entra en la app Anacan y compara los datos de pañales de los últimos días. ¿Todo va bien?', title_fr = 'On regarde vos statistiques de change ? 📊', body_fr = 'Ouvrez l''application Anacan et comparez les données de couches des derniers jours. Tout va bien ?', title_hi = 'डायपर के आँकड़े देखें? 📊', body_hi = 'Anacan ऐप खोलिए और पिछले दिनों के डायपर डेटा की तुलना कीजिए। सब ठीक है?', title_id = 'Lihat statistik ganti popok yuk? 📊', body_id = 'Buka aplikasi Anacan dan bandingkan data popok beberapa hari terakhir. Semuanya baik-baik saja?', title_ja = 'おむつのデータを見てみましょう？📊', body_ja = 'Anacanアプリを開いて、ここ数日のおむつのデータを比べてみましょう。すべて順調ですか？', title_ko = '기저귀 통계를 볼까요? 📊', body_ko = 'Anacan 앱에서 최근 며칠간의 기저귀 기록을 비교해 보세요. 모든 게 괜찮나요?', title_nl = 'Zullen we je luierstatistieken bekijken? 📊', body_nl = 'Open de Anacan-app en vergelijk de luiergegevens van de afgelopen dagen. Is alles in orde?', title_pl = 'Zajrzymy do statystyk pieluszek? 📊', body_pl = 'Wejdź do aplikacji Anacan i porównaj dane pieluszek z ostatnich dni. Wszystko w porządku?', title_pt = 'Vamos ver as estatísticas das fraldas? 📊', body_pt = 'Entre na app Anacan e compare os dados das fraldas dos últimos dias. Está tudo bem?', title_sv = 'Ska vi titta på blöjstatistiken? 📊', body_sv = 'Öppna Anacan-appen och jämför blöjuppgifterna från de senaste dagarna. Är allt som det ska?', title_vi = 'Cùng xem thống kê thay tã nhé? 📊', body_vi = 'Vào ứng dụng Anacan và so sánh dữ liệu tã mấy ngày gần đây. Mọi thứ có ổn không?', title_zh = '来看看换尿布统计？📊', body_zh = '打开Anacan应用，对比一下最近几天的尿布数据。一切正常吗？' WHERE id = '3c5122e2-a92c-4444-baa3-d7b7fdd4786f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tomas y descansos. 🤱', body_es = 'Mide cada toma con la herramienta de Seguimiento de tomas y mejora aún más tu rutina.', title_fr = 'Repas et intervalles. 🤱', body_fr = 'Mesurez chaque tétée avec l''outil Suivi des repas pour améliorer encore votre routine.', title_hi = 'फ़ीडिंग और ब्रेक। 🤱', body_hi = 'हर फ़ीडिंग का समय फ़ीडिंग ट्रैकर से मापकर अपना रूटीन और बेहतर बनाइए।', title_id = 'Menyusu dan jedanya. 🤱', body_id = 'Ukur setiap sesi menyusui dengan alat Pemantau Menyusu untuk menyempurnakan rutinitas Anda.', title_ja = '授乳と間隔。🤱', body_ja = '授乳のたびに授乳記録ツールで時間を測って、リズムをさらに整えましょう。', title_ko = '수유와 간격. 🤱', body_ko = '수유할 때마다 수유 기록 도구로 시간을 재면서 루틴을 더 좋게 만들어 보세요.', title_nl = 'Voedingen en pauzes. 🤱', body_nl = 'Meet elke voeding met de Voedingstracker en maak je ritme nog beter.', title_pl = 'Karmienie i przerwy. 🤱', body_pl = 'Mierz każde karmienie piersią w narzędziu do śledzenia karmienia i jeszcze lepiej dopracuj swoją rutynę.', title_pt = 'Alimentação e pausas. 🤱', body_pt = 'Meça a duração de cada mamada com o Registo de Alimentação e aperfeiçoe ainda mais a sua rotina.', title_sv = 'Matning och pauser. 🤱', body_sv = 'Mät varje amning med verktyget Matningskoll och finslipa er rutin ännu mer.', title_vi = 'Cữ bú và khoảng nghỉ. 🤱', body_vi = 'Hãy đo thời gian mỗi cữ bú bằng công cụ Theo dõi cữ bú để hoàn thiện nếp sinh hoạt của mẹ và bé.', title_zh = '喂养与间隔。🤱', body_zh = '用喂养记录工具记录每次哺乳的时长，让你的日常安排更完善。' WHERE id = '041b2f2c-3594-4ff1-96a1-f589206d267b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cómo estás de ánimo, querida mamá? 💖', body_es = 'A veces todo se junta. Abre tu Diario de ánimo y desahógate con libertad.', title_fr = 'Comment allez-vous, chère maman ? 💖', body_fr = 'Parfois, tout peut s''accumuler. Ouvrez votre Journal d''humeur et videz librement votre cœur.', title_hi = 'आपका मूड कैसा है, प्यारी माँ? 💖', body_hi = 'कभी-कभी सब कुछ एक साथ आ जाता है। मूड डायरी खोलिए और खुलकर मन की बात लिखिए।', title_id = 'Bagaimana suasana hati Anda, Bunda tersayang? 💖', body_id = 'Terkadang semuanya bisa datang bersamaan. Buka Buku Harian Suasana Hati dan curahkan isi hati Anda dengan bebas.', title_ja = '気分はいかがですか、ママ？💖', body_ja = 'ときには、いろいろなことが重なってしまうことも。「気分日記」を開いて、思いきり気持ちを書き出しましょう。', title_ko = '기분은 어떠세요, 사랑하는 엄마? 💖', body_ko = '가끔은 모든 게 한꺼번에 몰려올 수 있어요. 기분 일기를 열고 마음껏 털어놓으세요.', title_nl = 'Hoe gaat het met je, lieve mama? 💖', body_nl = 'Soms komt alles tegelijk. Open je Stemmingsdagboek en stort vrijuit je hart uit.', title_pl = 'Jak twój nastrój, droga mamo? 💖', body_pl = 'Czasem wszystko może się na siebie nałożyć. Otwórz Dziennik nastroju i wyrzuć z siebie wszystko.', title_pt = 'Como está o seu humor, querida mãe? 💖', body_pt = 'Às vezes, tudo se acumula. Abra o Diário de Humor e desabafe à vontade.', title_sv = 'Hur mår du, kära mamma? 💖', body_sv = 'Ibland kan allt komma på en gång. Öppna Humördagboken och skriv fritt av dig.', title_vi = 'Mẹ yêu, tâm trạng mẹ thế nào? 💖', body_vi = 'Đôi khi mọi thứ dồn dập cùng lúc. Hãy mở Nhật ký tâm trạng và thoải mái trút bầu tâm sự.', title_zh = '亲爱的妈妈，你心情怎么样？💖', body_zh = '有时所有事情会一下子压过来。打开心情日记，尽情倾诉吧。' WHERE id = 'bae9c6f0-b7fe-4fe9-ba7a-7ba60aceb9ec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un cuidado especial para la piel de tu bebé. 🧴', body_es = 'Descubre en nuestro blog de Productos recomendados lo mejor para su piel de terciopelo, elegido por otras mamás.', title_fr = 'Des soins spéciaux pour la peau de bébé. 🧴', body_fr = 'Découvrez les meilleurs produits pour sa peau de velours, choisis par les mamans, dans notre blog Produits recommandés.', title_hi = 'बच्चे की त्वचा की खास देखभाल। 🧴', body_hi = 'उसकी मखमली त्वचा के लिए सबसे अच्छे प्रोडक्ट, जो माँओं ने चुने हैं, हमारे सुझाए गए प्रोडक्ट ब्लॉग में खोजिए।', title_id = 'Perawatan khusus untuk kulit bayi Anda. 🧴', body_id = 'Temukan produk terbaik untuk kulitnya yang selembut beludru di blog Produk Rekomendasi pilihan para ibu.', title_ja = '赤ちゃんの肌に特別なケアを。🧴', body_ja = 'ビロードのような肌にぴったりのアイテムを、ママたちが選んだ「おすすめ商品」のブログで見つけましょう。', title_ko = '아기 피부를 위한 특별한 돌봄. 🧴', body_ko = '벨벳 같은 아기 피부를 위한 최고의 제품을 엄마들이 고른 추천 제품 블로그에서 찾아보세요.', title_nl = 'Speciale verzorging voor de huid van je baby. 🧴', body_nl = 'Ontdek de beste producten voor die fluweelzachte huid in onze blog Aanbevolen producten, gekozen door mama’s.', title_pl = 'Wyjątkowa pielęgnacja skóry dziecka. 🧴', body_pl = 'Najlepsze kosmetyki do jego aksamitnej skóry, wybrane przez mamy, znajdziesz na naszym blogu Polecane produkty.', title_pt = 'Cuidados especiais para a pele do bebé. 🧴', body_pt = 'Descubra no nosso blogue Produtos Recomendados os melhores produtos escolhidos pelas mães para uma pele aveludada.', title_sv = 'Särskild omsorg om barnets hud. 🧴', body_sv = 'Upptäck de bästa produkterna för den sammetslena huden i vår blogg Rekommenderade produkter, utvalda av mammor.', title_vi = 'Chăm sóc đặc biệt cho làn da của bé. 🧴', body_vi = 'Khám phá những sản phẩm tốt nhất cho làn da mịn như nhung của bé, do các mẹ lựa chọn, trong blog Sản phẩm gợi ý.', title_zh = '宝宝肌肤的特别护理。🧴', body_zh = '在妈妈们精选的推荐商品博客里，为宝宝丝绒般的肌肤找到最好的护理用品。' WHERE id = 'cb8cc6b6-0d64-4498-81ae-bc15f03ad73b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Movimiento contra los gases! 🚴', body_es = 'Mientras le haces la bicicleta con las piernas, pon de fondo el Ruido blanco para que se divierta y se relaje.', title_fr = 'Bougeons contre les coliques ! 🚴', body_fr = 'Pendant les mouvements de vélo, mettez les Bruits blancs en fond pour qu''il s''amuse et se détende.', title_hi = 'गैस के दर्द के खिलाफ़ हलचल! 🚴', body_hi = 'साइकिल वाली एक्सरसाइज़ करवाते समय पीछे व्हाइट नॉइज़ चलाइए, ताकि उसका मन भी लगे और आराम भी मिले।', title_id = 'Gerakan melawan kolik! 🚴', body_id = 'Saat melakukan gerakan bersepeda, nyalakan Suara Putih di latar belakang agar ia terhibur sekaligus tenang.', title_ja = 'おなかのガスを出す運動！🚴', body_ja = '自転車こぎ運動をしながら、ホワイトノイズを流してあげましょう。楽しみながらリラックスできます。', title_ko = '가스 배앓이엔 움직임! 🚴', body_ko = '자전거 타기 동작을 할 때 백색소음을 배경으로 틀어 주면 아기가 즐겁고 편안해할 거예요.', title_nl = 'Bewegen tegen krampjes! 🚴', body_nl = 'Zet tijdens de fietsbewegingen Witte ruis op de achtergrond aan, zodat je baby plezier heeft en ontspant.', title_pl = 'Ruch przeciw kolkom! 🚴', body_pl = 'Podczas „rowerka” włącz w tle Biały szum, by dziecko i się bawiło, i uspokoiło.', title_pt = 'Movimento contra as cólicas! 🚴', body_pt = 'Enquanto faz os movimentos de bicicleta, ponha o Ruído Branco em fundo para o bebé se divertir e relaxar.', title_sv = 'Rörelse mot gasknip! 🚴', body_sv = 'När ni gör cykelrörelser, sätt på Vitt brus i bakgrunden så att barnet både har roligt och slappnar av.', title_vi = 'Vận động chống đầy hơi! 🚴', body_vi = 'Khi tập động tác đạp xe cho bé, hãy bật Tiếng ồn trắng làm nền để bé vừa vui vừa thư giãn.', title_zh = '动起来，赶走胀气！🚴', body_zh = '给宝宝做蹬自行车动作时，在背景里打开白噪音，让宝宝既开心又放松。' WHERE id = '47a30b46-d385-4b3c-979c-5465d481ef29' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Se acerca el salto de la 6.ª semana! 📈', body_es = 'Puede que tu bebé llore más de lo normal. Echa un vistazo a la sección Blog para conocer esta etapa de desarrollo y sus causas.', title_fr = 'Le pic de la 6e semaine approche ! 📈', body_fr = 'Votre bébé peut pleurer plus que d''habitude. Pour comprendre cette étape du développement et ses causes, consultez la rubrique Blogs.', title_hi = 'छठे हफ़्ते का ग्रोथ स्पर्ट करीब है! 📈', body_hi = 'आपका बच्चा सामान्य से ज़्यादा रो सकता है। इस विकास के दौर और उसकी वजहों को जानने के लिए ब्लॉग सेक्शन देखिए।', title_id = 'Lompatan minggu ke-6 sudah dekat! 📈', body_id = 'Bayi Anda mungkin lebih sering menangis dari biasanya. Lihat bagian Blog untuk memahami tahap perkembangan ini dan penyebabnya.', title_ja = '6週目のジャンプ期が近づいています！📈', body_ja = '赤ちゃんがいつもより泣くことがあるかもしれません。この発達段階と理由について、ブログで確認しましょう。', title_ko = '6주 차 급등기가 다가와요! 📈', body_ko = '아기가 평소보다 더 많이 울 수 있어요. 이 발달 단계와 그 이유를 알아보려면 블로그 섹션을 살펴보세요.', title_nl = 'De sprong van week 6 komt eraan! 📈', body_nl = 'Je baby kan meer huilen dan normaal. Lees in het onderdeel Blogs over deze ontwikkelingsfase en de oorzaken.', title_pl = 'Zbliża się skok 6. tygodnia! 📈', body_pl = 'Dziecko może płakać więcej niż zwykle. Zajrzyj do sekcji Blogi, by poznać ten etap rozwoju i jego przyczyny.', title_pt = 'Aproxima-se o salto de desenvolvimento das 6 semanas! 📈', body_pt = 'O bebé pode chorar mais do que o habitual. Veja a secção Blogues para conhecer esta fase de desenvolvimento e as suas causas.', title_sv = 'Språnget i vecka 6 närmar sig! 📈', body_sv = 'Barnet kan gråta mer än vanligt. Kika i Bloggen för att lära dig om den här utvecklingsfasen och orsakerna.', title_vi = 'Bước nhảy vọt tuần thứ 6 đang đến! 📈', body_vi = 'Bé có thể khóc nhiều hơn bình thường. Hãy xem mục Blog để tìm hiểu về giai đoạn phát triển này và nguyên nhân.', title_zh = '第6周猛长期快到了！📈', body_zh = '宝宝可能比平时哭得更多。去博客板块了解这个发育阶段及其原因吧。' WHERE id = 'a7868664-8e30-4849-9648-70deec39cf3a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de cuidarle junto a papá. 👨‍🍼', body_es = 'Después de la toma de la tarde, deja que papá se encargue de los gases y tú échate una siestecita.', title_fr = 'Le temps des soins avec Papa. 👨‍🍼', body_fr = 'Après la tétée du soir, confiez le rot à Papa et faites une petite sieste.', title_hi = 'पापा के साथ देखभाल का समय। 👨‍🍼', body_hi = 'शाम की फ़ीडिंग के बाद डकार दिलाने की बारी पापा को दीजिए, और आप एक छोटी सी झपकी ले लीजिए।', title_id = 'Waktunya merawat bersama Ayah. 👨‍🍼', body_id = 'Setelah menyusu malam, serahkan giliran menyendawakan kepada Ayah, sementara Anda tidur sejenak.', title_ja = 'パパと一緒にお世話する時間。👨‍🍼', body_ja = '夜の授乳のあとのげっぷはパパにまかせて、ママは少しうたた寝しましょう。', title_ko = '아빠와 함께하는 돌봄 시간. 👨‍🍼', body_ko = '저녁 수유 후 트림시키기는 아빠에게 맡기고, 엄마는 잠깐 눈을 붙이세요.', title_nl = 'Tijd voor samen zorgen met papa. 👨‍🍼', body_nl = 'Laat papa na de avondvoeding het boertje doen en doe jij even een kort dutje.', title_pl = 'Czas na wspólną opiekę z tatą. 👨‍🍼', body_pl = 'Po wieczornym karmieniu oddaj tacie odbijanie, a sama zdrzemnij się chwilę.', title_pt = 'Hora de cuidar do bebé com o pai. 👨‍🍼', body_pt = 'Depois da mamada da noite, deixe o pai tratar do arroto e faça uma pequena sesta.', title_sv = 'Dags för gemensam omvårdnad med pappa. 👨‍🍼', body_sv = 'Efter kvällsmatningen, låt pappa ta hand om rapningen och ta du en kort tupplur.', title_vi = 'Giờ chăm bé cùng bố. 👨‍🍼', body_vi = 'Sau cữ bú buổi tối, hãy giao lượt vỗ ợ hơi cho bố, còn mẹ chợp mắt một chút.', title_zh = '和爸爸一起照顾宝宝的时间。👨‍🍼', body_zh = '晚上喂完奶后，把拍嗝的任务交给爸爸，你去打个小盹吧。' WHERE id = 'ba4d5548-5eb3-44e1-bb68-bbab9deb11ee' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Formas naturales de aumentar la leche. 🥛', body_es = 'Para tener más leche, prueba las recetas de sopas y bebidas nutritivas de la sección Recetas saludables.', title_fr = 'Des moyens naturels d''avoir plus de lait. 🥛', body_fr = 'Pour plus de lait, essayez les recettes de soupes et de boissons nourrissantes de la rubrique Recettes saines.', title_hi = 'दूध बढ़ाने के प्राकृतिक तरीके। 🥛', body_hi = 'ज़्यादा दूध के लिए सेहतमंद रेसिपी सेक्शन के पौष्टिक सूप और पेय आज़माइए।', title_id = 'Cara alami menambah ASI. 🥛', body_id = 'Untuk ASI yang lebih banyak, coba resep sup dan minuman bergizi di bagian Resep Sehat.', title_ja = '母乳の出をよくする自然な方法。🥛', body_ja = '母乳をもっと出すために、「ヘルシーレシピ」セクションの栄養たっぷりのスープやドリンクを試してみましょう。', title_ko = '모유를 늘리는 자연스러운 방법. 🥛', body_ko = '모유를 늘리고 싶다면 건강한 레시피 섹션의 영양 가득한 수프와 음료 레시피를 시도해 보세요.', title_nl = 'Natuurlijke manieren voor meer melk. 🥛', body_nl = 'Probeer voor meer melk de voedzame soep- en drankrecepten in het onderdeel Gezonde recepten.', title_pl = 'Naturalne sposoby na więcej mleka. 🥛', body_pl = 'Aby mieć więcej mleka, wypróbuj pożywne zupy i napoje z sekcji Zdrowe przepisy.', title_pt = 'Formas naturais de aumentar o leite. 🥛', body_pt = 'Para ter mais leite, experimente as receitas de sopas e bebidas nutritivas da secção Receitas Saudáveis.', title_sv = 'Naturliga sätt att öka mjölken. 🥛', body_sv = 'För mer mjölk, prova de närande soppor och drycker som finns i avsnittet Hälsosamma recept.', title_vi = 'Cách tự nhiên giúp nhiều sữa. 🥛', body_vi = 'Để có nhiều sữa hơn, hãy thử các công thức súp và đồ uống bổ dưỡng trong mục Công thức lành mạnh.', title_zh = '天然的催奶方法。🥛', body_zh = '想要更多奶水，就试试健康食谱板块里滋补的汤和饮品吧。' WHERE id = '2a04ee0c-770e-425b-8987-e6ab25472f0b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El equilibrio diario entre tomas y sueño. ⚖', body_es = '️Analiza tus estadísticas de hoy en los gráficos de Seguimiento de tomas y de sueño y planifica el día siguiente.', title_fr = 'L''équilibre repas et sommeil de la journée. ⚖', body_fr = '️ Analysez vos statistiques du jour dans le Suivi des repas et les graphiques de sommeil, et planifiez le lendemain.', title_hi = 'रोज़ की फ़ीडिंग और नींद का संतुलन। ⚖', body_hi = '️ फ़ीडिंग ट्रैकर और नींद के चार्ट से आज के आँकड़ों का विश्लेषण कीजिए और अगले दिन की योजना बनाइए।', title_id = 'Keseimbangan menyusu dan tidur harian. ⚖', body_id = '️ Analisis statistik hari ini dari grafik Pemantau Menyusu dan tidur, lalu rencanakan hari berikutnya.', title_ja = '1日の授乳と睡眠のバランス。⚖', body_ja = '️ 授乳記録と睡眠グラフから今日のデータを分析して、明日の計画を立てましょう。', title_ko = '하루 수유와 수면의 균형. ⚖', body_ko = '️ 수유 기록과 수면 그래프로 오늘의 통계를 분석하고 다음 날을 계획해 보세요.', title_nl = 'Balans tussen voeding en slaap per dag. ⚖', body_nl = '️ Bekijk je statistieken van vandaag in de Voedingstracker en de slaapgrafieken en plan de volgende dag.', title_pl = 'Dzienna równowaga karmienia i snu. ⚖', body_pl = '️ Przeanalizuj dzisiejsze statystyki z wykresów karmienia i snu i zaplanuj kolejny dzień.', title_pt = 'O equilíbrio diário entre alimentação e sono. ⚖', body_pt = '️ Analise as estatísticas de hoje nos gráficos do Registo de Alimentação e do sono e planeie o dia seguinte.', title_sv = 'Daglig balans mellan matning och sömn. ⚖', body_sv = '️ Analysera dagens statistik i diagrammen för Matningskoll och sömn och planera nästa dag.', title_vi = 'Cân bằng cữ bú và giấc ngủ mỗi ngày. ⚖', body_vi = '️Phân tích thống kê hôm nay từ biểu đồ Theo dõi cữ bú và giấc ngủ, rồi lên kế hoạch cho ngày mai.', title_zh = '每日喂养与睡眠的平衡。⚖', body_zh = '️ 从喂养记录和睡眠图表中分析今天的统计，规划好明天。' WHERE id = '6a605601-9da6-47e9-8d07-a1f552eb5fc0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hoy terminamos la cuarentena! 🧿', body_es = 'Para hacer inolvidable este día especial y tradicional, elige temas divertidos en la sección Sesión de fotos del bebé y crea fotos.', title_fr = 'Aujourd''hui, nous fêtons nos 40 jours ! 🧿', body_fr = 'Pour rendre ce jour spécial et traditionnel inoubliable, choisissez des thèmes amusants dans la rubrique Séance photo bébé et créez de belles photos.', title_hi = 'आज हमारे 40 दिन पूरे हुए! 🧿', body_hi = 'इस खास और पारंपरिक दिन को यादगार बनाने के लिए बेबी फ़ोटोशूट सेक्शन से मज़ेदार थीम चुनकर तस्वीरें बनाइए।', title_id = 'Hari ini masa 40 hari kita selesai! 🧿', body_id = 'Agar hari istimewa dan penuh tradisi ini berkesan, pilih tema menarik di bagian Pemotretan Bayi dan buat foto-fotonya.', title_ja = '今日で産後40日！🧿', body_ja = 'この特別な伝統の日を思い出に残すために、「ベビーフォトセッション」で楽しいテーマを選んで写真をつくりましょう。', title_ko = '오늘로 산후 40일이 끝나요! 🧿', body_ko = '이 특별하고 전통적인 날을 기억에 남기려면 아기 사진 촬영 섹션에서 재미있는 테마를 골라 사진을 만들어 보세요.', title_nl = 'Vandaag zijn onze 40 dagen voorbij! 🧿', body_nl = 'Maak deze bijzondere, traditionele dag onvergetelijk: kies leuke thema’s in het onderdeel Babyfotoshoot en maak foto’s.', title_pl = 'Dziś mija nasze 40 dni! 🧿', body_pl = 'Aby ten wyjątkowy, tradycyjny dzień zapadł w pamięć, wybierz ciekawe motywy w sekcji Sesja zdjęciowa dziecka i stwórz zdjęcia.', title_pt = 'Hoje terminam os nossos 40 dias! 🧿', body_pt = 'Para tornar inesquecível este dia especial e tradicional, escolha temas divertidos na secção Sessão Fotográfica do Bebé e crie fotos.', title_sv = 'I dag är våra 40 dagar slut! 🧿', body_sv = 'Gör den här speciella och traditionella dagen minnesvärd genom att välja roliga teman och skapa bilder i avsnittet Babyfotografering.', title_vi = 'Hôm nay mình tròn 40 ngày! 🧿', body_vi = 'Để ngày đặc biệt, mang đậm truyền thống này thật đáng nhớ, hãy chọn chủ đề thú vị trong mục Chụp ảnh cho bé và tạo ảnh.', title_zh = '今天我们出月子啦（满40天）！🧿', body_zh = '为了让这个特别又传统的日子令人难忘，在宝宝写真板块选个有趣的主题拍照吧。' WHERE id = '2dcd9888-3b4b-4cb6-a25a-51c4642e3c54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una transición tranquila al sueño. 🌙', body_es = 'Al final de este día especial, oscurece la habitación, pon el Ruido blanco y duerme plácidamente mientras tu bebé se sumerge en un sueño profundo.', title_fr = 'Vers un sommeil paisible. 🌙', body_fr = 'À la fin de cette journée spéciale, tamisez la lumière, mettez les Bruits blancs et dormez paisiblement pendant que bébé s''endort profondément.', title_hi = 'सुकून भरी नींद की ओर। 🌙', body_hi = 'इस खास दिन के अंत में कमरे में अँधेरा कीजिए, व्हाइट नॉइज़ चलाइए और जब बच्चा गहरी नींद में जाए, तो आप भी चैन से सोइए।', title_id = 'Peralihan ke tidur nyenyak. 🌙', body_id = 'Di akhir hari istimewa ini, redupkan kamar, nyalakan Suara Putih, dan tidurlah nyenyak selagi bayi Anda terlelap.', title_ja = '心地よい眠りへ。🌙', body_ja = 'この特別な日の終わりに、部屋を暗くしてホワイトノイズをかけ、赤ちゃんが深く眠る間、ママもぐっすり休みましょう。', title_ko = '편안한 잠으로. 🌙', body_ko = '이 특별한 하루의 끝에 방을 어둡게 하고 백색소음을 틀어 주세요. 아기가 깊이 잠드는 동안 엄마도 푹 주무세요.', title_nl = 'Rustig naar dromenland. 🌙', body_nl = 'Maak aan het eind van deze bijzondere dag de kamer donker, zet Witte ruis aan en slaap zelf ook heerlijk terwijl je baby diep in slaap valt.', title_pl = 'Spokojne przejście w sen. 🌙', body_pl = 'Na koniec tego wyjątkowego dnia przyciemnij pokój, włącz Biały szum i śpij słodko, gdy dziecko zapada w głęboki sen.', title_pt = 'Uma transição tranquila para o sono. 🌙', body_pt = 'No fim deste dia especial, escureça o quarto, ligue o Ruído Branco e, enquanto o bebé adormece profundamente, durma também que nem um anjo.', title_sv = 'Lugn övergång till sömn. 🌙', body_sv = 'I slutet av den här speciella dagen, dämpa ljuset, sätt på Vitt brus och sov gott medan barnet somnar djupt.', title_vi = 'Nhẹ nhàng vào giấc ngủ. 🌙', body_vi = 'Cuối ngày đặc biệt này, hãy tắt bớt đèn, bật Tiếng ồn trắng và ngủ thật ngon khi bé chìm vào giấc ngủ sâu.', title_zh = '轻松进入梦乡。🌙', body_zh = '在这个特别的日子结束时，把房间调暗，打开白噪音，宝宝沉沉睡去时，你也好好睡一觉。' WHERE id = '92e4d1aa-c4f4-477c-ab81-176ef4f03a16' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cómo te sientes? ✨', body_es = '¡Has completado un periodo grande y especial de 40 días! ¡Eres una auténtica heroína!', title_fr = 'Comment vous sentez-vous ? ✨', body_fr = 'Vous avez bouclé une grande et précieuse période de 40 jours ! Vous êtes une véritable héroïne !', title_hi = 'आप कैसा महसूस कर रही हैं? ✨', body_hi = 'आपने 40 दिनों का एक बड़ा और खास दौर पूरा कर लिया! आप सच्ची हीरो हैं!', title_id = 'Bagaimana perasaan Anda? ✨', body_id = 'Anda telah menyelesaikan masa 40 hari yang besar dan istimewa! Anda pahlawan sejati!', title_ja = '気分はいかがですか？✨', body_ja = '40日間という大きくて特別な期間を終えました！あなたは本物のヒーローです！', title_ko = '기분은 어떠세요? ✨', body_ko = '40일이라는 크고 특별한 시기를 마쳤어요! 엄마는 진정한 영웅이에요!', title_nl = 'Hoe voel je je? ✨', body_nl = 'Je hebt een grote en bijzondere periode van 40 dagen afgesloten! Je bent een echte heldin!', title_pl = 'Jak się czujesz? ✨', body_pl = 'Zakończyłaś wielki i wyjątkowy 40-dniowy okres! Jesteś prawdziwą bohaterką!', title_pt = 'Como se sente? ✨', body_pt = 'Concluiu um período de 40 dias grande e especial! É uma verdadeira heroína!', title_sv = 'Hur mår du? ✨', body_sv = 'Du har avslutat en stor och speciell period på 40 dagar! Du är en riktig hjälte!', title_vi = 'Mẹ cảm thấy thế nào? ✨', body_vi = 'Mẹ đã hoàn thành chặng 40 ngày lớn lao và đặc biệt! Mẹ là một người hùng thực sự!', title_zh = '你感觉怎么样？✨', body_zh = '你完成了40天这个重要而特别的阶段！你是真正的英雄！' WHERE id = 'ba92608f-780e-4381-a0e7-3f6af86021be' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal ha ido tu día? 📝', body_es = 'Sírvete un café y relájate anotando lo que sientes hoy en el Diario de ánimo.', title_fr = 'Comment s''est passée votre journée ? 📝', body_fr = 'Servez-vous un café et détendez-vous en notant vos ressentis du jour dans le Journal d''humeur.', title_hi = 'आज का दिन कैसा रहा? 📝', body_hi = 'अपने लिए एक कप कॉफ़ी बनाइए और आज की अंदरूनी भावनाएँ मूड डायरी में लिखकर आराम कीजिए।', title_id = 'Bagaimana hari Anda? 📝', body_id = 'Tuang secangkir kopi dan bersantailah dengan mencatat perasaan terdalam Anda hari ini di Buku Harian Suasana Hati.', title_ja = '今日はどんな1日でしたか？📝', body_ja = 'コーヒーを入れて、今日の心の中の気持ちを「気分日記」に記録してリラックスしましょう。', title_ko = '오늘 하루는 어땠나요? 📝', body_ko = '커피 한 잔 따르고, 오늘의 속마음을 기분 일기에 적으며 편히 쉬세요.', title_nl = 'Hoe was je dag? 📝', body_nl = 'Schenk een kop koffie in en ontspan door je gevoelens van vandaag in je Stemmingsdagboek te noteren.', title_pl = 'Jak minął ci dzień? 📝', body_pl = 'Nalej sobie kawy i odpocznij, zapisując dzisiejsze uczucia w Dzienniku nastroju.', title_pt = 'Como correu o seu dia? 📝', body_pt = 'Sirva-se de um café e relaxe registando no Diário de Humor o que sente hoje.', title_sv = 'Hur var din dag? 📝', body_sv = 'Häll upp en kopp kaffe och slappna av genom att skriva ner dina innersta känslor i dag i Humördagboken.', title_vi = 'Hôm nay của mẹ thế nào? 📝', body_vi = 'Rót cho mình một tách cà phê và thư giãn bằng cách ghi lại cảm xúc hôm nay vào Nhật ký tâm trạng.', title_zh = '今天过得怎么样？📝', body_zh = '给自己倒杯咖啡，把今天内心的感受记在心情日记里，放松一下。' WHERE id = '6dd4f975-8504-4871-83c4-a6f7bc24a950' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Una nueva etapa después de la cuarentena! 🌸', body_es = 'Tu bebé muestra más interés por lo que le rodea. Tener tarjetas de estimulación a su alrededor le resulta beneficioso.', title_fr = 'Une nouvelle étape après les 40 jours ! 🌸', body_fr = 'Votre bébé s''intéresse davantage à ce qui l''entoure. Avoir des cartes d''éveil autour de lui est bénéfique.', title_hi = '40 दिनों के बाद नया दौर! 🌸', body_hi = 'आपका बच्चा आसपास की चीज़ों में ज़्यादा दिलचस्पी ले रहा है। उसके आसपास फ़्लैश कार्ड रखना उसके लिए फ़ायदेमंद है।', title_id = 'Babak baru setelah 40 hari! 🌸', body_id = 'Bayi Anda makin tertarik pada sekitarnya. Kartu stimulasi di sekitarnya bermanfaat untuk bayi Anda.', title_ja = '産後40日を過ぎて、新しい時期へ！🌸', body_ja = '赤ちゃんはまわりのことにもっと興味を示しています。知育カードをそばに置くと、赤ちゃんの役に立ちます。', title_ko = '40일 이후의 새로운 시기! 🌸', body_ko = '아기가 주변에 더 많은 관심을 보여요. 주변에 초점책 카드를 두면 아기에게 좋아요.', title_nl = 'Een nieuwe periode na de 40 dagen! 🌸', body_nl = 'Je baby toont meer interesse in de omgeving. Contrastkaarten in de buurt zijn goed voor je baby.', title_pl = 'Nowy etap po 40 dniach! 🌸', body_pl = 'Dziecko coraz bardziej interesuje się otoczeniem. Karty kontrastowe w jego pobliżu wspierają rozwój.', title_pt = 'Uma nova fase depois dos 40 dias! 🌸', body_pt = 'O bebé mostra cada vez mais interesse pelo que o rodeia. Ter cartões de estimulação por perto é benéfico para ele.', title_sv = 'En ny period efter de 40 dagarna! 🌸', body_sv = 'Barnet visar mer intresse för omgivningen. Det är bra för barnet att ha kontrastkort omkring sig.', title_vi = 'Giai đoạn mới sau 40 ngày! 🌸', body_vi = 'Bé ngày càng tò mò với xung quanh. Có thẻ kích thích thị giác quanh bé sẽ rất có lợi.', title_zh = '40天之后的新阶段！🌸', body_zh = '宝宝对周围越来越好奇了。身边放些早教卡片对宝宝很有好处。' WHERE id = 'c6c2469c-d36e-4ffe-a532-bee6050f4bac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal va la rutina de tomas? 🍼', body_es = 'Comprueba con la herramienta de Seguimiento de tomas y el temporizador de la app cuánto te ajustas a lo normal para cada día.', title_fr = 'Comment se passe la routine des repas ? 🍼', body_fr = 'Vérifiez avec l''outil Suivi des repas et le minuteur de l''application si vous correspondez à la norme quotidienne.', title_hi = 'फ़ीडिंग का रूटीन कैसा चल रहा है? 🍼', body_hi = 'ऐप के फ़ीडिंग ट्रैकर और टाइमर से जाँचिए कि आप रोज़ के मानक के कितने करीब हैं।', title_id = 'Bagaimana rutinitas menyusu? 🍼', body_id = 'Cek seberapa sesuai dengan angka harian menggunakan alat Pemantau Menyusu dan pengatur waktu di aplikasi.', title_ja = '授乳のリズムはどうですか？🍼', body_ja = 'アプリの授乳記録ツールとタイマーで、1日の目安にどれくらい合っているか確認しましょう。', title_ko = '수유 루틴은 잘 되고 있나요? 🍼', body_ko = '앱의 수유 기록 도구와 타이머로 하루 기준치에 얼마나 맞는지 확인하세요.', title_nl = 'Hoe gaat het voedingsritme? 🍼', body_nl = 'Kijk met de Voedingstracker en de timer in de app hoe goed je de dagelijkse norm haalt.', title_pl = 'Jak idzie rytm karmienia? 🍼', body_pl = 'Sprawdź w narzędziu do śledzenia karmienia i timerze w aplikacji, na ile trzymacie się dziennej normy.', title_pt = 'Como está a correr a rotina de alimentação? 🍼', body_pt = 'Use o Registo de Alimentação e o temporizador da app para ver se está a cumprir a quantidade diária recomendada.', title_sv = 'Hur går matningsrutinen? 🍼', body_sv = 'Kolla hur väl ni når den dagliga normen med verktyget Matningskoll och timern i appen.', title_vi = 'Nếp cho bú đang thế nào? 🍼', body_vi = 'Hãy dùng công cụ Theo dõi cữ bú và bộ hẹn giờ trong ứng dụng để kiểm tra mức độ đáp ứng định mức hằng ngày.', title_zh = '喂养规律怎么样？🍼', body_zh = '用应用里的喂养记录工具和计时器，看看你离每日参考量有多近。' WHERE id = 'd647162e-98ae-41c0-81b4-cc5ca3e15dff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Distingue mejor los colores! 🔴', body_es = 'Fíjate en cómo sigue con la mirada los objetos brillantes de la habitación.', title_fr = 'Il distingue mieux les couleurs ! 🔴', body_fr = 'Observez comment il suit du regard les objets brillants de la pièce.', title_hi = 'वह रंग बेहतर पहचानता है! 🔴', body_hi = 'देखिए वह कमरे की चमकीली चीज़ों का नज़रों से कैसे पीछा करता है।', title_id = 'Ia makin mengenali warna! 🔴', body_id = 'Perhatikan bagaimana ia mengikuti benda-benda cerah di kamar.', title_ja = '色をよりはっきり見分けられるように！🔴', body_ja = '部屋の中の明るい色のものを、どんなふうに目で追うか見てみましょう。', title_ko = '색을 더 잘 구별해요! 🔴', body_ko = '아기가 방 안의 밝은 물건을 어떻게 따라 보는지 살펴보세요.', title_nl = 'Je baby ziet kleuren beter! 🔴', body_nl = 'Let op hoe je baby felgekleurde dingen in de kamer volgt.', title_pl = 'Lepiej rozróżnia kolory! 🔴', body_pl = 'Zobacz, jak śledzi wzrokiem jaskrawe przedmioty w pokoju.', title_pt = 'Distingue melhor as cores! 🔴', body_pt = 'Repare como segue com o olhar os objetos brilhantes do quarto.', title_sv = 'Barnet skiljer färger bättre! 🔴', body_sv = 'Lägg märke till hur barnet följer klara föremål i rummet med blicken.', title_vi = 'Bé phân biệt màu sắc tốt hơn! 🔴', body_vi = 'Hãy để ý cách bé dõi theo những đồ vật sáng màu trong phòng.', title_zh = '宝宝更能分辨颜色了！🔴', body_zh = '留意宝宝是怎样追视房间里鲜艳的物品的。' WHERE id = '06dbea83-4e3d-4be5-8968-0961033df8d5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El aire fresco os sentará bien a los dos. 🌳', body_es = 'Para salir de paseo, elige en el mapa de Lugares para mamás un sitio donde se entre cómodamente con el cochecito.', title_fr = 'L''air frais vous fera du bien à tous les deux. 🌳', body_fr = 'Pour votre promenade, choisissez sur la carte des Lieux adaptés aux mamans un endroit facilement accessible en poussette.', title_hi = 'ताज़ी हवा आप दोनों के लिए अच्छी रहेगी। 🌳', body_hi = 'सैर पर जाने के लिए माँ के लिए अनुकूल जगहों के नक्शे से ऐसी जगह चुनिए जहाँ प्रैम आसानी से जा सके।', title_id = 'Udara segar akan baik untuk Anda berdua. 🌳', body_id = 'Untuk jalan-jalan, pilih tempat yang mudah dimasuki dengan kereta bayi dari peta Tempat Ramah Ibu.', title_ja = '新鮮な空気は2人にとっていいことです。🌳', body_ja = 'お散歩には、「ママにやさしいスポット」マップからベビーカーで入りやすい場所を選びましょう。', title_ko = '맑은 공기는 두 사람 모두에게 좋아요. 🌳', body_ko = '산책하러 나갈 땐 엄마 친화 장소 지도에서 유모차로 편하게 들어갈 수 있는 곳을 골라 보세요.', title_nl = 'Frisse lucht doet jullie allebei goed. 🌳', body_nl = 'Kies voor een wandeling een plek die goed toegankelijk is met de kinderwagen op de kaart Mamavriendelijke plekken.', title_pl = 'Świeże powietrze dobrze wam obojgu zrobi. 🌳', body_pl = 'Na spacer wybierz z mapy Miejsc przyjaznych mamom miejsce, do którego łatwo wjedziesz wózkiem.', title_pt = 'O ar puro vai fazer bem aos dois. 🌳', body_pt = 'Para o passeio, escolha no mapa de Locais Amigos das Mães um sítio com acesso fácil para carrinhos de bebé.', title_sv = 'Frisk luft gör er båda gott. 🌳', body_sv = 'För promenaden, välj ett ställe på kartan Mammavänliga platser där det är lätt att komma in med barnvagn.', title_vi = 'Không khí trong lành tốt cho cả hai mẹ con. 🌳', body_vi = 'Để đi dạo, hãy chọn nơi xe đẩy dễ vào trên bản đồ Địa điểm thân thiện với mẹ.', title_zh = '新鲜空气对你们俩都有好处。🌳', body_zh = '出门散步时，从妈妈友好场所地图里选一个方便推婴儿车进去的地方吧。' WHERE id = '295afbf2-1104-44c2-abf4-fb0e41a0ff0e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Facilita el paso al sueño. 🌙', body_es = 'Después del baño de la tarde, elige en Ruido blanco el sonido del secador o de la lluvia para prepararle para un sueño profundo.', title_fr = 'Facilitez l''endormissement. 🌙', body_fr = 'Après le bain du soir, choisissez le bruit du sèche-cheveux ou de la pluie dans les Bruits blancs pour le préparer à un sommeil profond.', title_hi = 'नींद में जाना आसान बनाइए। 🌙', body_hi = 'शाम के स्नान के बाद व्हाइट नॉइज़ में हेयर ड्रायर या बारिश की आवाज़ चुनकर उसे गहरी नींद के लिए तैयार कीजिए।', title_id = 'Permudah peralihan ke tidur. 🌙', body_id = 'Setelah mandi sore, pilih suara pengering rambut atau hujan dari Suara Putih untuk menyiapkannya tidur nyenyak.', title_ja = '寝かしつけをスムーズに。🌙', body_ja = '夜のお風呂のあと、「ホワイトノイズ」からドライヤーや雨の音を選んで、深い眠りの準備をしてあげましょう。', title_ko = '잠드는 과정을 쉽게 만들어요. 🌙', body_ko = '저녁 목욕 후 백색소음에서 드라이기 소리나 빗소리를 골라 아기가 깊이 잠들 준비를 도와주세요.', title_nl = 'Maak het inslapen makkelijker. 🌙', body_nl = 'Kies na het avondbadje het geluid van een haardroger of regen in Witte ruis en maak je baby klaar voor een diepe slaap.', title_pl = 'Ułatw zasypianie. 🌙', body_pl = 'Po wieczornej kąpieli wybierz w Białym szumie dźwięk suszarki lub deszczu i przygotuj dziecko do głębokiego snu.', title_pt = 'Facilite a hora de adormecer. 🌙', body_pt = 'Depois do banho da noite, escolha no Ruído Branco o som do secador de cabelo ou da chuva e prepare o bebé para um sono profundo.', title_sv = 'Gör övergången till sömn lättare. 🌙', body_sv = 'Efter kvällsbadet, välj hårtorksljudet eller regnljudet i Vitt brus och förbered barnet för djup sömn.', title_vi = 'Giúp bé vào giấc dễ hơn. 🌙', body_vi = 'Sau khi tắm tối, hãy chọn tiếng máy sấy tóc hoặc tiếng mưa trong Tiếng ồn trắng để chuẩn bị cho bé ngủ sâu.', title_zh = '让入睡更轻松。🌙', body_zh = '晚上洗完澡后，在白噪音里选吹风机声或雨声，帮宝宝准备进入深度睡眠。' WHERE id = '9f7dfdf1-83be-4fad-a93a-817e105844ce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empiezan las revisiones rutinarias. 💉', body_es = '¡Introduce la talla y el peso de tu bebé en el Seguimiento del desarrollo y crea su curva de crecimiento personal!', title_fr = 'Les examens de routine commencent. 💉', body_fr = 'Saisissez la taille et le poids de votre bébé dans le Suivi de croissance pour créer sa courbe personnalisée !', title_hi = 'रूटीन जाँचें शुरू होती हैं। 💉', body_hi = 'बच्चे की लंबाई और वज़न ग्रोथ ट्रैकर में दर्ज करके उसका व्यक्तिगत विकास चार्ट बनाइए!', title_id = 'Pemeriksaan rutin dimulai. 💉', body_id = 'Masukkan perkembangan tinggi dan berat bayi Anda ke Pelacak Pertumbuhan dan buat grafik pertumbuhan pribadinya!', title_ja = '定期健診が始まります。💉', body_ja = '赤ちゃんの身長と体重を「成長トラッカー」に入力して、あなただけの成長グラフをつくりましょう！', title_ko = '정기 검진이 시작돼요. 💉', body_ko = '아기의 키와 몸무게를 성장 기록에 입력해 나만의 성장 그래프를 만들어 보세요!', title_nl = 'De routinecontroles beginnen. 💉', body_nl = 'Voer de lengte en het gewicht van je baby in de Groeitracker in en maak een persoonlijke groeicurve!', title_pl = 'Zaczynają się rutynowe badania. 💉', body_pl = 'Wpisz wzrost i wagę dziecka do Śledzenia rozwoju i stwórz jego osobistą siatkę centylową!', title_pt = 'Começam as consultas de rotina. 💉', body_pt = 'Introduza a altura e o peso do bebé no Registo de Crescimento e crie a curva de crescimento personalizada!', title_sv = 'Rutinkontrollerna börjar. 💉', body_sv = 'Skriv in barnets längd och vikt i Tillväxtspåraren och skapa en personlig tillväxtkurva!', title_vi = 'Bắt đầu các buổi khám định kỳ. 💉', body_vi = 'Nhập chiều cao và cân nặng của bé vào Theo dõi phát triển để tạo biểu đồ tăng trưởng riêng!', title_zh = '常规检查开始了。💉', body_zh = '把宝宝的身高和体重录入成长记录，生成专属的成长曲线吧！' WHERE id = '2e317973-be56-4e35-b4da-81c9dc7b1f3d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Tus estadísticas del día están listas! 📊', body_es = 'Analiza los gráficos de la app para ver cuánto ha dormido y comido hoy.', title_fr = 'Vos statistiques du jour sont prêtes ! 📊', body_fr = 'Analysez vos graphiques dans l''application pour voir combien il a dormi et mangé aujourd''hui.', title_hi = 'आपके आज के आँकड़े तैयार हैं! 📊', body_hi = 'आज उसने कितना सोया और कितना खाया, यह देखने के लिए ऐप में अपने चार्ट का विश्लेषण कीजिए।', title_id = 'Statistik harian Anda sudah siap! 📊', body_id = 'Analisis grafik di aplikasi untuk melihat berapa lama ia tidur dan menyusu hari ini.', title_ja = '今日のデータができました！📊', body_ja = 'アプリのグラフで、今日赤ちゃんがどれくらい眠って、どれくらい飲んだか分析しましょう。', title_ko = '오늘의 통계가 준비됐어요! 📊', body_ko = '앱의 그래프를 분석해 오늘 아기가 얼마나 자고 먹었는지 확인하세요.', title_nl = 'Je dagstatistieken zijn klaar! 📊', body_nl = 'Bekijk de grafieken in de app om te zien hoeveel je baby vandaag heeft geslapen en gedronken.', title_pl = 'Twoje dzienne statystyki są gotowe! 📊', body_pl = 'Przeanalizuj wykresy w aplikacji, by zobaczyć, ile dziecko dziś spało i jadło.', title_pt = 'As suas estatísticas diárias estão prontas! 📊', body_pt = 'Analise os gráficos da app para ver quanto tempo dormiu e mamou hoje.', title_sv = 'Din dagliga statistik är klar! 📊', body_sv = 'Analysera diagrammen i appen för att se hur mycket barnet har sovit och ätit i dag.', title_vi = 'Thống kê hôm nay đã sẵn sàng! 📊', body_vi = 'Phân tích biểu đồ trong ứng dụng để xem hôm nay bé đã ngủ và bú bao nhiêu.', title_zh = '你的每日统计已生成！📊', body_zh = '分析应用里的图表，看看宝宝今天睡了多久、吃了多少。' WHERE id = '431cbe5a-0f52-442d-a6e8-ab53cd482a5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Seguimos su talla y su peso! 📏', body_es = 'Actualiza los últimos datos en la sección Seguimiento del desarrollo y siéntete orgullosa al ver su curva de crecimiento sana.', title_fr = 'Nous suivons sa taille et son poids ! 📏', body_fr = 'Mettez à jour les dernières mesures dans la rubrique Suivi de croissance, et soyez fière de sa belle courbe.', title_hi = 'हम लंबाई और वज़न की बढ़त पर नज़र रख रहे हैं! 📏', body_hi = 'ग्रोथ ट्रैकर सेक्शन में ताज़ा आँकड़े अपडेट कीजिए, सेहतमंद ग्रोथ चार्ट देखकर गर्व कीजिए।', title_id = 'Kita pantau pertambahan tinggi dan beratnya! 📏', body_id = 'Perbarui angka terbaru di bagian Pelacak Pertumbuhan, lalu banggalah melihat grafik pertumbuhannya yang sehat.', title_ja = '身長と体重の伸びを見守っています！📏', body_ja = '「成長トラッカー」で最新のデータを更新して、健やかな成長グラフを見て誇らしく思いましょう。', title_ko = '키와 몸무게 성장을 기록해요! 📏', body_ko = '성장 기록 섹션에서 최근 수치를 업데이트하고 건강한 성장 그래프를 보며 뿌듯해하세요.', title_nl = 'We volgen lengte en gewicht! 📏', body_nl = 'Werk de nieuwste metingen bij in het onderdeel Groeitracker en wees trots op de gezonde groeicurve.', title_pl = 'Śledzimy wzrost i wagę! 📏', body_pl = 'Zaktualizuj najnowsze wyniki w sekcji Śledzenie rozwoju i z dumą spójrz na wykres zdrowego rozwoju.', title_pt = 'Acompanhamos o crescimento em altura e peso! 📏', body_pt = 'Atualize os últimos valores na secção Registo de Crescimento e orgulhe-se ao ver a curva de crescimento saudável.', title_sv = 'Vi följer längd- och viktökningen! 📏', body_sv = 'Uppdatera de senaste måtten i Tillväxtspåraren och känn dig stolt när du ser den sunda tillväxtkurvan.', title_vi = 'Theo dõi chiều cao và cân nặng! 📏', body_vi = 'Cập nhật chỉ số mới nhất trong mục Theo dõi phát triển, nhìn biểu đồ phát triển khỏe mạnh và tự hào nhé.', title_zh = '记录身高和体重增长！📏', body_zh = '在成长记录板块更新最新数据，看着健康的成长曲线，为自己骄傲吧。' WHERE id = 'c4adf9ce-d711-4011-af60-94f404f59ae5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Feliz primer día! 🥳', body_es = 'Empieza a usar el temporizador de la app Anacan para seguir el sueño y las tomas de tu bebé.', title_fr = 'Joyeux premier jour ! 🥳', body_fr = 'Commencez à utiliser le minuteur de l''application Anacan pour suivre le sommeil et les repas de votre bébé.', title_hi = 'पहला दिन मुबारक! 🥳', body_hi = 'बच्चे की नींद और फ़ीडिंग के शेड्यूल पर नज़र रखने के लिए Anacan ऐप के टाइमर का इस्तेमाल शुरू कीजिए।', title_id = 'Selamat atas hari pertama Anda! 🥳', body_id = 'Mulailah menggunakan pengatur waktu di aplikasi Anacan untuk memantau jadwal tidur dan menyusu bayi Anda.', title_ja = '最初の日、おめでとうございます！🥳', body_ja = 'Anacanアプリのタイマーを使って、赤ちゃんの睡眠と授乳のリズムを記録しはじめましょう。', title_ko = '첫날을 축하해요! 🥳', body_ko = 'Anacan 앱의 타이머로 아기의 수면과 수유 패턴을 기록해 보세요.', title_nl = 'Gefeliciteerd met je eerste dag! 🥳', body_nl = 'Gebruik de timer in de Anacan-app om het slaap- en voedingsritme van je baby bij te houden.', title_pl = 'Wszystkiego najlepszego w pierwszym dniu! 🥳', body_pl = 'Zacznij korzystać z timera w aplikacji Anacan, by śledzić sen i karmienie dziecka.', title_pt = 'Feliz primeiro dia! 🥳', body_pt = 'Comece a usar o temporizador da app Anacan para acompanhar o sono e as mamadas do bebé.', title_sv = 'Grattis på din första dag! 🥳', body_sv = 'Börja använda timern i Anacan-appen för att hålla koll på barnets sömn och matning.', title_vi = 'Chúc mừng ngày đầu tiên! 🥳', body_vi = 'Hãy bắt đầu dùng bộ hẹn giờ trong ứng dụng Anacan để theo dõi giấc ngủ và cữ bú của bé.', title_zh = '第一天快乐！🥳', body_zh = '开始使用Anacan应用里的计时器，记录宝宝的睡眠和喂养规律吧。' WHERE id = '1af46170-3a5b-41ea-bb18-ce899698f996' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Fuente de energía para mamás! 🥗', body_es = 'Para recuperarte, elige un plato rico en vitaminas y delicioso de las Recetas saludables para mujeres de la app.', title_fr = 'Une source d''énergie pour les mamans ! 🥗', body_fr = 'Pour récupérer, choisissez un plat savoureux et riche en vitamines dans les Recettes saines pour femmes de l''application.', title_hi = 'माँओं के लिए ऊर्जा का स्रोत! 🥗', body_hi = 'रिकवरी के लिए ऐप के महिलाओं के लिए सेहतमंद रेसिपी सेक्शन से विटामिन भरी स्वादिष्ट डिश चुनिए।', title_id = 'Sumber energi untuk ibu! 🥗', body_id = 'Untuk pemulihan, pilih hidangan lezat kaya vitamin dari Resep Sehat untuk wanita di aplikasi.', title_ja = 'ママのためのエネルギー源！🥗', body_ja = '回復のために、アプリの「女性のためのヘルシーレシピ」からビタミンたっぷりのおいしい1品を選びましょう。', title_ko = '엄마를 위한 에너지원! 🥗', body_ko = '회복을 위해 앱의 여성을 위한 건강한 레시피에서 비타민 가득하고 맛있는 한 끼를 골라 보세요.', title_nl = 'Een bron van energie voor mama’s! 🥗', body_nl = 'Kies voor je herstel een vitaminerijk en lekker gerecht uit Gezonde recepten voor vrouwen in de app.', title_pl = 'Źródło energii dla mam! 🥗', body_pl = 'Aby wrócić do sił, wybierz smaczne, bogate w witaminy danie ze Zdrowych przepisów dla kobiet w aplikacji.', title_pt = 'Uma fonte de energia para as mães! 🥗', body_pt = 'Para recuperar, escolha nas Receitas Saudáveis para Mulheres da app um prato saboroso e rico em vitaminas.', title_sv = 'En energikälla för mammor! 🥗', body_sv = 'För att återhämta dig, välj en vitaminrik och god rätt bland Hälsosamma recept för kvinnor i appen.', title_vi = 'Nguồn năng lượng cho mẹ! 🥗', body_vi = 'Để hồi phục, hãy chọn một món ngon giàu vitamin từ Công thức lành mạnh cho phụ nữ trong ứng dụng.', title_zh = '妈妈的能量来源！🥗', body_zh = '为了恢复体力，从应用里的女性健康食谱中选一份富含维生素的美味吧。' WHERE id = 'ffb18a7a-0d53-482c-b130-00223f89efd3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Reacciona más a los sonidos! 🎶', body_es = '¿Ves cómo se calma al oír tu voz? Inmortaliza estos momentos tan tiernos en el Álbum del bebé.', title_fr = 'Il réagit de plus en plus aux sons ! 🎶', body_fr = 'Vous voyez comme il se calme en entendant votre voix ? Immortalisez ces doux moments dans l''Album de bébé.', title_hi = 'आवाज़ों पर उसकी प्रतिक्रिया बढ़ रही है! 🎶', body_hi = 'देखती हैं, आपकी आवाज़ सुनकर वह कैसे शांत हो जाता है? इन प्यारे पलों को बेबी एल्बम में हमेशा के लिए सहेजिए।', title_id = 'Reaksinya terhadap suara meningkat! 🎶', body_id = 'Lihat betapa tenangnya ia saat mendengar suara Anda? Abadikan momen manis ini di Album Bayi.', title_ja = '音への反応が増えています！🎶', body_ja = 'ママの声を聞くと赤ちゃんが落ち着くのがわかりますか？このかわいい瞬間を「ベビーアルバム」に残しましょう。', title_ko = '소리에 대한 반응이 늘고 있어요! 🎶', body_ko = '엄마 목소리를 들으면 아기가 얼마나 차분해지는지 보이나요? 이 사랑스러운 순간을 아기 앨범에 남겨 보세요.', title_nl = 'Je baby reageert meer op geluiden! 🎶', body_nl = 'Zie je hoe je baby rustig wordt als hij je stem hoort? Leg deze lieve momenten vast in het Babyalbum.', title_pl = 'Coraz mocniej reaguje na dźwięki! 🎶', body_pl = 'Widzisz, jak się uspokaja, gdy słyszy twój głos? Uwiecznij te słodkie chwile w Albumie dziecka.', title_pt = 'Reage cada vez mais aos sons! 🎶', body_pt = 'Vê como se acalma quando ouve a sua voz? Eternize estes momentos ternurentos no Álbum do Bebé.', title_sv = 'Barnet reagerar mer på ljud! 🎶', body_sv = 'Ser du hur barnet lugnar sig när det hör din röst? Förevig de här söta stunderna i Babyalbumet.', title_vi = 'Bé phản ứng với âm thanh nhiều hơn! 🎶', body_vi = 'Mẹ có thấy bé dịu lại thế nào khi nghe giọng mẹ không? Hãy lưu giữ những khoảnh khắc ngọt ngào này trong Album của bé.', title_zh = '对声音的反应越来越多！🎶', body_zh = '看到宝宝一听到你的声音就安静下来了吗？把这些甜蜜时刻永远留在宝宝相册里吧。' WHERE id = '40712cc0-bb4b-4d42-9a36-7942cb47a970' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Necesitas ir de compras? 🛍', body_es = '️Echa un vistazo a nuestra lista de Productos recomendados para encontrar productos de cuidado o juguetes adecuados para su nuevo mes.', title_fr = 'Besoin de faire des achats ? 🛍', body_fr = '️Découvrez notre liste de Produits recommandés pour trouver des produits de soin ou des jouets adaptés à ce nouveau mois.', title_hi = 'शॉपिंग की ज़रूरत है? 🛍', body_hi = '️बच्चे के नए महीने के लिए सही देखभाल की चीज़ों या खिलौनों के लिए हमारी सुझाए गए प्रोडक्ट की लिस्ट देखिए।', title_id = 'Perlu belanja? 🛍', body_id = '️Lihat daftar Produk Rekomendasi kami untuk perlengkapan perawatan atau mainan yang sesuai dengan bulan baru bayi Anda.', title_ja = 'お買い物が必要ですか？🛍', body_ja = '️赤ちゃんの新しい月に合ったケア用品やおもちゃを、「おすすめ商品」リストでチェックしましょう。', title_ko = '쇼핑이 필요하세요? 🛍', body_ko = '️새로운 달에 맞는 아기 돌봄 용품이나 장난감은 추천 제품 목록에서 확인해 보세요.', title_nl = 'Boodschappen nodig? 🛍', body_nl = '️Bekijk onze lijst Aanbevolen producten voor verzorgingsproducten of speelgoed die bij de nieuwe maand van je baby passen.', title_pl = 'Potrzebne zakupy? 🛍', body_pl = '️Zajrzyj do listy Polecane produkty po kosmetyki lub zabawki odpowiednie na nowy miesiąc dziecka.', title_pt = 'Precisa de fazer compras? 🛍', body_pt = '️Veja a nossa lista de Produtos Recomendados para encontrar produtos de higiene ou brinquedos adequados ao novo mês do bebé.', title_sv = 'Behöver du handla? 🛍', body_sv = '️Kika på listan Rekommenderade produkter efter skötselprodukter eller leksaker som passar barnets nya månad.', title_vi = 'Cần đi mua sắm? 🛍', body_vi = '️Hãy xem danh sách Sản phẩm gợi ý để tìm đồ chăm sóc hoặc đồ chơi phù hợp với tháng mới của bé.', title_zh = '需要购物吗？🛍', body_zh = '️想给宝宝买适合新月龄的护理用品或玩具，就看看我们的推荐商品列表吧。' WHERE id = 'aa025645-c5cd-4f2b-840e-6fb50bb6398b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Sigue contando pañales! 🧷', body_es = 'Anota en Anacan los pañales del día para asegurarte de que tu bebé come lo suficiente.', title_fr = 'Continuez à compter les couches ! 🧷', body_fr = 'Notez chaque jour les couches dans Anacan pour vous assurer que votre bébé mange à sa faim.', title_hi = 'डायपर गिनते रहिए! 🧷', body_hi = 'रोज़ के डायपर Anacan में दर्ज करके पक्का कीजिए कि बच्चे का पेट ठीक से भर रहा है।', title_id = 'Terus hitung popoknya! 🧷', body_id = 'Catat popok harian di Anacan untuk memastikan bayi Anda cukup menyusu.', title_ja = 'おむつの記録を続けましょう！🧷', body_ja = '1日のおむつの回数をAnacanに記録して、赤ちゃんが十分に飲めているか確認しましょう。', title_ko = '기저귀 세기는 계속돼요! 🧷', body_ko = '하루 기저귀 기록을 Anacan에 남기고 아기가 충분히 먹는지 확인하세요.', title_nl = 'Blijf luiers tellen! 🧷', body_nl = 'Noteer de luiers per dag in Anacan, zodat je zeker weet dat je baby genoeg binnenkrijgt.', title_pl = 'Dalej liczymy pieluszki! 🧷', body_pl = 'Zapisuj codzienne pieluszki w Anacan i miej pewność, że dziecko się najada.', title_pt = 'Continue a contar as fraldas! 🧷', body_pt = 'Registe as fraldas do dia no Anacan para ter a certeza de que o bebé está bem alimentado.', title_sv = 'Fortsätt räkna blöjorna! 🧷', body_sv = 'Anteckna de dagliga blöjorna i Anacan och känn dig trygg med att barnet får tillräckligt med mat.', title_vi = 'Tiếp tục đếm tã nhé! 🧷', body_vi = 'Ghi lại số tã hằng ngày trong Anacan để chắc chắn bé bú đủ.', title_zh = '继续数尿布！🧷', body_zh = '在Anacan里记录每天的尿布情况，确认宝宝吃得够。' WHERE id = 'c6ae0bdf-11e6-43d9-a0ab-d021b7461194' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Salto de desarrollo de la 6.ª semana! 📈', body_es = 'Hoy puede estar algo más exigente. No te agobies, consulta con Anacan AI para recibir apoyo.', title_fr = 'Le pic de développement de la 6e semaine ! 📈', body_fr = 'Il peut être un peu exigeant aujourd''hui. Pas d''inquiétude, demandez conseil à Anacan AI.', title_hi = 'छठे हफ़्ते का ग्रोथ स्पर्ट! 📈', body_hi = 'आज वह थोड़ा ज़िद्दी हो सकता है। घबराइए मत, सहारे के लिए Anacan AI से सलाह लीजिए।', title_id = 'Lompatan perkembangan minggu ke-6! 📈', body_id = 'Hari ini ia mungkin sedikit rewel. Jangan cemas, konsultasikan dengan Anacan AI untuk mendapat dukungan.', title_ja = '6週目の発達のジャンプ期！📈', body_ja = '今日は少し手がかかるかもしれません。あわてずに、Anacan AIに相談してサポートを受けましょう。', title_ko = '6주 차 성장 급등기! 📈', body_ko = '오늘은 아기가 조금 보챌 수 있어요. 걱정하지 말고 Anacan AI에게 도움을 받아 보세요.', title_nl = 'De ontwikkelingssprong van week 6! 📈', body_nl = 'Je baby kan vandaag wat veeleisend zijn. Geen paniek, vraag Anacan AI om steun.', title_pl = 'Skok rozwojowy 6. tygodnia! 📈', body_pl = 'Dziś dziecko może być trochę bardziej wymagające. Bez nerwów, po wsparcie zwróć się do Anacan AI.', title_pt = 'Salto de desenvolvimento das 6 semanas! 📈', body_pt = 'Hoje o bebé pode estar um pouco mais exigente. Não se aflija, peça apoio ao Anacan AI.', title_sv = 'Utvecklingssprånget i vecka 6! 📈', body_sv = 'I dag kan barnet vara lite krävande. Oroa dig inte, rådfråga Anacan AI för stöd.', title_vi = 'Bước nhảy vọt tuần thứ 6! 📈', body_vi = 'Hôm nay bé có thể hơi khó chiều. Đừng lo, hãy hỏi Anacan AI để được hỗ trợ.', title_zh = '第6周猛长期！📈', body_zh = '宝宝今天可能有点黏人。别着急，向Anacan AI寻求支持吧。' WHERE id = '99125d76-b832-4f75-8c29-6320b71e5e67' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ponemos rutina a los despertares nocturnos. 😴', body_es = 'No enciendas las luces cada vez que se despierte. Dale de comer con el temporizador de Anacan y vuelve a dormirle con el Ruido blanco.', title_fr = 'Instaurons une routine pour les réveils nocturnes. 😴', body_fr = 'N''allumez pas la lumière à chaque réveil. Nourrissez-le avec le minuteur Anacan, puis rendormez-le avec les Bruits blancs.', title_hi = 'रात में जागने को रूटीन में ला रहे हैं। 😴', body_hi = 'हर बार जागने पर लाइट मत जलाइए। Anacan टाइमर के साथ दूध पिलाइए और व्हाइट नॉइज़ से फिर सुलाइए।', title_id = 'Kita buat rutinitas untuk bangun malam. 😴', body_id = 'Jangan menyalakan lampu setiap kali ia bangun. Susui dengan pengatur waktu Anacan, lalu tidurkan kembali dengan Suara Putih.', title_ja = '夜中の目覚めにもリズムを。😴', body_ja = '起きるたびに明かりをつけないようにしましょう。Anacanのタイマーで授乳を記録し、ホワイトノイズで再び寝かしつけましょう。', title_ko = '밤중에 깨는 것도 루틴으로 만들어요. 😴', body_ko = '아기가 깰 때마다 불을 켜지 마세요. Anacan 타이머로 수유하고 백색소음으로 다시 재워 주세요.', title_nl = 'We brengen ritme in het nachtelijk wakker worden. 😴', body_nl = 'Doe niet elke keer het licht aan als je baby wakker wordt. Geef de voeding met de Anacan-timer en breng je baby weer in slaap met Witte ruis.', title_pl = 'Wprowadzamy rutynę w nocne pobudki. 😴', body_pl = 'Przy każdej pobudce nie zapalaj świateł. Nakarm z timerem Anacan i uśpij ponownie przy Białym szumie.', title_pt = 'Vamos criar uma rotina para os despertares noturnos. 😴', body_pt = 'Não acenda as luzes sempre que acorda. Alimente-o com o temporizador do Anacan e volte a adormecê-lo com o Ruído Branco.', title_sv = 'Vi skapar rutin kring nattliga uppvaknanden. 😴', body_sv = 'Tänd inte lamporna varje gång barnet vaknar. Mata med Anacan-timern och söv om med Vitt brus.', title_vi = 'Đưa những lần thức đêm vào nếp. 😴', body_vi = 'Đừng bật đèn mỗi lần bé thức. Cho bé bú với bộ hẹn giờ Anacan, rồi ru bé ngủ lại bằng Tiếng ồn trắng.', title_zh = '让夜醒也有规律。😴', body_zh = '宝宝每次醒来时不要开灯。用Anacan计时器喂完奶，再用白噪音哄宝宝重新入睡。' WHERE id = '9f56ae7d-2431-4cb2-8d79-fa19be16c242' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mientras duerme, descansa tú también. ⏱️', body_es = 'Pon el temporizador de sueño y, mientras tu bebé duerme, cierra tú también los ojos o lee un libro.', title_fr = 'Reposez-vous pendant qu''il dort. ⏱️', body_fr = 'Lancez le minuteur de sommeil et, pendant qu''il dort, fermez les yeux ou lisez un livre.', title_hi = 'वह सोए, तो आप भी आराम कीजिए। ⏱️', body_hi = 'स्लीप टाइमर चालू कीजिए, और जब तक बच्चा सोए, आप भी आँखें बंद कीजिए या किताब पढ़िए।', title_id = 'Saat ia tidur, Anda juga istirahat. ⏱️', body_id = 'Nyalakan pengatur waktu tidur, dan selama bayi Anda tidur, pejamkan mata atau bacalah buku.', title_ja = '赤ちゃんが眠ったら、ママも休んで。⏱️', body_ja = '睡眠タイマーをオンにして、赤ちゃんが眠っている間、ママも目を閉じたり本を読んだりしましょう。', title_ko = '아기가 잘 때 엄마도 쉬세요. ⏱️', body_ko = '수면 타이머를 켜고, 아기가 자는 동안 엄마도 눈을 붙이거나 책을 읽어 보세요.', title_nl = 'Rust jij ook als je baby slaapt. ⏱️', body_nl = 'Zet de slaaptimer aan en doe je ogen dicht of lees een boek zolang je baby slaapt.', title_pl = 'Gdy dziecko śpi, ty też odpocznij. ⏱️', body_pl = 'Włącz timer snu, a gdy maleństwo śpi, ty też zamknij oczy lub poczytaj książkę.', title_pt = 'Enquanto ele dorme, descanse também. ⏱️', body_pt = 'Ligue o temporizador de sono e, enquanto o bebé dorme, feche os olhos ou leia um livro.', title_sv = 'Vila du också när barnet sover. ⏱️', body_sv = 'Starta sömntimern och blunda du också eller läs en bok medan barnet sover.', title_vi = 'Khi bé ngủ, mẹ cũng nghỉ ngơi. ⏱️', body_vi = 'Bật bộ hẹn giờ ngủ, trong lúc bé ngủ, mẹ cũng nhắm mắt hoặc đọc sách nhé.', title_zh = '宝宝睡觉时，你也休息一下。⏱️', body_zh = '打开睡眠计时器，宝宝睡觉的时候，你也闭上眼睛歇歇或看看书。' WHERE id = 'bef1515a-3c39-4799-b9d9-717742d94d5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Siguen los primeros gorjeos! 🗣️', body_es = 'Graba sus intentos de hablar contigo. Elige un marco a juego para este momento en la sección Sesión de fotos del bebé.', title_fr = 'D''autres « areuh » arrivent ! 🗣️', body_fr = 'Filmez ses tentatives de vous parler. Choisissez un cadre adapté à ce moment dans la rubrique Séance photo bébé.', title_hi = 'पहली ''आ-गू'' के बाद और आवाज़ें आ रही हैं! 🗣️', body_hi = 'आपसे बात करने की उसकी कोशिश रिकॉर्ड कीजिए। बेबी फ़ोटोशूट सेक्शन में इस पल के लिए सही फ़्रेम चुनिए।', title_id = 'Ocehan pertamanya terus berlanjut! 🗣️', body_id = 'Rekam usahanya untuk berbicara dengan Anda. Pilih bingkai yang cocok untuk momen ini di bagian Pemotretan Bayi.', title_ja = '「アーウー」がどんどん続きます！🗣️', body_ja = '赤ちゃんがママに話しかけようとする様子を記録しましょう。「ベビーフォトセッション」で、この瞬間にぴったりのフレームを選んで。', title_ko = '첫 옹알이가 계속 이어져요! 🗣️', body_ko = '아기가 엄마에게 말을 걸려는 순간을 기록하세요. 아기 사진 촬영 섹션에서 이 순간에 어울리는 프레임을 골라 보세요.', title_nl = 'Er komen meer brabbelgeluidjes! 🗣️', body_nl = 'Leg vast hoe je baby met je probeert te praten. Kies een passend kader in het onderdeel Babyfotoshoot.', title_pl = 'Po pierwszym gaworzeniu przychodzi więcej! 🗣️', body_pl = 'Nagraj jego próby rozmowy z tobą. W sekcji Sesja zdjęciowa dziecka wybierz ramkę pasującą do tej chwili.', title_pt = 'Aos primeiros "agu" seguem-se mais! 🗣️', body_pt = 'Registe as tentativas que ele faz de falar consigo. Escolha uma moldura adequada para este momento na Sessão Fotográfica do Bebé.', title_sv = 'Fler jollrande ljud är på väg! 🗣️', body_sv = 'Spela in när barnet försöker prata med dig. Välj en ram som passar ögonblicket i avsnittet Babyfotografering.', title_vi = 'Tiếp nối những tiếng "a-ưm" đầu tiên! 🗣️', body_vi = 'Hãy ghi lại những lúc bé cố trò chuyện với mẹ. Chọn khung ảnh hợp với khoảnh khắc này trong mục Chụp ảnh cho bé.', title_zh = '“啊咕”声越来越多啦！🗣️', body_zh = '把宝宝想和你说话的样子记录下来。在宝宝写真板块为这一刻选一个合适的相框吧。' WHERE id = '3deddca7-0eae-4a46-a2c9-5a8e2ac8b32c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El calostro es la primera vacuna! 🤱', body_es = 'Registra fácilmente las tomas con la herramienta de Seguimiento de tomas de la app.', title_fr = 'Le colostrum est le premier vaccin ! 🤱', body_fr = 'Notez facilement les tétées avec l''outil Suivi des repas de l''application.', title_hi = 'कोलोस्ट्रम पहला टीका है! 🤱', body_hi = 'ऐप के फ़ीडिंग ट्रैकर से अपना रोज़ का पोषण आसानी से दर्ज कीजिए।', title_id = 'Kolostrum adalah vaksin pertama! 🤱', body_id = 'Catat asupan menyusu dengan mudah menggunakan alat Pemantau Menyusu di aplikasi.', title_ja = '初乳は最初の予防接種！🤱', body_ja = 'アプリの授乳記録ツールで、授乳の量をかんたんに記録できます。', title_ko = '초유는 첫 백신이에요! 🤱', body_ko = '앱의 수유 기록 도구로 수유량을 쉽게 기록하세요.', title_nl = 'Colostrum is de eerste vaccinatie! 🤱', body_nl = 'Houd de voedingen eenvoudig bij met de Voedingstracker in de app.', title_pl = 'Siara to pierwsza szczepionka! 🤱', body_pl = 'Łatwo zapisuj karmienia za pomocą narzędzia do śledzenia karmienia w aplikacji.', title_pt = 'O colostro é a primeira vacina! 🤱', body_pt = 'Registe facilmente a alimentação com o Registo de Alimentação da app.', title_sv = 'Råmjölken är det första vaccinet! 🤱', body_sv = 'Anteckna enkelt matningen med verktyget Matningskoll i appen.', title_vi = 'Sữa non là liều vắc-xin đầu tiên! 🤱', body_vi = 'Ghi lại lượng ăn của bé dễ dàng bằng công cụ Theo dõi cữ bú trong ứng dụng.', title_zh = '初乳是第一份疫苗！🤱', body_zh = '用应用里的喂养记录工具，轻松记下喂养量。' WHERE id = 'c21d305d-a798-46f7-a57b-5ee7fc159b60' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gestiona tus emociones. 💖', body_es = 'La maternidad puede ser agotadora. Entra en el Diario de ánimo, escribe qué te preocupa hoy y quítate peso de encima.', title_fr = 'Gérez vos émotions. 💖', body_fr = 'Être maman peut être épuisant. Ouvrez le Journal d''humeur, écrivez ce qui vous inquiète aujourd''hui, et sentez-vous plus légère.', title_hi = 'अपनी भावनाओं को संभालिए। 💖', body_hi = 'मातृत्व थकाने वाला हो सकता है। मूड डायरी खोलिए, लिखिए कि आज आपको किस बात ने परेशान किया, और मन हल्का कीजिए।', title_id = 'Kelola emosi Anda. 💖', body_id = 'Menjadi ibu bisa melelahkan. Buka Buku Harian Suasana Hati, tulis apa yang mengganggu Anda hari ini, dan rasakan lebih ringan.', title_ja = '気持ちをうまく整えましょう。💖', body_ja = '育児は疲れるものです。「気分日記」を開いて、今日気になっていることを書いて、心を軽くしましょう。', title_ko = '감정을 돌봐 주세요. 💖', body_ko = '엄마가 되는 건 힘들 수 있어요. 기분 일기를 열고 오늘 마음을 무겁게 한 일을 적으며 가벼워지세요.', title_nl = 'Ga goed om met je emoties. 💖', body_nl = 'Moederschap kan vermoeiend zijn. Open je Stemmingsdagboek, schrijf op wat je vandaag dwarszit en lucht je hart.', title_pl = 'Zadbaj o swoje emocje. 💖', body_pl = 'Macierzyństwo bywa męczące. Otwórz Dziennik nastroju, zapisz, co cię dziś niepokoi, i poczuj ulgę.', title_pt = 'Cuide das suas emoções. 💖', body_pt = 'A maternidade pode ser cansativa. Abra o Diário de Humor, escreva o que a preocupou hoje e sinta-se mais leve.', title_sv = 'Hantera dina känslor. 💖', body_sv = 'Moderskapet kan vara tröttsamt. Öppna Humördagboken och skriv ner vad som oroar dig i dag, så känns det lättare.', title_vi = 'Kiểm soát cảm xúc của mẹ. 💖', body_vi = 'Làm mẹ có thể rất mệt. Hãy vào Nhật ký tâm trạng, viết ra điều khiến mẹ lo lắng hôm nay để nhẹ lòng hơn.', title_zh = '照顾好自己的情绪。💖', body_zh = '做妈妈可能很累。打开心情日记，写下今天让你烦心的事，让自己轻松一些。' WHERE id = 'bcfe1987-8bea-4b53-a1dc-7ef7e234e755' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ajustamos los intervalos. 🍼', body_es = 'Sigue las tomas y los descansos con la herramienta de Seguimiento de tomas y crea la rutina perfecta para tu bebé.', title_fr = 'Nous ajustons les intervalles. 🍼', body_fr = 'Suivez les heures de repas et les intervalles avec l''outil Suivi des repas pour créer le rythme idéal de votre bébé.', title_hi = 'ब्रेक को सही करते हैं। 🍼', body_hi = 'फ़ीडिंग ट्रैकर से फ़ीडिंग और ब्रेक का समय देखकर बच्चे का परफ़ेक्ट रूटीन बनाइए।', title_id = 'Kita atur jedanya. 🍼', body_id = 'Bangun rutinitas sempurna bayi Anda dengan memantau waktu menyusu dan jeda lewat alat Pemantau Menyusu.', title_ja = '授乳の間隔を整えましょう。🍼', body_ja = '授乳記録ツールで授乳と間隔の時間を記録して、赤ちゃんにぴったりのリズムをつくりましょう。', title_ko = '수유 간격을 맞춰요. 🍼', body_ko = '수유 기록 도구로 수유와 휴식 시간을 기록하며 아기에게 꼭 맞는 패턴을 만들어 보세요.', title_nl = 'We regelen de pauzes. 🍼', body_nl = 'Volg de voedingen en pauzes met de Voedingstracker en bouw zo het perfecte ritme voor je baby op.', title_pl = 'Ustalamy przerwy. 🍼', body_pl = 'Śledź czas karmień i przerw w narzędziu do śledzenia karmienia i zbuduj idealny rytm dnia dziecka.', title_pt = 'Vamos organizar os intervalos. 🍼', body_pt = 'Acompanhe as mamadas e os intervalos com o Registo de Alimentação e crie a rotina perfeita para o bebé.', title_sv = 'Vi justerar pauserna. 🍼', body_sv = 'Bygg upp barnets perfekta rutin genom att följa matnings- och paustiderna med verktyget Matningskoll.', title_vi = 'Điều chỉnh khoảng nghỉ. 🍼', body_vi = 'Theo dõi giờ bú và khoảng nghỉ bằng công cụ Theo dõi cữ bú để xây dựng lịch sinh hoạt hoàn hảo cho bé.', title_zh = '调整喂养间隔。🍼', body_zh = '用喂养记录工具追踪喂奶和间隔时间，为宝宝建立完美的作息。' WHERE id = '4c289cf6-60de-4ba6-9f14-eae4086d8d21' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La capa blanca en la piel del bebé le protege. 👶 No te preocupes.', body_es = '¡Al cambiar el pañal, no olvides anotarlo en Anacan y revisar lo normal!', title_fr = 'La couche blanche sur la peau de bébé le protège. 👶 Pas d''inquiétude.', body_fr = 'Quand vous changez la couche, pensez à le noter dans Anacan et à vérifier les normes !', title_hi = 'बच्चे की त्वचा पर सफ़ेद परत उसकी रक्षा करती है। 👶 चिंता मत कीजिए।', body_hi = 'डायपर बदलते समय Anacan में दर्ज करना और मानक जाँचना न भूलें!', title_id = 'Lapisan putih di kulit bayi melindunginya. 👶 Jangan khawatir.', body_id = 'Saat mengganti popok, jangan lupa mencatatnya di Anacan dan memeriksa angka normalnya!', title_ja = '赤ちゃんの肌の白い膜は、赤ちゃんを守っています。👶 心配いりません。', body_ja = 'おむつを替えたら、Anacanに記録して目安をチェックするのを忘れずに！', title_ko = '아기 피부의 하얀 막은 아기를 보호해 줘요. 👶 걱정하지 마세요.', body_ko = '기저귀를 갈 때 Anacan에 기록하고 기준치를 확인하는 것 잊지 마세요!', title_nl = 'Het witte laagje op de huid van je baby beschermt. 👶 Maak je geen zorgen.', body_nl = 'Vergeet niet om bij het verschonen een notitie te maken in Anacan en de normen te bekijken!', title_pl = 'Biała warstwa na skórze dziecka je chroni. 👶 Nie martw się.', body_pl = 'Przy zmianie pieluszki zapisz to w Anacan i sprawdź normy!', title_pt = 'A camada branca na pele do bebé protege-o. 👶 Não se preocupe.', body_pt = 'Ao mudar a fralda, não se esqueça de registar no Anacan e verificar os valores normais!', title_sv = 'Det vita lagret på barnets hud skyddar det. 👶 Oroa dig inte.', body_sv = 'När du byter blöja, glöm inte att anteckna det i Anacan och kolla normerna!', title_vi = 'Lớp màu trắng trên da bé đang bảo vệ bé. 👶 Mẹ đừng lo nhé.', body_vi = 'Khi thay tã, đừng quên ghi lại trong Anacan và kiểm tra các chỉ số chuẩn!', title_zh = '宝宝皮肤上那层白色物质在保护宝宝。👶 不用担心。', body_zh = '换尿布时，别忘了在Anacan里记录并查看参考标准！' WHERE id = 'ee814c6a-2fd2-46fc-a3a3-6fece315052e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Te queda alguna pregunta? 🤖', body_es = '«Mi bebé ha dormido poco hoy, ¿es normal?»: plantea a otras mamás de la Comunidad las preguntas que te preocupan.', title_fr = 'Il vous reste des questions ? 🤖', body_fr = '« Mon bébé a peu dormi aujourd''hui, est-ce normal ? » Posez les questions qui vous préoccupent aux autres mamans dans la Communauté.', title_hi = 'कोई सवाल बाकी है? 🤖', body_hi = '''मेरा बच्चा आज कम सोया, क्या यह सामान्य है?'' जो सवाल परेशान करें, कम्युनिटी में दूसरी माँओं से पूछिए।', title_id = 'Masih ada pertanyaan? 🤖', body_id = 'Bayiku hari ini kurang tidur, normalkah? Ajukan pertanyaan yang mengganggu pikiran Anda kepada ibu-ibu lain di Komunitas.', title_ja = 'まだ気になることはありますか？🤖', body_ja = '「今日はあまり寝なかったけど、大丈夫？」気になる質問は、コミュニティでほかのママたちに聞いてみましょう。', title_ko = '궁금한 게 남았나요? 🤖', body_ko = '''오늘 아기가 잠을 적게 잤는데 괜찮을까요?'' 궁금한 점은 커뮤니티에서 다른 엄마들에게 물어보세요.', title_nl = 'Heb je nog vragen? 🤖', body_nl = '‘Mijn baby heeft vandaag weinig geslapen, is dat normaal?’ Stel de vragen die je bezighouden aan andere mama’s in de Community.', title_pl = 'Zostały ci jakieś pytania? 🤖', body_pl = '„Moje dziecko dziś mało spało, czy to normalne?” Zadaj pytania, które cię nurtują, innym mamom w Społeczności.', title_pt = 'Ficou com alguma pergunta? 🤖', body_pt = '"O meu bebé dormiu pouco hoje, é normal?" Faça as perguntas que a preocupam às outras mães na Comunidade.', title_sv = 'Har du några frågor kvar? 🤖', body_sv = 'Mitt barn sov lite i dag, är det normalt? Ställ frågorna som oroar dig till andra mammor i Community.', title_vi = 'Mẹ còn câu hỏi nào không? 🤖', body_vi = '"Hôm nay bé ngủ ít, có bình thường không?" Hãy gửi những câu hỏi khiến mẹ băn khoăn đến các mẹ khác trong Cộng đồng.', title_zh = '还有什么问题吗？🤖', body_zh = '“宝宝今天睡得少，正常吗？”：把让你困惑的问题发到社区，问问其他妈妈吧。' WHERE id = '7f93cf2f-abf0-4b16-9f93-396050a7ddb9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Ejercicios de tummy time! 🐢', body_es = 'Ya mantiene la cabeza erguida durante más tiempo. Repite estos ejercicios cada día para desarrollar los músculos de su cuello.', title_fr = 'Exercices sur le ventre ! 🐢', body_fr = 'Il tient déjà sa tête droite plus longtemps. Répétez ces exercices chaque jour pour développer les muscles de son cou.', title_hi = 'टमी टाइम एक्सरसाइज़! 🐢', body_hi = 'वह अब ज़्यादा देर तक सिर सीधा रखता है। गर्दन की मांसपेशियों के विकास के लिए ये एक्सरसाइज़ रोज़ दोहराइए।', title_id = 'Latihan tummy time! 🐢', body_id = 'Ia kini menegakkan kepala lebih lama. Ulangi latihan ini setiap hari untuk perkembangan otot lehernya.', title_ja = 'タミータイムの練習！🐢', body_ja = '赤ちゃんはもう、より長く頭を起こしていられます。首の筋肉の発達のために、毎日この練習を続けましょう。', title_ko = '엎드려 있기 운동! 🐢', body_ko = '아기가 이제 고개를 더 오래 들고 있어요. 목 근육 발달을 위해 이 운동을 매일 반복해 주세요.', title_nl = 'Oefeningen voor tummy time! 🐢', body_nl = 'Je baby houdt het hoofdje al langer rechtop. Herhaal deze oefeningen elke dag voor sterke nekspieren.', title_pl = 'Ćwiczenia na brzuszku! 🐢', body_pl = 'Coraz dłużej trzyma główkę prosto. Powtarzaj te ćwiczenia codziennie dla rozwoju mięśni szyi.', title_pt = 'Exercícios de tummy time! 🐢', body_pt = 'O bebé já segura a cabeça direita durante mais tempo. Repita estes exercícios todos os dias para desenvolver os músculos do pescoço.', title_sv = 'Övningar i magläge! 🐢', body_sv = 'Barnet håller nu huvudet upprätt längre. Upprepa övningarna varje dag för att utveckla nackmusklerna.', title_vi = 'Bài tập Tummy time! 🐢', body_vi = 'Bé đã giữ đầu thẳng lâu hơn. Hãy lặp lại các bài tập này mỗi ngày để cơ cổ phát triển.', title_zh = '趴趴练习！🐢', body_zh = '宝宝已经能更久地抬着头了。为了颈部肌肉的发育，每天重复这些练习吧。' WHERE id = 'c505d849-65c8-4ead-80b3-2648f5feaa49' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dedica hoy al menos 15 minutos solo a ti. 🛁', body_es = 'Date una ducha tibia y prémiate con las recetas saludables de la app.', title_fr = 'Aujourd''hui, prenez au moins 15 minutes rien que pour vous. 🛁', body_fr = 'Prenez une douche tiède et récompensez-vous avec les recettes saines de l''application.', title_hi = 'आज कम से कम 15 मिनट सिर्फ़ अपने लिए निकालिए। 🛁', body_hi = 'गुनगुने पानी से नहाइए और ऐप की सेहतमंद रेसिपी से खुद को इनाम दीजिए।', title_id = 'Hari ini sisihkan setidaknya 15 menit khusus untuk diri sendiri. 🛁', body_id = 'Mandi air hangat dan hadiahi diri Anda dengan resep sehat di aplikasi.', title_ja = '今日は少なくとも15分、自分だけの時間をとりましょう。🛁', body_ja = '温かいシャワーを浴びて、アプリのヘルシーレシピで自分にごほうびを。', title_ko = '오늘은 적어도 15분만큼은 오롯이 나를 위해 쓰세요. 🛁', body_ko = '따뜻한 샤워를 하고 앱의 건강한 레시피로 나에게 상을 주세요.', title_nl = 'Neem vandaag minstens 15 minuten alleen voor jezelf. 🛁', body_nl = 'Neem een warme douche en beloon jezelf met de gezonde recepten in de app.', title_pl = 'Znajdź dziś choć 15 minut tylko dla siebie. 🛁', body_pl = 'Weź ciepły prysznic i nagródź się zdrowym przepisem z aplikacji.', title_pt = 'Hoje, reserve pelo menos 15 minutos só para si. 🛁', body_pt = 'Tome um duche morno e mime-se com as receitas saudáveis da app.', title_sv = 'Ta åtminstone 15 minuter i dag bara för dig själv. 🛁', body_sv = 'Ta en ljummen dusch och belöna dig med de hälsosamma recepten i appen.', title_vi = 'Hôm nay hãy dành ít nhất 15 phút chỉ cho riêng mẹ. 🛁', body_vi = 'Tắm nước ấm và tự thưởng cho mình bằng các công thức lành mạnh trong ứng dụng.', title_zh = '今天至少留出15分钟只属于你自己。🛁', body_zh = '洗个温水澡，再用应用里的健康食谱犒劳一下自己吧。' WHERE id = 'ffd7ff0c-bf80-4552-8a28-8d30f0674b07' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal va la rutina de tomas? 🤱', body_es = 'Pon en marcha el temporizador de la app y sigue fácilmente las tomas con la herramienta de Seguimiento de tomas.', title_fr = 'Comment se passe la routine des repas ? 🤱', body_fr = 'Lancez le minuteur de l''application et suivez facilement les repas avec l''outil Suivi des repas.', title_hi = 'फ़ीडिंग का रूटीन कैसा चल रहा है? 🤱', body_hi = 'ऐप में टाइमर चालू कीजिए और फ़ीडिंग ट्रैकर से फ़ीडिंग का मानक आसानी से देखिए।', title_id = 'Bagaimana rutinitas menyusu? 🤱', body_id = 'Nyalakan pengatur waktu di aplikasi dan pantau jumlah menyusu dengan mudah lewat alat Pemantau Menyusu.', title_ja = '授乳のリズムはどうですか？🤱', body_ja = 'アプリのタイマーをスタートして、授乳記録ツールで授乳の目安をかんたんにチェックしましょう。', title_ko = '수유 루틴은 잘 되고 있나요? 🤱', body_ko = '앱의 타이머를 켜고 수유 기록 도구로 수유량을 쉽게 확인하세요.', title_nl = 'Hoe gaat het voedingsritme? 🤱', body_nl = 'Start de timer in de app en volg de voedingen eenvoudig met de Voedingstracker.', title_pl = 'Jak idzie rytm karmienia? 🤱', body_pl = 'Włącz timer w aplikacji i łatwo śledź karmienia w narzędziu do śledzenia karmienia.', title_pt = 'Como está a correr a rotina das mamadas? 🤱', body_pt = 'Ligue o temporizador da app e acompanhe facilmente as mamadas com o Registo de Alimentação.', title_sv = 'Hur går matningsrutinen? 🤱', body_sv = 'Starta timern i appen och följ enkelt matningen med verktyget Matningskoll.', title_vi = 'Nếp cho bú đang thế nào? 🤱', body_vi = 'Bật bộ hẹn giờ trong ứng dụng và dễ dàng theo dõi định mức cữ bú bằng công cụ Theo dõi cữ bú.', title_zh = '喂养规律怎么样？🤱', body_zh = '打开应用里的计时器，用喂养记录工具轻松追踪喂养量。' WHERE id = '20684bd3-d3fb-479e-89f1-9adf84e485af' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Involucremos también a papá. 👨‍🍼', body_es = 'Después de la toma de la tarde, deja que papá se encargue de los gases y de dormirle, y dedícate tiempo a ti.', title_fr = 'Impliquons aussi les papas. 👨‍🍼', body_fr = 'Après la tétée du soir, confiez le rot et le coucher à Papa, et prenez du temps pour vous.', title_hi = 'पापा को भी शामिल करें। 👨‍🍼', body_hi = 'शाम की फ़ीडिंग के बाद डकार दिलाने और सुलाने की बारी पापा को दीजिए और अपने लिए समय निकालिए।', title_id = 'Kita libatkan para ayah. 👨‍🍼', body_id = 'Setelah menyusu malam, serahkan giliran menyendawakan dan menidurkan kepada Ayah, lalu luangkan waktu untuk diri sendiri.', title_ja = 'パパにも参加してもらいましょう。👨‍🍼', body_ja = '夜の授乳のあと、げっぷと寝かしつけはパパにまかせて、自分のための時間をとりましょう。', title_ko = '아빠도 함께해요. 👨‍🍼', body_ko = '저녁 수유 후 트림시키기와 재우기는 아빠에게 맡기고 나를 위한 시간을 가져 보세요.', title_nl = 'Laten we papa’s erbij betrekken. 👨‍🍼', body_nl = 'Laat papa na de avondvoeding het boertje en het in slaap brengen doen, en neem tijd voor jezelf.', title_pl = 'Zaangażujmy tatę. 👨‍🍼', body_pl = 'Po wieczornym karmieniu oddaj tacie odbijanie i usypianie, a sama znajdź czas dla siebie.', title_pt = 'Vamos envolver também os pais. 👨‍🍼', body_pt = 'Depois da mamada da noite, deixe o pai tratar do arroto e de adormecer o bebé, e reserve tempo para si.', title_sv = 'Vi tar med papporna i processen. 👨‍🍼', body_sv = 'Efter kvällsmatningen, låt pappa ta rapningen och nattningen och ta tid för dig själv.', title_vi = 'Cùng rủ bố tham gia. 👨‍🍼', body_vi = 'Sau cữ bú buổi tối, hãy giao lượt vỗ ợ hơi và ru ngủ cho bố, còn mẹ dành thời gian cho bản thân.', title_zh = '让爸爸也参与进来。👨‍🍼', body_zh = '晚上喂完奶后，把拍嗝和哄睡交给爸爸，给自己留点时间。' WHERE id = '65d67a55-0ffc-4c5f-8c78-443c16c7f697' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Cada vez más sonrisas! 😍', body_es = '¡No te pierdas ese momento mágico en que te mira y hace gorjeos! Hazle una foto y ponla en el rincón más bonito del Álbum del bebé.', title_fr = 'Les sourires se multiplient ! 😍', body_fr = 'Ne manquez pas ce moment magique où il vous regarde en gazouillant ! Prenez une photo et placez-la au plus bel endroit de l''Album de bébé.', title_hi = 'मुस्कानें बढ़ रही हैं! 😍', body_hi = 'वह जादुई पल मत चूकिए जब वह आपको देखकर किलकारी मारे! फ़ोटो लीजिए और बेबी एल्बम के सबसे सुंदर कोने में रखिए।', title_id = 'Senyumnya makin banyak! 😍', body_id = 'Jangan lewatkan momen ajaib saat ia menatap Anda sambil mengoceh! Ambil fotonya dan letakkan di sudut terindah Album Bayi.', title_ja = '笑顔が増えてきました！😍', body_ja = '赤ちゃんがママを見てきゃっきゃっと声を出す魔法の瞬間を見逃さないで！写真を撮って、「ベビーアルバム」のいちばんすてきな場所に飾りましょう。', title_ko = '미소가 늘고 있어요! 😍', body_ko = '아기가 엄마를 보며 까르르 웃는 그 마법 같은 순간을 놓치지 마세요! 사진을 찍어 아기 앨범의 가장 예쁜 자리에 두세요.', title_nl = 'Steeds meer lachjes! 😍', body_nl = 'Mis dat magische moment niet waarop je baby naar je kijkt en brabbelt! Maak een foto en geef hem het mooiste plekje in het Babyalbum.', title_pl = 'Uśmiechów przybywa! 😍', body_pl = 'Nie przegap tej magicznej chwili, gdy patrzy na ciebie i gaworzy! Zrób zdjęcie i umieść je w najpiękniejszym miejscu Albumu dziecka.', title_pt = 'Os sorrisos estão a multiplicar-se! 😍', body_pt = 'Não perca aquele momento mágico em que olha para si e palra! Tire uma foto e ponha-a no cantinho mais bonito do Álbum do Bebé.', title_sv = 'Leendena blir fler! 😍', body_sv = 'Missa inte det magiska ögonblicket när barnet tittar på dig och jollrar! Ta en bild och placera den på den finaste platsen i Babyalbumet.', title_vi = 'Bé cười nhiều hơn! 😍', body_vi = 'Đừng bỏ lỡ khoảnh khắc kỳ diệu khi bé nhìn mẹ và cười khanh khách! Chụp lại và đặt vào góc đẹp nhất của Album của bé.', title_zh = '笑容越来越多！😍', body_zh = '别错过宝宝看着你咯咯笑的神奇瞬间！拍下来，放进宝宝相册最美的位置吧。' WHERE id = 'c7ab2e50-8e71-4df1-97cc-6432f40c4349' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Un café con amigas? ☕', body_es = 'Encuentra en Lugares para mamás las cafeterías más cercanas y cómodas a las que puedes ir con tu bebé.', title_fr = 'Une pause café entre copines ? ☕', body_fr = 'Trouvez les cafés confortables les plus proches où aller avec votre bébé dans les Lieux adaptés aux mamans.', title_hi = 'सहेलियों के साथ कॉफ़ी ब्रेक? ☕', body_hi = 'बच्चे के साथ जा सकें, ऐसे सबसे पास के आरामदायक कैफ़े माँ के लिए अनुकूल जगहों में ढूँढिए।', title_id = 'Ngopi bareng sahabat? ☕', body_id = 'Temukan kafe terdekat dan nyaman yang bisa Anda datangi bersama bayi di Tempat Ramah Ibu.', title_ja = '友達とコーヒーブレイク？☕', body_ja = '赤ちゃんと一緒に行ける近くの快適なカフェを、「ママにやさしいスポット」で見つけましょう。', title_ko = '친구들과 커피 타임? ☕', body_ko = '아기와 함께 갈 수 있는 가깝고 편한 카페를 엄마 친화 장소에서 찾아보세요.', title_nl = 'Koffie met vriendinnen? ☕', body_nl = 'Vind de dichtstbijzijnde fijne cafés waar je met je baby naartoe kunt in Mamavriendelijke plekken.', title_pl = 'Kawa z przyjaciółkami? ☕', body_pl = 'Najbliższe wygodne kawiarnie, do których pójdziesz z dzieckiem, znajdziesz w Miejscach przyjaznych mamom.', title_pt = 'Um café com as amigas? ☕', body_pt = 'Encontre nos Locais Amigos das Mães os cafés mais próximos e confortáveis onde pode ir com o bebé.', title_sv = 'Kafferast med väninnorna? ☕', body_sv = 'Hitta de närmaste och bekvämaste kaféerna dit du kan gå med barnet i Mammavänliga platser.', title_vi = 'Cà phê cùng hội bạn? ☕', body_vi = 'Tìm những quán cà phê gần nhất, thoải mái để đi cùng bé trong mục Địa điểm thân thiện với mẹ.', title_zh = '和闺蜜喝杯咖啡？☕', body_zh = '在妈妈友好场所里找到离你最近、可以带宝宝一起去的舒适咖啡馆。' WHERE id = 'dba00752-8e14-4710-8793-6a828172c915' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue su desarrollo paso a paso. 📚', body_es = 'Para saber qué habilidades adquieren los recién nacidos este mes, lee nuestro último artículo en la sección Blog.', title_fr = 'Suivez son développement pas à pas. 📚', body_fr = 'Pour savoir quelles compétences les nouveau-nés acquièrent ce mois-ci, lisez notre dernier article dans la rubrique Blogs.', title_hi = 'विकास पर कदम-दर-कदम नज़र रखिए। 📚', body_hi = 'नवजात शिशु इस महीने कौन से हुनर सीखते हैं, यह जानने के लिए ब्लॉग सेक्शन में हमारा नया लेख पढ़िए।', title_id = 'Pantau perkembangannya langkah demi langkah. 📚', body_id = 'Untuk mengetahui keterampilan apa yang dikuasai bayi baru lahir di bulan ini, baca artikel terbaru kami di bagian Blog.', title_ja = '成長を一歩ずつ見守りましょう。📚', body_ja = 'この月に赤ちゃんがどんなことをできるようになるのか、ブログの最新記事を読んでみましょう。', title_ko = '성장을 한 걸음씩 확인해요. 📚', body_ko = '이번 달 신생아가 어떤 능력을 익히는지 알고 싶다면 블로그 섹션의 최신 글을 읽어 보세요.', title_nl = 'Volg de ontwikkeling stap voor stap. 📚', body_nl = 'Lees ons nieuwste artikel in het onderdeel Blogs om te weten welke vaardigheden pasgeborenen deze maand leren.', title_pl = 'Śledź rozwój krok po kroku. 📚', body_pl = 'Aby wiedzieć, jakie umiejętności noworodki zdobywają w tym miesiącu, przeczytaj nasz najnowszy artykuł w sekcji Blogi.', title_pt = 'Acompanhe o desenvolvimento passo a passo. 📚', body_pt = 'Para saber que capacidades os recém-nascidos adquirem este mês, leia o nosso artigo mais recente na secção Blogues.', title_sv = 'Följ utvecklingen steg för steg. 📚', body_sv = 'Läs vår senaste artikel i Bloggen för att veta vilka färdigheter nyfödda lär sig den här månaden.', title_vi = 'Theo dõi sự phát triển từng bước. 📚', body_vi = 'Hãy đọc bài viết mới nhất trong mục Blog để biết trẻ sơ sinh học được những kỹ năng gì trong tháng này.', title_zh = '一步步记录成长。📚', body_zh = '想知道新生儿这个月会掌握哪些本领？读读博客板块里的最新文章吧。' WHERE id = '503a0808-7061-4b7d-ae17-f65b9abb87de' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las horas de sueño diarias. 🛌', body_es = 'Cuando tu bebé duerma, pon en marcha el temporizador de sueño y comprueba si cumple las 14-17 horas diarias.', title_fr = 'La norme de sommeil quotidienne. 🛌', body_fr = 'Quand votre bébé dort, lancez le minuteur de sommeil et vérifiez s''il atteint sa norme de 14 à 17 heures par jour.', title_hi = 'रोज़ की नींद का मानक। 🛌', body_hi = 'बच्चा सोए, तो स्लीप टाइमर शुरू कीजिए और देखिए कि वह रोज़ के 14-17 घंटे का मानक पूरा कर रहा है या नहीं।', title_id = 'Kebutuhan tidur harian. 🛌', body_id = 'Saat bayi Anda tidur, mulai pengatur waktu tidur dan analisis apakah ia memenuhi kebutuhan 14-17 jam sehari.', title_ja = '1日の睡眠の目安。🛌', body_ja = '赤ちゃんが眠ったら睡眠タイマーをスタートして、1日14-17時間の目安を満たしているか分析しましょう。', title_ko = '하루 수면 기준치. 🛌', body_ko = '아기가 잘 때 수면 타이머를 시작하고 하루 14-17시간 기준치를 채우는지 분석해 보세요.', title_nl = 'De dagelijkse slaapnorm. 🛌', body_nl = 'Zet de slaaptimer aan als je baby slaapt en bekijk of de dagelijkse norm van 14-17 uur wordt gehaald.', title_pl = 'Dzienna norma snu. 🛌', body_pl = 'Gdy dziecko śpi, włącz timer snu i sprawdź, czy osiąga dzienną normę 14-17 godzin.', title_pt = 'Horas de sono diárias. 🛌', body_pt = 'Quando o bebé dormir, ligue o temporizador de sono e veja se cumpre as 14-17 horas diárias recomendadas.', title_sv = 'Den dagliga sömnnormen. 🛌', body_sv = 'Starta sömntimern när barnet sover och analysera om det når sin dagliga norm på 14-17 timmar.', title_vi = 'Định mức ngủ hằng ngày. 🛌', body_vi = 'Khi bé ngủ, hãy bật bộ hẹn giờ ngủ và phân tích xem bé có ngủ đủ 14-17 tiếng mỗi ngày không.', title_zh = '每日睡眠参考量。🛌', body_zh = '宝宝睡觉时启动睡眠计时器，看看宝宝是否达到每天14-17小时的参考量。' WHERE id = 'aeea52a4-dd88-4cf1-a812-0c13b4f98004' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Ya lleváis 50 días juntos! 🎈', body_es = '¡Celebra este aniversario increíble creando una foto especial con la herramienta Sesión de fotos del bebé!', title_fr = 'Pile 50 jours ensemble ! 🎈', body_fr = 'Fêtez ce merveilleux anniversaire en créant une photo spéciale avec l''outil Séance photo bébé !', title_hi = 'आप पूरे 50 दिन से साथ हैं! 🎈', body_hi = 'इस शानदार सालगिरह को बेबी फ़ोटोशूट टूल से एक खास तस्वीर बनाकर मनाइए!', title_id = 'Tepat 50 hari Anda bersama! 🎈', body_id = 'Rayakan momen luar biasa ini dengan membuat foto istimewa lewat alat Pemotretan Bayi!', title_ja = '一緒に過ごしてちょうど50日！🎈', body_ja = 'このすばらしい記念日を、「ベビーフォトセッション」で特別な写真をつくってお祝いしましょう！', title_ko = '함께한 지 딱 50일이에요! 🎈', body_ko = '이 멋진 기념일을 아기 사진 촬영 도구로 특별한 사진을 만들어 축하해 보세요!', title_nl = 'Jullie zijn precies 50 dagen samen! 🎈', body_nl = 'Vier dit prachtige jubileum met een speciale foto via de tool Babyfotoshoot!', title_pl = 'Jesteście razem równo 50 dni! 🎈', body_pl = 'Uczcij ten wspaniały jubileusz wyjątkowym zdjęciem dzięki narzędziu Sesja zdjęciowa dziecka!', title_pt = 'Já estão juntos há 50 dias certinhos! 🎈', body_pt = 'Celebre este aniversário fantástico criando uma foto especial com a Sessão Fotográfica do Bebé!', title_sv = 'Nu har ni varit tillsammans i precis 50 dagar! 🎈', body_sv = 'Fira det här fantastiska jubileet genom att skapa en speciell bild med verktyget Babyfotografering!', title_vi = 'Tròn 50 ngày mẹ con bên nhau! 🎈', body_vi = 'Hãy kỷ niệm cột mốc tuyệt vời này bằng một bức ảnh đặc biệt với công cụ Chụp ảnh cho bé!', title_zh = '你们已经在一起整整50天啦！🎈', body_zh = '用宝宝写真工具拍一张特别的照片，庆祝这个了不起的纪念日吧！' WHERE id = '9d97fdbc-edef-4830-93ad-c388f586d909' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Análisis de los últimos 50 días. 📈', body_es = 'Mira las secciones Seguimiento del desarrollo y Seguimiento de tomas y descubre lo bien que ha crecido tu bebé en estos 50 días.', title_fr = 'Le bilan des 50 derniers jours. 📈', body_fr = 'Consultez le Suivi de croissance et le Suivi des repas pour découvrir à quel point votre bébé a bien grandi en 50 jours.', title_hi = 'पिछले 50 दिनों का विश्लेषण। 📈', body_hi = 'ग्रोथ ट्रैकर और फ़ीडिंग ट्रैकर सेक्शन देखकर जानिए कि इन 50 दिनों में आपका बच्चा कितनी खूबसूरती से बढ़ा।', title_id = 'Analisis 50 hari terakhir. 📈', body_id = 'Lihat bagian Pelacak Pertumbuhan dan Pemantau Menyusu untuk menemukan betapa indahnya bayi Anda tumbuh dalam 50 hari ini.', title_ja = 'この50日間をふり返り。📈', body_ja = '「成長トラッカー」と授乳記録を見て、この50日で赤ちゃんがどれだけすくすく育ったか確かめましょう。', title_ko = '지난 50일 분석. 📈', body_ko = '성장 기록과 수유 기록 섹션에서 아기가 50일 동안 얼마나 예쁘게 자랐는지 확인해 보세요.', title_nl = 'De analyse van de afgelopen 50 dagen. 📈', body_nl = 'Bekijk de onderdelen Groeitracker en Voedingstracker en ontdek hoe mooi je baby in deze 50 dagen is gegroeid.', title_pl = 'Podsumowanie ostatnich 50 dni. 📈', body_pl = 'Zajrzyj do sekcji Śledzenie rozwoju i Kontrola karmienia i zobacz, jak pięknie dziecko urosło w te 50 dni.', title_pt = 'A análise dos últimos 50 dias. 📈', body_pt = 'Veja as secções Registo de Crescimento e Registo de Alimentação e descubra como o bebé cresceu bem nestes 50 dias.', title_sv = 'Analys av de senaste 50 dagarna. 📈', body_sv = 'Titta i Tillväxtspåraren och Matningskoll och upptäck hur fint barnet har vuxit under de här 50 dagarna.', title_vi = 'Nhìn lại 50 ngày qua. 📈', body_vi = 'Xem mục Theo dõi phát triển và Theo dõi cữ bú để thấy bé đã lớn lên tuyệt vời thế nào trong 50 ngày này.', title_zh = '回顾这50天。📈', body_zh = '看看成长记录和喂养记录板块，发现宝宝这50天长得有多好。' WHERE id = 'cb1a5cad-e167-45a8-b0b1-4e8ebe455866' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Su campo de visión se amplía! 👀', body_es = 'Ya puede seguir mejor los objetos con la mirada.', title_fr = 'Son champ de vision s''élargit ! 👀', body_fr = 'Il peut mieux suivre les objets du regard.', title_hi = 'नज़र का दायरा बढ़ रहा है! 👀', body_hi = 'वह अब चीज़ों का नज़रों से बेहतर पीछा कर सकता है।', title_id = 'Jangkauan pandangnya meluas! 👀', body_id = 'Ia kini bisa mengikuti benda dengan lebih baik.', title_ja = '見える範囲が広がっています！👀', body_ja = '赤ちゃんはもう、ものをよりよく目で追えるようになりました。', title_ko = '시야가 넓어지고 있어요! 👀', body_ko = '아기가 이제 물건을 더 잘 따라 볼 수 있어요.', title_nl = 'Het gezichtsveld wordt breder! 👀', body_nl = 'Je baby kan dingen al beter volgen.', title_pl = 'Pole widzenia się poszerza! 👀', body_pl = 'Już lepiej śledzi wzrokiem przedmioty.', title_pt = 'O campo de visão está a alargar! 👀', body_pt = 'O bebé já consegue seguir melhor os objetos com o olhar.', title_sv = 'Synfältet vidgas! 👀', body_sv = 'Barnet kan nu följa föremål bättre med blicken.', title_vi = 'Tầm nhìn đang rộng hơn! 👀', body_vi = 'Bé đã có thể dõi theo đồ vật tốt hơn.', title_zh = '视野在变宽！👀', body_zh = '宝宝现在能更好地追视物品了。' WHERE id = 'b67a89c9-d8cf-40c2-97a2-43b27081ed44' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hora de aire fresco! 🌳', body_es = 'Entra en nuestro mapa de Lugares para mamás y encuentra el sitio más cómodo para ir con tu bebé.', title_fr = 'L''heure de prendre l''air ! 🌳', body_fr = 'Ouvrez notre carte des Lieux adaptés aux mamans et trouvez l''endroit le plus confortable où aller avec votre bébé.', title_hi = 'ताज़ी हवा का समय! 🌳', body_hi = 'माँ के लिए अनुकूल जगहों का नक्शा खोलिए और बच्चे के साथ जाने लायक सबसे आरामदायक जगह ढूँढिए।', title_id = 'Waktunya udara segar! 🌳', body_id = 'Buka peta Tempat Ramah Ibu kami dan temukan tempat paling nyaman untuk dikunjungi bersama bayi Anda.', title_ja = '新鮮な空気の時間！🌳', body_ja = '「ママにやさしいスポット」マップを開いて、赤ちゃんと一緒に行けるいちばん快適な場所を見つけましょう。', title_ko = '바깥 공기 쐴 시간! 🌳', body_ko = '엄마 친화 장소 지도에서 아기와 함께 갈 수 있는 가장 편한 곳을 찾아보세요.', title_nl = 'Tijd voor frisse lucht! 🌳', body_nl = 'Open onze kaart Mamavriendelijke plekken en vind de fijnste plek om met je baby naartoe te gaan.', title_pl = 'Czas na świeże powietrze! 🌳', body_pl = 'Otwórz naszą mapę Miejsc przyjaznych mamom i znajdź najwygodniejsze miejsce na wyjście z dzieckiem.', title_pt = 'Hora de apanhar ar puro! 🌳', body_pt = 'Abra o nosso mapa de Locais Amigos das Mães e encontre o sítio mais confortável para ir com o bebé.', title_sv = 'Dags för frisk luft! 🌳', body_sv = 'Öppna vår karta Mammavänliga platser och hitta det bekvämaste stället dit du kan gå tillsammans med barnet.', title_vi = 'Giờ hít thở không khí trong lành! 🌳', body_vi = 'Vào bản đồ Địa điểm thân thiện với mẹ và tìm nơi thoải mái nhất để đi cùng bé.', title_zh = '呼吸新鲜空气的时间到！🌳', body_zh = '打开我们的妈妈友好场所地图，找到可以带宝宝一起去的最舒适的地方。' WHERE id = '42ca0f3b-8083-4338-bf16-9998a33b15c6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control de peso y talla. 📏', body_es = '¿Cómo está creciendo tu bebé? Introduce los nuevos datos en el Registro de peso y sigue su curva de crecimiento personal.', title_fr = 'Suivi du poids et de la taille. 📏', body_fr = 'Comment grandit votre bébé ? Saisissez les nouvelles données dans le Suivi du poids et suivez sa courbe personnalisée.', title_hi = 'वज़न और लंबाई पर नज़र। 📏', body_hi = 'आपका बच्चा कैसे बढ़ रहा है? वेट ट्रैकर में नए आँकड़े दर्ज करके व्यक्तिगत विकास चार्ट देखिए।', title_id = 'Pemantauan berat dan tinggi. 📏', body_id = 'Bagaimana pertumbuhan bayi Anda? Masukkan data terbaru ke Pelacak Berat Badan dan pantau grafik pertumbuhan pribadinya.', title_ja = '体重と身長のチェック。📏', body_ja = '赤ちゃんはどんなふうに育っていますか？新しいデータを「体重トラッカー」に入力して、あなただけの成長グラフを見守りましょう。', title_ko = '몸무게와 키 확인. 📏', body_ko = '아기가 어떻게 자라고 있나요? 체중 기록에 새 정보를 입력하고 나만의 성장 그래프를 확인하세요.', title_nl = 'Gewicht en lengte bijhouden. 📏', body_nl = 'Hoe groeit je baby? Voer de nieuwe gegevens in de Gewichtstracker in en volg de persoonlijke groeicurve.', title_pl = 'Kontrola wagi i wzrostu. 📏', body_pl = 'Jak rośnie twoje dziecko? Wpisz nowe dane do Licznika wagi i śledź jego osobisty wykres rozwoju.', title_pt = 'Controlo do peso e da altura. 📏', body_pt = 'Como está o bebé a crescer? Introduza os novos dados no Registo de Peso e acompanhe a curva de crescimento personalizada.', title_sv = 'Koll på vikt och längd. 📏', body_sv = 'Hur växer ditt barn? Skriv in nya uppgifter i Viktspåraren och följ den personliga tillväxtkurvan.', title_vi = 'Theo dõi cân nặng và chiều cao. 📏', body_vi = 'Bé đang lớn thế nào? Nhập số liệu mới vào Theo dõi cân nặng để theo dõi biểu đồ phát triển riêng của bé.', title_zh = '体重和身高记录。📏', body_zh = '宝宝长得怎么样？把新数据录入体重记录，追踪宝宝的专属成长曲线。' WHERE id = '7fc52d97-b36d-4c5e-a169-0eadba238b0e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Descubre sus manos! 👐', body_es = 'Ya se mira los dedos y se los lleva a la boca.', title_fr = 'Il découvre ses mains ! 👐', body_fr = 'Il regarde déjà ses doigts et les porte à sa bouche.', title_hi = 'अपने हाथ खोज रहा है! 👐', body_hi = 'वह अब अपनी उँगलियों को देखता है और उन्हें मुँह में ले जाता है।', title_id = 'Ia menjelajahi tangannya! 👐', body_id = 'Ia kini memandangi jari-jarinya dan memasukkannya ke mulut.', title_ja = '手を発見しています！👐', body_ja = '赤ちゃんはもう自分の指を見つめて、口に持っていきます。', title_ko = '손을 발견하고 있어요! 👐', body_ko = '아기가 벌써 자기 손가락을 바라보고 입으로 가져가요.', title_nl = 'Je baby ontdekt de handjes! 👐', body_nl = 'Je baby kijkt al naar de vingertjes en stopt ze in het mondje.', title_pl = 'Odkrywa swoje rączki! 👐', body_pl = 'Już przygląda się swoim paluszkom i wkłada je do buzi.', title_pt = 'Está a descobrir as mãos! 👐', body_pt = 'O bebé já olha para os dedos e leva-os à boca.', title_sv = 'Barnet upptäcker sina händer! 👐', body_sv = 'Nu tittar barnet på sina fingrar och stoppar dem i munnen.', title_vi = 'Bé đang khám phá đôi tay! 👐', body_vi = 'Bé đã biết nhìn ngón tay và đưa chúng lên miệng.', title_zh = '宝宝在探索自己的小手！👐', body_zh = '宝宝已经会盯着自己的手指看，还把它们放进嘴里。' WHERE id = '0c1e843a-b2dc-4995-89cf-7af4230d574e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,''