UPDATE public.mommy_day_notifications SET title_es = '¡Tu informe diario está listo! 📊', body_es = 'Entra en la app Anacan y revisa el análisis de los gráficos de sueño, tomas y pañales de hoy.', title_fr = 'Votre rapport du jour est prêt ! 📊', body_fr = 'Ouvrez l''application Anacan pour consulter l''analyse de vos graphiques de sommeil, de repas et de couches du jour.', title_hi = 'आपकी रोज़ की रिपोर्ट तैयार है! 📊', body_hi = 'Anacan ऐप खोलकर आज की नींद, फ़ीडिंग और डायपर चार्ट का विश्लेषण देखिए।', title_id = 'Laporan harian Anda sudah siap! 📊', body_id = 'Buka aplikasi Anacan dan lihat analisis grafik tidur, menyusu, dan popok hari ini.', title_ja = '今日のレポートができました！📊', body_ja = 'Anacanアプリを開いて、今日の睡眠、授乳、おむつのグラフの分析を見てみましょう。', title_ko = '오늘의 리포트가 준비됐어요! 📊', body_ko = 'Anacan 앱에서 오늘의 수면, 수유, 기저귀 그래프 분석을 확인해 보세요.', title_nl = 'Je dagrapport is klaar! 📊', body_nl = 'Open de Anacan-app en bekijk de analyse van de slaap-, voedings- en luiergrafieken van vandaag.', title_pl = 'Twój dzienny raport jest gotowy! 📊', body_pl = 'Wejdź do aplikacji Anacan i zobacz analizę dzisiejszych wykresów snu, karmienia i pieluszek.', title_pt = 'O seu relatório diário está pronto! 📊', body_pt = 'Entre na app Anacan e veja a análise dos gráficos de sono, alimentação e fraldas de hoje.', title_sv = 'Din dagliga rapport är klar! 📊', body_sv = 'Öppna Anacan-appen och titta på analysen av dagens diagram för sömn, matning och blöjor.', title_vi = 'Báo cáo hằng ngày của mẹ đã sẵn sàng! 📊', body_vi = 'Vào ứng dụng Anacan để xem phân tích biểu đồ ngủ, cữ bú và thay tã hôm nay.', title_zh = '你的每日报告已生成！📊', body_zh = '打开Anacan应用，查看今天的睡眠、喂养和尿布图表分析。' WHERE id = 'd935b5ec-1166-4c5b-a013-19977086a00b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND 