UPDATE public.mommy_day_notifications SET title_es = 'Seguimos los pañales del día. 🧷', title_fr = 'Nous suivons les couches du jour. 🧷', title_hi = 'हम रोज़ के डायपर पर नज़र रख रहे हैं। 🧷', title_id = 'Kita pantau popok hariannya. 🧷', title_ja = '1日のおむつを記録しましょう。🧷', title_ko = '하루 기저귀를 기록해요. 🧷', title_nl = 'We houden de luiers per dag bij. 🧷', title_pl = 'Śledzimy dzienne pieluszki. 🧷', title_pt = 'Acompanhamos as fraldas do dia. 🧷', title_sv = 'Vi följer blöjorna varje dag. 🧷', title_vi = 'Theo dõi số tã hằng ngày. 🧷', title_zh = '记录每天的尿布情况。🧷' WHERE id = 'ffb2dcc3-196c-4439-b233-ee14c9337ae5' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Enhorabuena, ya llevas 1 semana siendo mamá! 🥳', body_es = '¡Enhorabuena, ya llevas 1 semana siendo mamá! 🥳 Crea una foto de recuerdo de este día especial con la sección Sesión de fotos del bebé.', title_fr = 'Félicitations, vous êtes maman depuis 1 semaine ! 🥳', body_fr = 'Félicitations, vous êtes maman depuis 1 semaine ! 🥳 Créez un souvenir photo de ce jour spécial avec la rubrique Séance photo bébé.', title_hi = 'बधाई हो, आपको माँ बने 1 हफ़्ता हो गया! 🥳', body_hi = 'बधाई हो, आपको माँ बने 1 हफ़्ता हो गया! 🥳 बेबी फ़ोटोशूट सेक्शन से इस खास दिन की यादगार तस्वीर बनाइए।', title_id = 'Selamat, Anda sudah 1 minggu menjadi ibu! 🥳', body_id = 'Selamat, Anda sudah 1 minggu menjadi ibu! 🥳 Manfaatkan bagian Pemotretan Bayi untuk membuat foto kenangan hari istimewa ini.', title_ja = 'おめでとうございます、ママになって1週間！🥳', body_ja = 'おめでとうございます、ママになって1週間！🥳 「ベビーフォトセッション」を使って、この特別な日の記念写真をつくりましょう。', title_ko = '축하해요, 엄마가 된 지 1주가 됐어요! 🥳', body_ko = '축하해요, 엄마가 된 지 1주가 됐어요! 🥳 아기 사진 촬영 섹션으로 이 특별한 날의 기념사진을 만들어 보세요.', title_nl = 'Gefeliciteerd, je bent al 1 week mama! 🥳', body_nl = 'Gefeliciteerd, je bent al 1 week mama! 🥳 Maak met het onderdeel Babyfotoshoot een herinnering aan deze bijzondere dag.', title_pl = 'Gratulacje, jesteś mamą od 1 tygodnia! 🥳', body_pl = 'Gratulacje, jesteś mamą od 1 tygodnia! 🥳 Skorzystaj z sekcji Sesja zdjęciowa dziecka i stwórz pamiątkowe zdjęcie tego wyjątkowego dnia.', title_pt = 'Parabéns, já é mãe há 1 semana! 🥳', body_pt = 'Parabéns, já é mãe há 1 semana! 🥳 Use a secção Sessão Fotográfica do Bebé para criar uma foto de recordação deste dia especial.', title_sv = 'Grattis, nu har du varit mamma i 1 vecka! 🥳', body_sv = 'Grattis, nu har du varit mamma i 1 vecka! 🥳 Skapa en minnesbild av den här speciella dagen i avsnittet Babyfotografering.', title_vi = 'Chúc mừng, mẹ đã làm mẹ được 1 tuần! 🥳', body_vi = 'Chúc mừng, mẹ đã làm mẹ được 1 tuần! 🥳 Hãy dùng mục Chụp ảnh cho bé để tạo tấm ảnh kỷ niệm ngày đặc biệt này.', title_zh = '恭喜，你当妈妈已经1周啦！🥳', body_zh = '恭喜，你当妈妈已经1周啦！🥳 用宝宝写真板块，为这个特别的日子留下纪念照片吧。' WHERE id = '74dae015-c762-4d96-ad34-7d706065ef5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Congelar el tiempo 📸', title_fr = 'Arrêter le temps 📸', title_hi = 'समय को थाम लीजिए 📸', title_id = 'Membekukan waktu 📸', title_ja = '時間を止めよう 📸', title_ko = '시간을 멈춰요 📸', title_nl = 'De tijd stilzetten 📸', title_pl = 'Zatrzymaj czas 📸', title_pt = 'Congelar o tempo 📸', title_sv = 'Frys tiden 📸', title_vi = 'Đóng băng thời gian 📸', title_zh = '定格时光 📸' WHERE id = 'e22900db-05e9-4ef6-8e2b-3f0d3690dce5' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ponemos rutina a los despertares nocturnos. 😴', body_es = 'No enciendas las luces cada vez que se despierte. Dale de comer con el temporizador de Anacan y vuelve a dormirle con el Ruido blanco.', title_fr = 'Instaurons une routine pour les réveils nocturnes. 😴', body_fr = 'N''allumez pas la lumière à chaque réveil. Nourrissez-le avec le minuteur Anacan, puis rendormez-le avec les Bruits blancs.', title_hi = 'रात में जागने को रूटीन में ला रहे हैं। 😴', body_hi = 'हर बार जागने पर लाइट मत जलाइए। Anacan टाइमर के साथ दूध पिलाइए और व्हाइट नॉइज़ से फिर सुलाइए।', title_id = 'Kita buat rutinitas untuk bangun malam. 😴', body_id = 'Jangan menyalakan lampu setiap kali ia bangun. Susui dengan pengatur waktu Anacan, lalu tidurkan kembali dengan Suara Putih.', title_ja = '夜中の目覚めにもリズムを。😴', body_ja = '起きるたびに明かりをつけないようにしましょう。Anacanのタイマーで授乳を記録し、ホワイトノイズで再び寝かしつけましょう。', title_ko = '밤중에 깨는 것도 루틴으로 만들어요. 😴', body_ko = '아기가 깰 때마다 불을 켜지 마세요. Anacan 타이머로 수유하고 백색소음으로 다시 재워 주세요.', title_nl = 'We brengen ritme in het nachtelijk wakker worden. 😴', body_nl = 'Doe niet elke keer het licht aan als je baby wakker wordt. Geef de voeding met de Anacan-timer en breng je baby weer in slaap met Witte ruis.', title_pl = 'Wprowadzamy rutynę w nocne pobudki. 😴', body_pl = 'Przy każdej pobudce nie zapalaj świateł. Nakarm z timerem Anacan i uśpij ponownie przy Białym szumie.', title_pt = 'Vamos criar uma rotina para os despertares noturnos. 😴', body_pt = 'Não acenda as luzes sempre que acorda. Alimente-o com o temporizador do Anacan e volte a adormecê-lo com o Ruído Branco.', title_sv = 'Vi skapar rutin kring nattliga uppvaknanden. 😴', body_sv = 'Tänd inte lamporna varje gång barnet vaknar. Mata med Anacan-timern och söv om med Vitt brus.', title_vi = 'Đưa những lần thức đêm vào nếp. 😴', body_vi = 'Đừng bật đèn mỗi lần bé thức. Cho bé bú với bộ hẹn giờ Anacan, rồi ru bé ngủ lại bằng Tiếng ồn trắng.', title_zh = '让夜醒也有规律。😴', body_zh = '宝宝每次醒来时不要开灯。用Anacan计时器喂完奶，再用白噪音哄宝宝重新入睡。' WHERE id = '42fb5186-3443-4ea8-b1d1-54ac0c1a9ccb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
