UPDATE public.mommy_day_notifications SET title_es = '¿Revisamos los datos de la primera semana? 📊', body_es = '¿Quieres ver tus estadísticas semanales de sueño, pañales y tomas en la app Anacan?', title_fr = 'On regarde le bilan de la première semaine ? 📊', body_fr = 'Envie de consulter vos statistiques hebdomadaires de sommeil, de couches et de repas dans l''application Anacan ?', title_hi = 'पहले हफ़्ते का विश्लेषण देखें? 📊', body_hi = 'क्या आप Anacan ऐप में हफ़्ते भर की नींद, डायपर और फ़ीडिंग के आँकड़े देखना चाहेंगी?', title_id = 'Lihat analisis minggu pertama yuk? 📊', body_id = 'Ingin memeriksa statistik tidur, popok, dan menyusu mingguan Anda di aplikasi Anacan?', title_ja = '最初の1週間のデータを見てみましょう？📊', body_ja = 'Anacanアプリで、1週間の睡眠、おむつ、授乳のデータを確認してみませんか？', title_ko = '첫 주 기록을 살펴볼까요? 📊', body_ko = 'Anacan 앱에서 일주일 동안의 수면, 기저귀, 수유 통계를 확인해 볼까요?', title_nl = 'Zullen we de cijfers van de eerste week bekijken? 📊', body_nl = 'Wil je je wekelijkse statistieken over slaap, luiers en voedingen in de Anacan-app bekijken?', title_pl = 'Przejrzymy dane z pierwszego tygodnia? 📊', body_pl = 'Chcesz sprawdzić tygodniowe statystyki snu, pieluszek i karmienia w aplikacji Anacan?', title_pt = 'Vamos ver os dados da primeira semana? 📊', body_pt = 'Quer ver as estatísticas semanais de sono, fraldas e mamadas na app Anacan?', title_sv = 'Ska vi titta på första veckans analys? 📊', body_sv = 'Vill du kolla din veckostatistik för sömn, blöjor och matning i Anacan-appen?', title_vi = 'Cùng xem số liệu tuần đầu nhé? 📊', body_vi = 'Mẹ có muốn xem thống kê giấc ngủ, thay tã và cữ bú hằng tuần trong ứng dụng Anacan không?', title_zh = '来看看第一周的数据？📊', body_zh = '想在Anacan应用里查看本周的睡眠、尿布和喂养统计吗？' WHERE id = '7c7a5fbe-09ea-4f4c-a054-883ad490f939' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title