UPDATE public.mommy_day_notifications SET title_es = 'Hora de salir 🌳', title_fr = 'L''heure de sortir 🌳', title_hi = 'बाहर निकलने का समय 🌳', title_id = 'Waktunya keluar rumah 🌳', title_ja = 'おでかけの時間 🌳', title_ko = '외출 시간 🌳', title_nl = 'Tijd om naar buiten te gaan 🌳', title_pl = 'Czas na wyjście 🌳', title_pt = 'Hora de sair 🌳', title_sv = 'Dags att gå ut 🌳', title_vi = 'Đến giờ ra ngoài 🌳', title_zh = '该出门了 🌳' WHERE id = 'b31044ce-8042-4a44-af14-b71856994efe' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Recuperación física 🩹', body_es = 'Tu cuerpo aún se está recuperando y puede que te duelan los puntos. No te exijas la perfección.', title_fr = 'Récupération physique 🩹', body_fr = 'Votre corps se rétablit encore, vos points de suture vous font peut-être mal. N''exigez pas la perfection de vous-même.', title_hi = 'शारीरिक रिकवरी 🩹', body_hi = 'आपका शरीर अभी भी ठीक हो रहा है, शायद टाँकों में दर्द हो। खुद से परफ़ेक्शन की उम्मीद मत कीजिए।', title_id = 'Pemulihan fisik 🩹', body_id = 'Tubuh Anda masih dalam pemulihan, mungkin jahitan Anda masih nyeri. Jangan menuntut kesempurnaan dari diri sendiri.', title_ja = '体の回復 🩹', body_ja = '体はまだ回復の途中で、傷口が痛むかもしれません。自分に完璧を求めないでくださいね。', title_ko = '몸의 회복 🩹', body_ko = '몸은 아직 회복 중이고, 봉합 부위가 아플 수도 있어요. 스스로에게 완벽함을 요구하지 마세요.', title_nl = 'Lichamelijk herstel 🩹', body_nl = 'Je lichaam herstelt nog, misschien doen je hechtingen nog pijn. Verwacht geen perfectie van jezelf.', title_pl = 'Powrót do formy 🩹', body_pl = 'Twoje ciało wciąż się regeneruje, może bolą cię szwy. Nie wymagaj od siebie perfekcji.', title_pt = 'Recuperação física 🩹', body_pt = 'O seu corpo ainda está a recuperar e talvez os pontos ainda doam. Não exija a perfeição de si mesma.', title_sv = 'Kroppslig återhämtning 🩹', body_sv = 'Din kropp återhämtar sig fortfarande och stygnen kanske gör ont. Kräv inte perfektion av dig själv.', title_vi = 'Hồi phục thể chất 🩹', body_vi = 'Cơ thể mẹ vẫn đang hồi phục, có thể vết khâu vẫn còn đau. Đừng đòi hỏi bản thân phải hoàn hảo.', title_zh = '身体恢复 🩹', body_zh = '你的身体还在恢复，伤口也许还在疼。别对自己要求完美。' WHERE id = 'd06a4b75-fad1-4ee5-9c5c-c70d98373c0c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
