UPDATE public.mommy_day_notifications SET title_es = '¡Somos un equipo! 💖', title_fr = 'Nous sommes une équipe ! 💖', title_hi = 'हम एक टीम हैं! 💖', title_id = 'Kita satu tim! 💖', title_ja = 'わたしたちはチームです！💖', title_ko = '우리는 한 팀이에요! 💖', title_nl = 'Wij zijn een team! 💖', title_pl = 'Jesteśmy drużyną! 💖', title_pt = 'Somos uma equipa! 💖', title_sv = 'Vi är ett lag! 💖', title_vi = 'Chúng mình là một đội! 💖', title_zh = '我们是一个团队！💖' WHERE id = '2ecd0a8e-2817-4551-98e0-4276739c7da9' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal los pañales del día? 🧷', body_es = 'La forma más fácil de saber si tu bebé come lo suficiente es el registro de cambios de pañal. ¡Anótalo ahora en la app!', title_fr = 'Combien de couches aujourd''hui ? 🧷', body_fr = 'Le moyen le plus simple de savoir si votre bébé mange assez, ce sont les notes de change. Saisissez-les maintenant dans l''application !', title_hi = 'रोज़ के डायपर कैसे हैं? 🧷', body_hi = 'बच्चे का पेट ठीक से भर रहा है, यह जानने का सबसे आसान तरीका डायपर बदलने का रिकॉर्ड है। अभी ऐप में दर्ज कीजिए!', title_id = 'Bagaimana popok hariannya? 🧷', body_id = 'Cara termudah mengetahui bayi cukup menyusu adalah catatan Ganti Popok. Masukkan ke aplikasi sekarang!', title_ja = '1日のおむつの様子はどうですか？🧷', body_ja = '赤ちゃんが十分に飲めているかを知るいちばんかんたんな方法は、おむつ替えの記録です。今すぐアプリに入力しましょう！', title_ko = '하루 기저귀 상태는 어떤가요? 🧷', body_ko = '아기가 충분히 먹는지 알 수 있는 가장 쉬운 방법은 기저귀 교체 기록이에요. 지금 앱에 입력하세요!', title_nl = 'Hoe zijn de luiers vandaag? 🧷', body_nl = 'De makkelijkste manier om te weten of je baby genoeg drinkt, zijn de verschoonnotities. Voer ze nu in de app in!', title_pl = 'Jak wyglądają dzienne pieluszki? 🧷', body_pl = 'Najprostszy sposób, by wiedzieć, czy dziecko się najada, to zapisy zmian pieluszek. Wpisz je teraz do aplikacji!', title_pt = 'Como estão as fraldas do dia? 🧷', body_pt = 'A forma mais fácil de saber se o bebé come o suficiente são os registos de mudas de fralda. Registe-as já na app!', title_sv = 'Hur ser blöjorna ut i dag? 🧷', body_sv = 'Det enklaste sättet att veta om barnet äter tillräckligt är anteckningarna om blöjbyten. Skriv in dem i appen nu!', title_vi = 'Số tã mỗi ngày thế nào? 🧷', body_vi = 'Cách dễ nhất để biết bé bú đủ là nhìn vào ghi chép Thay tã. Nhập vào ứng dụng ngay nhé!', title_zh = '每天的尿布情况怎么样？🧷', body_zh = '判断宝宝有没有吃饱，最简单的方法就是换尿布记录。现在就录入应用吧！' WHERE id = '70951e1d-e161-4f61-adb6-2b3b015c6f79' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Se acerca la primera sonrisa! 😊', body_es = 'No te pierdas los momentos en que te mira fijamente a la cara. Escribe en el Diario de ánimo lo que sientes en esos momentos.', title_fr = 'Le premier sourire approche ! 😊', body_fr = 'Ne manquez pas les moments où il regarde attentivement votre visage. Notez dans le Journal d''humeur les émotions qu''ils vous font vivre.', title_hi = 'पहली मुस्कान करीब है! 😊', body_hi = 'जब वह ध्यान से आपके चेहरे को देखे, वे पल मत चूकिए। इन पलों से जागी भावनाएँ मूड डायरी में लिखिए।', title_id = 'Senyum pertama segera datang! 😊', body_id = 'Jangan lewatkan saat ia menatap wajah Anda dengan saksama. Tuliskan emosi dari momen-momen ini di Buku Harian Suasana Hati.', title_ja = '初めての笑顔はもうすぐ！😊', body_ja = '赤ちゃんがママの顔をじっと見つめる瞬間を見逃さないで。そのとき感じた気持ちを「気分日記」に書きましょう。', title_ko = '첫 미소가 다가와요! 😊', body_ko = '아기가 엄마 얼굴을 가만히 바라보는 순간을 놓치지 마세요. 그때의 감정을 기분 일기에 적어 보세요.', title_nl = 'De eerste glimlach komt eraan! 😊', body_nl = 'Mis de momenten niet waarop je baby aandachtig naar je gezicht kijkt. Schrijf de emoties die ze je geven op in je Stemmingsdagboek.', title_pl = 'Zbliża się pierwszy uśmiech! 😊', body_pl = 'Nie przegap chwil, gdy uważnie przygląda się twojej twarzy. Zapisz w Dzienniku nastroju emocje, jakie w tobie budzą.', title_pt = 'O primeiro sorriso está a chegar! 😊', body_pt = 'Não perca os momentos em que ele olha atentamente para o seu rosto. Escreva no Diário de Humor o que estes momentos a fazem sentir.', title_sv = 'Det första leendet närmar sig! 😊', body_sv = 'Missa inte stunderna när barnet tittar uppmärksamt på ditt ansikte. Skriv ner känslorna de väcker i Humördagboken.', title_vi = 'Nụ cười đầu tiên sắp đến! 😊', body_vi = 'Đừng bỏ lỡ những lúc bé chăm chú nhìn mặt mẹ. Hãy viết những cảm xúc từ khoảnh khắc ấy vào Nhật ký tâm trạng.', title_zh = '第一个微笑快来了！😊', body_zh = '别错过宝宝专注地看着你的那些瞬间。把它们带给你的感受写进心情日记吧。' WHERE id = '9b230269-a517-40c2-a23b-f2bd57a211d4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Empezamos a crear una rutina! 🌙', body_es = 'Báñale, dale el pecho a la misma hora y pon el Ruido blanco junto con el temporizador de sueño.', title_fr = 'Nous commençons à créer une routine ! 🌙', body_fr = 'Donnez le bain et la tétée à la même heure, mettez les Bruits blancs et lancez le minuteur de sommeil.', title_hi = 'रूटीन बनाना शुरू करते हैं! 🌙', body_hi = 'रोज़ एक ही समय पर नहलाइए, दूध पिलाइए और व्हाइट नॉइज़ चलाकर स्लीप टाइमर शुरू कीजिए।', title_id = 'Kita mulai membangun rutinitas! 🌙', body_id = 'Mandikan, susui pada jam yang sama, nyalakan Suara Putih, lalu mulai pengatur waktu tidur.', title_ja = '生活リズムをつくりはじめましょう！🌙', body_ja = '毎日同じ時間にお風呂に入れて、授乳して、ホワイトノイズをかけながら睡眠タイマーをスタートしましょう。', title_ko = '루틴을 만들기 시작해요! 🌙', body_ko = '같은 시간에 목욕시키고 수유한 다음, 백색소음을 틀고 수면 타이머를 시작하세요.', title_nl = 'We beginnen met een vast ritme! 🌙', body_nl = 'Doe je baby op hetzelfde tijdstip in bad, geef de borst, zet Witte ruis aan en start de slaaptimer.', title_pl = 'Zaczynamy budować rutynę! 🌙', body_pl = 'Kąp i karm dziecko o tej samej porze, włącz Biały szum i uruchom timer snu.', title_pt = 'Vamos começar a criar uma rotina! 🌙', body_pt = 'Dê banho e mama à mesma hora todos os dias e ligue o temporizador de sono com o Ruído Branco.', title_sv = 'Vi börjar skapa en rutin! 🌙', body_sv = 'Bada, amma och starta sömntimern med Vitt brus på vid samma tid varje dag.', title_vi = 'Bắt đầu tạo nếp sinh hoạt! 🌙', body_vi = 'Hãy tắm, cho bú vào cùng một giờ, bật Tiếng ồn trắng và khởi động bộ hẹn giờ ngủ.', title_zh = '开始建立作息规律吧！🌙', body_zh = '每天在同一时间洗澡、喂奶，然后打开白噪音，启动睡眠计时器。' WHERE id = '6b6f1411-38ea-47b2-b82b-7ec0af1fa9ed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No olvides tus necesidades como mamá. 🛍', body_es = '️Usar crema para pezones y discos de lactancia te ayudará a sentirte más cómoda y protegida.', title_fr = 'N''oubliez pas vos besoins de maman. 🛍', body_fr = '️Une crème pour les mamelons et des coussinets d''allaitement vous apporteront plus de confort et de protection.', title_hi = 'माँ के रूप में अपनी ज़रूरतें मत भूलिए। 🛍', body_hi = '️निप्पल क्रीम और ब्रेस्ट पैड इस्तेमाल करने से आपको ज़्यादा आराम और सुरक्षा मिलेगी।', title_id = 'Jangan lupakan kebutuhan Anda sebagai ibu. 🛍', body_id = '️Menggunakan krem puting dan bantalan payudara akan membuat Anda lebih nyaman dan terlindungi.', title_ja = 'ママ自身に必要なものも忘れずに。🛍', body_ja = '️乳頭クリームや母乳パッドを使うと、より快適に過ごせて、肌も守られます。', title_ko = '엄마에게 필요한 것도 잊지 마세요. 🛍', body_ko = '️유두 크림과 수유 패드를 사용하면 더 편안하고 보호도 돼요.', title_nl = 'Vergeet je eigen behoeften als mama niet. 🛍', body_nl = '️Tepelcrème en zoogcompressen zorgen dat je je comfortabeler voelt en beschermd bent.', title_pl = 'Nie zapominaj o swoich potrzebach jako mamy. 🛍', body_pl = '️Krem na brodawki i wkładki laktacyjne zapewnią ci większy komfort i ochronę.', title_pt = 'Não se esqueça das suas necessidades de mãe. 🛍', body_pt = '️Usar creme para os mamilos e discos de amamentação vai ajudá-la a sentir-se mais confortável e protegida.', title_sv = 'Glöm inte dina egna behov som mamma. 🛍', body_sv = '️Bröstvårtskräm och amningsinlägg gör det bekvämare för dig och ger skydd.', title_vi = 'Đừng quên nhu cầu của mẹ. 🛍', body_vi = '️Kem bôi đầu ti và miếng lót thấm sữa sẽ giúp mẹ dễ chịu hơn và được bảo vệ.', title_zh = '别忘了妈妈自己的需要。🛍', body_zh = '️乳头霜和防溢乳垫能让你更舒适，也能起到保护作用。' WHERE id = 'b2ff3f80-95a8-44a7-96b9-573095f4b7ba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sorpresa del tiempo ⛅', title_fr = 'Surprise météo ⛅', title_hi = 'मौसम का सरप्राइज़ ⛅', title_id = 'Kejutan cuaca ⛅', title_ja = 'お天気サプライズ ⛅', title_ko = '날씨 서프라이즈 ⛅', title_nl = 'Weersverrassing ⛅', title_pl = 'Pogodowa niespodzianka ⛅', title_pt = 'Surpresa do tempo ⛅', title_sv = 'Väderöverraskning ⛅', title_vi = 'Bất ngờ thời tiết ⛅', title_zh = '天气惊喜 ⛅' WHERE id = 'b0e5435a-23a4-401e-a5a2-1b672694e080' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Época de salto de desarrollo! 📈', body_es = 'Tu bebé puede tener hambre más a menudo. Sigue el proceso controlando las tomas con el temporizador.', title_fr = 'Période de pic de croissance ! 📈', body_fr = 'Votre bébé peut avoir faim plus souvent. Suivez les tétées avec le minuteur du Suivi des repas.', title_hi = 'ग्रोथ स्पर्ट का दौर! 📈', body_hi = 'आपके बच्चे को बार-बार भूख लग सकती है। टाइमर और फ़ीडिंग ट्रैकर से प्रक्रिया पर नज़र रखिए।', title_id = 'Masa lonjakan pertumbuhan! 📈', body_id = 'Bayi Anda mungkin lebih sering lapar. Pantau prosesnya dengan pengatur waktu di Pemantau Menyusu.', title_ja = '成長のジャンプ期！📈', body_ja = '赤ちゃんがいつもより頻繁にお腹をすかせるかもしれません。タイマーで授乳を記録して見守りましょう。', title_ko = '성장 급등기예요! 📈', body_ko = '아기가 더 자주 배고파할 수 있어요. 타이머와 수유 기록으로 과정을 확인하세요.', title_nl = 'Tijd voor een groeisprong! 📈', body_nl = 'Je baby kan vaker honger hebben. Volg het met de timer in de Voedingstracker.', title_pl = 'Czas skoku rozwojowego! 📈', body_pl = 'Dziecko może częściej być głodne. Śledź karmienia timerem w narzędziu do śledzenia karmienia.', title_pt = 'Fase de pico de crescimento! 📈', body_pt = 'O bebé pode ter fome mais vezes. Acompanhe as mamadas com o temporizador do Registo de Alimentação.', title_sv = 'Utvecklingssprång! 📈', body_sv = 'Barnet kan bli hungrigt oftare. Följ förloppet genom att hålla koll på matningen med timern.', title_vi = 'Giai đoạn tăng trưởng vượt bậc! 📈', body_vi = 'Bé có thể đói thường xuyên hơn. Hãy theo dõi quá trình bằng bộ hẹn giờ trong Theo dõi cữ bú.', title_zh = '猛长期来了！📈', body_zh = '宝宝可能会更频繁地饿。用计时器和喂养记录追踪整个过程。' WHERE id = '1961895f-8e5d-4529-9dd1-eba3d3c72045' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Seguimos los pañales del día. 🧷', title_fr = 'Nous suivons les couches du jour. 🧷', title_hi = 'हम रोज़ के डायपर पर नज़र रख रहे हैं। 🧷', title_id = 'Kita pantau popok hariannya. 🧷', title_ja = '1日のおむつを記録しましょう。🧷', title_ko = '하루 기저귀를 기록해요. 🧷', title_nl = 'We houden de luiers per dag bij. 🧷', title_pl = 'Śledzimy dzienne pieluszki. 🧷', title_pt = 'Acompanhamos as fraldas do dia. 🧷', title_sv = 'Vi följer blöjorna varje dag. 🧷', title_vi = 'Theo dõi số tã hằng ngày. 🧷', title_zh = '记录每天的尿布情况。🧷' WHERE id = '9d58451e-ede3-4a05-ba21-dd4e0b7f4086' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Aumenta la inquietud por la tarde? 🎶', body_es = 'Pueden ser gases o cansancio. Cálmale con los sonidos de la naturaleza de la sección Ruido blanco.', title_fr = 'Plus d''agitation le soir ? 🎶', body_fr = 'Ce sont peut-être des coliques ou de la fatigue. Apaisez-le avec les sons de la nature de la rubrique Bruits blancs.', title_hi = 'शाम की बेचैनी बढ़ रही है? 🎶', body_hi = 'यह गैस का दर्द या थकान हो सकती है। व्हाइट नॉइज़ सेक्शन की प्रकृति की आवाज़ों से उसे शांत कीजिए।', title_id = 'Rewel di sore hari bertambah? 🎶', body_id = 'Bisa jadi karena kolik atau lelah. Tenangkan ia dengan suara alam dari bagian Suara Putih.', title_ja = '夕方のぐずりが増えていますか？🎶', body_ja = 'おなかのガスや疲れかもしれません。「ホワイトノイズ」の自然の音で落ち着かせてあげましょう。', title_ko = '저녁에 보채는 일이 늘었나요? 🎶', body_ko = '가스 배앓이나 피곤함일 수 있어요. 백색소음 섹션의 자연의 소리로 아기를 달래 주세요.', title_nl = 'Meer onrust in de avond? 🎶', body_nl = 'Het kunnen krampjes of vermoeidheid zijn. Kalmeer je baby met de natuurgeluiden in het onderdeel Witte ruis.', title_pl = 'Wieczorem więcej marudzenia? 🎶', body_pl = 'To mogą być kolki lub zmęczenie. Uspokój dziecko odgłosami natury z sekcji Biały szum.', title_pt = 'A agitação ao fim do dia está a aumentar? 🎶', body_pt = 'Podem ser cólicas ou cansaço. Acalme o bebé com os sons da natureza da secção Ruído Branco.', title_sv = 'Ökar oron på kvällarna? 🎶', body_sv = 'Det kan vara gasknip eller trötthet. Lugna barnet med naturljuden i avsnittet Vitt brus.', title_vi = 'Bé hay quấy buổi tối hơn? 🎶', body_vi = 'Có thể do đầy hơi hoặc mệt. Hãy dỗ bé bằng âm thanh thiên nhiên trong mục Tiếng ồn trắng.', title_zh = '傍晚哭闹变多了？🎶', body_zh = '可能是胀气或疲倦。用白噪音板块里的大自然声音安抚宝宝吧。' WHERE id = '2450c51d-55f8-4e27-b691-cd2f503d7dd4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
