UPDATE public.mommy_day_notifications SET title_es = '¡Después del baño de la tarde, a dormir! 🛁', body_es = 'Bañar a tu bebé antes de dormir por la noche le ayuda mucho a conciliar el sueño.', title_fr = 'Après le bain du soir, au lit ! 🛁', body_fr = 'Donner le bain avant la nuit aide beaucoup votre bébé à s''endormir paisiblement.', title_hi = 'शाम के स्नान के बाद सोने का समय! 🛁', body_hi = 'बच्चा आराम से सो सके, इसके लिए रात की नींद से पहले नहलाना बहुत फ़ायदेमंद है।', title_id = 'Setelah mandi sore, waktunya tidur! 🛁', body_id = 'Memandikan bayi sebelum tidur malam sangat bermanfaat agar ia tidur nyenyak.', title_ja = '夜のお風呂のあとはねんねの時間！🛁', body_ja = '夜の睡眠の前にお風呂に入れると、赤ちゃんがぐっすり眠りやすくなります。', title_ko = '저녁 목욕 후엔 잠잘 시간! 🛁', body_ko = '아기가 편안하게 잠들도록 밤잠 전에 목욕시키면 아주 좋아요.', title_nl = 'Na het avondbadje is het bedtijd! 🛁', body_nl = 'Je baby in bad doen voor de nachtrust helpt hem rustig in slaap te vallen.', title_pl = 'Po wieczornej kąpieli czas spać! 🛁', body_pl = 'Kąpiel przed nocnym snem bardzo pomaga dziecku spokojnie zasnąć.', title_pt = 'Depois do banho da noite, hora de dormir! 🛁', body_pt = 'Dar banho ao bebé antes do sono da noite ajuda muito a que adormeça tranquilo.', title_sv = 'Läggdags efter kvällsbadet! 🛁', body_sv = 'För att barnet ska somna lugnt är det väldigt bra att bada det före nattsömnen.', title_vi = 'Sau giờ tắm tối là giờ đi ngủ! 🛁', body_vi = 'Tắm cho bé trước giấc ngủ đêm rất có ích để bé dễ ngủ ngon.', title_zh = '晚上洗完澡就该睡觉啦！🛁', body_zh = '睡前给宝宝洗个澡，非常有助于宝宝安稳入睡。' WHERE id = '7797557a-9277-450c-98b3-b0fa58923513' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Involucramos también a los papás! 👨‍🍼', body_es = 'Con el Modo pareja, los papás también pueden estar al tanto del desarrollo del bebé.', title_fr = 'On implique aussi les papas ! 👨‍🍼', body_fr = 'Grâce au mode Partenaire, les papas peuvent eux aussi suivre le développement de bébé.', title_hi = 'पापा को भी शामिल करते हैं! 👨‍🍼', body_hi = 'पार्टनर मोड से पापा भी बच्चे के विकास की जानकारी पा सकते हैं।', title_id = 'Kita libatkan para ayah juga! 👨‍🍼', body_id = 'Lewat mode Pasangan, para ayah juga bisa mengikuti perkembangan bayi.', title_ja = 'パパにも参加してもらいましょう！👨‍🍼', body_ja = 'パートナーモードで、パパも赤ちゃんの成長を知ることができます。', title_ko = '아빠도 함께해요! 👨‍🍼', body_ko = '파트너 모드로 아빠도 아기의 성장 소식을 받아 볼 수 있어요.', title_nl = 'We betrekken papa’s er ook bij! 👨‍🍼', body_nl = 'Met de Partnermodus kunnen papa’s ook de ontwikkeling van de baby volgen.', title_pl = 'Angażujemy też tatusiów! 👨‍🍼', body_pl = 'Dzięki trybowi Partnera tata też może śledzić rozwój dziecka.', title_pt = 'Vamos envolver também os pais! 👨‍🍼', body_pt = 'Com o Modo Parceiro, os pais também podem acompanhar o desenvolvimento do bebé.', title_sv = 'Vi tar med papporna också! 👨‍🍼', body_sv = 'Med Partnerläget kan även pappor hålla sig uppdaterade om barnets utveckling.', title_vi = 'Cùng rủ bố tham gia! 👨‍🍼', body_vi = 'Với Chế độ đối tác, bố cũng có thể cập nhật sự phát triển của bé.', title_zh = '让爸爸也参与进来！👨‍🍼', body_zh = '通过伴侣模式，爸爸也能随时了解宝宝的成长。' WHERE id = '8152dc55-7f72-41b2-bb12-02cf7745f75a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND