UPDATE public.mommy_day_notifications SET title_es = 'La base del sueño ⏱️', title_fr = 'Les bases du sommeil ⏱️', title_hi = 'नींद की नींव ⏱️', title_id = 'Fondasi tidur ⏱️', title_ja = '睡眠の土台 ⏱️', title_ko = '수면의 기초 ⏱️', title_nl = 'De basis van goede slaap ⏱️', title_pl = 'Fundament snu ⏱️', title_pt = 'A base do sono ⏱️', title_sv = 'Grunden för sömnen ⏱️', title_vi = 'Nền tảng giấc ngủ ⏱️', title_zh = '睡眠基础 ⏱️' WHERE id = '21fef948-0fab-41a2-932d-5efc89cc4b78' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Todo va bien ✔️', body_es = 'A veces piensas que no consigues hacer nada. Pero mira su ropa limpia y su barriguita llena. ¡Lo estás haciendo de maravilla!', title_fr = 'Tout va bien ✔️', body_fr = 'Parfois, vous avez l''impression de n''arriver à rien. Mais regardez ses vêtements propres et son ventre rassasié. Vous faites un travail parfait !', title_hi = 'सब ठीक है ✔️', body_hi = 'कभी-कभी लगता है कि आप कुछ नहीं कर पा रहीं। पर उसके साफ़ कपड़े और भरा पेट देखिए। आप बेहतरीन काम कर रही हैं!', title_id = 'Semuanya baik-baik saja ✔️', body_id = 'Terkadang Anda merasa tidak bisa melakukan apa-apa. Tapi lihatlah bajunya yang bersih dan perutnya yang kenyang. Anda melakukannya dengan sempurna!', title_ja = 'すべて順調です ✔️', body_ja = '何もできていないと思うときもあるでしょう。でも、赤ちゃんの清潔な服と、満たされたお腹を見てください。あなたは完璧にやっています！', title_ko = '모든 게 괜찮아요 ✔️', body_ko = '가끔 아무것도 해내지 못한 것 같나요? 하지만 아기의 깨끗한 옷과 부른 배를 보세요. 엄마는 완벽하게 해내고 있어요!', title_nl = 'Alles is in orde ✔️', body_nl = 'Soms denk je dat je niets voor elkaar krijgt. Maar kijk naar die schone kleertjes en dat volle buikje. Je doet het perfect!', title_pl = 'Wszystko jest w porządku ✔️', body_pl = 'Czasem myślisz, że nic ci się nie udaje. Ale spójrz na jego czyste ubranko i pełny brzuszek. Świetnie sobie radzisz!', title_pt = 'Está tudo bem ✔️', body_pt = 'Às vezes acha que não consegue fazer nada. Mas olhe para a roupa limpa dele e para a barriguinha cheia. Está a fazer um trabalho perfeito!', title_sv = 'Allt är som det ska ✔️', body_sv = 'Ibland tror du att du inte får något gjort. Men titta på barnets rena kläder och mätta mage. Du gör ett perfekt jobb!', title_vi = 'Mọi thứ đều ổn ✔️', body_vi = 'Đôi khi mẹ nghĩ mình chẳng làm được gì. Nhưng hãy nhìn bộ đồ sạch sẽ và chiếc bụng no tròn của bé. Mẹ đang làm tuyệt vời lắm!', title_zh = '一切都很好 ✔️', body_zh = '有时你会觉得自己什么都没做好。可是看看宝宝干净的衣服、吃饱的小肚子。你做得非常棒！' WHERE id = '76b44761-7bef-4f9c-b984-97e78f4d78cb' AND coalesce(title_es,'') = '' AND coalesce(body