UPDATE public.mommy_day_notifications SET title_es = 'Hora de salir 🌳', title_fr = 'L''heure de sortir 🌳', title_hi = 'बाहर निकलने का समय 🌳', title_id = 'Waktunya keluar rumah 🌳', title_ja = 'おでかけの時間 🌳', title_ko = '외출 시간 🌳', title_nl = 'Tijd om naar buiten te gaan 🌳', title_pl = 'Czas na wyjście 🌳', title_pt = 'Hora de sair 🌳', title_sv = 'Dags att gå ut 🌳', title_vi = 'Đến giờ ra ngoài 🌳', title_zh = '该出门了 🌳' WHERE id = '83caf542-3e86-4833-b9bd-0befb15b04d7' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El héroe de la noche 🦸‍♂️', body_es = '¿Estás agotada de los despertares nocturnos? No dudes en despertar a papá. Ser un equipo significa repartir la carga a partes iguales.', title_fr = 'Le héros de la nuit 🦸‍♂️', body_fr = 'Les réveils nocturnes vous épuisent ? N''hésitez pas à réveiller Papa. Être une équipe, c''est partager la charge équitablement.', title_hi = 'रात के हीरो 🦸‍♂️', body_hi = 'रात में बार-बार जागने से थक गईं? पापा को जगाने में संकोच मत कीजिए। टीम होने का मतलब है बोझ बराबर बाँटना।', title_id = 'Pahlawan malam 🦸‍♂️', body_id = 'Lelah dengan bangun malam? Jangan ragu membangunkan Ayah. Menjadi satu tim berarti berbagi beban secara adil.', title_ja = '夜のヒーロー 🦸‍♂️', body_ja = '夜中の目覚めに疲れていますか？パパを起こすことをためらわないで。チームとは、負担を平等に分け合うことです。', title_ko = '밤의 영웅 🦸‍♂️', body_ko = '밤중에 깨는 데 지쳤나요? 아빠를 깨우는 걸 망설이지 마세요. 팀이 된다는 건 짐을 똑같이 나누는 거예요.', title_nl = 'De held van de nacht 🦸‍♂️', body_nl = 'Moe van het nachtelijk wakker worden? Maak papa gerust wakker. Een team zijn betekent de last eerlijk verdelen.', title_pl = 'Bohater nocy 🦸‍♂️', body_pl = 'Męczą cię nocne pobudki? Nie wahaj się budzić taty. Bycie drużyną oznacza równy podział obowiązków.', title_pt = 'O herói da noite 🦸‍♂️', body_pt = 'Está cansada dos despertares noturnos? Não hesite em acordar o pai. Ser uma equipa significa dividir o peso por igual.', title_sv = 'Nattens hjälte 🦸‍♂️', body_sv = 'Är du trött på de nattliga uppvaknandena? Tveka inte att väcka pappa. Att vara ett lag betyder att dela bördan lika.', title_vi = 'Người hùng ban đêm 🦸‍♂️', body_vi = 'Mẹ mệt vì thức đêm? Đừng ngại đánh thức bố. Là một đội nghĩa là chia đều gánh nặng.', title_zh = '夜晚的英雄 🦸‍♂️', body_zh = '被夜醒折腾得筋疲力尽？别犹豫，叫醒爸爸。一个团队就意味着平分重担。' WHERE id = 'fca627d6-9c72-4d82-999a-3b13347100cd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Preparación para un sueño profundo 🛀', body_es = 'Un baño tibio, un masaje suave y la habitación a oscuras... Mantener la rutina de sueño es el secreto de las noches sin interrupciones.', title_fr = 'Préparation à un sommeil profond 🛀', body_fr = 'Un bain tiède, un massage doux et une chambre plongée dans le noir... Préserver la routine du coucher est le secret des nuits sans interruption.', title_hi = 'गहरी नींद की तैयारी 🛀', body_hi = 'गुनगुना स्नान, हल्की मालिश और कमरे में अँधेरा... नींद का रूटीन बनाए रखना बिना रुकावट वाली रातों का राज़ है।', title_id = 'Persiapan tidur nyenyak 🛀', body_id = 'Mandi air hangat, pijatan lembut, dan kamar yang digelapkan... Menjaga rutinitas tidur adalah rahasia malam tanpa terputus.', title_ja = '深い眠りの準備 🛀', body_ja = 'ぬるめのお風呂、やさしいマッサージ、暗くした部屋...睡眠のルーティンを守ることが、朝までぐっすりのひみつです。', title_ko = '깊은 잠 준비 🛀', body_ko = '따뜻한 목욕, 부드러운 마사지, 어두운 방... 수면 루틴을 지키는 것이 깨지 않는 밤의 비결이에요.', title_nl = 'Klaar voor een diepe slaap 🛀', body_nl = 'Een warm badje, een zachte massage en een donkere kamer... Een vast slaapritueel is het geheim van ongestoorde nachten.', title_pl = 'Przygotowanie do głębokiego snu 🛀', body_pl = 'Ciepła kąpiel, delikatny masaż i zaciemniony pokój... Trzymanie się rutyny snu to sekret nieprzerwanych nocy.', title_pt = 'Preparação para um sono profundo 🛀', body_pt = 'Um banho morno, uma massagem suave e o quarto às escuras... Manter a rotina do sono é o segredo de noites sem interrupções.', title_sv = 'Förberedelser för djup sömn 🛀', body_sv = 'Ett ljummet bad, en mjuk massage och ett mörklagt rum... Att hålla fast vid sömnrutinen är hemligheten bakom ostörda nätter.', title_vi = 'Chuẩn bị cho giấc ngủ sâu 🛀', body_vi = 'Tắm nước ấm, xoa bóp nhẹ nhàng và làm tối phòng... Giữ nếp ngủ là bí quyết cho những đêm ngủ trọn giấc.', title_zh = '为深度睡眠做准备 🛀', body_zh = '温水澡、轻柔按摩、调暗房间……坚持睡前程序是整夜安睡的秘诀。' WHERE id = '8d02cce6-aec5-439c-aadf-52670f1abd08' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
