UPDATE public.mommy_day_notifications SET title_es = 'Una voz que calma 📖', title_fr = 'Une voix apaisante 📖', title_hi = 'शांत करने वाली आवाज़ 📖', title_id = 'Suara yang menenangkan 📖', title_ja = '心落ち着く声 📖', title_ko = '마음을 달래는 목소리 📖', title_nl = 'Een rustgevende stem 📖', title_pl = 'Kojący głos 📖', title_pt = 'Uma voz calmante 📖', title_sv = 'Lugnande röst 📖', title_vi = 'Âm thanh xoa dịu 📖', title_zh = '安抚的声音 📖' WHERE id = 'f25f7637-e945-4232-a1c1-f7594c81a0b3' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Señales de sueño 🥱', body_es = 'No esperes a que se frote los ojos y bostece. En cuanto su mirada se quede fija, pasa enseguida a la rutina de sueño.', title_fr = 'Les signaux du sommeil 🥱', body_fr = 'N''attendez pas qu''il se frotte les yeux et bâille. Dès que son regard devient fixe, commencez la routine du coucher.', title_hi = 'नींद के संकेत 🥱', body_hi = 'आँखें मलने और जम्हाई लेने का इंतज़ार मत कीजिए। जैसे ही उसकी नज़र सुस्त हो, तुरंत नींद का रूटीन शुरू कीजिए।', title_id = 'Tanda-tanda mengantuk 🥱', body_id = 'Jangan tunggu ia mengucek mata dan menguap. Begitu tatapannya mulai kosong, segera mulai rutinitas tidur.', title_ja = '眠いサイン 🥱', body_ja = '目をこすったりあくびをしたりするのを待たないで。視線がぼんやりしてきたら、すぐに寝かしつけのルーティンに移りましょう。', title_ko = '졸음 신호 🥱', body_ko = '눈을 비비고 하품할 때까지 기다리지 마세요. 시선이 멍해지면 바로 수면 루틴을 시작하세요.', title_nl = 'Slaapsignalen 🥱', body_nl = 'Wacht niet tot je baby in de ogen wrijft en gaapt. Zodra de blik wazig wordt, begin je meteen met het slaapritueel.', title_pl = 'Sygnały senności 🥱', body_pl = 'Nie czekaj, aż zacznie przecierać oczy i ziewać. Gdy tylko jego wzrok się zamgli, od razu zacznij rutynę przed snem.', title_pt = 'Sinais de sono 🥱', body_pt = 'Não espere que esfregue os olhos e boceje. Mal o olhar fique parado, passe logo à rotina do sono.', title_sv = 'Sömnsignaler 🥱', body_sv = 'Vänta inte tills barnet gnuggar ögonen och gäspar. Så fort blicken blir matt, gå direkt över till sömnrutinen.', title_vi = 'Tín hiệu buồn ngủ 🥱', body_vi = 'Đừng đợi bé dụi mắt và ngáp. Vừa thấy ánh mắt bé lờ đờ, hãy chuyển ngay sang nếp ngủ.', title_zh = '犯困信号 🥱', body_zh = '别等到宝宝揉眼睛、打哈欠。一看到宝宝眼神发直，就马上开始睡前程序。' WHERE id = '2a37fc3a-8b98-420a-99ba-c491a8c0f435' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '10 minutos para mamá ☕', title_fr = '10 minutes pour maman ☕', title_hi = 'माँ के लिए 10 मिनट ☕', title_id = '10 menit untuk ibu ☕', title_ja = 'ママのための10分 ☕', title_ko = '엄마를 위한 10분 ☕', title_nl = '10 minuten voor mama ☕', title_pl = '10 minut dla mamy ☕', title_pt = '10 minutos para a mãe ☕', title_sv = '10 minuter för mamma ☕', title_vi = '10 phút cho mẹ ☕', title_zh = '妈妈的10分钟 ☕' WHERE id = '74e14338-c8e1-4b5c-b426-24332f30b919' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hay cosas del bebé por toda la casa? Que las haya. Una casa desordenada no demuestra que seas mala madre, sino que tu prioridad es tu bebé.', body_fr = 'Des affaires de bébé partout dans la maison ? Laissez-les. Une maison en désordre ne montre pas que vous êtes une mauvaise mère, mais que votre priorité, c''est votre bébé.', body_hi = 'घर में हर जगह बच्चे की चीज़ें हैं? रहने दीजिए। बिखरा घर यह नहीं दिखाता कि आप बुरी माँ हैं, बल्कि यह कि आपकी प्राथमिकता आपका बच्चा है।', body_id = 'Barang-barang anak ada di seluruh rumah? Biarkan saja. Rumah yang berantakan bukan berarti Anda ibu yang buruk, melainkan tanda bahwa bayi Anda adalah prioritas.', body_ja = '家じゅうに赤ちゃんのものが散らばっている？そのままでいいのです。散らかった家は、あなたがダメなママだという証拠ではなく、赤ちゃんを最優先にしているという証です。', body_ko = '집 안 곳곳에 아기 물건이 있나요? 그냥 두세요. 어질러진 집은 나쁜 엄마라는 뜻이 아니라 아기가 우선이라는 뜻이에요.', body_nl = 'Ligt er overal in huis babyspul? Laat maar liggen. Een rommelig huis laat niet zien dat je een slechte moeder bent, maar dat je baby je prioriteit is.', body_pl = 'W całym domu leżą dziecięce rzeczy? Niech leżą. Bałagan w domu nie świadczy o tym, że jesteś złą mamą, tylko o tym, że twoim priorytetem jest dziecko.', body_pt = 'Há coisas do bebé por toda a casa? Deixe estar. Uma casa desarrumada não mostra que é má mãe, mostra que a sua prioridade é o bebé.', body_sv = 'Ligger det barnsaker överallt hemma? Låt dem ligga. Ett stökigt hem visar inte att du är en dålig mamma, utan att ditt barn kommer i första hand.', body_vi = 'Đồ của bé ở khắp mọi nơi trong nhà? Cứ để vậy. Nhà bừa bộn không có nghĩa mẹ là người mẹ tồi, mà cho thấy ưu tiên của mẹ là bé.', body_zh = '家里到处都是宝宝的东西？随它去吧。乱糟糟的家不说明你是个坏妈妈，只说明宝宝是你的头等大事。' WHERE id = '746b1115-b7ff-4fd7-b04a-46935d1a6f43' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de sonidos contra la inquietud. 🎶', title_fr = 'Une thérapie sonore contre l''agitation. 🎶', title_hi = 'बेचैनी के लिए साउंड थेरेपी। 🎶', title_id = 'Terapi suara untuk rewel. 🎶', title_ja = 'ぐずりに効くサウンドセラピー。🎶', title_ko = '보챌 때 소리 테라피. 🎶', title_nl = 'Geluidstherapie tegen onrust. 🎶', title_pl = 'Terapia dźwiękiem na niepokój. 🎶', title_pt = 'Terapia de sons contra a agitação. 🎶', title_sv = 'Ljudterapi mot oro. 🎶', title_vi = 'Liệu pháp âm thanh xoa dịu bé quấy. 🎶', title_zh = '缓解不安的声音疗法。🎶' WHERE id = 'bc99d2a9-e4a6-4af7-937f-bb0a7a91d292' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rutina de tomas puede cambiar. 🍼', body_es = 'Para seguir el apetito de tu bebé, pon en marcha el temporizador de Anacan y revisa lo normal para cada día.', title_fr = 'Le rythme des repas peut changer. 🍼', body_fr = 'Pour suivre l''appétit de votre bébé, lancez le minuteur Anacan et vérifiez la norme quotidienne.', title_hi = 'फ़ीडिंग का रूटीन बदल सकता है। 🍼', body_hi = 'बच्चे की भूख पर नज़र रखने के लिए Anacan टाइमर चालू कीजिए और रोज़ का मानक जाँचिए।', title_id = 'Pola menyusu bisa berubah. 🍼', body_id = 'Untuk memantau nafsu makan bayi, nyalakan pengatur waktu Anacan dan cek angka hariannya.', title_ja = '授乳のリズムが変わることがあります。🍼', body_ja = '赤ちゃんの食欲を見守るために、Anacanのタイマーをオンにして1日の目安をチェックしましょう。', title_ko = '수유 패턴이 바뀔 수 있어요. 🍼', body_ko = '아기의 식욕을 확인하려면 Anacan 타이머를 켜고 하루 기준치를 확인하세요.', title_nl = 'Het voedingsritme kan veranderen. 🍼', body_nl = 'Zet de Anacan-timer aan om de eetlust van je baby te volgen en bekijk de dagelijkse norm.', title_pl = 'Rytm karmienia może się zmienić. 🍼', body_pl = 'Aby śledzić apetyt dziecka, włącz timer Anacan i sprawdź dzienną normę.', title_pt = 'A rotina de alimentação pode mudar. 🍼', body_pt = 'Para acompanhar o apetite do bebé, ligue o temporizador do Anacan e verifique a quantidade diária recomendada.', title_sv = 'Matningsrutinen kan ändras. 🍼', body_sv = 'Starta Anacan-timern för att följa barnets aptit och kolla den dagliga normen.', title_vi = 'Lịch bú có thể thay đổi. 🍼', body_vi = 'Để theo dõi sự thèm ăn của bé, hãy bật bộ hẹn giờ của Anacan và kiểm tra định mức hằng ngày.', title_zh = '喂养规律可能会变化。🍼', body_zh = '想了解宝宝的胃口，就打开Anacan计时器，查看每日参考量。' WHERE id = 'c5b12eaa-4012-417b-bf89-d5bd9d26aee9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Seguimos los pañales del día. 🧷', body_es = 'Para asegurarte de que tu bebé come lo suficiente, sigue anotando cada cambio de pañal en Anacan.', title_fr = 'Nous suivons les couches du jour. 🧷', body_fr = 'Pour vous assurer que bébé mange assez, continuez à noter chaque change dans Anacan.', title_hi = 'हम रोज़ के डायपर पर नज़र रख रहे हैं। 🧷', body_hi = 'बच्चे का पेट ठीक से भर रहा है, यह पक्का करने के लिए Anacan में हर डायपर बदलना दर्ज करते रहिए।', title_id = 'Kita pantau popok hariannya. 🧷', body_id = 'Untuk memastikan bayi cukup menyusu, terus catat setiap ganti popok di Anacan.', title_ja = '1日のおむつを記録しましょう。🧷', body_ja = '赤ちゃんが十分に栄養をとれているか確かめるために、おむつ替えのたびにAnacanに記録し続けましょう。', title_ko = '하루 기저귀를 기록해요. 🧷', body_ko = '아기가 충분히 먹는지 확인하려면 기저귀를 갈 때마다 Anacan에 계속 기록하세요.', title_nl = 'We houden de luiers per dag bij. 🧷', body_nl = 'Blijf elke verschoning in Anacan noteren, zodat je zeker weet dat je baby genoeg binnenkrijgt.', title_pl = 'Śledzimy dzienne pieluszki. 🧷', body_pl = 'Aby mieć pewność, że dziecko się najada, dalej zapisuj w Anacan każdą zmianę pieluszki.', title_pt = 'Acompanhamos as fraldas do dia. 🧷', body_pt = 'Para ter a certeza de que o bebé está bem alimentado, continue a registar cada muda de fralda no Anacan.', title_sv = 'Vi följer blöjorna varje dag. 🧷', body_sv = 'Fortsätt anteckna varje blöjbyte i Anacan för att vara säker på att barnet får tillräckligt med mat.', title_vi = 'Theo dõi số tã hằng ngày. 🧷', body_vi = 'Để chắc chắn bé bú đủ, hãy tiếp tục ghi lại mỗi lần thay tã trong Anacan.', title_zh = '记录每天的尿布情况。🧷', body_zh = '为了确认宝宝吃得够，继续在Anacan里记录每一次换尿布。' WHERE id = '24927359-7877-4f99-9dea-0460583a0880' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Ya hemos empezado el 2.º mes! 🎊', body_es = 'Para apoyar el desarrollo de tu bebé, háblale a lo largo del día.', title_fr = 'Nous entrons déjà dans le 2e mois ! 🎊', body_fr = 'Pour soutenir le développement de votre bébé, parlez-lui tout au long de la journée.', title_hi = 'हम दूसरे महीने में आ गए! 🎊', body_hi = 'बच्चे के विकास में मदद के लिए दिन भर उससे बात कीजिए।', title_id = 'Kita sudah memasuki bulan ke-2! 🎊', body_id = 'Untuk mendukung perkembangannya, ajak bayi Anda bicara sepanjang hari.', title_ja = '2か月目に入りました！🎊', body_ja = '赤ちゃんの発達をサポートするために、1日を通して話しかけてあげましょう。', title_ko = '벌써 2개월째에 들어섰어요! 🎊', body_ko = '아기의 발달을 도우려면 하루 종일 아기에게 말을 걸어 주세요.', title_nl = 'We zijn in de 2e maand! 🎊', body_nl = 'Praat de hele dag met je baby om de ontwikkeling te ondersteunen.', title_pl = 'Wkroczyliśmy w 2. miesiąc! 🎊', body_pl = 'Aby wspierać rozwój dziecka, rozmawiaj z nim w ciągu dnia.', title_pt = 'Já entrámos no 2.º mês! 🎊', body_pt = 'Para apoiar o desenvolvimento do bebé, fale com ele ao longo do dia.', title_sv = 'Nu har vi klivit in i månad 2! 🎊', body_sv = 'Prata med barnet under dagen för att stödja dess utveckling.', title_vi = 'Chúng mình đã bước sang tháng thứ 2! 🎊', body_vi = 'Để hỗ trợ bé phát triển, hãy trò chuyện với bé suốt cả ngày.', title_zh = '我们进入第2个月啦！🎊', body_zh = '为了促进宝宝的发育，白天多和宝宝说说话。' WHERE id = '5366cee2-8491-4a45-8d5c-88d78aa6eee0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Alimentos que favorecen tu leche. 🍲', body_es = 'Prémiate con sopas y bebidas que favorecen la leche de la sección Recetas saludables para mujeres.', title_fr = 'Des aliments qui soutiennent la lactation. 🍲', body_fr = 'Faites-vous plaisir avec les soupes et boissons favorisant la lactation de la rubrique Recettes saines pour femmes.', title_hi = 'दूध में मदद करने वाले खाने। 🍲', body_hi = 'महिलाओं के लिए सेहतमंद रेसिपी सेक्शन के दूध बढ़ाने वाले सूप और पेय से खुद को इनाम दीजिए।', title_id = 'Makanan yang mendukung ASI Anda. 🍲', body_id = 'Hadiahi diri Anda dengan sup dan minuman pelancar ASI dari bagian Resep Sehat untuk wanita.', title_ja = '母乳をサポートする食べ物。🍲', body_ja = '「女性のためのヘルシーレシピ」から、母乳の出を助けるスープやドリンクで自分にごほうびを。', title_ko = '모유를 도와주는 음식. 🍲', body_ko = '여성을 위한 건강한 레시피 섹션의 모유를 늘려 주는 수프와 음료로 스스로에게 상을 주세요.', title_nl = 'Voeding die je melkproductie ondersteunt. 🍲', body_nl = 'Beloon jezelf met soepen en drankjes die de melkproductie stimuleren uit Gezonde recepten voor vrouwen.', title_pl = 'Produkty wspierające laktację. 🍲', body_pl = 'Nagródź się zupami i napojami wspierającymi laktację z sekcji Zdrowe przepisy dla kobiet.', title_pt = 'Alimentos que ajudam a produção de leite. 🍲', body_pt = 'Mime-se com as sopas e bebidas que aumentam o leite da secção Receitas Saudáveis para Mulheres.', title_sv = 'Mat som stödjer din mjölk. 🍲', body_sv = 'Belöna dig med mjölkökande soppor och drycker från avsnittet Hälsosamma recept för kvinnor.', title_vi = 'Thực phẩm hỗ trợ nguồn sữa. 🍲', body_vi = 'Hãy tự thưởng cho mình các món súp và đồ uống lợi sữa trong mục Công thức lành mạnh cho phụ nữ.', title_zh = '支持奶水的食物。🍲', body_zh = '用女性健康食谱板块里的催奶汤和饮品犒劳自己吧。' WHERE id = '48e4fdbb-6f6b-4c2d-90c9-ebe6d10f8179' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Es importante conocer las horas de sueño recomendadas. ⏱️', body_es = 'Cuando duerma, pon el temporizador de sueño y comprueba si cumple con sus horas de sueño diarias.', title_fr = 'Connaître les normes de sommeil est important. ⏱️', body_fr = 'Quand il dort, lancez le minuteur de sommeil et voyez s''il respecte la norme de sommeil quotidienne.', title_hi = 'नींद के मानक जानना ज़रूरी है। ⏱️', body_hi = 'वह सोए, तो स्लीप टाइमर चालू कीजिए और देखिए कि वह रोज़ की नींद का मानक पूरा कर रहा है या नहीं।', title_id = 'Penting memahami kebutuhan tidur. ⏱️', body_id = 'Saat ia tidur, nyalakan pengatur waktu tidur dan lihat apakah ia memenuhi kebutuhan tidur hariannya.', title_ja = '睡眠の目安を知ることは大切です。⏱️', body_ja = '赤ちゃんが眠ったら睡眠タイマーをオンにして、1日の睡眠の目安を満たしているか確認しましょう。', title_ko = '수면 기준치를 아는 게 중요해요. ⏱️', body_ko = '아기가 잘 때 수면 타이머를 켜고 하루 수면 기준치를 지키고 있는지 확인하세요.', title_nl = 'Het is belangrijk om de slaapnormen te kennen. ⏱️', body_nl = 'Zet de slaaptimer aan als je baby slaapt en kijk of de dagelijkse slaapnorm wordt gehaald.', title_pl = 'Warto znać normy snu. ⏱️', body_pl = 'Gdy dziecko śpi, włącz timer snu i zobacz, czy trzyma się dziennej normy.', title_pt = 'É importante conhecer as horas de sono recomendadas. ⏱️', body_pt = 'Quando ele dormir, ligue o temporizador de sono e veja se cumpre as horas de sono diárias recomendadas.', title_sv = 'Det är viktigt att känna till sömnnormerna. ⏱️', body_sv = 'Starta sömntimern när barnet sover och se om det når sin dagliga sömnnorm.', title_vi = 'Hiểu định mức giấc ngủ rất quan trọng. ⏱️', body_vi = 'Khi bé ngủ, hãy bật bộ hẹn giờ ngủ và xem bé có đáp ứng định mức ngủ hằng ngày không.', title_zh = '了解睡眠参考量很重要。⏱️', body_zh = '宝宝睡觉时打开睡眠计时器，看看是否达到了每日睡眠参考量。' WHERE id = '1a8980b4-ba5e-4179-adce-580423431a55' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
