UPDATE public.mommy_day_notifications SET title_es = 'Comparte tu experiencia 💬', title_fr = 'Partage d''expériences 💬', title_hi = 'अनुभव बाँटिए 💬', title_id = 'Berbagi pengalaman 💬', title_ja = '体験をシェアしよう 💬', title_ko = '경험 나누기 💬', title_nl = 'Ervaringen delen 💬', title_pl = 'Dzielenie się doświadczeniem 💬', title_pt = 'Partilha de experiências 💬', title_sv = 'Dela erfarenheter 💬', title_vi = 'Chia sẻ trải nghiệm 💬', title_zh = '分享经验 💬' WHERE id = '7405692f-45e1-45fa-9dd9-b527045b5e7d' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de salir 🌳', title_fr = 'L''heure de sortir 🌳', title_hi = 'बाहर निकलने का समय 🌳', title_id = 'Waktunya keluar rumah 🌳', title_ja = 'おでかけの時間 🌳', title_ko = '외출 시간 🌳', title_nl = 'Tijd om naar buiten te gaan 🌳', title_pl = 'Czas na wyjście 🌳', title_pt = 'Hora de sair 🌳', title_sv = 'Dags att gå ut 🌳', title_vi = 'Đến giờ ra ngoài 🌳', title_zh = '该出门了 🌳' WHERE id = '19b095ff-5334-4011-abd1-b8df6c79520c' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dulce final de un día precioso. 🌙', body_es = 'Baja la luz de la habitación, pon el sonido del vientre materno en Ruido blanco y mira cómo tu bebé duerme plácidamente.', title_fr = 'La douce fin d''une belle journée. 🌙', body_fr = 'Baissez la lumière, mettez le son du ventre maternel dans les Bruits blancs et regardez votre bébé s''endormir paisiblement.', title_hi = 'एक खूबसूरत दिन का मीठा अंत। 🌙', body_hi = 'कमरे की रोशनी कम कीजिए, व्हाइट नॉइज़ में गर्भ की आवाज़ चलाइए और अपने बच्चे को चैन से सोते देखिए।', title_id = 'Akhir manis dari hari yang indah. 🌙', body_id = 'Redupkan lampu kamar, nyalakan suara rahim dari Suara Putih, dan saksikan bayi Anda tidur nyenyak.', title_ja = 'すてきな1日のやさしい終わり。🌙', body_ja = '部屋の明かりを落として、「ホワイトノイズ」から胎内音をかけ、赤ちゃんがすやすや眠る様子を見守りましょう。', title_ko = '아름다운 하루의 달콤한 마무리. 🌙', body_ko = '방 불빛을 줄이고 백색소음에서 엄마 뱃속 소리를 틀어 주세요. 아기가 새근새근 잠드는 걸 지켜보세요.', title_nl = 'Een lief einde van een mooie dag. 🌙', body_nl = 'Dim het licht in de kamer, zet het baarmoedergeluid in Witte ruis aan en kijk hoe je baby heerlijk in slaap valt.', title_pl = 'Słodkie zakończenie pięknego dnia. 🌙', body_pl = 'Przyciemnij światło w pokoju, włącz w Białym szumie odgłos brzucha mamy i patrz, jak dziecko słodko zasypia.', title_pt = 'O doce final de um dia bonito. 🌙', body_pt = 'Diminua a luz do quarto, ligue no Ruído Branco o som do ventre materno e veja o bebé dormir que nem um anjo.', title_sv = 'Ett sött slut på en fin dag. 🌙', body_sv = 'Dämpa ljuset i rummet, sätt på magljudet i Vitt brus och se ditt barn sova sött.', title_vi = 'Kết thúc ngọt ngào cho một ngày đẹp. 🌙', body_vi = 'Giảm ánh sáng trong phòng, bật âm thanh trong bụng mẹ từ Tiếng ồn trắng và ngắm bé ngủ say.', title_zh = '美好一天的甜蜜结尾。🌙', body_zh = '调暗房间的灯光，在白噪音里打开子宫声，看着宝宝安然入睡。' WHERE id = '8e6d5e26-758c-4169-81b6-bd9cbcc10cc5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paso al sueño profundo. 😴', body_es = 'Elige el sonido del secador en Ruido blanco y, mientras duerme tranquilo, relájate escribiendo cómo te sientes en el Diario de ánimo.', title_fr = 'Vers un sommeil profond. 😴', body_fr = 'Choisissez le bruit du sèche-cheveux dans les Bruits blancs et, pendant qu''il dort, détendez-vous en écrivant vos ressentis dans le Journal d''humeur.', title_hi = 'गहरी नींद की ओर। 😴', body_hi = 'व्हाइट नॉइज़ में हेयर ड्रायर की आवाज़ चुनिए, और जब वह आराम से सोए, मूड डायरी में अपनी भावनाएँ लिखकर आराम कीजिए।', title_id = 'Peralihan ke tidur nyenyak. 😴', body_id = 'Pilih suara pengering rambut dari Suara Putih, dan selagi ia tidur nyenyak, bersantailah dengan menulis perasaan Anda di Buku Harian Suasana Hati.', title_ja = '深い眠りへ。😴', body_ja = '「ホワイトノイズ」からドライヤーの音を選び、赤ちゃんがぐっすり眠る間、「気分日記」に気持ちを書いてリラックスしましょう。', title_ko = '깊은 잠으로. 😴', body_ko = '백색소음에서 드라이기 소리를 골라 주세요. 아기가 편히 자는 동안 기분 일기에 감정을 적으며 쉬세요.', title_nl = 'Op weg naar een diepe slaap. 😴', body_nl = 'Kies het geluid van de haardroger in Witte ruis en ontspan terwijl je baby rustig slaapt door je gevoelens in je Stemmingsdagboek te schrijven.', title_pl = 'Przejście w głęboki sen. 😴', body_pl = 'Wybierz w Białym szumie dźwięk suszarki, a gdy dziecko spokojnie śpi, odpocznij, zapisując uczucia w Dzienniku nastroju.', title_pt = 'Rumo a um sono profundo. 😴', body_pt = 'Escolha no Ruído Branco o som do secador de cabelo e, enquanto ele dorme tranquilo, relaxe escrevendo o que sente no Diário de Humor.', title_sv = 'Övergång till djup sömn. 😴', body_sv = 'Välj hårtorksljudet i Vitt brus och slappna av genom att skriva ner dina känslor i Humördagboken medan barnet sover lugnt.', title_vi = 'Chìm vào giấc ngủ sâu. 😴', body_vi = 'Chọn tiếng máy sấy tóc trong Tiếng ồn trắng, khi bé ngủ yên, mẹ hãy viết cảm xúc vào Nhật ký tâm trạng để thư giãn.', title_zh = '进入深度睡眠。😴', body_zh = '在白噪音里选择吹风机声，宝宝安睡时，你把感受写进心情日记，放松一下。' WHERE id = '10f8db02-014b-4a08-8d7a-e5cbbb260125' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Análisis diario de las tomas. 🍼', body_es = 'Mide la duración de la toma con el temporizador de la app y revisa lo normal en la sección Seguimiento de tomas.', title_fr = 'Analyse des repas du jour. 🍼', body_fr = 'Mesurez la durée de la tétée avec le minuteur de l''application et vérifiez la norme dans la rubrique Suivi des repas.', title_hi = 'रोज़ की फ़ीडिंग का विश्लेषण। 🍼', body_hi = 'ऐप के टाइमर से ब्रेस्टफ़ीडिंग का समय मापिए और फ़ीडिंग ट्रैकर सेक्शन में मानक जाँचिए।', title_id = 'Analisis menyusu harian. 🍼', body_id = 'Ukur lama menyusui dengan pengatur waktu di aplikasi dan cek angka normalnya di bagian Pemantau Menyusu.', title_ja = '1日の授乳の分析。🍼', body_ja = 'アプリのタイマーで授乳時間を測って、授乳記録で目安をチェックしましょう。', title_ko = '하루 수유 분석. 🍼', body_ko = '앱 타이머로 수유 시간을 재고 수유 기록 섹션에서 기준치를 확인하세요.', title_nl = 'Dagelijkse voedingsanalyse. 🍼', body_nl = 'Meet de duur van de borstvoeding met de timer in de app en bekijk de norm in het onderdeel Voedingstracker.', title_pl = 'Dzienna analiza karmienia. 🍼', body_pl = 'Mierz czas karmienia piersią timerem w aplikacji i sprawdzaj normę w sekcji Kontrola karmienia.', title_pt = 'Análise diária da alimentação. 🍼', body_pt = 'Meça a duração da mamada com o temporizador da app e veja a quantidade recomendada na secção Registo de Alimentação.', title_sv = 'Daglig matningsanalys. 🍼', body_sv = 'Mät amningstiden med timern i appen och kolla normen i Matningskoll.', title_vi = 'Phân tích cữ bú hằng ngày. 🍼', body_vi = 'Đo thời gian cho bú bằng bộ hẹn giờ trong ứng dụng và kiểm tra định mức trong mục Theo dõi cữ bú.', title_zh = '每日喂养分析。🍼', body_zh = '用应用里的计时器测量哺乳时长，并在喂养记录板块查看参考量。' WHERE id = '2cd12a68-4486-435f-ad24-55a11a2f62a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Descubre nuevos sonidos! 🗣️', body_es = 'Graba sus tiernos gorjeos. Lee el Blog para saber más sobre el desarrollo del lenguaje.', title_fr = 'Il découvre de nouveaux sons ! 🗣️', body_fr = 'Enregistrez ses adorables « areuh ». Pour en savoir plus sur le développement du langage, lisez les Blogs.', title_hi = 'नई आवाज़ें खोज रहा है! 🗣️', body_hi = 'उसकी प्यारी ''आ-गू'' रिकॉर्ड कीजिए। भाषा के विकास के बारे में और जानने के लिए ब्लॉग पढ़िए।', title_id = 'Ia menemukan suara-suara baru! 🗣️', body_id = 'Rekam ocehan manisnya. Baca Blog untuk mempelajari lebih lanjut tentang perkembangan bahasa.', title_ja = '新しい音を発見中！🗣️', body_ja = 'かわいい「アーウー」を記録しましょう。言葉の発達についてもっと知りたいときは、ブログを読んでみましょう。', title_ko = '새로운 소리를 발견하고 있어요! 🗣️', body_ko = '아기의 귀여운 옹알이를 기록해 두세요. 언어 발달에 대해 더 알고 싶다면 블로그를 읽어 보세요.', title_nl = 'Je baby ontdekt nieuwe geluiden! 🗣️', body_nl = 'Leg die lieve brabbelgeluidjes vast. Lees de Blogs voor meer over de taalontwikkeling.', title_pl = 'Odkrywa nowe dźwięki! 🗣️', body_pl = 'Nagraj jego słodkie gaworzenie. Więcej o rozwoju mowy przeczytasz na Blogu.', title_pt = 'Está a descobrir novos sons! 🗣️', body_pt = 'Registe os seus "agu" ternurentos. Leia os Blogues para saber mais sobre o desenvolvimento da linguagem.', title_sv = 'Barnet upptäcker nya ljud! 🗣️', body_sv = 'Anteckna det söta jollret. Läs Bloggen för att lära dig mer om språkutvecklingen.', title_vi = 'Bé khám phá âm thanh mới! 🗣️', body_vi = 'Hãy ghi lại những tiếng "a-ưm" đáng yêu của bé. Đọc mục Blog để tìm hiểu thêm về phát triển ngôn ngữ.', title_zh = '宝宝在探索新的声音！🗣️', body_zh = '记录下宝宝可爱的“啊咕”声。想了解更多语言发育知识，就读读博客吧。' WHERE id = '917836b6-b023-4945-8e64-bc144ba97f42' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Siguen los despertares nocturnos? ⏱️', body_es = 'Anota cada despertar en el temporizador de sueño y analiza su rutina de sueño general y lo normal para cada día.', title_fr = 'Les réveils nocturnes continuent ? ⏱️', body_fr = 'Notez chaque réveil dans le minuteur de sommeil pour analyser son rythme de sommeil global et la norme quotidienne.', title_hi = 'रात में जागना जारी है? ⏱️', body_hi = 'हर बार जागना स्लीप टाइमर में दर्ज कीजिए और नींद के पूरे पैटर्न और रोज़ के मानक का विश्लेषण कीजिए।', title_id = 'Masih sering bangun malam? ⏱️', body_id = 'Catat setiap kali ia bangun di pengatur waktu tidur untuk menganalisis pola tidur keseluruhan dan kebutuhan hariannya.', title_ja = '夜中の目覚めが続いていますか？⏱️', body_ja = '起きるたびに睡眠タイマーで記録して、全体の睡眠リズムと1日の目安を分析しましょう。', title_ko = '밤중에 깨는 일이 계속되나요? ⏱️', body_ko = '깰 때마다 수면 타이머에 기록하고 전체 수면 패턴과 하루 기준치를 분석해 보세요.', title_nl = 'Nog steeds wakker ’s nachts? ⏱️', body_nl = 'Noteer elk wakker worden in de slaaptimer en analyseer het algehele slaapritme en de dagelijkse norm.', title_pl = 'Nocne pobudki trwają? ⏱️', body_pl = 'Zapisuj każdą pobudkę w timerze snu i analizuj ogólny rytm snu oraz dzienną normę.', title_pt = 'Os despertares noturnos continuam? ⏱️', body_pt = 'Registe cada despertar no temporizador de sono e analise o padrão geral de sono e as horas diárias recomendadas.', title_sv = 'Fortsätter de nattliga uppvaknandena? ⏱️', body_sv = 'Anteckna varje uppvaknande i sömntimern och analysera den övergripande sömnrytmen och den dagliga normen.', title_vi = 'Bé vẫn thức đêm? ⏱️', body_vi = 'Ghi lại mỗi lần bé thức trong bộ hẹn giờ ngủ để phân tích nếp ngủ chung và định mức hằng ngày.', title_zh = '还在夜醒？⏱️', body_zh = '把每次醒来都记在睡眠计时器里，分析整体睡眠规律和每日参考量。' WHERE id = 'd31b874f-e957-475e-a461-b294c96db59f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No te olvides de ti! 🥗', body_es = 'La energía de mamá es muy importante. Elige un plato rico en vitaminas de las Recetas saludables para mujeres y recupera fuerzas.', title_fr = 'Ne vous oubliez pas ! 🥗', body_fr = 'L''énergie de maman est très importante. Choisissez un plat riche en vitamines dans les Recettes saines pour femmes et retrouvez vos forces.', title_hi = 'खुद को मत भूलिए! 🥗', body_hi = 'माँ की ऊर्जा बहुत ज़रूरी है। महिलाओं के लिए सेहतमंद रेसिपी से विटामिन भरी डिश चुनकर अपनी ताकत लौटाइए।', title_id = 'Jangan lupakan diri Anda! 🥗', body_id = 'Energi ibu sangat penting. Pilih hidangan kaya vitamin dari Resep Sehat untuk wanita dan pulihkan kekuatan Anda.', title_ja = '自分のことも忘れずに！🥗', body_ja = 'ママのエネルギーはとても大切です。「女性のためのヘルシーレシピ」からビタミンたっぷりの1品を選んで、元気を取り戻しましょう。', title_ko = '엄마 자신도 잊지 마세요! 🥗', body_ko = '엄마의 에너지는 아주 중요해요. 여성을 위한 건강한 레시피에서 비타민 가득한 한 끼를 골라 기운을 되찾으세요.', title_nl = 'Vergeet jezelf niet! 🥗', body_nl = 'De energie van mama is heel belangrijk. Kies een vitaminerijk gerecht uit de gezonde recepten voor vrouwen en herwin je kracht.', title_pl = 'Nie zapominaj o sobie! 🥗', body_pl = 'Energia mamy jest bardzo ważna. Wybierz bogate w witaminy danie ze Zdrowych przepisów dla kobiet i odzyskaj siły.', title_pt = 'Não se esqueça de si! 🥗', body_pt = 'A energia da mãe é muito importante. Recupere as forças com um prato rico em vitaminas das receitas saudáveis para mulheres.', title_sv = 'Glöm inte bort dig själv! 🥗', body_sv = 'Mammans energi är väldigt viktig. Välj en vitaminrik rätt bland Hälsosamma recept för kvinnor och återfå dina krafter.', title_vi = 'Đừng quên bản thân! 🥗', body_vi = 'Năng lượng của mẹ rất quan trọng. Hãy chọn một món giàu vitamin từ Công thức lành mạnh cho phụ nữ để phục hồi sức lực.', title_zh = '别忘了你自己！🥗', body_zh = '妈妈的精力非常重要。从女性健康食谱里选一份富含维生素的餐点，恢复体力吧。' WHERE id = 'd491dc2d-f6b9-49dd-8461-5cbffee476e5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué te preocupa? 🤖', body_es = 'Incluso de madrugada, haz cualquier pregunta a nuestra asistente Anacan AI y recibe apoyo experto.', title_fr = 'Qu''est-ce qui vous inquiète ? 🤖', body_fr = 'Même en pleine nuit, posez n''importe quelle question à notre assistant Anacan AI et obtenez l''aide d''un spécialiste.', title_hi = 'आपको क्या परेशान कर रहा है? 🤖', body_hi = 'रात के समय भी, अपना कोई भी सवाल हमारे Anacan AI असिस्टेंट से पूछिए और विशेषज्ञ सहायता पाइए।', title_id = 'Apa yang membuat Anda cemas? 🤖', body_id = 'Bahkan di tengah malam, ajukan pertanyaan apa pun kepada asisten Anacan AI kami dan dapatkan dukungan ahli.', title_ja = '気になることは何ですか？🤖', body_ja = '夜中でも、どんな質問でもAnacan AIアシスタントに聞いて、専門的なサポートを受けましょう。', title_ko = '무엇이 걱정되나요? 🤖', body_ko = '한밤중에도 궁금한 건 무엇이든 Anacan AI 도우미에게 물어보고 전문적인 도움을 받으세요.', title_nl = 'Wat houdt je bezig? 🤖', body_nl = 'Stel zelfs midden in de nacht al je vragen aan onze assistent Anacan AI en krijg deskundige steun.', title_pl = 'Co cię niepokoi? 🤖', body_pl = 'Nawet w nocy zadaj dowolne pytanie naszej asystentce Anacan AI i otrzymaj fachowe wsparcie.', title_pt = 'O que a preocupa? 🤖', body_pt = 'Mesmo de madrugada, faça qualquer pergunta ao nosso assistente Anacan AI e receba apoio especializado.', title_sv = 'Vad oroar dig? 🤖', body_sv = 'Även mitt i natten kan du ställa vilken fråga som helst till vår assistent Anacan AI och få expertstöd.', title_vi = 'Điều gì khiến mẹ lo lắng? 🤖', body_vi = 'Ngay cả lúc nửa đêm, hãy hỏi trợ lý Anacan AI bất kỳ câu hỏi nào và nhận hỗ trợ chuyên môn.', title_zh = '有什么让你担心的？🤖', body_zh = '即使在深夜，也可以向我们的Anacan AI助手提出任何问题，获得专业支持。' WHERE id = '6ca1ad26-9f01-4a3a-9164-e9f0d68cc33c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisemos el Seguimiento de pañales. 🧷', body_es = 'Anota en Anacan los pañales del día para asegurarte de que tu bebé come lo suficiente.', title_fr = 'Vérifions le suivi des couches. 🧷', body_fr = 'Notez chaque jour le nombre de couches dans Anacan pour vous assurer que votre bébé mange à sa faim.', title_hi = 'डायपर ट्रैकर देखें। 🧷', body_hi = 'रोज़ के डायपर Anacan में दर्ज करके पक्का कीजिए कि बच्चे का पेट ठीक से भर रहा है।', title_id = 'Yuk, cek pelacak popok. 🧷', body_id = 'Catat jumlah popok harian di Anacan untuk memastikan bayi Anda cukup menyusu.', title_ja = 'おむつトラッカーをチェックしましょう。🧷', body_ja = '1日のおむつの回数をAnacanに記録して、赤ちゃんが十分に飲めているか確認しましょう。', title_ko = '기저귀 기록을 확인해 볼까요? 🧷', body_ko = '하루 기저귀 수를 Anacan에 기록하고 아기가 충분히 먹는지 확인하세요.', title_nl = 'Laten we de Luiertracker bekijken. 🧷', body_nl = 'Noteer het aantal luiers per dag in Anacan, zodat je zeker weet dat je baby genoeg binnenkrijgt.', title_pl = 'Sprawdźmy narzędzie do śledzenia pieluszek. 🧷', body_pl = 'Zapisuj dzienną liczbę pieluszek w Anacan i miej pewność, że dziecko się najada.', title_pt = 'Vamos ver o registo de fraldas. 🧷', body_pt = 'Registe o número de fraldas do dia no Anacan para ter a certeza de que o bebé está bem alimentado.', title_sv = 'Ska vi kolla Blöjkollen? 🧷', body_sv = 'Anteckna antalet blöjor varje dag i Anacan och känn dig trygg med att barnet får tillräckligt med mat.', title_vi = 'Cùng xem Theo dõi tã nhé. 🧷', body_vi = 'Ghi lại số tã hằng ngày trong Anacan để chắc chắn bé bú đủ.', title_zh = '来看看尿布记录。🧷', body_zh = '在Anacan里记录每天的尿布数量，确认宝宝吃得够。' WHERE id = 'f710f746-b942-4fd7-a8ca-dd9b5a248195' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rutina antes de dormir. 🛁', body_es = 'Báñale, dale el pecho y pon en marcha el temporizador de sueño. ¡Que todo vaya según lo previsto y con calma!', title_fr = 'La routine avant le coucher. 🛁', body_fr = 'Bain, tétée, puis lancez le minuteur de sommeil. Que tout se passe dans le calme et selon le plan !', title_hi = 'सोने से पहले का रूटीन। 🛁', body_hi = 'नहलाइए, दूध पिलाइए और स्लीप टाइमर चालू कीजिए। सब कुछ योजना के मुताबिक और आराम से चले!', title_id = 'Rutinitas sebelum tidur. 🛁', body_id = 'Mandikan, susui, dan nyalakan pengatur waktu tidur. Biarkan semuanya berjalan terencana dan nyaman!', title_ja = '寝る前のルーティン。🛁', body_ja = 'お風呂に入れて、授乳して、睡眠タイマーをスタート。すべてを計画どおり、ゆったり進めましょう！', title_ko = '잠자기 전 루틴. 🛁', body_ko = '목욕시키고, 수유하고, 수면 타이머를 켜세요. 모든 게 계획대로 편안하게 흘러가도록!', title_nl = 'Het ritueel voor het slapengaan. 🛁', body_nl = 'Bad, voeding en de slaaptimer aan. Laat alles volgens plan en rustig verlopen!', title_pl = 'Rutyna przed snem. 🛁', body_pl = 'Wykąp, nakarm i włącz timer snu. Niech wszystko idzie spokojnie i według planu!', title_pt = 'A rotina antes de dormir. 🛁', body_pt = 'Dê banho, amamente e ligue o temporizador de sono. Que tudo corra de forma planeada e tranquila!', title_sv = 'Rutin före läggdags. 🛁', body_sv = 'Bada, amma och starta sömntimern. Låt allt gå planerat och lugnt!', title_vi = 'Nếp sinh hoạt trước giờ ngủ. 🛁', body_vi = 'Tắm, cho bú và bật bộ hẹn giờ ngủ. Để mọi thứ diễn ra theo kế hoạch và nhẹ nhàng!', title_zh = '睡前程序。🛁', body_zh = '洗澡、喂奶，然后启动睡眠计时器。让一切有计划、轻轻松松！' WHERE id = 'df56b34d-b5f8-476f-a65e-11a244242a2f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Busca tu voz! 👂', body_es = 'Háblale mucho y mírale a los ojos. Descubre distintas actividades para su desarrollo en la sección Blog.', title_fr = 'Il cherche votre voix ! 👂', body_fr = 'Parlez-lui beaucoup et regardez-le dans les yeux. Découvrez des activités variées pour son développement dans la rubrique Blogs.', title_hi = 'वह आपकी आवाज़ ढूँढता है! 👂', body_hi = 'उससे खूब बात कीजिए, आँखों से संपर्क बनाइए। उसके विकास के लिए अलग-अलग गतिविधियाँ ब्लॉग सेक्शन से सीखिए।', title_id = 'Ia mencari suara Anda! 👂', body_id = 'Ajak ia banyak bicara dan jalin kontak mata. Pelajari berbagai aktivitas untuk perkembangannya di bagian Blog.', title_ja = 'ママの声を探しています！👂', body_ja = 'たくさん話しかけて、目を合わせてあげましょう。発達を助けるいろいろな遊びを、ブログで学びましょう。', title_ko = '엄마 목소리를 찾고 있어요! 👂', body_ko = '아기에게 많이 말을 걸고 눈을 맞춰 주세요. 발달을 돕는 다양한 활동은 블로그 섹션에서 알아보세요.', title_nl = 'Je baby zoekt je stem! 👂', body_nl = 'Praat veel met je baby en maak oogcontact. Ontdek verschillende activiteiten voor de ontwikkeling in het onderdeel Blogs.', title_pl = 'Szuka twojego głosu! 👂', body_pl = 'Dużo z nim rozmawiaj i nawiązuj kontakt wzrokowy. Różne zabawy wspierające rozwój znajdziesz w sekcji Blogi.', title_pt = 'Está à procura da sua voz! 👂', body_pt = 'Fale muito com ele e faça contacto visual. Descubra na secção Blogues atividades diferentes para o desenvolvimento.', title_sv = 'Barnet letar efter din röst! 👂', body_sv = 'Prata mycket med barnet och skapa ögonkontakt. Lär dig olika aktiviteter för utvecklingen i Bloggen.', title_vi = 'Bé đang tìm giọng mẹ! 👂', body_vi = 'Hãy trò chuyện với bé thật nhiều, giao tiếp bằng mắt. Tìm hiểu các hoạt động khác nhau cho sự phát triển của bé trong mục Blog.', title_zh = '宝宝在寻找你的声音！👂', body_zh = '多和宝宝说话，多进行眼神交流。在博客板块学习各种促进发育的活动吧。' WHERE id = '2776b020-9972-4e23-acb7-6a529664582d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tienes dudas sobre el cuidado del bebé? 🤖', body_es = 'La Comunidad Anacan te escuchará sin juzgarte y te dará el consejo más adecuado.', title_fr = 'Des hésitations sur les soins de bébé ? 🤖', body_fr = 'La Communauté Anacan vous écoutera sans vous juger et vous donnera les conseils les plus adaptés.', title_hi = 'बच्चे की देखभाल को लेकर कोई दुविधा है? 🤖', body_hi = 'Anacan कम्युनिटी आपको बिना जज किए सुनेगी और सबसे सही सलाह देगी।', title_id = 'Ragu soal perawatan bayi? 🤖', body_id = 'Komunitas Anacan akan mendengarkan Anda tanpa menghakimi dan memberikan saran yang paling sesuai.', title_ja = '赤ちゃんのお世話で迷っていることはありますか？🤖', body_ja = 'Anacanコミュニティは、あなたを責めることなく話を聞き、ぴったりのアドバイスをくれます。', title_ko = '아기 돌봄에 대해 고민이 있나요? 🤖', body_ko = 'Anacan 커뮤니티가 판단 없이 들어 주고 가장 알맞은 조언을 드릴 거예요.', title_nl = 'Twijfels over de verzorging van je baby? 🤖', body_nl = 'De Anacan Community luistert zonder oordeel naar je en geeft je het beste advies.', title_pl = 'Masz wątpliwości co do pielęgnacji dziecka? 🤖', body_pl = 'Społeczność Anacan wysłucha cię bez oceniania i podsunie najlepszą radę.', title_pt = 'Tem dúvidas sobre os cuidados com o bebé? 🤖', body_pt = 'A Comunidade Anacan vai ouvi-la sem julgamentos e dar-lhe o conselho mais adequado.', title_sv = 'Är du osäker på något kring barnets skötsel? 🤖', body_sv = 'Anacans Community lyssnar på dig utan att döma och ger dig de bästa råden.', title_vi = 'Mẹ còn phân vân về cách chăm bé? 🤖', body_vi = 'Cộng đồng Anacan sẽ lắng nghe mẹ mà không phán xét và đưa ra lời khuyên phù hợp nhất.', title_zh = '对宝宝护理有疑虑？🤖', body_zh = 'Anacan社区会不带评判地倾听你，给你最合适的建议。' WHERE id = '72abc90e-b301-468a-9629-3f3bb7949709' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Informe diario. 📊', body_es = '¿Cuánto ha dormido hoy y cuántas tomas ha hecho? Mira las estadísticas generales de hoy en los gráficos de la app.', title_fr = 'Rapport du jour. 📊', body_fr = 'Combien a-t-il dormi, combien de fois a-t-il mangé aujourd''hui ? Consultez les statistiques du jour dans vos graphiques de l''application.', title_hi = 'रोज़ की रिपोर्ट। 📊', body_hi = 'आज वह कितना सोया, कितनी बार दूध पिया? ऐप के चार्ट में आज के कुल आँकड़े देखिए।', title_id = 'Laporan harian. 📊', body_id = 'Berapa lama ia tidur dan berapa kali menyusu hari ini? Lihat statistik keseluruhan hari ini dari grafik di aplikasi.', title_ja = '今日のレポート。📊', body_ja = '今日はどれくらい眠って、何回飲んだ？アプリのグラフで今日のデータ全体を見てみましょう。', title_ko = '오늘의 리포트. 📊', body_ko = '오늘 얼마나 자고 몇 번 먹었을까요? 앱의 그래프에서 오늘의 전체 통계를 확인해 보세요.', title_nl = 'Dagrapport. 📊', body_nl = 'Hoeveel heeft je baby vandaag geslapen en hoe vaak gedronken? Bekijk de statistieken van vandaag in de grafieken in de app.', title_pl = 'Dzienny raport. 📊', body_pl = 'Ile dziś spało i ile razy jadło? Zajrzyj do ogólnych statystyk dnia na wykresach w aplikacji.', title_pt = 'Relatório diário. 📊', body_pt = 'Quanto dormiu e quantas vezes mamou hoje? Veja as estatísticas gerais de hoje nos gráficos da app.', title_sv = 'Daglig rapport. 📊', body_sv = 'Hur mycket har barnet sovit och hur många gånger har det ätit i dag? Kika på dagens samlade statistik i diagrammen i appen.', title_vi = 'Báo cáo hằng ngày. 📊', body_vi = 'Hôm nay bé ngủ bao lâu, bú mấy lần? Hãy xem thống kê chung hôm nay trên các biểu đồ trong ứng dụng.', title_zh = '每日报告。📊', body_zh = '今天宝宝睡了多久、吃了几次？在应用图表里看看今天的总体统计吧。' WHERE id = '427917df-21f2-46c9-a030-52d511e37ce5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' 