UPDATE public.mommy_day_notifications SET title_es = '¡No nos olvidamos de los papás! 👨‍🍼', body_es = 'Valora esos momentos tiernos y divertidos en que tu bebé juega con su papá.', title_fr = 'Nous n''oublions pas les papas ! 👨‍🍼', body_fr = 'Savourez les moments tendres et amusants où votre bébé joue avec son papa.', title_hi = 'हम पापा को भी नहीं भूलते! 👨‍🍼', body_hi = 'बच्चे के पापा के साथ खेलने के प्यारे और मज़ेदार पलों को सँजोइए।', title_id = 'Kita tidak melupakan para ayah! 👨‍🍼', body_id = 'Hargai momen manis dan seru saat bayi Anda bermain dengan ayahnya.', title_ja = 'パパのことも忘れずに！👨‍🍼', body_ja = '赤ちゃんがパパと遊ぶかわいくて楽しい瞬間を大切にしましょう。', title_ko = '아빠도 잊지 않아요! 👨‍🍼', body_ko = '아기가 아빠와 함께 노는 사랑스럽고 즐거운 순간을 소중히 여기세요.', title_nl = 'We vergeten papa’s niet! 👨‍🍼', body_nl = 'Geniet van de lieve en grappige momenten waarop je baby met papa speelt.', title_pl = 'Nie zapominamy o tatusiach! 👨‍🍼', body_pl = 'Doceniaj słodkie i radosne chwile, gdy dziecko bawi się z tatą.', title_pt = 'Também não nos esquecemos dos pais! 👨‍🍼', body_pt = 'Valorize os momentos ternurentos e divertidos em que o bebé brinca com o pai.', title_sv = 'Vi glömmer inte papporna! 👨‍🍼', body_sv = 'Ta vara på de söta och roliga stunderna när barnet leker med sin pappa.', title_vi = 'Không quên các ông bố! 👨‍🍼', body_vi = 'Hãy trân trọng những khoảnh khắc ngọt ngào, vui nhộn khi bé chơi cùng bố.', title_zh = '我们也没忘记爸爸！👨‍🍼', body_zh = '珍惜宝宝和爸爸一起玩耍的甜蜜欢乐时光。' WHERE id = 'c555165e-a5c9-4e8c-9a72-cf4d0a16a367' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,''