UPDATE public.mommy_day_notifications SET title_es = 'No te sientas culpable 💖', title_fr = 'Ne culpabilisez pas 💖', title_hi = 'अपराध-बोध मत रखिए 💖', title_id = 'Jangan merasa bersalah 💖', title_ja = '罪悪感を抱かないで 💖', title_ko = '죄책감은 내려놓으세요 💖', title_nl = 'Heb geen schuldgevoel 💖', title_pl = 'Nie miej wyrzutów sumienia 💖', title_pt = 'Não sinta remorsos 💖', title_sv = 'Ha inte dåligt samvete 💖', title_vi = 'Đừng cắn rứt lương tâm 💖', title_zh = '不要内疚 💖' WHERE id = '9ff73499-a2bd-41b7-96fa-1ec2d780279f' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Silencio absoluto 🤫', body_es = '¿Le cuesta dormirse? Oscurece por completo la habitación y corta el ruido. La oscuridad y el silencio son sus mejores amigos para dormir.', title_fr = 'Silence absolu 🤫', body_fr = 'Il a du mal à s''endormir ? Faites le noir complet dans la chambre et coupez les bruits. L''obscurité et le silence sont ses meilleurs alliés pour dormir.', title_hi = 'पूरी खामोशी 🤫', body_hi = 'सोने में मुश्किल हो रही है? कमरे में पूरा अँधेरा कीजिए और आवाज़ बंद कीजिए। अँधेरा और खामोशी उसकी नींद के सबसे अच्छे दोस्त हैं।', title_id = 'Keheningan total 🤫', body_id = 'Sulit tertidur? Gelapkan kamar sepenuhnya dan matikan suara. Gelap dan hening adalah teman tidur terbaiknya.', title_ja = '完全な静けさ 🤫', body_ja = 'なかなか寝つけない？部屋を真っ暗にして、音を消しましょう。暗さと静けさは、赤ちゃんのいちばんの睡眠の友達です。', title_ko = '완전한 고요함 🤫', body_ko = '잠들기 힘들어하나요? 방을 완전히 어둡게 하고 소리를 꺼 주세요. 어둠과 고요함이 아기의 가장 좋은 잠 친구예요.', title_nl = 'Volledige stilte 🤫', body_nl = 'Moeite met inslapen? Maak de kamer helemaal donker en zet alle geluid uit. Donker en stilte zijn de beste slaapmaatjes.', title_pl = 'Zupełna cisza 🤫', body_pl = 'Trudno mu zasnąć? Całkowicie zaciemnij pokój i wycisz dźwięki. Ciemność i cisza to jego najlepsi przyjaciele snu.', title_pt = 'Silêncio absoluto 🤫', body_pt = 'Tem dificuldade em adormecer? Escureça bem o quarto e corte o som. A escuridão e o silêncio são os melhores amigos do sono dele.', title_sv = 'Total tystnad 🤫', body_sv = 'Har barnet svårt att somna? Mörklägg rummet helt och stäng av ljuden. Mörker och tystnad är barnets bästa sömnvänner.', title_vi = 'Yên tĩnh tuyệt đối 🤫', body_vi = 'Bé khó vào giấc? Làm tối hẳn căn phòng và tắt mọi âm thanh. Bóng tối và sự yên tĩnh là người bạn tốt nhất cho giấc ngủ của bé.', title_zh = '绝对安静 🤫', body_zh = '入睡困难？把房间完全调暗，关掉声音。黑暗和安静是宝宝最好的睡眠伙伴。' WHERE id = '5cafdda5-c60b-4328-9530-450093ed8026' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Agotarse es normal 🔋', title_fr = 'C''est normal d''être épuisée 🔋', title_hi = 'थक जाना सामान्य है 🔋', title_id = 'Kehabisan tenaga itu normal 🔋', title_ja = 'くたくたになるのは普通のこと 🔋', title_ko = '지치는 건 정상이에요 🔋', title_nl = 'Uitgeput zijn is normaal 🔋', title_pl = 'Wyczerpanie jest normalne 🔋', title_pt = 'É normal ficar esgotada 🔋', title_sv = 'Det är normalt att vara slutkörd 🔋', title_vi = 'Kiệt sức là bình thường 🔋', title_zh = '累垮了也很正常 🔋' WHERE id = '9240cd01-c58e-42aa-be44-a4d2ac461bc2' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se te ha olvidado con qué pecho le diste? 🤱', body_es = 'Marca con el temporizador si es el pecho derecho o el izquierdo, ¡y deja que Anacan lo recuerde todo por ti!', title_fr = 'Vous avez oublié de quel côté vous avez allaité ? 🤱', body_fr = 'Notez sein droit ou gauche avec le minuteur, et laissez Anacan tout retenir pour vous !', title_hi = 'भूल गईं कि किस तरफ़ से दूध पिलाया? 🤱', body_hi = 'टाइमर से दायाँ या बायाँ स्तन दर्ज कीजिए, Anacan आपकी जगह सब याद रखेगा!', title_id = 'Lupa payudara mana yang terakhir menyusui? 🤱', body_id = 'Catat payudara kanan atau kiri dengan pengatur waktu, biarkan Anacan mengingat semuanya untuk Anda!', title_ja = 'どちらの胸で授乳したか忘れちゃった？🤱', body_ja = 'タイマーで右か左かを記録して、Anacanにぜんぶ覚えておいてもらいましょう！', title_ko = '어느 쪽 가슴으로 수유했는지 잊으셨나요? 🤱', body_ko = '타이머로 오른쪽, 왼쪽을 기록하세요. Anacan이 엄마 대신 모두 기억해 줄 거예요!', title_nl = 'Vergeten aan welke borst je baby dronk? 🤱', body_nl = 'Noteer met de timer of het de rechter- of linkerborst was, dan onthoudt Anacan alles voor je!', title_pl = 'Zapomniałaś, z której piersi karmiłaś? 🤱', body_pl = 'Zaznaczaj w timerze prawą lub lewą pierś, a Anacan wszystko zapamięta za ciebie!', title_pt = 'Esqueceu-se de qual foi a mama da última vez? 🤱', body_pt = 'Registe com o temporizador se foi a mama direita ou a esquerda, e o Anacan lembra-se de tudo por si!', title_sv = 'Har du glömt vilket bröst du ammade från? 🤱', body_sv = 'Anteckna höger eller vänster bröst med timern, så kommer Anacan ihåg allt åt dig!', title_vi = 'Mẹ quên đã cho bú bên ngực nào? 🤱', body_vi = 'Ghi lại bên trái hay bên phải bằng bộ hẹn giờ, để Anacan nhớ mọi thứ giúp mẹ!', title_zh = '忘了上次喂的是哪一侧？🤱', body_zh = '用计时器记录左侧还是右侧，让Anacan替你记住一切！' WHERE id = 'aba537d3-5a0f-4b17-b02b-4754b93f711f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Todo va bien ✔️', title_fr = 'Tout va bien ✔️', title_hi = 'सब ठीक है ✔️', title_id = 'Semuanya baik-baik saja ✔️', title_ja = 'すべて順調です ✔️', title_ko = '모든 게 괜찮아요 ✔️', title_nl = 'Alles is in orde ✔️', title_pl = 'Wszystko jest w porządku ✔️', title_pt = 'Está tudo bem ✔️', title_sv = 'Allt är som det ska ✔️', title_vi = 'Mọi thứ đều ổn ✔️', title_zh = '一切都很好 ✔️' WHERE id = 'ff86bc54-face-4f54-a1de-cc0ec9cccbc2' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de cuidarle junto a papá. 👨‍🍼', body_es = 'Después de la toma de la tarde, deja que papá se encargue de los gases y de dormirle, y tú descansa.', title_fr = 'Le temps des soins avec Papa. 👨‍🍼', body_fr = 'Après la tétée du soir, confiez le rot et le coucher à Papa, et reposez-vous.', title_hi = 'पापा के साथ देखभाल का समय। 👨‍🍼', body_hi = 'शाम की फ़ीडिंग के बाद डकार दिलाने और सुलाने की बारी पापा को दीजिए, और आप आराम कीजिए।', title_id = 'Waktunya merawat bersama Ayah. 👨‍🍼', body_id = 'Setelah menyusu malam, serahkan giliran menyendawakan dan menidurkan kepada Ayah, dan Anda beristirahatlah.', title_ja = 'パパと一緒にお世話する時間。👨‍🍼', body_ja = '夜の授乳のあと、げっぷと寝かしつけはパパにまかせて、ママは休みましょう。', title_ko = '아빠와 함께하는 돌봄 시간. 👨‍🍼', body_ko = '저녁 수유 후 트림시키기와 재우기는 아빠에게 맡기고 엄마는 쉬세요.', title_nl = 'Tijd voor samen zorgen met papa. 👨‍🍼', body_nl = 'Laat papa na de avondvoeding het boertje en het in slaap brengen doen, en rust jij uit.', title_pl = 'Czas na wspólną opiekę z tatą. 👨‍🍼', body_pl = 'Po wieczornym karmieniu oddaj tacie odbijanie i usypianie, a sama odpocznij.', title_pt = 'Hora de cuidar do bebé com o pai. 👨‍🍼', body_pt = 'Depois da mamada da noite, deixe o pai tratar do arroto e de adormecer o bebé, e descanse.', title_sv = 'Dags för gemensam omvårdnad med pappa. 👨‍🍼', body_sv = 'Efter kvällsmatningen, låt pappa ta rapningen och nattningen, och vila du.', title_vi = 'Giờ chăm bé cùng bố. 👨‍🍼', body_vi = 'Sau cữ bú buổi tối, hãy giao lượt vỗ ợ hơi và ru ngủ cho bố, còn mẹ nghỉ ngơi.', title_zh = '和爸爸一起照顾宝宝的时间。👨‍🍼', body_zh = '晚上喂完奶后，把拍嗝和哄睡交给爸爸，你去休息吧。' WHERE id = '5a4dd587-0176-4bbf-bb1c-d0eab0227cdc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El código del llanto 🧩', body_es = '¿No tiene hambre, el pañal está limpio y aun así está inquieto? Si te cuesta encontrar el motivo, usa el Análisis del llanto para descubrir la necesidad real detrás de ese sonido.', title_fr = 'Le code des pleurs 🧩', body_fr = 'Il n''a pas faim, sa couche est propre, mais il est toujours agité ? Si vous avez du mal à trouver la cause, utilisez l''Analyse des pleurs pour découvrir le vrai besoin derrière ces pleurs.', title_hi = 'रोने का कोड 🧩', body_hi = 'भूखा नहीं, डायपर साफ़ है, फिर भी बेचैन है? अगर वजह ढूँढने में मुश्किल हो रही है, तो क्राइंग एनालिसिस से इस आवाज़ के पीछे की असली ज़रूरत जानिए।', title_id = 'Kode tangisan 🧩', body_id = 'Tidak lapar, popok bersih, tapi tetap gelisah? Jika sulit menemukan penyebabnya, gunakan Analisis Tangisan untuk mengetahui kebutuhan sebenarnya di balik suara itu.', title_ja = '泣き声の暗号 🧩', body_ja = 'お腹もすいていないし、おむつもきれいなのに、まだぐずっている？理由がわからないときは、「泣き声分析」を使って、その声の裏にある本当の気持ちを知りましょう。', title_ko = '울음 암호 🧩', body_ko = '배고프지도 않고 기저귀도 깨끗한데 계속 보채나요? 이유를 찾기 어렵다면 울음 분석으로 그 울음 뒤에 숨은 진짜 필요를 알아보세요.', title_nl = 'De huilcode 🧩', body_nl = 'Geen honger, schone luier, en toch onrustig? Lukt het niet om de oorzaak te vinden, gebruik dan Huilanalyse en ontdek de echte behoefte achter dat geluid.', title_pl = 'Kod płaczu 🧩', body_pl = 'Nie jest głodne, pieluszka czysta, a mimo to jest niespokojne? Jeśli trudno ci znaleźć przyczynę, skorzystaj z Analizy płaczu i poznaj prawdziwą potrzebę kryjącą się za tym dźwiękiem.', title_pt = 'O código do choro 🧩', body_pt = 'Não tem fome, a fralda está limpa, mas continua inquieto? Se tem dificuldade em perceber porquê, use a Análise do Choro e descubra a verdadeira necessidade por trás deste som.', title_sv = 'Gråtkoden 🧩', body_sv = 'Inte hungrig, ren blöja, men ändå orolig? Om du har svårt att hitta orsaken, använd Gråtanalys och ta reda på det verkliga behovet bakom ljudet.', title_vi = 'Mật mã tiếng khóc 🧩', body_vi = 'Không đói, tã sạch, nhưng bé vẫn quấy? Nếu mẹ khó tìm ra nguyên nhân, hãy dùng Phân tích tiếng khóc để biết nhu cầu thật sự đằng sau tiếng khóc ấy.', title_zh = '哭声密码 🧩', body_zh = '不饿，尿布也是干净的，可还是哭闹？如果找不到原因，就用哭声分析来了解哭声背后真正的需求吧。' WHERE id = '36b1e2d3-b43a-467e-b08f-870a612d1bb5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La terquedad del ejercicio matutino 🐢', body_es = '¿No quiere estar boca abajo (tummy time) y llora? No le obligues. Pregunta a Anacan AI: «¿Cómo puedo hacer divertido el tiempo boca abajo para un bebé de 3 meses?» y recibe consejos rápidos.', title_fr = 'Le sport du matin, avec persévérance 🐢', body_fr = 'Il ne veut pas rester sur le ventre (tummy time) et pleure ? Ne le forcez pas. Demandez à Anacan AI : « Comment rendre le temps sur le ventre amusant pour un bébé de 3 mois ? » et obtenez des astuces rapides.', title_hi = 'सुबह की कसरत की ज़िद 🐢', body_hi = 'पेट के बल (टमी टाइम) लेटना पसंद नहीं और रोता है? ज़बरदस्ती मत कीजिए। Anacan AI से पूछिए: “3 महीने के बच्चे के लिए टमी टाइम को मज़ेदार कैसे बनाऊँ?” और झटपट टिप्स पाइए।', title_id = 'Keras kepala saat olahraga pagi 🐢', body_id = 'Ia tidak mau tengkurap (tummy time) dan menangis? Jangan memaksanya. Tanyakan kepada Anacan AI: “Bagaimana membuat waktu tengkurap menyenangkan untuk bayi 3 bulan?” dan dapatkan tips cepat.', title_ja = '朝の体操、いやいや期 🐢', body_ja = 'うつぶせ遊び（タミータイム）をいやがって泣く？無理強いしないで。Anacan AIに「3か月の赤ちゃんのうつぶせ遊びを楽しくするには？」と聞いて、すぐに使えるコツを受け取りましょう。', title_ko = '아침 운동 고집 🐢', body_ko = '엎드려 있기(터미 타임)를 싫어하고 우나요? 억지로 시키지 마세요. Anacan AI에게 “3개월 아기의 엎드려 있기를 어떻게 재미있게 할 수 있을까요?”라고 물어보고 빠른 팁을 받아 보세요.', title_nl = 'Koppig ochtendsporten 🐢', body_nl = 'Wil je baby niet op de buik liggen (tummy time) en huilt hij? Dwing hem niet. Vraag Anacan AI: “Hoe maak ik buikligging leuk voor een baby van 3 maanden?” en krijg snelle tips.', title_pl = 'Upór przy porannej gimnastyce 🐢', body_pl = 'Nie chce leżeć na brzuszku i płacze? Nie zmuszaj go. Zapytaj Anacan AI: „Jak sprawić, by czas na brzuszku był zabawny dla 3-miesięcznego dziecka?” i otrzymaj szybkie wskazówki.', title_pt = 'A teimosia do exercício matinal 🐢', body_pt = 'Não quer ficar de barriga para baixo (tummy time) e chora? Não o obrigue. Pergunte ao Anacan AI: "Como posso tornar o tummy time divertido para um bebé de 3 meses?" e receba dicas rápidas.', title_sv = 'Envis morgongympa 🐢', body_sv = 'Vill barnet inte ligga på magen (tummy time) och gråter? Tvinga inte. Fråga Anacan AI: ''Hur kan jag göra magläget roligt för ett 3 månader gammalt barn?'' och få snabba tips.', title_vi = 'Bài tập buổi sáng bướng bỉnh 🐢', body_vi = 'Bé không chịu nằm sấp (Tummy time) và khóc? Đừng ép bé. Hãy hỏi Anacan AI: “Làm sao để giờ nằm sấp vui hơn cho bé 3 tháng tuổi?” và nhận mẹo nhanh.', title_zh = '执着的晨练 🐢', body_zh = '宝宝不愿意趴着，还哭？别勉强。问问Anacan AI：“怎样让3个月宝宝的趴趴时间更有趣？”，快速获取小技巧。' WHERE id = '62da6149-1edf-4e2a-abc6-d69d21a43fa4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de los sonidos 🌊', body_es = 'Las horas de crisis sin motivo que empiezan al atardecer agotan. Lleva al bebé a la habitación y elige en Ruido blanco las olas del mar o el secador para neutralizar el ambiente al instante.', title_fr = 'Le pouvoir des sons 🌊', body_fr = 'Les crises sans raison qui commencent en fin d''après-midi sont épuisantes. Emmenez bébé dans la chambre, choisissez le bruit des vagues ou du sèche-cheveux dans les Bruits blancs et apaisez l''ambiance instantanément.', title_hi = 'आवाज़ों की ताकत 🌊', body_hi = 'शाम को बिना वजह शुरू होने वाले रोने के घंटे थका देते हैं। बच्चे को कमरे में ले जाइए, व्हाइट नॉइज़ में समुद्र की लहरों या हेयर ड्रायर की आवाज़ चुनकर माहौल तुरंत शांत कीजिए।', title_id = 'Kekuatan suara 🌊', body_id = 'Jam-jam rewel tanpa sebab di sore hari sangat melelahkan. Bawa bayi ke kamar, pilih suara ombak laut atau pengering rambut dari Suara Putih, dan netralkan suasana seketika.', title_ja = '音の力 🌊', body_ja = '夕方から始まる理由のわからないぐずりの時間は疲れます。赤ちゃんを部屋に連れて行き、「ホワイトノイズ」から波の音やドライヤーの音を選んで、すぐに環境を落ち着かせましょう。', title_ko = '소리의 힘 🌊', body_ko = '해 질 무렵 시작되는 이유 없는 보챔 시간은 정말 지쳐요. 아기를 방으로 데려가 백색소음에서 파도 소리나 드라이기 소리를 골라 분위기를 바로 차분하게 바꿔 보세요.', title_nl = 'De kracht van geluid 🌊', body_nl = 'De onverklaarbare huiluurtjes aan het eind van de middag zijn uitputtend. Neem je baby mee naar de kamer, kies oceaangolven of het geluid van de haardroger in Witte ruis en breng de sfeer meteen tot rust.', title_pl = 'Moc dźwięków 🌊', body_pl = 'Wieczorne godziny płaczu bez powodu są męczące. Zanieś dziecko do pokoju, wybierz w Białym szumie fale oceanu lub suszarkę i od razu wycisz otoczenie.', title_pt = 'O poder dos sons 🌊', body_pt = 'As horas de crise sem razão aparente que começam ao fim da tarde são cansativas. Leve o bebé para o quarto, escolha no Ruído Branco o som das ondas do mar ou do secador de cabelo e neutralize o ambiente de imediato.', title_sv = 'Ljudens kraft 🌊', body_sv = 'De oförklarliga krisstunderna som börjar på kvällen är tröttsamma. Ta barnet till rummet, välj havsvågor eller hårtorksljudet i Vitt brus och neutralisera miljön direkt.', title_vi = 'Sức mạnh của âm thanh 🌊', body_vi = 'Những giờ quấy khóc vô cớ bắt đầu từ chiều tối thật mệt mỏi. Hãy đưa bé vào phòng, chọn tiếng sóng biển hoặc tiếng máy sấy tóc trong Tiếng ồn trắng để xoa dịu không gian ngay lập tức.', title_zh = '声音的力量 🌊', body_zh = '傍晚开始的莫名哭闹时段让人筋疲力尽。把宝宝带回房间，在白噪音里选择海浪声或吹风机声，立刻让环境安静下来。' WHERE id = '55bafaf5-82ef-4f88-880d-836cf89145d0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Dónde está la energía de mamá? 🔋', body_es = 'No te culpes al ver tus ojos cansados en el espejo. ¿Cuidas tu alimentación? Elige en Recetas saludables un batido para mamá rico en hierro que se prepara en 10 minutos y recupera tu energía.', title_fr = 'Où est passée l''énergie de maman ? 🔋', body_fr = 'Ne vous jugez pas en voyant vos yeux fatigués dans le miroir. Faites-vous attention à votre alimentation ? Choisissez dans les Recettes saines un smoothie de maman riche en fer, prêt en 10 minutes, et retrouvez votre énergie.', title_hi = 'माँ की ऊर्जा कहाँ है? 🔋', body_hi = 'आईने में अपनी थकी आँखें देखकर खुद को मत कोसिए। क्या आप अपने खाने पर ध्यान दे रही हैं? सेहतमंद रेसिपी से 10 मिनट में बनने वाली आयरन से भरपूर माँ की स्मूदी चुनिए और अपनी ऊर्जा लौटाइए।', title_id = 'Ke mana energi ibu? 🔋', body_id = 'Jangan menyalahkan diri saat melihat mata lelah Anda di cermin. Apakah Anda memperhatikan asupan makan Anda? Pilih smoothie ibu yang kaya zat besi dan bisa dibuat dalam 10 menit dari Resep Sehat, lalu pulihkan energi Anda.', title_ja = 'ママのエネルギーはどこ？🔋', body_ja = '鏡に映る疲れた目を見て、自分を責めないで。食事に気をつけていますか？「ヘルシーレシピ」から10分でつくれる鉄分たっぷりのママ向けスムージーを選んで、元気を取り戻しましょう。', title_ko = '엄마의 에너지는 어디에? 🔋', body_ko = '거울 속 지친 눈을 보며 자신을 탓하지 마세요. 식사는 잘 챙기고 있나요? 건강한 레시피에서 10분 만에 만들 수 있는 철분 가득한 엄마 스무디를 골라 기운을 되찾으세요.', title_nl = 'Waar is mama’s energie? 🔋', body_nl = 'Veroordeel jezelf niet als je naar je vermoeide ogen in de spiegel kijkt. Let je wel op wat je eet? Kies uit Gezonde recepten een ijzerrijke mamasmoothie die in 10 minuten klaar is en herwin je energie.', title_pl = 'Gdzie jest energia mamy? 🔋', body_pl = 'Nie obwiniaj się, patrząc w lustrze na zmęczone oczy. Czy dbasz o swoje odżywianie? Wybierz ze Zdrowych przepisów bogate w żelazo smoothie dla mamy, gotowe w 10 minut, i odzyskaj energię.', title_pt = 'Onde está a energia da mãe? 🔋', body_pt = 'Não se critique ao ver os olhos cansados ao espelho. Está a ter atenção à sua alimentação? Escolha nas Receitas Saudáveis um smoothie para mães rico em ferro, pronto em 10 minutos, e recupere a energia.', title_sv = 'Var är mammans energi? 🔋', body_sv = 'Döm inte dig själv när du ser dina trötta ögon i spegeln. Tänker du på din kost? Välj en järnrik mammasmoothie bland Hälsosamma recept som går att göra på 10 minuter och få tillbaka energin.', title_vi = 'Năng lượng của mẹ đâu rồi? 🔋', body_vi = 'Đừng tự trách khi nhìn đôi mắt mệt mỏi trong gương. Mẹ có chú ý đến bữa ăn của mình không? Hãy chọn một ly sinh tố giàu sắt cho mẹ, làm trong 10 phút, từ Công thức lành mạnh để phục hồi năng lượng.', title_zh = '妈妈的能量去哪了？🔋', body_zh = '看着镜子里疲惫的双眼，别责怪自己。你注意自己的饮食了吗？从健康食谱里选一款10分钟就能做好、富含铁的妈妈奶昔，恢复能量吧。' WHERE id = 'a6e787a8-1712-42a4-9b2a-4f48a9e5fc87' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hambre o cansancio? 😭', title_fr = 'Faim ou fatigue ? 😭', title_hi = 'भूखा है या थका हुआ? 😭', title_id = 'Lapar atau lelah? 😭', title_ja = '痛いの？それとも疲れているの？😭', title_ko = '배고픈 걸까요, 피곤한 걸까요? 😭', title_nl = 'Honger of moe? 😭', title_pl = 'Ból czy zmęczenie? 😭', title_pt = 'Fome ou cansaço? 😭', title_sv = 'Hungrig eller trött? 😭', title_vi = 'Bé đau hay mệt? 😭', title_zh = '是饿了还是累了？😭' WHERE id = 'bcabe7b8-3e78-42a9-bdf0-3f1883219079' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se te ha olvidado con qué pecho le diste? 🤱', title_fr = 'Vous avez oublié de quel côté vous avez allaité ? 🤱', title_hi = 'भूल गईं कि किस तरफ़ से दूध पिलाया? 🤱', title_id = 'Lupa payudara mana yang terakhir menyusui? 🤱', title_ja = 'どちらの胸で授乳したか忘れちゃった？🤱', title_ko = '어느 쪽 가슴으로 수유했는지 잊으셨나요? 🤱', title_nl = 'Vergeten aan welke borst je baby dronk? 🤱', title_pl = 'Zapomniałaś, z której piersi karmiłaś? 🤱', title_pt = 'Esqueceu-se de qual foi a mama da última vez? 🤱', title_sv = 'Har du glömt vilket bröst du ammade från? 🤱', title_vi = 'Mẹ quên đã cho bú bên ngực nào? 🤱', title_zh = '忘了上次喂的是哪一侧？🤱' WHERE id = 'bda23a3e-0646-4246-a5dc-febd245b2bb1' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue sus horas de sueño. ⏱️', title_fr = 'Suivez les normes de sommeil. ⏱️', title_hi = 'नींद के मानकों पर नज़र रखिए। ⏱️', title_id = 'Pantau kebutuhan tidur. ⏱️', title_ja = '睡眠の目安を見守りましょう。⏱️', title_ko = '수면 기준치를 확인하세요. ⏱️', title_nl = 'Volg de slaapnormen. ⏱️', title_pl = 'Śledź normy snu. ⏱️', title_pt = 'Acompanhe as horas de sono. ⏱️', title_sv = 'Följ sömnnormerna. ⏱️', title_vi = 'Theo dõi định mức ngủ. ⏱️', title_zh = '关注睡眠参考量。⏱️' WHERE id = 'e2296439-aad7-4bdf-a627-05d1e066a3d8' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El aire fresco es medicina 🌳', title_fr = 'L''air frais est un remède 🌳', title_hi = 'ताज़ी हवा दवा है 🌳', title_id = 'Udara segar adalah obat 🌳', title_ja = '新鮮な空気は薬です 🌳', title_ko = '맑은 공기는 약이에요 🌳', title_nl = 'Frisse lucht is een medicijn 🌳', title_pl = 'Świeże powietrze to lekarstwo 🌳', title_pt = 'O ar puro é um remédio 🌳', title_sv = 'Frisk luft är medicin 🌳', title_vi = 'Không khí trong lành là liều thuốc 🌳', title_zh = '新鲜空气是良药 🌳' WHERE id = 'b349c13b-d822-42ec-876c-d41ccb790846' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reunión de equipo 🛋️', body_es = 'Cuando el bebé se duerma, mirad juntos tus estadísticas semanales del Diario de ánimo. ¿Qué días has tenido más estrés? ¿Qué podéis hacer distinto? ¡Sois un equipo!', title_fr = 'Discussion d''équipe 🛋️', body_fr = 'Une fois bébé couché, regardez avec votre conjoint vos statistiques de la semaine dans le Journal d''humeur. Quels jours ont été les plus stressants ? Que pourriez-vous faire autrement ? Vous êtes une équipe !', title_hi = 'टीम मीटिंग 🛋️', body_hi = 'बच्चे के सोने के बाद मूड डायरी में अपने हफ़्ते के आँकड़े साथी के साथ देखिए। किन दिनों ज़्यादा तनाव रहा? क्या अलग कर सकते हैं? आप एक टीम हैं!', title_id = 'Diskusi tim 🛋️', body_id = 'Setelah anak tidur, lihat statistik mingguan di Buku Harian Suasana Hati bersama pasangan. Hari apa yang paling membuat stres? Apa yang bisa dilakukan secara berbeda? Kalian satu tim!', title_ja = 'チームで話し合い 🛋️', body_ja = '赤ちゃんが寝たら、「気分日記」の1週間のデータをパートナーと一緒に見てみましょう。どの日がいちばんストレスだった？何を変えられる？2人はチームです！', title_ko = '팀 회의 🛋️', body_ko = '아기가 잠든 후 배우자와 함께 기분 일기의 주간 통계를 살펴보세요. 어떤 날 더 스트레스를 받았나요? 무엇을 다르게 할 수 있을까요? 두 사람은 한 팀이에요!', title_nl = 'Teamoverleg 🛋️', body_nl = 'Bekijk als de baby slaapt samen met je partner je weekstatistieken in het Stemmingsdagboek. Welke dagen waren het meest stressvol? Wat kunnen jullie anders doen? Jullie zijn een team!', title_pl = 'Narada drużyny 🛋️', body_pl = 'Gdy dziecko zaśnie, przejrzyjcie razem z partnerem tygodniowe statystyki w Dzienniku nastroju. Które dni były bardziej stresujące? Co możecie zrobić inaczej? Jesteście drużyną!', title_pt = 'Reunião de equipa 🛋️', body_pt = 'Depois de o bebé adormecer, vejam juntos, a mãe e o companheiro, as estatísticas semanais do Diário de Humor. Em que dias houve mais stress? O que podem fazer de diferente? São uma equipa!', title_sv = 'Lagdiskussion 🛋️', body_sv = 'När barnet har somnat, titta på veckostatistiken i Humördagboken tillsammans med din partner. Vilka dagar var mest stressiga? Vad kan ni göra annorlunda? Ni är ett lag!', title_vi = 'Cả đội cùng bàn bạc 🛋️', body_vi = 'Sau khi bé ngủ, hãy cùng chồng xem thống kê hằng tuần trong Nhật ký tâm trạng. Những ngày nào mẹ căng thẳng nhất? Có thể làm gì khác đi? Hai người là một đội!', title_zh = '团队讨论 🛋️', body_zh = '宝宝睡着后，和另一半一起看看心情日记里的每周统计。哪几天压力更大？可以做哪些改变？你们是一个团队！' WHERE id = '13035ad4-af08-4b79-ba71-a42ceb60fe5b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mira hacia abajo! 👣', body_es = '¡Ya está descubriendo sus pies! No te pierdas ese momento cómico y tierno en que intenta agarrarse los dedos de los pies. Abre la Sesión de fotos del bebé, decóralo con pegatinas y celebra este gran avance.', title_fr = 'Regardez en bas ! 👣', body_fr = 'Il découvre déjà ses pieds ! Ne manquez pas ce moment drôle et adorable où il essaie d''attraper ses orteils. Ouvrez la Séance photo bébé, décorez avec des stickers et célébrez ce grand moment de développement.', title_hi = 'नीचे देखिए! 👣', body_hi = 'वह अब अपने पैर खोज रहा है! पैर की उँगलियाँ पकड़ने की कोशिश वाला वह मज़ेदार और प्यारा पल मत चूकिए। बेबी फ़ोटोशूट खोलिए, स्टिकर से सजाइए और विकास के इस बड़े पल को यादगार बनाइए।', title_id = 'Lihat ke bawah! 👣', body_id = 'Ia mulai menemukan kakinya sendiri! Jangan lewatkan momen lucu dan manis saat ia mencoba meraih jari kakinya. Buka Pemotretan Bayi, hias dengan stiker, dan abadikan momen perkembangan besar ini.', title_ja = '足元を見て！👣', body_ja = '赤ちゃんはもう自分の足を発見しています！足の指をつかもうとする、おもしろくてかわいい瞬間を見逃さないで。「ベビーフォトセッション」を開いて、ステッカーで飾り、この大きな成長の瞬間を記録しましょう。', title_ko = '아래를 보세요! 👣', body_ko = '아기가 벌써 자기 발을 발견하고 있어요! 발가락을 잡으려는 그 귀엽고 웃긴 순간을 놓치지 마세요. 아기 사진 촬영을 열어 스티커로 꾸미고 이 큰 발달의 순간을 남겨 보세요.', title_nl = 'Kijk naar beneden! 👣', body_nl = 'Je baby ontdekt de eigen voetjes! Mis dat grappige, lieve moment niet waarop hij zijn teentjes probeert te pakken. Open Babyfotoshoot, versier de foto met stickers en leg deze grote ontwikkelingsstap vast.', title_pl = 'Spójrz w dół! 👣', body_pl = 'Już odkrywa swoje stópki! Nie przegap tej zabawnej i słodkiej chwili, gdy próbuje złapać paluszki u nóg. Otwórz Sesję zdjęciową dziecka, ozdób zdjęcie naklejkami i uwiecznij ten wielki krok w rozwoju.', title_pt = 'Olhe para baixo! 👣', body_pt = 'Agora está a descobrir os próprios pés! Não perca aquele momento cómico e ternurento em que tenta agarrar os dedos dos pés. Abra a Sessão Fotográfica do Bebé, decore com autocolantes e assinale este grande momento do desenvolvimento.', title_sv = 'Titta neråt! 👣', body_sv = 'Nu upptäcker barnet sina fötter! Missa inte den roliga och söta stunden när det försöker ta tag i tårna. Öppna Babyfotografering, dekorera med klistermärken och förevig det här stora utvecklingsögonblicket.', title_vi = 'Nhìn xuống dưới nào! 👣', body_vi = 'Bé đã khám phá ra đôi chân của mình! Đừng bỏ lỡ khoảnh khắc buồn cười và đáng yêu khi bé cố nắm ngón chân. Mở Chụp ảnh cho bé, trang trí bằng sticker và ghi dấu bước phát triển lớn này.', title_zh = '往下看！👣', body_zh = '宝宝已经在探索自己的小脚了！别错过宝宝想抓住脚趾时那个滑稽又可爱的瞬间。打开宝宝写真，用贴纸装饰一下，记录这个重要的成长时刻。' WHERE id = '400a0bc6-f5e7-4dd0-9d49-d6e66ce5c9b6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de un mordedor 🦷', body_es = '¿No para de babear y lo muerde todo? El Seguimiento de dentición te avisa. Es el momento perfecto para buscar en Productos recomendados mordedores limpios de silicona o de madera.', title_fr = 'À la recherche d''un anneau de dentition 🦷', body_fr = 'Il bave sans arrêt et mâchouille tout ? Le Suivi des dents vous alerte. C''est le moment idéal pour chercher des anneaux de dentition en silicone ou en bois dans la rubrique Produits recommandés.', title_hi = 'टीदर की तलाश 🦷', body_hi = 'लार रुक नहीं रही, हर चीज़ चबाता है? दाँत निकलने का ट्रैकर चेतावनी दे रहा है। सुझाए गए प्रोडक्ट सेक्शन में साफ़ सिलिकॉन या लकड़ी के टीदर देखने का यही सही समय है।', title_id = 'Mencari teether 🦷', body_id = 'Air liur tidak berhenti, semuanya digigit? Pelacak Tumbuh Gigi memberi peringatan. Inilah saat yang tepat untuk mencari teether silikon atau kayu yang bersih di bagian Produk Rekomendasi.', title_ja = '歯固めを探そう 🦷', body_ja = 'よだれが止まらず、何でもかじっている？「歯の生え始めトラッカー」がお知らせしています。「おすすめ商品」で、清潔なシリコンや木製の歯固めを調べるのにぴったりのタイミングです。', title_ko = '치아발육기를 찾아서 🦷', body_ko = '침이 멈추지 않고 무엇이든 깨무나요? 이앓이 기록이 알려 주고 있어요. 추천 제품 섹션에서 깨끗한 실리콘이나 나무 치아발육기를 알아볼 때예요.', title_nl = 'Op zoek naar een bijtring 🦷', body_nl = 'Houdt het kwijlen niet op en knaagt je baby op alles? De Tandjestracker waarschuwt je. Tijd om in het onderdeel Aanbevolen producten schone bijtringen van siliconen of hout te bekijken.', title_pl = 'Szukamy gryzaka 🦷', body_pl = 'Ślinka ciągle cieknie, a dziecko wszystko gryzie? Narzędzie do śledzenia ząbkowania daje znać. To idealny moment, by poszukać czystych silikonowych lub drewnianych gryzaków w sekcji Polecane produkty.', title_pt = 'À procura de um mordedor 🦷', body_pt = 'A baba não para e roe tudo? O Registo de Dentição está a dar o alerta. É o momento ideal para procurar mordedores de silicone ou de madeira limpos na secção Produtos Recomendados.', title_sv = 'På jakt efter bitring 🦷', body_sv = 'Dreglet slutar aldrig och barnet gnager på allt? Tandspåraren varnar. Nu är det perfekt tid att kolla in rena bitringar av silikon eller trä i avsnittet Rekommenderade produkter.', title_vi = 'Đi tìm đồ gặm nướu 🦷', body_vi = 'Nước dãi chảy không ngừng, bé gặm mọi thứ? Theo dõi mọc răng đang báo hiệu đấy. Đây là lúc tìm hiểu đồ gặm nướu bằng silicon hoặc gỗ sạch trong mục Sản phẩm gợi ý.', title_zh = '寻找牙胶 🦷', body_zh = '口水不停，什么都啃？出牙记录在提醒你。现在正是去推荐商品板块挑选干净的硅胶或木质牙胶的好时机。' WHERE id = 'daf9dd68-0ed6-4ada-9b16-84c4ff46a8e8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diálogo rápido 🤖', body_es = '¿Por qué de repente rechaza las siestas? No tienes tiempo de leer artículos largos. Escribe la pregunta directamente a Anacan AI y recibe una respuesta concreta y breve sobre la regresión del sueño de los 3 meses.', title_fr = 'Dialogue express 🤖', body_fr = 'Pourquoi refuse-t-il soudain ses siestes ? Vous n''avez pas le temps de lire de longs articles. Écrivez directement votre question à Anacan AI et obtenez une réponse courte et concrète sur la régression du sommeil des 3 mois.', title_hi = 'झटपट बातचीत 🤖', body_hi = 'बच्चा अचानक दिन की नींद से इनकार क्यों कर रहा है? लंबे लेख पढ़ने का समय नहीं है। सवाल सीधे Anacan AI को लिखिए और 3 महीने के स्लीप रिग्रेशन के बारे में सटीक, छोटा जवाब पाइए।', title_id = 'Dialog cepat 🤖', body_id = 'Kenapa anak tiba-tiba menolak tidur siang? Anda tidak punya waktu membaca artikel panjang. Tulis pertanyaan langsung ke Anacan AI dan dapatkan jawaban singkat dan jelas tentang regresi tidur 3 bulan.', title_ja = 'すばやくおしゃべり 🤖', body_ja = 'どうして急にお昼寝をいやがるの？長い記事を読む時間はありませんよね。質問を直接Anacan AIに書きこんで、3か月の睡眠退行について具体的で短い答えを受け取りましょう。', title_ko = '빠른 대화 🤖', body_ko = '아기가 갑자기 낮잠을 거부하는 이유는 뭘까요? 긴 글을 읽을 시간이 없죠. Anacan AI에게 바로 질문하고 3개월 수면 퇴행에 대한 짧고 명확한 답을 받으세요.', title_nl = 'Snel gesprek 🤖', body_nl = 'Waarom weigert je baby ineens de dutjes overdag? Je hebt geen tijd voor lange artikelen. Typ je vraag direct aan Anacan AI en krijg een duidelijk, kort antwoord over de slaapregressie van 3 maanden.', title_pl = 'Szybka rozmowa 🤖', body_pl = 'Dlaczego dziecko nagle odmawia drzemek w ciągu dnia? Nie masz czasu na długie artykuły. Napisz pytanie bezpośrednio do Anacan AI i otrzymaj konkretną, krótką odpowiedź o regresie snu 3. miesiąca.', title_pt = 'Um diálogo rápido 🤖', body_pt = 'Porque é que, de repente, recusa as sestas? Não tem tempo para ler artigos longos. Escreva a pergunta diretamente ao Anacan AI e receba uma resposta concreta e curta sobre a regressão do sono dos 3 meses.', title_sv = 'Snabb dialog 🤖', body_sv = 'Varför vägrar barnet plötsligt att sova på dagen? Du har inte tid att läsa långa artiklar. Skriv frågan direkt till Anacan AI och få ett konkret, kort svar om sömnregressionen vid 3 månader.', title_vi = 'Trò chuyện nhanh 🤖', body_vi = 'Vì sao bé đột nhiên không chịu ngủ ngày? Mẹ không có thời gian đọc bài dài. Hãy hỏi thẳng Anacan AI và nhận câu trả lời ngắn gọn, cụ thể về khủng hoảng giấc ngủ 3 tháng.', title_zh = '快速对话 🤖', body_zh = '宝宝为什么突然不肯白天小睡了？你没时间读长篇文章。直接把问题发给Anacan AI，获得关于3个月睡眠倒退的具体简短回答。' WHERE id = '0d132ba6-d6e9-44f6-a85d-e139c66b9760' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La filosofía del cuento 🪄', body_es = '¡Cuentos inteligentes vuelve a la carga! Escribe en el sistema: «La historia del hada que se cansaba de jugar de día y tenía sueños preciosos de noche». Quizá mientras lo lees seas tú la que se quede dormida.', title_fr = 'La philosophie des contes 🪄', body_fr = 'Les Contes intelligents sont de retour ! Écrivez : « L''histoire de la fée fatiguée de jouer le jour, qui fait de beaux rêves la nuit ». Peut-être vous endormirez-vous vous-même en la lisant.', title_hi = 'कहानी का फ़लसफ़ा 🪄', body_hi = 'स्मार्ट कहानियाँ फिर से काम पर हैं! सिस्टम में लिखिए: “दिन भर खेलकर थक जाने वाली और रात को सुंदर सपने देखने वाली परी की कहानी”। पढ़ते-पढ़ते शायद आप भी सो जाएँ।', title_id = 'Filosofi dongeng 🪄', body_id = 'Dongeng Pintar kembali beraksi! Tulis di sistem: “Kisah peri yang lelah bermain sepanjang siang dan bermimpi indah di malam hari”. Siapa tahu Anda sendiri ikut tertidur saat membacanya.', title_ja = 'おはなしの哲学 🪄', body_ja = '「スマートおはなし」がまた活躍します！入力してみましょう：「昼間は遊び疲れて、夜はすてきな夢を見る妖精のお話」。読んでいるうちに、あなたも眠ってしまうかも。', title_ko = '동화의 철학 🪄', body_ko = '스마트 동화가 다시 나섰어요! 이렇게 적어 보세요: “낮에는 놀다 지치고 밤에는 예쁜 꿈을 꾸는 요정 이야기”. 읽다 보면 엄마가 먼저 잠들지도 몰라요.', title_nl = 'De filosofie van sprookjes 🪄', body_nl = 'Slimme sprookjes is weer aan het werk! Typ: “Het verhaal van een fee die overdag moe wordt van het spelen en ’s nachts mooie dromen heeft”. Misschien val je zelf in slaap terwijl je voorleest.', title_pl = 'Filozofia bajki 🪄', body_pl = 'Mądre bajki znów w akcji! Wpisz: „Historia wróżki, która za dnia męczy się zabawą, a nocą śni piękne sny”. Może podczas czytania sama zaśniesz.', title_pt = 'A filosofia das histórias 🪄', body_pt = 'As Histórias Inteligentes voltam ao trabalho! Escreva no sistema: "A história da fada que se cansa a brincar durante o dia e tem sonhos lindos à noite". Talvez, enquanto lê, a própria mãe adormeça.', title_sv = 'Sagans filosofi 🪄', body_sv = 'Smarta sagor är i farten igen! Skriv in: ''Berättelsen om älvan som blir trött av att leka på dagarna och drömmer vackra drömmar på natten''. Kanske somnar du själv medan du läser.', title_vi = 'Triết lý cổ tích 🪄', body_vi = 'Truyện cổ tích thông minh lại vào việc rồi! Hãy nhập: “Câu chuyện về nàng tiên ban ngày chơi đùa mệt nhoài, ban đêm mơ những giấc mơ đẹp”. Đọc mãi, có khi chính mẹ cũng thiếp đi.', title_zh = '童话哲学 🪄', body_zh = '智慧童话又上岗啦！在系统里输入：“白天玩累了、晚上做美梦的小仙女的故事”。读着读着，说不定你自己也睡着了。' WHERE id = '3d40ac30-86f9-4dfc-9db8-efd1a5dd1198' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ropa que desafía la lógica 👗', body_es = '¿A veces lo abrigas demasiado poco y otras demasiado? No dudes. En lugar de mirar por la ventana, consulta ya Tiempo y ropa y respira tranquila con la propuesta de capas que te da el sistema.', title_fr = 'Des tenues illogiques 👗', body_fr = 'Parfois vous le couvrez trop peu, parfois trop ? Pas d''hésitation. Au lieu de regarder par la fenêtre, consultez tout de suite Météo et tenue et respirez grâce à la suggestion de tenue en couches proposée.', title_hi = 'उलझन भरे कपड़े 👗', body_hi = 'कभी बहुत ठंड लगवा देती हैं, कभी बहुत गर्म कपड़े पहना देती हैं? हिचकिचाइए मत। खिड़की से देखने के बजाय तुरंत मौसम और कपड़े देखिए, और सिस्टम के परत-दर-परत कपड़ों के सुझाव से चैन की साँस लीजिए।', title_id = 'Pakaian yang membingungkan 👗', body_id = 'Kadang terlalu tipis, kadang terlalu tebal memakaikan baju? Jangan ragu. Daripada melihat dari jendela, langsung cek Cuaca dan Pakaian, dan bernapaslah lega dengan saran pakaian berlapis dari sistem.', title_ja = '迷ってしまう服装 👗', body_ja = '寒くさせすぎたり、厚着させすぎたりしていませんか？迷わないで。窓の外を見る代わりにすぐ「天気と服装」をチェックして、提案される重ね着のアドバイスで安心しましょう。', title_ko = '엉뚱한 옷차림 👗', body_ko = '가끔은 너무 춥게, 가끔은 너무 덥게 입히나요? 망설이지 마세요. 창밖을 보는 대신 바로 날씨와 옷차림을 확인하고, 앱이 알려 주는 겹쳐 입기 제안으로 마음 편히 지내세요.', title_nl = 'Onlogische kleding 👗', body_nl = 'Kleed je je baby soms te koud en soms te warm aan? Twijfel niet. Kijk niet door het raam, maar meteen in Weer en kleding en adem rustig met het laagjesadvies van het systeem.', title_pl = 'Ubrania wbrew logice 👗', body_pl = 'Czasem ubierasz za lekko, a czasem za ciepło? Nie wahaj się. Zamiast patrzeć przez okno, od razu sprawdź Pogodę i ubiór i odetchnij z ulgą dzięki propozycji ubioru na cebulkę.', title_pt = 'Roupa sem lógica 👗', body_pt = 'Às vezes ele fica com frio, outras vezes veste-o com roupa quente demais? Não hesite. Em vez de olhar pela janela, consulte já o Tempo e Roupa e respire de alívio com a sugestão de camadas que o sistema lhe dá.', title_sv = 'Kläder som trotsar logiken 👗', body_sv = 'Klär du ibland barnet för kallt och ibland för varmt? Tveka inte. I stället för att titta ut genom fönstret, kolla direkt Väder och kläder och andas ut med systemets förslag på lager-på-lager.', title_vi = 'Mặc đồ trái lẽ thường 👗', body_vi = 'Lúc thì để bé quá lạnh, lúc lại mặc quá ấm? Đừng phân vân. Thay vì nhìn qua cửa sổ, hãy xem ngay Thời tiết và trang phục và yên tâm với gợi ý mặc nhiều lớp của hệ thống.', title_zh = '不合逻辑的穿衣 👗', body_zh = '有时穿得太少着凉，有时又穿得太多？别犹豫。与其看窗外，不如马上查看天气与穿衣，跟着系统的分层穿衣建议，安心呼吸。' WHERE id = '6c6289cf-6e7c-4e83-a178-d01d67cef488' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Somos un equipo! 💖', title_fr = 'Nous sommes une équipe ! 💖', title_hi = 'हम एक टीम हैं! 💖', title_id = 'Kita satu tim! 💖', title_ja = 'わたしたちはチームです！💖', title_ko = '우리는 한 팀이에요! 💖', title_nl = 'Wij zijn een team! 💖', title_pl = 'Jesteśmy drużyną! 💖', title_pt = 'Somos uma equipa! 💖', title_sv = 'Vi är ett lag! 💖', title_vi = 'Chúng mình là một đội! 💖', title_zh = '我们是一个团队！💖' WHERE id = 'ce7b77f8-95b5-4071-bf35-61b06d785d85' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Protege su sueño con el Medidor de sonido 🤫', body_es = 'Estás emocionada y en casa hay preparativos, pero el sueño del bebé tampoco debe alterarse. Deja el Medidor de sonido encendido en la habitación y ve al instante si el ruido supera el límite.', title_fr = 'Protégez son sommeil avec le Sonomètre 🤫', body_fr = 'L''excitation est là, les préparatifs vont bon train à la maison, mais le sommeil de bébé ne doit pas être perturbé. Laissez le Sonomètre allumé dans la pièce et voyez immédiatement quand le bruit dépasse la limite.', title_hi = 'साउंड मीटर से नींद की रक्षा कीजिए 🤫', body_hi = 'आप उत्साहित हैं, घर में तैयारी चल रही है, पर बच्चे की नींद नहीं टूटनी चाहिए। कमरे में साउंड मीटर चालू रखिए और तुरंत देखिए कि शोर सीमा से ऊपर तो नहीं गया।', title_id = 'Lindungi tidurnya dengan pengukur suara 🤫', body_id = 'Anda bersemangat, persiapan sedang berlangsung di rumah, tapi tidur bayi juga tidak boleh terganggu. Biarkan Pengukur Suara menyala di kamar dan langsung lihat jika kebisingan melewati batas.', title_ja = 'サウンドメーターで眠りを守りましょう 🤫', body_ja = 'ワクワクしていて、家では準備が進んでいる。でも赤ちゃんの眠りはさまたげたくないですよね。部屋で「サウンドメーター」をオンにしておけば、音量が限度を超えたときすぐにわかります。', title_ko = '소음 측정기로 잠을 지켜요 🤫', body_ko = '설레는 마음에 집에서 준비가 한창이지만 아기의 잠은 방해받지 않아야 해요. 방에 소음 측정기를 켜 두고 소음이 기준을 넘는지 바로 확인하세요.', title_nl = 'Bescherm de slaap met de geluidsmeter 🤫', body_nl = 'Je bent opgewonden en er wordt thuis van alles voorbereid, maar de slaap van je baby mag niet verstoord worden. Laat de Geluidsmeter aan staan in de kamer en zie meteen wanneer het lawaai de grens overschrijdt.', title_pl = 'Chroń sen Miernikiem dźwięku 🤫', body_pl = 'Jesteś podekscytowana, w domu trwają przygotowania, ale sen dziecka nie może być zakłócony. Zostaw Miernik dźwięku włączony w pokoju i od razu zobacz, gdy hałas przekroczy limit.', title_pt = 'Proteja o sono com o medidor de som 🤫', body_pt = 'Está entusiasmada, há preparativos em casa, mas o sono do bebé não pode ser perturbado. Deixe o Medidor de Som ligado no quarto e veja de imediato quando o barulho ultrapassa o limite.', title_sv = 'Skydda sömnen med ljudmätaren 🤫', body_sv = 'Du är förväntansfull och förberedelserna pågår hemma, men barnets sömn får inte störas. Låt Ljudmätaren vara på i rummet och se direkt när oljudet överskrider gränsen.', title_vi = 'Bảo vệ giấc ngủ bằng Đo âm thanh 🤫', body_vi = 'Mẹ đang háo hức, cả nhà đang chuẩn bị, nhưng giấc ngủ của bé cũng không được bị xáo trộn. Hãy để Đo âm thanh bật trong phòng và biết ngay khi tiếng ồn vượt ngưỡng.', title_zh = '用分贝仪守护睡眠 🤫', body_zh = '你很激动，家里正在忙着准备，但宝宝的睡眠也不能被打扰。在房间里开着分贝仪，噪音超过限度时立刻就能看到。' WHERE id = '132d4620-5085-4072-ac1e-81f46dc4e74c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Alimentos que favorecen tu leche. 🍲', title_fr = 'Des aliments qui soutiennent la lactation. 🍲', title_hi = 'दूध में मदद करने वाले खाने। 🍲', title_id = 'Makanan yang mendukung ASI Anda. 🍲', title_ja = '母乳をサポートする食べ物。🍲', title_ko = '모유를 도와주는 음식. 🍲', title_nl = 'Voeding die je melkproductie ondersteunt. 🍲', title_pl = 'Produkty wspierające laktację. 🍲', title_pt = 'Alimentos que ajudam a produção de leite. 🍲', title_sv = 'Mat som stödjer din mjölk. 🍲', title_vi = 'Thực phẩm hỗ trợ nguồn sữa. 🍲', title_zh = '支持奶水的食物。🍲' WHERE id = 'ccbd5c11-509e-4b73-9eb1-b2f8b729e5b5' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de sonidos contra la inquietud. 🎶', title_fr = 'Une thérapie sonore contre l''agitation. 🎶', title_hi = 'बेचैनी के लिए साउंड थेरेपी। 🎶', title_id = 'Terapi suara untuk rewel. 🎶', title_ja = 'ぐずりに効くサウンドセラピー。🎶', title_ko = '보챌 때 소리 테라피. 🎶', title_nl = 'Geluidstherapie tegen onrust. 🎶', title_pl = 'Terapia dźwiękiem na niepokój. 🎶', title_pt = 'Terapia de sons contra a agitação. 🎶', title_sv = 'Ljudterapi mot oro. 🎶', title_vi = 'Liệu pháp âm thanh xoa dịu bé quấy. 🎶', title_zh = '缓解不安的声音疗法。🎶' WHERE id = '72b7b721-7f37-4054-90fd-05ac29f9ff3c' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Enhorabuena! 🥂', body_es = 'Echa la vista atrás a todas tus anotaciones y gráficos de desarrollo. Mira cuánto ha crecido y lo fuerte que te has vuelto tú. ¡Es el momento perfecto para sentirte orgullosa de ti!', title_fr = 'Félicitations ! 🥂', body_fr = 'Retournez-vous sur toutes vos notes et vos courbes de croissance. Voyez combien il a grandi, et combien vous êtes devenue forte. C''est le moment d''être fière de vous !', title_hi = 'बधाई हो! 🥂', body_hi = 'अपने सारे रिकॉर्ड और ग्रोथ चार्ट पीछे मुड़कर देखिए। देखिए वह कितना बड़ा हो गया, और आप कितनी मज़बूत हो गईं। खुद पर गर्व करने का यही सही समय है!', title_id = 'Selamat! 🥂', body_id = 'Lihat kembali semua catatan dan grafik pertumbuhan Anda. Lihat seberapa besar ia tumbuh, dan seberapa kuat Anda kini. Saatnya bangga pada diri sendiri!', title_ja = 'おめでとうございます！🥂', body_ja = 'これまでの記録や成長グラフをふり返ってみましょう。赤ちゃんがどれだけ大きくなり、あなたがどれだけ強くなったか見てください。自分を誇りに思うのにぴったりのときです！', title_ko = '축하해요! 🥂', body_ko = '지금까지의 모든 기록과 성장 그래프를 돌아보세요. 아기가 얼마나 자랐는지, 엄마가 얼마나 강해졌는지 확인해 보세요. 스스로를 자랑스러워할 때예요!', title_nl = 'Gefeliciteerd! 🥂', body_nl = 'Kijk terug op al je notities en groeigrafieken. Zie hoeveel je baby is gegroeid en hoe sterk jij bent geworden. Hét moment om trots te zijn op jezelf!', title_pl = 'Gratulacje! 🥂', body_pl = 'Spójrz wstecz na wszystkie swoje zapisy i wykresy rozwoju. Zobacz, jak bardzo maleństwo urosło, a ty jak bardzo się wzmocniłaś. To idealny moment, by być z siebie dumną!', title_pt = 'Parabéns! 🥂', body_pt = 'Olhe para trás para todos os seus registos e gráficos de crescimento. Veja quanto ele cresceu e como a mãe ficou mais forte. É o momento certo para se orgulhar de si mesma!', title_sv = 'Grattis! 🥂', body_sv = 'Blicka tillbaka på alla dina anteckningar och tillväxtkurvor. Se hur mycket barnet har vuxit och hur mycket starkare du har blivit. Nu är det perfekt tid att vara stolt över dig själv!', title_vi = 'Chúc mừng! 🥂', body_vi = 'Hãy nhìn lại mọi ghi chép, mọi biểu đồ phát triển. Thấy bé đã lớn thế nào, còn mẹ đã mạnh mẽ ra sao. Đây là lúc tự hào về bản thân!', title_zh = '恭喜！🥂', body_zh = '回顾一下你所有的记录和成长曲线。看看宝宝长大了多少，你又变得多么坚强。现在正是为自己骄傲的时候！' WHERE id = '9877e456-4a5e-45a3-aee9-e9703be5cf91' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El momento de victoria del equipo 💖', body_es = 'Has dormido al bebé con ese temporizador de sueño especial. Ahora siéntate frente a tu pareja. Daos las gracias por cada momento de estos 90 días. ¡No son solo 3 meses del bebé, también son 3 meses de vuestra paternidad y maternidad!', title_fr = 'Le moment de victoire de l''équipe 💖', body_fr = 'Vous avez couché bébé avec ce minuteur de sommeil spécial. Maintenant, asseyez-vous face à votre conjoint. Remerciez-vous mutuellement pour chaque instant de ces 90 jours. Ce ne sont pas seulement les 3 mois de bébé, mais aussi vos 3 mois de parents !', title_hi = 'टीम की जीत का पल 💖', body_hi = 'आपने बच्चे को उस खास स्लीप टाइमर के साथ सुला दिया। अब अपने साथी के आमने-सामने बैठिए। इन 90 दिनों के हर पल के लिए एक-दूसरे का शुक्रिया अदा कीजिए। ये सिर्फ़ बच्चे के नहीं, आपकी पेरेंटिंग के भी 3 महीने हैं!', title_id = 'Momen kemenangan tim 💖', body_id = 'Anda sudah menidurkan bayi dengan pengatur waktu tidur khusus itu. Sekarang duduklah berhadapan dengan pasangan. Saling berterima kasihlah untuk setiap momen dalam 90 hari ini. Ini bukan hanya 3 bulan untuk anak, tapi juga 3 bulan Anda menjadi orang tua!', title_ja = 'チームの勝利の瞬間 💖', body_ja = 'あの特別な睡眠タイマーで赤ちゃんを寝かせたら、パートナーと向かい合って座りましょう。この90日間のすべての瞬間に、お互いありがとうを伝えて。これは赤ちゃんだけでなく、あなたたちが親になって3か月でもあるのです！', title_ko = '팀의 승리의 순간 💖', body_ko = '그 특별한 수면 타이머로 아기를 재웠나요? 이제 배우자와 마주 앉으세요. 이 90일의 모든 순간에 서로 고마움을 전하세요. 이건 아기의 3개월이자 두 사람이 부모가 된 3개월이에요!', title_nl = 'Het overwinningsmoment van het team 💖', body_nl = 'Je hebt je baby in slaap gebracht met die speciale slaaptimer. Ga nu tegenover je partner zitten. Bedank elkaar voor elk moment van deze 90 dagen. Het zijn niet alleen 3 maanden van je kind, maar ook 3 maanden van jullie ouderschap!', title_pl = 'Chwila zwycięstwa drużyny 💖', body_pl = 'Uśpiłaś dziecko z tym wyjątkowym timerem snu. Teraz usiądź z partnerem twarzą w twarz. Podziękujcie sobie nawzajem za każdą chwilę tych 90 dni. To nie tylko 3 miesiące dziecka, ale też 3 miesiące waszego rodzicielstwa!', title_pt = 'O momento de vitória da equipa 💖', body_pt = 'Adormeceu o bebé com aquele temporizador de sono especial. Agora sente-se frente a frente com o seu companheiro. Agradeçam um ao outro por cada momento destes 90 dias. Não são só 3 meses do bebé, são também 3 meses da vossa parentalidade!', title_sv = 'Lagets segerstund 💖', body_sv = 'Du har nattat barnet med den särskilda sömntimern. Sätt dig nu mitt emot din partner. Tacka varandra för varje stund av de här 90 dagarna. Det är inte bara barnets 3 månader, utan också 3 månader av ert föräldraskap!', title_vi = 'Khoảnh khắc chiến thắng của cả đội 💖', body_vi = 'Mẹ đã ru bé ngủ với bộ hẹn giờ ngủ đặc biệt ấy. Giờ hãy ngồi đối diện với chồng. Cảm ơn nhau vì từng khoảnh khắc của 90 ngày qua. Đây không chỉ là 3 tháng của bé, mà còn là 3 tháng làm cha mẹ của hai người!', title_zh = '团队的胜利时刻 💖', body_zh = '你用那个特别的睡眠计时器哄宝宝睡着了。现在和另一半面对面坐下来，为这90天的每一刻互相道谢。这不只是宝宝的3个月，也是你们为人父母的3个月！' WHERE id = '9b7b163b-1de2-4ecd-becc-21f1f3c0e10e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tu propio cuento especial 🪄', body_es = 'Esta noche demos a la herramienta Cuentos inteligentes un tema tierno: «La historia de la estrella más dulce que cayó del cielo». Que en la habitación solo se oiga este cuento y un silencio absoluto.', title_fr = 'Votre conte bien à vous 🪄', body_fr = 'Ce soir, donnons un joli thème à l''outil Contes intelligents : « L''histoire de la plus douce étoile tombée du ciel ». Que seuls la voix de ce conte et un silence absolu remplissent la pièce.', title_hi = 'आपकी अपनी खास कहानी 🪄', body_hi = 'आज शाम स्मार्ट कहानियाँ टूल को एक प्यारा विषय दें: “आसमान से गिरे सबसे प्यारे सितारे की कहानी”। कमरे में बस इस कहानी की आवाज़ और पूरी खामोशी रहे।', title_id = 'Dongeng istimewa Anda sendiri 🪄', body_id = 'Malam ini beri alat Dongeng Pintar tema yang manis: “Kisah bintang termanis yang jatuh dari langit”. Biarkan hanya suara dongeng ini dan keheningan total yang memenuhi kamar.', title_ja = 'あなただけの特別なお話 🪄', body_ja = '今夜は「スマートおはなし」にかわいいテーマを出しましょう：「空から落ちてきた、いちばんかわいい星のお話」。部屋の中は、このお話の声と静けさだけで満たしましょう。', title_ko = '나만의 특별한 동화 🪄', body_ko = '오늘 저녁 스마트 동화에 사랑스러운 주제를 줘 봐요: “하늘에서 떨어진 가장 달콤한 별 이야기”. 방 안에 이 동화 소리와 완전한 고요함만 흐르게 하세요.', title_nl = 'Je eigen speciale sprookje 🪄', body_nl = 'Laten we Slimme sprookjes vanavond een lief thema geven: “Het verhaal van het liefste sterretje dat uit de hemel viel”. Laat alleen het geluid van dit sprookje en volledige stilte de kamer vullen.', title_pl = 'Twoja własna bajka 🪄', body_pl = 'Dziś wieczorem dajmy Mądrym bajkom słodki temat: „Historia najsłodszej gwiazdki, która spadła z nieba”. Niech w pokoju rozbrzmiewa tylko ta bajka i panuje zupełna cisza.', title_pt = 'A sua história especial 🪄', body_pt = 'Esta noite, vamos dar às Histórias Inteligentes um tema ternurento: "A história da estrela mais doce que caiu do céu". Que no quarto se ouça apenas a voz desta história e silêncio absoluto.', title_sv = 'Din egen speciella saga 🪄', body_sv = 'I kväll ger vi verktyget Smarta sagor ett sött tema: ''Berättelsen om den sötaste stjärnan som föll från himlen''. Låt bara ljudet av den här sagan och total tystnad fylla rummet.', title_vi = 'Câu chuyện cổ tích của riêng mẹ 🪄', body_vi = 'Tối nay hãy giao cho Truyện cổ tích thông minh một chủ đề ngọt ngào: “Câu chuyện về ngôi sao đáng yêu nhất rơi xuống từ bầu trời”. Để trong phòng chỉ còn tiếng câu chuyện này và sự tĩnh lặng tuyệt đối.', title_zh = '你的专属童话 🪄', body_zh = '今晚给智慧童话一个甜蜜的主题：“从天上掉下来的最甜的小星星的故事”。让房间里只有这个故事的声音和绝对的安静。' WHERE id = '5c67089a-581e-455d-b113-f87f427babb2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El terreno de papá 👨‍👧', body_es = '¿Se te ha agotado la paciencia? Hoy pásale el turno a tu pareja durante un rato. Que pasen un poco de tiempo a solas, y tú simplemente estira las piernas y descansa.', title_fr = 'Le terrain de jeu de Papa 👨‍👧', body_fr = 'À bout de patience ? Aujourd''hui, passez le relais à votre conjoint pour un petit moment. Laissez-les passer un peu de temps en tête-à-tête, et vous, allongez simplement vos jambes et reposez-vous.', title_hi = 'पापा का मैदान 👨‍👧', body_hi = 'धैर्य जवाब दे रहा है? आज थोड़ी देर के लिए माँ की ड्यूटी अपने साथी को सौंप दीजिए। उन्हें थोड़ा साथ में समय बिताने दीजिए, और आप बस पैर फैलाकर आराम कीजिए।', title_id = 'Arena bermain Ayah 👨‍👧', body_id = 'Kesabaran mulai habis? Hari ini serahkan giliran mengasuh kepada pasangan Anda sebentar. Biarkan mereka menghabiskan waktu berdua, sementara Anda cukup meluruskan kaki dan beristirahat.', title_ja = 'パパの出番 👨‍👧', body_ja = '心の余裕がなくなっていますか？今日は少しの間、育児の当番をパートナーにバトンタッチしましょう。2人でゆっくり過ごしてもらって、あなたは足を伸ばして休んでください。', title_ko = '아빠의 놀이터 👨‍👧', body_ko = '인내심이 바닥났나요? 오늘은 잠시 육아 당번을 배우자에게 넘기세요. 둘만의 시간을 보내게 하고, 엄마는 다리를 쭉 뻗고 쉬기만 하세요.', title_nl = 'Papa’s speelveld 👨‍👧', body_nl = 'Is je geduld op? Geef de zorg vandaag even over aan je partner. Laat hen samen wat tijd doorbrengen, en leg jij gewoon je benen omhoog en rust uit.', title_pl = 'Plac zabaw taty 👨‍👧', body_pl = 'Kończy ci się cierpliwość? Dziś na chwilę przekaż maminą zmianę partnerowi. Niech pobędą trochę sam na sam, a ty po prostu wyciągnij nogi i odpocznij.', title_pt = 'O recreio do pai 👨‍👧', body_pt = 'A paciência está a esgotar-se? Hoje, passe por pouco tempo o turno de mãe ao seu companheiro. Deixe-os passar um pouco de tempo a sós, e a mãe só tem de esticar as pernas e descansar.', title_sv = 'Pappas lekplats 👨‍👧', body_sv = 'Börjar tålamodet tryta? Lämna över mammapasset till din partner en kort stund i dag. Låt dem få lite egen tid tillsammans, och du lägger bara upp fötterna och vilar.', title_vi = 'Sân chơi của bố 👨‍👧', body_vi = 'Mẹ hết kiên nhẫn rồi? Hôm nay hãy tạm giao ca làm mẹ cho chồng một lúc. Để hai bố con có thời gian riêng bên nhau, còn mẹ chỉ việc duỗi chân và nghỉ ngơi.', title_zh = '爸爸的游乐场 👨‍👧', body_zh = '耐心快用完了？今天把带娃的班短暂交给另一半吧。让他们单独相处一会儿，你只管把腿伸直，好好休息。' WHERE id = '66bd508e-0413-4d01-9ea7-c369b0d8cafa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hora de carcajadas! 😂', body_es = '¡Ya no solo sonríe, se ríe a carcajadas! Juega con él, hazle cosquillas en la barriga. Ese sonido es la mejor recompensa por todas las noches sin dormir.', title_fr = 'L''heure des éclats de rire ! 😂', body_fr = 'Il ne se contente plus de sourire, il éclate de rire ! Jouez avec lui, chatouillez son ventre. Ce son est la plus belle récompense de toutes ces nuits blanches.', title_hi = 'ठहाकों का समय! 😂', body_hi = 'अब वह सिर्फ़ मुस्कुराता नहीं, खिलखिलाकर हँसता है! उसके साथ खेलिए, उसके पेट में गुदगुदी कीजिए। यह आवाज़ जागी हुई सारी रातों का सबसे सुंदर इनाम है।', title_id = 'Waktunya tertawa! 😂', body_id = 'Kini ia tidak hanya tersenyum, tapi tertawa terbahak-bahak! Bermainlah bersamanya, gelitik perutnya. Suara ini adalah hadiah terindah untuk semua malam tanpa tidur.', title_ja = '大笑いの時間！😂', body_ja = 'もうにっこりするだけでなく、声を出して笑います！一緒に遊んだり、お腹をくすぐったりしてみましょう。この声は、眠れなかったすべての夜へのいちばんのごほうびです。', title_ko = '까르르 웃음 시간! 😂', body_ko = '이제 그냥 미소 짓는 게 아니라 소리 내어 까르르 웃어요! 함께 놀아 주고 배를 간지럽혀 보세요. 이 소리는 잠 못 든 모든 밤에 대한 가장 아름다운 보상이에요.', title_nl = 'Tijd om te schateren! 😂', body_nl = 'Je baby glimlacht niet alleen meer, maar lacht hardop! Speel spelletjes en kietel het buikje. Dit geluid is de mooiste beloning voor alle slapeloze nachten.', title_pl = 'Czas na śmiech! 😂', body_pl = 'Już nie tylko się uśmiecha, ale głośno się śmieje! Bawcie się razem, połaskocz go po brzuszku. Ten dźwięk to najpiękniejsza nagroda za wszystkie nieprzespane noce.', title_pt = 'Hora das gargalhadas! 😂', body_pt = 'Já não se limita a sorrir, dá gargalhadas bem audíveis! Brinque com ele e faça-lhe cócegas na barriga. Este som é a melhor recompensa por todas as noites sem dormir.', title_sv = 'Dags för skratt! 😂', body_sv = 'Nu ler barnet inte bara, det skrattar högt! Lek med barnet och kittla magen. Det ljudet är den finaste belöningen för alla sömnlösa nätter.', title_vi = 'Giờ cười giòn tan! 😂', body_vi = 'Bé không chỉ mỉm cười nữa, mà đã cười thành tiếng! Hãy chơi với bé, cù bụng bé. Tiếng cười này là phần thưởng đẹp nhất cho mọi đêm mất ngủ.', title_zh = '哈哈大笑时间！😂', body_zh = '宝宝已经不只是微笑，而是会咯咯大笑了！和宝宝玩游戏，挠挠宝宝的小肚子。这笑声是对所有不眠之夜最好的奖励。' WHERE id = '8474a75e-7aaf-420e-b5ab-acd7d55ac51c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Señales de sueño 🥱', body_es = '¿Se frota los ojos, se tira de la oreja o mira al vacío? No esperes a la crisis nocturna. En cuanto veas estas señales, oscurece la habitación y empieza la rutina de sueño.', title_fr = 'Les signaux du sommeil 🥱', body_fr = 'Il se frotte les yeux, se tire l''oreille ou regarde dans le vide ? N''attendez pas la crise du soir. Dès que vous voyez ces signaux, faites le noir dans la chambre et commencez la routine du coucher.', title_hi = 'नींद के संकेत 🥱', body_hi = 'आँखें मलता है, कान खींचता है या खाली जगह में ताकता है? रात के रोने-धोने का इंतज़ार मत कीजिए। ये संकेत दिखते ही कमरे में अँधेरा करके नींद का रूटीन शुरू कीजिए।', title_id = 'Tanda-tanda mengantuk 🥱', body_id = 'Ia mengucek mata, menarik telinga, atau menatap kosong? Jangan tunggu rewel malam datang. Begitu melihat tanda-tanda ini, segera gelapkan kamar dan mulai rutinitas tidur.', title_ja = '眠いサイン 🥱', body_ja = '目をこすったり、耳を引っぱったり、ぼんやり宙を見つめたりしていますか？夜のぐずりを待たずに、このサインに気づいたらすぐに部屋を暗くして、寝かしつけのルーティンを始めましょう。', title_ko = '졸음 신호 🥱', body_ko = '눈을 비비거나, 귀를 잡아당기거나, 멍하니 허공을 보나요? 밤 보챔을 기다리지 마세요. 이런 신호가 보이면 바로 방을 어둡게 하고 수면 루틴을 시작하세요.', title_nl = 'Slaapsignalen 🥱', body_nl = 'Wrijft je baby in de ogen, trekt hij aan zijn oor of staart hij voor zich uit? Wacht niet op de avondhuilbui. Zie je deze signalen, maak dan meteen de kamer donker en begin met het slaapritueel.', title_pl = 'Sygnały senności 🥱', body_pl = 'Przeciera oczy, ciągnie się za ucho lub patrzy w pustkę? Nie czekaj na wieczorny kryzys. Gdy tylko zobaczysz te sygnały, od razu zaciemnij pokój i zacznij rutynę przed snem.', title_pt = 'Sinais de sono 🥱', body_pt = 'Esfrega os olhos, puxa a orelha ou fica a olhar para o vazio? Não espere pela crise da noite. Mal veja estes sinais, escureça o quarto e comece a rotina do sono.', title_sv = 'Sömnsignaler 🥱', body_sv = 'Gnuggar barnet ögonen, drar i örat eller stirrar ut i tomma intet? Vänta inte på nattkrisen. Så fort du ser de här signalerna, mörklägg rummet och börja sömnrutinen.', title_vi = 'Tín hiệu buồn ngủ 🥱', body_vi = 'Bé dụi mắt, kéo tai hay nhìn vào khoảng không? Đừng đợi đến cơn quấy đêm. Thấy những tín hiệu này là hãy làm tối phòng và bắt đầu nếp ngủ ngay.', title_zh = '犯困信号 🥱', body_zh = '揉眼睛、拽耳朵，还是发呆？别等到夜里大哭。一看到这些信号，就马上调暗房间，开始睡前程序。' WHERE id = '0027b4ad-2816-4a79-ae3a-7ddbdcf29e4b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Exploración con la boca 🤤', body_es = '¿Se lleva directamente a la boca las manos, los juguetes y todo lo que encuentra? Es su forma de descubrir el mundo. No se lo quites todo, solo asegúrate de que lo que le rodea esté limpio.', title_fr = 'Exploration buccale 🤤', body_fr = 'Il porte ses mains, ses jouets, tout ce qu''il trouve directement à sa bouche ? C''est sa façon de découvrir le monde. Ne lui retirez pas tout, assurez-vous simplement que les objets autour de lui sont propres.', title_hi = 'मुँह से खोजबीन 🤤', body_hi = 'हाथ, खिलौने, जो भी मिले सीधे मुँह में ले जाता है? यह दुनिया को जानने का उसका तरीका है। हर चीज़ उससे छीनिए मत, बस पक्का कीजिए कि आसपास की चीज़ें साफ़ हैं।', title_id = 'Penjelajahan lewat mulut 🤤', body_id = 'Tangan, mainan, apa pun yang ia temukan langsung masuk ke mulut? Inilah caranya mengenal dunia. Jangan ambil semuanya dari tangannya, cukup pastikan benda-benda di sekitarnya bersih.', title_ja = 'お口で探検 🤤', body_ja = '手やおもちゃ、見つけたものを何でも口に入れていますか？これは赤ちゃんが世界を知る方法です。全部取り上げないで、まわりのものが清潔かどうかだけ気をつけましょう。', title_ko = '입으로 하는 탐험 🤤', body_ko = '손이며 장난감이며 잡히는 건 모두 입으로 가져가나요? 이건 아기가 세상을 알아가는 방법이에요. 모두 빼앗지 말고 주변 물건이 깨끗한지만 확인하세요.', title_nl = 'Ontdekken met het mondje 🤤', body_nl = 'Stopt je baby de handjes, het speelgoed en alles wat hij vindt meteen in zijn mond? Zo ontdekt hij de wereld. Pak niet alles af, zorg er gewoon voor dat de dingen om hem heen schoon zijn.', title_pl = 'Odkrywanie buzią 🤤', body_pl = 'Rączki, zabawki, wszystko, co znajdzie, wkłada prosto do buzi? To jego sposób na poznawanie świata. Nie zabieraj mu wszystkiego, po prostu dbaj, by przedmioty wokół były czyste.', title_pt = 'Exploração com a boca 🤤', body_pt = 'Leva as mãos, os brinquedos e tudo o que encontra diretamente à boca? É a forma dele de descobrir o mundo. Não lhe tire tudo das mãos, basta garantir que os objetos à volta estão limpos.', title_sv = 'Utforskning med munnen 🤤', body_sv = 'Stoppar barnet händerna, leksakerna och allt det hittar direkt i munnen? Det är barnets sätt att upptäcka världen. Ta inte ifrån det allt, se bara till att sakerna runt omkring är rena.', title_vi = 'Khám phá bằng miệng 🤤', body_vi = 'Tay, đồ chơi, bất cứ thứ gì bé tìm thấy đều cho thẳng vào miệng? Đây là cách bé khám phá thế giới. Đừng giật hết khỏi tay bé, chỉ cần đảm bảo đồ vật xung quanh sạch sẽ.', title_zh = '用嘴探索 🤤', body_zh = '小手、玩具，找到什么都直接往嘴里塞？这是宝宝认识世界的方式。不必什么都拿走，只要确保周围的物品干净就好。' WHERE id = '1867104a-7fa8-428a-ad5d-dd10e6890f0f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué está la casa tan desordenada? 🌪️', body_es = '¿Te culpas al ver el montón de juguetes en medio de la habitación y los platos sin fregar? Hoy deja esos platos donde están. ¡Criar a un bebé ya es un trabajo suficientemente grande!', title_fr = 'Pourquoi la maison est-elle si en désordre ? 🌪️', body_fr = 'Vous regardez la pile de jouets au milieu de la pièce et la vaisselle sale en vous le reprochant ? Aujourd''hui, laissez cette vaisselle là où elle est. Élever un enfant, c''est déjà un travail énorme !', title_hi = 'घर इतना बिखरा क्यों है? 🌪️', body_hi = 'कमरे के बीच खिलौनों के ढेर और बिना धुले बर्तनों को देखकर खुद को कोस रही हैं? आज वे बर्तन वहीं रहने दीजिए। बच्चा पालना अपने आप में बहुत बड़ा काम है!', title_id = 'Kenapa rumah berantakan sekali? 🌪️', body_id = 'Menyalahkan diri saat melihat tumpukan mainan di tengah kamar dan piring yang belum dicuci? Hari ini biarkan saja piring-piring itu di sana. Membesarkan anak sudah merupakan pekerjaan yang cukup besar!', title_ja = 'どうして家がこんなに散らかっているの？🌪️', body_ja = '部屋の真ん中のおもちゃの山や、洗っていないお皿を見て自分を責めていませんか？今日はそのお皿はそのままでいいのです。子育てだけで、もう十分大きな仕事なのですから！', title_ko = '집이 왜 이렇게 엉망일까요? 🌪️', body_ko = '방 한가운데 쌓인 장난감과 설거지 거리를 보며 자신을 탓하고 있나요? 오늘은 그 그릇들을 그냥 그 자리에 두세요. 아이를 키우는 것만으로도 충분히 큰일이에요!', title_nl = 'Waarom is het huis zo’n rommel? 🌪️', body_nl = 'Kijk je naar de berg speelgoed midden in de kamer en de vuile vaat en veroordeel je jezelf? Laat die afwas vandaag gewoon staan. Een kind opvoeden is al een enorme klus!', title_pl = 'Dlaczego w domu taki bałagan? 🌪️', body_pl = 'Patrzysz na stertę zabawek na środku pokoju i niepozmywane naczynia i masz do siebie żal? Niech dziś te naczynia zostaną tam, gdzie są. Wychowywanie dziecka to i tak wystarczająco wielka praca!', title_pt = 'Porque está a casa tão desarrumada? 🌪️', body_pt = 'Olha para o monte de brinquedos no meio do quarto e para a loiça por lavar e culpa-se? Hoje, deixe a loiça ficar onde está. Criar um filho já é um trabalho suficientemente grande!', title_sv = 'Varför är det så stökigt hemma? 🌪️', body_sv = 'Dömer du dig själv när du ser leksakshögen mitt i rummet och den odiskade disken? Låt disken stå kvar där den är i dag. Att ta hand om ett barn är redan ett tillräckligt stort jobb!', title_vi = 'Sao nhà bừa bộn thế này? 🌪️', body_vi = 'Mẹ nhìn đống đồ chơi giữa phòng, chồng bát đĩa chưa rửa và tự trách mình? Hôm nay cứ để bát đĩa ở đó. Nuôi con vốn đã là một việc đủ lớn rồi!', title_zh = '家里怎么这么乱？🌪️', body_zh = '看着房间中间的玩具堆和没洗的碗，在责怪自己吗？今天就让那些碗待在原地吧。养育孩子本身就已经是一项大工程了！' WHERE id = '4ad3cf84-0aac-46cb-bfdf-5a928764105a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ejercicios de volteo 🤸‍♂️', body_es = '¡Intenta darse la vuelta de espaldas a boca abajo! Es la gran lucha de un cuerpo pequeñito. Apoya estos intentos tan cómicos, pero ten mucho cuidado con los bordes de la cama.', title_fr = 'Exercices de retournement 🤸‍♂️', body_fr = 'Il essaie de passer du dos au ventre ! C''est le grand combat d''un petit corps. Encouragez ses tentatives comiques, mais faites bien attention aux bords du lit.', title_hi = 'करवट लेने की प्रैक्टिस 🤸‍♂️', body_hi = 'वह पीठ से पेट के बल पलटने की कोशिश कर रहा है! यह इस छोटे से शरीर की बड़ी लड़ाई है। उसकी इन मज़ेदार कोशिशों का साथ दीजिए, पर बिस्तर के किनारों पर ज़रूर सावधान रहिए।', title_id = 'Latihan berguling 🤸‍♂️', body_id = 'Ia mencoba berguling dari telentang ke tengkurap! Ini perjuangan besar tubuh mungil itu. Dukung usahanya yang lucu, tapi pastikan berhati-hati di tepi tempat tidur.', title_ja = '寝返りの練習 🤸‍♂️', body_ja = '赤ちゃんが仰向けからうつぶせに寝返ろうとしています！小さな体の大きな挑戦です。そのかわいい挑戦を応援しつつ、ベッドの端には必ず気をつけてくださいね。', title_ko = '뒤집기 연습 🤸‍♂️', body_ko = '아기가 등에서 배로 뒤집으려고 애쓰고 있어요! 작은 몸의 큰 도전이에요. 귀여운 시도를 응원하되, 침대 가장자리는 꼭 조심하세요.', title_nl = 'Omrol-oefeningen 🤸‍♂️', body_nl = 'Je baby probeert van de rug naar de buik te rollen! Een grote strijd voor dat kleine lijfje. Steun die grappige pogingen, maar let goed op bij de rand van het bed.', title_pl = 'Ćwiczymy przewroty 🤸‍♂️', body_pl = 'Próbuje przekręcić się z pleców na brzuch! To wielka walka tego małego ciałka. Wspieraj te zabawne próby, ale koniecznie uważaj na brzegi łóżka.', title_pt = 'Treino de rebolar 🤸‍♂️', body_pt = 'Está a tentar virar-se de costas para barriga para baixo! É a grande luta de um corpo pequenino. Apoie estas tentativas cómicas, mas tenha sempre cuidado com as bordas da cama.', title_sv = 'Rullövningar 🤸‍♂️', body_sv = 'Barnet försöker rulla från rygg till mage! Det är en stor kamp för en liten kropp. Uppmuntra de roliga försöken, men var alltid försiktig vid sängkanterna.', title_vi = 'Tập lật người 🤸‍♂️', body_vi = 'Bé đang cố lật từ ngửa sang sấp! Đây là cuộc chiến lớn của cơ thể bé nhỏ. Hãy cổ vũ những nỗ lực đáng yêu ấy, nhưng nhớ cẩn thận với mép giường.', title_zh = '翻身练习 🤸‍♂️', body_zh = '宝宝正努力从仰卧翻成趴着！这是小小身体的一场大挑战。支持宝宝可爱的尝试，但一定要特别注意床边。' WHERE id = '2e4ec0c9-5de6-407d-9e5d-26c67a8ecc5b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Eres suficiente! 💖', body_es = '¿Esta mañana te has mirado al espejo y te has sentido cansada, quizá insuficiente? Respira hondo. Para esos ojos inocentes de tu bebé que te miran, eres el ser más perfecto del mundo. ¡Eres suficiente!', title_fr = 'Vous suffisez ! 💖', body_fr = 'Ce matin, en vous regardant dans le miroir, vous vous êtes sentie fatiguée, peut-être insuffisante ? Respirez profondément. Pour les yeux innocents de votre bébé qui vous regardent, vous êtes l''être le plus parfait du monde. Vous suffisez !', title_hi = 'आप काफ़ी हैं! 💖', body_hi = 'आज सुबह आईने में देखकर खुद को थका हुआ, शायद अधूरा महसूस किया? एक गहरी साँस लीजिए। आपको देखने वाली बच्चे की उन मासूम आँखों के लिए आप दुनिया की सबसे परफ़ेक्ट इंसान हैं। आप काफ़ी हैं!', title_id = 'Anda sudah cukup! 💖', body_id = 'Pagi ini Anda bercermin dan merasa lelah, mungkin juga merasa kurang? Tarik napas dalam-dalam. Bagi mata polos bayi yang menatap Anda, Anda adalah sosok paling sempurna di dunia. Anda sudah cukup!', title_ja = 'あなたはそのままで十分！💖', body_ja = '今朝、鏡を見て疲れている、もしかしたら足りないと感じましたか？深呼吸して。あなたを見上げる赤ちゃんの無垢な瞳にとって、あなたは世界でいちばん完璧な存在です。あなたはそのままで十分！', title_ko = '엄마는 충분해요! 💖', body_ko = '오늘 아침 거울을 보며 지치고 어쩌면 부족하다고 느꼈나요? 깊게 숨을 쉬어요. 엄마를 바라보는 아기의 순수한 눈에는 엄마가 세상에서 가장 완벽한 사람이에요. 엄마는 충분해요!', title_nl = 'Jij bent genoeg! 💖', body_nl = 'Keek je vanochtend in de spiegel en voelde je je moe, misschien zelfs tekortschieten? Haal diep adem. Voor die onschuldige oogjes die naar je kijken, ben jij het meest volmaakte wezen ter wereld. Jij bent genoeg!', title_pl = 'Wystarczysz! 💖', body_pl = 'Spojrzałaś dziś rano w lustro i poczułaś się zmęczona, może nawet niewystarczająca? Weź głęboki oddech. Dla niewinnych oczu dziecka, które na ciebie patrzą, jesteś najdoskonalszą istotą na świecie. Wystarczysz!', title_pt = 'A Mamã é suficiente! 💖', body_pt = 'Esta manhã olhou-se ao espelho e sentiu-se cansada, talvez insuficiente? Respire fundo. Para aqueles olhos inocentes do bebé que olham para si, é o ser mais perfeito do mundo. É suficiente!', title_sv = 'Du räcker till! 💖', body_sv = 'Tittade du dig i spegeln i morse och kände dig trött, kanske otillräcklig? Andas djupt. För ditt barns oskyldiga ögon som tittar på dig är du den mest perfekta människan i världen. Du räcker till!', title_vi = 'Mẹ là đủ rồi! 💖', body_vi = 'Sáng nay nhìn gương, mẹ thấy mình mệt mỏi, có khi còn thấy chưa đủ tốt? Hãy hít một hơi thật sâu. Với đôi mắt ngây thơ đang nhìn mẹ, mẹ là người hoàn hảo nhất thế giới. Mẹ là đủ rồi!', title_zh = '你已经足够好了！💖', body_zh = '今天早上照镜子时，觉得自己疲惫，甚至不够好？深呼吸。在宝宝那双望着你的纯真眼睛里，你是世界上最完美的人。你已经足够好了！' WHERE id = '91aad506-9119-4c1d-9011-ca750f77b2da' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cuánto nos hemos cansado? 🛋️', body_es = 'El bebé se ha dormido, ¿y tú? Abre el Diario de ánimo y anota con humor junto a tu pareja el caos de hoy. Los días difíciles pasan y queda el espíritu de equipo.', title_fr = 'À quel point sommes-nous fatigués ? 🛋️', body_fr = 'Bébé dort, et vous ? Ouvrez le Journal d''humeur et notez avec humour le chaos du jour avec votre conjoint. Les jours difficiles passent, l''esprit d''équipe reste.', title_hi = 'हम कितने थक गए हैं? 🛋️', body_hi = 'बच्चा सो गया, और आप? मूड डायरी खोलिए, अपने साथी के साथ मिलकर आज की अफ़रा-तफ़री को मज़ाकिया अंदाज़ में लिखिए। मुश्किल दिन गुज़र जाते हैं, पीछे टीम की भावना रह जाती है।', title_id = 'Seberapa lelah kita? 🛋️', body_id = 'Anak sudah tidur, bagaimana dengan Anda? Buka Buku Harian Suasana Hati dan catat kekacauan hari ini dengan humor bersama pasangan. Hari-hari sulit akan berlalu, yang tertinggal adalah semangat tim.', title_ja = 'どれくらい疲れている？🛋️', body_ja = '赤ちゃんは寝たけれど、あなたは？「気分日記」を開いて、パートナーと一緒に今日のドタバタをユーモアたっぷりに記録しましょう。大変な日は過ぎ去り、チームの絆が残ります。', title_ko = '우리 얼마나 지쳤을까요? 🛋️', body_ko = '아기는 잠들었는데 엄마는요? 기분 일기를 열고 배우자와 함께 오늘의 혼란을 유머 있게 기록해 보세요. 힘든 날은 지나가고 팀의 마음은 남아요.', title_nl = 'Hoe moe zijn we? 🛋️', body_nl = 'De baby slaapt, en jij? Open je Stemmingsdagboek en noteer samen met je partner met humor de chaos van vandaag. Zware dagen gaan voorbij, de teamgeest blijft.', title_pl = 'Jak bardzo jesteśmy zmęczeni? 🛋️', body_pl = 'Dziecko zasnęło, a ty? Otwórz Dziennik nastroju i razem z partnerem zapiszcie z humorem dzisiejszy chaos. Trudne dni mijają, a zostaje duch drużyny.', title_pt = 'Quão cansados estamos? 🛋️', body_pt = 'O bebé adormeceu, e a mãe? Abra o Diário de Humor e registe com humor, junto com o seu companheiro, o caos de hoje. Os dias difíceis passam, fica o espírito de equipa.', title_sv = 'Hur trötta är vi? 🛋️', body_sv = 'Barnet sover, men du då? Öppna Humördagboken och anteckna dagens kaos med humor tillsammans med din partner. Svåra dagar går över, laganda blir kvar.', title_vi = 'Mình mệt đến mức nào rồi? 🛋️', body_vi = 'Bé ngủ rồi, còn mẹ thì sao? Mở Nhật ký tâm trạng, cùng chồng ghi lại sự hỗn loạn hôm nay một cách hài hước. Những ngày khó khăn rồi sẽ qua, còn lại là tinh thần đồng đội.', title_zh = '我们有多累？🛋️', body_zh = '宝宝睡了，那你呢？打开心情日记，和另一半一起幽默地记下今天的混乱。艰难的日子会过去，留下的是团队精神。' WHERE id = 'cc5d4a21-5a6c-4726-9656-04a48085588c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Llega la regresión del sueño? 🤖', body_es = '¿De repente ha empezado a despertarse mucho por la noche? No te asustes, se acerca la regresión del sueño del 4.º mes. Pide ya a Anacan AI información breve y tranquilizadora sobre este proceso biológico.', title_fr = 'La régression du sommeil approche ? 🤖', body_fr = 'Il s''est soudain mis à se réveiller souvent la nuit ? Pas de panique, la régression du sommeil du 4e mois approche. Demandez tout de suite à Anacan AI des informations courtes et rassurantes sur ce processus biologique.', title_hi = 'स्लीप रिग्रेशन दरवाज़े पर? 🤖', body_hi = 'बच्चा अचानक रात में बार-बार जागने लगा? घबराइए मत, चौथे महीने का स्लीप रिग्रेशन करीब है। तुरंत Anacan AI से इस जैविक प्रक्रिया के बारे में छोटी, तसल्ली देने वाली जानकारी पाइए।', title_id = 'Regresi tidur sudah di depan pintu? 🤖', body_id = 'Anak tiba-tiba sering terbangun di malam hari? Jangan takut, regresi tidur bulan ke-4 sudah dekat. Segera dapatkan informasi singkat dan menenangkan tentang proses biologis ini dari Anacan AI.', title_ja = '睡眠退行がやってくる？🤖', body_ja = '赤ちゃんが急に夜中によく起きるようになった？心配しないで、4か月の睡眠退行が近づいています。すぐにAnacan AIで、この生理的なプロセスについての短く安心できる情報を受け取りましょう。', title_ko = '수면 퇴행이 다가오나요? 🤖', body_ko = '아기가 갑자기 밤에 자주 깨기 시작했나요? 걱정 마세요, 4개월 수면 퇴행이 다가오고 있어요. 이 자연스러운 과정에 대해 Anacan AI에게 짧고 안심되는 정보를 바로 받아 보세요.', title_nl = 'Staat de slaapregressie voor de deur? 🤖', body_nl = 'Wordt je baby ineens vaak wakker ’s nachts? Schrik niet, de slaapregressie van 4 maanden komt eraan. Krijg meteen korte, geruststellende informatie over dit biologische proces van Anacan AI.', title_pl = 'Regres snu tuż-tuż? 🤖', body_pl = 'Dziecko nagle zaczęło często budzić się w nocy? Nie bój się, zbliża się regres snu 4. miesiąca. Od razu uzyskaj od Anacan AI krótką, uspokajającą informację o tym biologicznym procesie.', title_pt = 'A regressão do sono está à porta? 🤖', body_pt = 'De repente, o bebé começou a acordar muitas vezes à noite? Não se assuste, está a chegar a regressão do sono do 4.º mês. Peça já ao Anacan AI informação curta e tranquilizadora sobre este processo biológico.', title_sv = 'Står sömnregressionen för dörren? 🤖', body_sv = 'Har barnet plötsligt börjat vakna ofta på nätterna? Var inte rädd, sömnregressionen vid 4 månader närmar sig. Få direkt kort och lugnande information om den här biologiska processen från Anacan AI.', title_vi = 'Khủng hoảng giấc ngủ đang đến? 🤖', body_vi = 'Bé đột nhiên thức giấc nhiều lần vào ban đêm? Đừng sợ, khủng hoảng giấc ngủ tháng thứ 4 đang đến gần. Hãy hỏi ngay Anacan AI để nhận thông tin ngắn gọn, giúp mẹ yên tâm về quá trình sinh học này.', title_zh = '睡眠倒退要来了？🤖', body_zh = '宝宝突然开始夜里频繁醒来？别怕，4个月睡眠倒退快到了。马上向Anacan AI了解这个生理过程，获得简短又让人安心的信息。' WHERE id = '8557b605-4ddd-4ff9-9e9a-646d4a26ea63' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de salir ⛅', body_es = 'Vestiros cuesta, pero 20 minutos de aire fresco le sentarán genial al bebé y a tu estado de ánimo. Mira Tiempo y ropa, vestíos y abre la puerta, ¡no la ventana!', title_fr = 'L''heure de sortir ⛅', body_fr = 'S''habiller peut sembler pénible, mais 20 minutes d''air frais feront un bien fou à bébé comme à votre moral. Consultez Météo et tenue, habillez-vous et ouvrez la porte, pas seulement la fenêtre !', title_hi = 'बाहर निकलने का समय ⛅', body_hi = 'तैयार होना मुश्किल लगता है, पर 20 मिनट की ताज़ी हवा बच्चे और आपके मन दोनों पर बढ़िया असर डालेगी। मौसम और कपड़े देखिए, तैयार होइए और खिड़की नहीं, दरवाज़ा खोलिए!', title_id = 'Waktunya keluar rumah ⛅', body_id = 'Bersiap-siap memang merepotkan, tapi 20 menit udara segar akan sangat baik untuk bayi dan juga kesehatan mental Anda. Cek Cuaca dan Pakaian, berpakaianlah, dan bukalah pintu, bukan jendela!', title_ja = '外に出る時間 ⛅', body_ja = '身支度は大変に感じるかもしれませんが、20分の新鮮な空気は赤ちゃんにもあなたの心にもとてもいい影響があります。「天気と服装」を見て、着替えて、窓ではなくドアを開けましょう！', title_ko = '밖에 나갈 시간 ⛅', body_ko = '챙겨 입고 나가기가 힘들지만, 20분의 맑은 공기는 아기와 엄마의 마음 모두에 아주 좋아요. 날씨와 옷차림을 확인하고 옷을 입은 뒤 창문 말고 문을 여세요!', title_nl = 'Tijd om naar buiten te gaan ⛅', body_nl = 'Aankleden en klaarmaken voelt zwaar, maar 20 minuten frisse lucht doen wonderen voor je baby én voor jouw gemoed. Kijk in Weer en kleding, kleed je aan en open niet het raam, maar de deur!', title_pl = 'Czas wyjść na zewnątrz ⛅', body_pl = 'Ubieranie się bywa trudne, ale 20 minut na świeżym powietrzu świetnie zrobi i dziecku, i twojej psychice. Sprawdź Pogodę i ubiór, ubierz się i otwórz nie okno, a drzwi!', title_pt = 'Hora de sair ⛅', body_pt = 'Vestir-se e arranjar-se custa, mas 20 minutos de ar puro vão fazer muito bem ao bebé e ao seu estado de espírito. Veja o Tempo e Roupa, vista-se e abra a porta, não a janela!', title_sv = 'Dags att gå ut ⛅', body_sv = 'Det känns jobbigt att klä på sig, men 20 minuter i friska luften gör underverk både för barnet och för ditt psyke. Titta i Väder och kläder, klä på er och öppna dörren, inte bara fönstret!', title_vi = 'Đến giờ ra ngoài ⛅', body_vi = 'Mặc đồ cho cả hai mẹ con thì mệt, nhưng 20 phút không khí trong lành sẽ rất tốt cho cả bé lẫn tinh thần của mẹ. Xem Thời tiết và trang phục, mặc đồ rồi mở cửa ra ngoài, không phải chỉ mở cửa sổ!', title_zh = '该出门了 ⛅', body_zh = '穿戴整齐出门可能有点麻烦，但20分钟的新鲜空气对宝宝和你的心情都大有好处。看看天气与穿衣，穿好衣服，打开的不是窗户，而是大门！' WHERE id = '88a16b76-764f-4acc-b335-0aa3f126d25a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Papá, el héroe de la noche 🦸‍♂️', body_es = 'La mejor regla de los primeros meses: ¡sacar los gases y cantar nanas debe ir por turnos! Esta noche el bebé está en brazos de papá, y tú te pones los auriculares y disfrutas de la música.', title_fr = 'Papa, le héros de la nuit 🦸‍♂️', body_fr = 'La plus belle règle des premiers mois : le rot et la berceuse, chacun son tour ! Ce soir, bébé est dans les bras de Papa, et vous, vous mettez votre casque et profitez de la musique.', title_hi = 'रात के हीरो पापा 🦸‍♂️', body_hi = 'शुरुआती महीनों का सबसे अच्छा नियम: डकार दिलाना और लोरी सुनाना बारी-बारी से होना चाहिए! आज शाम बच्चा पापा की गोद में है, और आप हेडफ़ोन लगाकर संगीत का मज़ा ले रही हैं।', title_id = 'Ayah, pahlawan malam 🦸‍♂️', body_id = 'Aturan terbaik di bulan-bulan pertama: menyendawakan dan menyanyikan nina bobo harus bergantian! Malam ini bayi ada di pelukan Ayah, sementara Anda memasang headphone dan menikmati musik.', title_ja = '夜のヒーロー、パパ 🦸‍♂️', body_ja = '最初の数か月のいちばんのルール：げっぷと子守唄は交代制！今夜は赤ちゃんはパパの腕の中、あなたはヘッドホンをつけて音楽を楽しみましょう。', title_ko = '밤의 영웅 아빠 🦸‍♂️', body_ko = '첫 몇 달의 가장 좋은 규칙: 트림시키기와 자장가는 번갈아 하기! 오늘 저녁 아기는 아빠 품에 있고, 엄마는 헤드폰을 쓰고 음악을 즐기세요.', title_nl = 'Papa, de held van de nacht 🦸‍♂️', body_nl = 'De mooiste regel van de eerste maanden: boertjes laten doen en slaapliedjes zingen gaat om de beurt! Vanavond ligt de baby in papa’s armen, en zet jij je koptelefoon op en geniet van muziek.', title_pl = 'Tata, bohater nocy 🦸‍♂️', body_pl = 'Najpiękniejsza zasada pierwszych miesięcy: odbijanie i kołysanki na zmianę! Dziś wieczorem dziecko jest w ramionach taty, a ty zakładasz słuchawki i cieszysz się muzyką.', title_pt = 'O pai, herói da noite 🦸‍♂️', body_pt = 'A melhor regra dos primeiros meses: fazer arrotar e cantar canções de embalar deve ser por turnos! Esta noite o bebé está ao colo do pai, e a mãe põe os auscultadores e aproveita a música.', title_sv = 'Nattens hjälte: pappa 🦸‍♂️', body_sv = 'De första månadernas bästa regel: rapning och vaggvisor ska turas om! I kväll ligger barnet i pappas famn, och du sätter på hörlurarna och njuter av musiken.', title_vi = 'Bố, người hùng ban đêm 🦸‍♂️', body_vi = 'Quy tắc tuyệt nhất của những tháng đầu: vỗ ợ hơi và hát ru phải chia ca! Tối nay bé nằm trong vòng tay bố, còn mẹ đeo tai nghe và tận hưởng âm nhạc.', title_zh = '夜晚英雄爸爸 🦸‍♂️', body_zh = '头几个月最好的规则：拍嗝和唱摇篮曲要轮流来！今晚宝宝在爸爸怀里，你戴上耳机享受音乐吧。' WHERE id = 'bb5697de-df9c-4558-a606-a7acef72c755' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La taza de mamá ☕', body_es = '¿Qué has hecho hoy por ti? ¿Nada? En cuanto el bebé se duerma la siesta, deja el móvil a un lado. Sírvete un café (o un té) caliente y no pienses en nada durante 10 minutos.', title_fr = 'La tasse de maman ☕', body_fr = 'Qu''avez-vous fait pour vous aujourd''hui ? Rien ? Dès que bébé fait sa sieste, posez ce téléphone. Servez-vous un café (ou un thé) chaud et ne pensez à rien pendant 10 minutes.', title_hi = 'माँ का कप ☕', body_hi = 'आज आपने अपने लिए क्या किया? कुछ नहीं? जैसे ही बच्चा दिन की नींद ले, वह फ़ोन किनारे रख दीजिए। अपने लिए गरमा-गरम कॉफ़ी (या चाय) बनाइए और 10 मिनट कुछ मत सोचिए।', title_id = 'Cangkir ibu ☕', body_id = 'Apa yang sudah Anda lakukan untuk diri sendiri hari ini? Tidak ada? Begitu anak tidur siang, singkirkan ponsel itu. Tuang kopi (atau teh) hangat dan jangan pikirkan apa pun selama 10 menit.', title_ja = 'ママの1杯 ☕', body_ja = '今日は自分のために何をしましたか？何も？赤ちゃんがお昼寝したら、スマホを置きましょう。温かいコーヒー（または紅茶）を入れて、10分間何も考えずに過ごしてください。', title_ko = '엄마의 찻잔 ☕', body_ko = '오늘 나를 위해 무엇을 했나요? 아무것도요? 아기가 낮잠 들자마자 휴대폰은 내려놓으세요. 따뜻한 커피(또는 차)를 따르고 10분 동안 아무 생각도 하지 마세요.', title_nl = 'Mama’s kopje ☕', body_nl = 'Wat heb je vandaag voor jezelf gedaan? Niets? Leg die telefoon weg zodra je baby gaat slapen. Schenk een warme koffie (of thee) in en denk 10 minuten aan helemaal niets.', title_pl = 'Filiżanka mamy ☕', body_pl = 'Co dziś zrobiłaś dla siebie? Nic? Gdy tylko dziecko zaśnie na drzemkę, odłóż telefon. Nalej sobie ciepłej kawy (lub herbaty) i przez 10 minut o niczym nie myśl.', title_pt = 'A chávena da mãe ☕', body_pt = 'O que fez hoje por si? Nada? Mal o bebé adormeça a sesta, ponha o telemóvel de lado. Sirva-se de um café (ou chá) quente e não pense em nada durante 10 minutos.', title_sv = 'Mammas kopp ☕', body_sv = 'Vad har du gjort för dig själv i dag? Ingenting? Så fort barnet somnar för dagsluren, lägg undan telefonen. Häll upp en varm kopp kaffe (eller te) och tänk inte på någonting i 10 minuter.', title_vi = 'Tách cà phê của mẹ ☕', body_vi = 'Hôm nay mẹ đã làm gì cho bản thân? Chưa gì cả? Vừa khi bé ngủ ngày, hãy đặt điện thoại xuống. Rót cho mình một tách cà phê (hoặc trà) nóng và không nghĩ gì trong 10 phút.', title_zh = '妈妈的那杯 ☕', body_zh = '今天你为自己做了什么？什么都没有？宝宝一睡午觉，就把手机放到一边。给自己倒杯热咖啡（或茶），10分钟什么都不想。' WHERE id = '4696c250-45bb-4765-b4bf-ee4e94f6361c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de tirar del pelo 💇‍♀️', body_es = '¿Tu bebé te enreda las manos en el pelo y tira con fuerza? ¡Su reflejo de agarre se ha fortalecido! Graba sin falta en vídeo esta etapa divertida, aunque dolorosa, y guárdala como recuerdo.', title_fr = 'L''art de tirer les cheveux 💇‍♀️', body_fr = 'Votre bébé enroule ses mains dans vos cheveux et tire fort ? Son réflexe de préhension s''est renforcé ! Filmez cette étape drôle mais douloureuse et gardez-la en souvenir.', title_hi = 'बाल खींचने की कला 💇‍♀️', body_hi = 'आपका बच्चा अपने हाथ सीधे आपके बालों में लपेटकर ज़ोर से खींचता है? उसकी पकड़ मज़बूत हो गई है! विकास के इस मज़ेदार पर दर्द भरे दौर का वीडियो ज़रूर बनाइए और याद के तौर पर रखिए।', title_id = 'Seni menarik rambut 💇‍♀️', body_id = 'Bayi Anda melilitkan tangannya ke rambut Anda dan menariknya kuat-kuat? Refleks menggenggamnya makin kuat! Rekam tahap perkembangan yang lucu tapi menyakitkan ini dan simpan sebagai kenangan.', title_ja = '髪の毛つかみの達人 💇‍♀️', body_ja = '赤ちゃんがママの髪に手をからめて、ぎゅっと引っぱりますか？にぎる力が強くなっています！おもしろいけれど痛い、この成長の時期をぜひ動画に撮って思い出に残しましょう。', title_ko = '머리카락 잡아당기기의 기술 💇‍♀️', body_ko = '아기가 엄마 머리카락을 손에 감고 세게 잡아당기나요? 잡기 반사가 강해졌어요! 웃기지만 아픈 이 발달 단계를 꼭 영상으로 찍어 추억으로 남겨 두세요.', title_nl = 'De kunst van het haartrekken 💇‍♀️', body_nl = 'Draait je baby de handjes in je haar en trekt hij er stevig aan? De grijpreflex is sterker geworden! Leg deze grappige, maar pijnlijke ontwikkelingsfase zeker vast op video als herinnering.', title_pl = 'Sztuka wyrywania włosów 💇‍♀️', body_pl = 'Dziecko owija rączki wokół twoich włosów i mocno ciągnie? Odruch chwytania się wzmocnił! Ten zabawny, ale bolesny etap rozwoju koniecznie nagraj na pamiątkę.', title_pt = 'A arte de puxar cabelos 💇‍♀️', body_pt = 'O bebé enrola as mãos no seu cabelo e puxa com força? O reflexo de preensão ficou mais forte! Grave em vídeo esta fase divertida, mas dolorosa, e guarde-a como recordação.', title_sv = 'Konsten att dra i hår 💇‍♀️', body_sv = 'Lindar barnet in händerna i ditt hår och drar hårt? Gripreflexen har blivit starkare! Filma den här roliga men smärtsamma utvecklingsfasen och spara den som ett minne.', title_vi = 'Nghệ thuật giật tóc 💇‍♀️', body_vi = 'Bé quấn tay vào tóc mẹ và giật thật mạnh? Phản xạ cầm nắm đã mạnh hơn! Hãy quay video giai đoạn phát triển vừa buồn cười vừa đau này để làm kỷ niệm nhé.', title_zh = '拽头发的艺术 💇‍♀️', body_zh = '宝宝把小手缠进你的头发，使劲拽？抓握反射变强了！这个好笑又有点疼的成长阶段，一定要拍成视频留作纪念。' WHERE id = '7831318d-6b24-4373-9578-2c2a43ef02bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El milagro del contacto piel con piel 🫂', body_es = '¿No hay manera de que se duerma y grita en cuanto lo dejas en la cuna? A veces no hace falta ninguna herramienta. Ponlo sobre tu pecho y nota cómo el contacto piel con piel os calma a los dos.', title_fr = 'Le miracle du contact 🫂', body_fr = 'Il ne veut pas dormir et hurle dès que vous le posez ? Parfois, aucun outil n''est nécessaire. Posez-le contre votre poitrine et sentez comme le peau à peau vous apaise tous les deux.', title_hi = 'स्पर्श का चमत्कार 🫂', body_hi = 'किसी भी तरह सोना नहीं चाहता, बिस्तर पर रखते ही चीखता है? कभी-कभी किसी टूल की ज़रूरत नहीं होती। उसे अपने सीने से लगाइए और महसूस कीजिए कि त्वचा से त्वचा का स्पर्श आप दोनों को कैसे शांत करता है।', title_id = 'Keajaiban sentuhan kulit 🫂', body_id = 'Ia sama sekali tidak mau tidur dan menjerit begitu diletakkan di tempat tidur? Terkadang tidak perlu alat apa pun. Letakkan ia di dada Anda dan rasakan bagaimana kontak kulit ke kulit menenangkan Anda berdua.', title_ja = 'ふれあいの奇跡 🫂', body_ja = 'どうしても眠らず、ベッドに置いたとたんに泣き出す？ときには何の道具もいりません。胸に抱いて、肌と肌のふれあいが2人をどれだけ落ち着かせるか感じてみましょう。', title_ko = '스킨십의 기적 🫂', body_ko = '도무지 자려 하지 않고 침대에 눕히자마자 우나요? 가끔은 아무 도구도 필요 없어요. 가슴에 안고 맨살이 닿는 스킨십이 두 사람을 어떻게 진정시키는지 느껴 보세요.', title_nl = 'Het wonder van huidcontact 🫂', body_nl = 'Wil je baby maar niet slapen en schreeuwt hij zodra je hem in bed legt? Soms heb je geen enkel hulpmiddel nodig. Leg hem op je borst en voel hoe huid-op-huidcontact jullie allebei kalmeert.', title_pl = 'Cud bliskości 🫂', body_pl = 'Za nic nie chce zasnąć i krzyczy, gdy tylko odłożysz je do łóżeczka? Czasem nie potrzeba żadnych narzędzi. Połóż je na swojej piersi i poczuj, jak kontakt skóra do skóry uspokaja was oboje.', title_pt = 'O milagre do contacto pele com pele 🫂', body_pt = 'Não quer dormir de maneira nenhuma e grita mal o pousa na cama? Às vezes não é preciso nenhuma ferramenta. Ponha-o ao peito e sinta como o contacto pele com pele acalma os dois.', title_sv = 'Hudkontaktens mirakel 🫂', body_sv = 'Vill barnet inte sova alls och skriker så fort du lägger ner det? Ibland behövs inga verktyg. Lägg barnet mot ditt bröst och känn hur hud mot hud lugnar er båda.', title_vi = 'Phép màu của sự tiếp xúc 🫂', body_vi = 'Bé nhất định không chịu ngủ, vừa đặt xuống giường là khóc thét? Đôi khi chẳng cần công cụ nào cả. Hãy đặt bé lên ngực mẹ và cảm nhận tiếp xúc da kề da xoa dịu cả hai mẹ con thế nào.', title_zh = '肌肤接触的奇迹 🫂', body_zh = '怎么都不肯睡，一放到床上就大哭？有时什么工具都不需要。把宝宝贴在你胸前，感受肌肤相亲是怎样让你们俩都平静下来的。' WHERE id = 'd66ea07a-276e-489b-bd8f-3ff80abe7258' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se le moja el cuello cada 10 minutos?', body_es = 'Esos primeros avisos del Seguimiento de dentición se hacen realidad. Revisa a menudo la encía de abajo: ¡quizá la primera perla blanca ya esté en camino!', title_fr = 'Son col est mouillé toutes les 10 minutes ?', body_fr = 'Les premières alertes du Suivi des dents deviennent réalité. Vérifiez souvent la mâchoire inférieure, la première perle blanche est peut-être en route !', title_hi = 'हर 10 मिनट में कॉलर गीला हो जाता है?', body_hi = 'दाँत निकलने के ट्रैकर की वे पहली चेतावनियाँ सच हो रही हैं। निचले मसूड़े को बार-बार देखिए, शायद पहला सफ़ेद मोती रास्ते में है!', title_id = 'Kerah bajunya basah setiap 10 menit?', body_id = 'Peringatan pertama di Pelacak Tumbuh Gigi mulai menjadi nyata. Sering-seringlah memeriksa gusi bawahnya, mungkin mutiara putih pertamanya sedang dalam perjalanan!', title_ja = '10分ごとに襟がびしょびしょ？', body_ja = '「歯の生え始めトラッカー」の最初のお知らせが現実になってきました。下の歯ぐきをこまめにチェックしてみて。最初の白い真珠がもうすぐかも！', title_ko = '10분마다 옷깃이 젖나요?', body_ko = '이앓이 기록의 첫 신호들이 현실이 되고 있어요. 아래 잇몸을 자주 확인해 보세요, 첫 하얀 진주가 오고 있을지도 몰라요!', title_nl = 'Is het kraagje elke 10 minuten nat?', body_nl = 'De eerste waarschuwingen in de Tandjestracker worden werkelijkheid. Kijk vaak naar het ondertandvlees, misschien is de eerste witte parel onderweg!', title_pl = 'Śliniaczek mokry co 10 minut?', body_pl = 'Pierwsze ostrzeżenia z narzędzia do śledzenia ząbkowania stają się rzeczywistością. Często sprawdzaj dolne dziąsło, może pierwsza biała perełka jest w drodze!', title_pt = 'A gola fica molhada de 10 em 10 minutos?', body_pt = 'Aqueles primeiros alertas do Registo de Dentição estão a tornar-se realidade. Veja muitas vezes a gengiva de baixo, talvez a primeira pérola branca esteja a caminho!', title_sv = 'Blir kragen blöt var tionde minut?', body_sv = 'De första varningarna i Tandspåraren blir verklighet. Kolla underkäken ofta, kanske är den första vita pärlan på väg!', title_vi = 'Cổ áo bé ướt sau mỗi 10 phút?', body_vi = 'Những cảnh báo đầu tiên trong Theo dõi mọc răng đang thành hiện thực. Hãy thường xuyên kiểm tra hàm dưới, có khi viên ngọc trắng đầu tiên đang trên đường đến!', title_zh = '衣领每10分钟就湿一次？', body_zh = '出牙记录里最初的提醒正在成真。经常看看宝宝的下牙床，也许第一颗白色小珍珠就要来了！' WHERE id = 'a99309cf-e0e5-4d40-9004-a8b08226861a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo 15 minutos de silencio 🤫', body_es = '¿Te estalla la cabeza de cansancio después de todo el día? Al dormir al bebé, activa el Medidor de sonido para controlar el ambiente, declara silencio en casa y deja descansar tu mente.', title_fr = 'Juste 15 minutes de silence 🤫', body_fr = 'La fatigue vous donne mal à la tête toute la journée ? Quand vous couchez bébé, activez le Sonomètre pour contrôler l''ambiance, décrétez le silence à la maison et reposez votre esprit.', title_hi = 'बस 15 मिनट की खामोशी 🤫', body_hi = 'दिन भर थकान से सिर फटा जा रहा है? बच्चे को सुलाते समय साउंड मीटर चालू करके माहौल पर नियंत्रण रखिए, घरवालों के लिए खामोशी का ऐलान कीजिए और अपने दिमाग को आराम दीजिए।', title_id = 'Cukup 15 menit keheningan 🤫', body_id = 'Kepala pusing karena lelah seharian? Saat menidurkan bayi, aktifkan Pengukur Suara untuk mengontrol suasana, umumkan waktu hening kepada seisi rumah, dan istirahatkan pikiran Anda.', title_ja = 'たった15分の静けさ 🤫', body_ja = '1日中の疲れで頭が割れそう？赤ちゃんを寝かせたら「サウンドメーター」をオンにして環境を整え、家族に静かにするよう伝えて、頭を休ませましょう。', title_ko = '딱 15분의 고요함 🤫', body_ko = '하루 종일 피로로 머리가 지끈거리나요? 아기를 재울 때 소음 측정기를 켜서 주변을 관리하고, 가족에게 조용히 해 달라고 알린 뒤 머리를 쉬게 하세요.', title_nl = 'Gewoon 15 minuten stilte 🤫', body_nl = 'Barst je hoofd van vermoeidheid na een lange dag? Zet als je je baby in slaap brengt de Geluidsmeter aan, houd de omgeving onder controle, kondig stilte af in huis en geef je hoofd rust.', title_pl = 'Tylko 15 minut ciszy 🤫', body_pl = 'Przez cały dzień głowa pęka ci ze zmęczenia? Gdy usypiasz dziecko, włącz Miernik dźwięku, przejmij kontrolę nad otoczeniem, ogłoś domownikom ciszę i daj odpocząć głowie.', title_pt = 'Só 15 minutos de silêncio 🤫', body_pt = 'Ao fim do dia, a cabeça parece estalar de cansaço? Quando adormecer o bebé, ative o Medidor de Som e controle o ambiente, declare silêncio em casa e deixe o cérebro descansar.', title_sv = 'Bara 15 minuters tystnad 🤫', body_sv = 'Spricker huvudet av trötthet hela dagen? När du nattar barnet, aktivera Ljudmätaren och ta kontroll över miljön, utlys tystnad för de andra hemma och låt hjärnan vila.', title_vi = 'Chỉ 15 phút yên tĩnh 🤫', body_vi = 'Mệt đến nhức đầu cả ngày? Khi ru bé ngủ, hãy bật Đo âm thanh để kiểm soát không gian, yêu cầu cả nhà giữ yên lặng và cho đầu óc nghỉ ngơi.', title_zh = '只要15分钟的安静 🤫', body_zh = '一整天累得头都要裂开了？哄宝宝睡觉时打开分贝仪掌控环境，向家人宣布安静时间，让大脑休息一下。' WHERE id = 'b14018ad-b2b5-4374-a785-9d281ebdd7e0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué hacen otras mamás? 💬', body_es = '¿Te preguntas: «¿Solo mi bebé hace esto?»? ¡No estás sola! Entra en la Comunidad Anacan, lee historias reales de mamás y suelta un buen suspiro de alivio.', title_fr = 'Que font les autres mamans ? 💬', body_fr = 'Vous vous demandez : « Est-ce que seul mon enfant fait ça ? » Vous n''êtes pas seule ! Rejoignez la Communauté Anacan, lisez les vraies histoires de mamans et poussez un grand soupir de soulagement.', title_hi = 'दूसरी माँएँ क्या करती हैं? 💬', body_hi = 'सोचती हैं, ''क्या सिर्फ़ मेरा बच्चा ही ऐसा करता है?'' आप अकेली नहीं हैं! Anacan कम्युनिटी में जाइए, वहाँ असली माँओं की कहानियाँ पढ़िए और राहत की गहरी साँस लीजिए।', title_id = 'Apa yang dilakukan ibu-ibu lain? 💬', body_id = 'Anda berpikir, Apakah hanya anakku yang seperti ini? Anda tidak sendirian! Buka Komunitas Anacan, baca kisah nyata para ibu di sana, dan tarik napas lega.', title_ja = 'ほかのママたちはどうしている？💬', body_ja = '「こんなことをするのは、うちの子だけ？」と思っていませんか？あなただけではありません！Anacanコミュニティで、本物のママたちのお話を読んで、ほっとひと息つきましょう。', title_ko = '다른 엄마들은 어떻게 할까요? 💬', body_ko = '''우리 아기만 이런 걸까?'' 하고 생각하나요? 혼자가 아니에요! Anacan 커뮤니티에 들어가 진짜 엄마들의 이야기를 읽고 깊은 안도의 숨을 쉬어 보세요.', title_nl = 'Wat doen andere mama’s? 💬', body_nl = 'Denk je ‘Doet alleen mijn kind zo?’ Je bent niet de enige! Ga naar de Anacan Community, lees de echte verhalen van mama’s en slaak een diepe zucht van opluchting.', title_pl = 'Co robią inne mamy? 💬', body_pl = 'Myślisz: „Czy tylko moje dziecko tak robi?” Nie jesteś sama! Wejdź do Społeczności Anacan, przeczytaj prawdziwe historie mam i odetchnij głęboko.', title_pt = 'O que fazem as outras mães? 💬', body_pt = 'Pergunta-se: "Será que só o meu bebé faz isto?" Não está sozinha! Entre na Comunidade Anacan, leia as histórias reais de mães e solte um suspiro de alívio.', title_sv = 'Vad gör andra mammor? 💬', body_sv = 'Tänker du ''Är det bara mitt barn som gör så här?'' Du är inte ensam! Gå in i Anacans Community, läs riktiga mammors berättelser och dra en djup suck av lättnad.', title_vi = 'Các mẹ khác làm thế nào? 💬', body_vi = 'Mẹ đang nghĩ "Chẳng lẽ chỉ con mình như vậy?" Mẹ không đơn độc đâu! Hãy vào Cộng đồng Anacan, đọc những câu chuyện thật của các mẹ và thở phào nhẹ nhõm.', title_zh = '其他妈妈都怎么做？💬', body_zh = '在想“是不是只有我家宝宝这样？”你并不孤单！来Anacan社区读读真实的妈妈故事，长长地舒一口气吧。' WHERE id = 'c69510ed-a6e2-4456-a462-211d3917dec3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El amigo del espejo 👀', body_es = 'Ponlo delante de un espejo. Mira cómo observa su reflejo con asombro y sonriendo. Aún no sabe que es él mismo, pero este juego es perfecto para su desarrollo mental.', title_fr = 'L''ami dans le miroir 👀', body_fr = 'Placez-le devant le miroir. Regardez avec quel émerveillement il observe son reflet en souriant. Il ne sait pas encore que c''est lui, mais ce jeu est parfait pour son développement mental.', title_hi = 'आईने वाला दोस्त 👀', body_hi = 'उसे आईने के सामने ले जाइए। देखिए वह अपनी परछाईं को कैसे हैरानी से, मुस्कुराते हुए देखता है। उसे अभी नहीं पता कि आईने में वही है, पर यह खेल उसके दिमागी विकास के लिए बेहतरीन है।', title_id = 'Teman di cermin 👀', body_id = 'Bawa ia ke depan cermin. Saksikan betapa takjub dan tersenyumnya ia memandangi bayangannya. Ia belum tahu bahwa itu dirinya, tapi permainan ini sempurna untuk perkembangan kognitifnya.', title_ja = '鏡の中のお友達 👀', body_ja = '赤ちゃんを鏡の前に連れて行きましょう。自分の姿を驚きと笑顔で見つめる様子を見てみて。鏡の中が自分だとはまだわかりませんが、この遊びは知的な発達にぴったりです。', title_ko = '거울 속 친구 👀', body_ko = '아기를 거울 앞에 데려가 보세요. 자기 모습을 신기한 듯 웃으며 바라보는 걸 지켜보세요. 아직 거울 속 아기가 자기인 줄 모르지만, 이 놀이는 두뇌 발달에 아주 좋아요.', title_nl = 'Een vriendje in de spiegel 👀', body_nl = 'Zet je baby voor de spiegel. Kijk hoe hij verwonderd en glimlachend naar zijn spiegelbeeld kijkt. Hij weet nog niet dat hij het zelf is, maar dit spelletje is perfect voor de verstandelijke ontwikkeling.', title_pl = 'Przyjaciel w lustrze 👀', body_pl = 'Podejdź z nim do lustra. Zobacz, jak ze zdziwieniem i uśmiechem patrzy na swoje odbicie. Jeszcze nie wie, że to ono, ale ta zabawa jest idealna dla jego rozwoju umysłowego.', title_pt = 'O amigo do espelho 👀', body_pt = 'Leve-o para a frente de um espelho. Veja como olha para o próprio reflexo com espanto e a sorrir. Ainda não sabe que é ele, mas esta brincadeira é perfeita para o desenvolvimento mental.', title_sv = 'Kompisen i spegeln 👀', body_sv = 'Ta barnet till spegeln. Se hur det tittar förundrat och leende på sin spegelbild. Barnet vet inte än att det är sig själv det ser, men leken är perfekt för den mentala utvecklingen.', title_vi = 'Người bạn trong gương 👀', body_vi = 'Hãy bế bé đến trước gương. Ngắm bé nhìn hình ảnh của chính mình đầy ngạc nhiên và mỉm cười. Bé chưa biết người trong gương là mình, nhưng trò chơi này rất tốt cho sự phát triển trí tuệ.', title_zh = '镜子里的朋友 👀', body_zh = '把宝宝抱到镜子前，看看宝宝是怎样惊奇地、笑着看自己的倒影的。宝宝还不知道镜子里的是自己，但这个游戏对智力发育非常好。' WHERE id = '51cd27c2-62e8-409d-8a08-48c1ba2f8c3b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tu propio cuento especial 🪄', body_es = 'Facilita el paso al sueño por la noche con Cuentos inteligentes. Crea un cuento especial y tierno para él y léeselo.', title_fr = 'Votre conte bien à vous 🪄', body_fr = 'Facilitez le passage au sommeil du soir avec les Contes intelligents. Créez-lui une histoire spéciale et adorable, et lisez-la-lui.', title_hi = 'आपकी अपनी खास कहानी 🪄', body_hi = 'शाम की नींद में जाना स्मार्ट कहानियों से आसान बनाइए। उसके लिए एक खास, प्यारी कहानी बनाकर पढ़िए।', title_id = 'Dongeng istimewa Anda sendiri 🪄', body_id = 'Permudah peralihan ke tidur malam dengan Dongeng Pintar. Buat dan bacakan cerita manis yang istimewa untuknya.', title_ja = 'あなただけの特別なお話 🪄', body_ja = '夜の寝かしつけは「スマートおはなし」で楽に。赤ちゃんのために特別でかわいいお話をつくって読んであげましょう。', title_ko = '나만의 특별한 동화 🪄', body_ko = '스마트 동화로 밤잠에 쉽게 들게 해 주세요. 아기만을 위한 특별하고 사랑스러운 이야기를 만들어 읽어 주세요.', title_nl = 'Je eigen speciale sprookje 🪄', body_nl = 'Maak de overgang naar de nachtrust makkelijker met Slimme sprookjes. Maak een speciaal, lief verhaaltje en lees het voor.', title_pl = 'Twoja własna bajka 🪄', body_pl = 'Ułatw przejście w wieczorny sen dzięki Mądrym bajkom. Stwórz dla niego wyjątkową, słodką historię i przeczytaj ją.', title_pt = 'A sua história especial 🪄', body_pt = 'Facilite a transição para o sono da noite com as Histórias Inteligentes. Crie e leia-lhe uma história especial e ternurenta.', title_sv = 'Din egen speciella saga 🪄', body_sv = 'Gör övergången till kvällssömnen lättare med Smarta sagor. Skapa och läs en särskild, söt berättelse för barnet.', title_vi = 'Câu chuyện cổ tích của riêng mẹ 🪄', body_vi = 'Giúp bé vào giấc buổi tối dễ hơn với Truyện cổ tích thông minh. Hãy tạo và đọc cho bé một câu chuyện đặc biệt, ngọt ngào.', title_zh = '你的专属童话 🪄', body_zh = '用智慧童话让晚间入睡更轻松。为宝宝创作一个特别的温馨故事读给宝宝听吧。' WHERE id = '1e555e61-fac2-4756-83d5-5c2a2ceaa400' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comparte tu experiencia 💬', title_fr = 'Partage d''expériences 💬', title_hi = 'अनुभव बाँटिए 💬', title_id = 'Berbagi pengalaman 💬', title_ja = '体験をシェアしよう 💬', title_ko = '경험 나누기 💬', title_nl = 'Ervaringen delen 💬', title_pl = 'Dzielenie się doświadczeniem 💬', title_pt = 'Partilha de experiências 💬', title_sv = 'Dela erfarenheter 💬', title_vi = 'Chia sẻ trải nghiệm 💬', title_zh = '分享经验 💬' WHERE id = '41df7f7d-e272-4737-8498-6c866ab9545a' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Suelta la culpa 🛑', body_es = '¿Hoy se te ha agotado la paciencia, quizá te has enfadado un poco y ahora te sientes culpable? Para. ¿Eres un robot? No. Acepta lo que sientes, perdónate y mañana empieza un nuevo día.', title_fr = 'Lâchez la culpabilité 🛑', body_fr = 'Aujourd''hui, vous avez manqué de patience, peut-être un peu énervée, et maintenant vous culpabilisez ? Stop. Êtes-vous un robot ? Non. Acceptez vos émotions, pardonnez-vous et commencez demain une nouvelle journée.', title_hi = 'अपराध-बोध छोड़िए 🛑', body_hi = 'आज धैर्य जवाब दे गया, शायद थोड़ा गुस्सा आ गया और अब पछतावा हो रहा है? रुकिए। क्या आप रोबोट हैं? नहीं। अपनी भावनाओं को स्वीकार कीजिए, खुद को माफ़ कीजिए और कल एक नए दिन की शुरुआत कीजिए।', title_id = 'Buang rasa bersalah 🛑', body_id = 'Hari ini kesabaran Anda menipis, mungkin Anda sedikit marah dan kini merasa bersalah? Berhenti. Apakah Anda robot? Bukan. Terima perasaan Anda, maafkan diri sendiri, dan mulailah hari baru besok.', title_ja = '罪悪感を手放しましょう 🛑', body_ja = '今日は余裕がなくなって、少しイライラしてしまい、今になって自分を責めていますか？ストップ。あなたはロボットですか？いいえ。自分の気持ちを受け止めて、自分を許して、明日また新しい1日を始めましょう。', title_ko = '죄책감은 내려놓아요 🛑', body_ko = '오늘 인내심이 바닥나 조금 짜증을 내고 지금 마음이 무겁나요? 잠깐 멈추세요. 엄마가 로봇인가요? 아니에요. 감정을 받아들이고, 스스로를 용서하고, 내일 새로운 하루를 시작하세요.', title_nl = 'Laat je schuldgevoel los 🛑', body_nl = 'Was je geduld vandaag op, werd je misschien wat boos en heb je nu wroeging? Stop. Ben je een robot? Nee. Accepteer je gevoelens, vergeef jezelf en begin morgen aan een nieuwe dag.', title_pl = 'Pozbądź się poczucia winy 🛑', body_pl = 'Dziś zabrakło ci cierpliwości, może trochę się zdenerwowałaś i teraz masz wyrzuty sumienia? Stop. Czy jesteś robotem? Nie. Zaakceptuj swoje uczucia, wybacz sobie i jutro zacznij nowy dzień.', title_pt = 'Liberte-se da culpa 🛑', body_pt = 'Hoje perdeu a paciência, talvez se tenha irritado um pouco, e agora sente remorsos? Pare. É um robô? Não. Aceite o que sente, perdoe-se e amanhã comece um novo dia.', title_sv = 'Släpp skuldkänslorna 🛑', body_sv = 'Tröt tålamodet i dag, kanske blev du lite irriterad och har nu dåligt samvete? Stopp. Är du en robot? Nej. Acceptera dina känslor, förlåt dig själv och börja en ny dag i morgon.', title_vi = 'Gác lại cảm giác tội lỗi 🛑', body_vi = 'Hôm nay mẹ hết kiên nhẫn, có thể đã hơi cáu và giờ thấy cắn rứt? Dừng lại. Mẹ là robot à? Không. Hãy chấp nhận cảm xúc, tha thứ cho bản thân và bắt đầu ngày mới vào ngày mai.', title_zh = '放下内疚感 🛑', body_zh = '今天失去了耐心，也许还发了点脾气，现在正在自责？停下来。你是机器人吗？不是。接纳自己的情绪，原谅自己，明天重新开始。' WHERE id = '6f416e63-4acf-4dd2-8216-6601a8c26df5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El aire fresco es medicina 🌳', title_fr = 'L''air frais est un remède 🌳', title_hi = 'ताज़ी हवा दवा है 🌳', title_id = 'Udara segar adalah obat 🌳', title_ja = '新鮮な空気は薬です 🌳', title_ko = '맑은 공기는 약이에요 🌳', title_nl = 'Frisse lucht is een medicijn 🌳', title_pl = 'Świeże powietrze to lekarstwo 🌳', title_pt = 'O ar puro é um remédio 🌳', title_sv = 'Frisk luft är medicin 🌳', title_vi = 'Không khí trong lành là liều thuốc 🌳', title_zh = '新鲜空气是良药 🌳' WHERE id = '3995ea79-4422-4b71-b376-6426966b7d85' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Almacén de energía para mamá 🍲', body_es = '¿Por alimentar al bebé te has quedado sin comer? Prepara un tentempié energético y fácil de digerir de la sección Recetas saludables. Tienes que estar fuerte para darle fuerza.', title_fr = 'Une réserve d''énergie pour maman 🍲', body_fr = 'À force de nourrir bébé, vous vous êtes oubliée ? Préparez un en-cas énergétique et facile à digérer avec la rubrique Recettes saines. Vous devez être forte pour lui donner de la force.', title_hi = 'माँ के लिए ऊर्जा का भंडार 🍲', body_hi = 'बच्चे का पेट भरने में खुद भूखी रह गईं? सेहतमंद रेसिपी सेक्शन से आसानी से पचने वाला, ऊर्जा भरा स्नैक बनाइए। आपको मज़बूत रहना है, ताकि उसे भी ताकत दे सकें।', title_id = 'Gudang energi untuk ibu 🍲', body_id = 'Sibuk menyusui bayi sampai Anda sendiri kelaparan? Buat camilan berenergi yang mudah dicerna dari bagian Resep Sehat. Anda harus kuat agar bisa memberinya kekuatan.', title_ja = 'ママのエネルギー貯蔵庫 🍲', body_ja = '赤ちゃんにごはんをあげることに夢中で、自分はお腹をすかせたまま？「ヘルシーレシピ」から、消化がよく元気の出る軽食をつくりましょう。赤ちゃんに力をあげるには、あなたが元気でいることが大切です。', title_ko = '엄마를 위한 에너지 창고 🍲', body_ko = '아기를 먹이느라 엄마는 굶고 있나요? 건강한 레시피 섹션에서 소화가 잘되고 든든한 간식을 만들어 보세요. 엄마가 튼튼해야 아기에게도 힘을 줄 수 있어요.', title_nl = 'Een energievoorraad voor mama 🍲', body_nl = 'Heb je jezelf laten hongeren terwijl je je baby voedde? Maak uit het onderdeel Gezonde recepten een licht verteerbaar, energierijk tussendoortje. Je moet sterk zijn om je baby kracht te kunnen geven.', title_pl = 'Magazyn energii dla mamy 🍲', body_pl = 'Karmiąc dziecko, zostawiłaś siebie głodną? Przygotuj ze Zdrowych przepisów lekkostrawną, energetyczną przekąskę. Musisz być silna, żeby dawać siłę jemu.', title_pt = 'Um armazém de energia para a mãe 🍲', body_pt = 'De tanto alimentar o bebé, ficou com fome? Prepare na secção Receitas Saudáveis um lanche energético e fácil de digerir. Tem de estar forte para lhe dar força a ele.', title_sv = 'Energiförråd för mamma 🍲', body_sv = 'Har du låtit dig själv gå hungrig medan du matar barnet? Gör ett lättsmält och energirikt mellanmål från avsnittet Hälsosamma recept. Du måste vara stark för att kunna ge barnet styrka.', title_vi = 'Kho năng lượng cho mẹ 🍲', body_vi = 'Lo cho bé no mà mẹ lại để mình đói? Hãy làm một món ăn nhẹ dễ tiêu, giàu năng lượng từ mục Công thức lành mạnh. Mẹ phải khỏe để tiếp sức cho bé.', title_zh = '妈妈的能量仓库 🍲', body_zh = '忙着喂饱宝宝，自己却饿着肚子？从健康食谱板块做一份易消化、能补充能量的小零食吧。你要强壮，才能给宝宝力量。' WHERE id = 'd584b1c4-e42a-483d-b585-e83a9ab20c88' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Háblame! 🗣️', body_es = '¿Te mira e inventa sílabas curiosas? Responde a sus sonidos y a sus pausas. ¡Ahora mismo está teniendo un verdadero diálogo contigo! Es el paso más básico del desarrollo del lenguaje.', title_fr = 'Parle-moi ! 🗣️', body_fr = 'Il vous regarde en inventant de drôles de syllabes ? Réagissez à sa voix, à ses pauses. Il est en train de dialoguer vraiment avec vous ! C''est la toute première étape du langage.', title_hi = 'मुझसे बात कीजिए! 🗣️', body_hi = 'आपको देखकर अजीब-अजीब आवाज़ें निकालता है? उसकी आवाज़ और रुकने पर प्रतिक्रिया दीजिए। वह अभी आपसे सच्ची बातचीत कर रहा है! यह भाषा के विकास का सबसे बुनियादी कदम है।', title_id = 'Bicaralah padaku! 🗣️', body_id = 'Ia menatap Anda sambil menciptakan suku kata yang aneh? Tanggapi suara dan jedanya. Ia sedang benar-benar berdialog dengan Anda! Ini langkah paling dasar dalam perkembangan bahasa.', title_ja = 'お話しして！🗣️', body_ja = 'ママを見ながら、不思議な音をつくり出していますか？その声や間に反応してあげましょう。赤ちゃんは今、本当にママと会話しているのです！これは言葉の発達のいちばんの土台です。', title_ko = '저랑 이야기해요! 🗣️', body_ko = '엄마를 보며 신기한 소리를 지어내나요? 아기의 소리와 멈춤에 반응해 주세요. 아기는 지금 엄마와 진짜 대화를 하고 있어요! 이것이 언어 발달의 가장 기본적인 단계예요.', title_nl = 'Praat met me! 🗣️', body_nl = 'Kijkt je baby je aan en verzint hij vreemde lettergrepen? Reageer op zijn geluidjes en pauzes. Hij voert nu een echt gesprek met je! Dit is de belangrijkste basisstap in de taalontwikkeling.', title_pl = 'Mów do mnie! 🗣️', body_pl = 'Patrzy na ciebie i wymyśla dziwne sylaby? Reaguj na jego głos i pauzy. Prowadzi teraz z tobą prawdziwy dialog! To najbardziej podstawowy krok w rozwoju mowy.', title_pt = 'Fale comigo! 🗣️', body_pt = 'Olha para si e inventa sílabas estranhas? Reaja à voz e às pausas dele. Neste momento, está a ter um verdadeiro diálogo consigo! É o passo mais básico do desenvolvimento da linguagem.', title_sv = 'Prata med mig! 🗣️', body_sv = 'Tittar barnet på dig och hittar på konstiga stavelser? Reagera på ljuden och pauserna. Barnet för just nu en riktig dialog med dig! Det är det mest grundläggande steget i språkutvecklingen.', title_vi = 'Nói chuyện với con đi! 🗣️', body_vi = 'Bé nhìn mẹ và tự nghĩ ra những âm tiết lạ lùng? Hãy đáp lại giọng và những khoảng ngừng của bé. Lúc này bé đang thật sự đối thoại với mẹ! Đây là bước nền tảng nhất của phát triển ngôn ngữ.', title_zh = '和我说说话！🗣️', body_zh = '宝宝看着你，编出奇怪的音节？回应宝宝的声音和停顿。宝宝现在正在和你进行真正的对话！这是语言发育最基础的一步。' WHERE id = '014e3f07-72e8-47f8-b62e-ff583a9df29e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidades invisibles 🛒', body_es = 'Con tanto ajetreo, ¿se está acabando algo? ¿Papel higiénico, pañales, champú? Añádelo ahora a la Lista de la compra, antes de que se te olvide, y le llegará a tu pareja como notificación.', title_fr = 'Les besoins invisibles 🛒', body_fr = 'Quelque chose va manquer dans le tourbillon du quotidien ? Papier toilette, couches, shampoing ? Ajoutez-le tout de suite à la Liste de courses, avant d''oublier, pour que votre conjoint reçoive une notification.', title_hi = 'छुपी हुई ज़रूरतें 🛒', body_hi = 'रोज़ की भागदौड़ में कुछ खत्म होने वाला है? टॉयलेट पेपर, डायपर, शैम्पू? अभी, भूलने से पहले शॉपिंग लिस्ट में जोड़िए, ताकि साथी के फ़ोन पर नोटिफ़िकेशन चला जाए।', title_id = 'Kebutuhan yang tak terlihat 🛒', body_id = 'Ada yang hampir habis di tengah kesibukan sehari-hari? Tisu toilet, popok, sampo? Tambahkan ke Daftar Belanja sekarang sebelum lupa, biar terkirim sebagai notifikasi ke ponsel pasangan Anda.', title_ja = '見えないニーズ 🛒', body_ja = '毎日のバタバタの中で、何かが切れそう？トイレットペーパー、おむつ、シャンプー？忘れないうちに「買い物リスト」に追加して、パートナーのスマホに通知を送りましょう。', title_ko = '보이지 않는 필요 🛒', body_ko = '바쁜 하루 속에 떨어져 가는 게 있나요? 화장지, 기저귀, 샴푸? 잊기 전에 지금 쇼핑 목록에 추가하면 배우자 휴대폰으로 알림이 가요.', title_nl = 'Onzichtbare behoeften 🛒', body_nl = 'Raakt er in de dagelijkse drukte iets op? Wc-papier, luiers, shampoo? Zet het nu op het Boodschappenlijstje voor je het vergeet, dan krijgt je partner er een melding van op zijn telefoon.', title_pl = 'Niewidoczne potrzeby 🛒', body_pl = 'W codziennym biegu coś się kończy? Papier toaletowy, pieluszki, szampon? Dodaj to teraz do listy zakupów, zanim zapomnisz, a partner dostanie powiadomienie na telefon.', title_pt = 'Necessidades invisíveis 🛒', body_pt = 'Na correria do dia a dia, há algo a acabar? Papel higiénico, fraldas, champô? Junte-o já à Lista de Compras, antes que se esqueça, e a notificação chega ao telemóvel do seu companheiro.', title_sv = 'Osynliga behov 🛒', body_sv = 'Håller något på att ta slut i den dagliga stressen? Toalettpapper, blöjor, schampo? Lägg till det på Inköpslistan nu innan du glömmer, så går det som en avisering till din partners telefon.', title_vi = 'Những nhu cầu vô hình 🛒', body_vi = 'Giữa bộn bề mỗi ngày, có thứ gì sắp hết? Giấy vệ sinh, tã, dầu gội? Hãy thêm ngay vào Danh sách mua sắm kẻo quên, thông báo sẽ gửi đến điện thoại của chồng.', title_zh = '看不见的需求 🛒', body_zh = '每天忙忙碌碌，有什么快用完了？卫生纸、尿布、洗发水？趁还没忘，现在就加进购物清单，让它作为通知发到另一半的手机上。' WHERE id = 'c290d85d-0e02-4b4e-aaab-db6ae8bfcaef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento no tiene final 📖', body_es = 'Esta noche dale a Cuentos inteligentes un encargo más creativo: «La historia del osito que buscaba el olor de su mamá». Termina la noche con un final tranquilo y lleno de amor.', title_fr = 'Un conte sans fin 📖', body_fr = 'Ce soir, donnez une mission plus créative aux Contes intelligents : « L''histoire du petit ours qui cherchait l''odeur de sa maman ». Terminez la nuit sur une fin calme et pleine d''amour.', title_hi = 'कहानी का कोई अंत नहीं 📖', body_hi = 'आज शाम स्मार्ट कहानियों को और रचनात्मक काम दीजिए: “अपनी माँ की खुशबू ढूँढते नन्हे भालू की कहानी”। रात को प्यार भरे और शांत अंत के साथ खत्म कीजिए।', title_id = 'Dongeng tak pernah berakhir 📖', body_id = 'Malam ini beri Dongeng Pintar tugas yang lebih kreatif: “Kisah beruang kecil yang mencari aroma ibunya”. Akhiri malam dengan penutup yang penuh cinta dan tenang.', title_ja = 'お話に終わりはない 📖', body_ja = '今夜は「スマートおはなし」に、もっとクリエイティブなお題を：「ママのにおいを探す小さなクマのお話」。愛にあふれた穏やかな結末で夜を締めくくりましょう。', title_ko = '끝없는 동화 📖', body_ko = '오늘 저녁 스마트 동화에 더 창의적인 주제를 줘 보세요: “엄마 냄새를 찾아 나선 꼬마 곰 이야기”. 사랑 가득하고 평온한 결말로 밤을 마무리하세요.', title_nl = 'Het sprookje is nooit uit 📖', body_nl = 'Geef Slimme sprookjes vanavond een creatievere opdracht: “Het verhaal van het kleine beertje dat de geur van zijn mama zoekt”. Sluit de avond af met een liefdevol en rustig einde.', title_pl = 'Bajka nie ma końca 📖', body_pl = 'Dziś wieczorem daj Mądrym bajkom bardziej kreatywne zadanie: „Historia małego misia, który szukał zapachu mamy”. Zakończ noc pełnym miłości i spokojnym finałem.', title_pt = 'A história não tem fim 📖', body_pt = 'Esta noite, dê às Histórias Inteligentes uma tarefa mais criativa: "A história do ursinho que procurava o cheiro da mãe". Termine a noite com um final tranquilo e cheio de amor.', title_sv = 'Sagan tar aldrig slut 📖', body_sv = 'Ge Smarta sagor ett mer kreativt uppdrag i kväll: ''Berättelsen om den lilla björnen som letade efter sin mammas doft''. Avsluta kvällen med ett kärleksfullt och lugnt slut.', title_vi = 'Câu chuyện không có hồi kết 📖', body_vi = 'Tối nay hãy giao cho Truyện cổ tích thông minh một nhiệm vụ sáng tạo hơn: “Câu chuyện về chú gấu nhỏ đi tìm mùi hương của mẹ”. Khép lại đêm với một cái kết êm đềm, đầy yêu thương.', title_zh = '童话没有结局 📖', body_zh = '今晚给智慧童话一个更有创意的任务：“寻找妈妈气味的小熊的故事”。用一个充满爱的安静结局结束这一夜吧。' WHERE id = '43fbc1cb-7e93-4983-b59f-f5bc67650d3e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Señales de sueño 🥱', title_fr = 'Les signaux du sommeil 🥱', title_hi = 'नींद के संकेत 🥱', title_id = 'Tanda-tanda mengantuk 🥱', title_ja = '眠いサイン 🥱', title_ko = '졸음 신호 🥱', title_nl = 'Slaapsignalen 🥱', title_pl = 'Sygnały senności 🥱', title_pt = 'Sinais de sono 🥱', title_sv = 'Sömnsignaler 🥱', title_vi = 'Tín hiệu buồn ngủ 🥱', title_zh = '犯困信号 🥱' WHERE id = 'da354848-a7ac-41ba-9616-ccf0b8799a86' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gimnasia matutina 🐢', body_es = 'Estar boca abajo fortalece los músculos del cuello. Aunque llore, sigue haciéndolo cada día, aunque sea poco rato.', title_fr = 'Gym du matin 🐢', body_fr = 'Rester sur le ventre renforce les muscles du cou. Même s''il pleure, continuez chaque jour, ne serait-ce que quelques instants.', title_hi = 'सुबह की कसरत 🐢', body_hi = 'पेट के बल लेटना गर्दन की मांसपेशियाँ मज़बूत करता है। भले वह रोए, थोड़ी देर के लिए ही सही, रोज़ इसे जारी रखिए।', title_id = 'Olahraga pagi 🐢', body_id = 'Tengkurap menguatkan otot leher. Meski ia menangis, teruskan setiap hari walau hanya sebentar.', title_ja = '朝の体操 🐢', body_ja = 'うつぶせ遊びは首の筋肉を鍛えます。泣いてしまっても、短い時間でいいので毎日続けましょう。', title_ko = '아침 운동 🐢', body_ko = '엎드려 있기는 목 근육을 튼튼하게 해요. 울더라도 짧게라도 매일 계속해 주세요.', title_nl = 'Ochtendgymnastiek 🐢', body_nl = 'Op de buik liggen versterkt de nekspieren. Ga er elke dag mee door, ook al is het maar kort en ook al huilt je baby.', title_pl = 'Poranna gimnastyka 🐢', body_pl = 'Leżenie na brzuszku wzmacnia mięśnie szyi. Nawet jeśli płacze, kontynuuj to codziennie, choćby przez krótką chwilę.', title_pt = 'Exercício matinal 🐢', body_pt = 'Ficar de barriga para baixo fortalece os músculos do pescoço. Mesmo que chore, continue todos os dias, nem que seja por pouco tempo.', title_sv = 'Morgongympa 🐢', body_sv = 'Att ligga på magen stärker nackmusklerna. Även om barnet gråter, fortsätt varje dag, om så bara en kort stund.', title_vi = 'Bài tập buổi sáng 🐢', body_vi = 'Nằm sấp giúp cơ cổ khỏe hơn. Dù bé khóc, hãy duy trì mỗi ngày, dù chỉ trong thời gian ngắn.', title_zh = '晨间运动 🐢', body_zh = '趴着能增强颈部肌肉。即使宝宝哭，也每天坚持一小会儿吧。' WHERE id = '70597740-ab51-4b20-b743-042bccb768a6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Plan para salir de casa! 🌳', body_es = '¿No sabes adónde ir con el bebé? ¿Pasear por el parque te cansa? Descubre en Lugares para mamás un sitio donde sentarte cómoda con el bebé y tomarte un café.', title_fr = 'Plan de sortie ! 🌳', body_fr = 'Vous ne savez pas où aller avec bébé ? La promenade au parc vous fatigue ? Découvrez dans les Lieux adaptés aux mamans un endroit où vous installer confortablement avec bébé et boire un café.', title_hi = 'घर से निकलने का प्लान! 🌳', body_hi = 'पता नहीं बच्चे के साथ कहाँ जा सकती हैं? पार्क में घूमना थकाने वाला है? माँ के लिए अनुकूल जगहों में ऐसी जगह खोजिए जहाँ बच्चे के साथ आराम से बैठ सकें और कॉफ़ी भी पी सकें।', title_id = 'Rencana keluar rumah! 🌳', body_id = 'Tidak tahu harus ke mana bersama anak? Jalan-jalan di taman melelahkan? Temukan tempat di Tempat Ramah Ibu di mana Anda bisa duduk nyaman bersama anak sekaligus minum kopi.', title_ja = 'おでかけ計画！🌳', body_ja = '赤ちゃんとどこへ行けばいいかわからない？公園のお散歩は疲れる？「ママにやさしいスポット」で、赤ちゃんとゆったり座れて、コーヒーも楽しめる場所を見つけましょう。', title_ko = '외출 계획! 🌳', body_ko = '아기와 어디로 가야 할지 모르겠나요? 공원 산책은 지치나요? 엄마 친화 장소에서 아기와 편히 앉아 커피도 마실 수 있는 곳을 찾아보세요.', title_nl = 'Plan om de deur uit te gaan! 🌳', body_nl = 'Weet je niet waar je met je baby heen kunt? Is wandelen in het park vermoeiend? Ontdek in Mamavriendelijke plekken een plek waar je fijn met je baby kunt zitten en ook een kop koffie kunt drinken.', title_pl = 'Plan wyjścia z domu! 🌳', body_pl = 'Nie wiesz, dokąd możesz pójść z dzieckiem? Spacer po parku męczy? Odkryj w Miejscach przyjaznych mamom miejsce, w którym wygodnie usiądziesz z dzieckiem i napijesz się kawy.', title_pt = 'Plano para sair de casa! 🌳', body_pt = 'Não sabe aonde ir com o bebé? Passear no parque cansa? Descubra nos Locais Amigos das Mães um sítio onde pode estar à vontade com o bebé e beber um café.', title_sv = 'Plan för att komma ut! 🌳', body_sv = 'Vet du inte vart du kan gå med barnet? Är promenader i parken tröttsamma? Upptäck ett ställe i Mammavänliga platser där du både kan sitta bekvämt med barnet och dricka en kaffe.', title_vi = 'Kế hoạch ra ngoài! 🌳', body_vi = 'Không biết đưa bé đi đâu? Đi công viên thì mệt? Hãy khám phá trong Địa điểm thân thiện với mẹ một nơi vừa ngồi thoải mái cùng bé, vừa có thể uống một tách cà phê.', title_zh = '出门计划！🌳', body_zh = '不知道能带宝宝去哪儿？在公园散步太累？在妈妈友好场所里找一个既能带宝宝舒服坐着、又能喝杯咖啡的地方吧。' WHERE id = 'b8cf3d8c-2c7c-497e-8657-18fd989a1928' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aplaúdete 👏', body_es = 'Al mirar atrás, ves lo aterradores que fueron los primeros días y lo mucho que te enseñan ahora. Siéntete orgullosa de ti. El bebé no solo ha crecido 100 días, tú también has crecido 100 días.', title_fr = 'Applaudissez-vous 👏', body_fr = 'En regardant en arrière, vous voyez combien les premiers jours étaient effrayants, et combien ils vous ont appris. Soyez fière de vous. Bébé n''a pas seulement grandi de 100 jours, vous aussi.', title_hi = 'खुद के लिए तालियाँ बजाइए 👏', body_hi = 'पीछे मुड़कर देखती हैं तो दिखता है कि पहले दिन कितने डरावने थे और अब कितना कुछ सिखाने वाले हैं। खुद पर गर्व कीजिए। सिर्फ़ बच्चा 100 दिन नहीं बढ़ा, आप भी 100 दिन बढ़ी हैं।', title_id = 'Beri tepuk tangan untuk diri sendiri 👏', body_id = 'Saat menoleh ke belakang, Anda melihat betapa menakutkannya hari-hari pertama, dan betapa banyak pelajaran yang didapat sekarang. Banggalah pada diri sendiri. Bukan hanya anak yang tumbuh selama 100 hari, Anda pun ikut tumbuh selama 100 hari.', title_ja = '自分に拍手を 👏', body_ja = 'ふり返ると、最初の日々がどれほど怖く、今はどれほど学びに満ちているかがわかります。自分を誇りに思いましょう。赤ちゃんだけが100日成長したのではなく、あなたも100日成長したのです。', title_ko = '스스로에게 박수를 👏', body_ko = '돌아보면 첫날들이 얼마나 두려웠는지, 그리고 지금은 얼마나 많이 배웠는지 알 수 있어요. 스스로를 자랑스러워하세요. 아기만 100일 동안 자란 게 아니라 엄마도 100일 동안 자랐어요.', title_nl = 'Geef jezelf een applaus 👏', body_nl = 'Als je terugkijkt, zie je hoe eng de eerste dagen waren en hoeveel je er nu van hebt geleerd. Wees trots op jezelf. Niet alleen je kind is 100 dagen gegroeid, jij ook.', title_pl = 'Nagródź się brawami 👏', body_pl = 'Patrząc wstecz, widzisz, jak przerażające były pierwsze dni i ile cię nauczyły. Bądź z siebie dumna. Nie tylko dziecko rosło przez 100 dni, ty też rosłaś przez 100 dni.', title_pt = 'Aplauda-se 👏', body_pt = 'Ao olhar para trás, vê como os primeiros dias foram assustadores e como agora são de aprendizagem. Orgulhe-se de si. Não foi só o bebé que cresceu 100 dias, a mãe também cresceu 100 dias.', title_sv = 'Applådera dig själv 👏', body_sv = 'När du blickar tillbaka ser du hur skrämmande de första dagarna var och hur lärorikt det är nu. Var stolt över dig själv. Det är inte bara barnet som har vuxit i 100 dagar, du har också vuxit i 100 dagar.', title_vi = 'Vỗ tay cho chính mình 👏', body_vi = 'Nhìn lại, mẹ thấy những ngày đầu đáng sợ thế nào, và giờ đã dạy mẹ bao điều. Hãy tự hào về bản thân. Bé không chỉ lớn thêm 100 ngày, mẹ cũng đã trưởng thành thêm 100 ngày.', title_zh = '为自己鼓掌 👏', body_zh = '回头看看，你会发现最初的日子多么让人害怕，而现在又多么让人成长。为自己骄傲吧。宝宝不只是长大了100天，你也成长了100天。' WHERE id = '7c63492d-1515-406a-bd31-b41ece7e0412' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Contacto piel con piel 🫂', body_es = '¿El bebé está muy inquieto? Si nada funciona, ponlo sobre tu pecho. Tus latidos son el mejor calmante.', title_fr = 'Le peau à peau 🫂', body_fr = 'Bébé est très agité ? Si rien ne marche, posez-le contre votre poitrine. Les battements de votre cœur sont le meilleur apaisant.', title_hi = 'त्वचा से त्वचा का स्पर्श 🫂', body_hi = 'बच्चा बहुत बेचैन है? अगर कुछ काम नहीं कर रहा, तो उसे अपने सीने पर रखिए। आपकी धड़कन सबसे अच्छा सुकून है।', title_id = 'Kontak kulit ke kulit 🫂', body_id = 'Bayi sangat gelisah? Jika tidak ada yang berhasil, letakkan ia di dada Anda. Detak jantung Anda adalah penenang terbaik.', title_ja = '肌と肌のふれあい 🫂', body_ja = '赤ちゃんがとても落ち着かない？何をしてもだめなら、胸に抱いてあげましょう。ママの心臓の音がいちばんの安心材料です。', title_ko = '맨살 스킨십 🫂', body_ko = '아기가 많이 불안해하나요? 아무것도 통하지 않으면 가슴에 안아 주세요. 엄마의 심장 소리가 최고의 진정제예요.', title_nl = 'Huid-op-huidcontact 🫂', body_nl = 'Is je baby heel onrustig? Werkt niets, leg hem dan op je borst. Jouw hartslag kalmeert het allerbest.', title_pl = 'Kontakt skóra do skóry 🫂', body_pl = 'Dziecko jest bardzo niespokojne? Jeśli nic nie działa, połóż je na swojej piersi. Bicie twojego serca to najlepszy uspokajacz.', title_pt = 'Contacto pele com pele 🫂', body_pt = 'O bebé está muito inquieto? Se nada resulta, ponha-o ao peito. O bater do seu coração é o melhor calmante.', title_sv = 'Hud mot hud 🫂', body_sv = 'Är barnet väldigt oroligt? Om ingenting hjälper, lägg barnet mot ditt bröst. Dina hjärtslag är det bästa lugnandet.', title_vi = 'Tiếp xúc da kề da 🫂', body_vi = 'Bé rất bồn chồn? Nếu không cách nào hiệu quả, hãy đặt bé lên ngực mẹ. Nhịp tim của mẹ là liều thuốc xoa dịu tốt nhất.', title_zh = '肌肤接触 🫂', body_zh = '宝宝特别烦躁？如果什么都不管用，就把宝宝贴在你胸前。你的心跳是最好的安抚。' WHERE id = 'dd50206e-acee-43ac-8f19-c5dd29cf7e62' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego de tirar del pelo 💇‍♀️', body_es = '¿Te enreda los dedos en el pelo y tira con fuerza? Su reflejo de agarre se está desarrollando. Intenta reírte de esta etapa un poco dolorosa.', title_fr = 'Le jeu des cheveux tirés 💇‍♀️', body_fr = 'Il enroule ses doigts dans vos cheveux et tire fort ? Son réflexe de préhension se développe. Essayez d''en rire, même si cette étape fait un peu mal.', title_hi = 'बाल खींचने का खेल 💇‍♀️', body_hi = 'उँगलियाँ आपके बालों में लपेटकर ज़ोर से खींचता है? उसकी पकड़ विकसित हो रही है। विकास के इस थोड़े दर्द भरे पल पर हँसने की कोशिश कीजिए।', title_id = 'Permainan menarik rambut 💇‍♀️', body_id = 'Ia melilitkan jarinya ke rambut Anda dan menariknya kuat-kuat? Refleks menggenggamnya berkembang. Cobalah tertawa menghadapi momen perkembangan yang sedikit menyakitkan ini.', title_ja = '髪の毛つかみ遊び 💇‍♀️', body_ja = '指をママの髪にからめて、ぎゅっと引っぱりますか？にぎる力が発達しています。少し痛いこの成長の瞬間を、笑って楽しんでみましょう。', title_ko = '머리카락 잡아당기기 놀이 💇‍♀️', body_ko = '손가락에 엄마 머리카락을 감고 세게 잡아당기나요? 잡기 반사가 발달하고 있어요. 조금 아픈 이 발달의 순간을 웃으며 넘겨 보세요.', title_nl = 'Het haartrekspelletje 💇‍♀️', body_nl = 'Draait je baby zijn vingertjes in je haar en trekt hij hard? De grijpreflex ontwikkelt zich. Probeer te lachen om dit ietwat pijnlijke ontwikkelingsmoment.', title_pl = 'Zabawa w ciągnięcie za włosy 💇‍♀️', body_pl = 'Owija paluszki wokół twoich włosów i mocno ciągnie? Rozwija się odruch chwytania. Spróbuj pośmiać się z tej trochę bolesnej chwili rozwoju.', title_pt = 'A brincadeira de puxar cabelos 💇‍♀️', body_pt = 'Enrola os dedos no seu cabelo e puxa com força? O reflexo de preensão está a desenvolver-se. Tente rir-se deste momento de desenvolvimento um pouco doloroso.', title_sv = 'Hårdragningsleken 💇‍♀️', body_sv = 'Lindar barnet fingrarna i ditt hår och drar hårt? Gripreflexen utvecklas. Försök skratta åt den här lite smärtsamma utvecklingsstunden.', title_vi = 'Trò chơi giật tóc 💇‍♀️', body_vi = 'Bé quấn ngón tay vào tóc mẹ và giật mạnh? Phản xạ cầm nắm đang phát triển. Hãy cố mỉm cười với giai đoạn phát triển hơi đau này nhé.', title_zh = '拽头发游戏 💇‍♀️', body_zh = '宝宝把手指缠进你的头发使劲拽？抓握反射在发育。试着笑对这个有点疼的成长时刻吧。' WHERE id = '2c73f922-1b22-4eb6-922b-215d8e623242' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tonos distintos 🗣️', body_es = 'Sus balbuceos empiezan a sonar más fuertes y variados. Escúchale e imítale para hacerle reír.', title_fr = 'Des intonations différentes 🗣️', body_fr = 'Son babillage devient plus fort et plus varié. Écoutez-le et imitez-le pour le faire rire.', title_hi = 'अलग-अलग सुर 🗣️', body_hi = 'उसकी बोली और ऊँची और रंग-बिरंगी लगने लगी है। सुनिए और उसकी नकल करके उसे हँसाइए।', title_id = 'Nada yang berbeda 🗣️', body_id = 'Ocehannya mulai terdengar lebih keras dan beragam. Dengarkan dan buat ia tertawa dengan menirukannya.', title_ja = 'いろいろなトーン 🗣️', body_ja = '赤ちゃんのおしゃべりが、より大きく、より豊かな音になってきました。耳を傾けて、まねをして笑わせてあげましょう。', title_ko = '다양한 톤 🗣️', body_ko = '아기의 옹알이가 더 크고 다채로워지기 시작했어요. 귀 기울여 듣고 따라 하며 아기를 웃게 해 주세요.', title_nl = 'Verschillende tonen 🗣️', body_nl = 'Het gebrabbel van je baby klinkt steeds harder en gevarieerder. Luister en doe het na om hem aan het lachen te maken.', title_pl = 'Różne tony 🗣️', body_pl = 'Jego mowa zaczyna brzmieć głośniej i bardziej różnorodnie. Słuchaj i naśladuj, by go rozśmieszyć.', title_pt = 'Tons diferentes 🗣️', body_pt = 'A "conversa" dele começou a soar mais alta e variada. Ouça-o e faça-o rir imitando-o.', title_sv = 'Olika tonlägen 🗣️', body_sv = 'Barnets prat har börjat låta högre och mer varierat. Lyssna och få barnet att skratta genom att härma.', title_vi = 'Những tông giọng khác nhau 🗣️', body_vi = 'Tiếng bi bô của bé bắt đầu to hơn và đa dạng hơn. Hãy lắng nghe và bắt chước để bé bật cười.', title_zh = '不同的语调 🗣️', body_zh = '宝宝的“说话”声越来越响亮、越来越丰富了。认真听，模仿宝宝的声音逗宝宝笑吧。' WHERE id = '924ff591-18ec-4c20-80af-4008cda2fc41' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Silencio absoluto 🤫', body_es = '¿Le cuesta dormirse? Oscurece por completo la habitación y corta el ruido. La oscuridad y el silencio son sus mejores amigos para dormir.', title_fr = 'Silence absolu 🤫', body_fr = 'Il a du mal à s''endormir ? Faites le noir complet dans la chambre et coupez les bruits. L''obscurité et le silence sont ses meilleurs alliés pour dormir.', title_hi = 'पूरी खामोशी 🤫', body_hi = 'सोने में मुश्किल हो रही है? कमरे में पूरा अँधेरा कीजिए और आवाज़ बंद कीजिए। अँधेरा और खामोशी उसकी नींद के सबसे अच्छे दोस्त हैं।', title_id = 'Keheningan total 🤫', body_id = 'Sulit tertidur? Gelapkan kamar sepenuhnya dan matikan suara. Gelap dan hening adalah teman tidur terbaiknya.', title_ja = '完全な静けさ 🤫', body_ja = 'なかなか寝つけない？部屋を真っ暗にして、音を消しましょう。暗さと静けさは、赤ちゃんのいちばんの睡眠の友達です。', title_ko = '완전한 고요함 🤫', body_ko = '잠들기 힘들어하나요? 방을 완전히 어둡게 하고 소리를 꺼 주세요. 어둠과 고요함이 아기의 가장 좋은 잠 친구예요.', title_nl = 'Volledige stilte 🤫', body_nl = 'Moeite met inslapen? Maak de kamer helemaal donker en zet alle geluid uit. Donker en stilte zijn de beste slaapmaatjes.', title_pl = 'Zupełna cisza 🤫', body_pl = 'Trudno mu zasnąć? Całkowicie zaciemnij pokój i wycisz dźwięki. Ciemność i cisza to jego najlepsi przyjaciele snu.', title_pt = 'Silêncio absoluto 🤫', body_pt = 'Tem dificuldade em adormecer? Escureça bem o quarto e corte o som. A escuridão e o silêncio são os melhores amigos do sono dele.', title_sv = 'Total tystnad 🤫', body_sv = 'Har barnet svårt att somna? Mörklägg rummet helt och stäng av ljuden. Mörker och tystnad är barnets bästa sömnvänner.', title_vi = 'Yên tĩnh tuyệt đối 🤫', body_vi = 'Bé khó vào giấc? Làm tối hẳn căn phòng và tắt mọi âm thanh. Bóng tối và sự yên tĩnh là người bạn tốt nhất cho giấc ngủ của bé.', title_zh = '绝对安静 🤫', body_zh = '入睡困难？把房间完全调暗，关掉声音。黑暗和安静是宝宝最好的睡眠伙伴。' WHERE id = 'f32eaadc-b85c-4f36-b182-6f6665e1eaae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Llegan los primeros dientes? 🦷', body_es = '¿Babea más? Anótalo en el Seguimiento de dentición y ten a mano mordedores limpios.', title_fr = 'Les premières dents arrivent ? 🦷', body_fr = 'Il bave de plus en plus ? Prenez des notes dans le Suivi des dents et gardez des anneaux de dentition propres à portée de main.', title_hi = 'पहले दाँत आ रहे हैं? 🦷', body_hi = 'लार ज़्यादा बहने लगी है? दाँत निकलने के ट्रैकर में दर्ज कीजिए और साफ़ टीदर हाथ के पास रखिए।', title_id = 'Gigi pertama akan muncul? 🦷', body_id = 'Air liurnya makin banyak? Buat catatan di Pelacak Tumbuh Gigi dan sediakan teether yang bersih di dekat Anda.', title_ja = '最初の歯が生えてくる？🦷', body_ja = 'よだれが増えましたか？「歯の生え始めトラッカー」に記録して、清潔な歯固めを手元に用意しておきましょう。', title_ko = '첫 이가 나고 있나요? 🦷', body_ko = '침이 많아졌나요? 이앓이 기록에 기록하고 깨끗한 치아발육기를 손 닿는 곳에 두세요.', title_nl = 'Komen de eerste tandjes eraan? 🦷', body_nl = 'Kwijlt je baby meer? Maak een notitie in de Tandjestracker en houd schone bijtringen bij de hand.', title_pl = 'Idą pierwsze ząbki? 🦷', body_pl = 'Ślinienia przybyło? Zapisuj to w narzędziu do śledzenia ząbkowania i trzymaj pod ręką czyste gryzaki.', title_pt = 'Estão a chegar os primeiros dentes? 🦷', body_pt = 'A baba aumentou? Faça registos no Registo de Dentição e tenha à mão mordedores limpos.', title_sv = 'Kommer de första tänderna? 🦷', body_sv = 'Har dreglandet ökat? Anteckna i Tandspåraren och ha rena bitringar nära till hands.', title_vi = 'Những chiếc răng đầu tiên sắp mọc? 🦷', body_vi = 'Bé chảy dãi nhiều hơn? Hãy ghi lại trong Theo dõi mọc răng và để sẵn đồ gặm nướu sạch bên cạnh.', title_zh = '第一颗牙要来了？🦷', body_zh = '口水变多了？在出牙记录里做好记录，手边常备干净的牙胶。' WHERE id = 'f4e3cb01-431f-4e52-a62b-ab96cbc1de4b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tiempo libre 🛋️', body_es = 'Mientras juega solo, no corras a hacer tareas. Siéntate y, solo 5 minutos, obsérvale desde lejos mientras te tomas el café.', title_fr = 'Un moment de liberté 🛋️', body_fr = 'Quand il joue tout seul, ne vous précipitez pas sur les tâches. Asseyez-vous et buvez votre café en le regardant de loin, juste 5 minutes.', title_hi = 'आज़ादी का समय 🛋️', body_hi = 'जब वह खुद खेल रहा हो, तुरंत काम पर मत भागिए। बैठिए और बस 5 मिनट दूर से उसे देखते हुए अपनी कॉफ़ी पीजिए।', title_id = 'Waktu bebas 🛋️', body_id = 'Saat ia bermain sendiri, jangan langsung lari mengerjakan pekerjaan rumah. Duduklah, amati ia dari jauh selama 5 menit saja sambil minum kopi.', title_ja = '自由な時間 🛋️', body_ja = '赤ちゃんがひとりで遊んでいるときは、すぐ家事に走らないで。座って、5分間だけ離れたところから見守りながら、コーヒーを飲みましょう。', title_ko = '자유 시간 🛋️', body_ko = '아기가 혼자 놀 때 바로 집안일로 달려가지 마세요. 앉아서 5분만 멀리서 아기를 바라보며 커피를 드세요.', title_nl = 'Tijd voor jezelf 🛋️', body_nl = 'Ren niet meteen naar je klusjes als je baby zelf speelt. Ga zitten, kijk 5 minuten van een afstandje toe en drink je koffie.', title_pl = 'Czas wolny 🛋️', body_pl = 'Gdy bawi się samo, nie biegnij od razu do obowiązków. Usiądź i przez 5 minut po prostu obserwuj je z daleka, pijąc kawę.', title_pt = 'Hora de liberdade 🛋️', body_pt = 'Quando ele brinca sozinho, não corra logo para as tarefas. Sente-se e, durante só 5 minutos, observe-o de longe e beba o seu café.', title_sv = 'Egen tid 🛋️', body_sv = 'När barnet leker för sig själv, rusa inte direkt iväg till sysslorna. Sätt dig ner, titta på barnet på avstånd i bara 5 minuter och drick ditt kaffe.', title_vi = 'Thời gian tự do 🛋️', body_vi = 'Khi bé tự chơi, đừng vội lao vào việc nhà. Hãy ngồi xuống, ngắm bé từ xa 5 phút và nhâm nhi cà phê.', title_zh = '自由时间 🛋️', body_zh = '宝宝自己玩的时候，别马上跑去干家务。坐下来，从远处看宝宝5分钟，喝杯咖啡吧。' WHERE id = '724659ec-f59f-4bfe-b20d-efdd3d977217' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Primer día del tercer mes! 🎉', body_es = 'Tu bebé ya observa su entorno de forma más consciente.', title_fr = 'Le premier jour du troisième mois ! 🎉', body_fr = 'Votre bébé observe déjà son environnement de façon plus consciente.', title_hi = 'तीसरे महीने का पहला दिन! 🎉', body_hi = 'आपका बच्चा अब आसपास की चीज़ों को ज़्यादा समझदारी से देखता है।', title_id = 'Hari pertama bulan ketiga! 🎉', body_id = 'Bayi Anda kini mengamati sekitarnya dengan lebih sadar.', title_ja = '3か月目の最初の日！🎉', body_ja = '赤ちゃんはもう、まわりの様子をより意識して見ています。', title_ko = '3개월째 첫날! 🎉', body_ko = '아기가 이제 주변을 더 또렷하게 의식하며 바라봐요.', title_nl = 'De eerste dag van de derde maand! 🎉', body_nl = 'Je baby volgt de omgeving al veel bewuster.', title_pl = 'Pierwszy dzień trzeciego miesiąca! 🎉', body_pl = 'Dziecko coraz świadomiej obserwuje otoczenie.', title_pt = 'O primeiro dia do terceiro mês! 🎉', body_pt = 'O bebé já observa o que o rodeia com mais consciência.', title_sv = 'Första dagen i tredje månaden! 🎉', body_sv = 'Barnet följer nu omgivningen mer medvetet.', title_vi = 'Ngày đầu tiên của tháng thứ ba! 🎉', body_vi = 'Bé đã quan sát xung quanh một cách có ý thức hơn.', title_zh = '第三个月的第一天！🎉', body_zh = '宝宝现在会更有意识地观察周围了。' WHERE id = 'a19b5a5e-db95-4571-b0b8-5f50fabb0b6a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Energía matutina ⚡', body_es = '¿Nada más abrir los ojos empieza a gorjear? Quiere hablar contigo. Respóndele con una sonrisa: es la base de su desarrollo del lenguaje.', title_fr = 'L''énergie du matin ⚡', body_fr = 'Il gazouille dès qu''il ouvre les yeux ? Il veut vous parler. Répondez-lui avec le sourire, c''est la base de son langage.', title_hi = 'सुबह की ऊर्जा ⚡', body_hi = 'आँख खुलते ही किलकारी मारता है? वह आपसे बात करना चाहता है। मुस्कुराकर जवाब दीजिए, यह उसके भाषा विकास की नींव है।', title_id = 'Energi pagi ⚡', body_id = 'Begitu membuka mata ia langsung mengoceh? Ia ingin berbicara dengan Anda. Tersenyumlah dan jawab, inilah dasar perkembangan bahasanya.', title_ja = '朝のエネルギー ⚡', body_ja = '目を覚ましたとたん、きゃっきゃっと声を出していますか？ママとお話ししたいのです。笑顔で答えてあげましょう。これが言葉の発達の土台です。', title_ko = '아침 에너지 ⚡', body_ko = '눈을 뜨자마자 옹알이를 하나요? 엄마와 이야기하고 싶은 거예요. 웃으며 대답해 주세요, 이게 언어 발달의 기초예요.', title_nl = 'Ochtendenergie ⚡', body_nl = 'Brabbelt je baby zodra hij de ogen opendoet? Hij wil met je praten. Glimlach en antwoord, dat is de basis van de taalontwikkeling.', title_pl = 'Poranna energia ⚡', body_pl = 'Gaworzy, gdy tylko otworzy oczy? Chce z tobą rozmawiać. Uśmiechnij się i odpowiedz, to podstawa rozwoju jego mowy.', title_pt = 'Energia matinal ⚡', body_pt = 'Mal abre os olhos, começa a palrar? Quer falar consigo. Sorria e responda, é a base do desenvolvimento da linguagem.', title_sv = 'Morgonenergi ⚡', body_sv = 'Jollrar barnet så fort det slår upp ögonen? Det vill prata med dig. Le och svara, det är grunden för språkutvecklingen.', title_vi = 'Năng lượng buổi sáng ⚡', body_vi = 'Vừa mở mắt bé đã ê a? Bé muốn nói chuyện với mẹ đấy. Hãy mỉm cười đáp lại, đây là nền tảng phát triển ngôn ngữ của bé.', title_zh = '清晨能量 ⚡', body_zh = '宝宝一睁眼就咿咿呀呀？宝宝想和你说话。笑着回应吧，这是语言发育的基础。' WHERE id = 'aaed3963-e8dd-47d4-93bd-9b307c2b65fd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las tareas de casa pueden esperar 🛑', body_es = 'No te estreses al ver la habitación desordenada. Estás criando a un ser humano, no tienes por qué ser un ama de casa perfecta.', title_fr = 'Les tâches ménagères peuvent attendre 🛑', body_fr = 'Ne stressez pas devant une pièce en désordre. Vous élevez un être humain, vous n''êtes pas obligée d''être une parfaite femme d''intérieur.', title_hi = 'घर के काम इंतज़ार कर सकते हैं 🛑', body_hi = 'बिखरे कमरे को देखकर तनाव मत लीजिए। आप एक इंसान को पाल रही हैं, आपको परफ़ेक्ट गृहिणी बनने की ज़रूरत नहीं।', title_id = 'Pekerjaan rumah bisa menunggu 🛑', body_id = 'Jangan stres melihat kamar yang berantakan. Anda sedang membesarkan seorang manusia, Anda tidak harus menjadi ibu rumah tangga yang sempurna.', title_ja = '家事は後回しでOK 🛑', body_ja = '散らかった部屋を見てストレスをためないで。あなたは1人の人間を育てているのです。完璧な主婦である必要はありません。', title_ko = '집안일은 기다려도 돼요 🛑', body_ko = '어질러진 방을 보며 스트레스받지 마세요. 엄마는 한 사람을 키우고 있어요, 완벽한 살림꾼이 될 필요는 없어요.', title_nl = 'Het huishouden kan wachten 🛑', body_nl = 'Raak niet gestrest van een rommelige kamer. Je voedt een mens op, je hoeft geen perfecte huisvrouw te zijn.', title_pl = 'Obowiązki domowe mogą poczekać 🛑', body_pl = 'Nie stresuj się, patrząc na bałagan w pokoju. Wychowujesz człowieka, nie musisz być idealną panią domu.', title_pt = 'As tarefas de casa podem esperar 🛑', body_pt = 'Não se stresse a olhar para o quarto desarrumado. Está a criar um ser humano, não tem de ser uma dona de casa perfeita.', title_sv = 'Hushållssysslorna kan vänta 🛑', body_sv = 'Bli inte stressad av det stökiga rummet. Du uppfostrar en människa, du måste inte vara en perfekt hemmafru.', title_vi = 'Việc nhà có thể đợi 🛑', body_vi = 'Đừng căng thẳng khi nhìn căn phòng bừa bộn. Mẹ đang nuôi dạy một con người, không cần phải là người nội trợ hoàn hảo.', title_zh = '家务可以等等 🛑', body_zh = '看着乱糟糟的房间别焦虑。你在养育一个人，不必做一个完美的家庭主妇。' WHERE id = 'bfab4a59-c162-47a2-9035-51b03b7fe911' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de papá 👨‍🍼', body_es = 'Esta noche, sacar los gases y cantar la nana es cosa de papá. Tú ve a descansar.', title_fr = 'Au tour de Papa 👨‍🍼', body_fr = 'Ce soir, le rot et la berceuse, c''est le travail de Papa. Vous, allez vous reposer.', title_hi = 'पापा की बारी 👨‍🍼', body_hi = 'आज शाम डकार दिलाना और लोरी गाना पापा का काम है। और आप जाकर आराम कीजिए।', title_id = 'Giliran Ayah 👨‍🍼', body_id = 'Malam ini menyendawakan dan menyanyikan nina bobo adalah tugas Ayah. Anda pergilah beristirahat.', title_ja = 'パパの番 👨‍🍼', body_ja = '今夜はげっぷと子守唄はパパの担当。あなたは休んできてください。', title_ko = '아빠 차례 👨‍🍼', body_ko = '오늘 저녁 트림시키기와 자장가는 아빠 몫이에요. 엄마는 가서 쉬세요.', title_nl = 'Papa is aan de beurt 👨‍🍼', body_nl = 'Vanavond zijn boertjes laten doen en slaapliedjes zingen papa’s taak. Ga jij maar lekker rusten.', title_pl = 'Kolej taty 👨‍🍼', body_pl = 'Dziś wieczorem odbijanie i kołysanki to zadanie taty. A ty idź odpocząć.', title_pt = 'A vez do pai 👨‍🍼', body_pt = 'Esta noite, fazer arrotar e cantar canções de embalar é tarefa do pai. E a mãe vai descansar.', title_sv = 'Pappas tur 👨‍🍼', body_sv = 'I kväll är rapningen och vaggvisorna pappas jobb. Och du går och vilar.', title_vi = 'Đến lượt bố 👨‍🍼', body_vi = 'Tối nay vỗ ợ hơi và hát ru là việc của bố. Còn mẹ hãy đi nghỉ ngơi.', title_zh = '轮到爸爸了 👨‍🍼', body_zh = '今晚拍嗝和唱摇篮曲是爸爸的任务。你去休息吧。' WHERE id = 'ca9affc4-d638-41a2-8dc7-75447d9ea222' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Somos un equipo! 💪', body_es = '¿Te sientes sola y cansada? Respira hondo. Eres la heroína más fuerte de estos días tan agitados.', title_fr = 'Nous sommes une équipe ! 💪', body_fr = 'Seule et fatiguée ? Respirez profondément. Vous êtes la plus forte héroïne de ces jours agités.', title_hi = 'हम एक टीम हैं! 💪', body_hi = 'अकेली और थकी हुई महसूस कर रही हैं? गहरी साँस लीजिए। आप इन तूफ़ानी दिनों की सबसे मज़बूत हीरो हैं।', title_id = 'Kita satu tim! 💪', body_id = 'Merasa sendirian dan lelah? Tarik napas dalam-dalam. Anda adalah pahlawan terkuat di hari-hari yang penuh badai ini.', title_ja = 'わたしたちはチームです！💪', body_ja = 'ひとりぼっちで疲れていると感じますか？深呼吸して。あなたはこの嵐のような日々のいちばん強いヒーローです。', title_ko = '우리는 한 팀이에요! 💪', body_ko = '외롭고 지쳤나요? 깊게 숨을 쉬어요. 엄마는 이 폭풍 같은 날들의 가장 강한 영웅이에요.', title_nl = 'Wij zijn een team! 💪', body_nl = 'Voel je je alleen en moe? Haal diep adem. Jij bent de sterkste heldin van deze stormachtige dagen.', title_pl = 'Jesteśmy drużyną! 💪', body_pl = 'Czujesz się samotna i zmęczona? Weź głęboki oddech. Jesteś najsilniejszą bohaterką tych burzliwych dni.', title_pt = 'Somos uma equipa! 💪', body_pt = 'Sente-se sozinha e cansada? Respire fundo. É a heroína mais forte destes dias tempestuosos.', title_sv = 'Vi är ett lag! 💪', body_sv = 'Känner du dig ensam och trött? Andas djupt. Du är den starkaste hjälten under de här stormiga dagarna.', title_vi = 'Chúng mình là một đội! 💪', body_vi = 'Mẹ thấy cô đơn và mệt mỏi? Hãy hít thở sâu. Mẹ là người hùng mạnh mẽ nhất của những ngày giông bão này.', title_zh = '我们是一个团队！💪', body_zh = '觉得孤单又疲惫？深呼吸。你是这些风雨日子里最坚强的英雄。' WHERE id = 'a4146327-bb44-44e0-9860-d8e3c1abe5c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Un volteo increíble! 🤸‍♂️', body_es = '¿Intenta darse la vuelta de espaldas a boca abajo? ¡Se esfuerza mucho! Observa sus intentos, pero nunca lo dejes solo en la cama.', title_fr = 'Un retournement magnifique 🤸‍♂️', body_fr = 'Il essaie de passer du dos au ventre ? Il fait de gros efforts ! Observez ses tentatives, mais ne le laissez jamais seul sur le lit.', title_hi = 'शानदार करवट 🤸‍♂️', body_hi = 'पीठ से पेट के बल पलटने की कोशिश कर रहा है? वह बहुत मेहनत कर रहा है! इन कोशिशों को देखिए, पर उसे बिस्तर पर कभी अकेला मत छोड़िए।', title_id = 'Gulingan yang luar biasa 🤸‍♂️', body_id = 'Ia mencoba berguling dari telentang ke tengkurap? Ia berusaha keras! Amati usahanya, tapi jangan pernah meninggalkannya sendirian di tempat tidur.', title_ja = 'すばらしい寝返り 🤸‍♂️', body_ja = '仰向けからうつぶせに寝返ろうとしていますか？とってもがんばっています！その挑戦を見守りつつ、ベッドの上に1人で置いたままには絶対にしないでくださいね。', title_ko = '멋진 뒤집기 🤸‍♂️', body_ko = '등에서 배로 뒤집으려고 하나요? 정말 열심히 하고 있어요! 이 시도를 지켜보되, 침대 위에 절대 혼자 두지 마세요.', title_nl = 'Een geweldige draai 🤸‍♂️', body_nl = 'Probeert je baby van de rug naar de buik te draaien? Hij doet zo zijn best! Kijk naar deze pogingen, maar laat hem nooit alleen op het bed.', title_pl = 'Wspaniały przewrót 🤸‍♂️', body_pl = 'Próbuje przekręcić się z pleców na brzuch? Bardzo się stara! Obserwuj te próby, ale nigdy nie zostawiaj go samego na łóżku.', title_pt = 'Uma reviravolta fantástica 🤸‍♂️', body_pt = 'Está a tentar virar-se de costas para barriga para baixo? Esforça-se muito! Acompanhe estas tentativas, mas nunca o deixe sozinho na cama.', title_sv = 'En fantastisk vändning 🤸‍♂️', body_sv = 'Försöker barnet rulla från rygg till mage? Det kämpar verkligen! Följ försöken, men lämna aldrig barnet ensamt i sängen.', title_vi = 'Cú lật tuyệt vời 🤸‍♂️', body_vi = 'Bé đang cố lật từ ngửa sang sấp? Bé đang rất cố gắng! Hãy theo dõi những nỗ lực ấy, nhưng đừng bao giờ để bé một mình trên giường.', title_zh = '了不起的翻身 🤸‍♂️', body_zh = '宝宝在努力从仰卧翻成趴着？宝宝真的很努力！看着这些尝试吧，但千万不要把宝宝单独留在床上。' WHERE id = 'e3c0355b-40c6-476a-8c2d-f69c78debdb1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué le pongo? ⛅', body_es = 'No le des vueltas a qué ponerle para salir. Mira la herramienta Tiempo y ropa y encuentra el conjunto ideal en segundos.', title_fr = 'Comment l''habiller ? ⛅', body_fr = 'Ne vous cassez pas la tête pour savoir comment l''habiller avant de sortir. Consultez l''outil Météo et tenue et trouvez la tenue idéale en quelques secondes.', title_hi = 'क्या पहनाऊँ? ⛅', body_hi = 'बाहर जाते समय क्या पहनाएँ, यह सोचने में मत उलझिए। मौसम और कपड़े टूल देखकर सेकंडों में सबसे सही मेल ढूँढिए।', title_id = 'Pakai baju apa? ⛅', body_id = 'Jangan pusing memikirkan baju untuk keluar rumah. Cek alat Cuaca dan Pakaian dan temukan kombinasi ideal dalam hitungan detik.', title_ja = '何を着せよう？⛅', body_ja = '外出のときの服装で悩まないで。「天気と服装」ツールで、ぴったりの組み合わせを数秒で見つけましょう。', title_ko = '뭘 입힐까요? ⛅', body_ko = '밖에 나갈 때 뭘 입힐지 고민하지 마세요. 날씨와 옷차림 도구에서 딱 맞는 옷차림을 몇 초 만에 찾아보세요.', title_nl = 'Wat trek ik mijn baby aan? ⛅', body_nl = 'Pieker niet over wat je baby aan moet als jullie naar buiten gaan. Kijk in de tool Weer en kleding en vind binnen enkele seconden de ideale combinatie.', title_pl = 'W co go ubrać? ⛅', body_pl = 'Nie zastanawiaj się, w co ubrać dziecko na wyjście. Zajrzyj do narzędzia Pogoda i ubiór i w kilka sekund znajdź idealny zestaw.', title_pt = 'Que roupa lhe visto? ⛅', body_pt = 'Não perca tempo a pensar no que lhe vestir para sair. Veja a ferramenta Tempo e Roupa e encontre em segundos a combinação ideal.', title_sv = 'Vad ska barnet ha på sig? ⛅', body_sv = 'Fundera inte på vad du ska klä barnet i när ni ska ut. Titta i verktyget Väder och kläder och hitta den perfekta klädseln på några sekunder.', title_vi = 'Mặc gì cho bé đây? ⛅', body_vi = 'Đừng đắn đo nên mặc gì cho bé khi ra ngoài. Xem công cụ Thời tiết và trang phục để tìm bộ đồ lý tưởng chỉ trong vài giây.', title_zh = '给宝宝穿什么？⛅', body_zh = '出门时不用再纠结给宝宝穿什么。看看天气与穿衣工具，几秒钟找到理想搭配。' WHERE id = '532d58e2-50f3-422a-818a-36c88094bb87' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Agotarse es normal 🔋', body_es = 'Cuando se te acabe la paciencia, no te sientas una mala madre. Este cansancio es natural. No dudes en pedir apoyo a tu pareja.', title_fr = 'C''est normal d''être épuisée 🔋', body_fr = 'Quand vous manquez de patience, ne vous sentez pas une mauvaise mère. Cette fatigue est naturelle. N''hésitez pas à demander du soutien à votre conjoint.', title_hi = 'थक जाना सामान्य है 🔋', body_hi = 'जब धैर्य जवाब दे, तो खुद को बुरी माँ मत समझिए। यह थकान स्वाभाविक है। अपने साथी से मदद माँगने में संकोच मत कीजिए।', title_id = 'Kehabisan tenaga itu normal 🔋', body_id = 'Saat kesabaran menipis, jangan merasa menjadi ibu yang buruk. Lelah ini wajar. Jangan ragu meminta dukungan dari pasangan Anda.', title_ja = 'くたくたになるのは普通のこと 🔋', body_ja = '余裕がなくなっても、自分をダメなママだと思わないで。この疲れは自然なことです。パートナーに助けを求めることをためらわないでください。', title_ko = '지치는 건 정상이에요 🔋', body_ko = '인내심이 바닥날 때 나쁜 엄마라고 느끼지 마세요. 이런 피로는 자연스러워요. 배우자에게 도움을 청하는 걸 망설이지 마세요.', title_nl = 'Uitgeput zijn is normaal 🔋', body_nl = 'Voel je geen slechte moeder als je geduld opraakt. Deze vermoeidheid is natuurlijk. Vraag je partner gerust om steun.', title_pl = 'Wyczerpanie jest normalne 🔋', body_pl = 'Gdy kończy ci się cierpliwość, nie czuj się złą mamą. To zmęczenie jest naturalne. Nie wahaj się prosić partnera o wsparcie.', title_pt = 'É normal ficar esgotada 🔋', body_pt = 'Quando perder a paciência, não se sinta uma má mãe. Este cansaço é natural. Não hesite em pedir apoio ao seu companheiro.', title_sv = 'Det är normalt att vara slutkörd 🔋', body_sv = 'Känn dig inte som en dålig mamma när tålamodet tryter. Tröttheten är naturlig. Tveka inte att be din partner om stöd.', title_vi = 'Kiệt sức là bình thường 🔋', body_vi = 'Khi hết kiên nhẫn, đừng nghĩ mình là người mẹ tồi. Mệt mỏi thế này là tự nhiên. Đừng ngại nhờ chồng hỗ trợ.', title_zh = '累垮了也很正常 🔋', body_zh = '失去耐心时，别觉得自己是个坏妈妈。这种疲惫很自然。不要羞于向另一半寻求支持。' WHERE id = 'f37039a0-f7af-487a-827e-622e2d9e4d05' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Eres suficiente! 🌸', body_es = '¿Hoy todo sale al revés? No pasa nada. Tu bebé no necesita a nadie más que a ti. Para él eres más que suficiente.', title_fr = 'Vous suffisez ! 🌸', body_fr = 'Tout va de travers aujourd''hui ? Ce n''est pas grave. Votre bébé n''a besoin de personne d''autre que vous. Pour lui, vous suffisez entièrement.', title_hi = 'आप काफ़ी हैं! 🌸', body_hi = 'आज सब उल्टा हो रहा है? कोई बात नहीं। आपके बच्चे को आपके सिवा किसी की ज़रूरत नहीं। आप उसके लिए पूरी तरह काफ़ी हैं।', title_id = 'Anda sudah cukup! 🌸', body_id = 'Hari ini semuanya terasa kacau? Tidak apa-apa. Bayi Anda tidak membutuhkan siapa pun selain Anda. Bagi dia, Anda sudah lebih dari cukup.', title_ja = 'あなたはそのままで十分！🌸', body_ja = '今日は何もかもうまくいかない？大丈夫。赤ちゃんにはあなた以外の誰も必要ありません。あなたは赤ちゃんにとって、そのままで十分なのです。', title_ko = '엄마는 충분해요! 🌸', body_ko = '오늘은 모든 게 꼬이나요? 괜찮아요. 아기에게는 엄마 말고 누구도 필요 없어요. 엄마는 아기에게 충분하고도 남아요.', title_nl = 'Jij bent genoeg! 🌸', body_nl = 'Gaat vandaag alles mis? Niet erg. Je baby heeft niemand anders nodig dan jou. Jij bent helemaal genoeg voor je baby.', title_pl = 'Wystarczysz! 🌸', body_pl = 'Dziś wszystko idzie na opak? Nic nie szkodzi. Twoje dziecko nie potrzebuje nikogo poza tobą. Jesteś dla niego w zupełności wystarczająca.', title_pt = 'A Mamã é suficiente! 🌸', body_pt = 'Hoje está tudo a correr mal? Não faz mal. O bebé não precisa de mais ninguém além de si. Para ele, é absolutamente suficiente.', title_sv = 'Du räcker till! 🌸', body_sv = 'Går allt på tok i dag? Det gör ingenting. Ditt barn behöver ingen annan än dig. Du räcker helt till för barnet.', title_vi = 'Mẹ là đủ rồi! 🌸', body_vi = 'Hôm nay mọi thứ đều trục trặc? Không sao cả. Bé không cần ai ngoài mẹ. Với bé, mẹ là hoàn toàn đủ đầy.', title_zh = '你已经足够好了！🌸', body_zh = '今天诸事不顺？没关系。宝宝除了你谁都不需要。对宝宝来说，你已经完全足够好了。' WHERE id = 'f94cdd25-2b6b-47df-81dc-6e3cab221652' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Preparación para un sueño profundo 🛀', body_es = 'Un baño tibio, un masaje suave y la habitación a oscuras... Mantener la rutina de sueño es el secreto de las noches sin interrupciones.', title_fr = 'Préparation à un sommeil profond 🛀', body_fr = 'Un bain tiède, un massage doux et une chambre plongée dans le noir... Préserver la routine du coucher est le secret des nuits sans interruption.', title_hi = 'गहरी नींद की तैयारी 🛀', body_hi = 'गुनगुना स्नान, हल्की मालिश और कमरे में अँधेरा... नींद का रूटीन बनाए रखना बिना रुकावट वाली रातों का राज़ है।', title_id = 'Persiapan tidur nyenyak 🛀', body_id = 'Mandi air hangat, pijatan lembut, dan kamar yang digelapkan... Menjaga rutinitas tidur adalah rahasia malam tanpa terputus.', title_ja = '深い眠りの準備 🛀', body_ja = 'ぬるめのお風呂、やさしいマッサージ、暗くした部屋...睡眠のルーティンを守ることが、朝までぐっすりのひみつです。', title_ko = '깊은 잠 준비 🛀', body_ko = '따뜻한 목욕, 부드러운 마사지, 어두운 방... 수면 루틴을 지키는 것이 깨지 않는 밤의 비결이에요.', title_nl = 'Klaar voor een diepe slaap 🛀', body_nl = 'Een warm badje, een zachte massage en een donkere kamer... Een vast slaapritueel is het geheim van ongestoorde nachten.', title_pl = 'Przygotowanie do głębokiego snu 🛀', body_pl = 'Ciepła kąpiel, delikatny masaż i zaciemniony pokój... Trzymanie się rutyny snu to sekret nieprzerwanych nocy.', title_pt = 'Preparação para um sono profundo 🛀', body_pt = 'Um banho morno, uma massagem suave e o quarto às escuras... Manter a rotina do sono é o segredo de noites sem interrupções.', title_sv = 'Förberedelser för djup sömn 🛀', body_sv = 'Ett ljummet bad, en mjuk massage och ett mörklagt rum... Att hålla fast vid sömnrutinen är hemligheten bakom ostörda nätter.', title_vi = 'Chuẩn bị cho giấc ngủ sâu 🛀', body_vi = 'Tắm nước ấm, xoa bóp nhẹ nhàng và làm tối phòng... Giữ nếp ngủ là bí quyết cho những đêm ngủ trọn giấc.', title_zh = '为深度睡眠做准备 🛀', body_zh = '温水澡、轻柔按摩、调暗房间……坚持睡前程序是整夜安睡的秘诀。' WHERE id = '07f48fa2-56fd-416e-adda-88c824f2bd6f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te sientas culpable 💖', body_es = '¿Crees que dedicas poco tiempo a tu bebé? 10 minutos de calidad y con una sonrisa valen más que 1 hora con estrés.', title_fr = 'Ne culpabilisez pas 💖', body_fr = 'Vous pensez ne pas passer assez de temps avec votre enfant ? 10 minutes de qualité et de sourires valent plus qu''une heure de stress.', title_hi = 'अपराध-बोध मत रखिए 💖', body_hi = 'लगता है कि बच्चे को कम समय दे रही हैं? हँसते-मुस्कुराते बिताए अच्छे 10 मिनट तनाव भरे 1 घंटे से ज़्यादा कीमती हैं।', title_id = 'Jangan merasa bersalah 💖', body_id = 'Merasa kurang meluangkan waktu untuk anak? 10 menit berkualitas dengan wajah ceria lebih berharga daripada 1 jam penuh stres.', title_ja = '罪悪感を抱かないで 💖', body_ja = '赤ちゃんとの時間が少ないと思っていますか？笑顔で過ごす充実した10分は、ストレスいっぱいの1時間よりも価値があります。', title_ko = '죄책감은 내려놓으세요 💖', body_ko = '아기와 보내는 시간이 적다고 생각하나요? 웃음 가득한 알찬 10분이 스트레스받는 1시간보다 더 소중해요.', title_nl = 'Heb geen schuldgevoel 💖', body_nl = 'Denk je dat je te weinig tijd aan je kind besteedt? 10 fijne, vrolijke minuten zijn meer waard dan een stressvol uur.', title_pl = 'Nie miej wyrzutów sumienia 💖', body_pl = 'Myślisz, że poświęcasz dziecku za mało czasu? 10 wartościowych, radosnych minut jest cenniejsze niż stresująca godzina.', title_pt = 'Não sinta remorsos 💖', body_pt = 'Acha que dedica pouco tempo ao bebé? 10 minutos de qualidade e com um sorriso valem mais do que 1 hora de stress.', title_sv = 'Ha inte dåligt samvete 💖', body_sv = 'Tycker du att du ger barnet för lite tid? 10 minuter av kvalitet och glädje är värda mer än 1 stressig timme.', title_vi = 'Đừng cắn rứt lương tâm 💖', body_vi = 'Mẹ nghĩ mình dành ít thời gian cho bé? 10 phút chất lượng và vui vẻ quý hơn 1 tiếng căng thẳng.', title_zh = '不要内疚 💖', body_zh = '觉得陪宝宝的时间太少？10分钟高质量、笑容满满的陪伴，比充满压力的1小时更有价值。' WHERE id = '828415f3-317f-4e76-8caf-753026dcf9f1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lo cojo yo solo! 🧸', body_es = '¿Estira la mano con precisión hacia los juguetes colgantes? Su coordinación ojo-mano se fortalece. Anímale con objetos de distintos colores.', title_fr = 'Je vais l''attraper tout seul ! 🧸', body_fr = 'Il tend la main avec précision vers les jouets suspendus ? Sa coordination œil-main se renforce. Encouragez-le avec des objets de différentes couleurs.', title_hi = 'मैं खुद पकड़ूँगा! 🧸', body_hi = 'लटके खिलौनों की ओर बिल्कुल सही हाथ बढ़ाता है? आँख और हाथ का तालमेल मज़बूत हो रहा है। अलग-अलग रंगों की चीज़ों से उसका हौसला बढ़ाइए।', title_id = 'Aku pegang sendiri! 🧸', body_id = 'Ia meraih mainan gantung dengan sangat tepat? Koordinasi mata dan tangannya makin kuat. Semangati ia dengan benda-benda berwarna berbeda.', title_ja = '自分でつかむよ！🧸', body_ja = 'つり下げたおもちゃに、正確に手を伸ばしていますか？目と手の協調が強くなっています。いろいろな色のもので、やる気を引き出してあげましょう。', title_ko = '제가 잡을래요! 🧸', body_ko = '매달린 장난감에 정확하게 손을 뻗나요? 눈과 손의 협응력이 강해지고 있어요. 다양한 색의 물건으로 아기를 북돋아 주세요.', title_nl = 'Ik pak het zelf! 🧸', body_nl = 'Reikt je baby heel precies naar hangend speelgoed? De oog-handcoördinatie wordt sterker. Moedig hem aan met dingen in verschillende kleuren.', title_pl = 'Złapię to! 🧸', body_pl = 'Sięga po wiszące zabawki z pełną precyzją? Wzmacnia się koordynacja oko-ręka. Zachęcaj go przedmiotami w różnych kolorach.', title_pt = 'Eu é que agarro! 🧸', body_pt = 'Estica a mão com toda a precisão para os brinquedos pendurados? A coordenação olho-mão está a ficar mais forte. Estimule-o com objetos de cores diferentes.', title_sv = 'Jag håller själv! 🧸', body_sv = 'Sträcker sig barnet med full precision efter hängande leksaker? Koordinationen mellan öga och hand blir starkare. Uppmuntra med saker i olika färger.', title_vi = 'Con tự cầm! 🧸', body_vi = 'Bé với chính xác tới đồ chơi treo? Phối hợp tay và mắt đang mạnh hơn. Hãy khuyến khích bé bằng những đồ vật nhiều màu sắc.', title_zh = '我自己来抓！🧸', body_zh = '宝宝能准确地伸手去够挂着的玩具了？手眼协调能力在增强。用不同颜色的物品鼓励宝宝吧。' WHERE id = 'f4730701-e02f-4cf0-9730-df8b7e034297' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Desahogo emocional 📝', body_es = '¿Hoy se te viene todo encima? Escribe en el Diario de ánimo todas las dificultades y el cansancio. No te guardes lo que sientes.', title_fr = 'Libérer ses émotions 📝', body_fr = 'Tout vous tombe dessus aujourd''hui ? Écrivez toutes les difficultés et la fatigue dans le Journal d''humeur. N''étouffez pas vos émotions.', title_hi = 'भावनाओं को बाहर निकालिए 📝', body_hi = 'आज सब कुछ आप पर टूट पड़ा है? मूड डायरी में सारी मुश्किलें और थकान लिखिए। अपनी भावनाओं को दबाइए मत।', title_id = 'Melepas emosi 📝', body_id = 'Hari ini semuanya terasa menumpuk? Tulis semua kesulitan dan lelah Anda di Buku Harian Suasana Hati. Jangan pendam perasaan Anda.', title_ja = '気持ちを吐き出そう 📝', body_ja = '今日は何もかも押し寄せてくる感じ？「気分日記」に大変だったことや疲れをすべて書きましょう。気持ちを押し込めないで。', title_ko = '감정 털어내기 📝', body_ko = '오늘은 모든 게 한꺼번에 몰려오나요? 기분 일기에 모든 어려움과 피로를 적어 보세요. 감정을 억누르지 마세요.', title_nl = 'Emoties loslaten 📝', body_nl = 'Komt vandaag alles op je af? Schrijf alle moeilijkheden en vermoeidheid in je Stemmingsdagboek. Kropt je gevoelens niet op.', title_pl = 'Emocjonalne odreagowanie 📝', body_pl = 'Dziś wszystko się na ciebie wali? Zapisz w Dzienniku nastroju wszystkie trudności i zmęczenie. Nie tłum swoich uczuć.', title_pt = 'Libertar as emoções 📝', body_pt = 'Hoje está tudo a cair-lhe em cima? Escreva no Diário de Humor todas as dificuldades e o cansaço. Não reprima o que sente.', title_sv = 'Känslomässig urladdning 📝', body_sv = 'Känns allt övermäktigt i dag? Skriv ner alla svårigheter och all trötthet i Humördagboken. Kväv inte dina känslor.', title_vi = 'Giải tỏa cảm xúc 📝', body_vi = 'Hôm nay mọi thứ đè nặng lên mẹ? Hãy viết mọi khó khăn và mệt mỏi vào Nhật ký tâm trạng. Đừng kìm nén cảm xúc.', title_zh = '释放情绪 📝', body_zh = '今天所有事都压过来了？把所有的困难和疲惫写进心情日记。不要压抑自己的感受。' WHERE id = '81a8fffa-561b-48b8-9be0-ff9b930a7bac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La victoria del día 110! 🥂', body_es = 'Ya llevas 110 días justos gestionando una nueva vida. Daos las gracias tu pareja y tú y disfrutad esta noche del silencio.', title_fr = 'La victoire du 110e jour ! 🥂', body_fr = 'Cela fait pile 110 jours que vous gérez une nouvelle vie. Remerciez-vous mutuellement avec votre conjoint et savourez le silence ce soir.', title_hi = '110वें दिन की जीत! 🥂', body_hi = 'आप पूरे 110 दिन से एक नई ज़िंदगी संभाल रही हैं। अपने साथी के साथ एक-दूसरे का शुक्रिया अदा कीजिए और आज शाम खामोशी का मज़ा लीजिए।', title_id = 'Kemenangan hari ke-110! 🥂', body_id = 'Tepat 110 hari Anda mengelola kehidupan baru. Saling berterima kasihlah dengan pasangan dan nikmati keheningan malam ini.', title_ja = '110日目の勝利！🥂', body_ja = 'ちょうど110日間、新しい命を支えてきました。パートナーとお互いにありがとうを伝えて、今夜は静けさを味わいましょう。', title_ko = '110일째의 승리! 🥂', body_ko = '딱 110일 동안 새로운 삶을 꾸려 왔어요. 배우자와 서로 고마움을 전하고 오늘 저녁은 고요함을 즐기세요.', title_nl = 'De overwinning van dag 110! 🥂', body_nl = 'Al precies 110 dagen zorg je voor een nieuw leven. Bedank elkaar met je partner en geniet vanavond van de stilte.', title_pl = 'Zwycięstwo 110. dnia! 🥂', body_pl = 'Od równych 110 dni zarządzasz nowym życiem. Podziękujcie sobie z partnerem nawzajem i cieszcie się dziś wieczorem ciszą.', title_pt = 'A vitória do 110.º dia! 🥂', body_pt = 'Há 110 dias certinhos que gerem uma nova vida. Agradeçam um ao outro, a mãe e o companheiro, e aproveitem esta noite o silêncio.', title_sv = 'Segern på dag 110! 🥂', body_sv = 'I precis 110 dagar har du styrt ett nytt liv. Tacka varandra du och din partner och njut av tystnaden i kväll.', title_vi = 'Chiến thắng ngày thứ 110! 🥂', body_vi = 'Tròn 110 ngày mẹ quán xuyến một cuộc sống mới. Tối nay hãy cùng chồng cảm ơn nhau và tận hưởng sự yên tĩnh.', title_zh = '第110天的胜利！🥂', body_zh = '你们已经整整110天在照顾一个新生命了。和另一半互相道声谢谢，今晚好好享受安静吧。' WHERE id = '87db18be-f6b3-443d-9d07-0e305836d90b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia de los sonidos 🌊', body_es = 'Si por la tarde empiezan las crisis de llanto, no te agobies. Pon el Ruido blanco para tu bebé y cambia al instante el ambiente de la habitación.', title_fr = 'La magie des sons 🌊', body_fr = 'Si les crises de pleurs commencent le soir, pas de panique. Mettez les Bruits blancs pour votre bébé et changez instantanément l''ambiance de la pièce.', title_hi = 'आवाज़ों का जादू 🌊', body_hi = 'अगर शाम को रोने का दौर शुरू हो, तो घबराइए मत। बच्चे के लिए व्हाइट नॉइज़ चलाकर कमरे का माहौल तुरंत बदल दीजिए।', title_id = 'Keajaiban suara 🌊', body_id = 'Jika tangisan rewel mulai di sore hari, jangan cemas. Ubah suasana kamar seketika dengan menyalakan Suara Putih untuk bayi Anda.', title_ja = '音の魔法 🌊', body_ja = '夕方に泣きぐずりが始まっても、あわてないで。赤ちゃんのためにホワイトノイズをかけて、部屋の雰囲気をすぐに変えましょう。', title_ko = '소리의 마법 🌊', body_ko = '저녁마다 울음이 시작돼도 당황하지 마세요. 백색소음을 틀어 방의 분위기를 바로 바꿔 주세요.', title_nl = 'De magie van geluid 🌊', body_nl = 'Beginnen ’s avonds de huilbuien? Geen paniek. Zet Witte ruis aan voor je baby en verander meteen de sfeer in de kamer.', title_pl = 'Magia dźwięków 🌊', body_pl = 'Jeśli wieczorem zaczynają się napady płaczu, nie panikuj. Włącz dziecku Biały szum i od razu zmień atmosferę w pokoju.', title_pt = 'A magia dos sons 🌊', body_pt = 'Se as crises de choro começarem ao fim do dia, não se aflija. Ligue o Ruído Branco para o bebé e mude de imediato o ambiente do quarto.', title_sv = 'Ljudens magi 🌊', body_sv = 'Om gråtkriserna börjar på kvällarna, få inte panik. Sätt på Vitt brus för barnet och ändra stämningen i rummet direkt.', title_vi = 'Phép màu của âm thanh 🌊', body_vi = 'Nếu những cơn khóc bắt đầu vào buổi tối, đừng cuống. Hãy bật Tiếng ồn trắng cho bé để thay đổi bầu không khí trong phòng ngay lập tức.', title_zh = '声音的魔法 🌊', body_zh = '如果傍晚开始大哭，不要慌。给宝宝打开白噪音，立刻改变房间的氛围。' WHERE id = '18211145-ceeb-48f3-8053-1e2ff686e384' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pregunta a la inteligencia artificial 🤖', body_es = '¿Tienes mil preguntas en la cabeza? No pierdas tiempo buscando: pregunta ya a Anacan AI y recibe una respuesta precisa y científica.', title_fr = 'Demandez à l''intelligence artificielle 🤖', body_fr = 'Des milliers de questions en tête ? Ne perdez pas de temps à chercher, demandez tout de suite à Anacan AI et obtenez une réponse précise et scientifique.', title_hi = 'AI से पूछिए 🤖', body_hi = 'दिमाग में हज़ारों सवाल हैं? खोजने में समय बर्बाद मत कीजिए, तुरंत Anacan AI से पूछकर सटीक, वैज्ञानिक जवाब पाइए।', title_id = 'Tanyakan kepada kecerdasan buatan 🤖', body_id = 'Ada ribuan pertanyaan di kepala? Jangan buang waktu mencari, langsung tanyakan kepada Anacan AI dan dapatkan jawaban yang tepat dan ilmiah.', title_ja = 'AIに聞いてみよう 🤖', body_ja = '頭の中に質問が何千もありますか？検索で時間を無駄にせず、すぐにAnacan AIに聞いて、正確で科学的な答えを受け取りましょう。', title_ko = 'AI에게 물어보세요 🤖', body_ko = '머릿속에 질문이 가득한가요? 검색하느라 시간 낭비하지 말고 바로 Anacan AI에게 물어 정확하고 과학적인 답을 받으세요.', title_nl = 'Vraag het de AI 🤖', body_nl = 'Zit je hoofd vol met duizenden vragen? Verlies geen tijd met zoeken, vraag het meteen aan Anacan AI en krijg een precies, wetenschappelijk antwoord.', title_pl = 'Zapytaj sztuczną inteligencję 🤖', body_pl = 'Masz w głowie tysiące pytań? Nie trać czasu na szukanie, od razu zapytaj Anacan AI i otrzymaj dokładną, naukową odpowiedź.', title_pt = 'Pergunte à inteligência artificial 🤖', body_pt = 'Tem milhares de perguntas na cabeça? Não perca tempo a pesquisar: pergunte já ao Anacan AI e receba uma resposta precisa e científica.', title_sv = 'Fråga AI:n 🤖', body_sv = 'Har du tusentals frågor i huvudet? Slösa inte tid på att söka, fråga Anacan AI direkt och få ett exakt, vetenskapligt svar.', title_vi = 'Hỏi trí tuệ nhân tạo 🤖', body_vi = 'Đầu mẹ có hàng nghìn câu hỏi? Đừng mất thời gian tìm kiếm, hãy hỏi ngay Anacan AI để nhận câu trả lời chính xác, khoa học.', title_zh = '问问人工智能 🤖', body_zh = '脑子里有一千个问题？别把时间浪费在搜索上，马上问Anacan AI，获得准确、科学的回答。' WHERE id = '49d00520-8368-4f13-9074-fbe894888b76' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mira hacia abajo! 👣', body_es = '¡Ya está descubriendo los dedos de sus pies! Observa con atención este momento cómico y asombroso y disfruta de su desarrollo.', title_fr = 'Regardez en bas ! 👣', body_fr = 'Il découvre déjà ses orteils ! Observez attentivement ce moment comique et étonnant, et savourez son développement.', title_hi = 'नीचे देखिए! 👣', body_hi = 'वह अब अपने पैर की उँगलियाँ खोज रहा है! इस मज़ेदार और हैरान करने वाले पल को ध्यान से देखिए और विकास का मज़ा लीजिए।', title_id = 'Lihat ke bawah! 👣', body_id = 'Ia kini menemukan jari-jari kakinya sendiri! Amati momen lucu dan menakjubkan ini dengan saksama, dan nikmati perkembangannya.', title_ja = '足元を見て！👣', body_ja = '赤ちゃんはもう自分の足の指を発見しています！このおもしろくて驚きの瞬間をじっくり見守り、成長を味わいましょう。', title_ko = '아래를 보세요! 👣', body_ko = '아기가 벌써 자기 발가락을 발견하고 있어요! 이 웃기고 놀라운 순간을 지켜보며 성장을 즐기세요.', title_nl = 'Kijk naar beneden! 👣', body_nl = 'Je baby ontdekt al de eigen teentjes! Kijk goed naar dit grappige en verbazingwekkende moment en geniet van de ontwikkeling.', title_pl = 'Spójrz w dół! 👣', body_pl = 'Już odkrywa paluszki u stóp! Uważnie obserwuj tę zabawną i zdumiewającą chwilę i ciesz się jego rozwojem.', title_pt = 'Olhe para baixo! 👣', body_pt = 'Agora está a descobrir os dedos dos pés! Observe com atenção este momento cómico e surpreendente e aproveite o desenvolvimento.', title_sv = 'Titta neråt! 👣', body_sv = 'Nu upptäcker barnet sina tår! Följ noga den här roliga och fantastiska stunden och njut av utvecklingen.', title_vi = 'Nhìn xuống dưới nào! 👣', body_vi = 'Bé đã khám phá ngón chân của mình! Hãy chăm chú ngắm khoảnh khắc buồn cười và kỳ diệu này, tận hưởng sự phát triển của bé.', title_zh = '往下看！👣', body_zh = '宝宝已经在探索自己的脚趾了！仔细欣赏这个滑稽又神奇的时刻，享受宝宝的成长吧。' WHERE id = 'e6ea83f7-b8a5-46f7-ba44-81c58175071e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El héroe de la noche 🦸‍♂️', body_es = '¿Estás agotada de los despertares nocturnos? No dudes en despertar a papá. Ser un equipo significa repartir la carga a partes iguales.', title_fr = 'Le héros de la nuit 🦸‍♂️', body_fr = 'Les réveils nocturnes vous épuisent ? N''hésitez pas à réveiller Papa. Être une équipe, c''est partager la charge équitablement.', title_hi = 'रात के हीरो 🦸‍♂️', body_hi = 'रात में बार-बार जागने से थक गईं? पापा को जगाने में संकोच मत कीजिए। टीम होने का मतलब है बोझ बराबर बाँटना।', title_id = 'Pahlawan malam 🦸‍♂️', body_id = 'Lelah dengan bangun malam? Jangan ragu membangunkan Ayah. Menjadi satu tim berarti berbagi beban secara adil.', title_ja = '夜のヒーロー 🦸‍♂️', body_ja = '夜中の目覚めに疲れていますか？パパを起こすことをためらわないで。チームとは、負担を平等に分け合うことです。', title_ko = '밤의 영웅 🦸‍♂️', body_ko = '밤중에 깨는 데 지쳤나요? 아빠를 깨우는 걸 망설이지 마세요. 팀이 된다는 건 짐을 똑같이 나누는 거예요.', title_nl = 'De held van de nacht 🦸‍♂️', body_nl = 'Moe van het nachtelijk wakker worden? Maak papa gerust wakker. Een team zijn betekent de last eerlijk verdelen.', title_pl = 'Bohater nocy 🦸‍♂️', body_pl = 'Męczą cię nocne pobudki? Nie wahaj się budzić taty. Bycie drużyną oznacza równy podział obowiązków.', title_pt = 'O herói da noite 🦸‍♂️', body_pt = 'Está cansada dos despertares noturnos? Não hesite em acordar o pai. Ser uma equipa significa dividir o peso por igual.', title_sv = 'Nattens hjälte 🦸‍♂️', body_sv = 'Är du trött på de nattliga uppvaknandena? Tveka inte att väcka pappa. Att vara ett lag betyder att dela bördan lika.', title_vi = 'Người hùng ban đêm 🦸‍♂️', body_vi = 'Mẹ mệt vì thức đêm? Đừng ngại đánh thức bố. Là một đội nghĩa là chia đều gánh nặng.', title_zh = '夜晚的英雄 🦸‍♂️', body_zh = '被夜醒折腾得筋疲力尽？别犹豫，叫醒爸爸。一个团队就意味着平分重担。' WHERE id = 'de11a3ea-d3e5-4374-adb5-b6c04fb6fc41' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No tienes que ser una supermamá! 🦸‍♀', body_es = '️No dudes en pedir ayuda. Para motivarte, lee los artículos de nuestra sección Blog.', title_fr = 'Vous n''êtes pas obligée d''être une super maman ! 🦸‍♀', body_fr = '️ N''hésitez pas à demander de l''aide. Pour vous motiver, lisez les articles de notre rubrique Blogs.', title_hi = 'आपको सुपर मॉम बनने की ज़रूरत नहीं है! 🦸‍♀', body_hi = '️ मदद माँगने में संकोच मत कीजिए। प्रेरणा के लिए हमारे ब्लॉग सेक्शन के लेख पढ़िए।', title_id = 'Anda tidak harus menjadi ibu super! 🦸‍♀', body_id = '️ Jangan ragu meminta bantuan. Untuk motivasi, baca artikel di bagian Blog kami.', title_ja = 'スーパーママでいる必要はありません！🦸‍♀', body_ja = '️ 助けを求めることをためらわないで。ブログの記事を読んで、元気をチャージしましょう。', title_ko = '슈퍼맘이 될 필요는 없어요! 🦸‍♀', body_ko = '️ 도움을 요청하는 걸 망설이지 마세요. 힘이 필요할 땐 블로그 섹션의 글을 읽어 보세요.', title_nl = 'Je hoeft geen supermama te zijn! 🦸‍♀', body_nl = '️ Vraag gerust om hulp. Lees voor motivatie de artikelen in ons onderdeel Blogs.', title_pl = 'Nie musisz być supermamą! 🦸‍♀', body_pl = '️ Nie wahaj się prosić o pomoc. Dla motywacji przeczytaj artykuły w sekcji Blogi.', title_pt = 'Não tem de ser uma super-mãe! 🦸‍♀', body_pt = '️ Não hesite em pedir ajuda. Para se motivar, leia os artigos da nossa secção Blogues.', title_sv = 'Du måste inte vara en supermamma! 🦸‍♀', body_sv = '️ Tveka inte att be om hjälp. Läs artiklarna i vår Blogg för motivation.', title_vi = 'Mẹ không cần phải là siêu nhân! 🦸‍♀', body_vi = '️Đừng ngại nhờ giúp đỡ. Hãy đọc các bài viết trong mục Blog để có thêm động lực.', title_zh = '你不必当超级妈妈！🦸‍♀', body_zh = '️ 不要羞于寻求帮助。想获得动力，就读读博客板块里的文章吧。' WHERE id = 'c61401b5-5ca0-4aea-9f3d-ce4b09083a8c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '10 minutos para mamá ☕', body_es = 'En cuanto se duerma el bebé, no corras a hacer tareas. Siéntate en el sofá, tómate el café y descansa 10 minutos mirando a la pared.', title_fr = '10 minutes pour maman ☕', body_fr = 'Dès que bébé s''endort, ne vous précipitez pas sur les tâches ménagères. Asseyez-vous sur le canapé, buvez votre café et reposez-vous 10 minutes en regardant simplement le mur.', title_hi = 'माँ के लिए 10 मिनट ☕', body_hi = 'बच्चे के सोते ही घर के कामों में मत भागिए। सोफ़े पर बैठिए, अपनी कॉफ़ी पीजिए और 10 मिनट बस दीवार की ओर देखते हुए आराम कीजिए।', title_id = '10 menit untuk ibu ☕', body_id = 'Begitu anak tidur, jangan langsung lari mengerjakan pekerjaan rumah. Duduklah di sofa, minum kopi Anda, dan beristirahatlah 10 menit sambil hanya menatap dinding.', title_ja = 'ママのための10分 ☕', body_ja = '赤ちゃんが寝たとたんに家事に走らないで。ソファに座ってコーヒーを飲み、10分間ただ壁を見つめて休みましょう。', title_ko = '엄마를 위한 10분 ☕', body_ko = '아기가 잠들자마자 집안일로 달려가지 마세요. 소파에 앉아 커피를 마시며 10분만 멍하니 쉬세요.', title_nl = '10 minuten voor mama ☕', body_nl = 'Ren niet naar het huishouden zodra je baby slaapt. Ga op de bank zitten, drink je koffie en staar 10 minuten gewoon naar de muur om uit te rusten.', title_pl = '10 minut dla mamy ☕', body_pl = 'Gdy dziecko zaśnie, nie biegnij do obowiązków domowych. Usiądź na kanapie, wypij kawę i przez 10 minut po prostu patrz w ścianę i odpoczywaj.', title_pt = '10 minutos para a mãe ☕', body_pt = 'Mal o bebé adormeça, não corra para as tarefas de casa. Sente-se no sofá, beba o seu café e descanse 10 minutos só a olhar para a parede.', title_sv = '10 minuter för mamma ☕', body_sv = 'Rusa inte till hushållssysslorna så fort barnet somnar. Sätt dig i soffan, drick ditt kaffe och vila i 10 minuter genom att bara stirra in i väggen.', title_vi = '10 phút cho mẹ ☕', body_vi = 'Bé vừa ngủ, đừng vội lao vào việc nhà. Hãy ngồi lên sofa, uống cà phê và nghỉ ngơi 10 phút, chỉ nhìn lên tường thôi.', title_zh = '妈妈的10分钟 ☕', body_zh = '宝宝一睡着，别马上冲去干家务。坐在沙发上，喝杯咖啡，就盯着墙发10分钟呆，好好休息一下。' WHERE id = '93512cbe-adab-49c7-8e82-4466bf0e00ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pasa el turno 🛋️', body_es = 'Si cuando el bebé duerme tú también quieres caer rendida, encarga las demás tareas de casa a tu pareja. Tu salud es lo más importante.', title_fr = 'Passez le relais 🛋️', body_fr = 'Si vous avez envie de vous écrouler pour dormir quand bébé dort, confiez les autres tâches de la maison à votre partenaire. Votre santé passe avant tout.', title_hi = 'बारी सौंप दीजिए 🛋️', body_hi = 'अगर बच्चे के सोने पर आप भी गिरकर सो जाना चाहती हैं, तो घर के बाकी काम अपने साथी को सौंप दीजिए। आपकी सेहत सबसे ज़रूरी है।', title_id = 'Serahkan giliran 🛋️', body_id = 'Jika Anda juga ingin langsung tidur saat anak tidur, serahkan pekerjaan rumah lainnya kepada pasangan. Kesehatan Anda lebih penting dari segalanya.', title_ja = '当番をバトンタッチ 🛋️', body_ja = '赤ちゃんが寝たら自分も倒れこんで眠りたいなら、ほかの家事はパートナーにまかせましょう。あなたの健康が何よりも大切です。', title_ko = '당번을 넘기세요 🛋️', body_ko = '아기가 잘 때 엄마도 쓰러져 자고 싶다면 다른 집안일은 배우자에게 맡기세요. 엄마의 건강이 무엇보다 중요해요.', title_nl = 'Draag de zorg over 🛋️', body_nl = 'Wil je zelf ook neervallen en slapen als je baby slaapt? Laat het andere werk in huis dan aan je partner over. Jouw gezondheid is het allerbelangrijkst.', title_pl = 'Przekaż zmianę 🛋️', body_pl = 'Jeśli gdy dziecko śpi, ty też chcesz paść i zasnąć, zleć inne domowe obowiązki partnerowi. Twoje zdrowie jest najważniejsze.', title_pt = 'Passe o turno 🛋️', body_pt = 'Se, quando o bebé dorme, também lhe apetece cair na cama, deixe as outras tarefas da casa ao seu companheiro. A sua saúde é mais importante do que tudo.', title_sv = 'Lämna över passet 🛋️', body_sv = 'Om du också vill stupa i säng när barnet sover, lämna över de andra sysslorna hemma till din partner. Din hälsa är viktigast av allt.', title_vi = 'Giao ca nào 🛋️', body_vi = 'Nếu bé ngủ mà mẹ cũng chỉ muốn ngã ra ngủ, hãy giao những việc khác trong nhà cho chồng. Sức khỏe của mẹ quan trọng hơn tất cả.', title_zh = '交接班吧 🛋️', body_zh = '宝宝睡着时你也想倒头就睡？那就把家里其他事交给另一半。你的健康比什么都重要。' WHERE id = '8bc219eb-803c-491e-9625-0efec17a7dad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lista para la memoria 🛒', body_es = '¿La falta de sueño te ha debilitado la memoria? No intentes recordar nada de lo que hace falta en casa: apúntalo en la Lista de la compra.', title_fr = 'Liste mémo 🛒', body_fr = 'Le manque de sommeil affaiblit votre mémoire ? Ne gardez rien en tête de ce qu''il faut pour la maison, notez-le dans la Liste de courses.', title_hi = 'याद रखने की लिस्ट 🛒', body_hi = 'नींद की कमी से याददाश्त कमज़ोर हो गई? घर की कोई ज़रूरत दिमाग में मत रखिए, शॉपिंग लिस्ट में लिखिए।', title_id = 'Daftar pengingat 🛒', body_id = 'Kurang tidur membuat Anda pelupa? Jangan simpan kebutuhan rumah di kepala, tulis saja di Daftar Belanja.', title_ja = '覚え書きリスト 🛒', body_ja = '寝不足でもの忘れが増えていませんか？家に必要なものを頭で覚えておかず、「買い物リスト」に書きましょう。', title_ko = '기억 목록 🛒', body_ko = '잠이 부족해서 기억력이 흐려졌나요? 집에 필요한 건 머릿속에 담아 두지 말고 쇼핑 목록에 적으세요.', title_nl = 'Geheugenlijstje 🛒', body_nl = 'Heeft slaapgebrek je geheugen verzwakt? Onthoud niets van wat er in huis nodig is, schrijf het op het Boodschappenlijstje.', title_pl = 'Lista do zapamiętania 🛒', body_pl = 'Niewyspanie osłabiło twoją pamięć? Nie trzymaj w głowie niczego, co potrzebne w domu, zapisz to na Liście zakupów.', title_pt = 'Lista de memória 🛒', body_pt = 'A falta de sono enfraqueceu-lhe a memória? Não guarde na cabeça nada do que faz falta em casa, escreva-o na Lista de Compras.', title_sv = 'Minneslista 🛒', body_sv = 'Har sömnbristen försämrat minnet? Håll ingenting av det som behövs hemma i huvudet, skriv upp det på Inköpslistan.', title_vi = 'Danh sách ghi nhớ 🛒', body_vi = 'Thiếu ngủ làm mẹ hay quên? Đừng cố nhớ những thứ cần cho nhà, hãy ghi vào Danh sách mua sắm.', title_zh = '备忘清单 🛒', body_zh = '缺觉让你记性变差了？家里需要什么都别靠脑子记，写进购物清单吧。' WHERE id = 'be9ad5fd-195c-40e7-99c6-7f5f91e01526' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué hacen otras mamás? 💬', body_es = '¿Estás preocupada? Entra en la Comunidad Anacan y haz tu pregunta. Créeme, todas las mamás pasan por caminos parecidos.', title_fr = 'Que font les autres mamans ? 💬', body_fr = 'Vous êtes inquiète ? Rejoignez la Communauté Anacan et posez votre question. Croyez-nous, toutes les mamans passent par des chemins similaires.', title_hi = 'दूसरी माँएँ क्या करती हैं? 💬', body_hi = 'चिंतित हैं? Anacan कम्युनिटी में जाकर अपना सवाल पूछिए। यकीन मानिए, सभी माँएँ ऐसे ही रास्तों से गुज़रती हैं।', title_id = 'Apa yang dilakukan ibu-ibu lain? 💬', body_id = 'Cemas? Buka Komunitas Anacan dan ajukan pertanyaan Anda. Percayalah, semua ibu melewati jalan yang serupa.', title_ja = 'ほかのママたちはどうしている？💬', body_ja = '不安ですか？Anacanコミュニティで質問してみましょう。本当に、どのママも似たような道を通っています。', title_ko = '다른 엄마들은 어떻게 할까요? 💬', body_ko = '걱정되나요? Anacan 커뮤니티에 들어와 질문해 보세요. 모든 엄마가 비슷한 길을 걸어요.', title_nl = 'Wat doen andere mama’s? 💬', body_nl = 'Maak je je zorgen? Ga naar de Anacan Community en stel je vraag. Geloof ons, alle mama’s maken hetzelfde mee.', title_pl = 'Co robią inne mamy? 💬', body_pl = 'Martwisz się? Wejdź do Społeczności Anacan i zadaj pytanie. Uwierz, wszystkie mamy przechodzą podobną drogę.', title_pt = 'O que fazem as outras mães? 💬', body_pt = 'Está preocupada? Entre na Comunidade Anacan e faça a sua pergunta. Acredite, todas as mães passam por caminhos parecidos.', title_sv = 'Vad gör andra mammor? 💬', body_sv = 'Är du orolig? Gå in i Anacans Community och ställ din fråga. Tro oss, alla mammor går igenom liknande saker.', title_vi = 'Các mẹ khác làm thế nào? 💬', body_vi = 'Mẹ đang lo lắng? Hãy vào Cộng đồng Anacan và đặt câu hỏi. Tin đi, mọi bà mẹ đều trải qua những con đường tương tự.', title_zh = '其他妈妈都怎么做？💬', body_zh = '心里不安？来Anacan社区提出你的问题吧。相信我们，所有妈妈都走过相似的路。' WHERE id = '2226c745-19bb-4270-8e5c-a438c71816d4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una voz que calma 📖', body_es = 'Esta noche léele a tu bebé un cuento corto solo con tu voz. No hacen falta herramientas: la voz de mamá es la mayor magia.', title_fr = 'Une voix apaisante 📖', body_fr = 'Ce soir, lisez simplement un petit conte à bébé avec votre propre voix. Pas besoin d''outils, la voix de maman est la plus grande des magies.', title_hi = 'शांत करने वाली आवाज़ 📖', body_hi = 'आज शाम बच्चे को बस अपनी आवाज़ में एक छोटी कहानी सुनाइए। किसी टूल की ज़रूरत नहीं, माँ की आवाज़ सबसे बड़ा जादू है।', title_id = 'Suara yang menenangkan 📖', body_id = 'Malam ini bacakan dongeng pendek untuk anak hanya dengan suara Anda sendiri. Tidak perlu alat apa pun, suara ibu adalah sihir terbesar.', title_ja = '心落ち着く声 📖', body_ja = '今夜は、あなた自身の声だけで短いお話を読んであげましょう。道具はいりません。ママの声がいちばんの魔法です。', title_ko = '마음을 달래는 목소리 📖', body_ko = '오늘 저녁은 엄마 목소리로만 짧은 동화를 읽어 주세요. 도구는 필요 없어요, 엄마 목소리가 가장 큰 마법이에요.', title_nl = 'Een rustgevende stem 📖', body_nl = 'Lees je baby vanavond gewoon met je eigen stem een kort sprookje voor. Je hebt geen hulpmiddelen nodig, de stem van mama is de grootste magie.', title_pl = 'Kojący głos 📖', body_pl = 'Dziś wieczorem po prostu przeczytaj dziecku krótką bajkę własnym głosem. Nie potrzeba żadnych narzędzi, głos mamy to największa magia.', title_pt = 'Uma voz calmante 📖', body_pt = 'Esta noite, leia ao bebé uma história curta apenas com a sua voz. Não são precisas ferramentas, a voz da mãe é a maior magia.', title_sv = 'Lugnande röst 📖', body_sv = 'I kväll, läs bara en kort saga för barnet med din egen röst. Inga verktyg behövs, mammas röst är den största magin.', title_vi = 'Âm thanh xoa dịu 📖', body_vi = 'Tối nay chỉ cần đọc cho bé một câu chuyện ngắn bằng chính giọng của mẹ. Không cần công cụ nào, giọng mẹ là phép màu lớn nhất.', title_zh = '安抚的声音 📖', body_zh = '今晚就用你自己的声音给宝宝读一个短短的故事。不需要任何工具，妈妈的声音就是最大的魔法。' WHERE id = '31bb23a0-6713-4c06-9f74-65b7a51a3dd9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juegos divertidos 🎈', body_es = '¿Tumbado, mueve las piernas en el aire como si pedaleara? Es su nueva diversión. Únete y hazle cosquillas.', title_fr = 'Des jeux amusants 🎈', body_fr = 'Allongé, il pédale dans les airs avec ses jambes ? C''est son nouveau jeu. Participez et chatouillez-le.', title_hi = 'मज़ेदार खेल 🎈', body_hi = 'लेटकर पैरों से हवा में साइकिल चलाने जैसा करता है? यह उसका नया मनोरंजन है। साथ में शामिल होइए और उसे गुदगुदी कीजिए।', title_id = 'Permainan seru 🎈', body_id = 'Sambil berbaring, ia menggerakkan kakinya di udara seperti mengayuh sepeda? Ini hiburan barunya. Ikut bermain dan gelitiki ia.', title_ja = '楽しい遊び 🎈', body_ja = '仰向けで、空中で自転車をこぐように足を動かしていますか？これが赤ちゃんの新しいお気に入りです。一緒に遊んで、くすぐってあげましょう。', title_ko = '즐거운 놀이 🎈', body_ko = '누워서 다리로 허공에 자전거를 타나요? 아기의 새로운 놀이예요. 함께 어울리며 간지럽혀 주세요.', title_nl = 'Leuke spelletjes 🎈', body_nl = 'Ligt je baby op de rug te fietsen met de beentjes in de lucht? Dat is zijn nieuwe vermaak. Doe mee en kietel hem.', title_pl = 'Przyjemne zabawy 🎈', body_pl = 'Leży i jakby jeździ nóżkami na rowerku w powietrzu? To jego nowa rozrywka. Dołącz do zabawy i połaskocz go.', title_pt = 'Brincadeiras divertidas 🎈', body_pt = 'Deitado, faz com as pernas como se andasse de bicicleta no ar? É a nova diversão dele. Junte-se a ele e faça-lhe cócegas.', title_sv = 'Roliga lekar 🎈', body_sv = 'Ligger barnet på rygg och cyklar med benen i luften? Det är barnets nya nöje. Var med och kittla det.', title_vi = 'Trò chơi thú vị 🎈', body_vi = 'Bé nằm ngửa và đạp chân như đang đạp xe trên không? Đây là trò vui mới của bé. Hãy tham gia và cù bé nhé.', title_zh = '开心的游戏 🎈', body_zh = '宝宝躺着用小脚在空中“蹬自行车”？这是宝宝的新乐趣。加入进来，挠挠宝宝吧。' WHERE id = '34253cb9-0e01-47a7-9def-03c3b3e05aba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Regresión del sueño? 🌙', body_es = '¿Ha empezado a despertarse a menudo por la noche? Pueden ser señales de la regresión del sueño del 4.º mes. Ten paciencia, también es una etapa pasajera.', title_fr = 'Régression du sommeil ? 🌙', body_fr = 'Il se réveille souvent la nuit ? Ce sont peut-être les signes de la régression du sommeil du 4e mois. Soyez patiente, c''est aussi une étape passagère.', title_hi = 'स्लीप रिग्रेशन? 🌙', body_hi = 'रात में बार-बार जागने लगा है? ये चौथे महीने के स्लीप रिग्रेशन के संकेत हो सकते हैं। धैर्य रखिए, यह भी एक गुज़र जाने वाला दौर है।', title_id = 'Regresi tidur? 🌙', body_id = 'Mulai sering terbangun di malam hari? Bisa jadi ini tanda regresi tidur bulan ke-4. Bersabarlah, ini juga tahap yang akan berlalu.', title_ja = '睡眠退行？🌙', body_ja = '夜中によく起きるようになりましたか？4か月の睡眠退行のサインかもしれません。焦らずにいきましょう。これも一時的な時期です。', title_ko = '수면 퇴행? 🌙', body_ko = '밤에 자주 깨기 시작했나요? 4개월 수면 퇴행의 신호일 수 있어요. 조금만 견뎌요, 이것도 지나가는 시기예요.', title_nl = 'Slaapregressie? 🌙', body_nl = 'Wordt je baby ’s nachts vaak wakker? Dat kunnen signalen zijn van de slaapregressie van 4 maanden. Heb geduld, ook dit is een tijdelijke fase.', title_pl = 'Regres snu? 🌙', body_pl = 'Zaczęło często budzić się w nocy? To mogą być sygnały regresu snu 4. miesiąca. Bądź cierpliwa, to także przejściowy etap.', title_pt = 'Regressão do sono? 🌙', body_pt = 'Começou a acordar muitas vezes à noite? Podem ser sinais da regressão do sono do 4.º mês. Tenha paciência, também esta é uma fase passageira.', title_sv = 'Sömnregression? 🌙', body_sv = 'Har barnet börjat vakna ofta på nätterna? Det kan vara tecken på sömnregressionen vid 4 månader. Ha tålamod, även den här fasen går över.', title_vi = 'Khủng hoảng giấc ngủ? 🌙', body_vi = 'Bé bắt đầu hay thức giấc ban đêm? Đó có thể là dấu hiệu khủng hoảng giấc ngủ tháng thứ 4. Hãy kiên nhẫn, đây cũng chỉ là giai đoạn tạm thời.', title_zh = '睡眠倒退？🌙', body_zh = '宝宝夜里开始频繁醒来？这可能是4个月睡眠倒退的信号。要有耐心，这也只是一个暂时的阶段。' WHERE id = 'd1e64fb7-d149-4fd0-afca-834eed2264d1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuídate 🥑', body_es = 'En el posparto, los huesos y los dientes se vuelven más sensibles. No olvides añadir calcio a tu alimentación. Cuídate mucho.', title_fr = 'Prenez soin de vous 🥑', body_fr = 'Pendant le post-partum, les os et les dents deviennent plus fragiles. N''oubliez pas d''ajouter du calcium à votre alimentation. Prenez soin de vous.', title_hi = 'अपना ख्याल रखिए 🥑', body_hi = 'प्रसव के बाद के दौर में हड्डियाँ और दाँत संवेदनशील हो जाते हैं। अपने खाने में कैल्शियम जोड़ना न भूलें। अपना अच्छा ख्याल रखिए।', title_id = 'Jaga diri Anda 🥑', body_id = 'Di masa pascapersalinan, tulang dan gigi menjadi lebih sensitif. Jangan lupa menambahkan kalsium ke menu Anda. Rawat diri Anda dengan baik.', title_ja = '自分を大切に 🥑', body_ja = '産後は骨や歯がデリケートになります。食事にカルシウムを取り入れるのを忘れずに。自分を大切にしてくださいね。', title_ko = '엄마 몸을 챙기세요 🥑', body_ko = '산후에는 뼈와 치아가 약해질 수 있어요. 식단에 칼슘을 더하는 것 잊지 마세요. 스스로를 잘 돌보세요.', title_nl = 'Zorg voor jezelf 🥑', body_nl = 'Na de bevalling worden botten en tanden gevoeliger. Vergeet niet calcium aan je voeding toe te voegen. Zorg goed voor jezelf.', title_pl = 'Zadbaj o siebie 🥑', body_pl = 'W okresie poporodowym kości i zęby stają się bardziej wrażliwe. Pamiętaj o wapniu w swojej diecie. Dbaj o siebie.', title_pt = 'Proteja-se 🥑', body_pt = 'No pós-parto, os ossos e os dentes ficam mais sensíveis. Não se esqueça de juntar cálcio à sua alimentação. Cuide bem de si.', title_sv = 'Ta hand om dig själv 🥑', body_sv = 'Efter förlossningen blir skelett och tänder känsligare. Glöm inte att få i dig kalcium i kosten. Ta väl hand om dig själv.', title_vi = 'Hãy chăm sóc bản thân 🥑', body_vi = 'Sau sinh, xương và răng trở nên nhạy cảm hơn. Đừng quên bổ sung canxi vào bữa ăn. Hãy chăm sóc bản thân thật tốt.', title_zh = '照顾好自己 🥑', body_zh = '产后骨骼和牙齿会变得敏感。别忘了在饮食中补充钙。好好照顾自己。' WHERE id = '4eb27952-4f25-4c0d-8e25-cf21169fe3eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Esta mañana nada le parece bien? ☁️', body_es = 'Puede estar en un salto de crecimiento. Simplemente abrázale más y hazle sentir seguro.', title_fr = 'Rien ne lui convient ce matin ? ☁️', body_fr = 'Il traverse peut-être un pic de croissance. Prenez-le simplement plus souvent dans vos bras et rassurez-le.', title_hi = 'आज सुबह किसी बात से खुश नहीं? ☁️', body_hi = 'वह ग्रोथ स्पर्ट में हो सकता है। बस उसे ज़्यादा गले लगाइए और सुरक्षित महसूस कराइए।', title_id = 'Pagi ini ia rewel tanpa sebab? ☁️', body_id = 'Mungkin ia sedang mengalami lonjakan pertumbuhan. Cukup peluk ia lebih sering dan buat ia merasa aman.', title_ja = '今朝はご機嫌ななめ？☁️', body_ja = '成長のジャンプ期かもしれません。いつもより多く抱っこして、安心させてあげましょう。', title_ko = '오늘 아침 아무것도 마음에 안 드나요? ☁️', body_ko = '성장 급등기일 수 있어요. 더 많이 안아 주고 안전하다고 느끼게 해 주세요.', title_nl = 'Is je baby vanochtend nergens tevreden mee? ☁️', body_nl = 'Het kan een groeisprong zijn. Knuffel hem gewoon meer en laat hem zich veilig voelen.', title_pl = 'Dziś rano nic mu nie pasuje? ☁️', body_pl = 'To może być skok rozwojowy. Po prostu więcej go przytulaj i daj mu poczucie bezpieczeństwa.', title_pt = 'Esta manhã nada o contenta? ☁️', body_pt = 'Pode estar num pico de crescimento. Basta dar-lhe mais colo e fazê-lo sentir-se seguro.', title_sv = 'Är barnet missnöjt med allt i morse? ☁️', body_sv = 'Det kan vara mitt i ett utvecklingssprång. Krama barnet bara lite mer och få det att känna sig tryggt.', title_vi = 'Sáng nay bé chẳng hài lòng với điều gì? ☁️', body_vi = 'Có thể bé đang ở giai đoạn tăng trưởng vượt bậc. Chỉ cần ôm bé nhiều hơn và giúp bé cảm thấy an toàn.', title_zh = '今天早上什么都不满意？☁️', body_zh = '宝宝可能正处于猛长期。多抱抱宝宝，让宝宝感到安全就好。' WHERE id = '5e90ebc0-15bf-465f-ae64-eff8a7b0a00c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Señales de sueño 🥱', body_es = 'No esperes a que se frote los ojos y bostece. En cuanto su mirada se quede fija, pasa enseguida a la rutina de sueño.', title_fr = 'Les signaux du sommeil 🥱', body_fr = 'N''attendez pas qu''il se frotte les yeux et bâille. Dès que son regard devient fixe, commencez la routine du coucher.', title_hi = 'नींद के संकेत 🥱', body_hi = 'आँखें मलने और जम्हाई लेने का इंतज़ार मत कीजिए। जैसे ही उसकी नज़र सुस्त हो, तुरंत नींद का रूटीन शुरू कीजिए।', title_id = 'Tanda-tanda mengantuk 🥱', body_id = 'Jangan tunggu ia mengucek mata dan menguap. Begitu tatapannya mulai kosong, segera mulai rutinitas tidur.', title_ja = '眠いサイン 🥱', body_ja = '目をこすったりあくびをしたりするのを待たないで。視線がぼんやりしてきたら、すぐに寝かしつけのルーティンに移りましょう。', title_ko = '졸음 신호 🥱', body_ko = '눈을 비비고 하품할 때까지 기다리지 마세요. 시선이 멍해지면 바로 수면 루틴을 시작하세요.', title_nl = 'Slaapsignalen 🥱', body_nl = 'Wacht niet tot je baby in de ogen wrijft en gaapt. Zodra de blik wazig wordt, begin je meteen met het slaapritueel.', title_pl = 'Sygnały senności 🥱', body_pl = 'Nie czekaj, aż zacznie przecierać oczy i ziewać. Gdy tylko jego wzrok się zamgli, od razu zacznij rutynę przed snem.', title_pt = 'Sinais de sono 🥱', body_pt = 'Não espere que esfregue os olhos e boceje. Mal o olhar fique parado, passe logo à rotina do sono.', title_sv = 'Sömnsignaler 🥱', body_sv = 'Vänta inte tills barnet gnuggar ögonen och gäspar. Så fort blicken blir matt, gå direkt över till sömnrutinen.', title_vi = 'Tín hiệu buồn ngủ 🥱', body_vi = 'Đừng đợi bé dụi mắt và ngáp. Vừa thấy ánh mắt bé lờ đờ, hãy chuyển ngay sang nếp ngủ.', title_zh = '犯困信号 🥱', body_zh = '别等到宝宝揉眼睛、打哈欠。一看到宝宝眼神发直，就马上开始睡前程序。' WHERE id = '813f6345-1636-47fd-9a6b-aee16d069800' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Algo te tiene confundida? 🤖', body_es = 'En lugar de pasarte horas leyendo foros, hazle tu pregunta a Anacan AI y recibe una respuesta rápida.', title_fr = 'Quelque chose vous trouble ? 🤖', body_fr = 'Plutôt que de lire des forums pendant des heures, posez votre question à Anacan AI et obtenez une réponse rapide.', title_hi = 'कोई बात उलझा रही है? 🤖', body_hi = 'घंटों फ़ोरम पढ़ने के बजाय अपना सवाल Anacan AI से पूछिए और झटपट जवाब पाइए।', title_id = 'Ada yang membingungkan pikiran Anda? 🤖', body_id = 'Daripada berjam-jam membaca forum, ajukan pertanyaan Anda kepada Anacan AI dan dapatkan jawaban cepat.', title_ja = '何か気になることがありますか？🤖', body_ja = '何時間も掲示板を読むより、Anacan AIに質問して、すばやく答えを受け取りましょう。', title_ko = '머릿속이 복잡한가요? 🤖', body_ko = '몇 시간씩 게시판을 읽는 대신 Anacan AI에게 물어보고 빠른 답을 받으세요.', title_nl = 'Zit je ergens over te piekeren? 🤖', body_nl = 'Lees niet urenlang fora, stel je vraag aan Anacan AI en krijg snel antwoord.', title_pl = 'Coś nie daje ci spokoju? 🤖', body_pl = 'Zamiast godzinami czytać fora, zadaj pytanie Anacan AI i otrzymaj szybką odpowiedź.', title_pt = 'Há algo que a confunde? 🤖', body_pt = 'Em vez de passar horas a ler fóruns, faça a sua pergunta ao Anacan AI e receba uma resposta rápida.', title_sv = 'Är det något som snurrar i huvudet? 🤖', body_sv = 'I stället för att läsa forum i timmar, ställ din fråga till Anacan AI och få ett snabbt svar.', title_vi = 'Có điều gì khiến mẹ rối bời? 🤖', body_vi = 'Thay vì đọc diễn đàn hàng giờ, hãy hỏi Anacan AI và nhận câu trả lời nhanh chóng.', title_zh = '有什么让你困惑的？🤖', body_zh = '与其花几个小时翻论坛，不如把问题发给Anacan AI，快速得到答案。' WHERE id = '088b061c-e51f-4931-8636-b06152d7eaff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Sin paciencia y con los brazos agotados? 👨‍👧', body_es = 'Esta noche dale el bebé a papá, cierra la puerta y quédate 15 minutos contigo misma.', title_fr = 'À bout de patience, les bras fatigués ? 👨‍👧', body_fr = 'Ce soir, confiez bébé à Papa, fermez la porte et restez 15 minutes avec vous-même.', title_hi = 'धैर्य खत्म, बाँहें थक गईं? 👨‍👧', body_hi = 'आज शाम बच्चे को पापा को दीजिए, दरवाज़ा बंद कीजिए और 15 मिनट अपने साथ बिताइए।', title_id = 'Kesabaran habis, lengan pegal? 👨‍👧', body_id = 'Malam ini serahkan anak kepada Ayah, tutup pintu, dan nikmati 15 menit untuk diri sendiri.', title_ja = '心の余裕がなくなって、腕もくたくた？👨‍👧', body_ja = '今夜は赤ちゃんをパパにまかせて、ドアを閉めて、15分間ひとりの時間を過ごしましょう。', title_ko = '인내심은 바닥나고 팔은 지쳤나요? 👨‍👧', body_ko = '오늘 저녁은 아기를 아빠에게 맡기고 문을 닫은 뒤 15분 동안 나만의 시간을 가지세요.', title_nl = 'Is je geduld op en zijn je armen moe? 👨‍👧', body_nl = 'Geef je baby vanavond aan papa, doe de deur dicht en neem 15 minuten voor jezelf.', title_pl = 'Kończy się cierpliwość, ręce zmęczone? 👨‍👧', body_pl = 'Dziś wieczorem oddaj dziecko tacie, zamknij drzwi i pobądź 15 minut sama ze sobą.', title_pt = 'Perdeu a paciência e tem os braços cansados? 👨‍👧', body_pt = 'Esta noite, entregue o bebé ao pai, feche a porta e fique 15 minutos consigo mesma.', title_sv = 'Har tålamodet tagit slut och armarna blivit trötta? 👨‍👧', body_sv = 'I kväll, ge barnet till pappa, stäng dörren och var för dig själv i 15 minuter.', title_vi = 'Hết kiên nhẫn, tay mỏi nhừ? 👨‍👧', body_vi = 'Tối nay hãy trao bé cho bố, đóng cửa lại và dành 15 phút cho riêng mình.', title_zh = '耐心用完了，胳膊也累了？👨‍👧', body_zh = '今晚把宝宝交给爸爸，关上门，留15分钟给自己。' WHERE id = '616fd04c-b736-454a-9242-b3c011b0cdc5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un paraíso desordenado 🌪️', body_es = '¿Hay cosas del bebé por toda la casa? Que las haya. Una casa desordenada no demuestra que seas mala madre, sino que tu prioridad es tu bebé.', title_fr = 'Un paradis en désordre 🌪️', body_fr = 'Des affaires de bébé partout dans la maison ? Laissez-les. Une maison en désordre ne montre pas que vous êtes une mauvaise mère, mais que votre priorité, c''est votre bébé.', title_hi = 'बिखरा हुआ स्वर्ग 🌪️', body_hi = 'घर में हर जगह बच्चे की चीज़ें हैं? रहने दीजिए। बिखरा घर यह नहीं दिखाता कि आप बुरी माँ हैं, बल्कि यह कि आपकी प्राथमिकता आपका बच्चा है।', title_id = 'Surga yang berantakan 🌪️', body_id = 'Barang-barang anak ada di seluruh rumah? Biarkan saja. Rumah yang berantakan bukan berarti Anda ibu yang buruk, melainkan tanda bahwa bayi Anda adalah prioritas.', title_ja = '散らかった楽園 🌪️', body_ja = '家じゅうに赤ちゃんのものが散らばっている？そのままでいいのです。散らかった家は、あなたがダメなママだという証拠ではなく、赤ちゃんを最優先にしているという証です。', title_ko = '어질러진 천국 🌪️', body_ko = '집 안 곳곳에 아기 물건이 있나요? 그냥 두세요. 어질러진 집은 나쁜 엄마라는 뜻이 아니라 아기가 우선이라는 뜻이에요.', title_nl = 'Een rommelig paradijs 🌪️', body_nl = 'Ligt er overal in huis babyspul? Laat maar liggen. Een rommelig huis laat niet zien dat je een slechte moeder bent, maar dat je baby je prioriteit is.', title_pl = 'Bałaganiarski raj 🌪️', body_pl = 'W całym domu leżą dziecięce rzeczy? Niech leżą. Bałagan w domu nie świadczy o tym, że jesteś złą mamą, tylko o tym, że twoim priorytetem jest dziecko.', title_pt = 'Um paraíso desarrumado 🌪️', body_pt = 'Há coisas do bebé por toda a casa? Deixe estar. Uma casa desarrumada não mostra que é má mãe, mostra que a sua prioridade é o bebé.', title_sv = 'Ett stökigt paradis 🌪️', body_sv = 'Ligger det barnsaker överallt hemma? Låt dem ligga. Ett stökigt hem visar inte att du är en dålig mamma, utan att ditt barn kommer i första hand.', title_vi = 'Thiên đường bừa bộn 🌪️', body_vi = 'Đồ của bé ở khắp mọi nơi trong nhà? Cứ để vậy. Nhà bừa bộn không có nghĩa mẹ là người mẹ tồi, mà cho thấy ưu tiên của mẹ là bé.', title_zh = '乱糟糟的天堂 🌪️', body_zh = '家里到处都是宝宝的东西？随它去吧。乱糟糟的家不说明你是个坏妈妈，只说明宝宝是你的头等大事。' WHERE id = '232de7cd-2ff6-4b62-8cee-002063d545fd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Harta de estar en casa? ☕', body_es = '¿Harta de estar en casa? Elige en Lugares para mamás una cafetería cercana con acceso cómodo para el cochecito.', title_fr = 'Marre de rester à la maison ? ☕', body_fr = 'Marre de rester à la maison ? Choisissez dans les Lieux adaptés aux mamans un café proche, facilement accessible en poussette.', title_hi = 'घर में रहकर ऊब गईं? ☕', body_hi = 'घर में रहकर ऊब गईं? माँ के लिए अनुकूल जगहों में से पास का ऐसा कैफ़े चुनिए जहाँ प्रैम के साथ आसानी से जा सकें।', title_id = 'Bosan di rumah? ☕', body_id = 'Bosan di rumah? Pilih kafe terdekat yang mudah dimasuki dengan kereta bayi dari Tempat Ramah Ibu.', title_ja = '家にいるのに飽きた？☕', body_ja = '家にいるのに飽きましたか？「ママにやさしいスポット」から、ベビーカーで入りやすい近くのカフェを選びましょう。', title_ko = '집에만 있어서 답답한가요? ☕', body_ko = '집에만 있어서 답답한가요? 엄마 친화 장소에서 유모차로 편하게 들어갈 수 있는 가까운 카페를 골라 보세요.', title_nl = 'Ben je het thuiszitten zat? ☕', body_nl = 'Ben je het thuiszitten zat? Kies in Mamavriendelijke plekken een café in de buurt dat goed toegankelijk is met de kinderwagen.', title_pl = 'Nudzi cię siedzenie w domu? ☕', body_pl = 'Nudzi cię siedzenie w domu? Wybierz w Miejscach przyjaznych mamom pobliską kawiarnię, do której łatwo wjedziesz wózkiem.', title_pt = 'Farta de estar em casa? ☕', body_pt = 'Farta de estar em casa? Escolha nos Locais Amigos das Mães um café próximo com acesso fácil para carrinhos de bebé.', title_sv = 'Trött på att vara hemma? ☕', body_sv = 'Trött på att vara hemma? Välj ett kafé i närheten i Mammavänliga platser dit du lätt kommer in med barnvagnen.', title_vi = 'Ở nhà mãi thấy bức bối? ☕', body_vi = 'Ở nhà mãi thấy bức bối? Hãy chọn trong Địa điểm thân thiện với mẹ một quán cà phê gần nhà, có lối vào thuận tiện cho xe đẩy.', title_zh = '在家待腻了？☕', body_zh = '在家待腻了？在妈妈友好场所里选一家附近方便推婴儿车进去的咖啡馆吧。' WHERE id = '2cbef83d-a5f1-4b69-858b-9d1310e2cac3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora del cuento inteligente 🪄', body_es = 'Crea en Cuentos inteligentes una historia especial para esta noche: la historia del pequeño valiente que duerme sobre las nubes.', title_fr = 'L''heure du conte intelligent 🪄', body_fr = 'Créez dans les Contes intelligents une histoire spéciale pour ce soir : l''histoire du petit courageux qui dort sur les nuages.', title_hi = 'स्मार्ट कहानी का समय 🪄', body_hi = 'स्मार्ट कहानियों में आज की रात के लिए खास कहानी बनाइए: बादलों पर सोने वाले बहादुर नन्हे की कहानी।', title_id = 'Waktunya Dongeng Pintar 🪄', body_id = 'Buat cerita khusus untuk malam ini di Dongeng Pintar: Kisah si kecil pemberani yang tidur di atas awan.', title_ja = 'スマートおはなしの時間 🪄', body_ja = '「スマートおはなし」で今夜だけの特別なお話をつくりましょう：雲の上で眠る勇敢な赤ちゃんのお話。', title_ko = '스마트 동화 시간 🪄', body_ko = '스마트 동화에서 오늘 밤만을 위한 이야기를 만들어 보세요: 구름 위에서 잠드는 용감한 아기 이야기.', title_nl = 'Tijd voor een slim sprookje 🪄', body_nl = 'Maak in Slimme sprookjes een speciaal verhaal voor vannacht: het verhaal van de dappere kleine die op de wolken slaapt.', title_pl = 'Czas na Mądrą bajkę 🪄', body_pl = 'Stwórz w Mądrych bajkach wyjątkową historię na tę noc: Opowieść o dzielnym maluchu, który śpi na chmurach.', title_pt = 'Hora da história inteligente 🪄', body_pt = 'Crie nas Histórias Inteligentes uma história especial para esta noite: a história do bebé corajoso que dorme em cima das nuvens.', title_sv = 'Dags för en smart saga 🪄', body_sv = 'Skapa en berättelse speciellt för i kväll i Smarta sagor: ''Berättelsen om den modiga lilla som sov ovanpå molnen''.', title_vi = 'Giờ Truyện cổ tích thông minh 🪄', body_vi = 'Hãy tạo một câu chuyện dành riêng cho đêm nay trong Truyện cổ tích thông minh: Câu chuyện về em bé dũng cảm ngủ trên những đám mây.', title_zh = '智慧童话时间 🪄', body_zh = '在智慧童话里为今晚创作一个专属故事：睡在云朵上的勇敢小宝贝的故事。' WHERE id = 'ff5950e2-aed4-41ca-bc9a-64a1b039968a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crisis de babas 🤤', body_es = '¿Se le moja todo el cuello en segundos? Sus encías se están preparando poco a poco. Los baberos de silicona son tu mejor salvación.', title_fr = 'Crises de bave 🤤', body_fr = 'Son col est trempé en quelques secondes ? Ses gencives se préparent petit à petit. Les bavoirs en silicone sont les meilleurs alliés.', title_hi = 'लार का सैलाब 🤤', body_hi = 'पूरा कॉलर सेकंडों में भीग जाता है? मसूड़े धीरे-धीरे तैयार हो रहे हैं। सिलिकॉन बिब सबसे अच्छे मददगार हैं।', title_id = 'Banjir air liur 🤤', body_id = 'Seluruh kerah bajunya basah dalam hitungan detik? Gusinya perlahan sedang bersiap. Celemek silikon adalah penyelamat terbaik.', title_ja = 'よだれ大洪水 🤤', body_ja = '襟元が数秒でびしょびしょ？歯ぐきが少しずつ準備を始めています。シリコンのスタイがいちばんの救世主です。', title_ko = '침 대홍수 🤤', body_ko = '옷깃이 몇 초 만에 다 젖나요? 잇몸이 천천히 준비하고 있어요. 실리콘 턱받이가 최고의 구세주예요.', title_nl = 'Kwijlcrisis 🤤', body_nl = 'Is het hele kraagje binnen enkele seconden nat? Het tandvlees bereidt zich langzaam voor. Siliconen slabbers zijn de beste redding.', title_pl = 'Kryzysy ze śliną 🤤', body_pl = 'Cały śliniaczek mokry w kilka sekund? Dziąsła powoli się przygotowują. Silikonowe śliniaki to najlepszy ratunek.', title_pt = 'Crises de baba 🤤', body_pt = 'A gola fica toda molhada em segundos? As gengivas estão a preparar-se aos poucos. Os babetes de silicone são a melhor salvação.', title_sv = 'Dreglkriser 🤤', body_sv = 'Blir hela kragen blöt på några sekunder? Tandköttet förbereder sig sakta. Haklappar av silikon är den bästa räddningen.', title_vi = 'Khủng hoảng nước dãi 🤤', body_vi = 'Cả cổ áo ướt sũng chỉ trong vài giây? Lợi của bé đang dần chuẩn bị. Yếm silicon là vị cứu tinh tốt nhất.', title_zh = '口水泛滥 🤤', body_zh = '整个衣领几秒钟就湿透了？牙龈正在慢慢做准备。硅胶围兜是最好的救星。' WHERE id = '37346c6c-3239-4e07-bcc0-24af9be99f3f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El aire fresco es medicina 🌳', body_es = 'Si el bebé está muy inquieto, sácalo enseguida al aire libre. El aire fresco es el remedio más sencillo y eficaz contra las crisis.', title_fr = 'L''air frais est un remède 🌳', body_fr = 'Si votre enfant est très agité, sortez-le tout de suite au grand air. L''air frais est le remède le plus simple et le plus efficace contre les crises.', title_hi = 'ताज़ी हवा दवा है 🌳', body_hi = 'अगर बच्चा बहुत बेचैन है, तो उसे तुरंत खुली हवा में ले जाइए। ताज़ी हवा रोने-धोने की सबसे आसान और असरदार दवा है।', title_id = 'Udara segar adalah obat 🌳', body_id = 'Jika anak sangat gelisah, segera bawa ia ke udara terbuka. Udara segar adalah obat paling sederhana dan ampuh untuk meredakan rewel.', title_ja = '新鮮な空気は薬です 🌳', body_ja = '赤ちゃんがとても落ち着かないときは、すぐに外に連れ出しましょう。新鮮な空気は、ぐずりにいちばんシンプルでよく効く薬です。', title_ko = '맑은 공기는 약이에요 🌳', body_ko = '아기가 많이 보채면 바로 바깥 공기를 쐬어 주세요. 맑은 공기는 보챔을 멈추는 가장 간단하고 확실한 약이에요.', title_nl = 'Frisse lucht is een medicijn 🌳', body_nl = 'Is je baby heel onrustig? Ga dan meteen naar buiten. Frisse lucht is het eenvoudigste en snelste middel tegen huilbuien.', title_pl = 'Świeże powietrze to lekarstwo 🌳', body_pl = 'Jeśli dziecko jest bardzo niespokojne, od razu wyjdź z nim na zewnątrz. Świeże powietrze to najprostsze i najskuteczniejsze lekarstwo na kryzysy.', title_pt = 'O ar puro é um remédio 🌳', body_pt = 'Se o bebé estiver muito inquieto, leve-o logo ao ar livre. O ar puro é o remédio mais simples e eficaz contra as crises.', title_sv = 'Frisk luft är medicin 🌳', body_sv = 'Om barnet är väldigt oroligt, ta genast ut det i friska luften. Frisk luft är den enklaste och mest effektiva medicinen mot kriser.', title_vi = 'Không khí trong lành là liều thuốc 🌳', body_vi = 'Nếu bé quá bồn chồn, hãy đưa bé ra ngoài trời ngay. Không khí trong lành là liều thuốc đơn giản và hiệu quả nhất cho những cơn quấy.', title_zh = '新鲜空气是良药 🌳', body_zh = '如果宝宝特别烦躁，马上带宝宝出门。新鲜空气是止住哭闹最简单、最有效的良药。' WHERE id = '86a98c8a-884a-4567-83c1-4d206dccead9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Somos un equipo! 💖', body_es = 'Después de un día difícil, siéntate frente a tu pareja y desahogaos. Apoyaros el uno al otro reparte la carga a la mitad.', title_fr = 'Nous sommes une équipe ! 💖', body_fr = 'Après une journée difficile, asseyez-vous face à votre conjoint et confiez-vous l''un à l''autre. Se soutenir mutuellement divise la charge par deux.', title_hi = 'हम एक टीम हैं! 💖', body_hi = 'एक मुश्किल दिन के बाद अपने साथी के आमने-सामने बैठकर दिल की बात कीजिए। एक-दूसरे का साथ देने से बोझ आधा हो जाता है।', title_id = 'Kita satu tim! 💖', body_id = 'Setelah hari yang berat, duduklah berhadapan dengan pasangan dan saling bercerita. Saling mendukung membagi beban menjadi separuh.', title_ja = 'わたしたちはチームです！💖', body_ja = '大変な1日のあとは、パートナーと向かい合って座り、話をしましょう。支え合うことで、負担は半分になります。', title_ko = '우리는 한 팀이에요! 💖', body_ko = '힘든 하루가 끝나면 배우자와 마주 앉아 이야기를 나누세요. 서로 의지하면 짐이 절반으로 줄어요.', title_nl = 'Wij zijn een team! 💖', body_nl = 'Ga na een zware dag tegenover je partner zitten en praat je hart uit. Elkaar steunen halveert de last.', title_pl = 'Jesteśmy drużyną! 💖', body_pl = 'Po trudnym dniu usiądź z partnerem twarzą w twarz i porozmawiajcie. Wzajemne wsparcie dzieli ciężar na pół.', title_pt = 'Somos uma equipa! 💖', body_pt = 'Depois de um dia difícil, sente-se frente a frente com o seu companheiro e desabafem. Apoiarem-se um ao outro divide o peso ao meio.', title_sv = 'Vi är ett lag! 💖', body_sv = 'Efter en svår dag, sätt dig mitt emot din partner och prata av er. Att stötta varandra halverar bördan.', title_vi = 'Chúng mình là một đội! 💖', body_vi = 'Sau một ngày khó khăn, hãy ngồi đối diện với chồng và tâm sự. Hỗ trợ lẫn nhau giúp gánh nặng vơi đi một nửa.', title_zh = '我们是一个团队！💖', body_zh = '忙碌了艰难的一天后，和另一半面对面坐下来聊聊心事。互相支持能让负担减半。' WHERE id = 'ae291c04-b5c7-4ff1-937e-2b2b6d502624' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No dudes en compartir lo que sientes. 📝', body_es = '¿Cansada o feliz? Da igual: anota tus emociones de hoy en el Diario de ánimo y quítate peso de encima.', title_fr = 'N''hésitez pas à partager vos ressentis. 📝', body_fr = 'Fatiguée ou heureuse ? Peu importe, allégez-vous en notant vos émotions du jour dans le Journal d''humeur.', title_hi = 'अपनी भावनाएँ बाँटने में संकोच मत कीजिए। 📝', body_hi = 'थकी हैं या खुश? फ़र्क नहीं पड़ता, आज की भावनाएँ मूड डायरी में लिखकर मन हल्का कीजिए।', title_id = 'Jangan ragu berbagi perasaan. 📝', body_id = 'Lelah atau bahagia? Tidak masalah, ringankan hati dengan mencatat emosi Anda hari ini di Buku Harian Suasana Hati.', title_ja = '気持ちを打ち明けることをためらわないで。📝', body_ja = '疲れている？それとも幸せ？どちらでも大丈夫。今日の気持ちを「気分日記」に記録して、心を軽くしましょう。', title_ko = '감정을 나누는 걸 망설이지 마세요. 📝', body_ko = '피곤하든 행복하든 상관없어요. 오늘의 감정을 기분 일기에 기록하고 마음을 가볍게 하세요.', title_nl = 'Deel gerust je gevoelens. 📝', body_nl = 'Moe of gelukkig? Maakt niet uit, noteer je emoties van vandaag in je Stemmingsdagboek en lucht je hart.', title_pl = 'Nie wahaj się dzielić uczuciami. 📝', body_pl = 'Zmęczona czy szczęśliwa? Nieważne, zapisz dzisiejsze emocje w Dzienniku nastroju i poczuj ulgę.', title_pt = 'Não hesite em partilhar o que sente. 📝', body_pt = 'Cansada ou feliz? Não importa, alivie-se registando as emoções de hoje no Diário de Humor.', title_sv = 'Tveka inte att dela dina känslor. 📝', body_sv = 'Trött eller glad? Det spelar ingen roll, lätta ditt hjärta genom att skriva ner dagens känslor i Humördagboken.', title_vi = 'Đừng ngại chia sẻ cảm xúc. 📝', body_vi = 'Mệt mỏi hay hạnh phúc? Không sao cả, hãy ghi lại cảm xúc hôm nay vào Nhật ký tâm trạng để nhẹ lòng hơn.', title_zh = '不要羞于分享你的感受。📝', body_zh = '疲惫还是幸福？都没关系，把今天的情绪记在心情日记里，让自己轻松一点。' WHERE id = 'eabf6802-121e-4850-8036-ab2dbabaf84e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de la música 🎶', body_es = 'Prueba a cortar los llantos sin motivo del atardecer con música clásica de ritmo lento. A menudo funciona.', title_fr = 'Le pouvoir de la musique 🎶', body_fr = 'Essayez d''apaiser les pleurs sans raison de fin d''après-midi avec de la musique classique au tempo lent. Ça marche souvent.', title_hi = 'संगीत की ताकत 🎶', body_hi = 'शाम को बिना वजह शुरू होने वाले रोने को धीमी लय वाले शास्त्रीय संगीत से रोकने की कोशिश कीजिए। अक्सर यह काम करता है।', title_id = 'Kekuatan musik 🎶', body_id = 'Coba redakan tangisan tanpa sebab di sore hari dengan musik klasik bertempo lambat. Sering kali berhasil.', title_ja = '音楽の力 🎶', body_ja = '夕方から始まる理由のわからない泣きぐずりには、ゆったりしたテンポのクラシック音楽を試してみましょう。効くことが多いですよ。', title_ko = '음악의 힘 🎶', body_ko = '해 질 무렵 시작되는 이유 없는 울음엔 느린 템포의 클래식 음악을 틀어 보세요. 대부분 효과가 있어요.', title_nl = 'De kracht van muziek 🎶', body_nl = 'Probeer het onverklaarbare huilen aan het eind van de middag te stoppen met rustige klassieke muziek. Dat werkt vaak.', title_pl = 'Moc muzyki 🎶', body_pl = 'Wieczorny płacz bez powodu spróbuj przerwać spokojną muzyką klasyczną w wolnym tempie. Często to działa.', title_pt = 'O poder da música 🎶', body_pt = 'Experimente acalmar o choro sem razão que começa ao fim da tarde com música clássica em ritmo lento. Muitas vezes resulta.', title_sv = 'Musikens kraft 🎶', body_sv = 'Prova att bryta den oförklarliga gråten som börjar på kvällen med klassisk musik i långsamt tempo. Det fungerar ofta.', title_vi = 'Sức mạnh của âm nhạc 🎶', body_vi = 'Hãy thử xoa dịu những cơn khóc vô cớ lúc chiều tối bằng nhạc cổ điển tiết tấu chậm. Thường thì rất hiệu quả.', title_zh = '音乐的力量 🎶', body_zh = '傍晚开始莫名哭闹时，试试放些慢节奏的古典音乐。常常很管用。' WHERE id = '5fcfd433-5086-40d6-89d5-0d756fb06e17' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lo está intentando! 🤸‍♂️', body_es = 'Boca abajo, se apoya en los brazos e intenta mirar hacia arriba. Sus músculos se fortalecen día a día, ¡bravo por él!', title_fr = 'Il essaie ! 🤸‍♂️', body_fr = 'Sur le ventre, il prend appui sur ses bras pour essayer de regarder en haut. Ses muscles se renforcent de jour en jour, bravo à lui !', title_hi = 'कोशिश कर रहा है! 🤸‍♂️', body_hi = 'पेट के बल लेटे हुए वह बाँहों के बल ऊपर देखने की कोशिश करता है। उसकी मांसपेशियाँ दिन-ब-दिन मज़बूत हो रही हैं, शाबाश!', title_id = 'Ia sedang mencoba! 🤸‍♂️', body_id = 'Saat tengkurap, ia bertumpu pada lengannya dan mencoba melihat ke atas. Ototnya makin kuat dari hari ke hari, hebat!', title_ja = 'がんばってる！🤸‍♂️', body_ja = 'うつぶせのとき、腕で体を支えて上を見ようとしています。筋肉が日に日に強くなっています。えらいね！', title_ko = '도전 중이에요! 🤸‍♂️', body_ko = '엎드려 있을 때 팔에 힘을 주고 위를 보려고 해요. 근육이 날마다 튼튼해지고 있어요, 정말 잘했어요!', title_nl = 'Je baby doet zijn best! 🤸‍♂️', body_nl = 'Tijdens de buikligging duwt je baby zich op met de armpjes en probeert hij omhoog te kijken. De spiertjes worden elke dag sterker, goed zo!', title_pl = 'Próbuje! 🤸‍♂️', body_pl = 'Leżąc na brzuszku, odpycha się rączkami i próbuje spojrzeć w górę. Jego mięśnie z dnia na dzień są silniejsze, brawo!', title_pt = 'Está a tentar! 🤸‍♂️', body_pt = 'De barriga para baixo, apoia-se nos braços e tenta olhar para cima. Os músculos estão a ficar mais fortes de dia para dia, muito bem!', title_sv = 'Barnet försöker! 🤸‍♂️', body_sv = 'I magläge tar barnet spjärn med armarna och försöker titta upp. Musklerna blir starkare dag för dag, bra jobbat!', title_vi = 'Bé đang cố gắng! 🤸‍♂️', body_vi = 'Khi nằm sấp, bé chống tay để cố ngước lên nhìn. Cơ bắp của bé ngày một cứng cáp hơn, giỏi quá!', title_zh = '在努力尝试！🤸‍♂️', body_zh = '趴着时，宝宝用胳膊撑起身子，努力往上看。肌肉一天比一天结实，宝宝真棒！' WHERE id = 'b4113857-b164-4ab8-b41d-4e516341edad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Detener el tiempo 📸', body_es = 'Crece tan rápido... Ponle algo bonito e inmortaliza el momento con la Sesión de fotos del bebé.', title_fr = 'Arrêter le temps 📸', body_fr = 'Il grandit si vite... Habillez-le joliment et immortalisez l''instant avec la Séance photo bébé.', title_hi = 'समय को रोक लीजिए 📸', body_hi = 'वह इतनी तेज़ी से बड़ा हो रहा है... उसे सुंदर कपड़े पहनाइए और बेबी फ़ोटोशूट से इस पल को अमर कर दीजिए।', title_id = 'Menghentikan waktu 📸', body_id = 'Ia tumbuh begitu cepat... Pakaikan baju yang cantik dan abadikan momen ini dengan Pemotretan Bayi.', title_ja = '時間を止めよう 📸', body_ja = '赤ちゃんはあっという間に大きくなります...かわいいお洋服を着せて、「ベビーフォトセッション」でこの瞬間を永遠に残しましょう。', title_ko = '시간을 멈추기 📸', body_ko = '아기가 너무 빨리 자라요... 예쁘게 입히고 아기 사진 촬영으로 이 순간을 영원히 남기세요.', title_nl = 'De tijd stilzetten 📸', body_nl = 'Je baby groeit zo snel... Trek hem iets moois aan en leg het moment voor altijd vast met Babyfotoshoot.', title_pl = 'Zatrzymać czas 📸', body_pl = 'Rośnie tak szybko... Ubierz je ładnie i uwiecznij tę chwilę w Sesji zdjęciowej dziecka.', title_pt = 'Parar o tempo 📸', body_pt = 'Cresce tão depressa... Vista-o com uma roupa bonita e eternize o momento com a Sessão Fotográfica do Bebé.', title_sv = 'Stoppa tiden 📸', body_sv = 'Barnet växer så snabbt... Klä upp det fint och förevig ögonblicket med Babyfotografering.', title_vi = 'Dừng lại thời gian 📸', body_vi = 'Bé lớn nhanh quá... Hãy mặc cho bé thật xinh và lưu giữ khoảnh khắc mãi mãi với Chụp ảnh cho bé.', title_zh = '让时间停下来 📸', body_zh = '宝宝长得太快了……给宝宝穿上漂亮衣服，用宝宝写真把这一刻永远留住吧。' WHERE id = 'ec61705b-0071-49b5-a6b0-3849dfa461ac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cada vez más risas 😂', body_es = 'Responde con carcajadas a cada gesto gracioso que haces. ¡No olvides grabar en vídeo este momento increíble!', title_fr = 'Les éclats de rire se multiplient 😂', body_fr = 'Il répond par des éclats de rire à chacune de vos grimaces. N''oubliez pas de filmer ce moment magnifique !', title_hi = 'हँसी बढ़ रही है 😂', body_hi = 'आपकी हर मज़ेदार हरकत का जवाब वह ठहाकों से देता है। इस शानदार पल का वीडियो बनाना न भूलें!', title_id = 'Tawanya makin sering 😂', body_id = 'Ia membalas setiap gerakan lucu Anda dengan tawa terbahak-bahak. Jangan lupa merekam momen luar biasa ini!', title_ja = '笑い声が増えています 😂', body_ja = 'あなたのおもしろいしぐさのひとつひとつに、大きな笑い声で応えてくれます。このすばらしい瞬間を動画に撮るのを忘れずに！', title_ko = '웃음이 늘어나요 😂', body_ko = '엄마의 웃긴 행동 하나하나에 까르르 웃음으로 대답해요. 이 멋진 순간을 영상으로 남기는 것 잊지 마세요!', title_nl = 'Steeds meer lachjes 😂', body_nl = 'Je baby reageert op elk grappig gebaar van jou met een schaterlach. Vergeet dit geweldige moment niet op video vast te leggen!', title_pl = 'Śmiechu przybywa 😂', body_pl = 'Na każdy twój zabawny ruch odpowiada głośnym śmiechem. Nie zapomnij nagrać tej wspaniałej chwili!', title_pt = 'As gargalhadas estão a aumentar 😂', body_pt = 'Responde com gargalhadas a cada gesto engraçado que faz. Não se esqueça de gravar este momento fantástico em vídeo!', title_sv = 'Skratten blir fler 😂', body_sv = 'Barnet svarar med skratt på varje rolig grej du gör. Glöm inte att filma det här fantastiska ögonblicket!', title_vi = 'Tiếng cười ngày càng nhiều 😂', body_vi = 'Bé đáp lại mỗi trò ngộ nghĩnh của mẹ bằng tràng cười giòn tan. Đừng quên quay lại khoảnh khắc tuyệt vời này!', title_zh = '笑声越来越多 😂', body_zh = '你做的每个滑稽动作，宝宝都用哈哈大笑来回应。别忘了把这美妙时刻拍成视频！' WHERE id = '72b166c9-a8f9-4dc5-be7f-5911ccda18ea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La base del sueño ⏱️', body_es = 'En el cuarto mes es muy importante crear una buena rutina de sueño. No la rompas nunca, para que tus noches sean tranquilas.', title_fr = 'Les bases du sommeil ⏱️', body_fr = 'Au quatrième mois, il est très important d''installer un bon rythme de sommeil. Ne cassez jamais la routine, pour que vos nuits soient paisibles.', title_hi = 'नींद की नींव ⏱️', body_hi = 'चौथे महीने में सही नींद का रूटीन बनाना बहुत ज़रूरी है। रूटीन कभी मत तोड़िए, ताकि आपकी रातें आराम से गुज़रें।', title_id = 'Fondasi tidur ⏱️', body_id = 'Di bulan keempat, membangun pola tidur yang tepat sangat penting. Jangan pernah merusak rutinitas agar malam-malam Anda tenang.', title_ja = '睡眠の土台 ⏱️', body_ja = '4か月目に正しい睡眠リズムをつくることはとても大切です。夜を穏やかに過ごせるよう、ルーティンを崩さないようにしましょう。', title_ko = '수면의 기초 ⏱️', body_ko = '4개월에는 올바른 수면 패턴을 만드는 게 아주 중요해요. 편안한 밤을 위해 루틴을 절대 깨지 마세요.', title_nl = 'De basis van goede slaap ⏱️', body_nl = 'In de vierde maand is een goed slaapritme heel belangrijk. Doorbreek de routine nooit, zodat jullie nachten rustig verlopen.', title_pl = 'Fundament snu ⏱️', body_pl = 'W czwartym miesiącu bardzo ważne jest ustalenie właściwego rytmu snu. Nigdy nie łam rutyny, by twoje noce były spokojne.', title_pt = 'A base do sono ⏱️', body_pt = 'No quarto mês, é muito importante criar uma rotina de sono correta. Nunca quebre a rotina, para que as suas noites sejam tranquilas.', title_sv = 'Grunden för sömnen ⏱️', body_sv = 'I fjärde månaden är det väldigt viktigt att bygga upp en bra sömnrytm. Bryt aldrig rutinen, så blir nätterna lugna.', title_vi = 'Nền tảng giấc ngủ ⏱️', body_vi = 'Ở tháng thứ tư, xây dựng nếp ngủ đúng rất quan trọng. Đừng bao giờ phá vỡ nếp sinh hoạt để những đêm của mẹ được yên bình.', title_zh = '睡眠基础 ⏱️', body_zh = '第四个月建立正确的睡眠规律非常重要。千万别打乱作息，这样夜晚才能安稳。' WHERE id = '968ec1c9-36e5-4127-8374-922149e153dc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
