UPDATE public.mommy_day_notifications SET title_es = '¡Sigue contando pañales! 🧷', body_es = 'Anota en Anacan los pañales del día para asegurarte de que tu bebé come lo suficiente.', title_fr = 'Continuez à compter les couches ! 🧷', body_fr = 'Notez chaque jour les couches dans Anacan pour vous assurer que votre bébé mange à sa faim.', title_hi = 'डायपर गिनते रहिए! 🧷', body_hi = 'रोज़ के डायपर Anacan में दर्ज करके पक्का कीजिए कि बच्चे का पेट ठीक से भर रहा है।', title_id = 'Terus hitung popoknya! 🧷', body_id = 'Catat popok harian di Anacan untuk memastikan bayi Anda cukup menyusu.', title_ja = 'おむつの記録を続けましょう！🧷', body_ja = '1日のおむつの回数をAnacanに記録して、赤ちゃんが十分に飲めているか確認しましょう。', title_ko = '기저귀 세기는 계속돼요! 🧷', body_ko = '하루 기저귀 기록을 Anacan에 남기고 아기가 충분히 먹는지 확인하세요.', title_nl = 'Blijf luiers tellen! 🧷', body_nl = 'Noteer de luiers per dag in Anacan, zodat je zeker weet dat je baby genoeg binnenkrijgt.', title_pl = 'Dalej liczymy pieluszki! 🧷', body_pl = 'Zapisuj codzienne pieluszki w Anacan i miej pewność, że dziecko się najada.', title_pt = 'Continue a contar as fraldas! 🧷', body_pt = 'Registe as fraldas do dia no Anacan para ter a certeza de que o bebé está bem alimentado.', title_sv = 'Fortsätt räkna blöjorna! 🧷', body_sv = 'Anteckna de dagliga blöjorna i Anacan och känn dig trygg med att barnet får tillräckligt med mat.', title_vi = 'Tiếp tục đếm tã nhé! 🧷', body_vi = 'Ghi lại số tã hằng ngày trong Anacan để chắc chắn bé bú đủ.', title_zh = '继续数尿布！🧷', body_zh = '在Anacan里记录每天的尿布情况，确认宝宝吃得够。' WHERE id = '4a91e0c3-a4cb-4e5c-b68a-474b7d153369' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_p