UPDATE public.mommy_day_notifications SET body_es = '¡Esta noche, cuando el bebé se duerma, no olvides celebrar con tu pareja vuestra victoria de equipo!', body_fr = 'Ce soir, une fois bébé couché, n''oubliez pas de fêter la victoire de votre équipe avec votre conjoint !', body_hi = 'आज शाम बच्चे के सोने के बाद अपने साथी के साथ टीम की जीत का जश्न मनाना न भूलें!', body_id = 'Malam ini setelah anak tidur, jangan lupa merayakan kemenangan tim bersama pasangan Anda!', body_ja = '今夜、赤ちゃんが寝たら、パートナーと一緒にチームの勝利をお祝いするのを忘れずに！', body_ko = '오늘 밤 아기가 잠든 뒤 배우자와 함께 팀의 승리를 축하하는 것 잊지 마세요!', body_nl = 'Vergeet niet vanavond, als je baby slaapt, met je partner jullie teamoverwinning te vieren!', body_pl = 'Dziś wieczorem, gdy dziecko zaśnie, nie zapomnij uczcić z partnerem zwycięstwa waszej drużyny!', body_pt = 'Esta noite, depois de o bebé adormecer, não se esqueça de celebrar com o seu companheiro a vitória da vossa equipa!', body_sv = 'Glöm inte att fira lagets seger med din partner i kväll när barnet har somnat!', body_vi = 'Tối nay sau khi bé ngủ, đừng quên cùng chồng ăn mừng chiến thắng của cả đội!', body_zh = '今晚宝宝睡着后，别忘了和另一半一起庆祝你们团队的胜利！' WHERE id = 'b0d45a27-101a-4c13-b494-715c8c48dda4' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
